insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antimuscarinic-agents-6d3265f3dc', 'pharm-antimuscarinic-agents', 'mcq', 'Which is true of cholinolytics (antimuscarinic agents) used in airway disease?', '["Tiotropium has a longer duration of action than ipratropium", "They are atropine antagonists", "Only ipratropium has a bronchodilator effect", "Ipratropium has been associated with causation of chronic obstructive airway disease", "They are ineffective as inhalational agents"]'::jsonb, 'Tiotropium has a longer duration of action than ipratropium', '[]'::jsonb, 'Tiotropium dissociates very slowly from M3 receptors, so one inhalation lasts about 24 hours, whereas ipratropium lasts 4 to 6 hours and is given three or four times daily. All drugs in the class bronchodilate, they are atropine-like rather than atropine antagonists, and they are given by inhalation precisely because that route works well with few systemic effects.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.001 Q95, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-81476e4c44', 'pharm-sympathomimetics', 'mcq', 'Which drug has a greater effect on beta-1 than on beta-2 adrenoceptors?', '["Dobutamine", "Terbutaline", "Salbutamol", "Metaproterenol", "Ritodrine"]'::jsonb, 'Dobutamine', '[]'::jsonb, 'Dobutamine is a relatively beta-1 selective agonist used as an inotrope in cardiogenic shock and acute heart failure. Terbutaline, salbutamol, metaproterenol and ritodrine are all beta-2 selective agonists, used for bronchodilation or, in the case of ritodrine, to relax the uterus.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.001 Q90, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-leukotriene-inhibitors-other-drugs-ab90c3f004', 'pharm-leukotriene-inhibitors-other-drugs', 'mcq', 'All of the following are true of montelukast EXCEPT:', '["Does not require periodic monitoring of liver function tests", "It is a leukotriene receptor antagonist", "Recommended as monotherapy for rapid reversal of bronchoconstriction in asthmatic attacks", "Used to prevent asthma symptoms", "Food does not affect its absorption"]'::jsonb, 'Recommended as monotherapy for rapid reversal of bronchoconstriction in asthmatic attacks', '[]'::jsonb, 'Montelukast blocks the CysLT1 receptor and is a once-daily oral controller; it has no role in reversing an acute attack, where an inhaled short-acting beta-2 agonist is needed. Unlike zileuton, which can raise liver enzymes, montelukast needs no liver function monitoring, and its absorption is not affected by food.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.001 Q3, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cough-suppressants-and-expectorants-621437f9ed', 'pharm-cough-suppressants-and-expectorants', 'mcq', 'Which is NOT a mucolytic drug?', '["Bromhexine", "Noscapine", "Carbocisteine", "Ambroxol", "Acetylcysteine"]'::jsonb, 'Noscapine', '[]'::jsonb, 'Noscapine is a non-addictive opium alkaloid that suppresses the cough centre, so it is an antitussive. Bromhexine, its metabolite ambroxol, carbocisteine and acetylcysteine all reduce the viscosity of sputum; acetylcysteine does so by breaking disulphide bonds in mucoproteins.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.001, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-4792ebad5f', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'Which is true about sympathomimetics used in asthma?', '["They inhibit phosphodiesterase", "Inhalation is the recommended route of administration", "The commonest adverse effect is smooth muscle tremor", "Epinephrine is selective for the beta-2 adrenergic receptor", "Salmeterol is the most effective bronchodilator"]'::jsonb, 'Inhalation is the recommended route of administration', '[]'::jsonb, 'Inhalation delivers the beta-2 agonist straight to the airways, giving fast bronchodilation with the least systemic effect. The common adverse effect is tremor of skeletal, not smooth, muscle. Epinephrine acts on alpha and all beta receptors, and phosphodiesterase inhibition is the mechanism of the methylxanthines.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.002, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-b70acb2162', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'Which drug should not be administered as a rapid intravenous bolus in asthma?', '["Salbutamol", "Montelukast", "Penicillin", "Ipratropium bromide", "Aminophylline"]'::jsonb, 'Aminophylline', '[]'::jsonb, 'Aminophylline (theophylline with ethylenediamine) has a narrow therapeutic index. A rapid bolus produces high peak concentrations that can cause arrhythmias, seizures and sudden death, so the loading dose is given slowly over at least 20 minutes. Montelukast is oral and ipratropium is inhaled, so the question does not arise for them.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.002, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-96448ecb7d', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'Which is true of salbutamol?', '["It is a beta-adrenoceptor blocker", "It causes skeletal muscle tremor", "It is an ultra-long-acting drug", "It is administered via the rectal route", "Its main effect is anti-inflammatory"]'::jsonb, 'It causes skeletal muscle tremor', '[]'::jsonb, 'Salbutamol is a short-acting beta-2 agonist. Stimulation of beta-2 receptors on skeletal muscle produces a fine tremor, its commonest dose-related adverse effect. It bronchodilates but does not treat airway inflammation, acts for only 4 to 6 hours, and is given by inhalation, orally or parenterally.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.003 Q1, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-4242e21864', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'mcq', 'Histamine-induced oedema results from the action of histamine on which receptors?', '["H3", "H2", "H1", "H4", "All of the above"]'::jsonb, 'H1', '[]'::jsonb, 'H1 receptors on endothelial cells of post-capillary venules are coupled to Gq; their activation makes the cells contract and separate, so plasma leaks out and a wheal or oedema forms. H2 receptors mainly drive gastric acid secretion, H3 are presynaptic autoreceptors and H4 act on immune cell chemotaxis.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.003 Q96, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-576d362512', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'Which adverse event is associated with salbutamol?', '["Dry mouth", "Hoarse voice", "Skeletal muscle tremors", "Seizures", "Oral candidiasis"]'::jsonb, 'Skeletal muscle tremors', '[]'::jsonb, 'Tremor follows stimulation of beta-2 receptors in skeletal muscle and is the typical dose-related adverse effect of salbutamol, along with tachycardia and hypokalaemia. Hoarse voice and oral candidiasis belong to inhaled corticosteroids, dry mouth to antimuscarinics and seizures to theophylline toxicity.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.003, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-4db5da50cd', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'Identify the selective beta-2 adrenergic receptor agonist:', '["Propranolol", "Zafirlukast", "Epinephrine", "Omalizumab", "Salbutamol"]'::jsonb, 'Salbutamol', '[]'::jsonb, 'Salbutamol is a selective beta-2 agonist that relaxes bronchial smooth muscle by raising cAMP. Epinephrine also stimulates beta-2 receptors but is non-selective, acting on alpha and beta-1 receptors too. Propranolol is a beta blocker, zafirlukast a leukotriene receptor antagonist and omalizumab an anti-IgE antibody.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.004 Q20, Respiratory. Added the word ''selective'' to the stem, because epinephrine (option C) is also a beta-2 agonist.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-leukotriene-inhibitors-other-drugs-951d295439', 'pharm-leukotriene-inhibitors-other-drugs', 'mcq', 'Which one of the following is NOT a bronchodilator anti-asthmatic?', '["Zafirlukast", "Isoproterenol", "Ephedrine", "Albuterol", "Theophylline"]'::jsonb, 'Zafirlukast', '[]'::jsonb, 'Zafirlukast is a leukotriene receptor antagonist used as an oral controller to prevent asthma symptoms; it is not classed as a bronchodilator. Isoproterenol, ephedrine and albuterol relax airway smooth muscle through beta receptors, and theophylline does so as a methylxanthine.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.004, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antimuscarinic-agents-59cdd22506', 'pharm-antimuscarinic-agents', 'mcq', 'The following are long-acting antimuscarinics EXCEPT:', '["Glycopyrronium", "Oxitropium", "Umeclidinium", "Tiotropium", "Aclidinium"]'::jsonb, 'Oxitropium', '[]'::jsonb, 'Oxitropium, like ipratropium, is a short-acting antimuscarinic bronchodilator given several times a day. Tiotropium, glycopyrronium, umeclidinium and aclidinium are long-acting agents (LAMAs) given once or twice daily, mainly for maintenance treatment of COPD. Short-acting agents suit acute relief; LAMAs suit regular control.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.005, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-1a264f6b74', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'Which of the following sympathomimetic anti-asthmatics is long acting?', '["Terbutaline", "Albuterol", "Metaproterenol", "Pirbuterol", "Salmeterol"]'::jsonb, 'Salmeterol', '[]'::jsonb, 'Salmeterol has a long lipophilic side chain that anchors it near the beta-2 receptor, giving about 12 hours of bronchodilation; it is used twice daily with an inhaled corticosteroid, never for acute relief. Terbutaline, albuterol, metaproterenol and pirbuterol are short-acting relievers lasting 4 to 6 hours.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.006, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-dce0a9ccea', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'Which statement about salbutamol is correct?', '["It causes bradycardia", "It causes maximal bronchodilation in 15-30 minutes", "It is not nebulised", "It reduces chronic airway inflammation", "It is an ultra-long-acting beta-2 agonist"]'::jsonb, 'It causes maximal bronchodilation in 15-30 minutes', '[]'::jsonb, 'Inhaled salbutamol starts to work within about 5 minutes, bronchodilation peaks at 15 to 30 minutes and lasts 3 to 4 hours. It causes tachycardia, not bradycardia, is routinely nebulised in acute severe asthma, and has no useful effect on chronic airway inflammation.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.007, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-leukotriene-inhibitors-other-drugs-0b2c26d046', 'pharm-leukotriene-inhibitors-other-drugs', 'mcq', 'Leukotriene pathway inhibitors are useful in the management of which one of the following conditions?', '["Asthma", "Hypertension", "Bleeding disorders", "Peptic ulcer disease", "Inflammatory bowel disease"]'::jsonb, 'Asthma', '[]'::jsonb, 'Cysteinyl leukotrienes cause bronchoconstriction, mucus secretion and airway oedema. Blocking their receptor (montelukast, zafirlukast) or their synthesis by 5-lipoxygenase (zileuton) helps to control asthma, especially aspirin-sensitive and exercise-induced asthma. They have no place in the other conditions listed.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.008 Q31, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-in-asthma-mast-cell-st-30d15216f1', 'pharm-corticosteroids-in-asthma-mast-cell-stabilisers', 'mcq', 'Which is NOT an adverse effect of corticosteroids?', '["Positive nitrogen balance", "Hyperglycaemia", "Cataracts", "Depression", "Euphoria"]'::jsonb, 'Positive nitrogen balance', '[]'::jsonb, 'Glucocorticoids are catabolic: they break down protein in muscle, skin and bone, giving a negative nitrogen balance with muscle wasting and thin skin. Hyperglycaemia, posterior subcapsular cataracts and mood changes in either direction (euphoria or depression) are all recognised adverse effects.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.009, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-in-asthma-mast-cell-st-73a2d8281f', 'pharm-corticosteroids-in-asthma-mast-cell-stabilisers', 'mcq', 'Regarding the use of corticosteroids in asthma, which statement is INCORRECT?', '["Inhaled ciclesonide is a prodrug activated by esterases in the airways", "The anti-inflammatory effect is immediate", "Steroids may reduce the rate of growth in children", "Inhaled steroids may be complicated by oral candidiasis", "Oral steroids are used in severe asthma"]'::jsonb, 'The anti-inflammatory effect is immediate', '[]'::jsonb, 'Corticosteroids act by changing gene transcription, so their anti-inflammatory effect takes hours to begin and weeks of regular use to become maximal. That is why they are controllers and not relievers. Growth slowing in children and oral candidiasis are recognised effects of inhaled steroids.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.009, Respiratory. Option A originally read ''Inhaled ciclesonide is safer than budesonide due to lower lipid solubility'', which is itself wrong (ciclesonide is highly lipophilic); replaced with a clearly true statement so only one option is incorrect.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cough-suppressants-and-expectorants-4f8d2604d8', 'pharm-cough-suppressants-and-expectorants', 'mcq', 'What is the mechanism of action of codeine as an antitussive agent?', '["Depression of pulmonary action", "Paralysis of bronchial sensory nerves", "Production of mild nausea", "Depression of the cough centre", "Depression of bronchiolar secretions"]'::jsonb, 'Depression of the cough centre', '[]'::jsonb, 'Codeine acts on opioid receptors in the medulla to raise the threshold of the cough centre, at doses lower than those needed for analgesia. Blocking bronchial sensory nerves is how peripherally acting agents such as benzonatate work, and mild nausea is the reflex mechanism of some expectorants.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.012, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-in-asthma-mast-cell-st-d184f9b859', 'pharm-corticosteroids-in-asthma-mast-cell-stabilisers', 'mcq', 'Which statement is FALSE regarding inhaled corticosteroids used in the treatment of asthma?', '["They reduce bronchial reactivity", "Use of a spacer device can reduce oropharyngeal adverse effects", "They can be administered as dry powder", "Optimal bronchodilation is achieved in 30 minutes", "They decrease mast cell numbers in the respiratory mucosa"]'::jsonb, 'Optimal bronchodilation is achieved in 30 minutes', '[]'::jsonb, 'Inhaled corticosteroids do not relax airway smooth muscle; they reduce inflammation and bronchial hyperreactivity over weeks. Peak bronchodilation at 15 to 30 minutes describes a short-acting beta-2 agonist. Spacers and mouth rinsing reduce oropharyngeal deposition, and so candidiasis and hoarseness.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.012, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-in-asthma-mast-cell-st-41d49212f1', 'pharm-corticosteroids-in-asthma-mast-cell-stabilisers', 'mcq', 'All the following are adverse effects of corticosteroids EXCEPT:', '["Proximal myopathy", "Gastrointestinal bleeding", "Adrenal suppression", "Dehydration", "Diabetes mellitus"]'::jsonb, 'Dehydration', '[]'::jsonb, 'Corticosteroids have some mineralocorticoid activity and cause sodium and water retention, with oedema and hypertension, not dehydration. Proximal myopathy, peptic ulceration with bleeding, suppression of the hypothalamic-pituitary-adrenal axis and steroid-induced diabetes are all well recognised.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.013, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-in-asthma-mast-cell-st-79824eeaf1', 'pharm-corticosteroids-in-asthma-mast-cell-stabilisers', 'mcq', 'Which statement is TRUE regarding the use of corticosteroids in asthma management?', '["Corticosteroids have no effect on the frequency of asthma exacerbations", "Steroids have a brisk bronchodilator effect", "Inhaled corticosteroids are the drugs of choice for immediate relief of an acute attack", "Long-term steroid therapy reduces mast cells in the respiratory mucosa", "The optimal effect of inhaled corticosteroids is seen in 5 minutes"]'::jsonb, 'Long-term steroid therapy reduces mast cells in the respiratory mucosa', '[]'::jsonb, 'Regular corticosteroid treatment reduces the number of mast cells, eosinophils and lymphocytes in the airway mucosa, which lowers bronchial hyperreactivity and the frequency of exacerbations. They are not bronchodilators, and their full benefit takes weeks, so they cannot relieve an acute attack on their own.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.013, Respiratory. Paper asked ''True ... except'' although four of the five options were false; reworded to ''Which is TRUE''. Option C (a doubtful comparison of beclomethasone and ciclesonide lipid solubility) was replaced with a clearly false statement.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cough-suppressants-and-expectorants-fa08c16ab6', 'pharm-cough-suppressants-and-expectorants', 'mcq', 'Which drug is NOT a cough suppressant?', '["Noscapine", "Levopropoxyphene", "Guaifenesin", "Dextromethorphan", "Codeine"]'::jsonb, 'Guaifenesin', '[]'::jsonb, 'Guaifenesin is an expectorant: it increases the volume and lowers the viscosity of respiratory secretions so they are easier to cough up. Codeine and levopropoxyphene are opioid antitussives, and noscapine and dextromethorphan are non-analgesic centrally acting antitussives.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.013, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-5005009eaa', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'All of the following are true of beta-2 selective adrenergic receptor agonists EXCEPT:', '["They activate adenylyl cyclase and increase cAMP", "They are administered via the inhalation route", "They have no effect on chronic inflammation in asthma", "Salmeterol is long acting", "The onset of action of salbutamol is 6 hours"]'::jsonb, 'The onset of action of salbutamol is 6 hours', '[]'::jsonb, 'Inhaled salbutamol works within 1 to 5 minutes, peaks at 15 to 30 minutes and lasts 3 to 4 hours, which is why it is the standard reliever. Beta-2 agonists act through Gs, adenylyl cyclase and cAMP, and they relax smooth muscle without treating the underlying inflammation.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.014, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antimuscarinic-agents-d7aadca5a0', 'pharm-antimuscarinic-agents', 'mcq', 'Which one of the following is a long-acting antimuscarinic agent used in obstructive airway disease?', '["Aclidinium", "Terbutaline", "Montelukast", "Ipratropium", "Atropine"]'::jsonb, 'Aclidinium', '[]'::jsonb, 'Aclidinium is a long-acting muscarinic antagonist (LAMA) inhaled twice daily, in the same group as tiotropium and umeclidinium. Ipratropium and atropine are short acting. Terbutaline is a short-acting beta-2 agonist and montelukast a leukotriene receptor antagonist.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.014, Respiratory. Stem said ''used in asthma''; widened to ''obstructive airway disease'' because aclidinium is licensed for COPD.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antimuscarinic-agents-bb69ef81f0', 'pharm-antimuscarinic-agents', 'mcq', 'The best drug for treating an acute asthmatic attack in a 20-year-old male alcoholic with hypertension and congestive cardiac failure is:', '["Albuterol", "Salmeterol", "Theophylline", "Cromolyn sodium", "Ipratropium bromide"]'::jsonb, 'Ipratropium bromide', '[]'::jsonb, 'Inhaled ipratropium bronchodilates by blocking M3 receptors and is poorly absorbed, so it has almost no cardiac effect; this makes it the preferred choice when beta agonists and theophylline, which cause tachycardia and arrhythmias, are undesirable. Salmeterol and cromolyn are of no use in an acute attack.', 'admin', 'draft', 1, false, '[]'::jsonb, 'resp p.014, Respiratory. Examiner''s intended answer is ipratropium (cardiac disease makes beta agonists and theophylline less safe), but in real practice inhaled salbutamol is still first line in acute asthma; albuterol could be defended.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-bd6a965ab6', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'Identify the FALSE statement about salbutamol:', '["It causes skeletal muscle tremors", "It is a bronchodilator", "It causes bradycardia", "It has no effect on chronic inflammation in asthma", "It is inhaled"]'::jsonb, 'It causes bradycardia', '[]'::jsonb, 'Salbutamol causes tachycardia: directly through cardiac beta-2 (and some beta-1) receptors, and by reflex after beta-2 mediated vasodilation. The other statements are true; it is an inhaled bronchodilator that causes tremor and leaves the underlying airway inflammation untreated.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.015, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-in-asthma-mast-cell-st-0a32e4ead9', 'pharm-corticosteroids-in-asthma-mast-cell-stabilisers', 'mcq', 'Which one of the following agents used in asthma is a mast cell stabiliser?', '["Omalizumab", "Formoterol", "Salbutamol", "Cromolyn sodium", "Aminophylline"]'::jsonb, 'Cromolyn sodium', '[]'::jsonb, 'Cromolyn sodium (sodium cromoglicate) and nedocromil stop mast cells degranulating, so they prevent the response to antigen and exercise when taken before exposure. Omalizumab is an anti-IgE antibody, formoterol and salbutamol are beta-2 agonists, and aminophylline is a methylxanthine.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.015 Q40, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-in-asthma-mast-cell-st-857793b756', 'pharm-corticosteroids-in-asthma-mast-cell-stabilisers', 'mcq', 'Which statement is FALSE regarding the use of corticosteroids in asthma?', '["They prevent progression of disease in chronic asthma", "They have a rapid bronchodilator effect", "The inhaled formulation may cause oral candidiasis", "They are anti-inflammatory", "Optimal effects take weeks to achieve"]'::jsonb, 'They have a rapid bronchodilator effect', '[]'::jsonb, 'Corticosteroids do not relax bronchial smooth muscle directly. They suppress airway inflammation through altered gene transcription, an effect that builds over days to weeks, so a bronchodilator is still needed for immediate relief. Inhaled steroid deposited in the mouth predisposes to candidiasis.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.016, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-cbe7619117', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'The mechanism of action of theophylline is:', '["Muscarinic receptor antagonist", "Mast cell stabiliser", "Phosphodiesterase inhibitor", "Agonist at the beta-2 receptor", "Lipoxygenase inhibitor"]'::jsonb, 'Phosphodiesterase inhibitor', '[]'::jsonb, 'Theophylline inhibits phosphodiesterases, so cAMP accumulates in airway smooth muscle and relaxes it; it also blocks adenosine receptors. Beta-2 agonists raise cAMP by making more of it, not by slowing its breakdown. Zileuton is the lipoxygenase inhibitor.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.017, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-in-asthma-mast-cell-st-7010473129', 'pharm-corticosteroids-in-asthma-mast-cell-stabilisers', 'mcq', 'The following drugs are used to relieve an acute exacerbation of asthma EXCEPT:', '["Salbutamol", "Magnesium sulphate", "Aminophylline", "Nedocromil", "Ipratropium bromide"]'::jsonb, 'Nedocromil', '[]'::jsonb, 'Nedocromil is a mast cell stabiliser that works only as prophylaxis; it cannot reverse established bronchospasm. Nebulised salbutamol and ipratropium, intravenous magnesium sulphate and, in refractory cases, intravenous aminophylline are all used in acute severe asthma.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.018, Respiratory. Option E was tiotropium, which is also not used in acute exacerbations (two correct answers); replaced with ipratropium bromide.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-9db0e2ba1e', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'With regard to the treatment of asthma, which statement is true?', '["Epinephrine is a controller", "Salbutamol is a long-acting beta-2 agonist", "Salmeterol is a long-acting beta-2 agonist", "Theophylline is a muscarinic receptor antagonist", "None of the above is true"]'::jsonb, 'Salmeterol is a long-acting beta-2 agonist', '[]'::jsonb, 'Salmeterol and formoterol are long-acting beta-2 agonists giving about 12 hours of bronchodilation, used with an inhaled corticosteroid. Salbutamol is short acting, epinephrine is a rescue drug and not a controller, and theophylline is a methylxanthine phosphodiesterase inhibitor.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.018 Q1, Respiratory (Systemic pharmacology revision MCQs). Option D originally read ''Theophylline directly relaxes smooth muscles of the respiratory tract'', which is also true; changed to a false statement so only one option is correct.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-respiratory-pharmacolo-b7a946a024', 'pharm-introduction-to-respiratory-pharmacology-drugs-used-in-asthma', 'mcq', 'Identify the true statement about inhaled drug delivery in asthma:', '["Pressurised metered-dose inhalers (pMDIs) are easy to use", "When using spacer chambers, most of the drug is deposited in the oropharynx", "Dry powder inhalers require careful coordination", "Nebulisers deliver much higher doses of drugs compared to pMDIs", "Theophylline can be given by inhalation"]'::jsonb, 'Nebulisers deliver much higher doses of drugs compared to pMDIs', '[]'::jsonb, 'A nebuliser delivers a much larger dose over several minutes of normal breathing (salbutamol 2.5 to 5 mg against 100 micrograms per puff). pMDIs need the puff to be timed with inspiration, which many patients find hard; spacers reduce oropharyngeal deposition, and dry powder inhalers are breath-actuated so need no such timing.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.018 Q2, Respiratory (Systemic pharmacology revision MCQs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-in-asthma-mast-cell-st-9440a4be21', 'pharm-corticosteroids-in-asthma-mast-cell-stabilisers', 'mcq', 'All the following are true EXCEPT:', '["Nedocromil and cromolyn sodium are mast cell stabilisers", "Omalizumab is an immunoglobulin E antagonist", "Fluticasone is a systemic corticosteroid", "Zafirlukast is a leukotriene antagonist", "Budesonide is an inhaled corticosteroid"]'::jsonb, 'Fluticasone is a systemic corticosteroid', '[]'::jsonb, 'Fluticasone is given by inhalation (or topically); what is swallowed undergoes almost complete first-pass metabolism, so it has very little systemic activity. Prednisolone and hydrocortisone are the systemic steroids used in asthma. The other four statements are correct.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.019 Q4, Respiratory (Systemic pharmacology revision MCQs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-168c8721ef', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'Which statement is NOT true of methylxanthines?', '["They are classified as relievers", "Enprofylline does not antagonise adenosine receptors", "Their only mechanism of action is inhibition of phosphodiesterase enzymes", "They have positive chronotropic and inotropic effects on the cardiovascular system", "They can exacerbate peptic ulcer disease"]'::jsonb, 'Their only mechanism of action is inhibition of phosphodiesterase enzymes', '[]'::jsonb, 'Besides phosphodiesterase inhibition, methylxanthines block adenosine receptors and activate histone deacetylase, which contributes an anti-inflammatory effect. Enprofylline bronchodilates without adenosine antagonism. They stimulate the heart and increase gastric acid secretion, so they can worsen peptic ulcer disease.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.019 Q5, Respiratory (Systemic pharmacology revision MCQs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-in-asthma-mast-cell-st-cda7d09489', 'pharm-corticosteroids-in-asthma-mast-cell-stabilisers', 'mcq', 'Which is a FALSE statement about corticosteroids used in asthma?', '["They inhibit production of inflammatory cytokines", "They inhibit eicosanoid synthesis", "They decrease vascular permeability", "They cause bronchodilation", "They inhibit accumulation of inflammatory cells in lung tissue"]'::jsonb, 'They cause bronchodilation', '[]'::jsonb, 'Corticosteroids have no direct relaxant action on airway smooth muscle. They work by switching off inflammatory genes: fewer cytokines, less eicosanoid synthesis through inhibition of phospholipase A2 and COX-2 expression, less vascular leak and fewer eosinophils and mast cells in the airway wall.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.019 Q6, Respiratory (Systemic pharmacology revision MCQs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antimuscarinic-agents-52e1525a69', 'pharm-antimuscarinic-agents', 'mcq', 'Which is true of ipratropium bromide?', '["It is a tertiary ammonium compound", "It has good systemic and oral absorption", "It has a faster onset of action than salbutamol", "It is an inhalational anti-asthma drug", "It has a duration of action of 24 hours"]'::jsonb, 'It is an inhalational anti-asthma drug', '[]'::jsonb, 'Ipratropium is a quaternary ammonium derivative of atropine. Its permanent charge means it is poorly absorbed and does not enter the brain, so it is given by inhalation for a local effect. Its onset is slower than salbutamol''s (peak at 30 to 60 minutes) and it lasts 4 to 6 hours; tiotropium is the 24-hour drug.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.020 Q9, Respiratory (Systemic pharmacology revision MCQs). Option C originally read ''Has a fast onset of action'', which is debatable; made explicit (''faster than salbutamol'') so that only option D is true.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-leukotriene-inhibitors-other-drugs-73b7d23041', 'pharm-leukotriene-inhibitors-other-drugs', 'mcq', 'The main mechanism of action of magnesium sulphate in asthma relief is:', '["Reduction of mucus secretion", "Inhibition of mast cell degranulation", "Reduction of cytosolic calcium in airway smooth muscle", "Inhibition of vagal activity in the airways", "Inhibition of pro-inflammatory cytokine release"]'::jsonb, 'Reduction of cytosolic calcium in airway smooth muscle', '[]'::jsonb, 'Magnesium acts as a physiological calcium antagonist: it blocks calcium entry through voltage-gated channels and its release from stores, lowering cytosolic calcium so bronchial smooth muscle relaxes. A single intravenous dose is used in acute severe asthma that has not responded to inhaled bronchodilators.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.020 Q10, Respiratory (Systemic pharmacology revision MCQs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cough-suppressants-and-expectorants-db294f33d8', 'pharm-cough-suppressants-and-expectorants', 'mcq', 'All are mucolytics EXCEPT:', '["Bromhexine", "Guaiacol", "Ambroxol", "Acetylcysteine", "Carbocisteine"]'::jsonb, 'Guaiacol', '[]'::jsonb, 'Guaiacol, like its derivative guaifenesin, is an expectorant: it increases the volume of airway secretions, partly by a reflex from gastric irritation. Mucolytics act on the mucus itself; acetylcysteine and carbocisteine alter its disulphide-linked glycoproteins, and bromhexine and ambroxol break up mucopolysaccharide fibres.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.020 Q11, Respiratory (Systemic pharmacology revision MCQs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-5e63235ea2', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'A 68-year-old retired police officer who has smoked half a pack of cigarettes a day for the past 40 years is diagnosed with chronic obstructive pulmonary disease (COPD). He has difficulty in expiration, but the symptoms are mild and intermittent. Which one of the following agents would be the most appropriate initial therapy?', '["Systemic corticosteroids", "Albuterol", "Salmeterol", "Tiotropium plus salmeterol", "Theophylline"]'::jsonb, 'Albuterol', '[]'::jsonb, 'Mild, intermittent COPD symptoms are treated with a short-acting bronchodilator used as needed, such as albuterol. Long-acting bronchodilators, alone or combined, are added when symptoms become persistent. Systemic corticosteroids are kept for exacerbations, and theophylline is a last-line drug because of its toxicity.', 'admin', 'draft', 1, false, '[]'::jsonb, 'resp p.020 Q12, Respiratory (Systemic pharmacology revision MCQs). Student''s key marked salmeterol. Albuterol is the textbook (Lippincott) answer for mild intermittent symptoms; recent GOLD guidance accepts either a short- or long-acting bronchodilator, so this is guideline-dependent.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-in-asthma-mast-cell-st-7c7d32bba4', 'pharm-corticosteroids-in-asthma-mast-cell-stabilisers', 'mcq', 'A 9-year-old girl has severe asthma, which required three hospitalisations in the last year. She is now receiving therapy that has greatly reduced the frequency of these severe attacks. Which of the following therapies is most likely responsible for this benefit?', '["Albuterol by aerosol", "Cromolyn by inhaler", "Fluticasone by aerosol", "Theophylline orally", "Zafirlukast orally"]'::jsonb, 'Fluticasone by aerosol', '[]'::jsonb, 'Regular inhaled corticosteroids are the most effective controllers: they reduce airway inflammation and so cut the number of severe exacerbations and hospital admissions. Cromolyn is far weaker and suits only mild asthma; albuterol relieves symptoms without changing the frequency of attacks.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.021 Q13, Respiratory. Student''s key marked cromolyn; inhaled corticosteroid (fluticasone) is the correct answer for severe asthma.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antimuscarinic-agents-2971b16f38', 'pharm-antimuscarinic-agents', 'mcq', 'The following drugs have anti-inflammatory effects in asthma EXCEPT:', '["Tiotropium", "Beclomethasone", "Montelukast", "Omalizumab", "Nedocromil"]'::jsonb, 'Tiotropium', '[]'::jsonb, 'Tiotropium is a long-acting muscarinic antagonist: it only bronchodilates and reduces mucus secretion by blocking M3 receptors. Beclomethasone (corticosteroid), montelukast (leukotriene antagonist), omalizumab (anti-IgE) and nedocromil (mast cell stabiliser) all act on the inflammatory process.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.021 Q38, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-d37df0175a', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'All of the following are true of beta-2 adrenoceptor agonists in the treatment of asthma EXCEPT:', '["They mediate bronchodilation by increasing cAMP in bronchial smooth muscle cells", "Salmeterol has a fast onset of action", "Salbutamol is a drug of choice for treatment of an acute asthmatic attack", "Salmeterol is used for asthma prophylaxis", "They may cause tachycardia when given by inhalation"]'::jsonb, 'Salmeterol has a fast onset of action', '[]'::jsonb, 'Salmeterol takes 10 to 20 minutes or more to begin working, so it is unsuitable for acute relief and is used twice daily for prophylaxis alongside an inhaled steroid. Formoterol, by contrast, is long acting with a fast onset. Enough inhaled drug is absorbed to cause tachycardia and tremor.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.021 Q39, Respiratory. Option B originally read ''Formoterol has a fast onset of action'', which is true (leaving no false option); changed to salmeterol.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antimuscarinic-agents-3936bb33f8', 'pharm-antimuscarinic-agents', 'mcq', 'Which of the following is true about muscarinic receptor antagonist use in the management of asthma?', '["They have no effect on the chronic inflammatory phase of asthma", "Ipratropium has a longer duration of action than tiotropium", "They reverse acute bronchospasm in most asthmatic patients", "They should not be used concurrently with beta-2 agonists", "They cause significant systemic effects"]'::jsonb, 'They have no effect on the chronic inflammatory phase of asthma', '[]'::jsonb, 'Antimuscarinics block only the vagally mediated part of bronchoconstriction and mucus secretion; they do nothing to the underlying inflammation. They are less effective than beta-2 agonists in most asthmatics, are usefully combined with them in acute severe asthma, and as inhaled quaternary compounds cause few systemic effects.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.022-023 Q50, Respiratory') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-b6182c3d26', 'pharm-adrenoceptor-blockers', 'mcq', 'Most beta blockers:', '["Have half-lives of 3-10 hours", "Have a small volume of distribution", "Are not absorbed after oral administration", "Are highly lipid soluble and hence cross the blood-brain barrier", "Are excreted entirely unchanged in the urine"]'::jsonb, 'Have half-lives of 3-10 hours', '[]'::jsonb, 'Most beta blockers have half-lives between 3 and 10 hours; esmolol (about 10 minutes) and nadolol (up to 24 hours) are the extremes. They are well absorbed orally and have large volumes of distribution. Lipid solubility varies widely: propranolol enters the brain readily, atenolol and nadolol hardly at all.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.023 Q13, Respiratory (Asthma and beta blockers MCQs). Options C and E reworded slightly (''have poor oral bioavailability'', ''are rarely excreted unchanged'') to make them unambiguously false.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-respiratory-pharmacolo-c87e27ade6', 'pharm-introduction-to-respiratory-pharmacology-drugs-used-in-asthma', 'mcq', 'Regarding asthma treatment, all of the following are true EXCEPT:', '["Therapy is divided into short-term relievers and long-term controllers", "Short-term relievers consist mostly of bronchodilators", "Leukotriene antagonists are short-term relievers of bronchial asthma", "Cromolyn and nedocromil are mast cell inhibitors", "Inhaled corticosteroids are long-term controllers"]'::jsonb, 'Leukotriene antagonists are short-term relievers of bronchial asthma', '[]'::jsonb, 'Leukotriene receptor antagonists such as montelukast are taken regularly by mouth as long-term controllers; they act too slowly and too weakly to relieve an attack. Relievers are bronchodilators, chiefly short-acting beta-2 agonists. Cromolyn and nedocromil are also prophylactic only.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.023 Q29, Respiratory (Asthma and beta blockers MCQs). Paper''s option E was ''All of the above'', which makes no sense in an EXCEPT question; replaced with a true statement. Option A tidied from ''short term and long term relievers'' to ''relievers and controllers''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-leukotriene-inhibitors-other-drugs-b313afc5fb', 'pharm-leukotriene-inhibitors-other-drugs', 'mcq', 'With regard to oral anti-asthmatic agents, which statement is true?', '["Prednisone is a long-acting glucocorticoid", "Methotrexate has been shown to be beneficial in prednisone-dependent asthmatics in all studies", "Cyclosporin''s toxicity limits its use as an oral anti-asthmatic agent", "Oral nifedipine significantly inhibits exercise-induced bronchoconstriction", "Macrolide antibiotics show no benefit in managing asthmatics"]'::jsonb, 'Cyclosporin''s toxicity limits its use as an oral anti-asthmatic agent', '[]'::jsonb, 'Ciclosporin can reduce steroid requirements in severe asthma, but nephrotoxicity and hypertension prevent its routine use. Prednisone is an intermediate-acting glucocorticoid (12 to 36 hours); dexamethasone is long acting. Trials of methotrexate gave mixed results, and some macrolides do reduce exacerbations.', 'admin', 'draft', 1, false, '[]'::jsonb, 'resp p.023 Q36, Respiratory (Asthma and beta blockers MCQs). Student''s key marked A (prednisone long acting), which is wrong: prednisone is intermediate acting. C is the textbook (Katzung) statement, but the item is obscure and option D/E wording is loose; needs a human check.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-6cae3d3817', 'pharm-adrenoceptor-blockers', 'mcq', 'Non-selective beta adrenergic blockers should be used with caution in the following conditions EXCEPT:', '["Hyperthyroidism", "Asthma", "Cardiac conduction disease", "Bradycardia", "Diabetes mellitus"]'::jsonb, 'Hyperthyroidism', '[]'::jsonb, 'Propranolol is actually a treatment in hyperthyroidism: it controls tachycardia, tremor and anxiety and reduces conversion of T4 to T3. Non-selective beta blockers can provoke bronchospasm in asthma, worsen heart block and bradycardia, and mask the warning signs of hypoglycaemia in treated diabetics.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.023 Q40, Respiratory (Asthma and beta blockers MCQs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-a4d36cb20f', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'Which statement is FALSE regarding theophylline?', '["It is a methylxanthine", "It inhibits cholinesterase", "It has a narrow therapeutic window", "Its clearance is increased in cigarette smokers", "It may cause seizures"]'::jsonb, 'It inhibits cholinesterase', '[]'::jsonb, 'Theophylline inhibits phosphodiesterase, not cholinesterase, and also antagonises adenosine receptors. Its therapeutic window is narrow (about 5 to 20 mg/L), smoking induces CYP1A2 and speeds its clearance, and toxic concentrations cause arrhythmias and seizures. Plasma levels are therefore monitored.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.023 Q41, Respiratory (Asthma and beta blockers MCQs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-7b354983fb', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'The following are effects of theophylline EXCEPT:', '["Nervousness", "Bronchodilatation", "Insomnia", "Tachycardia", "Reduced contractility of the diaphragm"]'::jsonb, 'Reduced contractility of the diaphragm', '[]'::jsonb, 'Theophylline increases the strength of contraction of the diaphragm and reduces its fatigue, which is one reason it helps some patients with COPD. Its other effects are those of a caffeine-like stimulant: nervousness, insomnia, tachycardia and bronchodilatation.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.023-024 Q67, Respiratory (Asthma and beta blockers MCQs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-f2102fbd54', 'pharm-adrenoceptor-blockers', 'mcq', 'Which drug blocks both alpha and beta adrenergic receptors?', '["Propranolol", "Atenolol", "Carvedilol", "Esmolol", "Acebutolol"]'::jsonb, 'Carvedilol', '[]'::jsonb, 'Carvedilol, like labetalol, blocks beta-1, beta-2 and alpha-1 receptors, so it lowers peripheral resistance as well as heart rate; it is used in heart failure and hypertension. Propranolol is a non-selective beta blocker, while atenolol, esmolol and acebutolol are beta-1 selective.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.024 Q68, Respiratory (Asthma and beta blockers MCQs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-g-proteins-and-second-messengers-cca3e74844', 'pharm-g-proteins-and-second-messengers', 'mcq', 'Which second messenger mediates the bronchial smooth muscle relaxation produced by beta-2 agonists in asthma?', '["cGMP", "cAMP", "Calcium ions", "Diacylglycerol (DAG)", "Inositol trisphosphate (IP3)"]'::jsonb, 'cAMP', '[]'::jsonb, 'Beta-2 receptors couple to Gs, which activates adenylyl cyclase and raises cAMP; protein kinase A then lowers intracellular calcium and inactivates myosin light chain kinase, so the muscle relaxes. IP3, DAG and calcium are the Gq pathway that muscarinic M3 receptors use to cause contraction.', 'admin', 'published', 1, false, '[]'::jsonb, 'resp p.024 Q87, Respiratory (Asthma and beta blockers MCQs). Stem tightened to name beta-2 agonists (original: ''which second messenger causes smooth muscle relaxation in the respiratory system in asthma''), since cGMP also relaxes smooth muscle.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-inflammatory-and-irritable-b-a599e87348', 'pharm-drugs-for-inflammatory-and-irritable-bowel-disease', 'mcq', 'Which is true regarding drugs used in the management of inflammatory bowel disease?', '["Sulfasalazine consists of two 5-aminosalicylic acid molecules bound together", "Asacol contains timed-release microgranules that release 5-aminosalicylic acid in the small intestine", "Adverse effects of sulfasalazine are more common among rapid acetylators", "Balsalazide can cause oligospermia", "Sulfasalazine impairs folate absorption"]'::jsonb, 'Sulfasalazine impairs folate absorption', '[]'::jsonb, 'Sulfasalazine inhibits intestinal folate absorption, so folic acid supplements are advised. It is 5-ASA linked to sulfapyridine; two linked 5-ASA molecules describes olsalazine. Timed-release microgranules are Pentasa (Asacol is a pH-dependent coating), and sulfapyridine toxicity, including oligospermia, is worse in slow acetylators.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.001 Q20, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-7b4052814e', 'pharm-antidiarrheal-agents-laxatives', 'mcq', 'Which is true of loperamide?', '["Its bioavailability is 100%", "It is not analgesic", "It binds to muscarinic receptors", "It is addictive", "It is a laxative"]'::jsonb, 'It is not analgesic', '[]'::jsonb, 'Loperamide is a mu-opioid agonist that acts on the gut wall. It has low oral bioavailability and is pumped out of the brain by P-glycoprotein, so at normal doses it produces no analgesia, euphoria or dependence. It slows transit and is an antidiarrhoeal, the opposite of a laxative.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.001 Q16, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cytoprotective-agents-bismuth-compound-f02369c6b2', 'pharm-cytoprotective-agents-bismuth-compounds-sucralfate-etc', 'mcq', 'Which of the following is NOT caused by bismuth compound toxicity?', '["Ataxia", "Headaches", "Confusion", "Hypersalivation", "Seizures"]'::jsonb, 'Hypersalivation', '[]'::jsonb, 'Prolonged or high-dose bismuth can cause a reversible encephalopathy with headache, confusion, ataxia, myoclonus and seizures. Hypersalivation is not a feature. The common harmless effects are blackening of the stool and tongue. Toxicity is rare with short courses because under 1% of a dose is absorbed.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.001 Q48, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h2-receptor-antagonist-proton-pump-inh-bd0f2a92f6', 'pharm-h2-receptor-antagonist-proton-pump-inhibitor', 'mcq', 'Which drug produces the highest degree of gastric acid secretion suppression?', '["Lansoprazole", "Esomeprazole", "Omeprazole", "Ranitidine", "Misoprostol"]'::jsonb, 'Esomeprazole', '[]'::jsonb, 'Proton pump inhibitors suppress acid far more than H2 antagonists or misoprostol because they block the final step of secretion. Among them esomeprazole, the S-isomer of omeprazole, is cleared more slowly and gives a higher exposure, so at standard doses it keeps intragastric pH above 4 for the longest.', 'admin', 'draft', 1, false, '[]'::jsonb, 'git p.001 Q47, GIT pharmacology. Three options are PPIs; differences between them are small and dose-dependent. Esomeprazole is the usual exam answer (and the student''s), but a human should confirm against the lecture notes.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-treating-pancreatic-disorder-cd8d501a00', 'pharm-drugs-for-treating-pancreatic-disorders-aprotinin-glucagon-use-o', 'mcq', 'Which drug is used in the management of steatorrhoea?', '["Loperamide", "Ondansetron", "Aluminium hydroxide", "Pancrelipase", "Sulfasalazine"]'::jsonb, 'Pancrelipase', '[]'::jsonb, 'Steatorrhoea from pancreatic exocrine insufficiency (chronic pancreatitis, cystic fibrosis) is treated by replacing the missing enzymes. Pancrelipase supplies lipase, amylase and protease and is taken with each meal so that fat can be digested and absorbed.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.002, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cytoprotective-agents-bismuth-compound-3b2a2f4736', 'pharm-cytoprotective-agents-bismuth-compounds-sucralfate-etc', 'mcq', 'All of the following are true of sucralfate EXCEPT:', '["It has limited solubility", "It stimulates prostaglandin and bicarbonate production", "It is given 1 hour before meals", "Prolonged use in renal failure should be avoided", "About 20% is absorbed"]'::jsonb, 'About 20% is absorbed', '[]'::jsonb, 'Less than 3% of sucralfate is absorbed; it acts locally, forming a viscous paste that binds to the ulcer base for up to 6 hours. It needs acid to be activated, hence dosing an hour before meals. The small amount of aluminium absorbed can accumulate in renal failure.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.002, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emetics-antiemetics-and-prokinetic-age-e030f0db17', 'pharm-emetics-antiemetics-and-prokinetic-agents', 'mcq', 'Prolonged QT interval is associated with which of the following antiemetic agents?', '["Droperidol", "Metoclopramide", "Meclizine", "Aprepitant", "Dronabinol"]'::jsonb, 'Droperidol', '[]'::jsonb, 'Droperidol, a butyrophenone D2 antagonist, prolongs the QT interval and can cause torsades de pointes, which earned it a boxed warning and limits its use. The 5-HT3 antagonists and domperidone share this risk, but they are not among the options.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.003, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h2-receptor-antagonist-proton-pump-inh-81b9356342', 'pharm-h2-receptor-antagonist-proton-pump-inhibitor', 'mcq', 'Which one of the following proton pump inhibitors is least likely to have drug interactions?', '["Dexlansoprazole", "Lansoprazole", "Pantoprazole", "Esomeprazole", "Omeprazole"]'::jsonb, 'Pantoprazole', '[]'::jsonb, 'Pantoprazole has the lowest affinity for CYP2C19 and other cytochrome P450 enzymes, and so has the fewest metabolic interactions (rabeprazole is similar). Omeprazole and esomeprazole inhibit CYP2C19, which can reduce activation of clopidogrel and raise levels of diazepam and phenytoin.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.003, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-d3d89fe667', 'pharm-antidiarrheal-agents-laxatives', 'mcq', 'Which bulk-forming agent is used as a laxative?', '["Bran", "Lactulose", "Castor oil", "Glycerin", "Magnesium citrate"]'::jsonb, 'Bran', '[]'::jsonb, 'Bran is indigestible fibre that holds water in the stool, increasing its bulk and stimulating peristalsis; psyllium, methylcellulose and polycarbophil act in the same way. Lactulose and magnesium citrate are osmotic laxatives, castor oil is a stimulant and glycerin is a lubricant and osmotic suppository.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.004, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cytoprotective-agents-bismuth-compound-9ed532c5b8', 'pharm-cytoprotective-agents-bismuth-compounds-sucralfate-etc', 'mcq', 'All of the following are true about colloidal bismuth compounds EXCEPT:', '["Over 99% of the bismuth appears in the stool", "They are reserve anti-peptic ulcer disease compounds", "They stimulate production of mucus and prostaglandins", "They have direct antimicrobial activity", "They cause diarrhoea"]'::jsonb, 'They cause diarrhoea', '[]'::jsonb, 'Bismuth is used to treat diarrhoea, not cause it; bismuth subsalicylate reduces stool frequency in traveller''s diarrhoea. It is barely absorbed, coats ulcers, stimulates mucus, bicarbonate and prostaglandin secretion, and is directly toxic to Helicobacter pylori, which is why it features in quadruple therapy.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.004, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-f4d65df270', 'pharm-antidiarrheal-agents-laxatives', 'mcq', 'Which antidiarrhoeal agent is NOT an opioid?', '["Diphenoxylate", "Colestipol", "Loperamide", "Eluxadoline", "Difenoxin"]'::jsonb, 'Colestipol', '[]'::jsonb, 'Colestipol is a bile acid-binding resin; it relieves diarrhoea caused by excess bile salts reaching the colon, for example after ileal resection. Diphenoxylate, its metabolite difenoxin, loperamide and eluxadoline all act on opioid receptors in the gut wall to slow transit.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.005, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-inflammatory-and-irritable-b-4d5e97f576', 'pharm-drugs-for-inflammatory-and-irritable-bowel-disease', 'mcq', 'Which one of the following is a monoclonal antibody against integrin, useful in the management of inflammatory bowel disease?', '["Rituximab", "Infliximab", "Certolizumab", "Natalizumab", "Canakinumab"]'::jsonb, 'Natalizumab', '[]'::jsonb, 'Natalizumab binds the alpha-4 subunit of integrins on leucocytes and stops them leaving the circulation for the gut wall; it is used in refractory Crohn''s disease but carries a risk of progressive multifocal leucoencephalopathy. Infliximab and certolizumab are anti-TNF agents, rituximab is anti-CD20 and canakinumab anti-IL-1 beta.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.005, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emetics-antiemetics-and-prokinetic-age-fc332126aa', 'pharm-emetics-antiemetics-and-prokinetic-agents', 'mcq', 'Which one of the following serotonin antagonists has the longest serum half-life?', '["Granisetron", "Ondansetron", "Dolasetron", "Tropisetron", "Palonosetron"]'::jsonb, 'Palonosetron', '[]'::jsonb, 'Palonosetron has a half-life of about 40 hours and a higher affinity for the 5-HT3 receptor, so a single dose also covers delayed chemotherapy-induced vomiting. Ondansetron, granisetron, dolasetron and tropisetron have half-lives of roughly 4 to 9 hours.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.006, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h2-receptor-antagonist-proton-pump-inh-e6df0895fe', 'pharm-h2-receptor-antagonist-proton-pump-inhibitor', 'mcq', 'Adverse effects of esomeprazole include the following EXCEPT:', '["Hypomagnesaemia", "Acute interstitial nephritis", "Megaloblastic anaemia", "Hepatitis", "Osteoporosis"]'::jsonb, 'Hepatitis', '[]'::jsonb, 'Long-term proton pump inhibitor use is linked to hypomagnesaemia, reduced calcium absorption with fractures, vitamin B12 malabsorption (so megaloblastic anaemia) and, idiosyncratically, acute interstitial nephritis. Hepatitis is not a characteristic adverse effect of the class.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.006, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-97a3dcf443', 'pharm-antidiarrheal-agents-laxatives', 'mcq', 'Which antidiarrhoeal drug may cause black discolouration of the stool?', '["Diphenoxylate", "Bismuth subsalicylate", "Racecadotril (acetorphan)", "Berberine", "Octreotide"]'::jsonb, 'Bismuth subsalicylate', '[]'::jsonb, 'Bismuth reacts with hydrogen sulphide made by gut bacteria to form black bismuth sulphide, which harmlessly darkens the stool and tongue. It matters clinically because it can be mistaken for melaena. None of the other antidiarrhoeals does this.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.007 Q2, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-appetite-stimulants-and-suppressants-45db862096', 'pharm-appetite-stimulants-and-suppressants', 'mcq', 'Which drug is a gastrointestinal lipase inhibitor?', '["Lorcaserin", "Cilastatin", "Phentermine", "Bupropion/naltrexone", "Orlistat"]'::jsonb, 'Orlistat', '[]'::jsonb, 'Orlistat inhibits gastric and pancreatic lipases, so about 30% of dietary fat is not broken down and is lost in the stool; this is how it aids weight loss. Lorcaserin (5-HT2C agonist), phentermine and bupropion/naltrexone suppress appetite centrally. Cilastatin inhibits renal dehydropeptidase.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.007 Q7, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-fa47e535cd', 'pharm-antidiarrheal-agents-laxatives', 'mcq', 'All of the following are true of antidiarrhoeal agents EXCEPT:', '["They have adverse effects", "They are used for symptomatic relief", "They do not treat the underlying cause", "They are used as alternatives to oral rehydration salts to prevent dehydration", "They may delay expulsion of pathogens"]'::jsonb, 'They are used as alternatives to oral rehydration salts to prevent dehydration', '[]'::jsonb, 'Antidiarrhoeal drugs only reduce stool frequency; they do not replace lost water and electrolytes, so oral rehydration remains the mainstay of treatment and cannot be substituted. By slowing transit, antimotility agents can prolong infection with invasive organisms.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.007 Q13, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h2-receptor-antagonist-proton-pump-inh-517adb85f9', 'pharm-h2-receptor-antagonist-proton-pump-inhibitor', 'mcq', 'Which is true regarding proton pump inhibitors?', '["Food reduces their bioavailability by 20%", "They inhibit 70-80% of 24-hour acid secretion", "They have no direct antimicrobial properties against Helicobacter pylori", "They are lipophilic", "They reduce intragastric pH"]'::jsonb, 'They are lipophilic', '[]'::jsonb, 'Proton pump inhibitors are lipophilic weak bases; this lets them cross the parietal cell membrane and become trapped and activated in the acid canaliculus. Food cuts their bioavailability by about half, standard doses suppress 90-98% of 24-hour acid output, they raise intragastric pH, and they have a minor direct action against H. pylori.', 'admin', 'draft', 1, false, '[]'::jsonb, 'git p.008 Q18, GIT pharmacology. Student''s key marked C (no direct antimicrobial action). Katzung states PPIs have minor direct antimicrobial activity against H. pylori and are lipophilic weak bases, so D is taken as correct. Depends on textbook detail; human check advised.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-treating-pancreatic-disorder-f4630f86b4', 'pharm-drugs-for-treating-pancreatic-disorders-aprotinin-glucagon-use-o', 'mcq', 'Which drug is NOT used for portal hypertension?', '["Propranolol", "Amlodipine", "Isosorbide 5-mononitrate", "Terlipressin", "Somatostatin"]'::jsonb, 'Amlodipine', '[]'::jsonb, 'Amlodipine, an arterial vasodilator, has no role in lowering portal pressure. Non-selective beta blockers such as propranolol reduce portal inflow, nitrates lower intrahepatic resistance, and terlipressin and somatostatin constrict the splanchnic bed in acute variceal bleeding.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.008 Q46, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-44430b65f1', 'pharm-antidiarrheal-agents-laxatives', 'mcq', 'Which statement is correct regarding laxatives?', '["Glycerine acts as a hygroscopic agent when given orally", "Misoprostol can be used in the treatment of constipation", "Nitric oxide synthase has no role in the pathophysiology of constipation", "Castor oil is a luminally active laxative", "A 5-HT4 receptor antagonist is useful in the treatment of chronic constipation"]'::jsonb, 'Misoprostol can be used in the treatment of constipation', '[]'::jsonb, 'Misoprostol, a prostaglandin E1 analogue, increases intestinal secretion and motility and is occasionally used for refractory constipation. Glycerin works as a hygroscopic agent only rectally, because it is absorbed when swallowed. Castor oil is a stimulant, and it is 5-HT4 agonists such as prucalopride that help constipation.', 'admin', 'draft', 1, false, '[]'::jsonb, 'git p.008 Q93, GIT pharmacology. Student''s key marked A (glycerine orally). Per Goodman & Gilman glycerin is absorbed orally and acts as a hygroscopic agent only rectally, while misoprostol is used off-label for constipation, so B is taken as correct. Needs a human check.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-e34b08908a', 'pharm-antidiarrheal-agents-laxatives', 'mcq', 'All of the following are true of diphenoxylate EXCEPT:', '["It is a prescription-only drug", "Difenoxin is its active metabolite", "It is potentially addictive", "It is available in preparations containing small doses of atropine", "It is a more potent antidiarrhoeal agent than loperamide"]'::jsonb, 'It is a more potent antidiarrhoeal agent than loperamide', '[]'::jsonb, 'Loperamide is the more potent antidiarrhoeal and does not enter the brain. Diphenoxylate is a pethidine congener that can cause opioid central effects and dependence at high doses, so it is combined with a small dose of atropine to discourage abuse.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.009, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-1d70ae8b2d', 'pharm-antidiarrheal-agents-laxatives', 'mcq', 'The following are stimulant laxatives EXCEPT:', '["Docusate sodium", "Castor oil", "Senna", "Bisacodyl", "Sodium picosulfate"]'::jsonb, 'Docusate sodium', '[]'::jsonb, 'Docusate is an anionic surfactant that lets water and fat penetrate the stool, softening it without stimulating the bowel. Senna, bisacodyl, sodium picosulfate and castor oil (through ricinoleic acid) irritate the mucosa or stimulate the enteric nerves to increase motility and secretion.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.009, GIT pharmacology. Paper''s options included liquid paraffin and glycerin, which are also not stimulant laxatives (three correct answers); replaced with castor oil and sodium picosulfate.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-f82e935183', 'pharm-antidiarrheal-agents-laxatives', 'mcq', 'Which statement about lubiprostone is UNTRUE?', '["Many patients experience a bowel movement within 24 hours of taking a dose", "It may safely be used in pregnancy", "It is indicated for the treatment of chronic constipation", "It stimulates the type 2 chloride channel in the small intestine", "It undergoes minimal systemic absorption"]'::jsonb, 'It may safely be used in pregnancy', '[]'::jsonb, 'Lubiprostone is a prostanoic acid derivative that opens type 2 chloride channels (ClC-2) in the small intestine, drawing fluid into the lumen. Animal studies showed fetal loss, so it should be avoided in pregnancy and in women who may become pregnant. Its main adverse effect is nausea.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.010, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emetics-antiemetics-and-prokinetic-age-711dfc3725', 'pharm-emetics-antiemetics-and-prokinetic-agents', 'mcq', 'A 40-year-old patient is about to undergo cancer chemotherapy with a highly emetogenic drug combination. The antiemetic drug most likely to be included in the regimen is:', '["Ketanserin", "Cetirizine", "Ondansetron", "Cimetidine", "Bromocriptine"]'::jsonb, 'Ondansetron', '[]'::jsonb, 'Cytotoxic drugs release serotonin from enterochromaffin cells in the gut, which stimulates 5-HT3 receptors on vagal afferents and in the chemoreceptor trigger zone. Ondansetron blocks these receptors and, with dexamethasone and aprepitant, is standard prophylaxis. Ketanserin blocks 5-HT2 receptors, and bromocriptine actually causes vomiting.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.011, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-appetite-stimulants-and-suppressants-f2a6254ada', 'pharm-appetite-stimulants-and-suppressants', 'mcq', 'All of the following are true of orlistat EXCEPT:', '["Fat-soluble vitamins should be replenished", "It inhibits gastric lipase", "It has no drug interactions", "It increases faecal fat excretion", "It is administered via the oral route"]'::jsonb, 'It has no drug interactions', '[]'::jsonb, 'By blocking fat absorption, orlistat reduces absorption of fat-soluble vitamins and of lipophilic drugs such as ciclosporin, amiodarone and levothyroxine, and it can enhance warfarin by lowering vitamin K. It is taken orally with meals and inhibits both gastric and pancreatic lipases.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.012, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-8f17cc11a3', 'pharm-antidiarrheal-agents-laxatives', 'mcq', 'Which drug is contraindicated in patients with a history of pancreatitis?', '["Racecadotril (acetorphan)", "Cholestyramine", "Bismuth subsalicylate", "Eluxadoline", "Probiotics"]'::jsonb, 'Eluxadoline', '[]'::jsonb, 'Eluxadoline, a mixed mu-opioid agonist and delta antagonist used for diarrhoea-predominant irritable bowel syndrome, can cause spasm of the sphincter of Oddi and pancreatitis. It is contraindicated in patients with previous pancreatitis, no gallbladder, biliary obstruction or heavy alcohol use.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.012, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-treating-pancreatic-disorder-9d313bc7ce', 'pharm-drugs-for-treating-pancreatic-disorders-aprotinin-glucagon-use-o', 'mcq', 'All of the following are true of octreotide EXCEPT:', '["It is administered parenterally", "It is used in gastrointestinal tumours associated with secretory diarrhoea", "It causes hyperglycaemia", "It causes hyperthyroidism", "It reduces both intestinal and pancreatic fluid secretion"]'::jsonb, 'It causes hyperthyroidism', '[]'::jsonb, 'Octreotide, a somatostatin analogue, inhibits TSH release and so can cause hypothyroidism, not hyperthyroidism. It also suppresses insulin release, causing hyperglycaemia, and reduces intestinal and pancreatic secretion, which is why it controls the diarrhoea of carcinoid tumours and VIPomas.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.013, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-inflammatory-and-irritable-b-a27b5808a1', 'pharm-drugs-for-inflammatory-and-irritable-bowel-disease', 'mcq', 'Which of the following is a monoclonal antibody targeting integrin in the management of inflammatory bowel disease?', '["Vedolizumab", "Rituximab", "Alemtuzumab", "Omalizumab", "Pembrolizumab"]'::jsonb, 'Vedolizumab', '[]'::jsonb, 'Vedolizumab binds the alpha-4 beta-7 integrin, which is specific to gut-homing lymphocytes, and blocks their entry into the intestinal mucosa. This gut selectivity gives it a lower risk of progressive multifocal leucoencephalopathy than natalizumab. Omalizumab targets IgE and rituximab CD20.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.014, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emetics-antiemetics-and-prokinetic-age-52f2f99935', 'pharm-emetics-antiemetics-and-prokinetic-agents', 'mcq', 'Which statement is FALSE regarding ondansetron?', '["It causes constipation", "It inhibits 5-HT3 receptors on vagal nerve afferents", "Its predominant antiemetic effect is via central 5-HT3 receptor antagonism", "It causes QT prolongation within 1 to 2 hours of administration", "It does not require dose adjustment in renal impairment"]'::jsonb, 'Its predominant antiemetic effect is via central 5-HT3 receptor antagonism', '[]'::jsonb, 'The antiemetic action of 5-HT3 antagonists comes mainly from blocking peripheral 5-HT3 receptors on intestinal vagal and spinal afferents, with a smaller contribution from the chemoreceptor trigger zone. Constipation, headache and dose-related QT prolongation are recognised effects, and the dose is reduced in hepatic, not renal, impairment.', 'admin', 'draft', 1, false, '[]'::jsonb, 'git p.015, GIT pharmacology. Student''s key marked D (QT prolongation). Katzung states the antiemetic effect is mainly peripheral, and QT prolongation is a recognised early effect, so C is taken as the false statement. Two options are arguable; human check needed.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-treating-pancreatic-disorder-606883f6b2', 'pharm-drugs-for-treating-pancreatic-disorders-aprotinin-glucagon-use-o', 'mcq', 'The following drugs are used for the management of portal hypertension and oesophageal varices EXCEPT:', '["Isosorbide 5-mononitrate", "Terlipressin", "Propranolol", "Tolvaptan", "Octreotide"]'::jsonb, 'Tolvaptan', '[]'::jsonb, 'Tolvaptan is a vasopressin V2 receptor antagonist used for hyponatraemia; it does not lower portal pressure. Terlipressin acts on V1 receptors to constrict splanchnic vessels, octreotide reduces splanchnic blood flow, and propranolol with or without a nitrate is used to prevent variceal bleeding.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.016, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-appetite-stimulants-and-suppressants-c0340f7f67', 'pharm-appetite-stimulants-and-suppressants', 'mcq', 'Which drug is an appetite stimulant?', '["Liraglutide", "Topiramate", "Bupropion", "Phentermine", "Cyproheptadine"]'::jsonb, 'Cyproheptadine', '[]'::jsonb, 'Cyproheptadine blocks H1 and 5-HT2 receptors; antagonising serotonin''s satiety effect in the hypothalamus increases appetite and weight. The other four reduce appetite and are used, alone or in combination, as anti-obesity drugs. It is sometimes used for this purpose in underweight children.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.016, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-treating-pancreatic-disorder-42b1f0e170', 'pharm-drugs-for-treating-pancreatic-disorders-aprotinin-glucagon-use-o', 'mcq', 'Which is the FALSE statement about pancrelipase?', '["It can cause mucositis if chewed", "It is rapidly inactivated by gastric acid", "It is available as an enteric-coated formulation", "It is an alcohol-derived extract of hog pancreas", "High doses can cause diarrhoea"]'::jsonb, 'It is an alcohol-derived extract of hog pancreas', '[]'::jsonb, 'The alcohol-derived extract of hog pancreas is pancreatin, which has a low enzyme content. Pancrelipase is an enriched preparation with much higher lipase activity. Its enzymes are destroyed by acid, hence the enteric-coated microspheres, and they digest the oral mucosa if the capsule contents are chewed.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.018 Q33, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cytoprotective-agents-bismuth-compound-b6f835319d', 'pharm-cytoprotective-agents-bismuth-compounds-sucralfate-etc', 'mcq', 'Which statement is FALSE regarding drug use in the treatment of peptic ulcer disease?', '["Misoprostol can protect against NSAID-associated gastric ulcer", "Bismuth has direct action against H. pylori", "Sucralfate is most effective at basic pH", "Cimetidine may cause decreased libido in men", "Proton pump inhibitors are prodrugs"]'::jsonb, 'Sucralfate is most effective at basic pH', '[]'::jsonb, 'Sucralfate needs an acid environment (pH below 4) to polymerise into the viscous gel that binds to the ulcer base, so it should not be given together with antacids, H2 antagonists or proton pump inhibitors. Cimetidine''s anti-androgenic action explains reduced libido and gynaecomastia.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.020, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-treating-pancreatic-disorder-94a6eeae01', 'pharm-drugs-for-treating-pancreatic-disorders-aprotinin-glucagon-use-o', 'mcq', 'In the treatment of portal hypertension, which beta-adrenoceptor antagonist would you use?', '["Atenolol", "Nebivolol", "Metoprolol", "Propranolol", "Bisoprolol"]'::jsonb, 'Propranolol', '[]'::jsonb, 'A non-selective beta blocker is needed: beta-1 blockade lowers cardiac output and beta-2 blockade leaves splanchnic alpha vasoconstriction unopposed, so portal inflow falls. Propranolol and nadolol are the classic choices. Atenolol, metoprolol, bisoprolol and nebivolol are beta-1 selective and lack the splanchnic effect.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.020, GIT pharmacology. Paper''s option E was carvedilol, which is non-selective and is now also recommended for portal hypertension; replaced with bisoprolol to leave one correct answer.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-0f7158a8fa', 'pharm-antidiarrheal-agents-laxatives', 'mcq', 'Which laxative is used in hepatic encephalopathy?', '["Polyethylene glycol solution", "Castor oil", "Lactulose", "Bran", "Mannitol"]'::jsonb, 'Lactulose', '[]'::jsonb, 'Colonic bacteria ferment lactulose to lactic and acetic acids. The lower pH converts ammonia to non-absorbable ammonium, which is trapped in the lumen and expelled by the osmotic laxative effect, so blood ammonia falls. Mannitol and polyethylene glycol are osmotic but do not acidify the colon.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.020, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h2-receptor-antagonist-proton-pump-inh-49b2d46559', 'pharm-h2-receptor-antagonist-proton-pump-inhibitor', 'mcq', 'Which is true of cimetidine?', '["It acts on both H1 and H2 receptors", "It is poorly absorbed when taken orally", "It is a microsomal enzyme inducer", "It inhibits prolactin production", "It alters oestrogen metabolism in men"]'::jsonb, 'It alters oestrogen metabolism in men', '[]'::jsonb, 'Cimetidine inhibits the hepatic metabolism of oestradiol and also blocks androgen receptors, which causes gynaecomastia and impotence in men. It is selective for H2 receptors, well absorbed orally, an inhibitor (not inducer) of cytochrome P450, and it raises prolactin levels.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.021, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-git-pharmacology-class-f9509636a9', 'pharm-introduction-to-git-pharmacology-classification-of-drugs-for-pep', 'mcq', 'Choose the drug that causes constipation:', '["Aluminium hydroxide", "Magnesium oxide", "Misoprostol", "Magnesium hydroxide", "Sodium bicarbonate"]'::jsonb, 'Aluminium hydroxide', '[]'::jsonb, 'Aluminium salts slow intestinal motility and cause constipation, whereas magnesium salts are osmotic and cause diarrhoea; the two are combined in antacid mixtures to balance each other. Misoprostol causes diarrhoea, and sodium bicarbonate causes belching and alkalosis.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.022, GIT pharmacology. Paper''s option D was calcium carbonate, which also causes constipation (two correct answers); replaced with magnesium hydroxide.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h2-receptor-antagonist-proton-pump-inh-fc21e4dfa0', 'pharm-h2-receptor-antagonist-proton-pump-inhibitor', 'mcq', 'Which drug inhibits the gastric mucosal proton pump?', '["Magnesium hydroxide", "Famotidine", "Carbenoxolone sodium", "Lansoprazole", "Sucralfate"]'::jsonb, 'Lansoprazole', '[]'::jsonb, 'Lansoprazole is activated in the acid canaliculus of the parietal cell and binds covalently to the H+/K+ ATPase, blocking the final step of acid secretion. Famotidine blocks H2 receptors, magnesium hydroxide neutralises acid already secreted, and carbenoxolone and sucralfate protect the mucosa.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.022, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-absorption-f85a5b3fea', 'pharm-absorption', 'mcq', 'The main mechanism of absorption of most drugs in the gastrointestinal tract is:', '["Endocytosis and exocytosis", "Passive diffusion (lipid diffusion)", "Osmosis", "Filtration (aqueous diffusion)", "Active transport (carrier-mediated)"]'::jsonb, 'Passive diffusion (lipid diffusion)', '[]'::jsonb, 'Most drugs are small lipid-soluble molecules that cross the intestinal epithelium by dissolving in the membrane and moving down their concentration gradient, without energy or a carrier. Only the non-ionised form crosses readily. Carrier-mediated transport matters for a few drugs such as levodopa.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.023, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emetics-antiemetics-and-prokinetic-age-5944a67907', 'pharm-emetics-antiemetics-and-prokinetic-agents', 'mcq', 'The most effective antiemetic for controlling cisplatin-induced vomiting is:', '["Ondansetron", "Prochlorperazine", "Metoclopramide", "Promethazine", "Domperidone"]'::jsonb, 'Ondansetron', '[]'::jsonb, 'Cisplatin is highly emetogenic because it releases large amounts of serotonin from the gut. 5-HT3 antagonists such as ondansetron are the most effective single agents for the acute phase and replaced high-dose metoclopramide, which was less effective and caused extrapyramidal reactions.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.024, GIT pharmacology. Student''s key marked metoclopramide; ondansetron (a 5-HT3 antagonist) is the correct answer.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-treating-pancreatic-disorder-6bd353d488', 'pharm-drugs-for-treating-pancreatic-disorders-aprotinin-glucagon-use-o', 'mcq', 'Which drug is NOT used for the management of oesophageal varices?', '["Metoprolol", "Propranolol", "Vasopressin", "Terlipressin", "Octreotide"]'::jsonb, 'Metoprolol', '[]'::jsonb, 'Metoprolol is beta-1 selective, so it lacks the beta-2 blockade that produces splanchnic vasoconstriction and lowers portal pressure. Propranolol is used for prophylaxis, while vasopressin, its analogue terlipressin and octreotide are used to control acute variceal bleeding.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.025, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h2-receptor-antagonist-proton-pump-inh-63e19a4143', 'pharm-h2-receptor-antagonist-proton-pump-inhibitor', 'mcq', 'Which drug lowers gastric acid by antagonism of histamine receptors?', '["Bismuth", "Misoprostol", "Sucralfate", "Omeprazole", "Ranitidine"]'::jsonb, 'Ranitidine', '[]'::jsonb, 'Ranitidine competitively blocks H2 receptors on the parietal cell, reducing the cAMP-driven acid secretion stimulated by histamine from enterochromaffin-like cells. Omeprazole blocks the proton pump itself, misoprostol acts on prostaglandin receptors, and bismuth and sucralfate are mucosal protectants.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.025, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-inflammatory-and-irritable-b-240ce5ebcd', 'pharm-drugs-for-inflammatory-and-irritable-bowel-disease', 'mcq', 'Which drug is used for mild inflammatory bowel disease?', '["Natalizumab", "Methotrexate", "Methylprednisolone", "Infliximab", "5-aminosalicylate"]'::jsonb, '5-aminosalicylate', '[]'::jsonb, '5-aminosalicylates (mesalazine, sulfasalazine) are first-line treatment for inducing and maintaining remission in mild to moderate ulcerative colitis, acting topically on the mucosa. Corticosteroids are added for moderate to severe flares, and immunosuppressants and biologics are reserved for refractory disease.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.026, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h2-receptor-antagonist-proton-pump-inh-dc0e2cbc08', 'pharm-h2-receptor-antagonist-proton-pump-inhibitor', 'mcq', 'All of the following are true of proton pump inhibitors EXCEPT:', '["Pantoprazole is available in an intravenous formulation", "They are administered as prodrugs", "They should be administered on an empty stomach", "They have long half-lives", "They irreversibly inactivate the parietal cell H+/K+ ATPase"]'::jsonb, 'They have long half-lives', '[]'::jsonb, 'Proton pump inhibitors have short plasma half-lives of 1 to 2 hours. Their effect nevertheless lasts about 24 hours because they bind the pump covalently, and acid secretion returns only when new pumps are made. They are given 30 to 60 minutes before a meal so peak levels coincide with active pumps.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.026, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emetics-antiemetics-and-prokinetic-age-faeb59c518', 'pharm-emetics-antiemetics-and-prokinetic-agents', 'mcq', 'Which of the following drugs is NOT appropriately matched with its clinical indication?', '["Promethazine: morning sickness of pregnancy", "Hyoscine: chemotherapy-induced vomiting", "Ondansetron: radiation therapy-induced vomiting", "Chlorpromazine: cancer-induced vomiting", "Dronabinol: drug-induced vomiting"]'::jsonb, 'Hyoscine: chemotherapy-induced vomiting', '[]'::jsonb, 'Hyoscine (scopolamine) is a muscarinic antagonist that acts on the vestibular pathway; it is the drug for motion sickness and has no useful effect on chemotherapy-induced vomiting, which is driven by serotonin and substance P and treated with 5-HT3 and NK1 antagonists.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.027, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-inflammatory-and-irritable-b-69fe203b52', 'pharm-drugs-for-inflammatory-and-irritable-bowel-disease', 'mcq', 'Which one of the following preparations is a suppository used in the management of inflammatory bowel disease?', '["Canasa", "Rowasa", "Asacol", "Pentasa", "Olsalazine"]'::jsonb, 'Canasa', '[]'::jsonb, 'Canasa is mesalazine (5-ASA) formulated as a suppository for ulcerative proctitis. Rowasa is a mesalazine enema that reaches the left colon, while Asacol (pH-dependent coating), Pentasa (timed-release microgranules) and olsalazine (a 5-ASA dimer) are oral preparations.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.027, GIT pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-fluids-776c972c03', 'pharm-intravenous-fluids', 'mcq', 'The recommended intravenous fluid for rehydration of a patient with severe vomiting is:', '["Ringer''s solution", "Darrow''s solution", "Normal saline", "5% dextrose solution", "Hartmann''s solution"]'::jsonb, 'Normal saline', '[]'::jsonb, 'Vomiting loses hydrochloric acid, producing a hypochloraemic, hypokalaemic metabolic alkalosis. Normal saline (0.9% sodium chloride, with added potassium) replaces volume and chloride, allowing the kidney to excrete bicarbonate. Hartmann''s and Darrow''s solutions contain lactate, which is converted to bicarbonate and would worsen the alkalosis; they suit diarrhoea.', 'admin', 'draft', 1, false, '[]'::jsonb, 'git p.027, GIT pharmacology. Student''s key marked Ringer''s solution. Normal saline is the standard answer for vomiting-induced hypochloraemic alkalosis, but (non-lactated) Ringer''s solution is also chloride-rich, so the lecturer''s intended answer should be confirmed.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h2-receptor-antagonist-proton-pump-inh-8742836fe0', 'pharm-h2-receptor-antagonist-proton-pump-inhibitor', 'mcq', 'Histamine H2-receptor antagonists are indicated for the following EXCEPT:', '["Peptic ulcer disease", "Gastro-oesophageal reflux disease", "Dyspepsia", "Stress ulcer prophylaxis", "Allergic rhinitis and urticaria"]'::jsonb, 'Allergic rhinitis and urticaria', '[]'::jsonb, 'Allergic rhinitis and urticaria are mediated by H1 receptors and are treated with H1 antihistamines such as cetirizine. H2 antagonists reduce gastric acid secretion, so their uses are all acid-related: peptic ulcer, reflux, dyspepsia and prevention of stress ulcers.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.028 Q1, GIT pharmacology (Gastrointestinal Pharmacology MCQs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h2-receptor-antagonist-proton-pump-inh-6a1460d250', 'pharm-h2-receptor-antagonist-proton-pump-inhibitor', 'mcq', 'All of the following are true of omeprazole EXCEPT:', '["It is enteric coated", "Its bioavailability is reduced by food", "Its binding to the proton pump is reversible", "It is metabolised in the liver", "It is administered orally"]'::jsonb, 'Its binding to the proton pump is reversible', '[]'::jsonb, 'Activated omeprazole forms a covalent disulphide bond with the H+/K+ ATPase, inactivating it irreversibly; secretion recovers only as new pumps are synthesised. It is acid-labile, hence the enteric coating, is best taken before food, and is cleared by hepatic CYP2C19 and CYP3A4.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.028 Q2, GIT pharmacology (Gastrointestinal Pharmacology MCQs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emetics-antiemetics-and-prokinetic-age-6ce0ceacda', 'pharm-emetics-antiemetics-and-prokinetic-agents', 'mcq', 'Induction of emesis is contraindicated in all of the following EXCEPT:', '["Ingestion of kerosene", "A comatose patient", "Overdose of an antiemetic agent", "Ingestion of a corrosive agent", "Overdose of a CNS stimulant"]'::jsonb, 'Overdose of an antiemetic agent', '[]'::jsonb, 'Emesis is dangerous after kerosene (aspiration pneumonitis), in coma (unprotected airway), after corrosives (a second burn to the oesophagus) and after CNS stimulants (it may trigger convulsions). An antiemetic overdose is not a contraindication, though the emetic may simply fail to work.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.028 Q3, GIT pharmacology (Gastrointestinal Pharmacology MCQs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-203a521203', 'pharm-antidiarrheal-agents-laxatives', 'mcq', 'Bulk laxatives include:', '["Calcium polycarbophil", "Frangula", "Mannitol", "Bisacodyl", "Sodium docusate"]'::jsonb, 'Calcium polycarbophil', '[]'::jsonb, 'Calcium polycarbophil is a synthetic hydrophilic resin that absorbs water and swells, increasing stool bulk like psyllium and methylcellulose. Frangula (an anthraquinone) and bisacodyl are stimulants, mannitol is osmotic and docusate is a stool softener.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.028 Q4, GIT pharmacology (Gastrointestinal Pharmacology MCQs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emetics-antiemetics-and-prokinetic-age-0f35a6805a', 'pharm-emetics-antiemetics-and-prokinetic-agents', 'mcq', 'Which of the following has both antiemetic and prokinetic effects?', '["Cisapride", "Neostigmine", "Domperidone", "Promethazine", "Chlorpromazine"]'::jsonb, 'Domperidone', '[]'::jsonb, 'Domperidone blocks D2 receptors in the chemoreceptor trigger zone (antiemetic) and in the upper gut (prokinetic), as metoclopramide does, but crosses the blood-brain barrier poorly. Cisapride and neostigmine are prokinetic only; promethazine and chlorpromazine are antiemetic without prokinetic action.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.028 Q5, GIT pharmacology (Gastrointestinal Pharmacology MCQs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-git-pharmacology-class-44429d4373', 'pharm-introduction-to-git-pharmacology-classification-of-drugs-for-pep', 'mcq', 'The following are true of antacids EXCEPT:', '["Magnesium hydroxide is a luminal (non-systemic) antacid", "Sodium bicarbonate has systemic effects when given orally", "Aluminium hydroxide causes gastric distension and belching", "Sodium bicarbonate may worsen fluid retention in heart failure", "Sodium bicarbonate can lead to milk-alkali syndrome when given concurrently with dairy products"]'::jsonb, 'Aluminium hydroxide causes gastric distension and belching', '[]'::jsonb, 'Distension and belching come from the carbon dioxide released when sodium bicarbonate or calcium carbonate reacts with acid. Aluminium hydroxide produces no gas; its problems are constipation and phosphate depletion. Sodium bicarbonate is absorbed, causing alkalosis and a sodium load.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.028 Q6, GIT pharmacology (Gastrointestinal Pharmacology MCQs). Paper''s option D attributed fluid retention in heart failure to calcium carbonate, which is also false (two correct answers); corrected to sodium bicarbonate.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-git-pharmacology-class-474e4063c4', 'pharm-introduction-to-git-pharmacology-classification-of-drugs-for-pep', 'mcq', 'The following factors affect the acid neutralisation capacity of an antacid EXCEPT:', '["Its rate of dissolution", "Its lipid solubility", "Its water solubility", "Its rate of reaction with hydrochloric acid", "The rate of gastric emptying"]'::jsonb, 'Its lipid solubility', '[]'::jsonb, 'Antacids act in the gastric lumen by a chemical reaction with acid, so what matters is how fast they dissolve and react and how long they stay in the stomach (given after meals they last up to 2 hours). They do not need to cross membranes, so lipid solubility is irrelevant.', 'admin', 'published', 1, false, '[]'::jsonb, 'git p.028-029 Q7, GIT pharmacology (Gastrointestinal Pharmacology MCQs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacology-routes-of-fcb4f3662f', 'pharm-introduction-to-pharmacology-routes-of-drug-administration', 'mcq', 'Which of the following describes the study of what the body does to a drug?', '["Pharmacodynamics", "Pharmacokinetics", "Pharmacotherapeutics", "Toxicology", "Posology"]'::jsonb, 'Pharmacokinetics', '[]'::jsonb, 'Pharmacokinetics covers absorption, distribution, metabolism and excretion: what the body does to the drug. Pharmacodynamics is the reverse, what the drug does to the body (mechanism and effects). Posology is the study of dosage.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.006 Q1, Introduction to Pharmacology & Routes of Administration') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacology-routes-of-b5ce96335f', 'pharm-introduction-to-pharmacology-routes-of-drug-administration', 'mcq', 'The "first-pass effect" is most significant with which route of administration?', '["Sublingual", "Intravenous", "Oral", "Rectal", "Transdermal"]'::jsonb, 'Oral', '[]'::jsonb, 'A swallowed drug is absorbed into the portal vein and must pass the gut wall and liver before reaching the systemic circulation, so it may be extensively metabolised first. Sublingual, transdermal and intravenous routes bypass the portal circulation; the rectal route bypasses it only partly.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.006 Q2, Introduction to Pharmacology & Routes of Administration') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacology-routes-of-aaab6ecf88', 'pharm-introduction-to-pharmacology-routes-of-drug-administration', 'mcq', 'Which route provides 100% bioavailability?', '["Intramuscular", "Oral", "Subcutaneous", "Intravenous", "Inhalation"]'::jsonb, 'Intravenous', '[]'::jsonb, 'An intravenous dose is placed directly into the systemic circulation, so by definition its bioavailability (F) is 1. Intramuscular and subcutaneous doses are usually well absorbed, but absorption can be incomplete or the drug may be degraded at the site, so 100% is not guaranteed.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.006 Q3, Introduction to Pharmacology & Routes of Administration') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacology-routes-of-5e6c6059d9', 'pharm-introduction-to-pharmacology-routes-of-drug-administration', 'mcq', 'Which factor primarily determines the rate of drug absorption from the subcutaneous site?', '["Gastric emptying time", "Blood flow to the injection site", "First-pass metabolism", "Plasma protein binding", "Glomerular filtration rate"]'::jsonb, 'Blood flow to the injection site', '[]'::jsonb, 'A drug injected subcutaneously only has to diffuse into nearby capillaries, so local blood flow sets the rate. This is why adrenaline (vasoconstriction) slows absorption and warmth or massage speeds it. Gastric emptying and first-pass metabolism matter only for oral dosing.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.007 Q4, Introduction to Pharmacology & Routes of Administration') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacology-routes-of-f1e39350b6', 'pharm-introduction-to-pharmacology-routes-of-drug-administration', 'mcq', 'A prodrug is:', '["An active drug that is metabolized to an inactive form", "An inactive precursor that is converted to an active drug in the body", "A drug that acts only on the central nervous system", "A drug used exclusively in neonates", "A drug that bypasses all metabolic pathways"]'::jsonb, 'An inactive precursor that is converted to an active drug in the body', '[]'::jsonb, 'A prodrug has little or no activity until it is biotransformed into the active compound, for example enalapril to enalaprilat or levodopa to dopamine. The first option describes ordinary metabolic inactivation, which is the opposite process.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.007 Q5, Introduction to Pharmacology & Routes of Administration') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacology-routes-of-f729aa0afa', 'pharm-introduction-to-pharmacology-routes-of-drug-administration', 'mcq', 'The term "Orphan Drugs" refers to:', '["Drugs used for common cold", "Drugs used for the treatment of rare diseases", "Drugs that have no patent", "Drugs derived from plants", "Over-the-counter medications"]'::jsonb, 'Drugs used for the treatment of rare diseases', '[]'::jsonb, 'Orphan drugs treat diseases so rare that development would not be commercially worthwhile without incentives such as market exclusivity and tax relief. The term has nothing to do with patent status: a drug without patent protection is simply off-patent or generic.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.007 Q6, Introduction to Pharmacology & Routes of Administration') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacology-routes-of-d5b53b44a3', 'pharm-introduction-to-pharmacology-routes-of-drug-administration', 'mcq', 'Which of the following is a disadvantage of the sublingual route?', '["It bypasses the liver", "Rapid onset of action", "Frequent use may irritate the mucosa", "High bioavailability", "Easy self-administration"]'::jsonb, 'Frequent use may irritate the mucosa', '[]'::jsonb, 'Sublingual drugs are absorbed straight into the systemic veins, giving a fast onset and avoiding first-pass metabolism, which are advantages. The drawbacks are that only small doses of lipid-soluble, palatable drugs can be given and repeated use may irritate or ulcerate the oral mucosa.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.007 Q7, Introduction to Pharmacology & Routes of Administration') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacology-routes-of-ca24456b09', 'pharm-introduction-to-pharmacology-routes-of-drug-administration', 'mcq', 'Enteric-coated tablets are designed to dissolve in the:', '["Stomach", "Oesophagus", "Small intestine", "Mouth", "Rectum"]'::jsonb, 'Small intestine', '[]'::jsonb, 'The enteric coat is an acid-resistant polymer that stays intact at gastric pH and dissolves only in the more alkaline small intestine. It protects acid-labile drugs (such as omeprazole) from the stomach and protects the stomach from irritant drugs (such as aspirin).', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.007 Q8, Introduction to Pharmacology & Routes of Administration') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacology-routes-of-b4391afd44', 'pharm-introduction-to-pharmacology-routes-of-drug-administration', 'mcq', 'Intrathecal administration involves injecting the drug into the:', '["Spinal subarachnoid space", "Joint space", "Bone marrow", "Pleural cavity", "Muscle belly"]'::jsonb, 'Spinal subarachnoid space', '[]'::jsonb, 'Intrathecal injection delivers the drug into the cerebrospinal fluid of the subarachnoid space, bypassing the blood-brain barrier; it is used for spinal anaesthesia and some chemotherapy. Injection into a joint is intra-articular and into the marrow is intraosseous.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.007 Q9, Introduction to Pharmacology & Routes of Administration') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacology-routes-of-1ef39e0188', 'pharm-introduction-to-pharmacology-routes-of-drug-administration', 'mcq', 'The study of the adverse effects of drugs and chemicals is known as:', '["Pharmacy", "Pharmacogenetics", "Toxicology", "Pharmacognosy", "Clinical Pharmacology"]'::jsonb, 'Toxicology', '[]'::jsonb, 'Toxicology deals with the harmful effects of drugs, chemicals and poisons, and with their detection and treatment. Pharmacognosy is the study of drugs from natural sources, and pharmacogenetics is the study of inherited differences in drug response.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.008 Q10, Introduction to Pharmacology & Routes of Administration') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacology-routes-of-2deecf67fb', 'pharm-introduction-to-pharmacology-routes-of-drug-administration', 'mcq', 'Which of the following is a topical route of administration?', '["Oral", "Transdermal patch", "Intramuscular", "Intraperitoneal", "Intravenous"]'::jsonb, 'Transdermal patch', '[]'::jsonb, 'Topical administration means applying the drug to a body surface such as skin or mucous membrane. A transdermal patch is applied to the skin, although its aim is a systemic effect. The other options are enteral (oral) or injected routes.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.008 Q11, Introduction to Pharmacology & Routes of Administration') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-bioavailability-0c1cdf4780', 'pharm-bioavailability', 'mcq', 'Bioavailability is defined as:', '["The total amount of drug excreted in urine", "The fraction of an administered dose that reaches the systemic circulation in unchanged form", "The rate at which the drug is metabolized by the liver", "The ratio of the lethal dose to the effective dose", "The time required for the plasma concentration to reduce by half"]'::jsonb, 'The fraction of an administered dose that reaches the systemic circulation in unchanged form', '[]'::jsonb, 'Bioavailability (F) is the fraction of the dose that reaches the systemic circulation unchanged; it is reduced by incomplete absorption and first-pass metabolism. The ratio of lethal to effective dose is the therapeutic index, and the time for the concentration to halve is the half-life.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.008 Q12, Introduction to Pharmacology & Routes of Administration') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacology-routes-of-2815713c0b', 'pharm-introduction-to-pharmacology-routes-of-drug-administration', 'mcq', 'Which route of administration is most suitable for emergency situations requiring immediate action?', '["Oral", "Intramuscular", "Intravenous", "Transdermal", "Subcutaneous"]'::jsonb, 'Intravenous', '[]'::jsonb, 'Intravenous injection has no absorption phase, so effective plasma concentrations are reached within seconds and the dose can be titrated. Intramuscular injection is quicker than oral dosing but still depends on absorption from the muscle.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.008 Q13, Introduction to Pharmacology & Routes of Administration') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-log-dose-responses-ac48a21991', 'pharm-log-dose-responses', 'mcq', 'The "Therapeutic Index" is a measure of a drug''s:', '["Potency", "Efficacy", "Safety", "Bioavailability", "Absorption rate"]'::jsonb, 'Safety', '[]'::jsonb, 'The therapeutic index is the ratio of the dose toxic or lethal to half the population to the dose effective in half (TD50 or LD50 divided by ED50). The larger it is, the wider the margin between useful and harmful doses. Potency is read from the ED50 alone.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.008 Q14, Introduction to Pharmacology & Routes of Administration') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacology-routes-of-ff33d44bda', 'pharm-introduction-to-pharmacology-routes-of-drug-administration', 'mcq', 'Which of the following is NOT a parenteral route?', '["Intradermal", "Intravenous", "Subcutaneous", "Oral", "Intramuscular"]'::jsonb, 'Oral', '[]'::jsonb, 'Parenteral routes avoid the gastrointestinal tract and in practice mean injections: intradermal, subcutaneous, intramuscular and intravenous. The oral route is the main enteral route, with absorption through the gut.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.008 Q15, Introduction to Pharmacology & Routes of Administration. Original had two defensible answers (inhalation and sublingual); replaced them with intravenous and oral so only one option is not parenteral.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-dosage-forms-eb14e34af8', 'pharm-dosage-forms', 'mcq', 'A liquid dosage form that consists of a solid dispersed in a liquid medium is a:', '["Solution", "Suspension", "Elixir", "Syrup", "Tincture"]'::jsonb, 'Suspension', '[]'::jsonb, 'In a suspension, insoluble solid particles are dispersed, not dissolved, in the liquid, which is why the bottle must be shaken before use. In a solution the drug is fully dissolved, giving a clear single-phase liquid.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.009 Q1, Dosage Forms') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-dosage-forms-ba3d25bd96', 'pharm-dosage-forms', 'mcq', 'Sustained-release formulations are primarily intended to:', '["Increase the peak plasma concentration", "Reduce the frequency of dosing", "Increase the first-pass effect", "Decrease the shelf life of the drug", "Increase the rate of drug excretion"]'::jsonb, 'Reduce the frequency of dosing', '[]'::jsonb, 'Sustained-release products release the drug slowly, keeping plasma levels in the therapeutic range for longer so that fewer doses are needed and adherence improves. They flatten, rather than raise, the peak concentration, which also reduces peak-related adverse effects.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.009 Q2, Dosage Forms') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-dosage-forms-1ef4d65592', 'pharm-dosage-forms', 'mcq', 'Which of the following is a semi-solid dosage form?', '["Capsule", "Ointment", "Tablet", "Powder", "Aerosol"]'::jsonb, 'Ointment', '[]'::jsonb, 'Semi-solid forms include ointments, creams, gels and pastes, which are applied to skin or mucous membranes. Capsules, tablets and powders are solid dosage forms, and an aerosol is a pressurised dispersion in gas.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.009 Q3, Dosage Forms') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-dosage-forms-1e2ae5c43e', 'pharm-dosage-forms', 'mcq', 'A "Syrup" is defined as:', '["An alcoholic solution of a drug", "A concentrated aqueous solution of sugar", "A mixture of oil and water", "A solid dosage form for rectal use", "A sterile preparation for the eye"]'::jsonb, 'A concentrated aqueous solution of sugar', '[]'::jsonb, 'A syrup is a concentrated, viscous aqueous solution of sucrose (or another sugar), with or without a drug; the sugar masks taste and acts as a preservative. An alcoholic solution of a drug is a tincture or spirit, and a mixture of oil and water is an emulsion.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.009 Q4, Dosage Forms') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-dosage-forms-b328e78fd5', 'pharm-dosage-forms', 'mcq', 'Hard gelatin capsules are typically used for:', '["Oils", "Dry powdered ingredients", "Volatile liquids", "Highly acidic solutions", "Intravenous injections"]'::jsonb, 'Dry powdered ingredients', '[]'::jsonb, 'Hard gelatin capsules consist of two shells filled with dry powders, granules or pellets. Oils and other non-aqueous liquids are sealed in soft gelatin capsules instead, since liquids would leak from or soften a two-piece hard shell.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.009 Q5, Dosage Forms') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-dosage-forms-e73465ef55', 'pharm-dosage-forms', 'mcq', 'Which dosage form is specifically designed for insertion into body cavities such as the rectum or vagina?', '["Troche", "Suppository", "Lozenge", "Pellet", "Cachet"]'::jsonb, 'Suppository', '[]'::jsonb, 'Suppositories (and pessaries for the vagina) are solid forms that melt or dissolve at body temperature after insertion, for local or systemic effect. Troches and lozenges dissolve slowly in the mouth, and a cachet is a swallowed wafer shell containing powder.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.009 Q6, Dosage Forms') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-dosage-forms-38081e2d18', 'pharm-dosage-forms', 'mcq', 'An "Elixir" differs from a syrup because it contains:', '["More sugar", "Hydro-alcoholic solvent", "Only water", "Suspended particles", "Solid fat base"]'::jsonb, 'Hydro-alcoholic solvent', '[]'::jsonb, 'An elixir is a clear, sweetened, flavoured solution in a mixture of water and alcohol, which dissolves drugs that are poorly soluble in water alone. A syrup is a purely aqueous concentrated sugar solution, so it is more viscous and sweeter.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.010 Q7, Dosage Forms') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-dosage-forms-0a8b57ce64', 'pharm-dosage-forms', 'mcq', 'Which of the following is an advantage of liquid dosage forms over solid ones?', '["Better stability", "Easier to mask unpleasant tastes", "Faster absorption", "More convenient for travel", "Precise dosing without a measuring tool"]'::jsonb, 'Faster absorption', '[]'::jsonb, 'A drug in solution does not have to disintegrate and dissolve first, so absorption begins sooner than from a tablet. Liquids are also easy to swallow for children. Their weaknesses are the other options: poorer stability, more obvious taste, bulk, and the need for a measuring device.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.010 Q8, Dosage Forms') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-dosage-forms-513babc07e', 'pharm-dosage-forms', 'mcq', 'The process of "Trituration" in pharmacy refers to:', '["Dissolving a solid in a liquid", "Grinding a solid to a fine powder", "Mixing two liquids", "Sterilizing a solution", "Coating a tablet"]'::jsonb, 'Grinding a solid to a fine powder', '[]'::jsonb, 'Trituration is grinding a solid in a mortar with a pestle to reduce particle size, and it is also used to mix powders intimately. Dissolving a solid in a liquid is simply making a solution.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.010 Q9, Dosage Forms') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-dosage-forms-cd541cbfc9', 'pharm-dosage-forms', 'mcq', 'A "Bolus" refers to:', '["A slow intravenous drip", "A single, large dose given quickly", "A small tablet placed under the tongue", "A medicated gas", "A topical cream"]'::jsonb, 'A single, large dose given quickly', '[]'::jsonb, 'A bolus is a single dose given rapidly, usually intravenously, to raise the plasma concentration quickly. It contrasts with a slow intravenous infusion, which delivers the drug at a steady rate over time.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.010 Q10, Dosage Forms') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-dosage-forms-8734b7683d', 'pharm-dosage-forms', 'mcq', 'Enteric coating of a tablet is used to protect:', '["The drug from gastric acid only", "The stomach from the drug only", "The drug from light", "Both the drug from gastric acid and the stomach from the drug", "Neither the drug nor the stomach"]'::jsonb, 'Both the drug from gastric acid and the stomach from the drug', '[]'::jsonb, 'An enteric coat resists gastric acid and dissolves in the intestine. This serves two purposes: acid-labile drugs such as omeprazole or erythromycin are not destroyed in the stomach, and gastric irritants such as aspirin or diclofenac do not contact the gastric mucosa directly.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.010 Q12, Dosage Forms. Reworded ''A and B'' / ''None of the above'' options into words.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-dosage-forms-0e31a439f5', 'pharm-dosage-forms', 'mcq', 'Transdermal delivery systems (patches) are NOT suitable for:', '["Potent drugs", "Drugs with short half-lives", "Drugs that undergo extensive first-pass metabolism", "Drugs that require immediate high-peak concentrations", "Lipid-soluble drugs"]'::jsonb, 'Drugs that require immediate high-peak concentrations', '[]'::jsonb, 'Absorption through the skin is slow and steady, so a patch cannot give a rapid high peak. Patches work best for exactly the other options: potent, lipid-soluble drugs needed in small daily doses, with short half-lives or high first-pass metabolism, such as glyceryl trinitrate and fentanyl.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.011 Q13, Dosage Forms') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-dosage-forms-d605108935', 'pharm-dosage-forms', 'mcq', 'A sterile, pyrogen-free preparation intended for injection is called:', '["Parenteral", "Tincture", "Emulsion", "Suspension", "Liniment"]'::jsonb, 'Parenteral', '[]'::jsonb, 'Parenteral preparations are injected through the body''s barriers, so they must be sterile and free of pyrogens (fever-producing bacterial products). A tincture is an alcoholic extract, and a liniment is rubbed onto the skin.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.011 Q14, Dosage Forms') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-dosage-forms-2bb682089d', 'pharm-dosage-forms', 'mcq', 'The component of a dosage form that has no pharmacological effect but is used as a vehicle or filler is called:', '["Active ingredient", "Excipient", "Adjuvant", "Potentiator", "Antagonist"]'::jsonb, 'Excipient', '[]'::jsonb, 'Excipients are the inert substances in a formulation: diluents, binders, lubricants, preservatives, flavours and vehicles. An adjuvant, in contrast, is added to enhance the action of the active ingredient, as in vaccines.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.011 Q15, Dosage Forms') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-absorption-95114f9761', 'pharm-absorption', 'mcq', 'Which carrier-mediated mechanism of drug transport across membranes does NOT require energy and moves drugs down a concentration gradient?', '["Passive diffusion", "Facilitated diffusion", "Active transport", "Paracellular transport", "Endocytosis"]'::jsonb, 'Facilitated diffusion', '[]'::jsonb, 'Facilitated diffusion uses a membrane carrier but no energy, so it can only move a drug down its concentration gradient and is saturable. Active transport also uses a carrier but consumes energy and can move drugs against a gradient. Passive diffusion needs no carrier at all.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.011 Q1, Drug Absorption. Original stem was self-contradictory (no energy but against a gradient); reworded so facilitated diffusion is the single correct answer.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-absorption-547e47570d', 'pharm-absorption', 'mcq', 'Most drugs are absorbed across the gastrointestinal tract via:', '["Active transport", "Facilitated diffusion", "Passive diffusion", "Pinocytosis", "Filtration through pores"]'::jsonb, 'Passive diffusion', '[]'::jsonb, 'Most drugs are small, reasonably lipid-soluble molecules that cross the gut epithelium by passive diffusion down a concentration gradient. Active transport applies only to the few drugs that resemble nutrients, such as levodopa and methyldopa.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.011 Q2, Drug Absorption') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-absorption-62bb70d8f0', 'pharm-absorption', 'mcq', 'Weakly acidic drugs are best absorbed from the stomach because they are:', '["Highly ionized in acidic pH", "Largely non-ionized in acidic pH", "Highly water-soluble in the stomach", "Bound to gastric mucin", "More stable in low pH"]'::jsonb, 'Largely non-ionized in acidic pH', '[]'::jsonb, 'At a pH below its pKa a weak acid is mostly protonated and therefore uncharged, and only the uncharged, lipid-soluble form diffuses across membranes. Ionised molecules are water-soluble and cross poorly. In practice the small intestine still absorbs most of the dose because of its huge surface area.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.011 Q3, Drug Absorption') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-absorption-90bbd77101', 'pharm-absorption', 'mcq', 'Which of the following significantly increases the surface area available for drug absorption in the small intestine?', '["Tight junctions", "Villi and microvilli", "Gastric rugae", "Peristaltic waves", "Bile duct secretions"]'::jsonb, 'Villi and microvilli', '[]'::jsonb, 'Folds, villi and microvilli give the small intestine a surface of about 200 square metres, which is why it is the main site of absorption for nearly all oral drugs. Gastric rugae are folds of the stomach, whose absorptive surface is small.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.012 Q4, Drug Absorption') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-absorption-0d0dd86d80', 'pharm-absorption', 'mcq', 'P-glycoprotein is a membrane transporter that:', '["Increases drug absorption into the blood", "Acts as an efflux pump to move drugs out of cells", "Facilitates the entry of glucose into brain cells", "Is only found in the liver", "Binds to albumin in the plasma"]'::jsonb, 'Acts as an efflux pump to move drugs out of cells', '[]'::jsonb, 'P-glycoprotein is an ATP-driven efflux pump in the gut epithelium, liver, kidney and blood-brain barrier. It pumps drugs such as digoxin back out of cells, so it lowers absorption and brain penetration. Inhibitors such as verapamil raise the levels of its substrates.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.012 Q5, Drug Absorption') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-absorption-b9d5bdb59c', 'pharm-absorption', 'mcq', 'The rate of gastric emptying is slowed by:', '["Large volumes of water", "Fatty meals", "Prokinetic drugs like metoclopramide", "Anxiety", "Hunger"]'::jsonb, 'Fatty meals', '[]'::jsonb, 'Fat in the duodenum releases cholecystokinin, which delays gastric emptying, so a fatty meal slows the delivery of a drug to its main absorption site. Antimuscarinics and opioids do the same. Metoclopramide has the opposite effect and speeds emptying.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.012 Q6, Drug Absorption') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-absorption-d29860984a', 'pharm-absorption', 'mcq', 'Absorption of a drug from the intramuscular site is generally faster than from the subcutaneous site because:', '["Muscles have higher fat content", "Muscles have a richer blood supply", "Subcutaneous tissue has more nerve endings", "Muscle pH is more alkaline", "Subcutaneous tissue contains more proteases"]'::jsonb, 'Muscles have a richer blood supply', '[]'::jsonb, 'Absorption from an injection site is limited by local blood flow. Skeletal muscle is more vascular than subcutaneous fat, so the drug is carried away faster. Exercise increases muscle blood flow further, and shock slows absorption from both sites.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.012 Q7, Drug Absorption') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-absorption-6029d30794', 'pharm-absorption', 'mcq', 'Which drug property favours passive diffusion across the blood-brain barrier?', '["High ionization at physiological pH", "High lipid solubility", "High molecular weight", "High water solubility", "Strong binding to plasma proteins"]'::jsonb, 'High lipid solubility', '[]'::jsonb, 'Brain capillaries have tight junctions and no pores, so a drug must dissolve in the endothelial cell membrane to enter. Small, un-ionised, lipid-soluble and unbound molecules such as diazepam cross readily; ionised, polar or large molecules are excluded.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.012 Q8, Drug Absorption') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-absorption-f9b20825c1', 'pharm-absorption', 'mcq', 'The Henderson-Hasselbalch equation is used to determine:', '["The rate of drug metabolism", "The degree of ionization of a drug at a given pH", "The volume of distribution", "The half-life of a drug", "The clearance of a drug from the kidneys"]'::jsonb, 'The degree of ionization of a drug at a given pH', '[]'::jsonb, 'The equation relates pH and the drug''s pKa to the ratio of ionised to un-ionised drug. This predicts how well a weak acid or base will cross membranes at a given site and explains ion trapping, for example in alkaline urine.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.012 Q9, Drug Absorption') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-absorption-c9498a77b3', 'pharm-absorption', 'mcq', 'Lipid-soluble drugs are absorbed more rapidly than water-soluble drugs because:', '["Cell membranes are primarily protein", "Cell membranes are primarily phospholipid bilayers", "Water-soluble drugs are too large", "Lipid-soluble drugs are always non-polar", "Water-soluble drugs are always acidic"]'::jsonb, 'Cell membranes are primarily phospholipid bilayers', '[]'::jsonb, 'The cell membrane is a phospholipid bilayer with a hydrophobic core, so a drug must dissolve in lipid to diffuse through it. Water-soluble (polar or ionised) molecules cannot pass unless they are very small or have a carrier.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.013 Q11, Drug Absorption') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-absorption-ccc895b29e', 'pharm-absorption', 'mcq', 'Which of the following decreases the absorption of oral tetracycline?', '["Vitamin C supplements", "Taking it with a glass of water", "Concurrent administration of antacids containing calcium or magnesium", "Fasting", "Taking it in a standing position"]'::jsonb, 'Concurrent administration of antacids containing calcium or magnesium', '[]'::jsonb, 'Tetracyclines chelate divalent and trivalent cations (calcium, magnesium, aluminium, iron) to form insoluble complexes that are not absorbed. Antacids, milk and iron tablets should therefore be separated from the dose by a few hours. Fasting actually improves absorption.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.013 Q12, Drug Absorption') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-bioavailability-5136a11eb4', 'pharm-bioavailability', 'mcq', 'Bioequivalence between two drug products means they have the same:', '["Colour and shape", "Cost and manufacturer", "Rate and extent of absorption", "Number of excipients", "Shelf life"]'::jsonb, 'Rate and extent of absorption', '[]'::jsonb, 'Two products are bioequivalent when the same dose gives essentially the same AUC (extent of absorption) and the same Cmax and Tmax (rate of absorption). This is what allows a generic to be substituted for the brand; appearance and excipients may differ.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.013 Q13, Drug Absorption') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-absorption-d95f58f6d3', 'pharm-absorption', 'mcq', 'Pinocytosis involves:', '["Movement through aqueous pores", "Engulfing of drug particles by the cell membrane", "Binding to a carrier protein", "Passage through the placenta", "Diffusion through lipid layers"]'::jsonb, 'Engulfing of drug particles by the cell membrane', '[]'::jsonb, 'In pinocytosis the membrane invaginates around a droplet of fluid containing the drug and pinches off as a vesicle inside the cell. It needs energy and is how some large molecules, such as proteins and vitamin B12 with intrinsic factor, are taken up.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.013 Q14, Drug Absorption') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-absorption-76a20ab26c', 'pharm-absorption', 'mcq', 'The absorption of basic drugs is maximized in the:', '["Stomach", "Small intestine", "Oesophagus", "Large intestine", "Mouth"]'::jsonb, 'Small intestine', '[]'::jsonb, 'A weak base is largely un-ionised, and so lipid-soluble, at the higher pH of the small intestine, which also has a very large surface area and blood flow. In the acid stomach a weak base is ionised and trapped, so little is absorbed there.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.013 Q15, Drug Absorption') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-transport-and-distribution-319e59710e', 'pharm-transport-and-distribution', 'mcq', 'Volume of distribution (Vd) is defined as:', '["The total volume of blood in the body", "The ratio of the amount of drug in the body to the concentration of drug in plasma", "The volume of fluid filtered by the kidneys per minute", "The amount of drug excreted in the bile", "The total volume of the intracellular fluid"]'::jsonb, 'The ratio of the amount of drug in the body to the concentration of drug in plasma', '[]'::jsonb, 'Vd is the amount of drug in the body divided by its plasma concentration: the volume that would be needed to hold all the drug at the plasma concentration. It is an apparent volume, not an anatomical one, and it is used to calculate loading doses.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.014 Q1, Drug Transport, Distribution & Bioavailability') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-transport-and-distribution-8f60cb3667', 'pharm-transport-and-distribution', 'mcq', 'If a drug has a very high volume of distribution (e.g. 500 L), it suggests the drug is:', '["Confined to the plasma compartment", "Highly bound to plasma proteins", "Extensively sequestered in peripheral tissues", "Highly water-soluble", "Unable to cross the blood-brain barrier"]'::jsonb, 'Extensively sequestered in peripheral tissues', '[]'::jsonb, 'A Vd far above total body water (about 42 L) means that very little of the drug remains in plasma because it is concentrated in tissues such as fat or muscle, as with chloroquine and digoxin. Strong plasma protein binding does the opposite and keeps Vd small.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.014 Q2, Drug Transport, Distribution & Bioavailability') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-transport-and-distribution-ec04b48008', 'pharm-transport-and-distribution', 'mcq', 'Which plasma protein primarily binds acidic drugs?', '["Alpha-1 acid glycoprotein", "Albumin", "Gamma globulin", "Haemoglobin", "Transcortin"]'::jsonb, 'Albumin', '[]'::jsonb, 'Albumin is the main carrier of acidic drugs such as warfarin, phenytoin, salicylates and sulfonamides. Alpha-1 acid glycoprotein, despite its name, binds mainly basic drugs such as lidocaine, propranolol and quinidine.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.014 Q3, Drug Transport, Distribution & Bioavailability') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-transport-and-distribution-806fa13695', 'pharm-transport-and-distribution', 'mcq', 'Only the "free" (unbound) fraction of a drug is:', '["Pharmacologically active", "Available for metabolism", "Available for excretion", "Able to cross cell membranes", "All of the above"]'::jsonb, 'All of the above', '[]'::jsonb, 'Drug bound to plasma protein is too large to leave the capillaries, so it cannot reach receptors, enter cells, be filtered at the glomerulus or reach metabolising enzymes. The bound fraction acts as a circulating reservoir in equilibrium with free drug.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.014 Q4, Drug Transport, Distribution & Bioavailability') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-1820e30849', 'pharm-drug-interactions', 'mcq', 'Competition between two drugs for the same protein binding site can lead to:', '["Decreased toxicity of both drugs", "Displacement of one drug and a sudden increase in its free concentration", "Increased volume of distribution for both drugs", "Reduced glomerular filtration", "Permanent binding of the drugs to the protein"]'::jsonb, 'Displacement of one drug and a sudden increase in its free concentration', '[]'::jsonb, 'Binding sites on albumin are limited, so a drug with higher affinity or concentration can displace another and briefly raise its free, active concentration. This matters for highly bound drugs with a narrow therapeutic index, such as warfarin displaced by sulfonamides.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.014 Q5, Drug Transport, Distribution & Bioavailability') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-transport-and-distribution-7f6019bbc8', 'pharm-transport-and-distribution', 'mcq', 'The blood-brain barrier is least permeable to:', '["Highly lipid-soluble drugs", "Non-ionized drugs", "Highly ionized or polar drugs", "Oxygen and carbon dioxide", "Ethanol"]'::jsonb, 'Highly ionized or polar drugs', '[]'::jsonb, 'Tight junctions between brain capillary endothelial cells remove the aqueous route, so charged or polar molecules cannot enter unless a carrier exists. Lipid-soluble un-ionised drugs, gases and ethanol diffuse through easily. This is why quaternary ammonium drugs such as neostigmine lack central effects.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.014 Q6, Drug Transport, Distribution & Bioavailability') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-transport-and-distribution-f1596f2d18', 'pharm-transport-and-distribution', 'mcq', 'Redistribution is a phenomenon seen with:', '["Highly water-soluble drugs", "Highly lipid-soluble drugs given intravenously (e.g. thiopental)", "Drugs with very low volume of distribution", "Drugs that are not metabolized", "Sublingual medications"]'::jsonb, 'Highly lipid-soluble drugs given intravenously (e.g. thiopental)', '[]'::jsonb, 'After an intravenous bolus, a very lipid-soluble drug first enters the well-perfused brain and then moves out again into muscle and fat as plasma levels fall. This redistribution, not metabolism, ends the anaesthetic action of thiopental within minutes.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.015 Q7, Drug Transport, Distribution & Bioavailability') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-bioavailability-d9a5d593c7', 'pharm-bioavailability', 'mcq', 'Bioavailability (F) is calculated by comparing the area under the curve (AUC) of an oral dose to the AUC of:', '["A subcutaneous dose", "An intramuscular dose", "An intravenous dose", "A rectal dose", "A topical dose"]'::jsonb, 'An intravenous dose', '[]'::jsonb, 'Absolute bioavailability is AUC(oral) divided by AUC(intravenous) for the same dose, because an intravenous dose is 100% available and serves as the reference. Comparing with another non-intravenous formulation gives only relative bioavailability.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.015 Q8, Drug Transport, Distribution & Bioavailability') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-bioavailability-497412af9f', 'pharm-bioavailability', 'mcq', 'Which factor reduces the bioavailability of an orally administered drug?', '["High lipid solubility", "Chemical instability in gastric acid", "Small molecular size", "Absence of first-pass effect", "Formulation as a solution"]'::jsonb, 'Chemical instability in gastric acid', '[]'::jsonb, 'A drug destroyed by gastric acid, such as benzylpenicillin, never reaches the absorbing surface intact, so less arrives in the circulation. The other options all favour absorption: lipid solubility, small size, no first-pass loss, and a solution that needs no dissolution.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.015 Q9, Drug Transport, Distribution & Bioavailability') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-transport-and-distribution-27ae23863d', 'pharm-transport-and-distribution', 'mcq', 'The amount of a drug in the body is 100 mg and its plasma concentration is 5 mg/L. What is the volume of distribution?', '["0.05 L", "20 L", "500 L", "10 L", "100 L"]'::jsonb, '20 L', '[]'::jsonb, 'Vd equals the amount in the body divided by the plasma concentration: 100 mg divided by 5 mg/L is 20 L. Multiplying instead of dividing gives the wrong answer of 500, and inverting the ratio gives 0.05.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.015 Q10, Drug Transport, Distribution & Bioavailability. Corrected ''concentration of a drug in the body is 100 mg'' to ''amount''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-transport-and-distribution-d26af38f81', 'pharm-transport-and-distribution', 'mcq', 'Basic drugs such as lidocaine primarily bind to:', '["Albumin", "Alpha-1 acid glycoprotein", "Lipoproteins", "Transferrin", "Fetuin"]'::jsonb, 'Alpha-1 acid glycoprotein', '[]'::jsonb, 'Alpha-1 acid glycoprotein is the main plasma binding protein for basic drugs such as lidocaine, propranolol and quinidine. It is an acute-phase protein, so its level rises in inflammation and after myocardial infarction, lowering the free fraction. Albumin mainly binds acidic drugs.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.015 Q11, Drug Transport, Distribution & Bioavailability') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-transport-and-distribution-cc418ce1d3', 'pharm-transport-and-distribution', 'mcq', 'The "apparent" volume of distribution can exceed total body water because:', '["The drug is highly concentrated in the blood", "The drug is bound to tissue components outside the plasma", "The drug is rapidly excreted by the lungs", "The drug is poorly absorbed", "The drug is a prodrug"]'::jsonb, 'The drug is bound to tissue components outside the plasma', '[]'::jsonb, 'Vd is calculated from the plasma concentration. When a drug binds avidly to tissue proteins or dissolves in fat, the plasma concentration is very low, so the calculated volume becomes huge, sometimes thousands of litres. It is a proportionality constant, not a real space.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.015 Q12, Drug Transport, Distribution & Bioavailability') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-transport-and-distribution-174f77e6e2', 'pharm-transport-and-distribution', 'mcq', 'Which organs receive the highest drug delivery initially because of their high blood flow?', '["Fat", "Skin", "Skeletal muscle", "Brain and kidneys", "Bone"]'::jsonb, 'Brain and kidneys', '[]'::jsonb, 'Early distribution is governed by perfusion. The vessel-rich organs (brain, heart, liver, kidneys) receive most of the cardiac output and so equilibrate first. Muscle and skin follow, and poorly perfused fat and bone take up drug slowly, even though fat may eventually store a lot.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.016 Q13, Drug Transport, Distribution & Bioavailability') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-5c3cf50f62', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Drug distribution to the foetus is limited by:', '["The placental barrier", "Low foetal blood pressure", "High foetal gastric pH", "Lack of foetal plasma proteins", "The umbilical cord length"]'::jsonb, 'The placental barrier', '[]'::jsonb, 'The placenta behaves as a lipid membrane with some efflux transporters and enzymes, so lipid-soluble, un-ionised, small drugs cross easily while large or highly ionised ones such as heparin do not. It is only a partial barrier: most drugs given to the mother reach the foetus to some degree.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.016 Q14, Drug Transport, Distribution & Bioavailability. Removed the explanatory hint from the answer option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-effects-of-disease-on-drug-disposition-42fee9669a', 'pharm-effects-of-disease-on-drug-disposition', 'mcq', 'A decrease in plasma albumin (as in liver disease) would most likely:', '["Decrease the free concentration of phenytoin", "Increase the free concentration of phenytoin", "Have no effect on drug action", "Decrease the volume of distribution of the drug", "Increase the half-life of all basic drugs"]'::jsonb, 'Increase the free concentration of phenytoin', '[]'::jsonb, 'Phenytoin is about 90% bound to albumin. With less albumin a larger fraction is unbound, so the patient may show toxicity at a total plasma concentration that looks normal; total levels must be interpreted with the albumin level in mind.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.016 Q15, Drug Transport, Distribution & Bioavailability. Removed hints from options.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biotransformation-6e85b2113f', 'pharm-biotransformation', 'mcq', 'The primary site of drug metabolism in the human body is the:', '["Kidneys", "Lungs", "Liver", "Intestines", "Skin"]'::jsonb, 'Liver', '[]'::jsonb, 'Hepatocytes contain the highest concentration of drug-metabolising enzymes, both cytochrome P450 and conjugating enzymes, and receive all the portal blood from the gut. The gut wall, kidney, lung and plasma contribute, but to a much smaller extent.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.016 Q1, Biotransformation (Metabolism)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biotransformation-6514da0ea7', 'pharm-biotransformation', 'mcq', 'Phase I reactions include all of the following EXCEPT:', '["Oxidation", "Reduction", "Hydrolysis", "Glucuronidation", "Deamination"]'::jsonb, 'Glucuronidation', '[]'::jsonb, 'Phase I reactions introduce or unmask a functional group by oxidation (including deamination and hydroxylation), reduction or hydrolysis. Glucuronidation is a phase II reaction, in which an endogenous molecule is conjugated to the drug to make it more water-soluble.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.016 Q2, Biotransformation (Metabolism)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biotransformation-ac80495057', 'pharm-biotransformation', 'mcq', 'The most common Phase II conjugation reaction is:', '["Acetylation", "Methylation", "Glucuronidation", "Sulfation", "Glutathione conjugation"]'::jsonb, 'Glucuronidation', '[]'::jsonb, 'Glucuronidation, catalysed by UDP-glucuronosyltransferases in the endoplasmic reticulum, handles the widest range of drugs, including morphine, paracetamol and chloramphenicol. It is immature in the newborn, which explains grey baby syndrome with chloramphenicol.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.016 Q3, Biotransformation (Metabolism)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biotransformation-aa00ee371c', 'pharm-biotransformation', 'mcq', 'Cytochrome P450 enzymes are primarily located in the:', '["Mitochondria", "Smooth endoplasmic reticulum (microsomes)", "Nucleus", "Lysosomes", "Cytosol"]'::jsonb, 'Smooth endoplasmic reticulum (microsomes)', '[]'::jsonb, 'The CYP450 mixed-function oxidases are embedded in the membrane of the smooth endoplasmic reticulum of hepatocytes; when cells are homogenised these membranes form vesicles called microsomes, hence ''microsomal enzymes''. Cytosolic and mitochondrial enzymes such as alcohol dehydrogenase and MAO are non-microsomal.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.017 Q4, Biotransformation (Metabolism)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biotransformation-fc503a3fab', 'pharm-biotransformation', 'mcq', 'Which of the following is a potent inducer of cytochrome P450 enzymes?', '["Cimetidine", "Rifampicin", "Ketoconazole", "Erythromycin", "Grapefruit juice"]'::jsonb, 'Rifampicin', '[]'::jsonb, 'Rifampicin strongly induces CYP3A4 and other isoforms, speeding the metabolism of oral contraceptives, warfarin and many antiretrovirals. All the other options are enzyme inhibitors, which raise the levels of co-administered drugs.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.017 Q5, Biotransformation (Metabolism)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biotransformation-095afb0529', 'pharm-biotransformation', 'mcq', 'Enzyme induction usually leads to:', '["Increased plasma levels of the co-administered drug", "Decreased pharmacological effect of the co-administered drug", "Increased half-life of the drug", "Decreased rate of metabolism", "Reduced toxicity of prodrugs"]'::jsonb, 'Decreased pharmacological effect of the co-administered drug', '[]'::jsonb, 'An inducer increases the synthesis of metabolising enzymes, so a co-administered drug is cleared faster, its plasma level and half-life fall and its effect is reduced: for example contraceptive failure with rifampicin. Prodrugs and drugs with toxic metabolites may become more, not less, toxic.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.017 Q6, Biotransformation (Metabolism)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biotransformation-f871ee5f4e', 'pharm-biotransformation', 'mcq', 'Phase II reactions generally result in products that are:', '["More lipid-soluble", "More pharmacologically active", "Highly polar and easily excreted", "Less water-soluble", "Bound more tightly to proteins"]'::jsonb, 'Highly polar and easily excreted', '[]'::jsonb, 'Conjugation with glucuronic acid, sulfate or glycine adds a large polar group, giving a water-soluble and usually inactive product that is readily excreted in urine or bile. Morphine-6-glucuronide is a notable exception that remains active.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.017 Q7, Biotransformation (Metabolism)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biotransformation-9d73355228', 'pharm-biotransformation', 'mcq', 'Which enzyme is responsible for the metabolism of alcohol (ethanol)?', '["Monoamine oxidase", "Alcohol dehydrogenase", "Xanthine oxidase", "Carbonic anhydrase", "Pseudocholinesterase"]'::jsonb, 'Alcohol dehydrogenase', '[]'::jsonb, 'Cytosolic alcohol dehydrogenase oxidises ethanol to acetaldehyde, which aldehyde dehydrogenase then converts to acetate. The enzyme saturates at low concentrations, giving zero-order kinetics. Fomepizole inhibits it, which is used in methanol and ethylene glycol poisoning.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.017 Q8, Biotransformation (Metabolism)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biotransformation-6c40584b65', 'pharm-biotransformation', 'mcq', 'The term "non-microsomal enzymes" refers to enzymes found in:', '["Smooth endoplasmic reticulum", "Cytoplasm and mitochondria", "Only the liver", "Only the kidneys", "Red blood cells only"]'::jsonb, 'Cytoplasm and mitochondria', '[]'::jsonb, 'Non-microsomal enzymes are those outside the endoplasmic reticulum: in the cytosol (alcohol dehydrogenase, xanthine oxidase), mitochondria (monoamine oxidase) and plasma (esterases). Unlike microsomal CYP450 enzymes they are generally not inducible.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.017 Q9, Biotransformation (Metabolism)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-genetic-medicine-d3eb390b68', 'pharm-genetic-medicine', 'mcq', 'A patient who is a "slow acetylator" is at higher risk of toxicity from:', '["Penicillin", "Isoniazid", "Digoxin", "Paracetamol", "Gentamicin"]'::jsonb, 'Isoniazid', '[]'::jsonb, 'Isoniazid is inactivated by N-acetyltransferase 2, which shows genetic polymorphism. Slow acetylators have higher drug levels and are more prone to peripheral neuropathy (prevented with pyridoxine). Hydralazine, procainamide, dapsone and sulfonamides are handled the same way.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.018 Q10, Biotransformation (Metabolism)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-0266d5e16f', 'pharm-drug-interactions', 'mcq', 'Grapefruit juice inhibits CYP3A4, which can lead to:', '["Decreased bioavailability of drugs like felodipine", "Increased toxicity of drugs metabolized by CYP3A4", "Faster excretion of drugs", "Failure of oral contraceptives", "Reduced absorption of iron"]'::jsonb, 'Increased toxicity of drugs metabolized by CYP3A4', '[]'::jsonb, 'Furanocoumarins in grapefruit juice irreversibly inhibit CYP3A4 in the gut wall, reducing first-pass metabolism. Bioavailability of substrates such as felodipine, simvastatin and ciclosporin therefore rises, not falls, with a risk of toxicity. Contraceptive failure is a feature of inducers.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.018 Q11, Biotransformation (Metabolism)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biotransformation-a877fc09b2', 'pharm-biotransformation', 'mcq', 'First-pass metabolism occurs primarily in the:', '["Kidney and bladder", "Gut wall and liver", "Lungs and heart", "Spleen and pancreas", "Brain and spinal cord"]'::jsonb, 'Gut wall and liver', '[]'::jsonb, 'A swallowed drug meets CYP3A4 and conjugating enzymes in the enterocytes and then travels in the portal vein to the liver before reaching the systemic circulation. Loss at these two sites is first-pass (presystemic) metabolism; it is large for propranolol, morphine and glyceryl trinitrate.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.018 Q12, Biotransformation (Metabolism)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biotransformation-85496d94e2', 'pharm-biotransformation', 'mcq', 'Which of the following is an example of a Phase I oxidation reaction?', '["Hydrolysis of esters", "Hydroxylation", "Acetylation of sulfonamides", "Glucuronidation of morphine", "Glycine conjugation"]'::jsonb, 'Hydroxylation', '[]'::jsonb, 'Hydroxylation, the insertion of an oxygen atom into the drug by CYP450, is the classic phase I oxidation, as with phenytoin. Ester hydrolysis is phase I but is not an oxidation, and the remaining options are phase II conjugations.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.018 Q13, Biotransformation (Metabolism)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biotransformation-26a41fd24b', 'pharm-biotransformation', 'mcq', 'The goal of biotransformation is generally to make drugs:', '["More toxic", "More lipid-soluble for reabsorption", "More polar for excretion", "More likely to cross the blood-brain barrier", "Larger in molecular size"]'::jsonb, 'More polar for excretion', '[]'::jsonb, 'Lipid-soluble drugs filtered by the kidney are reabsorbed from the tubule and would persist for a long time. Metabolism converts them into polar, water-soluble products that stay in the tubular fluid or bile and are excreted. Most metabolites are also less active.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.018 Q14, Biotransformation (Metabolism)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-acetaminophen-acetylsalicylic-acid-poi-3e639619c8', 'pharm-acetaminophen-acetylsalicylic-acid-poisoning', 'mcq', 'Paracetamol toxicity is caused by the depletion of:', '["Glucuronic acid", "Sulfate", "Glutathione", "Acetyl-CoA", "NADPH"]'::jsonb, 'Glutathione', '[]'::jsonb, 'A small fraction of paracetamol is oxidised by CYP2E1 to the reactive metabolite NAPQI, which is normally detoxified by glutathione. In overdose glutathione stores run out and NAPQI binds to hepatocyte proteins, causing centrilobular necrosis. N-acetylcysteine replenishes glutathione.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.018 Q15, Biotransformation (Metabolism)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-excretion-3dbcfc7b4e', 'pharm-excretion', 'mcq', 'The three processes involved in renal drug excretion are:', '["Filtration, absorption, secretion", "Glomerular filtration, tubular reabsorption, active tubular secretion", "Filtration, metabolism, defecation", "Digestion, absorption, excretion", "Diffusion, osmosis, filtration"]'::jsonb, 'Glomerular filtration, tubular reabsorption, active tubular secretion', '[]'::jsonb, 'The amount of drug in urine equals what is filtered at the glomerulus, plus what is actively secreted in the proximal tubule, minus what is passively reabsorbed along the tubule. Changing urine pH alters the reabsorption step.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.019 Q1, Drug Excretion') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-excretion-8277fadb96', 'pharm-excretion', 'mcq', 'Glomerular filtration of a drug is dependent on:', '["Lipid solubility", "Plasma protein binding", "Degree of ionization", "Presence of transport carriers", "Use of ATP"]'::jsonb, 'Plasma protein binding', '[]'::jsonb, 'The glomerulus is a size filter: any free drug molecule below about 20 kDa passes regardless of charge or lipid solubility, but albumin and anything bound to it are held back. Lipid solubility and ionisation instead govern tubular reabsorption.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.019 Q2, Drug Excretion. Removed hint from the answer option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-excretion-e1f7aa773e', 'pharm-excretion', 'mcq', 'Alkalinization of urine with sodium bicarbonate increases the excretion of:', '["Weakly basic drugs (e.g. amphetamine)", "Weakly acidic drugs (e.g. aspirin)", "Neutral drugs", "Highly lipid-soluble drugs", "All drugs equally"]'::jsonb, 'Weakly acidic drugs (e.g. aspirin)', '[]'::jsonb, 'In alkaline urine a weak acid is ionised, so it cannot diffuse back across the tubule and is trapped and excreted. This is used in salicylate and phenobarbital poisoning. Weak bases behave the opposite way and are excreted faster in acid urine.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.019 Q3, Drug Excretion') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-excretion-c159c1c729', 'pharm-excretion', 'mcq', '"Enterohepatic circulation" refers to:', '["Drugs moving from the heart to the liver", "Drugs excreted in bile being reabsorbed from the intestine into the portal blood", "Drugs moving from the kidney to the liver", "Secretion of drugs into the saliva", "Metabolism of drugs in the stomach"]'::jsonb, 'Drugs excreted in bile being reabsorbed from the intestine into the portal blood', '[]'::jsonb, 'Drug conjugates secreted in bile can be hydrolysed by gut bacteria, releasing the parent drug, which is reabsorbed and returned to the liver. The cycle prolongs the action of drugs such as ethinylestradiol, morphine and digitoxin.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.019 Q4, Drug Excretion') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-excretion-70b9ed70f5', 'pharm-excretion', 'mcq', 'Which of the following are excreted to a significant extent through the lungs?', '["Penicillin", "Ethanol and general anaesthetic gases", "Digoxin", "Aspirin", "Lithium"]'::jsonb, 'Ethanol and general anaesthetic gases', '[]'::jsonb, 'Volatile substances leave the blood across the alveoli: inhalational anaesthetics are eliminated mainly this way, and a small but measurable fraction of ethanol is exhaled, which is the basis of the breath test. The other drugs are cleared by the kidney.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.019 Q5, Drug Excretion. Stem reworded slightly: ethanol is mainly metabolised, only partly exhaled.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-excretion-1c3d25a01c', 'pharm-excretion', 'mcq', 'Active tubular secretion occurs primarily in the:', '["Glomerulus", "Proximal tubule", "Loop of Henle", "Distal tubule", "Collecting duct"]'::jsonb, 'Proximal tubule', '[]'::jsonb, 'Proximal tubule cells carry organic anion transporters (for penicillins, salicylates, diuretics) and organic cation transporters (for metformin, cimetidine) that pump drugs from blood into the lumen. Secretion can clear even protein-bound drug. The glomerulus only filters.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.019 Q6, Drug Excretion') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-957c75f8a5', 'pharm-drug-interactions', 'mcq', 'Probenecid decreases the renal excretion of penicillin by:', '["Inhibiting glomerular filtration", "Competing for the organic acid transport system in the proximal tubule", "Increasing tubular reabsorption", "Changing the pH of the urine", "Binding to the penicillin molecule"]'::jsonb, 'Competing for the organic acid transport system in the proximal tubule', '[]'::jsonb, 'Penicillin is cleared mainly by active secretion through the organic anion transporter in the proximal tubule. Probenecid competes for the same carrier, so penicillin levels are higher and last longer. Filtration is not affected.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.020 Q7, Drug Excretion') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacokinetics-10a9352d73', 'pharm-introduction-to-pharmacokinetics', 'mcq', 'Total body clearance (CL) is the:', '["Amount of drug excreted per unit time", "Volume of plasma cleared of drug per unit time", "Rate of drug metabolism in the liver", "Time taken for the concentration to drop by 50%", "Ratio of dose to volume of distribution"]'::jsonb, 'Volume of plasma cleared of drug per unit time', '[]'::jsonb, 'Clearance is expressed as a volume per unit time (mL/min or L/h): the volume of plasma from which the drug is completely removed each minute. The amount removed per unit time is the elimination rate, which equals clearance multiplied by plasma concentration.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.020 Q8, Drug Excretion') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacokinetics-c349e04a52', 'pharm-introduction-to-pharmacokinetics', 'mcq', 'In zero-order elimination kinetics:', '["A constant fraction of drug is eliminated per unit time", "The rate of elimination is proportional to the concentration", "A constant amount of drug is eliminated per unit time", "The half-life is constant", "It is the most common form of elimination"]'::jsonb, 'A constant amount of drug is eliminated per unit time', '[]'::jsonb, 'When the eliminating enzymes or carriers are saturated, the same amount of drug is removed per hour whatever the concentration, so the half-life is not constant. Ethanol, and phenytoin and aspirin at high doses, behave this way. A constant fraction describes first-order kinetics.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.020 Q9, Drug Excretion') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacokinetics-2e56318627', 'pharm-introduction-to-pharmacokinetics', 'mcq', 'Most drugs follow first-order kinetics, which means:', '["Half-life increases as concentration increases", "A constant amount is removed every hour", "Elimination rate is proportional to the plasma concentration", "Clearance is always zero", "Enzymes are saturated"]'::jsonb, 'Elimination rate is proportional to the plasma concentration', '[]'::jsonb, 'In first-order kinetics a constant fraction of the drug is eliminated per unit time, so the rate rises and falls with the concentration and the half-life stays constant. Removal of a constant amount with saturated enzymes describes zero-order kinetics.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.020 Q10, Drug Excretion') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacokinetics-c3085945dd', 'pharm-introduction-to-pharmacokinetics', 'mcq', 'Which of the following drugs follows zero-order kinetics at high or toxic doses?', '["Penicillin", "Phenytoin", "Digoxin", "Morphine", "Atropine"]'::jsonb, 'Phenytoin', '[]'::jsonb, 'Phenytoin''s hepatic hydroxylation saturates within the therapeutic range, so a small dose increase can produce a disproportionate rise in plasma level and toxicity. Ethanol and high-dose salicylate are the other classic examples of saturation kinetics.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.020 Q11, Drug Excretion') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-excretion-b0d815a86a', 'pharm-excretion', 'mcq', 'Acidification of urine (using ammonium chloride) would increase the elimination of which of the following in overdose?', '["Phenobarbital", "Salicylates", "Amphetamines", "Penicillin", "Warfarin"]'::jsonb, 'Amphetamines', '[]'::jsonb, 'Amphetamine is a weak base, so in acid urine it is ionised, trapped in the tubule and excreted faster. Phenobarbital and salicylates are weak acids whose excretion is increased by alkaline urine. Acid diuresis is rarely used today because of its risks.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.020 Q12, Drug Excretion') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-excretion-b8e5ac9d18', 'pharm-excretion', 'mcq', 'Drugs with a molecular weight greater than about 300 Da are often excreted via:', '["Sweat", "Tears", "Bile", "Exhalation", "Sebum"]'::jsonb, 'Bile', '[]'::jsonb, 'Biliary excretion favours larger polar molecules, typically above 300 to 500 Da, especially glucuronide conjugates, which are actively transported into bile. Examples are rifampicin and ceftriaxone. Smaller molecules are mostly excreted in urine.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.020 Q13, Drug Excretion') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-excretion-8409f2f513', 'pharm-excretion', 'mcq', 'If the renal clearance of a drug is greater than the glomerular filtration rate (125 mL/min), it indicates:', '["The drug is being reabsorbed", "The drug is highly protein-bound", "The drug is undergoing active tubular secretion", "The drug is being metabolized in the kidney", "The drug is not filtered"]'::jsonb, 'The drug is undergoing active tubular secretion', '[]'::jsonb, 'Filtration alone can clear at most the GFR. A higher renal clearance means the tubules are adding drug to the urine by active secretion, as with penicillin and para-aminohippurate. A renal clearance below the GFR suggests reabsorption or protein binding.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.021 Q14, Drug Excretion') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-effects-of-disease-on-drug-disposition-8e3452cacb', 'pharm-effects-of-disease-on-drug-disposition', 'mcq', 'Creatinine clearance is used as a clinical marker for:', '["Liver function", "Heart rate", "Glomerular filtration rate", "Drug half-life", "Bioavailability"]'::jsonb, 'Glomerular filtration rate', '[]'::jsonb, 'Creatinine is produced at a steady rate, freely filtered and only slightly secreted, so its clearance approximates the GFR. It is used to adjust the doses of renally excreted drugs such as aminoglycosides and digoxin.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.021 Q15, Drug Excretion. Removed hint ''(Renal function)'' from the answer option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adverse-drug-reactions-b100c92e73', 'pharm-adverse-drug-reactions', 'mcq', 'A "Type A" (augmented) adverse drug reaction is characterized by being:', '["Unpredictable and rare", "Related to the known pharmacological action of the drug", "Independent of dose", "Related to genetic abnormalities only", "Associated with carcinogenesis"]'::jsonb, 'Related to the known pharmacological action of the drug', '[]'::jsonb, 'Type A reactions are an exaggeration of the drug''s normal pharmacology: they are common, dose-dependent, predictable and usually managed by reducing the dose, for example bleeding with warfarin. Unpredictable, dose-independent reactions are Type B.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.021 Q1, Adverse Drug Reactions (ADRs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adverse-drug-reactions-8bb47cacca', 'pharm-adverse-drug-reactions', 'mcq', 'An "idiosyncratic" reaction is:', '["An expected side effect", "A genetically determined abnormal reactivity to a drug", "A reaction occurring only after chronic use", "An allergic reaction mediated by IgE", "A result of drug-drug interactions"]'::jsonb, 'A genetically determined abnormal reactivity to a drug', '[]'::jsonb, 'Idiosyncrasy is an unusual, qualitatively abnormal response seen in a few individuals, usually because of an inherited enzyme difference, such as haemolysis with primaquine in G6PD deficiency. It is not immune-mediated, which distinguishes it from allergy.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.021 Q2, Adverse Drug Reactions (ADRs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adverse-drug-reactions-7a66d73f72', 'pharm-adverse-drug-reactions', 'mcq', 'Which of the following is a Type B (bizarre) reaction?', '["Bradycardia from propranolol", "Hypoglycaemia from insulin", "Anaphylaxis from penicillin", "Mouth dryness from atropine", "Postural hypotension from prazosin"]'::jsonb, 'Anaphylaxis from penicillin', '[]'::jsonb, 'Type B reactions cannot be predicted from the drug''s pharmacology, are not dose-related and are often immunological; penicillin anaphylaxis is the classic example. The other options are all extensions of the drugs'' known actions, so they are Type A.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.021 Q3, Adverse Drug Reactions (ADRs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-c64b5d3932', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Teratogenicity refers to drug-induced damage to:', '["The liver", "The kidney", "The foetus in utero", "The elderly", "Nerve endings"]'::jsonb, 'The foetus in utero', '[]'::jsonb, 'A teratogen causes structural or functional abnormalities in the developing embryo or foetus, with the highest risk during organogenesis (weeks 3 to 8). Examples include thalidomide, isotretinoin, warfarin and valproate.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.021 Q4, Adverse Drug Reactions (ADRs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adverse-drug-reactions-02772e78a8', 'pharm-adverse-drug-reactions', 'mcq', 'Type I hypersensitivity reactions are mediated by:', '["IgG", "IgM", "IgE", "T-lymphocytes", "Complement system"]'::jsonb, 'IgE', '[]'::jsonb, 'In Type I (immediate) hypersensitivity, drug antigen cross-links IgE on mast cells and basophils, releasing histamine and other mediators and causing urticaria, bronchospasm or anaphylaxis. T-lymphocytes mediate Type IV (delayed) reactions such as contact dermatitis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.022 Q5, Adverse Drug Reactions (ADRs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paediatric-clinical-pharmacology-06671ba674', 'pharm-paediatric-clinical-pharmacology', 'mcq', 'The "grey baby syndrome" is a serious adverse drug reaction associated with:', '["Tetracycline", "Chloramphenicol", "Sulfonamides", "Penicillin", "Gentamicin"]'::jsonb, 'Chloramphenicol', '[]'::jsonb, 'Neonates have immature glucuronyl transferase and poor renal excretion, so chloramphenicol accumulates and causes vomiting, hypothermia, ashen-grey cyanosis and circulatory collapse. Sulfonamides in the newborn cause a different problem, kernicterus, by displacing bilirubin.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.022 Q6, Adverse Drug Reactions (ADRs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-978aceef77', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Phocomelia (seal-like limbs) was a tragic adverse drug reaction caused by:', '["Aspirin", "Thalidomide", "Warfarin", "Phenytoin", "Alcohol"]'::jsonb, 'Thalidomide', '[]'::jsonb, 'Thalidomide, given for morning sickness around 1960, caused shortened or absent limbs in thousands of babies when taken in early pregnancy. The disaster led to modern requirements for reproductive toxicity testing. Warfarin and phenytoin are teratogens with different patterns.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.022 Q7, Adverse Drug Reactions (ADRs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adverse-drug-reactions-33ed4080dd', 'pharm-adverse-drug-reactions', 'mcq', 'Tachyphylaxis is defined as:', '["Slow development of tolerance", "Rapidly developing tolerance after a few doses", "Increased sensitivity to a drug", "An allergic skin rash", "Drug-induced rapid heart rate"]'::jsonb, 'Rapidly developing tolerance after a few doses', '[]'::jsonb, 'Tachyphylaxis is a rapid loss of response after doses repeated at short intervals, as with ephedrine or tyramine (transmitter stores are depleted) and nitrates. Ordinary tolerance develops gradually over days to weeks.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.022 Q8, Adverse Drug Reactions (ADRs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adverse-drug-reactions-0ec97e610c', 'pharm-adverse-drug-reactions', 'mcq', 'Which term describes a reaction in which a drug causes the very condition it is intended to treat?', '["Paradoxical reaction", "Synergism", "Antagonism", "Side effect", "Iatrogenic disease"]'::jsonb, 'Paradoxical reaction', '[]'::jsonb, 'A paradoxical reaction is the opposite of the expected effect, for example bronchospasm after a bronchodilator inhaler or agitation after a benzodiazepine. Iatrogenic disease is broader: any illness caused by medical treatment.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.022 Q9, Adverse Drug Reactions (ADRs). Corrected ''Latrogenic'' to ''Iatrogenic''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adverse-drug-reactions-7cc644eaac', 'pharm-adverse-drug-reactions', 'mcq', 'Photosensitivity is a common side effect of which antibiotic class?', '["Penicillins", "Macrolides", "Tetracyclines", "Aminoglycosides", "Cephalosporins"]'::jsonb, 'Tetracyclines', '[]'::jsonb, 'Tetracyclines, especially doxycycline and demeclocycline, absorb ultraviolet light in the skin and cause an exaggerated sunburn reaction. Fluoroquinolones and sulfonamides do the same. Aminoglycosides are known instead for kidney and ear toxicity.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.022 Q10, Adverse Drug Reactions (ADRs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adverse-drug-reactions-e0c67663aa', 'pharm-adverse-drug-reactions', 'mcq', 'Type D adverse drug reactions are:', '["Dose-related", "Delayed (e.g. carcinogenesis or teratogenesis)", "Due to withdrawal", "Due to treatment failure", "Immediate hypersensitivity"]'::jsonb, 'Delayed (e.g. carcinogenesis or teratogenesis)', '[]'::jsonb, 'In the extended ABCDEF classification: A augmented (dose-related), B bizarre, C chronic, D delayed, E end of use (withdrawal) and F failure of therapy. Type D reactions appear long after exposure, such as secondary cancers after alkylating agents.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.023 Q11, Adverse Drug Reactions (ADRs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adverse-drug-reactions-4608e33ee9', 'pharm-adverse-drug-reactions', 'mcq', 'Stevens-Johnson syndrome is a severe drug reaction that mainly affects the:', '["Liver", "Kidneys", "Skin and mucous membranes", "Bone marrow", "Heart"]'::jsonb, 'Skin and mucous membranes', '[]'::jsonb, 'Stevens-Johnson syndrome is an immune-mediated reaction with epidermal necrosis, blistering and mucosal erosions; it lies on the same spectrum as toxic epidermal necrolysis, which involves more than 30% of the skin. Common culprits are sulfonamides, nevirapine, carbamazepine, lamotrigine and allopurinol.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.023 Q12, Adverse Drug Reactions (ADRs). Reworded: the original called SJS ''a severe form of toxic epidermal necrolysis'', which is the wrong way round.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-addiction-and-abuse-addiction-to--798a3b0373', 'pharm-drug-addiction-and-abuse-addiction-to-cannabinoids-inhalants', 'mcq', 'Drug dependence characterized by a physical withdrawal syndrome is called:', '["Psychological dependence", "Addiction", "Physical dependence", "Habituation", "Tolerance"]'::jsonb, 'Physical dependence', '[]'::jsonb, 'Physical dependence is an adapted state in which stopping the drug produces a characteristic withdrawal syndrome, as with opioids, alcohol and benzodiazepines. Psychological dependence is craving and compulsive use without necessarily any physical withdrawal signs.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.023 Q13, Adverse Drug Reactions (ADRs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-development-stages-regulations-go-43b0a81e41', 'pharm-drug-development-stages-regulations-governing-development-of-new', 'mcq', 'Carcinogenicity testing of a new drug is usually conducted in:', '["Phase I clinical trials", "Healthy human volunteers", "Laboratory animals over long periods", "In vitro cell cultures only", "Phase IV monitoring only"]'::jsonb, 'Laboratory animals over long periods', '[]'::jsonb, 'Carcinogenicity is assessed preclinically by giving the drug to rodents for most of their lifespan (about two years) and examining them for tumours, supported by in vitro mutagenicity tests such as the Ames test. It would be unethical and impractical to test this in volunteers.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.023 Q14, Adverse Drug Reactions (ADRs)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adverse-drug-reactions-4a6370bdf0', 'pharm-adverse-drug-reactions', 'mcq', 'Analgesic nephropathy after years of analgesic use is an example of which type of adverse drug reaction?', '["Type A (augmented)", "Type B (bizarre)", "Type C (chronic)", "Type D (delayed)", "Type E (end of use)"]'::jsonb, 'Type C (chronic)', '[]'::jsonb, 'Type C reactions result from long-term cumulative exposure; analgesic nephropathy and adrenal suppression from prolonged corticosteroids are examples. Type D reactions are delayed effects such as cancer or teratogenesis that appear some time after exposure.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.023 Q15, Adverse Drug Reactions (ADRs). Reworded: the original stem named the kidney condition and then asked which organ, giving the answer away.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-receptors-and-signal-transduction-mech-a608c4fb0e', 'pharm-receptors-and-signal-transduction-mechanisms', 'mcq', 'Which of the following is an example of a ligand-gated ion channel (ionotropic receptor)?', '["Nicotinic acetylcholine receptor", "Muscarinic acetylcholine receptor", "Beta-adrenoceptor", "Insulin receptor", "Oestrogen receptor"]'::jsonb, 'Nicotinic acetylcholine receptor', '[]'::jsonb, 'The nicotinic receptor is a pentameric channel that opens when acetylcholine binds, letting cations through within milliseconds. Muscarinic receptors and beta-adrenoceptors are G-protein coupled, the insulin receptor is a tyrosine kinase, and the oestrogen receptor is nuclear.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.023 Q1, Receptors and Signal Transduction') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-receptors-and-signal-transduction-mech-15aa5c4b26', 'pharm-receptors-and-signal-transduction-mechanisms', 'mcq', 'G-protein coupled receptors (GPCRs) are also known as:', '["Metabotropic receptors", "Ionotropic receptors", "Nuclear receptors", "Kinase-linked receptors", "Voltage-gated channels"]'::jsonb, 'Metabotropic receptors', '[]'::jsonb, 'GPCRs are called metabotropic (or seven-transmembrane) receptors because they act through G-proteins and second messengers to change cell metabolism, rather than opening an ion pore directly. Ionotropic receptors are the ligand-gated ion channels.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.024 Q2, Receptors and Signal Transduction') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-receptors-and-signal-transduction-mech-1cdcfb56d3', 'pharm-receptors-and-signal-transduction-mechanisms', 'mcq', 'The time scale for cellular effects mediated by intracellular (nuclear) receptors is typically:', '["Milliseconds", "Seconds", "Minutes", "Hours to days", "Microseconds"]'::jsonb, 'Hours to days', '[]'::jsonb, 'Nuclear receptors alter gene transcription, so the effect has to wait for new mRNA and protein to be made; this takes hours and persists after the drug has gone. Ion channels act in milliseconds, GPCRs in seconds and kinase-linked receptors in minutes to hours.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.024 Q3, Receptors and Signal Transduction') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-receptors-and-signal-transduction-mech-7b39a64f17', 'pharm-receptors-and-signal-transduction-mechanisms', 'mcq', 'Which receptor type possesses intrinsic tyrosine kinase activity?', '["GABA-A receptor", "Insulin receptor", "Alpha-1 receptor", "Opioid receptor", "Glucocorticoid receptor"]'::jsonb, 'Insulin receptor', '[]'::jsonb, 'Insulin binding makes the receptor''s intracellular beta subunits phosphorylate each other on tyrosine residues and then phosphorylate insulin receptor substrates. Growth factor receptors (EGF, PDGF) work the same way. GABA-A is an ion channel, and alpha-1 and opioid receptors are GPCRs.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.024 Q4, Receptors and Signal Transduction') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-agonists-and-antagonists-ac7f696ede', 'pharm-drug-agonists-and-antagonists', 'mcq', 'A molecule that binds to a receptor but produces no response on its own is called an:', '["Agonist", "Partial agonist", "Antagonist", "Inverse agonist", "Allosteric modulator"]'::jsonb, 'Antagonist', '[]'::jsonb, 'An antagonist has affinity for the receptor but no efficacy: it occupies the site and blocks agonists without activating anything itself. An inverse agonist differs because it does produce an effect, reducing the receptor''s basal activity.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.024 Q5, Receptors and Signal Transduction') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-g-proteins-and-second-messengers-7ae8d694a8', 'pharm-g-proteins-and-second-messengers', 'mcq', 'The "second messenger" concept is most closely associated with which receptor family?', '["Type 1 (ion channels)", "Type 2 (GPCRs)", "Type 3 (enzyme-linked)", "Type 4 (nuclear)", "Cytoplasmic enzymes"]'::jsonb, 'Type 2 (GPCRs)', '[]'::jsonb, 'GPCRs pass the signal through a G-protein to an effector enzyme that generates second messengers such as cAMP, IP3, DAG and calcium inside the cell. Ion channel receptors change membrane potential directly, and nuclear receptors act on DNA.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.024 Q6, Receptors and Signal Transduction') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-receptors-and-signal-transduction-mech-f7cc83aaf9', 'pharm-receptors-and-signal-transduction-mechanisms', 'mcq', 'Down-regulation of receptors occurs due to:', '["Chronic exposure to an antagonist", "Chronic exposure to an agonist", "Acute withdrawal of a drug", "Presence of an inverse agonist", "Low drug concentration"]'::jsonb, 'Chronic exposure to an agonist', '[]'::jsonb, 'Continuous stimulation leads the cell to internalise and degrade receptors, reducing their number and the response; this contributes to tolerance, as with beta-2 agonists. Chronic antagonist exposure does the opposite, causing up-regulation and supersensitivity.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.024 Q7, Receptors and Signal Transduction') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-receptors-and-signal-transduction-mech-8bf2e42b3a', 'pharm-receptors-and-signal-transduction-mechanisms', 'mcq', 'Which of the following binds to intracellular receptors?', '["Adrenaline", "Acetylcholine", "Steroid hormones (e.g. cortisol)", "Histamine", "Dopamine"]'::jsonb, 'Steroid hormones (e.g. cortisol)', '[]'::jsonb, 'Steroid hormones are lipid-soluble, so they diffuse through the cell membrane and bind receptors in the cytoplasm or nucleus that regulate gene transcription. Adrenaline, acetylcholine, histamine and dopamine are polar and act on cell-surface receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.025 Q8, Receptors and Signal Transduction') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-receptors-and-signal-transduction-mech-f0d4766758', 'pharm-receptors-and-signal-transduction-mechanisms', 'mcq', 'The nicotinic acetylcholine receptor allows the passage of:', '["Chloride ions", "Sodium and potassium ions", "Calcium ions only", "Glucose", "Proteins"]'::jsonb, 'Sodium and potassium ions', '[]'::jsonb, 'The nicotinic receptor is a non-selective cation channel: when it opens, sodium flows in and potassium flows out, and the net inward current depolarises the cell. Chloride channels are opened by GABA-A and glycine receptors, which are inhibitory.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.025 Q9, Receptors and Signal Transduction') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-g-proteins-and-second-messengers-1eb34d79bf', 'pharm-g-proteins-and-second-messengers', 'mcq', 'The alpha subunit of a G-protein is active when it is bound to:', '["GDP", "GTP", "ATP", "cAMP", "Inorganic phosphate"]'::jsonb, 'GTP', '[]'::jsonb, 'Receptor activation makes the alpha subunit release GDP and bind GTP; it then separates from the beta-gamma dimer and acts on its effector. Its own GTPase activity hydrolyses GTP back to GDP, which switches the signal off.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.025 Q10, Receptors and Signal Transduction') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-receptors-and-signal-transduction-mech-25b7ccfd6e', 'pharm-receptors-and-signal-transduction-mechanisms', 'mcq', 'Which receptor type is located in the nucleus or cytoplasm?', '["Adrenoceptors", "Thyroid hormone receptors", "Dopamine receptors", "Serotonin receptors", "H1 receptors"]'::jsonb, 'Thyroid hormone receptors', '[]'::jsonb, 'Thyroid hormone receptors sit in the nucleus bound to DNA and regulate transcription when T3 binds; steroid, vitamin D and retinoid receptors belong to the same superfamily. The other options are all cell-surface receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.025 Q11, Receptors and Signal Transduction') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-agonists-and-antagonists-85f427e346', 'pharm-drug-agonists-and-antagonists', 'mcq', 'The ability of a drug to activate a receptor and produce a physiological response is called:', '["Affinity", "Potency", "Intrinsic activity (efficacy)", "Bioavailability", "Clearance"]'::jsonb, 'Intrinsic activity (efficacy)', '[]'::jsonb, 'Intrinsic activity, or efficacy, is the capacity of the bound drug to activate the receptor: 1 for a full agonist, between 0 and 1 for a partial agonist and 0 for an antagonist. Affinity describes only how readily the drug binds.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.025 Q12, Receptors and Signal Transduction') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-receptors-and-signal-transduction-mech-20e8833daf', 'pharm-receptors-and-signal-transduction-mechanisms', 'mcq', 'Up-regulation of receptors may lead to:', '["Tolerance", "Supersensitivity", "Tachyphylaxis", "Resistance", "Desensitization"]'::jsonb, 'Supersensitivity', '[]'::jsonb, 'Prolonged blockade or denervation increases receptor numbers, so the tissue over-responds when the agonist returns. This explains rebound tachycardia and angina after abrupt beta-blocker withdrawal. Tolerance, tachyphylaxis and desensitisation are all forms of reduced response.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.025 Q13, Receptors and Signal Transduction') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-receptors-and-signal-transduction-mech-a606119d2a', 'pharm-receptors-and-signal-transduction-mechanisms', 'mcq', 'Which receptor family is involved in the fastest neurotransmission?', '["G-protein coupled", "Kinase-linked", "Ligand-gated ion channels", "Nuclear receptors", "Intracellular enzymes"]'::jsonb, 'Ligand-gated ion channels', '[]'::jsonb, 'Ligand-gated ion channels open within milliseconds of transmitter binding, which suits fast synaptic transmission at the neuromuscular junction and at glutamate and GABA-A synapses. GPCRs need seconds because several coupling steps intervene.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.026 Q14, Receptors and Signal Transduction') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-agonists-and-antagonists-03dc05df67', 'pharm-drug-agonists-and-antagonists', 'mcq', 'Receptor "affinity" refers to:', '["The maximum effect a drug can produce", "The strength of the bond between drug and receptor", "The speed of drug metabolism", "The ability to cause a change in cell function", "The number of receptors in a tissue"]'::jsonb, 'The strength of the bond between drug and receptor', '[]'::jsonb, 'Affinity is the tendency of a drug to bind its receptor, expressed by the dissociation constant Kd: the lower the Kd, the higher the affinity. The ability to change cell function once bound is efficacy, a separate property.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.026 Q15, Receptors and Signal Transduction') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-g-proteins-and-second-messengers-8a60ce1819', 'pharm-g-proteins-and-second-messengers', 'mcq', 'Which enzyme is activated by Gs proteins?', '["Phospholipase C", "Adenylyl cyclase", "Phosphodiesterase", "Guanylyl cyclase", "Protein kinase C"]'::jsonb, 'Adenylyl cyclase', '[]'::jsonb, 'The alpha subunit of Gs stimulates adenylyl cyclase, raising cAMP; beta-adrenoceptors, D1 and H2 receptors use this pathway. Phospholipase C is the effector of Gq, used by alpha-1, M1, M3 and H1 receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.026 Q1, G-Proteins and 2nd Messengers') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-g-proteins-and-second-messengers-c9f44d67aa', 'pharm-g-proteins-and-second-messengers', 'mcq', 'The primary function of adenylyl cyclase is to convert ATP into:', '["ADP", "Cyclic AMP (cAMP)", "Cyclic GMP (cGMP)", "Inositol trisphosphate (IP3)", "Diacylglycerol (DAG)"]'::jsonb, 'Cyclic AMP (cAMP)', '[]'::jsonb, 'Adenylyl cyclase is a membrane enzyme that cyclises ATP to cAMP, releasing pyrophosphate. cGMP is made from GTP by guanylyl cyclase, and IP3 and DAG come from membrane phospholipid split by phospholipase C.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.026 Q2, G-Proteins and 2nd Messengers') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-g-proteins-and-second-messengers-d562555b88', 'pharm-g-proteins-and-second-messengers', 'mcq', 'Gq protein activation leads to the stimulation of:', '["Adenylyl cyclase", "Phospholipase C", "cAMP phosphodiesterase", "Potassium channels", "Sodium channels"]'::jsonb, 'Phospholipase C', '[]'::jsonb, 'Gq activates phospholipase C-beta, which splits PIP2 into IP3 and DAG, raising intracellular calcium and activating protein kinase C. Opening of potassium channels is a typical action of Gi, through its beta-gamma subunits.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.026 Q3, G-Proteins and 2nd Messengers') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-g-proteins-and-second-messengers-de54add63f', 'pharm-g-proteins-and-second-messengers', 'mcq', 'The cleavage of phosphatidylinositol 4,5-bisphosphate (PIP2) produces:', '["cAMP and cGMP", "IP3 and DAG", "ATP and magnesium", "Tyrosine and kinase", "Sodium and potassium"]'::jsonb, 'IP3 and DAG', '[]'::jsonb, 'Phospholipase C hydrolyses the membrane phospholipid PIP2 into two messengers: water-soluble IP3, which diffuses into the cytosol to release calcium, and lipid-soluble DAG, which stays in the membrane and activates protein kinase C.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.026 Q4, G-Proteins and 2nd Messengers') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-g-proteins-and-second-messengers-985636c6ca', 'pharm-g-proteins-and-second-messengers', 'mcq', 'What is the main role of IP3 in the cell?', '["Activation of protein kinase A", "Release of calcium from the endoplasmic (sarcoplasmic) reticulum", "Phosphorylation of tyrosine residues", "Inhibition of adenylyl cyclase", "Degradation of cAMP"]'::jsonb, 'Release of calcium from the endoplasmic (sarcoplasmic) reticulum', '[]'::jsonb, 'IP3 binds to IP3-gated calcium channels on the endoplasmic or sarcoplasmic reticulum, releasing stored calcium into the cytosol and triggering smooth muscle contraction or secretion. Protein kinase A is activated by cAMP, a separate pathway.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.027 Q5, G-Proteins and 2nd Messengers') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-g-proteins-and-second-messengers-f215e4af7c', 'pharm-g-proteins-and-second-messengers', 'mcq', 'Diacylglycerol (DAG) primarily activates:', '["Protein kinase A", "Protein kinase C", "Calmodulin", "Myosin light chain kinase", "Phosphodiesterase"]'::jsonb, 'Protein kinase C', '[]'::jsonb, 'DAG remains in the membrane and, together with calcium, activates protein kinase C, which phosphorylates many target proteins. Protein kinase A is the target of cAMP, and calmodulin is activated by calcium itself.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.027 Q6, G-Proteins and 2nd Messengers') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-g-proteins-and-second-messengers-b6470a2429', 'pharm-g-proteins-and-second-messengers', 'mcq', 'Gi proteins act by:', '["Stimulating adenylyl cyclase", "Inhibiting adenylyl cyclase", "Activating phospholipase C", "Increasing calcium influx", "Stimulating phosphodiesterase"]'::jsonb, 'Inhibiting adenylyl cyclase', '[]'::jsonb, 'Gi inhibits adenylyl cyclase, lowering cAMP, and its beta-gamma subunits open potassium channels. Alpha-2, M2, D2 and opioid receptors couple to Gi. Stimulation of adenylyl cyclase is the action of Gs.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.027 Q7, G-Proteins and 2nd Messengers') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-g-proteins-and-second-messengers-3b38aeeed5', 'pharm-g-proteins-and-second-messengers', 'mcq', 'Cyclic AMP (cAMP) exerts most of its effects by activating:', '["Protein kinase C", "Protein kinase G", "Protein kinase A", "Janus kinase (JAK)", "Rho kinase"]'::jsonb, 'Protein kinase A', '[]'::jsonb, 'cAMP binds the regulatory subunits of protein kinase A, freeing the catalytic subunits to phosphorylate enzymes and channels. Protein kinase G is the target of cGMP, and protein kinase C is activated by DAG and calcium.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.027 Q8, G-Proteins and 2nd Messengers') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-g-proteins-and-second-messengers-e585c3095a', 'pharm-g-proteins-and-second-messengers', 'mcq', 'Phosphodiesterase (PDE) enzymes are responsible for:', '["Synthesizing cAMP", "Breaking down cAMP and cGMP", "Phosphorylating receptors", "Binding to Gq proteins", "Transporting calcium"]'::jsonb, 'Breaking down cAMP and cGMP', '[]'::jsonb, 'Phosphodiesterases hydrolyse cAMP and cGMP to inactive 5''-AMP and 5''-GMP, ending the signal. PDE inhibitors prolong it: theophylline (non-selective), sildenafil (PDE5, cGMP) and milrinone (PDE3, cAMP).', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.027 Q9, G-Proteins and 2nd Messengers') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-g-proteins-and-second-messengers-a78e854d32', 'pharm-g-proteins-and-second-messengers', 'mcq', 'The second messenger involved in the action of atrial natriuretic peptide (ANP) and nitric oxide is:', '["cAMP", "cGMP", "IP3", "DAG", "Calcium"]'::jsonb, 'cGMP', '[]'::jsonb, 'ANP activates a membrane-bound guanylyl cyclase and nitric oxide activates the soluble form; both raise cGMP, which activates protein kinase G and relaxes vascular smooth muscle. Nitrates work through this pathway.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.027 Q10, G-Proteins and 2nd Messengers') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-g-proteins-and-second-messengers-2e640bbd6d', 'pharm-g-proteins-and-second-messengers', 'mcq', 'Beta-adrenoceptors are coupled to:', '["Gs proteins", "Gi proteins", "Gq proteins", "Go proteins", "Direct ion channels"]'::jsonb, 'Gs proteins', '[]'::jsonb, 'All beta-adrenoceptors (beta-1, beta-2 and beta-3) couple to Gs, which stimulates adenylyl cyclase and raises cAMP. Alpha-1 receptors use Gq and alpha-2 receptors use Gi.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.028 Q11, G-Proteins and 2nd Messengers') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-g-proteins-and-second-messengers-076a2552e3', 'pharm-g-proteins-and-second-messengers', 'mcq', 'Muscarinic M2 receptors in the heart are coupled to:', '["Gs", "Gi", "Gq", "G12/13", "Tyrosine kinase"]'::jsonb, 'Gi', '[]'::jsonb, 'M2 receptors couple to Gi: cAMP falls and beta-gamma subunits open potassium channels in the sinoatrial and atrioventricular nodes, slowing the heart rate and conduction. The odd-numbered muscarinic receptors (M1, M3, M5) couple to Gq.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.028 Q12, G-Proteins and 2nd Messengers') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-g-proteins-and-second-messengers-5cf47bb3d2', 'pharm-g-proteins-and-second-messengers', 'mcq', 'Calcium ions often produce their cellular effects by binding to the protein:', '["Albumin", "Calmodulin", "Haemoglobin", "Actin", "Tubulin"]'::jsonb, 'Calmodulin', '[]'::jsonb, 'Calmodulin binds four calcium ions and the complex then activates enzymes such as myosin light chain kinase in smooth muscle, nitric oxide synthase and calcium-calmodulin-dependent kinases. Albumin binds calcium in plasma but has no signalling role.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.028 Q13, G-Proteins and 2nd Messengers') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-g-proteins-and-second-messengers-bd4248545e', 'pharm-g-proteins-and-second-messengers', 'mcq', 'Cholera toxin causes massive diarrhoea by permanently activating:', '["Gi protein", "Gs protein", "Gq protein", "IP3 receptors", "Sodium-potassium ATPase"]'::jsonb, 'Gs protein', '[]'::jsonb, 'Cholera toxin ADP-ribosylates the alpha subunit of Gs and blocks its GTPase activity, so it stays switched on. cAMP in enterocytes rises continuously, driving chloride and water secretion into the gut. Pertussis toxin, in contrast, inactivates Gi.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.028 Q14, G-Proteins and 2nd Messengers') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-g-proteins-and-second-messengers-6fa01e98c8', 'pharm-g-proteins-and-second-messengers', 'mcq', 'Which of the following is NOT a second messenger?', '["cAMP", "Calcium", "IP3", "Magnesium", "DAG"]'::jsonb, 'Magnesium', '[]'::jsonb, 'The recognised second messengers are cAMP, cGMP, IP3, DAG and calcium, whose concentrations change rapidly when a receptor is activated. Magnesium is an enzyme cofactor whose intracellular level does not relay receptor signals.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.028 Q15, G-Proteins and 2nd Messengers') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-agonists-and-antagonists-26ff1b1d40', 'pharm-drug-agonists-and-antagonists', 'mcq', 'A drug that binds to a receptor and produces a sub-maximal response even at 100% receptor occupancy is a:', '["Full agonist", "Partial agonist", "Competitive antagonist", "Non-competitive antagonist", "Inverse agonist"]'::jsonb, 'Partial agonist', '[]'::jsonb, 'A partial agonist has intrinsic activity between 0 and 1, so even when it occupies every receptor it cannot produce the full response. Buprenorphine at the mu-opioid receptor is an example. A full agonist can give the maximum response, often with spare receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.028 Q1, Drug Agonist and Antagonist') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-agonists-and-antagonists-9b52a1bbb9', 'pharm-drug-agonists-and-antagonists', 'mcq', 'A competitive antagonist causes the agonist log dose-response curve to:', '["Shift to the left", "Shift to the right without changing the maximum response", "Shift to the right and suppress the maximum response", "Stay in the same position", "Become steeper"]'::jsonb, 'Shift to the right without changing the maximum response', '[]'::jsonb, 'A reversible competitive antagonist competes for the same binding site, so more agonist is needed for the same effect (parallel shift to the right), but enough agonist still gives the full maximum. A depressed maximum is the mark of non-competitive or irreversible antagonism.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.029 Q2, Drug Agonist and Antagonist') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-agonists-and-antagonists-fc25c43864', 'pharm-drug-agonists-and-antagonists', 'mcq', 'In the presence of a non-competitive antagonist, increasing the concentration of the agonist will:', '["Fully restore the maximum response", "Fail to restore the maximum response", "Shift the curve to the left", "Convert the antagonist into an agonist", "Displace the antagonist from its binding site"]'::jsonb, 'Fail to restore the maximum response', '[]'::jsonb, 'A non-competitive antagonist acts at a different site or downstream of the receptor, or binds irreversibly, so the agonist cannot displace it. The maximum response therefore stays depressed however much agonist is added. Only competitive antagonism is surmountable.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.029 Q3, Drug Agonist and Antagonist. Reworded: the original stem ''can be overcome by'' had ''it cannot be overcome'' as an option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-agonists-and-antagonists-c73f7909ea', 'pharm-drug-agonists-and-antagonists', 'mcq', 'An inverse agonist:', '["Has no effect on constitutive receptor activity", "Reduces the constitutive (basal) activity of a receptor", "Acts exactly like a partial agonist", "Binds only to inactive receptors", "Increases the maximum response of the agonist"]'::jsonb, 'Reduces the constitutive (basal) activity of a receptor', '[]'::jsonb, 'Some receptors are partly active without any ligand. An inverse agonist stabilises the inactive conformation and so lowers this basal activity, giving an effect opposite to that of an agonist. A neutral antagonist leaves constitutive activity unchanged.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.029 Q4, Drug Agonist and Antagonist') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-agonists-and-antagonists-2acdf6cc9b', 'pharm-drug-agonists-and-antagonists', 'mcq', 'Chemical antagonism occurs when:', '["Two drugs compete for the same receptor", "Two drugs react together in solution to form an inactive product", "One drug speeds up the metabolism of another", "Two drugs produce opposite physiological effects", "A drug binds to an allosteric site"]'::jsonb, 'Two drugs react together in solution to form an inactive product', '[]'::jsonb, 'In chemical antagonism the antagonist combines directly with the other drug and no receptor is involved: protamine neutralising heparin, or chelators such as dimercaprol binding heavy metals. Opposite effects through different receptors is physiological antagonism.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.029 Q5, Drug Agonist and Antagonist') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-agonists-and-antagonists-182f4958bc', 'pharm-drug-agonists-and-antagonists', 'mcq', 'Physiological (functional) antagonism is seen when:', '["Adrenaline relaxes bronchial muscle while histamine contracts it", "Naloxone reverses morphine overdose at the mu-receptor", "Protamine neutralizes heparin", "Phenobarbital induces liver enzymes", "Atropine blocks acetylcholine at the heart"]'::jsonb, 'Adrenaline relaxes bronchial muscle while histamine contracts it', '[]'::jsonb, 'Physiological antagonists act on different receptors to produce opposing effects in the same tissue: adrenaline (beta-2) dilates the bronchi that histamine (H1) constricts. Naloxone and atropine are competitive antagonists at the agonist''s own receptor, and protamine is a chemical antagonist.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.029 Q6, Drug Agonist and Antagonist') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-agonists-and-antagonists-f59a0c84ed', 'pharm-drug-agonists-and-antagonists', 'mcq', 'The concentration of an antagonist that reduces the response to an agonist by 50% is known as:', '["ED50", "LD50", "IC50", "pA2", "Km"]'::jsonb, 'IC50', '[]'::jsonb, 'IC50 is the inhibitory concentration that halves a given response. pA2 is related but different: the negative logarithm of the antagonist concentration that requires the agonist dose to be doubled to restore the original response.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.029 Q7, Drug Agonist and Antagonist') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-agonists-and-antagonists-54bc557cef', 'pharm-drug-agonists-and-antagonists', 'mcq', 'Irreversible antagonism usually involves:', '["Hydrogen bonding", "Van der Waals forces", "Covalent bonding", "Ionic bonding", "Hydrophobic interactions"]'::jsonb, 'Covalent bonding', '[]'::jsonb, 'Covalent bonds are strong enough to be effectively permanent, so the receptor stays blocked until new receptors are synthesised. Phenoxybenzamine at alpha-adrenoceptors is an example. The weaker bonds listed underlie ordinary reversible drug-receptor binding.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.030 Q8, Drug Agonist and Antagonist') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-agonists-and-antagonists-3a0d297522', 'pharm-drug-agonists-and-antagonists', 'mcq', 'A drug with high affinity but zero intrinsic activity is an:', '["Agonist", "Antagonist", "Partial agonist", "Inverse agonist", "Allosteric activator"]'::jsonb, 'Antagonist', '[]'::jsonb, 'Affinity lets the drug occupy the receptor, but with no intrinsic activity it cannot activate it, so its only effect is to block agonists. An inverse agonist has negative, not zero, intrinsic activity.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.030 Q9, Drug Agonist and Antagonist') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-agonists-and-antagonists-4eeb152c86', 'pharm-drug-agonists-and-antagonists', 'mcq', 'The pA2 value is a measure of the:', '["Potency of an agonist", "Potency of a competitive antagonist", "Efficacy of a drug", "Safety of a drug", "Ionization constant"]'::jsonb, 'Potency of a competitive antagonist', '[]'::jsonb, 'pA2 is the negative logarithm of the molar concentration of a competitive antagonist that makes it necessary to double the agonist concentration for the same response. The higher the pA2, the greater the antagonist''s affinity and potency.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.030 Q10, Drug Agonist and Antagonist') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-agonists-and-antagonists-3ac880ca08', 'pharm-drug-agonists-and-antagonists', 'mcq', 'When a partial agonist is added in the presence of a full agonist, it acts as an:', '["Synergist", "Antagonist", "Potentiator", "Additive drug", "Inverse agonist"]'::jsonb, 'Antagonist', '[]'::jsonb, 'The partial agonist competes with the full agonist for receptors but activates them less, so the overall response falls. This is why buprenorphine can precipitate withdrawal in a person dependent on a full opioid agonist.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.030 Q11, Drug Agonist and Antagonist') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-agonists-and-antagonists-92bbb7272c', 'pharm-drug-agonists-and-antagonists', 'mcq', 'Which of the following is an example of an irreversible antagonist?', '["Propranolol", "Atropine", "Phenoxybenzamine", "Naloxone", "Cimetidine"]'::jsonb, 'Phenoxybenzamine', '[]'::jsonb, 'Phenoxybenzamine forms a covalent bond with alpha-adrenoceptors, giving a block that lasts days and cannot be overcome by catecholamines, which is useful before phaeochromocytoma surgery. The other four are reversible competitive antagonists.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.030 Q12, Drug Agonist and Antagonist') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-agonists-and-antagonists-35380e7046', 'pharm-drug-agonists-and-antagonists', 'mcq', 'An intrinsic activity of 1.0 is assigned to a:', '["Full agonist", "Partial agonist", "Competitive antagonist", "Inverse agonist", "Non-competitive antagonist"]'::jsonb, 'Full agonist', '[]'::jsonb, 'Intrinsic activity is the drug''s maximal effect as a fraction of the system''s maximum: 1 for a full agonist, between 0 and 1 for a partial agonist, 0 for a neutral antagonist and negative for an inverse agonist.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.030 Q13, Drug Agonist and Antagonist') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-agonists-and-antagonists-720d574e02', 'pharm-drug-agonists-and-antagonists', 'mcq', 'Antagonism at the level of the signalling pathway, downstream of the receptor, is called:', '["Pharmacokinetic antagonism", "Non-competitive antagonism", "Competitive antagonism", "Chemical antagonism", "Absorption antagonism"]'::jsonb, 'Non-competitive antagonism', '[]'::jsonb, 'A non-competitive antagonist does not compete for the agonist binding site; it interrupts the chain of events between receptor activation and response. Calcium channel blockers, for example, prevent smooth muscle contraction whatever agonist is used. Pharmacokinetic antagonism lowers the agonist''s concentration instead.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.031 Q14, Drug Agonist and Antagonist') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-agonists-and-antagonists-421e43f497', 'pharm-drug-agonists-and-antagonists', 'mcq', 'A drug that binds to a site on the receptor different from the agonist binding site is called an:', '["Orthosteric ligand", "Allosteric ligand", "Competitive ligand", "Isosteric ligand", "Polar ligand"]'::jsonb, 'Allosteric ligand', '[]'::jsonb, 'Allosteric ligands bind elsewhere on the receptor and change its shape, increasing or decreasing the response to the agonist; benzodiazepines at the GABA-A receptor are positive allosteric modulators. Orthosteric ligands bind the agonist''s own site.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.031 Q15, Drug Agonist and Antagonist') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-log-dose-responses-f97afffbca', 'pharm-log-dose-responses', 'mcq', 'The dose-response curve is usually plotted as response against log dose in order to:', '["Make the curve linear over a wide range of doses", "Hide the errors in measurement", "Increase the maximum response", "Decrease the potency", "Make the drug appear safer"]'::jsonb, 'Make the curve linear over a wide range of doses', '[]'::jsonb, 'Plotting log dose turns the hyperbolic curve into a sigmoid whose middle portion (roughly 20 to 80% of maximum) is nearly straight. It also compresses a wide dose range onto one axis and makes it easy to compare the potencies of different drugs.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.031 Q1, Log-Dose Responses') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-log-dose-responses-c40283ad46', 'pharm-log-dose-responses', 'mcq', 'The ED50 of a drug is a measure of its:', '["Efficacy", "Potency", "Safety", "Toxicity", "Half-life"]'::jsonb, 'Potency', '[]'::jsonb, 'ED50 is the dose that gives half the maximal effect (or an effect in half the subjects). The lower the ED50, the more potent the drug. Efficacy is read from the height of the curve (Emax), not its position along the dose axis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.031 Q2, Log-Dose Responses') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-log-dose-responses-3654b04ef8', 'pharm-log-dose-responses', 'mcq', 'If Drug A has an ED50 of 5 mg and Drug B has an ED50 of 50 mg for the same effect:', '["Drug B is more potent than Drug A", "Drug A is more potent than Drug B", "Drug A is more efficacious than Drug B", "Drug B is more efficacious than Drug A", "Both drugs are equally potent"]'::jsonb, 'Drug A is more potent than Drug B', '[]'::jsonb, 'Potency is the amount of drug needed for a given effect, so the drug with the lower ED50 is more potent: A is ten times as potent as B. ED50 says nothing about efficacy, which depends on the maximal response each drug can reach.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.031 Q3, Log-Dose Responses') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-log-dose-responses-2c7338a238', 'pharm-log-dose-responses', 'mcq', '"Efficacy" (maximal effect) refers to:', '["The dose required to produce 50% of the maximal effect", "The greatest response a drug can produce regardless of dose", "The ratio of the lethal dose to the effective dose", "The speed at which the drug works", "The concentration at which the drug is metabolized"]'::jsonb, 'The greatest response a drug can produce regardless of dose', '[]'::jsonb, 'Efficacy is the plateau of the dose-response curve (Emax). It matters more clinically than potency: morphine relieves pain that no dose of aspirin can. The dose giving half the maximal effect is the ED50, a measure of potency.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.031 Q4, Log-Dose Responses') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-log-dose-responses-13319ad3d1', 'pharm-log-dose-responses', 'mcq', 'A steep dose-response curve indicates that:', '["The drug is very safe", "A small increase in dose leads to a large increase in response", "The drug has a high therapeutic index", "The drug is a partial agonist", "Receptor occupancy is low"]'::jsonb, 'A small increase in dose leads to a large increase in response', '[]'::jsonb, 'The slope shows how sharply the response changes with dose. With a steep curve, a small dose change can take the patient from no effect to an excessive effect, so dosing must be careful. Slope gives no information about the therapeutic index.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.032 Q5, Log-Dose Responses') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-level-monitoring-and-interpretati-eca6421d84', 'pharm-drug-level-monitoring-and-interpretation', 'mcq', 'The "therapeutic window" is the range of concentrations between:', '["Minimum effective concentration and minimum toxic concentration", "Zero dose and ED50", "ED50 and LD50", "Oral dose and intravenous dose", "Peak level and trough level"]'::jsonb, 'Minimum effective concentration and minimum toxic concentration', '[]'::jsonb, 'Below the minimum effective concentration the drug does not work, and above the minimum toxic concentration adverse effects appear; dosing aims to keep plasma levels between the two. Peak and trough are simply the highest and lowest levels in a dosing interval.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.032 Q6, Log-Dose Responses') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-log-dose-responses-0dd7ff556b', 'pharm-log-dose-responses', 'mcq', 'The therapeutic index (TI) is calculated as:', '["ED50 / LD50", "LD50 / ED50", "Vd / clearance", "Half-life × 0.693", "AUC / dose"]'::jsonb, 'LD50 / ED50', '[]'::jsonb, 'The therapeutic index is the median lethal (or toxic) dose divided by the median effective dose. A large value means a wide margin of safety. The inverse ratio would give a number below 1 for any usable drug.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.032 Q7, Log-Dose Responses') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-log-dose-responses-4e20b28ded', 'pharm-log-dose-responses', 'mcq', 'A "quantal" dose-response curve measures:', '["The intensity of response in a single individual", "The percentage of a population showing an all-or-none effect", "The rate of drug metabolism", "The duration of drug action", "The number of receptors occupied"]'::jsonb, 'The percentage of a population showing an all-or-none effect', '[]'::jsonb, 'Quantal curves plot the proportion of subjects in whom a defined either/or effect occurs (sleep, seizure protection, death) against dose. They give the ED50, TD50 and LD50 and show variation between individuals. Intensity of response in one subject is a graded curve.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.032 Q8, Log-Dose Responses') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-log-dose-responses-da82bd41ac', 'pharm-log-dose-responses', 'mcq', 'Which of the following is a "graded" response?', '["Prevention of pregnancy", "Death", "Decrease in blood pressure (mmHg)", "Cure of an infection", "Occurrence of a seizure"]'::jsonb, 'Decrease in blood pressure (mmHg)', '[]'::jsonb, 'A graded response is continuous and measurable on a scale, increasing with dose in a single subject, like a fall in blood pressure. The other options are all-or-none (quantal) events that either happen or do not.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.032 Q9, Log-Dose Responses') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-log-dose-responses-a4b69b4aaa', 'pharm-log-dose-responses', 'mcq', '"Ceiling effect" refers to:', '["The dose at which the drug becomes toxic", "The point where further increases in dose do not increase the response", "The dose given to elderly patients", "The minimum dose required to see any effect", "The first-pass effect"]'::jsonb, 'The point where further increases in dose do not increase the response', '[]'::jsonb, 'Once the maximal response (Emax) is reached, giving more drug adds only adverse effects. NSAIDs and partial agonists such as buprenorphine show a ceiling for analgesia. The minimum dose producing any effect is the threshold dose.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.032 Q11, Log-Dose Responses') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-log-dose-responses-7236331aa1', 'pharm-log-dose-responses', 'mcq', 'A drug with a therapeutic index of 2 is:', '["Very safe", "Relatively unsafe, with a narrow safety margin", "Highly potent", "A prodrug", "Non-toxic"]'::jsonb, 'Relatively unsafe, with a narrow safety margin', '[]'::jsonb, 'A therapeutic index of 2 means that only twice the effective dose is toxic or lethal to half of subjects, so small dosing errors or interactions can cause harm. Digoxin, lithium and theophylline are narrow-index drugs. The index says nothing about potency.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.033 Q12, Log-Dose Responses') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-log-dose-responses-396062132f', 'pharm-log-dose-responses', 'mcq', 'The potency of an agonist is determined by its:', '["Affinity and efficacy", "Affinity and receptor density", "Clearance and volume of distribution", "Bioavailability and dose", "Maximum effect only"]'::jsonb, 'Affinity and efficacy', '[]'::jsonb, 'The position of the dose-response curve (EC50) depends on how well the drug binds (affinity) and how effectively the bound drug is coupled to a response (efficacy). Receptor number also influences EC50 where spare receptors exist, but it is a property of the tissue, not the drug.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.033 Q13, Log-Dose Responses. Textbook answer (Rang & Dale, Katzung) is affinity + efficacy, but receptor density also affects observed potency, so option B is partly defensible.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-agonists-and-antagonists-b50ee6c51d', 'pharm-drug-agonists-and-antagonists', 'mcq', 'In the presence of a competitive antagonist, the ED50 of an agonist:', '["Decreases", "Increases", "Stays the same", "Becomes zero", "Equals the LD50"]'::jsonb, 'Increases', '[]'::jsonb, 'A competitive antagonist shifts the agonist curve to the right, so a higher dose is needed for half-maximal effect: apparent potency falls while the maximum is unchanged. A non-competitive antagonist lowers the maximum instead.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.033 Q14, Log-Dose Responses') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-log-dose-responses-34745db139', 'pharm-log-dose-responses', 'mcq', 'The "safety margin" (certain safety factor) of a drug is often defined as:', '["LD1 / ED99", "ED50 / LD50", "LD50 − ED50", "100% − response", "Half-life / clearance"]'::jsonb, 'LD1 / ED99', '[]'::jsonb, 'The certain safety factor compares the dose lethal to 1% of subjects with the dose effective in 99%. It is more realistic than the therapeutic index (LD50/ED50), which can look reassuring even when the tails of the two curves overlap.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.033 Q15, Log-Dose Responses') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacokinetics-f556626c9d', 'pharm-introduction-to-pharmacokinetics', 'mcq', 'Pharmacokinetics is the study of:', '["Drug mechanisms of action", "The relationship between drug concentration and effect", "The movement of drugs into, through, and out of the body", "The genetic basis of drug response", "The side effects of drugs"]'::jsonb, 'The movement of drugs into, through, and out of the body', '[]'::jsonb, 'Pharmacokinetics describes the time course of absorption, distribution, metabolism and excretion, and so how plasma concentration changes with time. Mechanisms of action and the concentration-effect relationship belong to pharmacodynamics.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.033 Q1, Introduction to Pharmacokinetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacokinetics-201e8e3643', 'pharm-introduction-to-pharmacokinetics', 'mcq', 'Which of the following is NOT a primary pharmacokinetic parameter?', '["Bioavailability", "Volume of distribution", "Clearance", "Affinity", "Elimination half-life"]'::jsonb, 'Affinity', '[]'::jsonb, 'Affinity describes how strongly a drug binds its receptor, which is a pharmacodynamic property. Bioavailability, volume of distribution, clearance and half-life describe how the body handles the drug and are used to design dosing regimens.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.034 Q2, Introduction to Pharmacokinetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacokinetics-bc48adc37d', 'pharm-introduction-to-pharmacokinetics', 'mcq', '"Steady state" is reached when:', '["The rate of drug administration equals the rate of elimination", "The drug is completely absorbed", "The patient stops taking the medication", "The drug is 100% protein bound", "Metabolism is bypassed"]'::jsonb, 'The rate of drug administration equals the rate of elimination', '[]'::jsonb, 'With repeated dosing or an infusion, the plasma level rises until the amount eliminated in each interval equals the amount given; the average concentration then stays constant. This takes about four to five half-lives whatever the dose.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.034 Q4, Introduction to Pharmacokinetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacokinetics-a9a9851da5', 'pharm-introduction-to-pharmacokinetics', 'mcq', 'How many half-lives does it typically take to reach about 94% of the steady-state concentration?', '["1", "2", "4", "7", "10"]'::jsonb, '4', '[]'::jsonb, 'The approach to steady state follows 50%, 75%, 87.5% and 93.75% after one, two, three and four half-lives. After four to five half-lives the drug is considered to be at steady state for clinical purposes; the same rule applies to elimination after stopping.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.034 Q5, Introduction to Pharmacokinetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacokinetics-2f37486c6d', 'pharm-introduction-to-pharmacokinetics', 'mcq', 'The elimination half-life is defined as the time taken for:', '["The drug to be completely eliminated from the body", "The plasma concentration to be reduced by 50%", "The drug to reach the site of action", "The liver to metabolize the first dose", "The drug to be 50% absorbed"]'::jsonb, 'The plasma concentration to be reduced by 50%', '[]'::jsonb, 'Half-life is the time for the plasma concentration to fall by half during the elimination phase. It equals 0.693 × Vd / CL and determines the dosing interval and the time to steady state. Complete elimination takes about five half-lives.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.034 Q6, Introduction to Pharmacokinetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacokinetics-6098df924b', 'pharm-introduction-to-pharmacokinetics', 'mcq', 'The constant fraction of drug eliminated per unit time in first-order kinetics is called the:', '["Clearance", "Elimination rate constant (Kel)", "Absorption coefficient", "Volume of distribution", "Bioavailability"]'::jsonb, 'Elimination rate constant (Kel)', '[]'::jsonb, 'Kel is the fraction of the drug in the body removed per unit time, with units of 1/time. It equals clearance divided by volume of distribution, and the half-life is 0.693 divided by Kel. Clearance is a volume of plasma cleared per unit time.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.034 Q7, Introduction to Pharmacokinetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacokinetics-164d843359', 'pharm-introduction-to-pharmacokinetics', 'mcq', 'A loading dose is administered to:', '["Rapidly achieve the target therapeutic plasma concentration", "Increase the drug''s half-life", "Prevent drug metabolism", "Reduce the frequency of dosing", "Bypass the kidneys"]'::jsonb, 'Rapidly achieve the target therapeutic plasma concentration', '[]'::jsonb, 'Without a loading dose, a drug takes four to five half-lives to reach steady state, which is too slow for drugs with long half-lives such as digoxin or amiodarone. A loading dose fills the volume of distribution at once; it does not change half-life or clearance.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.034 Q8, Introduction to Pharmacokinetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacokinetics-b2e1ae8502', 'pharm-introduction-to-pharmacokinetics', 'mcq', 'The formula for calculating a loading dose (LD) is:', '["LD = clearance × target concentration", "LD = Vd × target concentration", "LD = half-life × dose", "LD = Vd / clearance", "LD = dose / F"]'::jsonb, 'LD = Vd × target concentration', '[]'::jsonb, 'The loading dose must fill the volume of distribution to the desired concentration, so it is Vd × target concentration (divided by F if given orally). Clearance × target concentration gives the maintenance dose rate instead.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.035 Q9, Introduction to Pharmacokinetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacokinetics-f96c7fa3b7', 'pharm-introduction-to-pharmacokinetics', 'mcq', 'The maintenance dose is primarily determined by:', '["Volume of distribution", "Drug clearance", "Patient''s height", "Number of receptors", "Drug potency"]'::jsonb, 'Drug clearance', '[]'::jsonb, 'At steady state the rate of dosing must equal the rate of elimination, which is clearance × target concentration. Reduced clearance in renal or hepatic disease therefore calls for a lower maintenance dose. Volume of distribution determines the loading dose.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.035 Q10, Introduction to Pharmacokinetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacokinetics-34be7c8f7a', 'pharm-introduction-to-pharmacokinetics', 'mcq', 'Total body clearance is the sum of:', '["Renal clearance + hepatic clearance + other (e.g. lung) clearance", "Absorption + distribution", "Vd + half-life", "Dose + bioavailability", "Metabolic rate + heart rate"]'::jsonb, 'Renal clearance + hepatic clearance + other (e.g. lung) clearance', '[]'::jsonb, 'Clearance is additive: each eliminating organ contributes its own clearance, and the total is their sum. Knowing the renal share tells you how far to reduce the dose in kidney disease.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.035 Q11, Introduction to Pharmacokinetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacokinetics-13bced048e', 'pharm-introduction-to-pharmacokinetics', 'mcq', 'In a one-compartment model, the body is treated as:', '["A series of separate organs", "A single, uniform volume in which the drug distributes instantly", "A system where the brain is the only exit", "A system with no metabolism", "A vessel with infinite volume"]'::jsonb, 'A single, uniform volume in which the drug distributes instantly', '[]'::jsonb, 'The one-compartment model assumes that the drug mixes immediately and evenly throughout a single volume, so the plasma level declines in a single exponential phase. Two-compartment models add a peripheral compartment and show separate distribution and elimination phases.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.035 Q12, Introduction to Pharmacokinetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-effects-of-disease-on-drug-disposition-957d53615a', 'pharm-effects-of-disease-on-drug-disposition', 'mcq', 'Which factor would increase the half-life of a drug excreted by the kidneys?', '["Increased renal blood flow", "Renal failure", "Decreased protein binding", "Enzyme induction", "Increased fluid intake"]'::jsonb, 'Renal failure', '[]'::jsonb, 'Half-life equals 0.693 × Vd / CL, so anything that lowers clearance prolongs it. Renal failure reduces the clearance of drugs such as gentamicin, digoxin and lithium, which then accumulate unless the dose or interval is adjusted.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.035 Q13, Introduction to Pharmacokinetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-bioavailability-641ea47a36', 'pharm-bioavailability', 'mcq', 'The area under the plasma concentration-time curve (AUC) represents:', '["The total amount of drug that reaches the systemic circulation", "The peak concentration only", "The time the drug takes to be absorbed", "The toxicity level", "The drug''s affinity for the receptor"]'::jsonb, 'The total amount of drug that reaches the systemic circulation', '[]'::jsonb, 'AUC measures total systemic exposure to the drug and is proportional to the dose absorbed divided by clearance. Comparing the oral AUC with the intravenous AUC gives bioavailability. The peak concentration is Cmax, a single point on the curve.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.035 Q14, Introduction to Pharmacokinetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacokinetics-bdb8d05abe', 'pharm-introduction-to-pharmacokinetics', 'mcq', 'If a drug follows zero-order kinetics, its half-life:', '["Is constant", "Decreases as concentration increases", "Increases as concentration increases", "Is independent of the dose", "Is always 4 hours"]'::jsonb, 'Increases as concentration increases', '[]'::jsonb, 'In zero-order elimination a fixed amount is removed per unit time, so the higher the starting concentration, the longer it takes to remove half of it. A constant, dose-independent half-life is the hallmark of first-order kinetics.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.036 Q15, Introduction to Pharmacokinetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-time-course-of-drug-action-2e5123d29f', 'pharm-time-course-of-drug-action', 'mcq', 'The "onset of action" is the time required for:', '["The drug to reach the peak concentration", "The drug concentration to reach the minimum effective concentration (MEC)", "The drug to be 100% eliminated", "Side effects to appear", "The drug to bind to albumin"]'::jsonb, 'The drug concentration to reach the minimum effective concentration (MEC)', '[]'::jsonb, 'Onset is the interval from administration until the plasma level first reaches the minimum effective concentration and an effect appears. It depends on route and absorption rate. The time to peak concentration is Tmax, which comes later.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.036 Q1, Time Course of Drug Effect') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-time-course-of-drug-action-6dbb91e4e4', 'pharm-time-course-of-drug-action', 'mcq', 'The duration of action of a drug is the time during which:', '["The drug is present in the blood", "The plasma concentration remains above the minimum effective concentration", "The drug is being absorbed", "The drug is being metabolized by the liver", "The patient feels no symptoms"]'::jsonb, 'The plasma concentration remains above the minimum effective concentration', '[]'::jsonb, 'The effect lasts from the moment the plasma level rises above the minimum effective concentration until it falls below it again. Drug is still detectable in blood after that, but at sub-therapeutic levels.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.036 Q2, Time Course of Drug Effect') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anti-microbials-classi-24a3d89ea0', 'pharm-introduction-to-anti-microbials-classification-and-resistance', 'mcq', 'The "post-antibiotic effect" (PAE) describes:', '["Toxicity that occurs after the antibiotic is stopped", "Continued suppression of bacterial growth after the antibiotic concentration falls below the MIC", "Rapid resistance development", "Immediate cure of the infection", "Allergy to the antibiotic"]'::jsonb, 'Continued suppression of bacterial growth after the antibiotic concentration falls below the MIC', '[]'::jsonb, 'Some antibiotics, notably aminoglycosides and fluoroquinolones, keep bacteria from regrowing for hours after levels fall below the minimum inhibitory concentration. Together with concentration-dependent killing, this justifies once-daily aminoglycoside dosing.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.036 Q3, Time Course of Drug Effect') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-level-monitoring-and-interpretati-a8902c606a', 'pharm-drug-level-monitoring-and-interpretation', 'mcq', '"Trough concentration" (Cmin) is measured:', '["Immediately after an intravenous bolus", "Midway between two doses", "Just before the next dose is administered", "1 hour after oral intake", "At the exact time of the peak"]'::jsonb, 'Just before the next dose is administered', '[]'::jsonb, 'The trough is the lowest level in a dosing interval, so the sample is taken immediately before the next dose. It is the usual sample for monitoring drugs such as digoxin, vancomycin and gentamicin.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.036 Q4, Time Course of Drug Effect') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-time-course-of-drug-action-d496926da6', 'pharm-time-course-of-drug-action', 'mcq', 'Which of the following determines the peak concentration (Cmax) after a single oral dose?', '["Rate of absorption", "Rate of elimination", "Dose administered", "All of the above", "None of the above"]'::jsonb, 'All of the above', '[]'::jsonb, 'The peak occurs when the rate of absorption equals the rate of elimination. A larger dose or faster absorption raises Cmax, and faster elimination lowers it, so all three contribute.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.037 Q5, Time Course of Drug Effect') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-time-course-of-drug-action-3d6fc44edf', 'pharm-time-course-of-drug-action', 'mcq', 'For a drug given by intravenous infusion, the steady-state concentration (Css) is directly proportional to:', '["The infusion rate", "The volume of distribution", "The age of the patient", "The size of the needle", "The storage temperature"]'::jsonb, 'The infusion rate', '[]'::jsonb, 'At steady state, Css equals infusion rate divided by clearance, so doubling the rate doubles Css. Volume of distribution affects how long it takes to reach steady state (through the half-life) but not the level reached.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.037 Q6, Time Course of Drug Effect') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-time-course-of-drug-action-c81317105a', 'pharm-time-course-of-drug-action', 'mcq', 'A delay in drug effect relative to plasma concentration (hysteresis) may be due to:', '["The time taken for the drug to distribute to the site of action", "Slow receptor-binding kinetics", "The time required for existing proteins to be depleted (e.g. warfarin)", "All of the above", "None of the above"]'::jsonb, 'All of the above', '[]'::jsonb, 'The effect can lag behind the plasma level when the drug must first reach its site of action, when it binds slowly, or when the response depends on a slow downstream event: warfarin stops clotting factor synthesis at once, but the existing factors take days to decay.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.037 Q7, Time Course of Drug Effect. Option C reworded: the warfarin delay is due to slow decay of existing clotting factors, not synthesis of new proteins.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-time-course-of-drug-action-4e8873d9ff', 'pharm-time-course-of-drug-action', 'mcq', 'If the dosing interval is significantly shorter than the half-life, the drug will:', '["Be eliminated faster", "Accumulate in the body", "Reach steady state instantly", "Lose its efficacy", "Not be absorbed"]'::jsonb, 'Accumulate in the body', '[]'::jsonb, 'When the next dose arrives before much of the previous one has been eliminated, plasma levels build up until a steady state is reached well above the level after the first dose. The shorter the interval relative to the half-life, the greater the accumulation.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.037 Q8, Time Course of Drug Effect') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-time-course-of-drug-action-9846f729b7', 'pharm-time-course-of-drug-action', 'mcq', 'Which parameter remains unchanged when the dose of a drug with first-order kinetics is doubled?', '["Cmax", "AUC", "Half-life", "Css", "Total amount of drug in the body"]'::jsonb, 'Half-life', '[]'::jsonb, 'In first-order kinetics, half-life depends only on clearance and volume of distribution, not on dose. Doubling the dose doubles Cmax, AUC, steady-state concentration and the amount in the body, but the drug still takes the same time to halve.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.037 Q10, Time Course of Drug Effect') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-time-course-of-drug-action-365dd53ce4', 'pharm-time-course-of-drug-action', 'mcq', 'Intermittent dosing (e.g. every 8 hours) leads to:', '["Constant plasma levels", "Fluctuations between peak and trough levels", "Immediate steady state", "Zero-order kinetics", "Complete elimination between doses"]'::jsonb, 'Fluctuations between peak and trough levels', '[]'::jsonb, 'Each dose gives a peak followed by a fall to a trough before the next dose, so the level oscillates around the average steady-state concentration. Only a continuous infusion gives a constant level. Smaller, more frequent doses reduce the swings.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.038 Q11, Time Course of Drug Effect') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-time-course-of-drug-action-628a248c03', 'pharm-time-course-of-drug-action', 'mcq', 'The "washout period" refers to the time needed to:', '["Sterilize the equipment", "Ensure a drug is completely eliminated before starting a new one", "Increase the heart rate", "Dissolve a tablet in water", "Reach peak concentration"]'::jsonb, 'Ensure a drug is completely eliminated before starting a new one', '[]'::jsonb, 'A washout of about five half-lives lets one drug leave the body before another is started, as when switching between an MAO inhibitor and an SSRI, or between the arms of a crossover trial, so that the effects of the first do not carry over.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.038 Q12, Time Course of Drug Effect') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacology-routes-of-f4c1054a83', 'pharm-introduction-to-pharmacology-routes-of-drug-administration', 'mcq', 'Which route of administration usually shows the slowest onset of action?', '["Intravenous", "Sublingual", "Transdermal", "Intramuscular", "Inhalation"]'::jsonb, 'Transdermal', '[]'::jsonb, 'A drug from a patch has to cross the stratum corneum, which is a slow rate-limiting barrier, so effective levels may take hours to develop. Intravenous, inhaled and sublingual routes act within seconds to minutes.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.038 Q13, Time Course of Drug Effect') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-time-course-of-drug-action-184e1d54c5', 'pharm-time-course-of-drug-action', 'mcq', 'The time to reach steady state depends solely on:', '["The dose", "The elimination half-life", "The frequency of dosing", "The route of administration", "The bioavailability"]'::jsonb, 'The elimination half-life', '[]'::jsonb, 'Steady state is reached after four to five half-lives regardless of dose or dosing interval. Dose and frequency change the level of the plateau, not the time needed to get there.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.038 Q14, Time Course of Drug Effect') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-time-course-of-drug-action-a3002c8cd2', 'pharm-time-course-of-drug-action', 'mcq', 'Continuous intravenous infusion is preferred when:', '["A narrow therapeutic window requires constant plasma levels", "The drug has a very long half-life", "The drug is highly toxic at low concentrations", "The patient is mobile", "Rapid elimination is desired"]'::jsonb, 'A narrow therapeutic window requires constant plasma levels', '[]'::jsonb, 'An infusion avoids peaks and troughs, so it suits drugs with a narrow therapeutic window and a short half-life, such as heparin, lidocaine and dopamine. A drug with a long half-life gives steady levels with intermittent dosing anyway.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.038 Q15, Time Course of Drug Effect') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-level-monitoring-and-interpretati-76edc9896e', 'pharm-drug-level-monitoring-and-interpretation', 'mcq', 'Therapeutic drug monitoring (TDM) is most useful for drugs with:', '["A wide therapeutic index", "A narrow therapeutic index", "Short half-lives", "High bioavailability", "Irreversible effects"]'::jsonb, 'A narrow therapeutic index', '[]'::jsonb, 'Measuring plasma levels is worthwhile when the toxic concentration is close to the therapeutic one, kinetics vary between patients and the effect is hard to measure directly. For wide-index drugs it adds nothing, and for irreversible (''hit and run'') drugs levels do not reflect effect.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.038 Q1, Therapeutic Drug Monitoring (TDM) & Interactions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-level-monitoring-and-interpretati-1091e041a7', 'pharm-drug-level-monitoring-and-interpretation', 'mcq', 'Which of the following drugs is a classic candidate for therapeutic drug monitoring?', '["Penicillin", "Digoxin", "Paracetamol", "Ibuprofen", "Vitamin C"]'::jsonb, 'Digoxin', '[]'::jsonb, 'Digoxin has a narrow therapeutic range (roughly 0.5 to 2 ng/mL) and is cleared by the kidney, so levels vary with renal function. Other monitored drugs are lithium, phenytoin, theophylline, aminoglycosides, vancomycin and ciclosporin. Penicillin has a wide safety margin.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.039 Q2, Therapeutic Drug Monitoring (TDM) & Interactions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-level-monitoring-and-interpretati-871500df16', 'pharm-drug-level-monitoring-and-interpretation', 'mcq', 'In therapeutic drug monitoring, a trough level is typically used to:', '["Measure the peak toxicity of the drug", "Check that the concentration stays above the minimum effective level before the next dose", "Measure the rate of absorption", "Check the patient''s height", "Determine the volume of distribution"]'::jsonb, 'Check that the concentration stays above the minimum effective level before the next dose', '[]'::jsonb, 'The trough is the lowest concentration in the dosing interval, so it shows whether the level remains adequate until the next dose. For some drugs, notably aminoglycosides, a high trough is also used as a warning of accumulation and toxicity.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.039 Q3, Therapeutic Drug Monitoring (TDM) & Interactions. Ambiguous: for aminoglycosides the trough is monitored mainly to avoid toxicity, so the original option A (''ensure the drug doesn''t reach toxic levels'') is also defensible; option A reworded.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-1d918e801d', 'pharm-drug-interactions', 'mcq', 'Pharmacodynamic drug interactions involve:', '["Changes in drug absorption", "Competition at the receptor site or signalling pathway", "Induction of liver enzymes", "Changes in renal excretion", "Alterations in protein binding"]'::jsonb, 'Competition at the receptor site or signalling pathway', '[]'::jsonb, 'A pharmacodynamic interaction changes the effect of a drug without changing its concentration: the drugs act on the same receptor or the same physiological system. The other options alter absorption, distribution, metabolism or excretion and are pharmacokinetic.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.039 Q4, Therapeutic Drug Monitoring (TDM) & Interactions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-cb442e0650', 'pharm-drug-interactions', 'mcq', 'Which interaction is an example of synergism?', '["Alcohol and benzodiazepines causing extreme sedation", "Naloxone reversing morphine effects", "Antacids reducing tetracycline absorption", "Phenobarbital increasing the metabolism of warfarin", "Probenecid increasing penicillin levels"]'::jsonb, 'Alcohol and benzodiazepines causing extreme sedation', '[]'::jsonb, 'Alcohol and benzodiazepines both enhance GABA-A mediated inhibition, and together they depress the CNS more than expected from either alone. Naloxone with morphine is antagonism, and the remaining options are pharmacokinetic interactions.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.039 Q5, Therapeutic Drug Monitoring (TDM) & Interactions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-ee66a31435', 'pharm-drug-interactions', 'mcq', 'Which of the following is a pharmacokinetic interaction at the level of absorption?', '["Aspirin and warfarin competing for albumin", "Adrenaline added to lidocaine to slow its systemic uptake", "Propranolol blocking the effect of salbutamol", "Rifampicin inducing CYP enzymes", "Atropine and acetylcholine at the heart"]'::jsonb, 'Adrenaline added to lidocaine to slow its systemic uptake', '[]'::jsonb, 'Adrenaline constricts local blood vessels, so lidocaine is absorbed from the injection site more slowly; the block lasts longer and systemic toxicity is less. Competition for albumin affects distribution and enzyme induction affects metabolism.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.039 Q6, Therapeutic Drug Monitoring (TDM) & Interactions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-4c4512a618', 'pharm-drug-interactions', 'mcq', 'Displacement of a drug from plasma protein binding sites is most dangerous when:', '["The drug has a high volume of distribution", "The drug is highly protein-bound (>90%) and has a narrow therapeutic index", "The drug is water-soluble", "The drug is a prodrug", "The drug is eliminated by the lungs"]'::jsonb, 'The drug is highly protein-bound (>90%) and has a narrow therapeutic index', '[]'::jsonb, 'If a drug is 99% bound, displacing just 1% doubles the free concentration, which matters when the toxic level is close to the therapeutic one, as with warfarin or phenytoin. A large volume of distribution buffers the change because the freed drug moves into tissues.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.039 Q7, Therapeutic Drug Monitoring (TDM) & Interactions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-ab794254a6', 'pharm-drug-interactions', 'mcq', '"Additivity" occurs when the combined effect of two drugs is:', '["Greater than the sum of their individual effects", "Equal to the sum of their individual effects", "Less than the sum of their individual effects", "Zero", "Unpredictable"]'::jsonb, 'Equal to the sum of their individual effects', '[]'::jsonb, 'An additive effect is simple summation (1 + 1 = 2), usually seen with drugs acting by the same mechanism. An effect greater than the sum is synergism, and one less than the sum is antagonism.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.039 Q8, Therapeutic Drug Monitoring (TDM) & Interactions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-dfe6e4d5f2', 'pharm-drug-interactions', 'mcq', 'Which of the following is a potent inhibitor of microsomal (CYP450) enzymes?', '["Phenytoin", "Cimetidine", "St John''s wort", "Carbamazepine", "Chronic alcohol use"]'::jsonb, 'Cimetidine', '[]'::jsonb, 'Cimetidine binds the haem iron of several CYP450 isoforms and slows the metabolism of warfarin, theophylline and phenytoin. All the other options are enzyme inducers, which lower the levels of co-administered drugs.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.040 Q9, Therapeutic Drug Monitoring (TDM) & Interactions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-1d61d5a6b1', 'pharm-drug-interactions', 'mcq', 'Which drug interaction occurs in the renal tubules?', '["Warfarin and rifampicin", "Penicillin and probenecid", "Iron and calcium", "Morphine and naloxone", "Insulin and glucagon"]'::jsonb, 'Penicillin and probenecid', '[]'::jsonb, 'Probenecid competes with penicillin for the organic anion transporter in the proximal tubule, reducing its secretion and prolonging its action. Warfarin with rifampicin is hepatic enzyme induction, and iron with calcium interact in the gut lumen.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.040 Q11, Therapeutic Drug Monitoring (TDM) & Interactions. Replaced option ''Digoxin and Quinidine'' (quinidine also reduces renal tubular secretion of digoxin, so it was a second defensible answer) with ''Warfarin and rifampicin''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-856e70e7ea', 'pharm-drug-interactions', 'mcq', 'Tyramine-rich foods (like aged cheese) cause a hypertensive crisis in patients taking:', '["Beta-blockers", "MAO inhibitors", "ACE inhibitors", "Diuretics", "Calcium channel blockers"]'::jsonb, 'MAO inhibitors', '[]'::jsonb, 'Dietary tyramine is normally destroyed by MAO-A in the gut wall and liver. With a non-selective MAO inhibitor it reaches the circulation and releases the enlarged stores of noradrenaline from nerve endings, causing severe hypertension (the ''cheese reaction'').', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.040 Q12, Therapeutic Drug Monitoring (TDM) & Interactions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-f198eb02dc', 'pharm-drug-interactions', 'mcq', 'If each number stands for the size of a drug''s effect, which sum represents potentiation?', '["1 + 1 = 2", "1 + 1 = 3", "0 + 1 = 2", "1 − 1 = 0", "2 + 2 = 1"]'::jsonb, '0 + 1 = 2', '[]'::jsonb, 'In potentiation a drug with no effect of its own increases the effect of another, for example clavulanic acid with amoxicillin or carbidopa with levodopa. 1 + 1 = 2 is addition, and 1 + 1 = 3 is synergism, where both drugs are active.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.040 Q14, Therapeutic Drug Monitoring (TDM) & Interactions. Removed the explanatory hint from the answer option and clarified the stem.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-aab5b6eb84', 'pharm-drug-interactions', 'mcq', 'A patient on lithium should avoid which class of drugs because of the risk of lithium toxicity?', '["Penicillins", "NSAIDs (e.g. ibuprofen)", "Antacids", "Statins", "Beta-agonists"]'::jsonb, 'NSAIDs (e.g. ibuprofen)', '[]'::jsonb, 'NSAIDs reduce renal prostaglandin synthesis, lowering renal blood flow and lithium clearance, so plasma lithium rises into the toxic range. Thiazide diuretics and ACE inhibitors do the same by promoting proximal sodium and lithium reabsorption.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.041 Q15, Therapeutic Drug Monitoring (TDM) & Interactions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-effects-of-disease-on-drug-disposition-6da1a31c15', 'pharm-effects-of-disease-on-drug-disposition', 'mcq', 'In patients with chronic renal failure, the most important dosing adjustment is to:', '["Increase the loading dose", "Decrease the maintenance dose or increase the dosing interval", "Switch to an oral route", "Increase the protein intake", "Stop all medications"]'::jsonb, 'Decrease the maintenance dose or increase the dosing interval', '[]'::jsonb, 'Renal failure reduces the clearance of drugs excreted by the kidney, so the usual maintenance regimen would cause accumulation. The dose is reduced or the interval lengthened in proportion to creatinine clearance. The loading dose is usually unchanged because it depends on volume of distribution.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.041 Q1, Drug Disposition in Disease States') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-effects-of-disease-on-drug-disposition-4395a8b4ff', 'pharm-effects-of-disease-on-drug-disposition', 'mcq', 'In liver cirrhosis, the first-pass effect is typically:', '["Increased", "Decreased", "Unchanged", "Eliminated completely", "Only affected for intravenous drugs"]'::jsonb, 'Decreased', '[]'::jsonb, 'Loss of functioning hepatocytes and portosystemic shunting let more of an oral dose reach the systemic circulation unmetabolised. Bioavailability of high-extraction drugs such as propranolol, morphine and labetalol can rise several-fold, so oral doses must be reduced.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.041 Q2, Drug Disposition in Disease States. Removed hint from the answer option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-effects-of-disease-on-drug-disposition-acfa82c114', 'pharm-effects-of-disease-on-drug-disposition', 'mcq', 'Which condition significantly alters the distribution of water-soluble drugs such as gentamicin?', '["Obesity", "Oedema or ascites", "Dehydration", "All of the above", "None of the above"]'::jsonb, 'All of the above', '[]'::jsonb, 'Gentamicin distributes in extracellular fluid. Oedema and ascites expand that volume and lower plasma levels, dehydration shrinks it and raises them, and in obesity the drug does not enter the extra fat, so dosing on total body weight overdoses the patient.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.041 Q4, Drug Disposition in Disease States. ''All of the above'' is the intended answer, but oedema/ascites is the single classic one; a marker could argue either way.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-effects-of-disease-on-drug-disposition-1fef0f2444', 'pharm-effects-of-disease-on-drug-disposition', 'mcq', 'In congestive heart failure, drug absorption from the gut is often reduced due to:', '["High gastric acid", "Oedema of the gut wall and reduced blood flow", "Increased peristalsis", "Lower pH of the intestine", "Increased bile production"]'::jsonb, 'Oedema of the gut wall and reduced blood flow', '[]'::jsonb, 'Venous congestion makes the bowel wall oedematous, and the low cardiac output reduces splanchnic blood flow, so oral drugs such as furosemide are absorbed slowly and erratically. This is one reason intravenous diuretics are used in decompensated heart failure.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.041 Q5, Drug Disposition in Disease States') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-effects-of-disease-on-drug-disposition-06958cee1d', 'pharm-effects-of-disease-on-drug-disposition', 'mcq', 'Drugs with high hepatic extraction ratios are most sensitive to:', '["Changes in renal function", "Changes in liver blood flow", "Changes in urine pH", "Dietary fibre", "Exposure to sunlight"]'::jsonb, 'Changes in liver blood flow', '[]'::jsonb, 'When the liver removes most of the drug in a single pass (lidocaine, propranolol, morphine), clearance is limited by how fast blood delivers the drug, so it falls in heart failure or shock. Low-extraction drugs depend instead on enzyme activity and protein binding.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.042 Q6, Drug Disposition in Disease States') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-effects-of-disease-on-drug-disposition-842979a7c3', 'pharm-effects-of-disease-on-drug-disposition', 'mcq', 'A patient with hyperthyroidism may require:', '["Lower doses of digoxin", "Higher doses of digoxin", "No adjustment of the digoxin dose", "Digoxin by the intravenous route only", "Withdrawal of digoxin altogether"]'::jsonb, 'Higher doses of digoxin', '[]'::jsonb, 'Thyrotoxicosis increases the renal clearance and volume of distribution of digoxin and makes the heart less sensitive to it, so larger doses are needed. Hypothyroid patients are the opposite: they are sensitive to digoxin and need less.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.042 Q7, Drug Disposition in Disease States. Original option A said ''lower doses (due to increased metabolism/clearance)'', which contradicts itself; options tidied.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-effects-of-disease-on-drug-disposition-c08bd3d4ed', 'pharm-effects-of-disease-on-drug-disposition', 'mcq', 'In achlorhydria (lack of stomach acid), the absorption of which drug is impaired?', '["Aspirin", "Ketoconazole", "Diazepam", "Ethanol", "Paracetamol"]'::jsonb, 'Ketoconazole', '[]'::jsonb, 'Ketoconazole is a weak base that needs gastric acid to dissolve before it can be absorbed. Achlorhydria, proton pump inhibitors, H2 blockers and antacids all reduce its absorption; itraconazole capsules and iron salts behave similarly.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.042 Q8, Drug Disposition in Disease States') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-geriatric-clinical-pharmacology-5e00cfc259', 'pharm-geriatric-clinical-pharmacology', 'mcq', 'The volume of distribution in an elderly patient is often different because:', '["They have more muscle mass", "They have a higher percentage of body fat and lower body water", "They have higher plasma albumin", "Their liver is larger", "They have more stomach acid"]'::jsonb, 'They have a higher percentage of body fat and lower body water', '[]'::jsonb, 'With age, lean mass and total body water fall and the proportion of fat rises. Lipid-soluble drugs such as diazepam therefore have a larger volume of distribution and a longer half-life, while water-soluble drugs such as digoxin and gentamicin reach higher plasma levels.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.042 Q9, Drug Disposition in Disease States') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-effects-of-disease-on-drug-disposition-ca9d825dbc', 'pharm-effects-of-disease-on-drug-disposition', 'mcq', 'Uraemia (in renal failure) can decrease drug-protein binding by:', '["Increasing albumin levels", "Accumulating organic acids that compete for binding sites", "Decreasing the temperature of the blood", "Making the blood more alkaline", "Increasing the number of receptors"]'::jsonb, 'Accumulating organic acids that compete for binding sites', '[]'::jsonb, 'Retained endogenous organic acids compete with acidic drugs for albumin binding sites, and albumin itself is altered and often reduced in uraemia. The free fraction of phenytoin, for example, rises, so total plasma levels underestimate the active concentration.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.042 Q10, Drug Disposition in Disease States') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aminoglycosides-880c4f7e66', 'pharm-aminoglycosides', 'mcq', 'Which drug should be avoided or used with extreme caution in patients with myasthenia gravis?', '["Penicillin", "Aminoglycosides (e.g. gentamicin)", "Aspirin", "Paracetamol", "Vitamin D"]'::jsonb, 'Aminoglycosides (e.g. gentamicin)', '[]'::jsonb, 'Aminoglycosides inhibit presynaptic calcium entry and acetylcholine release and reduce postsynaptic sensitivity, which worsens neuromuscular transmission that is already impaired. They can precipitate a myasthenic crisis and they potentiate neuromuscular blockers.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.042 Q11, Drug Disposition in Disease States') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-effects-of-disease-on-drug-disposition-cd1aaa172d', 'pharm-effects-of-disease-on-drug-disposition', 'mcq', 'In a patient with severe burns, the volume of distribution of many drugs increases due to:', '["Fluid loss", "Increased capillary permeability and fluid shifts", "Faster metabolism", "Increased skin thickness", "High protein diet"]'::jsonb, 'Increased capillary permeability and fluid shifts', '[]'::jsonb, 'Burns cause capillary leak, oedema and loss of albumin, and large volumes of resuscitation fluid are given, so the extracellular space expands. Water-soluble drugs such as aminoglycosides are diluted and need higher doses, guided by plasma levels.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.043 Q12, Drug Disposition in Disease States') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-effects-of-disease-on-drug-disposition-bc09cc2ea8', 'pharm-effects-of-disease-on-drug-disposition', 'mcq', 'The Cockcroft-Gault formula is used to estimate:', '["Liver enzymes", "Creatinine clearance", "Heart rate", "Body fat percentage", "Maximum lung capacity"]'::jsonb, 'Creatinine clearance', '[]'::jsonb, 'The formula estimates creatinine clearance from age, weight, sex and serum creatinine: (140 − age) × weight / (72 × serum creatinine in mg/dL), multiplied by 0.85 in women. It is the usual basis for adjusting drug doses in renal impairment.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.043 Q13, Drug Disposition in Disease States. Removed hint from the answer option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-effects-of-disease-on-drug-disposition-fc8a3138fc', 'pharm-effects-of-disease-on-drug-disposition', 'mcq', 'Drug-induced hepatotoxicity is more likely in patients who:', '["Drink alcohol chronically", "Are malnourished", "Have pre-existing liver disease", "All of the above", "None of the above"]'::jsonb, 'All of the above', '[]'::jsonb, 'Chronic alcohol induces CYP2E1, producing more toxic metabolites; malnutrition depletes the glutathione that detoxifies them; and a diseased liver has less reserve. All three lower the threshold for liver injury from paracetamol, isoniazid and similar drugs.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.043 Q14, Drug Disposition in Disease States. Removed hint ''(low glutathione)'' from an option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-genetic-medicine-73508e2f3b', 'pharm-genetic-medicine', 'mcq', 'A patient with glucose-6-phosphate dehydrogenase (G6PD) deficiency is at risk of haemolysis if they take:', '["Primaquine", "Penicillin", "Insulin", "Propranolol", "Digoxin"]'::jsonb, 'Primaquine', '[]'::jsonb, 'G6PD supplies the NADPH that keeps glutathione reduced in red cells. Oxidant drugs such as primaquine, dapsone, sulfonamides and nitrofurantoin overwhelm deficient cells and cause acute haemolysis. G6PD status should be checked before giving primaquine.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.043 Q15, Drug Disposition in Disease States. Corrected spelling ''Primiquine''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-900be12013', 'pharm-drug-interactions', 'mcq', 'The "disulfiram-like reaction" occurs when alcohol is taken with:', '["Metronidazole", "Amoxicillin", "Aspirin", "Ciprofloxacin", "Digoxin"]'::jsonb, 'Metronidazole', '[]'::jsonb, 'Metronidazole is taught as an inhibitor of aldehyde dehydrogenase, so acetaldehyde accumulates after alcohol, causing flushing, nausea, vomiting and tachycardia. Patients are told to avoid alcohol during treatment and for 48 hours afterwards. Some cephalosporins and chlorpropamide do the same.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.043 Q2, Drug Interactions (Advanced)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-502ba04887', 'pharm-drug-interactions', 'mcq', 'Co-administration of levodopa and carbidopa is an example of:', '["Beneficial pharmacokinetic interaction", "Harmful antagonism", "Enzyme induction", "Competitive receptor blockade", "Chemical neutralization"]'::jsonb, 'Beneficial pharmacokinetic interaction', '[]'::jsonb, 'Carbidopa inhibits peripheral dopa decarboxylase and does not cross the blood-brain barrier. Less levodopa is wasted outside the brain, so a much smaller dose is needed and peripheral effects such as nausea are reduced. It alters levodopa''s metabolism, so the interaction is pharmacokinetic.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.044 Q4, Drug Interactions (Advanced)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emergency-management-of-poisoning-938be1e1f2', 'pharm-emergency-management-of-poisoning', 'mcq', 'Activated charcoal is used in poisoning to:', '["Speed up metabolism", "Prevent drug absorption via adsorption in the gut", "Increase renal excretion", "Neutralize the drug chemically", "Block receptors"]'::jsonb, 'Prevent drug absorption via adsorption in the gut', '[]'::jsonb, 'Charcoal''s very large surface area adsorbs many drugs in the gut lumen so that they pass out in the faeces; it works best within an hour of ingestion. It does not bind iron, lithium, alcohols, acids or alkalis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.044 Q5, Drug Interactions (Advanced)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-55683fb074', 'pharm-drug-interactions', 'mcq', 'Which antibiotic is known to inhibit the metabolism of theophylline?', '["Penicillin", "Erythromycin", "Amoxicillin", "Gentamicin", "Ceftriaxone"]'::jsonb, 'Erythromycin', '[]'::jsonb, 'Erythromycin inhibits cytochrome P450 enzymes, reducing theophylline clearance and risking nausea, arrhythmias and seizures. Ciprofloxacin and cimetidine do the same. Beta-lactams and aminoglycosides do not affect hepatic enzymes.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.044 Q6, Drug Interactions (Advanced)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-cca6358233', 'pharm-drug-interactions', 'mcq', 'A patient taking warfarin starts taking rifampicin. What is the likely result?', '["Increased risk of bleeding", "Decreased anticoagulant effect, with a risk of clots", "No change", "Immediate kidney failure", "Severe skin rash"]'::jsonb, 'Decreased anticoagulant effect, with a risk of clots', '[]'::jsonb, 'Rifampicin induces CYP2C9 and other enzymes that metabolise warfarin, so plasma warfarin falls and the INR drops. The warfarin dose must be increased, and then reduced again when rifampicin stops. An increased bleeding risk follows enzyme inhibitors such as metronidazole.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.044 Q7, Drug Interactions (Advanced)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-a9ab64d93c', 'pharm-drug-interactions', 'mcq', '"Summation" is another term for:', '["Synergism", "Additive effect", "Antagonism", "Potentiation", "Tachyphylaxis"]'::jsonb, 'Additive effect', '[]'::jsonb, 'Summation, or addition, means that the combined effect of two drugs equals the sum of their separate effects, as with two NSAIDs. In synergism the combined effect is greater than the sum.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.044 Q8, Drug Interactions (Advanced)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-a760937384', 'pharm-drug-interactions', 'mcq', 'Which of the following describes "pharmacodynamic antagonism"?', '["One drug inducing the metabolism of another", "Two drugs acting on the same receptor with opposite effects", "A drug changing the pH of urine", "A drug forming a complex with another in the gut", "A drug reducing the absorption of another"]'::jsonb, 'Two drugs acting on the same receptor with opposite effects', '[]'::jsonb, 'Pharmacodynamic interactions happen at the site of action: one drug opposes the effect of the other at the receptor or physiological system, as naloxone does to morphine. Enzyme induction, urinary pH changes and chelation in the gut alter the concentration of a drug, so they are pharmacokinetic interactions.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.045 Q9, Drug Interactions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-6f70bd6424', 'pharm-drug-interactions', 'mcq', 'Adrenaline (epinephrine) is added to local anaesthetics in order to:', '["Increase the pH", "Cause local vasoconstriction to prolong the anaesthetic effect", "Block the pain receptors directly", "Speed up metabolism", "Induce sleep"]'::jsonb, 'Cause local vasoconstriction to prolong the anaesthetic effect', '[]'::jsonb, 'Adrenaline constricts local vessels through alpha-1 receptors, slowing removal of the anaesthetic from the injection site. This prolongs the block, lowers peak plasma levels (less systemic toxicity) and reduces bleeding. It has no direct action on the sodium channels that the anaesthetic blocks.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.045 Q10, Drug Interactions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-39fd48df0c', 'pharm-drug-interactions', 'mcq', 'Which interaction leads to "serotonin syndrome"?', '["SSRIs and MAO inhibitors", "Aspirin and ibuprofen", "Penicillin and cephalosporins", "Digoxin and furosemide", "Atropine and propranolol"]'::jsonb, 'SSRIs and MAO inhibitors', '[]'::jsonb, 'SSRIs block serotonin reuptake while MAO inhibitors block its breakdown, so together synaptic serotonin rises dangerously, causing hyperthermia, clonus, agitation and autonomic instability. Digoxin with furosemide is also a harmful pair, but through hypokalaemia-induced digoxin toxicity, not serotonin.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.045 Q11, Drug Interactions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-8672e28577', 'pharm-drug-interactions', 'mcq', 'The "triple whammy" that risks acute kidney injury involves:', '["ACE inhibitor or ARB + diuretic + NSAID", "Penicillin + gentamicin + vancomycin", "Insulin + metformin + sulfonylurea", "Aspirin + clopidogrel + warfarin", "Statin + fibrate + niacin"]'::jsonb, 'ACE inhibitor or ARB + diuretic + NSAID', '[]'::jsonb, 'Diuretics reduce plasma volume, ACE inhibitors or ARBs dilate the efferent arteriole, and NSAIDs constrict the afferent arteriole by blocking prostaglandins. Together they collapse glomerular filtration pressure. Aspirin, clopidogrel and warfarin together is a bleeding risk, not primarily a renal one.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.045 Q12, Drug Interactions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-2925484896', 'pharm-drug-interactions', 'mcq', 'Antacids containing magnesium or aluminium should not be taken at the same time as:', '["Ciprofloxacin", "Paracetamol", "Vitamin D", "Metformin", "Propranolol"]'::jsonb, 'Ciprofloxacin', '[]'::jsonb, 'Divalent and trivalent cations (magnesium, aluminium, calcium, iron) chelate fluoroquinolones and tetracyclines in the gut, forming insoluble complexes that are not absorbed, so the antibiotic may fail. Doses should be separated by at least two hours. The other drugs listed are not chelated.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.045 Q13, Drug Interactions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-c13c17591d', 'pharm-drug-interactions', 'mcq', 'Which of the following increases the toxicity of digoxin?', '["Hyperkalaemia", "Hypokalaemia", "Hypercalcaemia", "Hypomagnesaemia", "Hypokalaemia, hypercalcaemia and hypomagnesaemia"]'::jsonb, 'Hypokalaemia, hypercalcaemia and hypomagnesaemia', '[]'::jsonb, 'Digoxin competes with potassium for the Na+/K+-ATPase, so low potassium (often from loop or thiazide diuretics) increases its binding. High calcium adds to the intracellular calcium overload that drives arrhythmias, and low magnesium also sensitises the myocardium. Hyperkalaemia reduces digoxin binding.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.045 Q14, Drug Interactions. Paper''s option E was "B, C and D"; written out in full so it survives option shuffling.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-d8d0f7844a', 'pharm-drug-interactions', 'mcq', 'A "prodrug" interaction occurs when:', '["An enzyme inhibitor prevents the conversion of a prodrug to its active form", "An inducer speeds up the excretion of an active drug", "Two prodrugs are given together", "A drug is 100% bioavailable", "A drug is given intravenously"]'::jsonb, 'An enzyme inhibitor prevents the conversion of a prodrug to its active form', '[]'::jsonb, 'A prodrug needs metabolic activation, so inhibiting the activating enzyme causes therapeutic failure rather than toxicity. Examples are omeprazole (CYP2C19 inhibitor) reducing activation of clopidogrel, and CYP2D6 inhibitors such as fluoxetine reducing conversion of codeine to morphine.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.046 Q15, Drug Interactions') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paediatric-clinical-pharmacology-c989610af9', 'pharm-paediatric-clinical-pharmacology', 'mcq', 'Which factor primarily contributes to the increased half-life of many drugs in neonates?', '["Increased glomerular filtration rate", "Immature hepatic microsomal enzymes", "Decreased total body water", "Increased plasma albumin levels", "Faster gastric emptying"]'::jsonb, 'Immature hepatic microsomal enzymes', '[]'::jsonb, 'Hepatic cytochrome P450 and glucuronidation activity are low at birth, and glomerular filtration is only about a third of the adult value, so clearance is slow and half-lives are long. Neonates actually have more total body water and less albumin, not the reverse.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.046 Q1, Paediatric Clinical Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paediatric-clinical-pharmacology-f1442d2910', 'pharm-paediatric-clinical-pharmacology', 'mcq', 'The "grey baby syndrome" associated with chloramphenicol is due to the neonate''s inability to:', '["Conjugate the drug with glucuronic acid", "Excrete the drug via the lungs", "Bind the drug to haemoglobin", "Absorb the drug from the gut", "Acetylate the drug"]'::jsonb, 'Conjugate the drug with glucuronic acid', '[]'::jsonb, 'Chloramphenicol is inactivated by hepatic glucuronyl transferase, which is deficient in neonates, and the immature kidney excretes the unconjugated drug poorly. It accumulates and causes vomiting, abdominal distension, ashen-grey cyanosis and circulatory collapse. Acetylation is the pathway for isoniazid and sulfonamides.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.046 Q2, Paediatric Clinical Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paediatric-clinical-pharmacology-96a433f057', 'pharm-paediatric-clinical-pharmacology', 'mcq', 'In infants, the volume of distribution of water-soluble drugs such as gentamicin is generally:', '["Lower than in adults due to less fat", "Higher than in adults due to a higher percentage of total body water", "The same as in adults", "Zero", "Unpredictable"]'::jsonb, 'Higher than in adults due to a higher percentage of total body water', '[]'::jsonb, 'Total body water is about 75 to 80% of weight in a neonate against 60% in an adult, with a large extracellular compartment. Water-soluble drugs spread through this bigger space, so the mg/kg dose of gentamicin is larger while the immature kidney requires a longer dosing interval.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.046 Q3, Paediatric Clinical Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paediatric-clinical-pharmacology-7e2180252a', 'pharm-paediatric-clinical-pharmacology', 'mcq', 'Which of the following is a consequence of immature renal function in a newborn?', '["Rapid clearance of penicillin", "Reduced clearance of digoxin and aminoglycosides", "Increased tubular secretion of organic acids", "Higher urine concentrating ability", "Lower risk of drug toxicity"]'::jsonb, 'Reduced clearance of digoxin and aminoglycosides', '[]'::jsonb, 'Glomerular filtration and tubular secretion are both low at birth and reach adult values over several months. Drugs eliminated mainly by the kidney, such as aminoglycosides, digoxin and penicillins, therefore accumulate unless the dose interval is lengthened. Tubular secretion is reduced, not increased.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.046 Q4, Paediatric Clinical Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paediatric-clinical-pharmacology-55a2a69e35', 'pharm-paediatric-clinical-pharmacology', 'mcq', 'Percutaneous absorption of drugs is much higher in infants because:', '["They have thicker skin layers", "Their skin has a thinner stratum corneum and they have a higher surface-area-to-weight ratio", "They have less blood flow to the skin", "Their skin is more acidic", "They lack sweat glands"]'::jsonb, 'Their skin has a thinner stratum corneum and they have a higher surface-area-to-weight ratio', '[]'::jsonb, 'The stratum corneum, the main barrier to absorption, is thin and well hydrated in infants, and their body surface area is large relative to weight. Topical steroids, hexachlorophene, iodine and alcohols can therefore reach toxic systemic levels, especially under an occlusive nappy.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.046 Q5, Paediatric Clinical Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paediatric-clinical-pharmacology-593c6879c3', 'pharm-paediatric-clinical-pharmacology', 'mcq', '"Kernicterus" in neonates can be triggered by sulfonamides because they:', '["Damage the blood-brain barrier directly", "Displace bilirubin from albumin binding sites", "Inhibit liver enzymes", "Increase the production of red blood cells", "Cause kidney failure"]'::jsonb, 'Displace bilirubin from albumin binding sites', '[]'::jsonb, 'Sulfonamides are highly bound to albumin and compete with unconjugated bilirubin for the same sites. The freed bilirubin crosses the neonate''s immature blood-brain barrier and deposits in the basal ganglia. Ceftriaxone does the same, which is why both are avoided in neonates and late pregnancy.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.047 Q6, Paediatric Clinical Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paediatric-clinical-pharmacology-1a6c545213', 'pharm-paediatric-clinical-pharmacology', 'mcq', 'Tetracyclines are generally avoided in children under 8 years old because they:', '["Cause permanent staining of teeth and affect bone growth", "Lead to sudden infant death syndrome", "Cause acute liver failure", "Are poorly absorbed in children", "Cause hyperactivity"]'::jsonb, 'Cause permanent staining of teeth and affect bone growth', '[]'::jsonb, 'Tetracyclines chelate calcium and are deposited in growing teeth and bone as a tetracycline-calcium-orthophosphate complex. This causes permanent yellow-brown discolouration, enamel hypoplasia and temporary slowing of bone growth. They are well absorbed in children, which is exactly the problem.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.047 Q7, Paediatric Clinical Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paediatric-clinical-pharmacology-318cf60fbc', 'pharm-paediatric-clinical-pharmacology', 'mcq', 'Gastric pH in a newborn at birth is typically:', '["Highly acidic (pH 1.0)", "Neutral or alkaline (pH 6 to 8)", "The same as an adult (pH 2.0)", "Always pH 4.0", "Irrelevant to drug absorption"]'::jsonb, 'Neutral or alkaline (pH 6 to 8)', '[]'::jsonb, 'At birth the stomach contains swallowed amniotic fluid and the pH is near neutral. Acid output stays low for weeks and reaches adult values only after about two to three years. Acid-labile drugs such as penicillin G are therefore better absorbed, while weak acids such as phenobarbital are absorbed less.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.047 Q8, Paediatric Clinical Pharmacology. Added "at birth" to the stem: pH falls transiently within hours of birth.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paediatric-clinical-pharmacology-85553dc861', 'pharm-paediatric-clinical-pharmacology', 'mcq', 'Drug doses in children are most accurately calculated based on:', '["Age in years", "Body surface area", "Weight in pounds", "Height in centimetres", "The parents'' weight"]'::jsonb, 'Body surface area', '[]'::jsonb, 'Body surface area correlates better than weight or age with cardiac output, renal function and metabolic rate, so it gives the most accurate scaling of an adult dose and is used for cytotoxic drugs. Weight-based dosing is the practical everyday method, while age-based rules such as Young''s are the least reliable.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.047 Q9, Paediatric Clinical Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paediatric-clinical-pharmacology-a43c47803e', 'pharm-paediatric-clinical-pharmacology', 'mcq', 'Phase II metabolic pathways such as sulfate conjugation in neonates are:', '["Completely absent", "Relatively well developed compared to glucuronidation", "The primary cause of toxicity", "Faster than in adults", "Only active in the brain"]'::jsonb, 'Relatively well developed compared to glucuronidation', '[]'::jsonb, 'Sulfation is close to adult capacity at birth, whereas glucuronidation takes months to mature. This is why neonates handle paracetamol mainly by sulfate conjugation and are relatively protected, yet cannot clear chloramphenicol or morphine, which depend on glucuronidation.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.047 Q10, Paediatric Clinical Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paediatric-clinical-pharmacology-6d6c097ad4', 'pharm-paediatric-clinical-pharmacology', 'mcq', 'Which drug is known to cause paradoxical excitation instead of sedation in some children?', '["Phenobarbital", "Morphine", "Paracetamol", "Ibuprofen", "Amoxicillin"]'::jsonb, 'Phenobarbital', '[]'::jsonb, 'Barbiturates such as phenobarbital can produce hyperactivity, irritability and aggression rather than sedation in a proportion of children, an example of an age-related pharmacodynamic difference. Benzodiazepines and sedating antihistamines can do the same. Morphine produces sedation and respiratory depression in children as in adults.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.047 Q11, Paediatric Clinical Pharmacology. Paper offered phenobarbital, morphine, chloral hydrate, diazepam and "All of the above"; diazepam and chloral hydrate can also cause paradoxical excitation, so the paper had no single fair answer. Replaced those three options with clear non-sedatives.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paediatric-clinical-pharmacology-33dec28f6d', 'pharm-paediatric-clinical-pharmacology', 'mcq', 'The blood-brain barrier in neonates is:', '["Fully developed at birth", "More permeable, allowing easier entry of drugs into the CNS", "Completely impermeable to all drugs", "Only permeable to water", "Thicker than in adults"]'::jsonb, 'More permeable, allowing easier entry of drugs into the CNS', '[]'::jsonb, 'The neonatal blood-brain barrier is functionally immature and myelination is incomplete, so drugs and bilirubin enter the brain more readily. This explains the greater sensitivity of neonates to opioids and sedatives, and the risk of kernicterus when bilirubin is displaced from albumin.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.048 Q12, Paediatric Clinical Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paediatric-clinical-pharmacology-9e22985fc9', 'pharm-paediatric-clinical-pharmacology', 'mcq', '"Gasping syndrome" in neonates was associated with the use of which preservative in intravenous fluids?', '["Methylparaben", "Benzyl alcohol", "Phenol", "Thimerosal", "Sodium chloride"]'::jsonb, 'Benzyl alcohol', '[]'::jsonb, 'Benzyl alcohol, used as a bacteriostatic preservative in flush solutions, is oxidised to benzoic acid, which premature neonates cannot conjugate with glycine. Accumulation causes metabolic acidosis, gasping respiration, seizures and death. It shows that excipients, not only active drugs, can be toxic in neonates.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.048 Q13, Paediatric Clinical Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paediatric-clinical-pharmacology-d6743cbe16', 'pharm-paediatric-clinical-pharmacology', 'mcq', 'Aspirin is avoided in children with viral infections such as influenza or chickenpox in order to prevent:', '["Cushing''s syndrome", "Reye''s syndrome", "Fanconi syndrome", "Down syndrome", "Nephrotic syndrome"]'::jsonb, 'Reye''s syndrome', '[]'::jsonb, 'Reye''s syndrome is an acute encephalopathy with fatty degeneration of the liver, linked to salicylate use during viral illness in children through mitochondrial injury. Paracetamol is used instead for fever. Fanconi syndrome is a proximal tubular disorder classically caused by outdated tetracyclines.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.048 Q14, Paediatric Clinical Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paediatric-clinical-pharmacology-7202c80254', 'pharm-paediatric-clinical-pharmacology', 'mcq', 'In toddlers aged 1 to 2 years, the metabolic rate for some drugs such as theophylline may be:', '["Slower than in adults", "Faster than in adults", "Non-existent", "Zero-order only", "Constant for life"]'::jsonb, 'Faster than in adults', '[]'::jsonb, 'After the slow neonatal period, hepatic metabolism per kilogram overshoots adult values in young children because the liver is large relative to body weight. Theophylline, phenytoin and carbamazepine therefore need higher mg/kg doses in toddlers than in adults, falling again towards puberty.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.048 Q15, Paediatric Clinical Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-geriatric-clinical-pharmacology-958f256fd6', 'pharm-geriatric-clinical-pharmacology', 'mcq', 'In the elderly, the most significant pharmacokinetic change affecting drug dosing is:', '["Increased gastric acid secretion", "Decline in glomerular filtration rate", "Increased total body water", "Increased liver size", "Decreased body fat"]'::jsonb, 'Decline in glomerular filtration rate', '[]'::jsonb, 'Glomerular filtration falls steadily with age, by roughly 1 mL/min each year after 40, and is the most consistent and clinically important change. Renally cleared drugs such as digoxin, aminoglycosides and lithium accumulate unless doses are reduced. Body water falls and body fat rises with age, the opposite of the distractors.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.048 Q1, Geriatric Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-geriatric-clinical-pharmacology-a337c32c0a', 'pharm-geriatric-clinical-pharmacology', 'mcq', 'The "Beers criteria" is a list used to identify:', '["Safe herbal supplements", "Potentially inappropriate medications for older adults", "Drugs that interact with alcohol", "New drugs in clinical trials", "Optimal doses for paediatric patients"]'::jsonb, 'Potentially inappropriate medications for older adults', '[]'::jsonb, 'The Beers criteria, maintained by the American Geriatrics Society, list drugs whose risks usually outweigh benefits in people over 65, such as long-acting benzodiazepines, strongly anticholinergic drugs and some NSAIDs. The name comes from Dr Mark Beers and has nothing to do with alcohol.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.048 Q2, Geriatric Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-geriatric-clinical-pharmacology-971010c8e4', 'pharm-geriatric-clinical-pharmacology', 'mcq', 'Elderly patients are more sensitive to the CNS effects of benzodiazepines primarily due to:', '["A decreased number of GABA receptors", "Pharmacodynamic changes (increased brain sensitivity)", "Faster metabolism", "Decreased blood-brain barrier permeability", "Increased muscle mass"]'::jsonb, 'Pharmacodynamic changes (increased brain sensitivity)', '[]'::jsonb, 'At the same plasma concentration an older person shows more sedation, confusion and ataxia than a younger one, so the difference is pharmacodynamic. Slower oxidative metabolism of long-acting agents adds to the effect, but metabolism is slower, not faster, in old age.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.049 Q3, Geriatric Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-geriatric-clinical-pharmacology-570443ca09', 'pharm-geriatric-clinical-pharmacology', 'mcq', 'Which change in body composition is typical in geriatric patients?', '["Increased lean body mass", "Decreased body fat percentage", "Decreased total body water and increased body fat", "Increased bone density", "Increased plasma albumin"]'::jsonb, 'Decreased total body water and increased body fat', '[]'::jsonb, 'With ageing, lean mass and total body water fall while the proportion of fat rises. Lipid-soluble drugs such as diazepam gain a larger volume of distribution and a longer half-life, whereas water-soluble drugs such as digoxin and ethanol reach higher concentrations from the same dose.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.049 Q4, Geriatric Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-geriatric-clinical-pharmacology-fda2f69306', 'pharm-geriatric-clinical-pharmacology', 'mcq', 'First-pass metabolism in the elderly is generally:', '["Increased due to larger liver size", "Reduced due to decreased hepatic blood flow", "Unchanged", "Bypassed by all oral drugs", "Doubled"]'::jsonb, 'Reduced due to decreased hepatic blood flow', '[]'::jsonb, 'Liver mass and hepatic blood flow fall by about a third in old age, so less drug is extracted on the first pass. Bioavailability of high-extraction drugs such as propranolol, verapamil and morphine rises, which is one reason to start with lower oral doses.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.049 Q5, Geriatric Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-geriatric-clinical-pharmacology-1f23cd4730', 'pharm-geriatric-clinical-pharmacology', 'mcq', 'The use of anticholinergic drugs in the elderly is associated with an increased risk of:', '["Excessive salivation", "Diarrhoea", "Confusion, urinary retention and falls", "Bradycardia", "Lowering of intraocular pressure"]'::jsonb, 'Confusion, urinary retention and falls', '[]'::jsonb, 'Blocking muscarinic receptors in an ageing brain with reduced cholinergic reserve causes confusion and delirium, while peripheral blockade causes urinary retention (especially with prostatic enlargement), constipation, blurred vision and dry mouth. The typical effects are the opposite of the distractors: dry mouth, constipation and tachycardia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.049 Q6, Geriatric Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-geriatric-clinical-pharmacology-64d5cfc5d3', 'pharm-geriatric-clinical-pharmacology', 'mcq', 'Serum creatinine in the elderly may remain "normal" despite reduced renal function because:', '["The kidneys compensate perfectly", "Creatinine production decreases due to reduced muscle mass", "The elderly eat more protein", "Creatinine is reabsorbed in the elderly", "The liver makes more creatinine"]'::jsonb, 'Creatinine production decreases due to reduced muscle mass', '[]'::jsonb, 'Creatinine comes from muscle, and muscle mass falls with age, so less is produced. A lower production rate and a lower filtration rate cancel out, leaving serum creatinine in the normal range. Creatinine clearance should be estimated, for example with the Cockcroft-Gault equation, before dosing renally cleared drugs.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.049 Q7, Geriatric Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-geriatric-clinical-pharmacology-41b54a56d4', 'pharm-geriatric-clinical-pharmacology', 'mcq', 'Which drug is often avoided in the elderly because of its long half-life and risk of accumulation?', '["Lorazepam", "Diazepam", "Oxazepam", "Temazepam", "Zolpidem"]'::jsonb, 'Diazepam', '[]'::jsonb, 'Diazepam is highly lipid soluble and is oxidised to the active metabolite desmethyldiazepam; in the elderly its half-life can exceed 80 hours, causing prolonged sedation, falls and fractures. Lorazepam, oxazepam and temazepam are simply glucuronidated with no active metabolites, a pathway that is preserved in old age.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.049 Q8, Geriatric Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-geriatric-clinical-pharmacology-2c845819c2', 'pharm-geriatric-clinical-pharmacology', 'mcq', 'Elderly patients are at a higher risk of orthostatic hypotension when taking:', '["Prazosin", "Vitamin C", "Penicillin", "Paracetamol", "Metformin"]'::jsonb, 'Prazosin', '[]'::jsonb, 'Baroreceptor reflexes are blunted in old age, so the elderly cannot compensate for drug-induced vasodilation on standing. Alpha-1 blockers such as prazosin, and also nitrates, diuretics, tricyclic antidepressants and antipsychotics, cause postural falls in blood pressure with dizziness and falls.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.050 Q9, Geriatric Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-geriatric-clinical-pharmacology-ac9eccdaa3', 'pharm-geriatric-clinical-pharmacology', 'mcq', 'A decrease in plasma albumin levels in the elderly can lead to:', '["A decreased free fraction of drugs like warfarin", "An increased free fraction of highly protein-bound drugs", "A lower risk of toxicity", "Faster metabolism of all drugs", "An increased volume of distribution of water-soluble drugs"]'::jsonb, 'An increased free fraction of highly protein-bound drugs', '[]'::jsonb, 'Albumin falls with age, chronic illness and malnutrition. Acidic drugs that are highly bound, such as warfarin, phenytoin and NSAIDs, then have a larger unbound, active fraction, so a total plasma level in the ''therapeutic range'' can still be toxic.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.050 Q10, Geriatric Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-geriatric-clinical-pharmacology-9e0e467956', 'pharm-geriatric-clinical-pharmacology', 'mcq', 'Polypharmacy is defined as:', '["Using one pharmacy for all prescriptions", "The use of multiple medications concurrently by a single patient", "Overdosing on a single drug", "The study of new drug formulations", "Taking only generic drugs"]'::jsonb, 'The use of multiple medications concurrently by a single patient', '[]'::jsonb, 'Polypharmacy means the concurrent use of several medicines by one patient, commonly taken as five or more. It is frequent in the elderly because of multiple illnesses and raises the risk of adverse reactions, drug interactions and poor adherence roughly in proportion to the number of drugs.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.050 Q11, Geriatric Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-geriatric-clinical-pharmacology-d5b066bcc9', 'pharm-geriatric-clinical-pharmacology', 'mcq', 'Which of the following is an example of a "prescribing cascade"?', '["Giving a drug for a specific diagnosis", "A side effect of one drug being misinterpreted as a new medical condition, leading to another drug being prescribed", "Giving a lower dose to an elderly patient", "Stopping a medication when it is no longer needed", "Switching from oral to intravenous therapy"]'::jsonb, 'A side effect of one drug being misinterpreted as a new medical condition, leading to another drug being prescribed', '[]'::jsonb, 'In a prescribing cascade an adverse effect is mistaken for a new disease and treated with a further drug. Classic examples are ankle oedema from amlodipine treated with furosemide, or parkinsonism from metoclopramide treated with levodopa. The right response is to stop or change the first drug.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.050 Q12, Geriatric Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-geriatric-clinical-pharmacology-32dadbe460', 'pharm-geriatric-clinical-pharmacology', 'mcq', 'Elderly patients are more prone to digoxin toxicity because of:', '["Increased heart rate", "Reduced renal clearance and potential hypokalaemia from diuretics", "Increased stomach acid", "Faster liver metabolism", "A large volume of distribution"]'::jsonb, 'Reduced renal clearance and potential hypokalaemia from diuretics', '[]'::jsonb, 'Digoxin is excreted largely unchanged by the kidney, so the age-related fall in glomerular filtration raises its level. The elderly also have less lean mass for it to distribute into and often take diuretics that cause hypokalaemia, which increases digoxin binding to the Na+/K+-ATPase.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.050 Q13, Geriatric Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-geriatric-clinical-pharmacology-b17b7070dc', 'pharm-geriatric-clinical-pharmacology', 'mcq', 'The absorption of vitamin B12 and iron may be reduced in the elderly due to:', '["Increased gastric acidity", "Achlorhydria or reduced gastric acid secretion", "Increased intrinsic factor production", "Rapid intestinal transit", "A high-fibre diet"]'::jsonb, 'Achlorhydria or reduced gastric acid secretion', '[]'::jsonb, 'Atrophic gastritis is common in old age and reduces acid and intrinsic factor. Acid is needed to release B12 from food protein and to keep iron in the soluble ferrous form, so absorption of both falls. Long-term proton pump inhibitors have the same effect.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.050 Q14, Geriatric Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-geriatric-clinical-pharmacology-d3506c4083', 'pharm-geriatric-clinical-pharmacology', 'mcq', 'Which drug is preferred for pain in the elderly to avoid the gastrointestinal and renal risks of NSAIDs?', '["High-dose aspirin", "Naproxen", "Paracetamol", "Indomethacin", "Diclofenac"]'::jsonb, 'Paracetamol', '[]'::jsonb, 'Paracetamol has little peripheral COX inhibition, so it does not cause gastric ulceration, bleeding, fluid retention or the fall in renal blood flow seen with NSAIDs. It is the first-line analgesic for mild to moderate pain in older people; all four other options are NSAIDs.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.051 Q15, Geriatric Pharmacology') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-organization-and-function-of-adrenergi-2a50ffdf0e', 'pharm-organization-and-function-of-adrenergic-cholinergic-and-nanc-neu', 'mcq', 'The primary neurotransmitter released by all preganglionic autonomic fibres is:', '["Noradrenaline", "Adrenaline", "Acetylcholine", "Dopamine", "Serotonin"]'::jsonb, 'Acetylcholine', '[]'::jsonb, 'Every preganglionic neurone, sympathetic or parasympathetic, releases acetylcholine onto nicotinic (Nn) receptors in the ganglion. The two divisions differ only at the postganglionic ending, where sympathetic fibres mostly release noradrenaline and parasympathetic fibres release acetylcholine onto muscarinic receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.051 Q1, Autonomic Nervous System (ANS)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-organization-and-function-of-adrenergi-beb6ac3da7', 'pharm-organization-and-function-of-adrenergic-cholinergic-and-nanc-neu', 'mcq', 'The parasympathetic nervous system is also known as the:', '["Thoracolumbar outflow", "Craniosacral outflow", "Somatic nervous system", "Adrenergic system", "Enteric system"]'::jsonb, 'Craniosacral outflow', '[]'::jsonb, 'Parasympathetic preganglionic fibres leave the CNS in cranial nerves III, VII, IX and X and in sacral segments S2 to S4, hence craniosacral. The sympathetic outflow arises from T1 to L2 or L3 and is called thoracolumbar.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.051 Q2, Autonomic Nervous System (ANS)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-organization-and-function-of-adrenergi-e3e7e8d11a', 'pharm-organization-and-function-of-adrenergic-cholinergic-and-nanc-neu', 'mcq', 'Which receptor is found at the neuromuscular junction of skeletal muscle?', '["Muscarinic M1", "Muscarinic M2", "Nicotinic Nm", "Nicotinic Nn", "Alpha-1"]'::jsonb, 'Nicotinic Nm', '[]'::jsonb, 'The motor end plate carries muscle-type nicotinic receptors (Nm), ligand-gated sodium/potassium channels that are blocked by tubocurarine and suxamethonium. Neuronal nicotinic receptors (Nn) are found in autonomic ganglia and the adrenal medulla and are blocked by hexamethonium instead.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.051 Q3, Autonomic Nervous System (ANS)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-organization-and-function-of-adrenergi-2f30327647', 'pharm-organization-and-function-of-adrenergic-cholinergic-and-nanc-neu', 'mcq', 'Activation of the sympathetic nervous system ("fight or flight") results in:', '["Constriction of the pupils (miosis)", "Dilation of the pupils (mydriasis)", "Increased gastrointestinal motility", "Bradycardia", "Contraction of the bladder detrusor muscle"]'::jsonb, 'Dilation of the pupils (mydriasis)', '[]'::jsonb, 'Sympathetic stimulation contracts the radial (dilator) muscle of the iris through alpha-1 receptors, giving mydriasis. It also raises heart rate, relaxes the gut and the detrusor, and dilates the bronchi. Miosis, increased motility, bradycardia and detrusor contraction are all parasympathetic effects.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.051 Q4, Autonomic Nervous System (ANS)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-organization-and-function-of-adrenergi-721be7a97e', 'pharm-organization-and-function-of-adrenergic-cholinergic-and-nanc-neu', 'mcq', 'Most postganglionic sympathetic fibres release:', '["Acetylcholine", "Noradrenaline", "Adrenaline", "GABA", "Glutamate"]'::jsonb, 'Noradrenaline', '[]'::jsonb, 'Postganglionic sympathetic neurones synthesise and release noradrenaline; they lack the enzyme PNMT needed to make adrenaline, which comes from the adrenal medulla. The exceptions are fibres to eccrine sweat glands, which release acetylcholine, and some renal vascular fibres, which release dopamine.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.051 Q5, Autonomic Nervous System (ANS)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-organization-and-function-of-adrenergi-92857edb14', 'pharm-organization-and-function-of-adrenergic-cholinergic-and-nanc-neu', 'mcq', 'The enzyme responsible for the synthesis of acetylcholine is:', '["Acetylcholinesterase", "Choline acetyltransferase", "Monoamine oxidase", "Tyrosine hydroxylase", "DOPA decarboxylase"]'::jsonb, 'Choline acetyltransferase', '[]'::jsonb, 'Choline acetyltransferase joins choline to acetyl-CoA in the cytoplasm of the nerve terminal. The rate-limiting step is uptake of choline into the terminal, which is blocked by hemicholinium. Acetylcholinesterase does the opposite job, hydrolysing acetylcholine in the synaptic cleft.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.052 Q6, Autonomic Nervous System (ANS)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-organization-and-function-of-adrenergi-2201dca0d8', 'pharm-organization-and-function-of-adrenergic-cholinergic-and-nanc-neu', 'mcq', 'Which sympathetic postganglionic fibres are exceptions and release acetylcholine instead of noradrenaline?', '["Fibres to the heart", "Fibres to the lungs", "Fibres to the eccrine sweat glands", "Fibres to the adrenal medulla", "Fibres to the kidneys"]'::jsonb, 'Fibres to the eccrine sweat glands', '[]'::jsonb, 'Thermoregulatory (eccrine) sweat glands are supplied by sympathetic postganglionic fibres that are cholinergic and act on M3 receptors, which is why atropine stops sweating. The adrenal medulla is supplied by preganglionic fibres, so it is not a postganglionic exception.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.052 Q7, Autonomic Nervous System (ANS)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-organization-and-function-of-adrenergi-108ec9054e', 'pharm-organization-and-function-of-adrenergic-cholinergic-and-nanc-neu', 'mcq', 'The rate-limiting step in the synthesis of catecholamines is:', '["Conversion of DOPA to dopamine", "Conversion of tyrosine to DOPA by tyrosine hydroxylase", "Transport of noradrenaline into vesicles", "Release of noradrenaline from the nerve terminal", "Reuptake into the presynaptic neurone"]'::jsonb, 'Conversion of tyrosine to DOPA by tyrosine hydroxylase', '[]'::jsonb, 'Tyrosine hydroxylase is the slowest enzyme of the pathway and is subject to end-product inhibition by noradrenaline; it is blocked by metyrosine. DOPA decarboxylase, which converts DOPA to dopamine, is fast and non-specific, and vesicular uptake is the step blocked by reserpine.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.052 Q8, Autonomic Nervous System (ANS)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-organization-and-function-of-adrenergi-2781882871', 'pharm-organization-and-function-of-adrenergic-cholinergic-and-nanc-neu', 'mcq', 'Muscarinic receptors are examples of:', '["Ligand-gated ion channels", "G-protein coupled receptors", "Nuclear receptors", "Tyrosine kinase receptors", "Voltage-gated channels"]'::jsonb, 'G-protein coupled receptors', '[]'::jsonb, 'All five muscarinic subtypes are seven-transmembrane G-protein coupled receptors: M1, M3 and M5 couple to Gq (phospholipase C, IP3 and DAG) and M2 and M4 to Gi (reduced cAMP, opening of potassium channels). Nicotinic receptors are the cholinergic ligand-gated ion channels.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.052 Q9, Autonomic Nervous System (ANS)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-organization-and-function-of-adrenergi-0ec2ddda03', 'pharm-organization-and-function-of-adrenergic-cholinergic-and-nanc-neu', 'mcq', 'The main mechanism for termination of the action of noradrenaline in the synapse is:', '["Metabolism by COMT in the synapse", "Metabolism by MAO in the synapse", "Reuptake into the nerve terminal (uptake-1)", "Diffusion into the blood", "Binding to albumin"]'::jsonb, 'Reuptake into the nerve terminal (uptake-1)', '[]'::jsonb, 'About three quarters of released noradrenaline is taken back into the nerve terminal by the noradrenaline transporter (uptake-1), which is blocked by cocaine and tricyclic antidepressants. MAO is intracellular (mitochondrial), not in the synapse, and COMT handles mainly circulating catecholamines.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.052 Q10, Autonomic Nervous System (ANS)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-organization-and-function-of-adrenergi-32cbc235df', 'pharm-organization-and-function-of-adrenergic-cholinergic-and-nanc-neu', 'mcq', 'Which of these receives sympathetic innervation but lacks parasympathetic innervation?', '["Heart", "Eyes", "Most blood vessels", "Salivary glands", "Lungs"]'::jsonb, 'Most blood vessels', '[]'::jsonb, 'Most arterioles and veins have only sympathetic vasoconstrictor fibres, so vascular tone is set by the sympathetic system alone. They do carry uninnervated M3 receptors on the endothelium. The heart, eye, salivary glands and bronchi all receive both divisions.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.052 Q11, Autonomic Nervous System (ANS)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-organization-and-function-of-adrenergi-8b114ee1e1', 'pharm-organization-and-function-of-adrenergic-cholinergic-and-nanc-neu', 'mcq', 'The adrenal medulla is unique because it is innervated by:', '["Postganglionic sympathetic fibres", "Preganglionic sympathetic fibres", "Postganglionic parasympathetic fibres", "Somatic motor neurones", "Sensory neurones"]'::jsonb, 'Preganglionic sympathetic fibres', '[]'::jsonb, 'The adrenal medulla is in effect a modified sympathetic ganglion. Preganglionic fibres in the splanchnic nerves release acetylcholine onto nicotinic receptors on chromaffin cells, which then secrete adrenaline (about 80%) and noradrenaline directly into the blood.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.053 Q12, Autonomic Nervous System (ANS)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-organization-and-function-of-adrenergi-5dfbb686f2', 'pharm-organization-and-function-of-adrenergic-cholinergic-and-nanc-neu', 'mcq', 'Which receptor type mediates the increase in heart rate and contractility?', '["Alpha-1", "Alpha-2", "Beta-1", "Beta-2", "Muscarinic M2"]'::jsonb, 'Beta-1', '[]'::jsonb, 'Beta-1 receptors predominate in the heart; through Gs and cAMP they increase rate at the SA node, conduction at the AV node and force of contraction. M2 receptors do the opposite, slowing the heart, and beta-2 receptors mainly relax bronchial and vascular smooth muscle.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.053 Q13, Autonomic Nervous System (ANS)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-organization-and-function-of-adrenergi-ed576c4fef', 'pharm-organization-and-function-of-adrenergic-cholinergic-and-nanc-neu', 'mcq', 'Botulinum toxin acts by:', '["Blocking acetylcholine receptors", "Inhibiting the release of acetylcholine from the nerve terminal", "Inhibiting acetylcholinesterase", "Stimulating the sympathetic system", "Blocking sodium channels"]'::jsonb, 'Inhibiting the release of acetylcholine from the nerve terminal', '[]'::jsonb, 'Botulinum toxin is a protease that cleaves SNARE proteins such as SNAP-25 and synaptobrevin, so vesicles cannot fuse with the terminal membrane and acetylcholine is not released, giving flaccid paralysis. Receptor blockade is how curare-like drugs work, a different mechanism with a similar result.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.053 Q14, Autonomic Nervous System (ANS)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-organization-and-function-of-adrenergi-031321044f', 'pharm-organization-and-function-of-adrenergic-cholinergic-and-nanc-neu', 'mcq', 'The primary neurotransmitter of the "adrenergic" system is:', '["Acetylcholine", "Noradrenaline", "Serotonin", "Histamine", "Glycine"]'::jsonb, 'Noradrenaline', '[]'::jsonb, 'Adrenergic neurones are those that release noradrenaline, the transmitter at most sympathetic postganglionic endings; adrenaline is mainly a hormone from the adrenal medulla. Acetylcholine is the transmitter of cholinergic neurones, which include all preganglionic and parasympathetic postganglionic fibres.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.053 Q15, Autonomic Nervous System (ANS)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-direct-acting-cholinomimetics-ef71ced851', 'pharm-direct-acting-cholinomimetics', 'mcq', 'Which of the following is a naturally occurring alkaloid used to treat glaucoma by causing miosis?', '["Acetylcholine", "Pilocarpine", "Methacholine", "Bethanechol", "Carbachol"]'::jsonb, 'Pilocarpine', '[]'::jsonb, 'Pilocarpine is a tertiary amine alkaloid from Pilocarpus leaves. It contracts the sphincter pupillae and ciliary muscle, opening the trabecular meshwork and increasing aqueous outflow. Carbachol is also used in the eye, but it is a synthetic choline ester, not a natural alkaloid.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.053 Q1, Direct Acting Cholinomimetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-direct-acting-cholinomimetics-b02b945263', 'pharm-direct-acting-cholinomimetics', 'mcq', 'Bethanechol is primarily used clinically for:', '["Treatment of asthma", "Postoperative urinary retention and abdominal distension", "Alzheimer''s disease", "Tachycardia", "Motion sickness"]'::jsonb, 'Postoperative urinary retention and abdominal distension', '[]'::jsonb, 'Bethanechol is a muscarinic-selective choline ester resistant to cholinesterase, with its main action on the bladder and gut. It contracts the detrusor and stimulates peristalsis, so it is used for non-obstructive urinary retention and postoperative ileus. It would worsen asthma by causing bronchoconstriction.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.053 Q2, Direct Acting Cholinomimetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-direct-acting-cholinomimetics-c8cfeafc2c', 'pharm-direct-acting-cholinomimetics', 'mcq', 'Which muscarinic agonist is used in a "challenge test" to diagnose bronchial hyperreactivity (asthma)?', '["Pilocarpine", "Bethanechol", "Methacholine", "Carbachol", "Muscarine"]'::jsonb, 'Methacholine', '[]'::jsonb, 'Inhaled methacholine stimulates M3 receptors on bronchial smooth muscle. Asthmatic airways are hyperreactive and show a 20% fall in FEV1 at much lower concentrations than normal airways (the PC20). Bethanechol is used for the bladder and gut, pilocarpine for the eye and dry mouth.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.054 Q3, Direct Acting Cholinomimetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-direct-acting-cholinomimetics-9689f0ce6e', 'pharm-direct-acting-cholinomimetics', 'mcq', 'Acetylcholine itself is rarely used clinically because:', '["It is too toxic", "It is very rapidly hydrolysed by acetylcholinesterase and pseudocholinesterase", "It cannot be synthesised", "It only acts on nicotinic receptors", "It causes severe constipation"]'::jsonb, 'It is very rapidly hydrolysed by acetylcholinesterase and pseudocholinesterase', '[]'::jsonb, 'Acetylcholine is destroyed within seconds by acetylcholinesterase at synapses and by butyrylcholinesterase in plasma, and it acts non-selectively on every muscarinic and nicotinic receptor. Its only use is intraocular, to produce rapid miosis during cataract surgery.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.054 Q4, Direct Acting Cholinomimetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-direct-acting-cholinomimetics-96e3da09ab', 'pharm-direct-acting-cholinomimetics', 'mcq', 'Muscarinic effects of cholinomimetic drugs include all of the following EXCEPT:', '["Bradycardia", "Increased sweating", "Mydriasis", "Bronchoconstriction", "Increased gastrointestinal motility"]'::jsonb, 'Mydriasis', '[]'::jsonb, 'Muscarinic stimulation contracts the sphincter pupillae and so causes miosis, not mydriasis. Pupil dilation is produced by antimuscarinics such as atropine or by alpha-1 agonists. The other effects listed are typical M2 (bradycardia) and M3 (glands and smooth muscle) responses.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.054 Q5, Direct Acting Cholinomimetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-direct-acting-cholinomimetics-09a2d377ea', 'pharm-direct-acting-cholinomimetics', 'mcq', 'Which direct-acting cholinergic agonist has both significant muscarinic and nicotinic activity?', '["Bethanechol", "Pilocarpine", "Carbachol", "Methacholine", "Muscarine"]'::jsonb, 'Carbachol', '[]'::jsonb, 'Carbachol is a carbamate ester of choline that is resistant to cholinesterase and stimulates both muscarinic and nicotinic receptors, so it is restricted to topical use in glaucoma. Bethanechol has the same carbamate group but an added beta-methyl group that removes nicotinic activity.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.054 Q6, Direct Acting Cholinomimetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-direct-acting-cholinomimetics-3d27bfc538', 'pharm-direct-acting-cholinomimetics', 'mcq', 'Contraindications to the use of muscarinic agonists include:', '["Glaucoma", "Bronchial asthma", "Paralytic ileus", "Urinary retention", "Xerostomia (dry mouth)"]'::jsonb, 'Bronchial asthma', '[]'::jsonb, 'Muscarinic agonists constrict the bronchi and increase bronchial secretions through M3 receptors, so they can precipitate an asthma attack. They are also avoided in peptic ulcer, bradycardia and mechanical bowel or bladder obstruction. The other four options are actually indications for these drugs.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.054 Q7, Direct Acting Cholinomimetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-direct-acting-cholinomimetics-5a4069d919', 'pharm-direct-acting-cholinomimetics', 'mcq', 'Sjogren''s syndrome, characterised by dry eyes and dry mouth, can be treated with:', '["Atropine", "Pilocarpine", "Scopolamine", "Ipratropium", "Propranolol"]'::jsonb, 'Pilocarpine', '[]'::jsonb, 'Oral pilocarpine and the newer M3 agonist cevimeline stimulate residual salivary and lacrimal gland tissue, relieving xerostomia in Sjogren''s syndrome and after head and neck radiotherapy. Atropine, scopolamine and ipratropium are antimuscarinics and would make the dryness worse.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.054 Q8, Direct Acting Cholinomimetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-direct-acting-cholinomimetics-16a71badde', 'pharm-direct-acting-cholinomimetics', 'mcq', 'Which of the following describes the effect of pilocarpine on the eye?', '["Contraction of the radial muscle (mydriasis)", "Contraction of the sphincter pupillae (miosis) and of the ciliary muscle", "An increase in intraocular pressure", "Paralysis of accommodation (cycloplegia)", "Closure of the canal of Schlemm"]'::jsonb, 'Contraction of the sphincter pupillae (miosis) and of the ciliary muscle', '[]'::jsonb, 'Pilocarpine stimulates M3 receptors on the sphincter pupillae, giving miosis, and on the ciliary muscle, giving accommodation for near vision. Both actions open the drainage angle and the trabecular meshwork, so intraocular pressure falls. Cycloplegia is the effect of atropine.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.055 Q9, Direct Acting Cholinomimetics. Option E reworded from "Dilation of the canal of Schlemm" (which pilocarpine does help open) to a clearly wrong statement.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-direct-acting-cholinomimetics-98cb627a69', 'pharm-direct-acting-cholinomimetics', 'mcq', 'The toxicity of muscarinic agonists can be reversed by:', '["Neostigmine", "Propranolol", "Atropine", "Adrenaline", "Acetylcholine"]'::jsonb, 'Atropine', '[]'::jsonb, 'Atropine is a competitive antagonist at all muscarinic receptors and reverses the bradycardia, bronchoconstriction, salivation and diarrhoea of muscarinic excess. Neostigmine would worsen matters by raising acetylcholine. Adrenaline only opposes some effects physiologically.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.055 Q10, Direct Acting Cholinomimetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-direct-acting-cholinomimetics-c407241bc3', 'pharm-direct-acting-cholinomimetics', 'mcq', 'Bethanechol is "muscarinic selective". This means it has little to no effect on:', '["The bladder", "The heart", "Nicotinic receptors at the neuromuscular junction or ganglia", "Sweat glands", "Salivary glands"]'::jsonb, 'Nicotinic receptors at the neuromuscular junction or ganglia', '[]'::jsonb, 'The beta-methyl group on bethanechol abolishes nicotinic activity, so it does not stimulate ganglia or skeletal muscle. It still acts on every tissue with muscarinic receptors, including bladder, gut, glands and to a lesser degree the heart.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.055 Q11, Direct Acting Cholinomimetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-direct-acting-cholinomimetics-8ee301e99b', 'pharm-direct-acting-cholinomimetics', 'mcq', 'Which of the following is a choline ester?', '["Pilocarpine", "Nicotine", "Methacholine", "Lobeline", "Muscarine"]'::jsonb, 'Methacholine', '[]'::jsonb, 'The choline esters are acetylcholine, methacholine, carbachol and bethanechol: quaternary ammonium compounds that are poorly absorbed and do not enter the brain. Pilocarpine, nicotine, lobeline and muscarine are plant or fungal alkaloids, the other chemical group of direct cholinomimetics.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.055 Q12, Direct Acting Cholinomimetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-direct-acting-cholinomimetics-1d0eec7ccb', 'pharm-direct-acting-cholinomimetics', 'mcq', 'Cholinomimetic alkaloids like nicotine act primarily on:', '["Muscarinic receptors", "Nicotinic receptors in the CNS and ganglia", "Adrenergic receptors", "Dopamine receptors", "Serotonin receptors"]'::jsonb, 'Nicotinic receptors in the CNS and ganglia', '[]'::jsonb, 'Nicotine stimulates neuronal nicotinic receptors in autonomic ganglia, the adrenal medulla and the brain, and at high doses blocks them by persistent depolarisation. Its rewarding effect comes from nicotinic receptors on dopaminergic neurones, but it does not bind dopamine receptors itself.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.055 Q13, Direct Acting Cholinomimetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-direct-acting-cholinomimetics-6c683f731d', 'pharm-direct-acting-cholinomimetics', 'mcq', 'Overdose of muscarine, from certain mushrooms, leads to:', '["Extreme dry mouth", "Tachycardia", "Salivation, lacrimation, urination and diarrhoea", "Hypertension", "Constipation"]'::jsonb, 'Salivation, lacrimation, urination and diarrhoea', '[]'::jsonb, 'Inocybe and Clitocybe mushrooms contain muscarine, a pure muscarinic agonist. Within 30 to 60 minutes it causes salivation, lacrimation, urination, diarrhoea, sweating, miosis, bronchospasm and bradycardia, all reversed by atropine. Dry mouth and tachycardia are features of atropine-like poisoning.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.055 Q14, Direct Acting Cholinomimetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-direct-acting-cholinomimetics-71914b4c65', 'pharm-direct-acting-cholinomimetics', 'mcq', 'Varenicline is a partial agonist used for:', '["Glaucoma", "Smoking cessation", "Urinary retention", "Alzheimer''s disease", "Myasthenia gravis"]'::jsonb, 'Smoking cessation', '[]'::jsonb, 'Varenicline is a partial agonist at alpha-4 beta-2 nicotinic receptors in the brain. It gives enough stimulation to ease craving and withdrawal, while occupying the receptor so that nicotine from a cigarette produces less reward.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.056 Q15, Direct Acting Cholinomimetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-indirect-acting-cholinomimetics-6b43b98d30', 'pharm-indirect-acting-cholinomimetics', 'mcq', 'The mechanism of action of physostigmine is:', '["Direct stimulation of muscarinic receptors", "Reversible inhibition of acetylcholinesterase", "Irreversible inhibition of acetylcholinesterase", "Blocking the reuptake of choline", "Stimulation of acetylcholine release"]'::jsonb, 'Reversible inhibition of acetylcholinesterase', '[]'::jsonb, 'Physostigmine is a carbamate that carbamylates the active site of acetylcholinesterase; the bond is hydrolysed over 30 minutes to a few hours, so inhibition is reversible. Irreversible inhibition is the property of organophosphates, which phosphorylate the enzyme.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.056 Q1, Indirect Acting Cholinomimetics (Anticholinesterases)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-indirect-acting-cholinomimetics-6f4153ef38', 'pharm-indirect-acting-cholinomimetics', 'mcq', 'Which anticholinesterase is a quaternary compound and does NOT cross the blood-brain barrier?', '["Physostigmine", "Neostigmine", "Donepezil", "Rivastigmine", "Galantamine"]'::jsonb, 'Neostigmine', '[]'::jsonb, 'Neostigmine carries a permanently charged quaternary nitrogen, so it is poorly absorbed orally and stays out of the CNS; pyridostigmine and edrophonium are similar. Physostigmine and the Alzheimer''s drugs are lipid-soluble and enter the brain.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.056 Q2, Indirect Acting Cholinomimetics (Anticholinesterases)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-indirect-acting-cholinomimetics-71df16e4bc', 'pharm-indirect-acting-cholinomimetics', 'mcq', 'Edrophonium is used in the "Tensilon test" to diagnose:', '["Glaucoma", "Organophosphate poisoning", "Myasthenia gravis", "Alzheimer''s disease", "Parkinson''s disease"]'::jsonb, 'Myasthenia gravis', '[]'::jsonb, 'Edrophonium is a very short-acting anticholinesterase (5 to 15 minutes). Given intravenously it briefly raises acetylcholine at the motor end plate, producing a rapid, transient improvement in muscle strength in myasthenia gravis. It also distinguishes a myasthenic crisis (improves) from a cholinergic crisis (worsens).', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.056 Q3, Indirect Acting Cholinomimetics (Anticholinesterases)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-indirect-acting-cholinomimetics-828f7ae3aa', 'pharm-indirect-acting-cholinomimetics', 'mcq', 'The preferred drug for treating the CNS toxicity of atropine overdose is:', '["Neostigmine", "Physostigmine", "Pyridostigmine", "Edrophonium", "Pralidoxime"]'::jsonb, 'Physostigmine', '[]'::jsonb, 'Physostigmine is a tertiary amine that crosses the blood-brain barrier, raising acetylcholine centrally as well as peripherally to overcome atropine''s competitive block and reverse delirium and hyperthermia. Neostigmine and pyridostigmine are quaternary and would correct only the peripheral signs.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.056 Q4, Indirect Acting Cholinomimetics (Anticholinesterases)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-indirect-acting-cholinomimetics-9d66bb7b54', 'pharm-indirect-acting-cholinomimetics', 'mcq', 'Organophosphates such as malathion or sarin are:', '["Reversible anticholinesterases", "Irreversible anticholinesterases", "Muscarinic antagonists", "Adrenergic agonists", "Neuromuscular blockers"]'::jsonb, 'Irreversible anticholinesterases', '[]'::jsonb, 'Organophosphates phosphorylate the serine at the active site of acetylcholinesterase, forming a very stable covalent bond. Enzyme activity returns only when new enzyme is made, unless an oxime is given early. Carbamates such as neostigmine are the reversible inhibitors.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.056 Q5, Indirect Acting Cholinomimetics (Anticholinesterases)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-indirect-acting-cholinomimetics-9cc1dbb6d7', 'pharm-indirect-acting-cholinomimetics', 'mcq', '"Ageing" of the enzyme-inhibitor complex is a characteristic of:', '["Neostigmine", "Organophosphate binding to acetylcholinesterase", "Edrophonium", "Pilocarpine", "Atropine"]'::jsonb, 'Organophosphate binding to acetylcholinesterase', '[]'::jsonb, 'After an organophosphate phosphorylates acetylcholinesterase, one alkyl group is lost from the phosphate, strengthening the phosphorus-enzyme bond. Once this ageing has happened, oximes such as pralidoxime can no longer regenerate the enzyme. Ageing takes minutes with soman but hours with most insecticides.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.057 Q6, Indirect Acting Cholinomimetics (Anticholinesterases)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-indirect-acting-cholinomimetics-f640bca934', 'pharm-indirect-acting-cholinomimetics', 'mcq', 'The specific antidote used to reactivate phosphorylated acetylcholinesterase, if given early, is:', '["Atropine", "Pralidoxime", "Diazepam", "Activated charcoal", "Naloxone"]'::jsonb, 'Pralidoxime', '[]'::jsonb, 'Pralidoxime (2-PAM) is an oxime whose nucleophilic group pulls the phosphate off the enzyme, restoring activity, provided ageing has not occurred. Atropine is essential too, but it only blocks muscarinic receptors; it does not regenerate the enzyme or relieve nicotinic muscle weakness.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.057 Q7, Indirect Acting Cholinomimetics (Anticholinesterases)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-indirect-acting-cholinomimetics-646d2c49bc', 'pharm-indirect-acting-cholinomimetics', 'mcq', 'Which drug is commonly used for the long-term treatment of myasthenia gravis?', '["Edrophonium", "Pyridostigmine", "Physostigmine", "Suxamethonium", "Tubocurarine"]'::jsonb, 'Pyridostigmine', '[]'::jsonb, 'Pyridostigmine is an oral quaternary anticholinesterase lasting 3 to 6 hours, which raises acetylcholine at the depleted nicotinic receptors of the motor end plate. Edrophonium is too short-acting and was used only for diagnosis; the neuromuscular blockers would worsen weakness.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.057 Q8, Indirect Acting Cholinomimetics (Anticholinesterases)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-indirect-acting-cholinomimetics-9b1579415d', 'pharm-indirect-acting-cholinomimetics', 'mcq', 'Donepezil and rivastigmine are used primarily to treat:', '["Glaucoma", "Postoperative ileus", "Alzheimer''s disease", "Myasthenia gravis", "Nerve gas poisoning"]'::jsonb, 'Alzheimer''s disease', '[]'::jsonb, 'These are lipid-soluble, centrally acting cholinesterase inhibitors. Alzheimer''s disease involves loss of cholinergic neurones from the nucleus basalis, and raising cortical acetylcholine gives modest symptomatic improvement in memory and function without altering the course of the disease.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.057 Q9, Indirect Acting Cholinomimetics (Anticholinesterases)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-indirect-acting-cholinomimetics-7986dfcd92', 'pharm-indirect-acting-cholinomimetics', 'mcq', 'A "cholinergic crisis", caused by too much anticholinesterase, is characterised by:', '["Improved muscle strength", "Muscle weakness and paralysis due to persistent depolarisation", "Severe dry skin", "Tachycardia", "Mydriasis"]'::jsonb, 'Muscle weakness and paralysis due to persistent depolarisation', '[]'::jsonb, 'Excess acetylcholine keeps the motor end plate depolarised, so the muscle becomes unresponsive (a depolarising block), and weakness is accompanied by muscarinic signs: salivation, sweating, miosis, bradycardia and diarrhoea. Dry skin, tachycardia and mydriasis point instead to antimuscarinic poisoning.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.057 Q10, Indirect Acting Cholinomimetics (Anticholinesterases)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-indirect-acting-cholinomimetics-459a4dacc4', 'pharm-indirect-acting-cholinomimetics', 'mcq', 'Which effect is NOT seen in organophosphate poisoning?', '["Pinpoint pupils", "Excessive salivation", "Muscle fasciculations", "Bradycardia", "Constipation"]'::jsonb, 'Constipation', '[]'::jsonb, 'Organophosphate poisoning floods muscarinic and nicotinic receptors with acetylcholine, so gut motility and secretions increase and the patient has diarrhoea and cramps, never constipation. Miosis, salivation and bradycardia are muscarinic signs; fasciculations followed by weakness are nicotinic.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.057 Q11, Indirect Acting Cholinomimetics (Anticholinesterases). Option D simplified from "Hypertension and tachycardia (initial) followed by bradycardia" to "Bradycardia".') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-indirect-acting-cholinomimetics-37660f8d18', 'pharm-indirect-acting-cholinomimetics', 'mcq', 'Physostigmine is a tertiary amine. This property allows it to:', '["Be excreted rapidly by the kidney", "Cross the blood-brain barrier", "Act only on the bladder", "Be used only intravenously", "Avoid all side effects"]'::jsonb, 'Cross the blood-brain barrier', '[]'::jsonb, 'A tertiary amine is uncharged at part of physiological pH and is lipid soluble, so physostigmine is well absorbed and enters the brain. That makes it useful in central anticholinergic poisoning, but also able to cause seizures. Quaternary agents such as neostigmine stay in the periphery.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.058 Q12, Indirect Acting Cholinomimetics (Anticholinesterases)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-indirect-acting-cholinomimetics-5f0f6a8f98', 'pharm-indirect-acting-cholinomimetics', 'mcq', 'Pyridostigmine is preferred over neostigmine for myasthenia gravis because it:', '["Crosses the blood-brain barrier better", "Has a longer duration of action", "Is more potent", "Does not inhibit acetylcholinesterase", "Is available as an inhaler"]'::jsonb, 'Has a longer duration of action', '[]'::jsonb, 'Pyridostigmine acts for 3 to 6 hours against 2 to 4 hours for neostigmine, giving smoother control with fewer doses, and it causes less gastrointestinal upset. Both are quaternary and stay out of the brain, and neostigmine is actually the more potent of the two.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.058 Q13, Indirect Acting Cholinomimetics (Anticholinesterases). Paper''s option D "Has fewer muscarinic side effects" is also defensible, so it was replaced with a clearly wrong option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-indirect-acting-cholinomimetics-b045a513f5', 'pharm-indirect-acting-cholinomimetics', 'mcq', 'Which enzyme is inhibited by neostigmine, physostigmine and the organophosphates?', '["Monoamine oxidase", "Catechol-O-methyltransferase", "Acetylcholinesterase", "Tyrosine hydroxylase", "DNA polymerase"]'::jsonb, 'Acetylcholinesterase', '[]'::jsonb, 'All indirect-acting cholinomimetics inhibit acetylcholinesterase, so acetylcholine accumulates at muscarinic and nicotinic synapses and its effects are prolonged. Monoamine oxidase and COMT are the enzymes that break down catecholamines, not acetylcholine.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.058 Q14, Indirect Acting Cholinomimetics (Anticholinesterases). Stem said "these drugs"; the drugs were named so the question stands alone.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-indirect-acting-cholinomimetics-44b519bfda', 'pharm-indirect-acting-cholinomimetics', 'mcq', 'The primary cause of death in organophosphate poisoning is:', '["Kidney failure", "Cardiac arrest", "Respiratory failure", "Liver necrosis", "Seizures"]'::jsonb, 'Respiratory failure', '[]'::jsonb, 'Death results from respiratory failure with three components: bronchoconstriction and profuse bronchial secretions (muscarinic), paralysis of the diaphragm and intercostal muscles (nicotinic) and depression of the respiratory centre (central). This is why atropine, airway suction and ventilation come first in management.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.058 Q15, Indirect Acting Cholinomimetics (Anticholinesterases)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticholinergics-and-ganglion-blockers-825e60e06e', 'pharm-anticholinergics-and-ganglion-blockers', 'mcq', 'The prototypical muscarinic antagonist is:', '["Neostigmine", "Atropine", "Pilocarpine", "Propranolol", "Pralidoxime"]'::jsonb, 'Atropine', '[]'::jsonb, 'Atropine, an alkaloid from Atropa belladonna, is a competitive antagonist at all muscarinic receptor subtypes and the reference drug of the class. Neostigmine and pilocarpine do the opposite, increasing cholinergic activity.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.058 Q1, Cholinolytics (Antimuscarinics)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticholinergics-and-ganglion-blockers-34beef5d92', 'pharm-anticholinergics-and-ganglion-blockers', 'mcq', 'Which of the following is a clinical effect of atropine on the eye?', '["Miosis and contraction of the ciliary muscle", "Mydriasis and cycloplegia", "Decreased intraocular pressure", "Increased lacrimation", "Opening of the canal of Schlemm"]'::jsonb, 'Mydriasis and cycloplegia', '[]'::jsonb, 'Atropine blocks M3 receptors on the sphincter pupillae, leaving the radial muscle unopposed (mydriasis), and on the ciliary muscle, paralysing accommodation (cycloplegia). The relaxed iris can crowd the drainage angle, raising intraocular pressure in narrow-angle glaucoma, and tear secretion falls.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.058 Q2, Cholinolytics (Antimuscarinics). Option E reworded from "Constriction of the canal of Schlemm" to keep it clearly wrong.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticholinergics-and-ganglion-blockers-6b2b371f48', 'pharm-anticholinergics-and-ganglion-blockers', 'mcq', 'Ipratropium bromide is preferred over atropine for asthma because it:', '["Is more lipid soluble", "Is administered orally", "Is a quaternary ammonium compound with minimal systemic absorption", "Increases mucus secretions", "Stimulates beta-2 receptors"]'::jsonb, 'Is a quaternary ammonium compound with minimal systemic absorption', '[]'::jsonb, 'Ipratropium''s permanent positive charge keeps it in the airway after inhalation, so it blocks bronchial M3 receptors with little systemic or CNS effect and, unlike atropine, does not impair mucociliary clearance. It is less lipid soluble than atropine, which is the point.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.059 Q3, Cholinolytics (Antimuscarinics)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticholinergics-and-ganglion-blockers-53bcb6c351', 'pharm-anticholinergics-and-ganglion-blockers', 'mcq', 'Scopolamine (hyoscine) is primarily used clinically for the prevention of:', '["Glaucoma", "Motion sickness", "Hypertension", "Myasthenia gravis", "Urinary retention"]'::jsonb, 'Motion sickness', '[]'::jsonb, 'Hyoscine enters the brain readily and blocks muscarinic transmission from the vestibular apparatus to the vomiting centre. It is most effective when given before travel, often as a transdermal patch behind the ear. Antimuscarinics would worsen glaucoma and urinary retention.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.059 Q4, Cholinolytics (Antimuscarinics)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticholinergics-and-ganglion-blockers-d246e44bcd', 'pharm-anticholinergics-and-ganglion-blockers', 'mcq', 'Which antimuscarinic is used specifically to reduce bladder overactivity and urge incontinence?', '["Oxybutynin", "Bethanechol", "Edrophonium", "Benztropine", "Tropicamide"]'::jsonb, 'Oxybutynin', '[]'::jsonb, 'Oxybutynin blocks M3 receptors on the detrusor, reducing involuntary contractions and increasing bladder capacity; tolterodine, solifenacin and darifenacin are alternatives. Bethanechol is a muscarinic agonist used for the opposite problem, urinary retention.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.059 Q5, Cholinolytics (Antimuscarinics)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticholinergics-and-ganglion-blockers-df9e2644b8', 'pharm-anticholinergics-and-ganglion-blockers', 'mcq', 'Atropine is contraindicated in patients with:', '["Bradycardia", "Organophosphate poisoning", "Narrow-angle glaucoma", "Mushroom (muscarine) poisoning", "Excessive salivation"]'::jsonb, 'Narrow-angle glaucoma', '[]'::jsonb, 'Mydriasis bunches the iris into a narrow drainage angle and blocks aqueous outflow, precipitating acute angle-closure glaucoma. Atropine is also avoided in prostatic enlargement and paralytic ileus. The other four options are conditions that atropine is used to treat.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.059 Q6, Cholinolytics (Antimuscarinics)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticholinergics-and-ganglion-blockers-1debb97a08', 'pharm-anticholinergics-and-ganglion-blockers', 'mcq', 'The drug used to treat parkinsonian tremor or drug-induced extrapyramidal symptoms is:', '["Atropine", "Benztropine", "Ipratropium", "Glycopyrrolate", "Homatropine"]'::jsonb, 'Benztropine', '[]'::jsonb, 'Benztropine (like trihexyphenidyl/benzhexol) is a centrally acting antimuscarinic that restores the dopamine-acetylcholine balance in the striatum. It helps tremor and rigidity and reverses acute dystonia from antipsychotics. Ipratropium and glycopyrrolate are quaternary and do not reach the brain.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.059 Q7, Cholinolytics (Antimuscarinics)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticholinergics-and-ganglion-blockers-5ff0245482', 'pharm-anticholinergics-and-ganglion-blockers', 'mcq', 'Belladonna poisoning (atropine overdose) is characterised by:', '["Pinpoint pupils and sweating", "Bradycardia and diarrhoea", "\"Hot as a hare, blind as a bat, dry as a bone, red as a beet and mad as a hatter\"", "Excessive salivation and urination", "Hypotension and hypothermia"]'::jsonb, '"Hot as a hare, blind as a bat, dry as a bone, red as a beet and mad as a hatter"', '[]'::jsonb, 'The mnemonic lists the features: hyperthermia from absent sweating, blurred vision from mydriasis and cycloplegia, dry mouth and skin, cutaneous flushing, and delirium with hallucinations. Tachycardia and urinary retention complete the picture. Pinpoint pupils with sweating and salivation indicate cholinergic poisoning instead.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.059 Q8, Cholinolytics (Antimuscarinics)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticholinergics-and-ganglion-blockers-d8a535b358', 'pharm-anticholinergics-and-ganglion-blockers', 'mcq', 'Which of the following is used to produce short-acting mydriasis for ophthalmic examination?', '["Atropine", "Tropicamide", "Scopolamine", "Pilocarpine", "Physostigmine"]'::jsonb, 'Tropicamide', '[]'::jsonb, 'Tropicamide acts within 20 to 30 minutes and wears off in about 6 hours, so it is the usual choice for fundoscopy. Atropine''s mydriasis and cycloplegia last 7 to 10 days, far longer than an examination requires. Pilocarpine and physostigmine constrict the pupil.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.060 Q9, Cholinolytics (Antimuscarinics)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticholinergics-and-ganglion-blockers-e97a662b6e', 'pharm-anticholinergics-and-ganglion-blockers', 'mcq', 'Glycopyrrolate is often used pre-operatively to:', '["Increase gastric acid secretion", "Reduce salivary and respiratory secretions", "Induce sleep", "Increase gastrointestinal motility", "Slow the heart rate"]'::jsonb, 'Reduce salivary and respiratory secretions', '[]'::jsonb, 'Glycopyrrolate is a quaternary antimuscarinic that dries salivary and bronchial secretions and protects against vagal bradycardia during anaesthesia. Because it does not cross the blood-brain barrier it causes no sedation or confusion, unlike hyoscine.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.060 Q10, Cholinolytics (Antimuscarinics). Giveaway option "Stimulate the heart rate to 150 bpm" replaced with "Slow the heart rate".') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticholinergics-and-ganglion-blockers-1fa87fd81d', 'pharm-anticholinergics-and-ganglion-blockers', 'mcq', 'The effect of atropine on the heart at therapeutic doses is:', '["Profound bradycardia", "Tachycardia", "Decreased AV conduction", "No effect", "A reduction in cardiac output"]'::jsonb, 'Tachycardia', '[]'::jsonb, 'Atropine blocks M2 receptors on the SA and AV nodes, removing vagal tone, so heart rate rises and AV conduction speeds up. This is why it is used for symptomatic bradycardia. Very low doses can cause a slight transient slowing, but profound bradycardia does not occur.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.060 Q11, Cholinolytics (Antimuscarinics). Removed the hint ''(by blocking M2 receptors)'' from the answer option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticholinergics-and-ganglion-blockers-08f31194d9', 'pharm-anticholinergics-and-ganglion-blockers', 'mcq', 'Which drug is a tertiary amine antimuscarinic?', '["Ipratropium", "Tiotropium", "Atropine", "Glycopyrrolate", "Propantheline"]'::jsonb, 'Atropine', '[]'::jsonb, 'Atropine, hyoscine, tropicamide and benztropine are tertiary amines: lipid soluble, well absorbed and able to enter the eye and the brain. Ipratropium, tiotropium, glycopyrrolate and propantheline are quaternary ammonium compounds that are poorly absorbed and act peripherally only.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.060 Q12, Cholinolytics (Antimuscarinics)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticholinergics-and-ganglion-blockers-bc98e28b54', 'pharm-anticholinergics-and-ganglion-blockers', 'mcq', 'Antimuscarinics can cause "atropine fever" primarily by:', '["Stimulating the hypothalamus", "Inhibiting sweating", "Increasing muscle activity", "Causing vasodilation", "Increasing metabolic rate"]'::jsonb, 'Inhibiting sweating', '[]'::jsonb, 'Eccrine sweat glands are driven by sympathetic cholinergic fibres acting on M3 receptors. Atropine blocks them, removing evaporative heat loss, and body temperature rises, especially in children and in hot climates. The skin flushing that accompanies it is a compensatory vasodilation, not the cause.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.060 Q13, Cholinolytics (Antimuscarinics)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticholinergics-and-ganglion-blockers-71a40a1ffa', 'pharm-anticholinergics-and-ganglion-blockers', 'mcq', 'In the treatment of peptic ulcers, pirenzepine was used because it is selective for:', '["M1 receptors", "M2 receptors", "M3 receptors", "Nn receptors", "Alpha receptors"]'::jsonb, 'M1 receptors', '[]'::jsonb, 'Pirenzepine blocks M1 receptors on enteric ganglia and enterochromaffin-like cells, reducing vagally driven histamine release and acid secretion with fewer atropine-like side effects. It has been superseded by H2 antagonists and proton pump inhibitors.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.060 Q14, Cholinolytics (Antimuscarinics)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticholinergics-and-ganglion-blockers-0eaba0bbb9', 'pharm-anticholinergics-and-ganglion-blockers', 'mcq', 'Which statement is TRUE regarding scopolamine (hyoscine) compared with atropine?', '["Atropine has more central sedative effects", "Scopolamine has more prominent CNS effects such as sedation and amnesia", "Only atropine crosses the blood-brain barrier", "Scopolamine is only used for the heart", "Neither drug affects the pupil"]'::jsonb, 'Scopolamine has more prominent CNS effects such as sedation and amnesia', '[]'::jsonb, 'Hyoscine crosses the blood-brain barrier more readily and at therapeutic doses causes drowsiness, amnesia and an antiemetic effect. Atropine at clinical doses has little central action and is mildly stimulant in overdose; it has the stronger and longer effect on the heart, gut and bronchi.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.061 Q15, Cholinolytics (Antimuscarinics)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-4d43e7e4dc', 'pharm-sympathomimetics', 'mcq', 'Adrenaline (epinephrine) stimulates which receptors?', '["Alpha-1 only", "Beta-1 and beta-2 only", "Alpha-1, alpha-2, beta-1 and beta-2", "Alpha-1 and alpha-2 only", "Dopamine receptors only"]'::jsonb, 'Alpha-1, alpha-2, beta-1 and beta-2', '[]'::jsonb, 'Adrenaline is an agonist at all alpha and beta adrenoceptors. At low doses beta effects dominate (tachycardia, bronchodilation, vasodilation in muscle); at high doses alpha-1 vasoconstriction takes over. It has no significant action on dopamine receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.061 Q1, Sympathomimetic Drugs (Adrenergic Agonists)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-b877a4d830', 'pharm-sympathomimetics', 'mcq', 'The drug of choice for the treatment of anaphylactic shock is:', '["Noradrenaline", "Adrenaline given intramuscularly", "Isoprenaline", "Phenylephrine", "Salbutamol"]'::jsonb, 'Adrenaline given intramuscularly', '[]'::jsonb, 'Adrenaline reverses every life-threatening feature: alpha-1 vasoconstriction restores blood pressure and reduces laryngeal oedema, beta-1 supports cardiac output, and beta-2 relaxes the bronchi and stabilises mast cells. It is given into the anterolateral thigh, 0.5 mg of 1:1000 in adults. Salbutamol treats only the bronchospasm.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.061 Q2, Sympathomimetic Drugs (Adrenergic Agonists)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-0250ac1295', 'pharm-sympathomimetics', 'mcq', 'Noradrenaline primarily acts on which receptors?', '["Alpha-1, alpha-2 and beta-1, with minimal beta-2 activity", "Beta-1 and beta-2 only", "Alpha-1 only", "Beta-2 only", "Dopamine receptors"]'::jsonb, 'Alpha-1, alpha-2 and beta-1, with minimal beta-2 activity', '[]'::jsonb, 'Noradrenaline is a potent alpha and beta-1 agonist with very little beta-2 action. It therefore causes intense vasoconstriction, raising both systolic and diastolic pressure, with reflex bradycardia, and no bronchodilation. This makes it the vasopressor of choice in septic shock.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.061 Q3, Sympathomimetic Drugs (Adrenergic Agonists)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-1a69d1563a', 'pharm-sympathomimetics', 'mcq', 'Isoprenaline (isoproterenol) is a:', '["Selective alpha-1 agonist", "Non-selective beta agonist (beta-1 and beta-2)", "Selective beta-2 agonist", "Non-selective alpha agonist", "Indirect-acting sympathomimetic"]'::jsonb, 'Non-selective beta agonist (beta-1 and beta-2)', '[]'::jsonb, 'Isoprenaline is a synthetic catecholamine acting on beta-1 and beta-2 receptors with virtually no alpha activity. It raises heart rate and contractility while dilating skeletal muscle vessels, so diastolic pressure falls. It is occasionally used for heart block and bradycardia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.061 Q4, Sympathomimetic Drugs (Adrenergic Agonists)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-628fd51313', 'pharm-sympathomimetics', 'mcq', 'Salbutamol (albuterol) is used in asthma because it is a:', '["Selective beta-1 agonist", "Selective beta-2 agonist", "Selective alpha-1 agonist", "Non-selective beta agonist", "Muscarinic antagonist"]'::jsonb, 'Selective beta-2 agonist', '[]'::jsonb, 'Salbutamol stimulates beta-2 receptors on bronchial smooth muscle, raising cAMP and causing relaxation within minutes. Selectivity spares the heart compared with isoprenaline, a non-selective beta agonist that causes far more tachycardia and arrhythmia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.061 Q5, Sympathomimetic Drugs (Adrenergic Agonists)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-4edcf1b716', 'pharm-sympathomimetics', 'mcq', 'Phenylephrine is commonly used as a:', '["Bronchodilator", "Nasal decongestant", "Treatment for tachycardia", "Muscle relaxant", "Sedative"]'::jsonb, 'Nasal decongestant', '[]'::jsonb, 'Phenylephrine is a selective alpha-1 agonist that constricts the dilated vessels of the nasal mucosa, shrinking it. It is also used as a mydriatic without cycloplegia and as a vasopressor in anaesthesia. Having no beta-2 action, it cannot bronchodilate.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.062 Q6, Sympathomimetic Drugs (Adrenergic Agonists). Removed the hint ''(Alpha-1 agonist)'' from the answer option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-85f4e39a17', 'pharm-sympathomimetics', 'mcq', 'Dopamine at high doses primarily stimulates:', '["D1 receptors", "Beta-1 receptors", "Alpha-1 receptors", "Muscarinic receptors", "Nicotinic receptors"]'::jsonb, 'Alpha-1 receptors', '[]'::jsonb, 'Dopamine''s effects depend on dose: low rates act on D1 receptors, dilating renal and mesenteric vessels; intermediate rates stimulate cardiac beta-1 receptors; above about 10 micrograms/kg/min alpha-1 vasoconstriction predominates, raising blood pressure and reducing renal blood flow.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.062 Q7, Sympathomimetic Drugs (Adrenergic Agonists)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-c0fdd746d0', 'pharm-sympathomimetics', 'mcq', 'Dobutamine is used in acute heart failure because it is relatively selective for:', '["Alpha-1 receptors", "Beta-1 receptors", "Beta-2 receptors", "Alpha-2 receptors", "Dopamine receptors"]'::jsonb, 'Beta-1 receptors', '[]'::jsonb, 'Dobutamine stimulates cardiac beta-1 receptors, increasing contractility and cardiac output with relatively little rise in heart rate or peripheral resistance. Despite the name it does not act on dopamine receptors. It is given by infusion in cardiogenic shock and acute decompensated heart failure.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.062 Q8, Sympathomimetic Drugs (Adrenergic Agonists)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-dfd1cd14b4', 'pharm-sympathomimetics', 'mcq', 'Which sympathomimetic is an indirect-acting drug that displaces stored noradrenaline?', '["Adrenaline", "Tyramine", "Phenylephrine", "Clonidine", "Methoxamine"]'::jsonb, 'Tyramine', '[]'::jsonb, 'Tyramine is taken up into the nerve terminal by uptake-1 and displaces noradrenaline from vesicles, with no action on receptors itself. It is normally destroyed by MAO in the gut and liver, hence the hypertensive ''cheese reaction'' in patients on MAO inhibitors. The other options act directly on receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.062 Q9, Sympathomimetic Drugs (Adrenergic Agonists)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-30d9de24b9', 'pharm-sympathomimetics', 'mcq', 'Ephedrine is distinctive because it:', '["Has only direct action", "Has only indirect action", "Has mixed action (direct and indirect)", "Does not cross the blood-brain barrier", "Is metabolised by COMT"]'::jsonb, 'Has mixed action (direct and indirect)', '[]'::jsonb, 'Ephedrine both stimulates alpha and beta receptors directly and releases stored noradrenaline. It is not a catecholamine, so it resists COMT and MAO, is active orally, lasts for hours and enters the brain. Repeated doses show tachyphylaxis as noradrenaline stores are depleted.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.062 Q10, Sympathomimetic Drugs (Adrenergic Agonists)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-5297b4a044', 'pharm-sympathomimetics', 'mcq', 'Activation of beta-2 receptors results in:', '["Bronchoconstriction", "Bronchodilation and vasodilation in skeletal muscle", "Increased gastrointestinal motility", "Contraction of the sphincter pupillae", "Decreased heart rate"]'::jsonb, 'Bronchodilation and vasodilation in skeletal muscle', '[]'::jsonb, 'Beta-2 receptors couple to Gs, raising cAMP in smooth muscle and causing relaxation of the bronchi, skeletal muscle arterioles and uterus. They also promote glycogenolysis and move potassium into cells. Bronchoconstriction and contraction of the sphincter pupillae are muscarinic M3 effects.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.062 Q11, Sympathomimetic Drugs (Adrenergic Agonists)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympatholytics-7bec5c8b52', 'pharm-sympatholytics', 'mcq', 'Clonidine acts as a sympatholytic in the CNS by being an agonist at:', '["Alpha-1 receptors", "Alpha-2 receptors", "Beta-1 receptors", "Beta-2 receptors", "D2 receptors"]'::jsonb, 'Alpha-2 receptors', '[]'::jsonb, 'Clonidine stimulates alpha-2 receptors (and imidazoline receptors) in the brainstem vasomotor centre, reducing sympathetic outflow, so blood pressure and heart rate fall. Stopping it suddenly causes rebound hypertension. Alpha-1 agonists would raise, not lower, blood pressure.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.062 Q12, Sympathomimetic Drugs (Adrenergic Agonists)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-ca5290fe29', 'pharm-sympathomimetics', 'mcq', 'Which drug is a selective beta-2 agonist with a long duration of action (LABA)?', '["Salbutamol", "Salmeterol", "Terbutaline", "Orciprenaline (metaproterenol)", "Isoprenaline"]'::jsonb, 'Salmeterol', '[]'::jsonb, 'Salmeterol has a long lipophilic side chain that anchors it beside the receptor, giving about 12 hours of bronchodilation; formoterol is the other common LABA. They are used with an inhaled corticosteroid for maintenance, never alone. Salbutamol and terbutaline last only 4 to 6 hours.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.063 Q13, Sympathomimetic Drugs (Adrenergic Agonists)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-5559bca020', 'pharm-sympathomimetics', 'mcq', 'Cocaine increases sympathetic activity by:', '["Directly stimulating alpha receptors", "Inhibiting the reuptake of noradrenaline (uptake-1)", "Inhibiting MAO", "Increasing acetylcholine release", "Stimulating beta-2 receptors"]'::jsonb, 'Inhibiting the reuptake of noradrenaline (uptake-1)', '[]'::jsonb, 'Cocaine blocks the noradrenaline, dopamine and serotonin transporters, so released transmitter stays in the synapse. Peripherally this causes vasoconstriction, hypertension, tachycardia and mydriasis; centrally, dopamine accumulation gives euphoria. It has no direct receptor agonist action.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.063 Q14, Sympathomimetic Drugs (Adrenergic Agonists)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-1ca6084275', 'pharm-sympathomimetics', 'mcq', 'A significant side effect of beta-2 agonists like salbutamol is:', '["Bradycardia", "Muscle tremor and tachycardia", "Constipation", "Hypoglycaemia", "Miosis"]'::jsonb, 'Muscle tremor and tachycardia', '[]'::jsonb, 'Tremor arises from beta-2 receptors in skeletal muscle, and tachycardia from reflex response to vasodilation plus some direct cardiac stimulation. High doses also cause hypokalaemia and a rise, not a fall, in blood glucose through glycogenolysis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.063 Q15, Sympathomimetic Drugs (Adrenergic Agonists)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-c8e16d734a', 'pharm-adrenoceptor-blockers', 'mcq', 'Phenoxybenzamine is:', '["An irreversible, non-selective alpha blocker", "A reversible, selective alpha-1 blocker", "A selective beta blocker", "An alpha-2 agonist", "An indirect agonist"]'::jsonb, 'An irreversible, non-selective alpha blocker', '[]'::jsonb, 'Phenoxybenzamine binds covalently to alpha-1 and alpha-2 receptors, giving a non-competitive block lasting days until new receptors are made. A surge of catecholamines cannot overcome it, which is why it is used before surgery for phaeochromocytoma. Prazosin is the reversible alpha-1 selective drug.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.063 Q1, Sympatholytics (Adrenergic Antagonists - Alpha)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-4f0b70259c', 'pharm-adrenoceptor-blockers', 'mcq', 'Phentolamine is primarily used for:', '["Long-term treatment of hypertension", "Diagnosis and short-term management of phaeochromocytoma", "Asthma", "Glaucoma", "Benign prostatic hyperplasia"]'::jsonb, 'Diagnosis and short-term management of phaeochromocytoma', '[]'::jsonb, 'Phentolamine is a short-acting, competitive, non-selective alpha blocker given intravenously to control hypertensive episodes of phaeochromocytoma, especially during surgery, and to treat extravasation of noradrenaline. Reflex tachycardia makes it unsuitable for long-term hypertension.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.063 Q2, Sympatholytics (Adrenergic Antagonists - Alpha)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-df24279dfd', 'pharm-adrenoceptor-blockers', 'mcq', 'Prazosin is a selective antagonist at:', '["Alpha-1 receptors", "Alpha-2 receptors", "Beta-1 receptors", "Beta-2 receptors", "Muscarinic receptors"]'::jsonb, 'Alpha-1 receptors', '[]'::jsonb, 'Prazosin competitively blocks alpha-1 receptors on arterioles and veins, lowering peripheral resistance. Because presynaptic alpha-2 receptors are spared, the negative feedback on noradrenaline release is kept and reflex tachycardia is less than with non-selective alpha blockers.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.063 Q3, Sympatholytics (Adrenergic Antagonists - Alpha)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-ef4eaab3c3', 'pharm-adrenoceptor-blockers', 'mcq', 'The "first-dose phenomenon" (severe orthostatic hypotension) is associated with:', '["Propranolol", "Prazosin", "Atropine", "Digoxin", "Clonidine"]'::jsonb, 'Prazosin', '[]'::jsonb, 'The first dose of prazosin can cause a sudden fall in blood pressure and syncope 30 to 90 minutes later, from venous and arteriolar dilation without adequate reflex compensation. It is commoner in patients who are volume depleted or on diuretics, so the first dose is small and taken at bedtime.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.064 Q4, Sympatholytics (Adrenergic Antagonists - Alpha)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-ef3f292d4d', 'pharm-adrenoceptor-blockers', 'mcq', 'Tamsulosin is used in benign prostatic hyperplasia because it is relatively selective for:', '["Alpha-1B receptors in blood vessels", "Alpha-1A receptors in the prostate and bladder neck", "Beta-3 receptors", "Alpha-2 receptors", "M3 receptors"]'::jsonb, 'Alpha-1A receptors in the prostate and bladder neck', '[]'::jsonb, 'Alpha-1A receptors mediate contraction of prostatic and bladder-neck smooth muscle; blocking them improves urine flow. Because tamsulosin largely spares vascular alpha-1B receptors it causes less postural hypotension than prazosin, although abnormal ejaculation is common.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.064 Q5, Sympatholytics (Adrenergic Antagonists - Alpha)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-9eb609ff1d', 'pharm-adrenoceptor-blockers', 'mcq', 'Yohimbine is a selective antagonist at:', '["Alpha-1 receptors", "Alpha-2 receptors", "Beta-1 receptors", "Beta-2 receptors", "5-HT receptors"]'::jsonb, 'Alpha-2 receptors', '[]'::jsonb, 'Yohimbine blocks presynaptic alpha-2 receptors, removing the brake on noradrenaline release and so increasing sympathetic outflow, heart rate and blood pressure. It is essentially the pharmacological opposite of clonidine and has little therapeutic use.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.064 Q6, Sympatholytics (Adrenergic Antagonists - Alpha)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-af468814af', 'pharm-adrenoceptor-blockers', 'mcq', 'Alpha blockers are used in phaeochromocytoma to:', '["Prevent a hypertensive crisis during surgery", "Shrink the tumour", "Increase heart rate", "Stop the production of adrenaline", "Induce miosis"]'::jsonb, 'Prevent a hypertensive crisis during surgery', '[]'::jsonb, 'Handling the tumour releases large amounts of catecholamines. Alpha blockade, started one to two weeks beforehand, prevents severe vasoconstriction and allows the contracted blood volume to re-expand. A beta blocker is added only after alpha blockade, to avoid unopposed alpha-mediated vasoconstriction.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.064 Q7, Sympatholytics (Adrenergic Antagonists - Alpha)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-788f8883b9', 'pharm-adrenoceptor-blockers', 'mcq', 'Which of the following is a side effect of non-selective alpha blockers?', '["Bradycardia", "Reflex tachycardia", "Hypertension", "Urinary retention", "Dry mouth"]'::jsonb, 'Reflex tachycardia', '[]'::jsonb, 'The fall in blood pressure triggers a baroreceptor reflex, and blockade of presynaptic alpha-2 receptors removes feedback inhibition, so even more noradrenaline is released onto unblocked cardiac beta-1 receptors. Alpha blockers relieve rather than cause urinary retention.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.064 Q8, Sympatholytics (Adrenergic Antagonists - Alpha). Removed the hint ''(due to Alpha-2 blockade)'' from the answer option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-antagonists-and-ergot-alkalo-0b51663d86', 'pharm-serotonin-antagonists-and-ergot-alkaloids', 'mcq', 'Ergot alkaloids such as ergotamine have complex actions but are primarily used for:', '["Asthma", "Migraine", "Heart failure", "Diabetes", "Insomnia"]'::jsonb, 'Migraine', '[]'::jsonb, 'Ergotamine is a partial agonist at alpha adrenoceptors and 5-HT receptors, including 5-HT1B/1D. It constricts dilated cranial vessels and inhibits trigeminal neurotransmission, aborting an acute migraine attack. Overuse causes peripheral vasospasm and gangrene (ergotism).', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.064 Q9, Sympatholytics (Adrenergic Antagonists - Alpha)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-18778808b4', 'pharm-adrenoceptor-blockers', 'mcq', 'A patient starting prazosin should be advised to:', '["Take the first dose at bedtime", "Take it on an empty stomach", "Avoid all water", "Double the dose if they feel dizzy", "Stop the drug if they have a dry cough"]'::jsonb, 'Take the first dose at bedtime', '[]'::jsonb, 'Taking the first dose lying down at bedtime means the patient is recumbent when the first-dose fall in blood pressure occurs, avoiding syncope. Dizziness is a reason to sit or lie down, not to increase the dose. Dry cough is a side effect of ACE inhibitors.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.065 Q10, Sympatholytics (Adrenergic Antagonists - Alpha)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-76bad4e187', 'pharm-adrenoceptor-blockers', 'mcq', 'Selective alpha-1 blockers cause:', '["Vasoconstriction", "Vasodilation and decreased peripheral resistance", "Increased blood glucose", "Bronchodilation", "Mydriasis"]'::jsonb, 'Vasodilation and decreased peripheral resistance', '[]'::jsonb, 'Alpha-1 receptors mediate contraction of arteriolar and venous smooth muscle, so blocking them dilates both, lowering peripheral resistance and venous return. They also relax the bladder neck and tend to cause miosis rather than mydriasis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.065 Q11, Sympatholytics (Adrenergic Antagonists - Alpha)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-484801d8a9', 'pharm-adrenoceptor-blockers', 'mcq', 'Which drug is used for hypertensive emergencies and blocks both alpha and beta receptors?', '["Propranolol", "Labetalol", "Atenolol", "Phentolamine", "Prazosin"]'::jsonb, 'Labetalol', '[]'::jsonb, 'Labetalol blocks alpha-1 receptors together with beta-1 and beta-2, so it lowers peripheral resistance without reflex tachycardia. Given intravenously it is used in hypertensive emergencies and in severe hypertension of pregnancy. Phentolamine blocks alpha receptors only.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.065 Q12, Sympatholytics (Adrenergic Antagonists - Alpha)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-e25b5d06f7', 'pharm-adrenoceptor-blockers', 'mcq', 'Alpha-2 receptor blockade leads to:', '["Decreased noradrenaline release", "Increased noradrenaline release from nerve terminals", "Decreased heart rate", "Miosis", "Hypotension"]'::jsonb, 'Increased noradrenaline release from nerve terminals', '[]'::jsonb, 'Presynaptic alpha-2 receptors are autoreceptors: noradrenaline acting on them inhibits its own further release. Blocking them, as yohimbine or phentolamine does, removes this negative feedback, so more noradrenaline is released and heart rate rises.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.065 Q13, Sympatholytics (Adrenergic Antagonists - Alpha)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-6c0ce2e63e', 'pharm-adrenoceptor-blockers', 'mcq', 'Doxazosin and terazosin differ from prazosin mainly in their:', '["Receptor selectivity", "Mechanism of action", "Longer half-life", "Route of administration", "Toxicity"]'::jsonb, 'Longer half-life', '[]'::jsonb, 'All three are selective, competitive alpha-1 blockers given orally. Prazosin has a half-life of about 3 hours and needs two or three doses daily, whereas terazosin (about 12 hours) and doxazosin (about 22 hours) allow once-daily dosing and a gentler onset.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.065 Q14, Sympatholytics (Adrenergic Antagonists - Alpha)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-01236fcec7', 'pharm-adrenoceptor-blockers', 'mcq', 'Which of the following is NOT caused by alpha-1 blockade?', '["Postural hypotension", "Nasal congestion", "Failure of ejaculation", "Tachyphylaxis", "Reflex tachycardia"]'::jsonb, 'Tachyphylaxis', '[]'::jsonb, 'Blocking alpha-1 receptors dilates vessels (postural hypotension, a stuffy nose from engorged mucosa, reflex tachycardia) and relaxes the vas deferens and bladder neck (impaired ejaculation). Tachyphylaxis, a rapid loss of response, is a feature of indirect sympathomimetics such as ephedrine, not of alpha blockers.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.065 Q15, Sympatholytics (Adrenergic Antagonists - Alpha)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-500b553c3f', 'pharm-adrenoceptor-blockers', 'mcq', 'Propranolol is a:', '["Selective beta-1 blocker", "Non-selective beta blocker (beta-1 and beta-2)", "Selective beta-2 blocker", "Beta-1 agonist", "Alpha-1 blocker"]'::jsonb, 'Non-selective beta blocker (beta-1 and beta-2)', '[]'::jsonb, 'Propranolol, the prototype, competitively blocks beta-1 and beta-2 receptors equally and has no intrinsic sympathomimetic activity. Blocking beta-2 receptors explains its bronchospasm and cold extremities, which cardioselective drugs such as atenolol cause less.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.066 Q1, Adrenoceptor Blockers (Beta Blockers)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-97fcc3cdc0', 'pharm-adrenoceptor-blockers', 'mcq', 'Which of the following is a cardioselective (beta-1) blocker?', '["Propranolol", "Atenolol", "Nadolol", "Timolol", "Pindolol"]'::jsonb, 'Atenolol', '[]'::jsonb, 'Atenolol, metoprolol, bisoprolol and esmolol preferentially block beta-1 receptors at ordinary doses; selectivity is lost as the dose rises. Propranolol, nadolol, timolol and pindolol are non-selective and block bronchial and vascular beta-2 receptors as well.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.066 Q2, Adrenoceptor Blockers (Beta Blockers)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-5574deb315', 'pharm-adrenoceptor-blockers', 'mcq', 'Beta blockers are contraindicated in patients with:', '["Hypertension", "Angina pectoris", "Bronchial asthma", "Hyperthyroidism", "Myocardial infarction"]'::jsonb, 'Bronchial asthma', '[]'::jsonb, 'Blocking bronchial beta-2 receptors removes sympathetic bronchodilator tone and can trigger severe bronchospasm in asthmatics; even cardioselective agents are not entirely safe. The other four options are recognised indications for a beta blocker.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.066 Q3, Adrenoceptor Blockers (Beta Blockers)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-1679f697b5', 'pharm-adrenoceptor-blockers', 'mcq', 'Timolol is used topically for the treatment of:', '["Conjunctivitis", "Cataracts", "Glaucoma", "Eye infections", "Corneal ulcers"]'::jsonb, 'Glaucoma', '[]'::jsonb, 'Timolol eye drops block beta receptors on the ciliary epithelium, reducing aqueous humour production and lowering intraocular pressure in open-angle glaucoma, without affecting pupil size or accommodation. Enough can be absorbed to provoke bronchospasm or bradycardia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.066 Q4, Adrenoceptor Blockers (Beta Blockers). Removed the hint about reducing aqueous humour production from the answer option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-997e727df8', 'pharm-adrenoceptor-blockers', 'mcq', 'Which beta blocker has intrinsic sympathomimetic activity (ISA)?', '["Propranolol", "Atenolol", "Pindolol", "Metoprolol", "Esmolol"]'::jsonb, 'Pindolol', '[]'::jsonb, 'Pindolol and acebutolol are partial agonists: they weakly stimulate the beta receptor while blocking the stronger effect of catecholamines. They cause less resting bradycardia and less disturbance of lipids, but are not preferred after myocardial infarction.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.066 Q5, Adrenoceptor Blockers (Beta Blockers)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-32d34ceae4', 'pharm-adrenoceptor-blockers', 'mcq', 'The primary reason for using beta blockers after a myocardial infarction is to:', '["Increase heart rate", "Reduce myocardial oxygen demand and prevent arrhythmias", "Increase blood pressure", "Dissolve the clot", "Increase cardiac output"]'::jsonb, 'Reduce myocardial oxygen demand and prevent arrhythmias', '[]'::jsonb, 'By lowering heart rate, contractility and blood pressure, beta blockers cut myocardial oxygen consumption, limit infarct size and suppress catecholamine-driven ventricular arrhythmias, reducing reinfarction and sudden death. Dissolving the clot is the job of thrombolytics.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.066 Q6, Adrenoceptor Blockers (Beta Blockers)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-29c9fd8176', 'pharm-adrenoceptor-blockers', 'mcq', 'Propranolol can mask the symptoms of:', '["Hypertension", "Hypoglycaemia in diabetic patients", "Asthma", "Glaucoma", "Heart failure"]'::jsonb, 'Hypoglycaemia in diabetic patients', '[]'::jsonb, 'Tachycardia, palpitations and tremor are adrenaline-mediated warning signs of hypoglycaemia, and beta blockade suppresses them; sweating persists because it is cholinergic. Non-selective agents also delay recovery by blocking beta-2 mediated glycogenolysis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.067 Q7, Adrenoceptor Blockers (Beta Blockers). Removed the parenthetical example from the answer option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-ad7bdc82a4', 'pharm-adrenoceptor-blockers', 'mcq', 'Which beta blocker has the shortest half-life and is given by intravenous infusion?', '["Nadolol", "Esmolol", "Atenolol", "Metoprolol", "Bisoprolol"]'::jsonb, 'Esmolol', '[]'::jsonb, 'Esmolol has an ester link hydrolysed by red cell esterases, giving a half-life of about 9 minutes. It is titrated by infusion for supraventricular tachycardia and perioperative hypertension. Nadolol has the longest half-life, around 20 hours.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.067 Q8, Adrenoceptor Blockers (Beta Blockers)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-dd74d49aa6', 'pharm-adrenoceptor-blockers', 'mcq', 'Side effects of beta blockers include all of the following EXCEPT:', '["Bradycardia", "Bronchospasm", "Fatigue and cold extremities", "Tremor and palpitations", "Depression and vivid dreams"]'::jsonb, 'Tremor and palpitations', '[]'::jsonb, 'Tremor and palpitations are beta-mediated, so beta blockers relieve them; propranolol is used for essential tremor. The others are predictable effects: beta-1 block slows the heart, beta-2 block constricts bronchi and limb vessels, and lipid-soluble agents enter the brain.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.067 Q9, Adrenoceptor Blockers (Beta Blockers). Paper''s EXCEPT option was hyperglycaemia, but beta blockers can impair glucose tolerance, so it was replaced with an unambiguous option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-3a6c740915', 'pharm-adrenoceptor-blockers', 'mcq', 'Carvedilol is distinctive because it blocks:', '["Beta-1 and beta-2 receptors only", "Beta-1 and alpha-1 receptors only", "Beta-1, beta-2 and alpha-1 receptors", "Beta-1 and muscarinic receptors", "Alpha-1 and alpha-2 receptors only"]'::jsonb, 'Beta-1, beta-2 and alpha-1 receptors', '[]'::jsonb, 'Carvedilol is a non-selective beta blocker with additional alpha-1 blockade, so it lowers heart rate and causes vasodilation; it also has antioxidant properties and reduces mortality in chronic heart failure. Labetalol has the same receptor profile.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.067 Q10, Adrenoceptor Blockers (Beta Blockers)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-4c220f9da0', 'pharm-adrenoceptor-blockers', 'mcq', 'Which beta blocker is preferred in patients with liver disease because it is excreted by the kidneys?', '["Propranolol", "Atenolol", "Metoprolol", "Carvedilol", "Labetalol"]'::jsonb, 'Atenolol', '[]'::jsonb, 'Atenolol is water soluble, undergoes little hepatic metabolism and is excreted unchanged in urine; nadolol and sotalol are similar. Propranolol, metoprolol, carvedilol and labetalol are lipid soluble with extensive first-pass hepatic metabolism.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.067 Q11, Adrenoceptor Blockers (Beta Blockers)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-63a87e6477', 'pharm-adrenoceptor-blockers', 'mcq', 'Beta blockers reduce blood pressure primarily by:', '["Direct vasodilation", "Reducing cardiac output and inhibiting renin release", "Increasing sodium excretion", "Blocking alpha-1 receptors", "Inhibiting ACE"]'::jsonb, 'Reducing cardiac output and inhibiting renin release', '[]'::jsonb, 'Blocking cardiac beta-1 receptors lowers heart rate and contractility, and blocking beta-1 receptors on juxtaglomerular cells reduces renin secretion and hence angiotensin II. Most beta blockers have no direct vasodilator action.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.067 Q12, Adrenoceptor Blockers (Beta Blockers)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-d17e1bd6d7', 'pharm-adrenoceptor-blockers', 'mcq', 'Abrupt withdrawal of beta blockers in a patient with angina can lead to:', '["A sudden drop in blood pressure", "Rebound hypertension and myocardial infarction", "Better exercise tolerance", "Excessive sleepiness", "Increased appetite"]'::jsonb, 'Rebound hypertension and myocardial infarction', '[]'::jsonb, 'Long-term blockade up-regulates beta receptors. If the drug stops suddenly, normal catecholamine levels act on these extra receptors, causing tachycardia, hypertension, worsening angina and arrhythmias. The dose should be tapered over one to two weeks.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.068 Q13, Adrenoceptor Blockers (Beta Blockers)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-7f6f107a3a', 'pharm-adrenoceptor-blockers', 'mcq', 'Lipid-soluble beta blockers such as propranolol are more likely to cause:', '["Kidney stones", "CNS side effects such as nightmares and insomnia", "Skin rashes", "Gastrointestinal bleeding", "Hair loss"]'::jsonb, 'CNS side effects such as nightmares and insomnia', '[]'::jsonb, 'Lipophilic beta blockers cross the blood-brain barrier and cause sleep disturbance, vivid dreams, fatigue and low mood. Water-soluble agents such as atenolol and nadolol penetrate the brain poorly and are preferred if these effects are troublesome.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.068 Q14, Adrenoceptor Blockers (Beta Blockers)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-f0b98e6e36', 'pharm-adrenoceptor-blockers', 'mcq', 'Which drug is a selective beta-1 blocker used in chronic heart failure?', '["Bisoprolol", "Propranolol", "Nadolol", "Phentolamine", "Salbutamol"]'::jsonb, 'Bisoprolol', '[]'::jsonb, 'Bisoprolol, metoprolol succinate and carvedilol are the beta blockers proven to reduce mortality in heart failure with reduced ejection fraction, by protecting the heart from chronic sympathetic drive. Of these bisoprolol is highly beta-1 selective, started low and titrated slowly.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.068 Q15, Adrenoceptor Blockers (Beta Blockers)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-ca9a202764', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Which of the following is the most sensitive period for drug-induced teratogenesis?', '["First 2 weeks (pre-differentiation)", "3rd to 8th week (organogenesis)", "Second trimester", "Third trimester", "During labour"]'::jsonb, '3rd to 8th week (organogenesis)', '[]'::jsonb, 'Organs form between weeks 3 and 8 after conception, so a drug given then can cause major structural malformations. In the first two weeks the effect is ''all or none'': the embryo either dies or recovers fully. Later exposure affects growth and function rather than structure.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.068 Q1, Drugs in Pregnancy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-cdab7ef2d7', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'The FDA pregnancy category "X" indicates that:', '["Studies in animals show no risk", "Human studies show no risk", "The risk of using the drug clearly outweighs any possible benefit", "The drug is safe only in the first trimester", "There is no data available for the drug"]'::jsonb, 'The risk of using the drug clearly outweighs any possible benefit', '[]'::jsonb, 'Category X drugs have proven fetal risk that outweighs any benefit, so they are contraindicated in pregnancy: isotretinoin, thalidomide, methotrexate, warfarin and statins are examples. Category A is the one where controlled human studies show no risk.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.068 Q2, Drugs in Pregnancy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-693ecbb271', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Which antihypertensive is generally considered the drug of choice for chronic hypertension in pregnancy?', '["Lisinopril", "Methyldopa", "Losartan", "Valsartan", "Spironolactone"]'::jsonb, 'Methyldopa', '[]'::jsonb, 'Methyldopa has the longest record of fetal safety, with follow-up of exposed children into childhood; labetalol and nifedipine are the other accepted choices. ACE inhibitors and angiotensin receptor blockers damage the fetal kidney, and spironolactone has anti-androgenic effects on a male fetus.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.068 Q3, Drugs in Pregnancy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-16588abff6', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'ACE inhibitors such as enalapril are contraindicated in pregnancy because they can cause:', '["Phocomelia", "Fetal renal damage and oligohydramnios", "Neural tube defects", "Grey baby syndrome", "Maternal hypertension"]'::jsonb, 'Fetal renal damage and oligohydramnios', '[]'::jsonb, 'The fetal kidney depends on angiotensin II to maintain glomerular filtration. ACE inhibitors in the second and third trimesters cause renal tubular dysgenesis, anuria and oligohydramnios, with lung hypoplasia and skull hypoplasia as consequences.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.069 Q4, Drugs in Pregnancy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-4edff9428d', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Which anticoagulant is preferred in pregnancy because it does not cross the placenta?', '["Warfarin", "Heparin (unfractionated or low molecular weight)", "Dabigatran", "Rivaroxaban", "High-dose aspirin"]'::jsonb, 'Heparin (unfractionated or low molecular weight)', '[]'::jsonb, 'Heparins are large, highly charged molecules that cannot cross the placenta, so they neither anticoagulate nor malform the fetus; low molecular weight heparin is the usual choice. Warfarin is small and lipid soluble, crosses freely and is teratogenic.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.069 Q5, Drugs in Pregnancy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-72d92163c0', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Warfarin use in the first trimester is associated with:', '["Fetal warfarin syndrome (nasal and cartilage hypoplasia)", "Discoloured teeth", "Premature closure of the ductus arteriosus", "Scalp defects", "Masculinisation of female fetuses"]'::jsonb, 'Fetal warfarin syndrome (nasal and cartilage hypoplasia)', '[]'::jsonb, 'Exposure between weeks 6 and 12 inhibits vitamin K dependent bone proteins, giving nasal hypoplasia and stippled epiphyses (chondrodysplasia punctata). Discoloured teeth come from tetracyclines, and scalp defects (aplasia cutis) are linked to carbimazole.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.069 Q6, Drugs in Pregnancy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-600a365851', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Neural tube defects such as spina bifida are a known risk with which antiepileptic drug?', '["Phenytoin", "Sodium valproate", "Ethosuximide", "Gabapentin", "Levetiracetam"]'::jsonb, 'Sodium valproate', '[]'::jsonb, 'Valproate carries a risk of neural tube defects many times the background rate, probably through interference with folate metabolism, and also impairs neurodevelopment. Women needing it are given high-dose folic acid before conception; levetiracetam is one of the safer choices.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.069 Q7, Drugs in Pregnancy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-ed8fc97704', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', '"Fetal hydantoin syndrome" is caused by maternal use of:', '["Valproate", "Phenytoin", "Carbamazepine", "Phenobarbital", "Diazepam"]'::jsonb, 'Phenytoin', '[]'::jsonb, 'Phenytoin is a hydantoin. Exposure in utero causes craniofacial anomalies (cleft lip and palate, broad nasal bridge), hypoplasia of the distal phalanges and nails, growth restriction and learning difficulty. Valproate has its own syndrome dominated by neural tube defects.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.069 Q8, Drugs in Pregnancy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-9f5974aeff', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Which of the following is traditionally the drug of choice for gestational diabetes when diet alone is insufficient?', '["Metformin", "Insulin", "Glimepiride", "Pioglitazone", "Sitagliptin"]'::jsonb, 'Insulin', '[]'::jsonb, 'Insulin does not cross the placenta and gives precise control, so it has long been the standard treatment and remains so in most pharmacology texts. Metformin crosses the placenta; some guidelines now allow it first, which is why the choice is debated.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.069 Q9, Drugs in Pregnancy. Guideline-dependent: some bodies recommend metformin first. Stem reworded to ''traditionally the drug of choice''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-7536309850', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'The use of NSAIDs in the third trimester is avoided primarily because of the risk of:', '["Cleft palate", "Premature closure of the ductus arteriosus", "Spontaneous abortion", "Neural tube defects", "Limb reduction"]'::jsonb, 'Premature closure of the ductus arteriosus', '[]'::jsonb, 'Prostaglandin E2 keeps the fetal ductus arteriosus open. NSAIDs inhibit prostaglandin synthesis and can close it prematurely, causing fetal pulmonary hypertension. They also reduce fetal urine output and can impair labour by inhibiting uterine contractions.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.070 Q10, Drugs in Pregnancy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-a8d52bdbde', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Thalidomide was originally marketed for morning sickness but caused:', '["Deafness", "Phocomelia (seal-like limbs)", "Blindness", "Liver failure", "Mental retardation"]'::jsonb, 'Phocomelia (seal-like limbs)', '[]'::jsonb, 'Thalidomide taken in early pregnancy caused phocomelia, a severe shortening or absence of the long bones so that the hands and feet arise close to the trunk. The disaster of the early 1960s led to the modern system of drug regulation and teratogenicity testing.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.070 Q11, Drugs in Pregnancy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-78846a5ec6', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Which antibiotic is avoided in pregnancy due to the risk of fetal tooth discoloration and bone growth inhibition?', '["Amoxicillin", "Tetracycline", "Erythromycin", "Cephalexin", "Nitrofurantoin"]'::jsonb, 'Tetracycline', '[]'::jsonb, 'Tetracyclines chelate calcium and are deposited in developing teeth and bone, causing permanent yellow-brown staining and slowed bone growth, so they are avoided from the second trimester. Penicillins, cephalosporins and erythromycin are considered safe in pregnancy.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.070 Q12, Drugs in Pregnancy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-6dd6749e99', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Isotretinoin, used for acne, is highly teratogenic and belongs to FDA category:', '["A", "B", "C", "D", "X"]'::jsonb, 'X', '[]'::jsonb, 'Isotretinoin is a retinoid that causes craniofacial, cardiac and CNS malformations, so it is category X and absolutely contraindicated in pregnancy. Women taking it must use reliable contraception and have a negative pregnancy test under formal pregnancy-prevention programmes.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.070 Q13, Drugs in Pregnancy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-a29aadb55b', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Maternal use of diethylstilbestrol (DES) was historically linked to what in female offspring?', '["Heart defects", "Vaginal clear cell adenocarcinoma", "Hypothyroidism", "Polydactyly", "Cleft lip"]'::jsonb, 'Vaginal clear cell adenocarcinoma', '[]'::jsonb, 'DES, a synthetic oestrogen once given to prevent miscarriage, is a transplacental carcinogen. Daughters exposed in utero developed vaginal and cervical clear cell adenocarcinoma in adolescence, as well as structural genital tract abnormalities and later fertility problems.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.070 Q14, Drugs in Pregnancy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-16800550d6', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Which drug is used during labour to induce uterine contractions?', '["Terbutaline", "Oxytocin", "Magnesium sulfate", "Indometacin", "Nifedipine"]'::jsonb, 'Oxytocin', '[]'::jsonb, 'Oxytocin stimulates rhythmic contraction of uterine smooth muscle through specific oxytocin receptors, whose number rises near term, so it is used to induce or augment labour. Terbutaline, magnesium sulfate, indometacin and nifedipine are all tocolytics that relax the uterus.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.070 Q15, Drugs in Pregnancy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-a2215cb401', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'The primary mechanism by which drugs enter breast milk is:', '["Active transport", "Facilitated diffusion", "Passive diffusion", "Pinocytosis", "Filtration"]'::jsonb, 'Passive diffusion', '[]'::jsonb, 'Most drugs cross from maternal plasma into milk by passive diffusion of the un-ionised, unbound, lipid-soluble fraction down a concentration gradient. Because only free drug diffuses, highly protein-bound drugs reach milk poorly.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.071 Q1, Drug Use During Lactation') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-bf6228a2c9', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Which drug property favours its passage into breast milk?', '["High molecular weight", "High protein binding in maternal plasma", "High lipid solubility", "High ionisation at pH 7.4", "Low bioavailability"]'::jsonb, 'High lipid solubility', '[]'::jsonb, 'Lipid-soluble, un-ionised, low molecular weight and poorly protein-bound drugs cross cell membranes most readily and so concentrate in milk, which is rich in fat. High protein binding and high ionisation keep a drug in maternal plasma instead.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.071 Q2, Drug Use During Lactation') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-bd941d19d7', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Breast milk is slightly more acidic than plasma. This causes which type of drugs to be "trapped" in milk?', '["Weakly acidic drugs", "Weakly basic drugs", "Neutral drugs", "Highly polar drugs", "Only drugs with zero protein binding"]'::jsonb, 'Weakly basic drugs', '[]'::jsonb, 'Milk is about pH 7.0 against plasma 7.4. A weak base becomes more ionised in the more acidic milk and so is ''ion trapped'' there, reaching concentrations above those in plasma. Weak acids are correspondingly less concentrated in milk.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.071 Q3, Drug Use During Lactation') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-09a054b491', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'The "milk-to-plasma" (M/P) ratio measures:', '["The rate of drug metabolism in the infant", "The concentration of drug in milk relative to maternal plasma", "The volume of milk produced per day", "The infant''s kidney function", "The fat content of breast milk"]'::jsonb, 'The concentration of drug in milk relative to maternal plasma', '[]'::jsonb, 'The M/P ratio is the drug concentration in milk divided by that in maternal plasma; a ratio above 1 means the drug concentrates in milk. It is only part of the risk assessment, because the actual infant dose also depends on the maternal plasma level and milk volume.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.071 Q4, Drug Use During Lactation') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-3c3448326c', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Which of the following is generally considered safe to use while breastfeeding?', '["Cyclophosphamide", "Lithium", "Paracetamol (acetaminophen)", "Radioactive iodine", "Methotrexate"]'::jsonb, 'Paracetamol (acetaminophen)', '[]'::jsonb, 'Paracetamol passes into milk in tiny amounts and is well tolerated by infants, making it the analgesic of choice. Cytotoxics such as cyclophosphamide and methotrexate, lithium and radioactive iodine are all contraindicated because of serious infant toxicity.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.071 Q5, Drug Use During Lactation') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-db5fc06867', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'The use of tetracyclines during lactation is generally discouraged because of potential:', '["Haemolysis in the infant", "Staining of the infant''s developing teeth", "Nephrotoxicity", "Ototoxicity", "Cardiotoxicity"]'::jsonb, 'Staining of the infant''s developing teeth', '[]'::jsonb, 'Tetracyclines in milk can chelate calcium in the infant''s forming teeth, risking discoloration and enamel defects, the same reason they are avoided in young children, although calcium in milk limits absorption. Short courses are sometimes judged acceptable.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.071 Q6, Drug Use During Lactation') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-e2f783dc8b', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Which drug can suppress lactation by inhibiting prolactin secretion?', '["Metoclopramide", "Bromocriptine", "Chlorpromazine", "Domperidone", "Oxytocin"]'::jsonb, 'Bromocriptine', '[]'::jsonb, 'Bromocriptine is a dopamine D2 agonist, and dopamine is the physiological inhibitor of prolactin release, so it suppresses lactation. Metoclopramide, domperidone and chlorpromazine block dopamine and therefore raise prolactin and can increase milk.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.072 Q7, Drug Use During Lactation') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-68d556764a', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Infants with G6PD deficiency are at risk of haemolysis if the breastfeeding mother takes:', '["Penicillin", "Nitrofurantoin", "Vitamin C", "Digoxin", "Paracetamol"]'::jsonb, 'Nitrofurantoin', '[]'::jsonb, 'Oxidant drugs such as nitrofurantoin, sulfonamides, dapsone and primaquine can trigger haemolysis in a G6PD-deficient infant when passed through milk. The deficient red cell cannot regenerate glutathione to counter oxidative stress, so the cells lyse.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.072 Q8, Drug Use During Lactation. Options reordered; aspirin replaced with paracetamol to keep five plausible distinct options.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-dd7deada7e', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Lithium is usually avoided in breastfeeding because it can cause:', '["Hyperactivity in the infant", "Lithium toxicity with hypotonia, lethargy and cyanosis", "Excessive weight gain", "Early teething", "Hair loss"]'::jsonb, 'Lithium toxicity with hypotonia, lethargy and cyanosis', '[]'::jsonb, 'Lithium passes freely into milk and the infant''s immature kidney clears it slowly, so it accumulates. Signs of infant toxicity include a ''floppy'' hypotonic baby, lethargy, poor feeding, cyanosis and thyroid dysfunction. Infant lithium levels and thyroid function must be monitored if it is used.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.072 Q9, Drug Use During Lactation. Option B reworded from the vague "floppy baby syndrome" (a term usually applied to benzodiazepines) to describe lithium toxicity.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-ff49c60b47', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'To minimise infant exposure, a breastfeeding mother should ideally take a necessary medication:', '["Immediately before breastfeeding", "Immediately after breastfeeding", "Midway between feedings", "Only at night", "With a high-fat meal"]'::jsonb, 'Immediately after breastfeeding', '[]'::jsonb, 'Taking the drug right after a feed gives the longest interval before the next feed, so the maternal plasma and milk levels have fallen from their peak by the time the infant feeds again. This simple timing manoeuvre reduces the dose the infant receives.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.072 Q10, Drug Use During Lactation') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-674a648853', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Which anticoagulant is considered safe during lactation?', '["Warfarin", "Phenindione", "High-dose aspirin", "Dabigatran", "Ethanol"]'::jsonb, 'Warfarin', '[]'::jsonb, 'Warfarin is highly protein-bound, so very little enters milk, and it is regarded as compatible with breastfeeding. Phenindione does appear in milk and has caused infant bleeding, so it is avoided; the direct oral anticoagulants lack safety data in lactation.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.072 Q11, Drug Use During Lactation. Option E ''None are safe'' replaced with ethanol to keep options distinct and factually gradable.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-576af91447', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'The "relative infant dose" (RID) is generally considered safe if it is below:', '["1%", "10%", "50%", "80%", "100%"]'::jsonb, '10%', '[]'::jsonb, 'The relative infant dose expresses the infant''s weight-adjusted dose from milk as a percentage of the mother''s weight-adjusted dose. A value under 10% is the widely used cut-off for likely safety; most drugs fall well below this.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.072 Q12, Drug Use During Lactation') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-76c0aba404', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Which antibiotic class is commonly associated with causing diarrhoea or candidiasis in the breastfed infant?', '["Aminoglycosides", "Penicillins and cephalosporins", "Fluoroquinolones", "Sulfonamides", "Macrolides"]'::jsonb, 'Penicillins and cephalosporins', '[]'::jsonb, 'Beta-lactams reach milk in small amounts but can disturb the infant''s gut flora, causing loose stools or oral and perianal thrush. They remain among the safest antibiotics in lactation; aminoglycosides are poorly absorbed from the infant gut.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.073 Q13, Drug Use During Lactation') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-0a5a28b915', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Maternal use of combined oral contraceptives containing oestrogen can:', '["Increase milk volume", "Decrease milk production and protein content", "Cause infant hirsutism", "Have no effect", "Increase infant growth rate"]'::jsonb, 'Decrease milk production and protein content', '[]'::jsonb, 'Oestrogen reduces the volume and protein content of breast milk, especially if started in the first weeks before lactation is established. Progestogen-only methods are therefore preferred for breastfeeding mothers.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.073 Q14, Drug Use During Lactation') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-in-pregnancy-and-lactation-f7d48b9053', 'pharm-drugs-in-pregnancy-and-lactation', 'mcq', 'Amiodarone is avoided in breastfeeding mothers because of its high iodine content and risk of:', '["Fetal arrhythmias", "Infant thyroid dysfunction", "Liver failure", "Retinal damage", "Seizures"]'::jsonb, 'Infant thyroid dysfunction', '[]'::jsonb, 'Amiodarone and its metabolite accumulate in milk and the molecule is about 37% iodine by weight. The large iodine load and the drug itself can cause neonatal hypothyroidism, so breastfeeding is not advised during treatment.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.073 Q15, Drug Use During Lactation') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-genetic-medicine-578d9f0364', 'pharm-genetic-medicine', 'mcq', 'Gene therapy is defined as:', '["The study of how genes affect drug response", "The introduction, removal or change of genetic material to treat a disease", "The use of herbal medicines to change DNA", "The mapping of the human genome", "The cloning of healthy individuals"]'::jsonb, 'The introduction, removal or change of genetic material to treat a disease', '[]'::jsonb, 'Gene therapy means altering a patient''s genetic material to treat or prevent disease, for instance by adding a working copy of a faulty gene or silencing a harmful one. Studying how genes affect drug response is pharmacogenomics, a different field.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.073 Q1, Gene Therapy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-genetic-medicine-db09946e14', 'pharm-genetic-medicine', 'mcq', 'In gene therapy, a "vector" is:', '["The disease being treated", "The delivery vehicle (usually a virus) used to carry the gene into cells", "The patient receiving the treatment", "The surgical instrument used", "The laboratory where the gene is made"]'::jsonb, 'The delivery vehicle (usually a virus) used to carry the gene into cells', '[]'::jsonb, 'A vector is the carrier that delivers the therapeutic gene into target cells. Modified viruses (retrovirus, lentivirus, adenovirus, adeno-associated virus) are the commonest, as they are efficient at entering cells; non-viral vectors such as liposomes are safer but less efficient.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.073 Q2, Gene Therapy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-genetic-medicine-07610c0259', 'pharm-genetic-medicine', 'mcq', '"Ex vivo" gene therapy involves:', '["Injecting the vector directly into the patient''s body", "Modifying cells outside the body and then transplanting them back", "Using only bacterial DNA", "Treating the patient with pills", "Changing the DNA of the patient''s offspring"]'::jsonb, 'Modifying cells outside the body and then transplanting them back', '[]'::jsonb, 'In the ex vivo approach, cells (often bone marrow stem cells or T cells) are taken from the patient, genetically modified in the laboratory, then returned. This allows selection of successfully modified cells. Injecting the vector straight into the body is the in vivo approach.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.073 Q3, Gene Therapy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-genetic-medicine-56ad423dda', 'pharm-genetic-medicine', 'mcq', 'Which virus is commonly used as a vector because it can integrate its DNA into the host genome?', '["Influenza virus", "Retrovirus (e.g. lentivirus)", "Rhinovirus", "Hepatitis B virus", "Rotavirus"]'::jsonb, 'Retrovirus (e.g. lentivirus)', '[]'::jsonb, 'Retroviruses, including lentiviruses, reverse-transcribe their RNA and integrate the resulting DNA into the host chromosome, giving long-lasting expression in dividing cells. The drawback is insertional mutagenesis, which caused leukaemia in early trials. Adenoviruses stay episomal and give only transient expression.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.074 Q4, Gene Therapy. Option E ''Adenosine deaminase'' (an enzyme, not a virus) replaced with rotavirus.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-genetic-medicine-485ef93c5d', 'pharm-genetic-medicine', 'mcq', '"Germline" gene therapy refers to modifying cells in:', '["The liver", "The brain", "Sperm or egg cells (heritable)", "Muscle tissue", "Skin cells"]'::jsonb, 'Sperm or egg cells (heritable)', '[]'::jsonb, 'Germline therapy alters gametes or the early embryo, so the change is passed to all cells and to future generations. It raises major ethical and safety concerns and is banned for clinical use. Somatic therapy affects only the treated individual''s body cells.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.074 Q5, Gene Therapy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-genetic-medicine-cb4aac859b', 'pharm-genetic-medicine', 'mcq', 'The first approved human gene therapy trial (1990) targeted which condition?', '["Cystic fibrosis", "Adenosine deaminase (ADA) deficiency", "Haemophilia", "Cancer", "Diabetes"]'::jsonb, 'Adenosine deaminase (ADA) deficiency', '[]'::jsonb, 'The landmark 1990 trial treated a girl with severe combined immunodeficiency caused by ADA deficiency, using her own T cells modified to carry a working ADA gene. It was the proof of principle for the field.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.074 Q6, Gene Therapy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-genetic-medicine-84ccf7cdf9', 'pharm-genetic-medicine', 'mcq', 'A major risk of using adenoviral vectors in gene therapy is:', '["Integration into the host genome", "A severe immune and inflammatory response", "They only infect non-dividing cells", "They are too small to carry genes", "They cause immediate hair loss"]'::jsonb, 'A severe immune and inflammatory response', '[]'::jsonb, 'Adenoviruses are highly immunogenic; a strong inflammatory response to the vector caused the death of Jesse Gelsinger in 1999. Unlike retroviruses they do not integrate into the genome, so they carry little insertional mutagenesis risk but give only short-lived expression.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.074 Q7, Gene Therapy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-genetic-medicine-4af2aa4a1d', 'pharm-genetic-medicine', 'mcq', '"Gene silencing" therapy often uses which of the following?', '["Plasmids", "RNA interference (siRNA or miRNA)", "DNA polymerase", "Ribosomes", "Insulin"]'::jsonb, 'RNA interference (siRNA or miRNA)', '[]'::jsonb, 'RNA interference uses small interfering or micro RNA to bind a complementary messenger RNA, marking it for destruction or blocking its translation, so the target protein is not made. This is the basis of drugs such as patisiran for hereditary transthyretin amyloidosis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.074 Q8, Gene Therapy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-genetic-medicine-7daa098c60', 'pharm-genetic-medicine', 'mcq', 'CRISPR-Cas9 is a revolutionary tool used for:', '["Measuring drug levels", "Precise genome editing", "Protein synthesis", "Bacterial staining", "Heart rate monitoring"]'::jsonb, 'Precise genome editing', '[]'::jsonb, 'CRISPR-Cas9 uses a guide RNA to direct the Cas9 nuclease to a chosen DNA sequence, where it makes a cut so that a gene can be disrupted, corrected or inserted. Its precision and ease have transformed genome editing and underlie new therapies for sickle cell disease.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.074 Q9, Gene Therapy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-genetic-medicine-c8a7fb6ff9', 'pharm-genetic-medicine', 'mcq', 'The main challenge of non-viral gene delivery, such as with liposomes, is:', '["High toxicity", "Low efficiency of gene transfer (transfection)", "Risk of viral infection", "Inability to be mass-produced", "They are too expensive"]'::jsonb, 'Low efficiency of gene transfer (transfection)', '[]'::jsonb, 'Non-viral methods such as liposomes and naked DNA are safer and less immunogenic than viruses, but they enter cells and reach the nucleus much less efficiently, so gene expression is low and short-lived. Improving transfection efficiency is the central problem.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.075 Q10, Gene Therapy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-genetic-medicine-b08339280d', 'pharm-genetic-medicine', 'mcq', 'In "somatic" gene therapy:', '["The changes are passed to future generations", "Only the treated individual is affected", "All cells in the body are changed", "Only plant genes are used", "It is currently illegal worldwide"]'::jsonb, 'Only the treated individual is affected', '[]'::jsonb, 'Somatic therapy modifies non-reproductive body cells, so the change affects only the treated patient and is not inherited. This distinguishes it from germline therapy and makes it ethically acceptable and clinically approved.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.075 Q11, Gene Therapy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-genetic-medicine-12716457c8', 'pharm-genetic-medicine', 'mcq', 'Which of the following is a potential application of gene therapy?', '["Replacing a mutated gene that causes disease", "Inactivating a gene that is functioning improperly", "Introducing a new gene to help fight a disease", "Repairing a gene by base or prime editing", "All of these are potential applications"]'::jsonb, 'All of these are potential applications', '[]'::jsonb, 'Gene therapy can add a correct copy of a defective gene, silence an overactive or harmful gene, introduce a wholly new gene (for example a chimeric antigen receptor in T cells against cancer), or directly correct a mutation. All of these strategies are being developed.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.075 Q12, Gene Therapy. Option E ''None of the above'' replaced with gene editing so the correct ''all of these'' choice is coherent.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-genetic-medicine-c72769008e', 'pharm-genetic-medicine', 'mcq', 'Zolgensma is a gene therapy used for the treatment of:', '["Spinal muscular atrophy", "Hypertension", "The common cold", "Malaria", "Obesity"]'::jsonb, 'Spinal muscular atrophy', '[]'::jsonb, 'Zolgensma (onasemnogene abeparvovec) delivers a working copy of the SMN1 gene using an adeno-associated virus vector, treating spinal muscular atrophy in young children. It is one of the first approved in vivo gene therapies and is famous for its very high cost.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.075 Q13, Gene Therapy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-genetic-medicine-f615c952c7', 'pharm-genetic-medicine', 'mcq', 'The term "transfection" refers to:', '["The process of DNA replication", "The introduction of foreign DNA into a eukaryotic cell", "The mutation of a gene", "The protein folding process", "The excretion of a drug"]'::jsonb, 'The introduction of foreign DNA into a eukaryotic cell', '[]'::jsonb, 'Transfection is the deliberate introduction of nucleic acid into a eukaryotic cell by non-viral means such as liposomes or electroporation. When a virus is the carrier the equivalent process is called transduction.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.075 Q14, Gene Therapy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-genetic-medicine-ca6df57726', 'pharm-genetic-medicine', 'mcq', 'A significant ethical concern regarding germline gene therapy is:', '["High cost", "The potential for \"designer babies\" and permanent changes to the human gene pool", "It only works in adults", "It requires too much blood", "It interferes with drug metabolism"]'::jsonb, 'The potential for "designer babies" and permanent changes to the human gene pool', '[]'::jsonb, 'Because germline edits are heritable, they permanently alter the human gene pool and could be used for enhancement rather than disease (''designer babies''), with unforeseeable consequences for descendants who cannot consent. This is why germline editing is prohibited clinically.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.075 Q15, Gene Therapy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-2bc30582b2', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'mcq', 'The term "autacoids" is derived from Greek words meaning:', '["External medicine", "Self-remedy (local hormones)", "Nerve message", "Toxic substance", "Fast action"]'::jsonb, 'Self-remedy (local hormones)', '[]'::jsonb, 'Autacoid comes from the Greek autos (self) and akos (remedy or medicine), reflecting that these substances are the body''s own locally acting agents. They are often called local hormones because they act near where they are made.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.076 Q1, Introduction to Autacoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-c83b1657d0', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'mcq', 'Autacoids differ from circulating hormones because they:', '["Are produced by specialised glands", "Act primarily near their site of synthesis (paracrine/autocrine)", "Have a very long half-life", "Act only on the brain", "Are always proteins"]'::jsonb, 'Act primarily near their site of synthesis (paracrine/autocrine)', '[]'::jsonb, 'Autacoids such as histamine, serotonin, prostaglandins and kinins are made by many tissues and act locally in a paracrine or autocrine fashion, usually with a short half-life. Classic hormones are made by specific glands and travel in the blood to distant targets.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.076 Q2, Introduction to Autacoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-517118e085', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'mcq', 'Which of the following is classified as an "amine" autacoid?', '["Prostaglandins", "Histamine", "Angiotensin", "Leukotrienes", "Bradykinin"]'::jsonb, 'Histamine', '[]'::jsonb, 'Histamine and serotonin are amine autacoids, formed by decarboxylation of amino acids. Prostaglandins and leukotrienes are lipid-derived, while angiotensin and bradykinin are peptides, so they belong to different chemical classes.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.076 Q3, Introduction to Autacoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-28ed8c18d4', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'mcq', 'Which of the following is a "lipid-derived" autacoid?', '["Serotonin", "Histamine", "Eicosanoids (e.g. prostaglandins)", "Substance P", "Gastrin"]'::jsonb, 'Eicosanoids (e.g. prostaglandins)', '[]'::jsonb, 'Eicosanoids, including prostaglandins, thromboxanes and leukotrienes, are derived from the 20-carbon fatty acid arachidonic acid, so they are lipid autacoids. Serotonin and histamine are amines, and substance P and gastrin are peptides.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.076 Q4, Introduction to Autacoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-c00307338b', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'mcq', 'Autacoids are involved in which physiological processes?', '["Inflammation", "Allergic reactions", "Gastric acid secretion", "Pain signalling", "All of the above"]'::jsonb, 'All of the above', '[]'::jsonb, 'Autacoids participate widely: histamine in allergy and acid secretion, prostaglandins and kinins in inflammation and pain, serotonin in gut motility and mood. Because they mediate so many processes, drugs that block their synthesis or receptors are central to pharmacology.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.076 Q5, Introduction to Autacoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-81a08bd84a', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'mcq', 'Which peptide autacoid is a potent vasodilator and is involved in pain?', '["Histamine", "Bradykinin", "Serotonin", "Adrenaline", "Insulin"]'::jsonb, 'Bradykinin', '[]'::jsonb, 'Bradykinin, a kinin peptide generated by kallikrein, dilates vessels, increases capillary permeability and strongly stimulates nociceptive nerve endings, so it is a key mediator of inflammatory pain. Its breakdown by ACE is why ACE inhibitors can cause cough and angio-oedema.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.076 Q6, Introduction to Autacoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-66c2673339', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'mcq', '"Triple response of Lewis" is produced by intradermal injection of:', '["Acetylcholine", "Histamine", "Atropine", "Prostaglandin", "Heparin"]'::jsonb, 'Histamine', '[]'::jsonb, 'Injecting histamine into the skin produces a red spot (local capillary dilation), a flare (axon-reflex arteriolar dilation) and a wheal (oedema from increased permeability). This triple response demonstrates histamine''s vascular actions.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.077 Q7, Introduction to Autacoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-908594d371', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'mcq', 'Which autacoid is found in high concentrations in mast cells and basophils?', '["Angiotensin", "Histamine", "Nitric oxide", "Endothelin", "Vasopressin"]'::jsonb, 'Histamine', '[]'::jsonb, 'Histamine is stored preformed in the granules of mast cells and basophils, bound to heparin, and is released on IgE-mediated allergen contact or by certain drugs. Enterochromaffin-like cells of the stomach are the other major store.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.077 Q8, Introduction to Autacoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-83df658f33', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'mcq', 'The primary precursor for the synthesis of eicosanoids is:', '["Histidine", "Tryptophan", "Arachidonic acid", "Tyrosine", "Cholesterol"]'::jsonb, 'Arachidonic acid', '[]'::jsonb, 'Eicosanoids are made from arachidonic acid, a 20-carbon polyunsaturated fatty acid released from membrane phospholipids by phospholipase A2. Histidine and tryptophan are precursors of histamine and serotonin respectively.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.077 Q9, Introduction to Autacoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-6cac142033', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'mcq', 'Autacoids typically act through:', '["G-protein coupled receptors", "Nuclear receptors", "Passive diffusion into the nucleus", "Binding to haemoglobin", "Ion channels only"]'::jsonb, 'G-protein coupled receptors', '[]'::jsonb, 'Most autacoid receptors, including histamine H1 to H4, the serotonin receptors (except 5-HT3) and the prostanoid receptors, are G-protein coupled, signalling through second messengers. This is why selective receptor antagonists are so useful as drugs.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.077 Q10, Introduction to Autacoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-f99eec1a46', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'mcq', 'Which of the following is NOT an autacoid?', '["Serotonin", "Leukotriene", "Thyroxine", "Cytokine", "Platelet-activating factor"]'::jsonb, 'Thyroxine', '[]'::jsonb, 'Thyroxine is a classic hormone, made by the thyroid gland and carried in the blood to distant tissues, so it is not an autacoid. Serotonin, leukotrienes, cytokines and platelet-activating factor are all locally acting mediators.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.077 Q11, Introduction to Autacoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-d33fe919a9', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'mcq', 'Platelet-activating factor (PAF) is involved in:', '["Bronchodilation", "Platelet aggregation and inflammation", "Decreasing vascular permeability", "Inhibiting labour", "Reducing gastric acid"]'::jsonb, 'Platelet aggregation and inflammation', '[]'::jsonb, 'PAF is a phospholipid mediator released by many inflammatory cells. It aggregates platelets, increases vascular permeability, recruits leukocytes and causes bronchoconstriction, making it an important mediator in asthma, anaphylaxis and shock.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.077 Q12, Introduction to Autacoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-6686451354', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'mcq', 'The physiological role of autacoids becomes "pathological" when:', '["They are produced in normal amounts", "They are released in excess during injury or allergy", "They are not produced at all", "They circulate in the blood for days", "They are used as drugs"]'::jsonb, 'They are released in excess during injury or allergy', '[]'::jsonb, 'At normal levels autacoids regulate blood flow, secretion and host defence. Excessive or inappropriate release, as in anaphylaxis, asthma or inflammation, turns these useful mediators into causes of disease, which is why their antagonists are therapeutic.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.078 Q13, Introduction to Autacoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-e2ecbf02df', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'mcq', 'Angiotensin II is a peptide autacoid known for its role in:', '["Vasodilation", "Vasoconstriction and blood pressure regulation", "Sleep induction", "Glucose metabolism", "Bone growth"]'::jsonb, 'Vasoconstriction and blood pressure regulation', '[]'::jsonb, 'Angiotensin II is a powerful vasoconstrictor that also stimulates aldosterone release and renal sodium retention, raising blood pressure. The renin-angiotensin system is the target of ACE inhibitors and angiotensin receptor blockers.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.078 Q14, Introduction to Autacoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-bbfe2ea62e', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'mcq', 'Many drugs, such as NSAIDs and antihistamines, work by:', '["Increasing autacoid synthesis", "Blocking the synthesis or receptors of autacoids", "Mimicking the effect of autacoids", "Transporting autacoids to the liver", "Binding to albumin"]'::jsonb, 'Blocking the synthesis or receptors of autacoids', '[]'::jsonb, 'NSAIDs block cyclooxygenase and so reduce prostaglandin synthesis, while antihistamines block histamine H1 receptors. Both act by opposing autacoids, illustrating the general therapeutic strategy of inhibiting autacoid production or blocking their receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.078 Q15, Introduction to Autacoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-4e4665c321', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'mcq', 'Histamine is formed by the decarboxylation of which amino acid?', '["Tyrosine", "Tryptophan", "Histidine", "Arginine", "Phenylalanine"]'::jsonb, 'Histidine', '[]'::jsonb, 'Histamine is made from the amino acid histidine by the enzyme histidine decarboxylase. Tryptophan is the precursor of serotonin and tyrosine of the catecholamines, so these are distractors from other autacoid pathways.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.078 Q1, Histamine Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-ff431824fe', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'mcq', 'H1 receptors are primarily involved in:', '["Gastric acid secretion", "Allergic reactions and smooth muscle contraction", "Regulation of neurotransmitter release (presynaptic)", "Cardiac rate increase", "Bone resorption"]'::jsonb, 'Allergic reactions and smooth muscle contraction', '[]'::jsonb, 'H1 receptors mediate the allergic effects of histamine: bronchoconstriction, contraction of gut smooth muscle, increased vascular permeability, vasodilation, itch and pain. Gastric acid secretion is an H2 effect, and presynaptic autoreceptor action is H3.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.078 Q2, Histamine Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-05693ce58e', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'mcq', 'H2 receptors are primarily found in the:', '["Brain", "Bronchial smooth muscle", "Gastric parietal cells", "Mast cells", "Skin"]'::jsonb, 'Gastric parietal cells', '[]'::jsonb, 'H2 receptors on gastric parietal cells drive acid secretion, which is why H2 antagonists such as ranitidine reduce acid. They are also present in cardiac and vascular tissue, but their best-known action is on the stomach.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.078 Q3, Histamine Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-autacoids-histamine-re-0cc50a5b78', 'pharm-introduction-to-autacoids-histamine-receptors-and-agonists', 'mcq', 'Stimulation of H1 receptors causes:', '["Bronchodilation", "Vasoconstriction", "Bronchoconstriction and increased capillary permeability", "Decreased mucus production", "Tachycardia"]'::jsonb, 'Bronchoconstriction and increased capillary permeability', '[]'::jsonb, 'H1 activation contracts bronchial smooth muscle and opens gaps between endothelial cells, producing bronchospasm and oedema; it also causes vasodilation, itch and increased mucus. These are precisely the features of an allergic response.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.079 Q4, Histamine Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h1-receptor-antagonists-fd51c7c121', 'pharm-h1-receptor-antagonists', 'mcq', 'First-generation H1 antihistamines such as diphenhydramine cause sedation because they:', '["Are very polar", "Cross the blood-brain barrier", "Block H2 receptors", "Stimulate the heart", "Are metabolised very slowly"]'::jsonb, 'Cross the blood-brain barrier', '[]'::jsonb, 'First-generation agents are lipophilic and readily cross the blood-brain barrier, where blocking central H1 receptors causes drowsiness; their antimuscarinic action adds to it. Second-generation drugs are more polar and penetrate the brain poorly, so they are far less sedating.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.079 Q5, Histamine Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h1-receptor-antagonists-eadb5c8e9f', 'pharm-h1-receptor-antagonists', 'mcq', 'Which of the following is a second-generation H1 antihistamine?', '["Chlorpheniramine", "Promethazine", "Cetirizine", "Hydroxyzine", "Cyclizine"]'::jsonb, 'Cetirizine', '[]'::jsonb, 'Cetirizine, loratadine, fexofenadine and desloratadine are second-generation antihistamines with little sedation. Chlorpheniramine, promethazine, hydroxyzine and cyclizine are first-generation drugs that cross into the brain and cause drowsiness.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.079 Q6, Histamine Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h1-receptor-antagonists-0d9bb26a22', 'pharm-h1-receptor-antagonists', 'mcq', 'Second-generation antihistamines are "non-sedating" because they:', '["Do not bind to H1 receptors", "Have poor CNS penetration", "Are only used topically", "Increase caffeine levels", "Act only on H3 receptors"]'::jsonb, 'Have poor CNS penetration', '[]'::jsonb, 'These drugs are more polar and are substrates of the P-glycoprotein efflux pump at the blood-brain barrier, so little reaches central H1 receptors; they still block peripheral H1 receptors fully. They are therefore preferred for daytime treatment of allergy.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.079 Q7, Histamine Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h1-receptor-antagonists-8cf04056ec', 'pharm-h1-receptor-antagonists', 'mcq', 'Cimetidine and ranitidine are antagonists at which receptor?', '["H1", "H2", "H3", "H4", "Alpha-1"]'::jsonb, 'H2', '[]'::jsonb, 'Cimetidine, ranitidine, famotidine and nizatidine competitively block histamine H2 receptors on gastric parietal cells, reducing acid secretion. Cimetidine also inhibits cytochrome P450 and causes many drug interactions, which later H2 blockers avoid.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.079 Q8, Histamine Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h1-receptor-antagonists-e5770a319d', 'pharm-h1-receptor-antagonists', 'mcq', 'The primary clinical use for H2 blockers is:', '["Allergic rhinitis", "Motion sickness", "Peptic ulcer disease and gastro-oesophageal reflux", "Insomnia", "Asthma"]'::jsonb, 'Peptic ulcer disease and gastro-oesophageal reflux', '[]'::jsonb, 'By reducing gastric acid secretion, H2 antagonists heal peptic ulcers and relieve reflux, though proton pump inhibitors are now more effective. Allergic rhinitis and motion sickness are treated with H1 antihistamines, which act on a different receptor.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.079 Q9, Histamine Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h1-receptor-antagonists-ad18e9ff23', 'pharm-h1-receptor-antagonists', 'mcq', 'Which H1 antihistamine is also used for the prevention of motion sickness?', '["Cetirizine", "Loratadine", "Promethazine", "Fexofenadine", "Desloratadine"]'::jsonb, 'Promethazine', '[]'::jsonb, 'Promethazine (and meclizine and cyclizine) are sedating first-generation antihistamines whose central H1 and antimuscarinic actions suppress the vestibular signals that cause motion sickness. The non-sedating second-generation drugs do not enter the brain enough to help.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.080 Q10, Histamine Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h1-receptor-antagonists-de36725070', 'pharm-h1-receptor-antagonists', 'mcq', 'Side effects of first-generation H1 blockers often include "atropine-like" effects such as:', '["Excessive salivation", "Diarrhoea", "Dry mouth and blurred vision", "Bradycardia", "Pinpoint pupils"]'::jsonb, 'Dry mouth and blurred vision', '[]'::jsonb, 'First-generation antihistamines also block muscarinic receptors, causing dry mouth, blurred vision, urinary retention, constipation and tachycardia. These anticholinergic effects make them useful for motion sickness but troublesome in the elderly.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.080 Q11, Histamine Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h1-receptor-antagonists-6b4199d61b', 'pharm-h1-receptor-antagonists', 'mcq', 'Histamine release from mast cells is triggered by:', '["IgE-mediated allergic reactions", "Physical injury (cold, heat, trauma)", "Certain drugs such as morphine and tubocurarine", "Complement components", "IgE-mediated reactions, physical injury and certain drugs"]'::jsonb, 'IgE-mediated reactions, physical injury and certain drugs', '[]'::jsonb, 'Mast cell histamine is released by allergen cross-linking of IgE, by physical stimuli, and by drugs such as morphine, tubocurarine and vancomycin that displace it directly without IgE. Recognising non-immune triggers explains reactions on first exposure to a drug.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.080 Q12, Histamine Agonists and Antagonists. Option E reworded from ''All of the above'' to list the triggers, and option D ''None of the above'' replaced with complement, so the inclusive answer survives shuffling.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h1-receptor-antagonists-2e6eda38b0', 'pharm-h1-receptor-antagonists', 'mcq', 'Which drug acts as a "mast cell stabiliser" by preventing the release of histamine?', '["Diphenhydramine", "Cimetidine", "Cromolyn sodium", "Ranitidine", "Adrenaline"]'::jsonb, 'Cromolyn sodium', '[]'::jsonb, 'Sodium cromoglicate (cromolyn) stabilises mast cell membranes so that degranulation and mediator release are reduced. It must be taken regularly for prophylaxis and is useless in an acute attack. Antihistamines block the receptor rather than preventing release.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.080 Q13, Histamine Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h1-receptor-antagonists-e17faae034', 'pharm-h1-receptor-antagonists', 'mcq', 'Betahistine is a histamine analogue used in the treatment of:', '["Gastric ulcers", "Meniere''s disease (vertigo)", "Hay fever", "Urticaria", "Anaphylaxis"]'::jsonb, 'Meniere''s disease (vertigo)', '[]'::jsonb, 'Betahistine is a weak H1 agonist and H3 antagonist thought to improve microcirculation in the inner ear, reducing the frequency and severity of vertigo attacks in Meniere''s disease. It would be expected to worsen, not treat, allergy.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.080 Q14, Histamine Agonists and Antagonists. Stem corrected: betahistine is a histamine analogue (H1 agonist/H3 antagonist), not a pure H1 agonist as the paper stated.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h1-receptor-antagonists-6e653d6056', 'pharm-h1-receptor-antagonists', 'mcq', 'H3 receptors are mainly located in the CNS and function as:', '["Postsynaptic excitators", "Presynaptic autoreceptors (inhibiting neurotransmitter release)", "Ion channels", "Gq-coupled receptors", "Transcription factors"]'::jsonb, 'Presynaptic autoreceptors (inhibiting neurotransmitter release)', '[]'::jsonb, 'H3 receptors act as presynaptic autoreceptors and heteroreceptors in the brain; histamine acting on them inhibits its own release and that of other transmitters. They regulate wakefulness, which is why H3 antagonists such as pitolisant are used in narcolepsy.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.080 Q15, Histamine Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-eicosanoids-f74f719261', 'pharm-eicosanoids', 'mcq', 'Eicosanoids are synthesised from which 20-carbon fatty acid?', '["Linoleic acid", "Arachidonic acid", "Stearic acid", "Oleic acid", "Palmitic acid"]'::jsonb, 'Arachidonic acid', '[]'::jsonb, 'Eicosanoids take their name from the Greek for twenty; all are derived from arachidonic acid, a 20-carbon polyunsaturated fatty acid released from membrane phospholipids. Linoleic acid is a dietary precursor of arachidonic acid but is not the direct substrate.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.081 Q1, Eicosanoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-eicosanoids-52a6b82f08', 'pharm-eicosanoids', 'mcq', 'The enzyme responsible for releasing arachidonic acid from membrane phospholipids is:', '["Cyclooxygenase", "Lipoxygenase", "Phospholipase A2", "Thromboxane synthase", "Epoxygenase"]'::jsonb, 'Phospholipase A2', '[]'::jsonb, 'Phospholipase A2 cleaves arachidonic acid from the sn-2 position of membrane phospholipids, the rate-limiting first step of eicosanoid synthesis. Cyclooxygenase and lipoxygenase then act on the freed arachidonic acid; glucocorticoids work by inhibiting phospholipase A2.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.081 Q2, Eicosanoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-eicosanoids-48762a986a', 'pharm-eicosanoids', 'mcq', 'Glucocorticoids (steroids) reduce inflammation primarily by inhibiting:', '["Cyclooxygenase-2 directly", "Phospholipase A2 (via lipocortin/annexin)", "Histamine receptors", "Serotonin reuptake", "Thromboxane receptors"]'::jsonb, 'Phospholipase A2 (via lipocortin/annexin)', '[]'::jsonb, 'Glucocorticoids induce the protein lipocortin-1 (annexin A1), which inhibits phospholipase A2, cutting off release of arachidonic acid and so reducing both prostaglandins and leukotrienes. NSAIDs act further downstream, blocking only cyclooxygenase.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.081 Q3, Eicosanoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-eicosanoids-abfcf19fcb', 'pharm-eicosanoids', 'mcq', 'Which of the following is a major pathway for arachidonic acid metabolism?', '["The cyclooxygenase (COX) pathway", "The lipoxygenase (LOX) pathway", "The P450 monooxygenase (epoxygenase) pathway", "The thromboxane synthase pathway only", "The cyclooxygenase, lipoxygenase and P450 pathways"]'::jsonb, 'The cyclooxygenase, lipoxygenase and P450 pathways', '[]'::jsonb, 'Arachidonic acid is metabolised by cyclooxygenase (to prostaglandins and thromboxanes), by lipoxygenase (to leukotrienes and lipoxins) and by cytochrome P450 epoxygenase (to epoxyeicosatrienoic acids). All three are genuine major pathways.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.081 Q4, Eicosanoids. Option D ''All of the above'' replaced with a specific option, and the three real pathways listed in option E, so the correct answer survives shuffling.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-eicosanoids-56464d7dc4', 'pharm-eicosanoids', 'mcq', '"Leukotrienes" are primarily produced via the action of:', '["COX-1", "COX-2", "5-Lipoxygenase", "Prostacyclin synthase", "Monoamine oxidase-B"]'::jsonb, '5-Lipoxygenase', '[]'::jsonb, '5-Lipoxygenase, together with its activating protein FLAP, converts arachidonic acid to leukotriene A4, the parent of LTB4 and the cysteinyl leukotrienes. Cyclooxygenases instead make prostaglandins and thromboxanes.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.081 Q5, Eicosanoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-eicosanoids-d18c0dd320', 'pharm-eicosanoids', 'mcq', 'Which eicosanoid is a potent stimulant of platelet aggregation and a vasoconstrictor?', '["Prostaglandin I2 (prostacyclin)", "Thromboxane A2", "Prostaglandin E2", "Leukotriene D4", "Lipoxin A4"]'::jsonb, 'Thromboxane A2', '[]'::jsonb, 'Thromboxane A2, made by COX and thromboxane synthase in platelets, promotes platelet aggregation and vasoconstriction. Prostacyclin from the endothelium does the opposite; low-dose aspirin works by shifting this balance against thromboxane.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.081 Q6, Eicosanoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-eicosanoids-c43b254bac', 'pharm-eicosanoids', 'mcq', 'The main effect of leukotrienes C4, D4 and E4 in the lungs is:', '["Bronchodilation", "Potent bronchoconstriction and mucus secretion", "Decreased vascular permeability", "Inhibition of inflammation", "Stimulation of surfactant production"]'::jsonb, 'Potent bronchoconstriction and mucus secretion', '[]'::jsonb, 'The cysteinyl leukotrienes, formerly called slow-reacting substance of anaphylaxis, cause intense and sustained bronchoconstriction, increased mucus and airway oedema, far more potently than histamine. This underlies their role in asthma.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.082 Q7, Eicosanoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-eicosanoids-0c38eec670', 'pharm-eicosanoids', 'mcq', '"Cysteinyl leukotrienes" are key mediators in the pathogenesis of:', '["Hypertension", "Bronchial asthma", "Peptic ulcers", "Glaucoma", "Diabetes"]'::jsonb, 'Bronchial asthma', '[]'::jsonb, 'Cysteinyl leukotrienes drive bronchoconstriction, mucus secretion and eosinophil recruitment in asthma, which is why leukotriene antagonists such as montelukast are used for its control and prophylaxis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.082 Q8, Eicosanoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-eicosanoids-8e5fbfa11b', 'pharm-eicosanoids', 'mcq', 'Which drug inhibits the 5-lipoxygenase enzyme?', '["Montelukast", "Zafirlukast", "Zileuton", "Aspirin", "Celecoxib"]'::jsonb, 'Zileuton', '[]'::jsonb, 'Zileuton directly inhibits 5-lipoxygenase, reducing synthesis of all leukotrienes. Montelukast and zafirlukast instead block the CysLT1 receptor, while aspirin and celecoxib act on cyclooxygenase and do not affect leukotriene production.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.082 Q9, Eicosanoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-eicosanoids-4efead71f3', 'pharm-eicosanoids', 'mcq', 'Montelukast and zafirlukast act by:', '["Inhibiting leukotriene synthesis", "Blocking CysLT1 leukotriene receptors", "Inhibiting COX-2", "Stimulating beta-2 receptors", "Neutralising histamine"]'::jsonb, 'Blocking CysLT1 leukotriene receptors', '[]'::jsonb, 'These drugs competitively block the CysLT1 receptor, preventing the cysteinyl leukotrienes from causing bronchoconstriction and inflammation. They are taken orally for asthma prophylaxis and allergic rhinitis; zileuton, by contrast, blocks synthesis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.082 Q10, Eicosanoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-eicosanoids-6ae8971bb2', 'pharm-eicosanoids', 'mcq', 'Lipoxins are eicosanoids that primarily function to:', '["Increase inflammation", "Resolve inflammation (anti-inflammatory)", "Cause fever", "Induce labour", "Stimulate gastric acid"]'::jsonb, 'Resolve inflammation (anti-inflammatory)', '[]'::jsonb, 'Lipoxins are lipoxygenase products that act as ''stop signals'', promoting the resolution of inflammation by inhibiting neutrophil recruitment and stimulating macrophage clearance of debris. They counterbalance the pro-inflammatory leukotrienes.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.082 Q11, Eicosanoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-eicosanoids-d984132427', 'pharm-eicosanoids', 'mcq', 'Which of the following best describes an "isoprostane"?', '["A prostaglandin-like compound formed by non-enzymatic free-radical peroxidation", "A synthetic prostaglandin used for glaucoma", "A precursor to cholesterol", "An enzyme found in the liver", "A drug used for pain"]'::jsonb, 'A prostaglandin-like compound formed by non-enzymatic free-radical peroxidation', '[]'::jsonb, 'Isoprostanes are formed when reactive oxygen species peroxidise arachidonic acid directly, without enzymes. Their levels reflect oxidative stress in the body and are used as a biomarker of it; some also have vasoconstrictor activity.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.082 Q12, Eicosanoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-eicosanoids-73080b3099', 'pharm-eicosanoids', 'mcq', 'Prostanoids include which of the following groups?', '["Prostaglandins and thromboxanes", "Leukotrienes only", "Lipoxins and epoxides", "Histamine and serotonin", "Bradykinin and substance P"]'::jsonb, 'Prostaglandins and thromboxanes', '[]'::jsonb, 'The prostanoids are the cyclooxygenase products: the prostaglandins and the thromboxanes. Leukotrienes and lipoxins come from the lipoxygenase pathway, so they are not prostanoids even though they are eicosanoids.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.082 Q13, Eicosanoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-eicosanoids-0c22daa9a1', 'pharm-eicosanoids', 'mcq', 'The "COX-independent" effects of NSAIDs may include:', '["Inhibition of NF-kappaB signalling", "Activation of PPAR-gamma", "Alteration of cell membrane fluidity", "Inhibition of neutrophil activation", "Several COX-independent actions including NF-kappaB inhibition and PPAR-gamma activation"]'::jsonb, 'Several COX-independent actions including NF-kappaB inhibition and PPAR-gamma activation', '[]'::jsonb, 'Besides blocking cyclooxygenase, NSAIDs can inhibit the pro-inflammatory transcription factor NF-kappaB, activate PPAR-gamma and alter membrane function, which may explain anti-inflammatory and anticancer effects beyond prostaglandin inhibition.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.083 Q14, Eicosanoids. Option D ''All of the above'' replaced with a specific action, and option E lists the effects, so the inclusive answer survives shuffling.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-eicosanoids-ad1fb29ee8', 'pharm-eicosanoids', 'mcq', 'Which eicosanoid maintains the patency of the ductus arteriosus in the fetus?', '["PGE2", "TXA2", "LTB4", "PGF2-alpha", "LTC4"]'::jsonb, 'PGE2', '[]'::jsonb, 'Prostaglandin E2 keeps the fetal ductus arteriosus relaxed and open. After birth its fall, and the use of a prostaglandin E1 analogue (alprostadil), keeps it open in duct-dependent heart defects, while indometacin closes a persistent duct.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.083 Q15, Eicosanoids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-prostaglandins-342fe81b1d', 'pharm-prostaglandins', 'mcq', 'Which prostaglandin is also known as "prostacyclin"?', '["PGE2", "PGF2-alpha", "PGI2", "PGD2", "TXA2"]'::jsonb, 'PGI2', '[]'::jsonb, 'Prostacyclin is PGI2, produced mainly by vascular endothelium. It inhibits platelet aggregation and dilates vessels, opposing thromboxane A2. Its analogues such as epoprostenol and iloprost are used in pulmonary hypertension.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.083 Q1, Prostaglandins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-prostaglandins-d975f01679', 'pharm-prostaglandins', 'mcq', 'PGI2 (prostacyclin) is produced mainly by vascular endothelium and acts to:', '["Stimulate platelet aggregation", "Inhibit platelet aggregation and cause vasodilation", "Cause potent vasoconstriction", "Increase gastric acid secretion", "Decrease renal blood flow"]'::jsonb, 'Inhibit platelet aggregation and cause vasodilation', '[]'::jsonb, 'Prostacyclin raises platelet cAMP, inhibiting their aggregation, and relaxes vascular smooth muscle to cause vasodilation. It is the physiological counterweight to platelet thromboxane A2 and helps keep the vascular lining non-thrombogenic.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.083 Q2, Prostaglandins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-prostaglandins-92e6c1af8b', 'pharm-prostaglandins', 'mcq', 'The PGE1 analogue alprostadil is used clinically to:', '["Treat diarrhoea", "Maintain patency of the ductus arteriosus in neonates with heart defects", "Induce sleep", "Stop bleeding", "Treat asthma"]'::jsonb, 'Maintain patency of the ductus arteriosus in neonates with heart defects', '[]'::jsonb, 'Alprostadil (PGE1) keeps the ductus arteriosus open in neonates with duct-dependent congenital heart defects, buying time until corrective surgery. It is also injected to treat erectile dysfunction, exploiting its vasodilator action.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.083 Q3, Prostaglandins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-prostaglandins-64bb22033b', 'pharm-prostaglandins', 'mcq', 'Misoprostol is a PGE1 analogue used for:', '["Treatment of hypertension", "Prevention of NSAID-induced gastric ulcers", "Treatment of glaucoma", "Bronchodilation", "Muscle relaxation"]'::jsonb, 'Prevention of NSAID-induced gastric ulcers', '[]'::jsonb, 'Misoprostol replaces the protective gastric prostaglandins that NSAIDs suppress, stimulating mucus and bicarbonate and reducing acid, so it prevents NSAID-induced ulcers. It also contracts the uterus and is used in obstetrics; this is why it is avoided in pregnancy for other indications.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.084 Q4, Prostaglandins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-prostaglandins-f9d58ce9c8', 'pharm-prostaglandins', 'mcq', 'Latanoprost is a PGF2α derivative used primarily for:', '["Induction of labour", "Treatment of glaucoma", "Dysmenorrhoea", "Heart failure", "Nasal congestion"]'::jsonb, 'Treatment of glaucoma', '[]'::jsonb, 'Latanoprost is a topical PGF2α analogue that lowers intraocular pressure by increasing uveoscleral outflow of aqueous humour, making it a first-line drug in open-angle glaucoma. Labour induction uses PGE analogues such as dinoprostone and misoprostol, not latanoprost.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.084 Q5, Prostaglandins. Removed the mechanism hint from the correct option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-prostaglandins-64cf9d55f8', 'pharm-prostaglandins', 'mcq', 'Which prostaglandin is used for the induction of labour and cervical ripening?', '["Dinoprostone", "Thromboxane", "Prostacyclin", "Latanoprost", "Ibuprofen"]'::jsonb, 'Dinoprostone', '[]'::jsonb, 'Dinoprostone is PGE2; given vaginally it softens (ripens) the cervix and stimulates uterine contractions. Prostacyclin and thromboxane act mainly on vessels and platelets, latanoprost is an ophthalmic PGF2α analogue, and ibuprofen inhibits prostaglandin synthesis and would delay labour.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.084 Q6, Prostaglandins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-prostaglandins-10bb32bd32', 'pharm-prostaglandins', 'mcq', 'Prostaglandins in the stomach are ''cytoprotective'' because they:', '["Increase acid secretion", "Increase mucus and bicarbonate secretion and improve blood flow", "Stimulate pepsin release", "Thicken the oesophageal wall", "Inhibit H. pylori growth"]'::jsonb, 'Increase mucus and bicarbonate secretion and improve blood flow', '[]'::jsonb, 'PGE2 and PGI2 in the gastric mucosa stimulate mucus and bicarbonate secretion, maintain mucosal blood flow and reduce acid secretion. This is why NSAIDs, which block their synthesis, cause ulcers and why misoprostol protects against them. They do not increase acid or act on H. pylori.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.084 Q7, Prostaglandins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-prostaglandins-7ac5be9baf', 'pharm-prostaglandins', 'mcq', '''Aspirin-induced asthma'' is thought to be caused by:', '["Inhibition of leukotrienes", "Shunting of arachidonic acid to the lipoxygenase pathway due to COX inhibition", "Excessive production of PGE2", "Blockade of histamine receptors", "Direct irritation of the trachea"]'::jsonb, 'Shunting of arachidonic acid to the lipoxygenase pathway due to COX inhibition', '[]'::jsonb, 'When COX is inhibited, arachidonic acid is diverted to 5-lipoxygenase, increasing the bronchoconstrictor cysteinyl leukotrienes, while bronchoprotective PGE2 falls. Leukotrienes are therefore increased, not inhibited, which is why leukotriene antagonists help these patients. The reaction is not an allergy, so it occurs with all non-selective NSAIDs.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.084 Q8, Prostaglandins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-prostaglandins-df8886d481', 'pharm-prostaglandins', 'mcq', 'The primary prostaglandin involved in causing dysmenorrhoea (painful menses) is:', '["PGI2", "PGF2α", "TXA2", "PGD2", "PGE1"]'::jsonb, 'PGF2α', '[]'::jsonb, 'Primary dysmenorrhoea is due to excess endometrial PGF2α (with PGE2), which causes strong myometrial contraction and ischaemia. NSAIDs relieve it by blocking prostaglandin synthesis. PGI2 relaxes smooth muscle and inhibits platelets and is not the cause.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.084 Q9, Prostaglandins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-prostaglandins-db89a3850c', 'pharm-prostaglandins', 'mcq', 'Epoprostenol, used in pulmonary hypertension, is a synthetic version of which prostaglandin?', '["PGE1", "PGI2", "PGF2α", "TXA2", "LTB4"]'::jsonb, 'PGI2', '[]'::jsonb, 'Epoprostenol is prostacyclin (PGI2), a vasodilator and inhibitor of platelet aggregation given by continuous infusion in pulmonary arterial hypertension. PGE1 is alprostadil, used to keep the ductus arteriosus open and for erectile dysfunction. Its half-life is only a few minutes, hence the continuous infusion; iloprost and treprostinil are longer-acting analogues.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.084 Q10, Prostaglandins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-prostaglandins-8e788c9580', 'pharm-prostaglandins', 'mcq', 'Bimatoprost, used for glaucoma and for eyelash hypotrichosis, is an analogue of which prostaglandin?', '["PGE2", "PGF2α", "PGI2", "TXA2", "PGD2"]'::jsonb, 'PGF2α', '[]'::jsonb, 'Bimatoprost, like latanoprost and travoprost, is a PGF2α analogue (a prostamide). It lowers intraocular pressure and, as a side effect put to use, lengthens and darkens eyelashes. PGE2 analogues are used in obstetrics instead. It can also darken the iris and the skin of the eyelids.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.085 Q11, Prostaglandins. Reworded: the original stem was garbled (''used to treat Bimatoprost'').') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-prostaglandins-7050b5259f', 'pharm-prostaglandins', 'mcq', 'Prostaglandins produce pain by:', '["Directly stimulating pain fibres", "Sensitising nerve endings to other mediators such as bradykinin", "Blocking opioid receptors", "Causing nerve degeneration", "Increasing skin thickness"]'::jsonb, 'Sensitising nerve endings to other mediators such as bradykinin', '[]'::jsonb, 'PGE2 and PGI2 do not cause much pain themselves; they lower the threshold of nociceptors so that bradykinin, histamine and mechanical stimuli hurt more (hyperalgesia). That is why NSAIDs work best for inflammatory pain rather than for direct stimulation of pain fibres.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.085 Q12, Prostaglandins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-prostaglandins-812c8b4070', 'pharm-prostaglandins', 'mcq', 'COX-1 is ''constitutive'', meaning it is involved in:', '["Inflammatory responses only", "Physiological ''housekeeping'' functions (stomach, kidneys, platelets)", "Fever only", "Cancer growth only", "Pain only in joints"]'::jsonb, 'Physiological ''housekeeping'' functions (stomach, kidneys, platelets)', '[]'::jsonb, 'COX-1 is expressed all the time in most tissues and makes the prostanoids that protect gastric mucosa, maintain renal blood flow and produce platelet thromboxane. COX-2 is the isoform mainly induced at sites of inflammation, so inflammation-only answers describe COX-2.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.085 Q13, Prostaglandins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-prostaglandins-e22c92198c', 'pharm-prostaglandins', 'mcq', 'Selective COX-2 inhibitors (such as celecoxib) were designed to:', '["Increase anti-platelet activity", "Provide anti-inflammatory effects with less gastric toxicity", "Treat asthma", "Replace morphine for severe pain", "Increase blood pressure"]'::jsonb, 'Provide anti-inflammatory effects with less gastric toxicity', '[]'::jsonb, 'Sparing COX-1 preserves the gastric cytoprotective prostaglandins, so coxibs cause fewer ulcers and bleeds than non-selective NSAIDs. They have no antiplatelet effect because platelet thromboxane comes from COX-1, which is part of the reason for their cardiovascular risk.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.085 Q14, Prostaglandins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-prostaglandins-272c34713e', 'pharm-prostaglandins', 'mcq', 'The cardiovascular risk associated with COX-2 inhibitors is due to an imbalance between:', '["Histamine and serotonin", "Prostacyclin (PGI2) and thromboxane (TXA2)", "Insulin and glucagon", "Dopamine and acetylcholine", "Sodium and potassium"]'::jsonb, 'Prostacyclin (PGI2) and thromboxane (TXA2)', '[]'::jsonb, 'Endothelial PGI2 (vasodilator, anti-aggregatory) depends largely on COX-2, whereas platelet TXA2 (vasoconstrictor, pro-aggregatory) depends on COX-1. Selective COX-2 inhibition lowers PGI2 but leaves TXA2 untouched, tipping the balance towards thrombosis. This explains the excess myocardial infarction and stroke that led to withdrawal of rofecoxib.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.085 Q15, Prostaglandins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-cdd24fcb7b', 'pharm-serotonin-receptors-and-agonists', 'mcq', 'Serotonin (5-hydroxytryptamine) is synthesised from the amino acid:', '["Histidine", "Tyrosine", "Tryptophan", "Arginine", "Glutamate"]'::jsonb, 'Tryptophan', '[]'::jsonb, 'Tryptophan is hydroxylated by tryptophan hydroxylase (the rate-limiting step) and then decarboxylated to 5-HT. Histidine gives histamine and tyrosine gives the catecholamines, which are the usual distractors. Dietary tryptophan supply and the hydroxylase step therefore control how much serotonin is made.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.085 Q1, Serotonin (5-HT) Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-76f3166e77', 'pharm-serotonin-receptors-and-agonists', 'mcq', 'The majority of the body''s serotonin is found in:', '["The brain", "Platelets", "Enterochromaffin cells in the GI tract", "The heart", "Skeletal muscle"]'::jsonb, 'Enterochromaffin cells in the GI tract', '[]'::jsonb, 'About 90% of body 5-HT is made and stored in enterochromaffin cells of the gut mucosa, where it regulates motility. Platelets cannot synthesise it but take it up from plasma, and the brain holds only a small percentage.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.086 Q2, Serotonin (5-HT) Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-aa23209b97', 'pharm-serotonin-receptors-and-agonists', 'mcq', 'Which serotonin receptor is an ion channel (ionotropic)?', '["5-HT1", "5-HT2", "5-HT3", "5-HT4", "5-HT7"]'::jsonb, '5-HT3', '[]'::jsonb, '5-HT3 is a ligand-gated cation channel of the Cys-loop family, like the nicotinic receptor; it mediates fast depolarisation in vagal afferents and the chemoreceptor trigger zone. All other 5-HT receptor families are G-protein coupled. Blocking it with ondansetron or granisetron prevents vomiting.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.086 Q3, Serotonin (5-HT) Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-4e06670b8a', 'pharm-serotonin-receptors-and-agonists', 'mcq', '''Triptans'' (such as sumatriptan), used for migraine, are agonists at which receptors?', '["5-HT1B/1D", "5-HT2A", "5-HT3", "5-HT4", "5-HT7"]'::jsonb, '5-HT1B/1D', '[]'::jsonb, 'Triptans stimulate 5-HT1B receptors on cranial vessels (vasoconstriction) and 5-HT1D receptors on trigeminal nerve endings (less release of CGRP and other peptides). 5-HT3 is the target of the antiemetic setrons, not of triptans. Because they constrict coronary vessels too, triptans are avoided in ischaemic heart disease.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.086 Q4, Serotonin (5-HT) Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-antagonists-and-ergot-alkalo-f9c8d57d3a', 'pharm-serotonin-antagonists-and-ergot-alkaloids', 'mcq', 'Ondansetron is a highly effective antiemetic that acts as an antagonist at:', '["5-HT1 receptors", "5-HT2 receptors", "5-HT3 receptors", "5-HT4 receptors", "Muscarinic receptors"]'::jsonb, '5-HT3 receptors', '[]'::jsonb, 'Ondansetron blocks 5-HT3 receptors on vagal afferents in the gut and in the chemoreceptor trigger zone, stopping the emetic signal produced by serotonin released by chemotherapy or radiation. Muscarinic block is how hyoscine works in motion sickness.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.086 Q5, Serotonin (5-HT) Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-c518193fae', 'pharm-serotonin-receptors-and-agonists', 'mcq', 'Buspirone is a 5-HT1A partial agonist used to treat:', '["Depression", "Generalised anxiety disorder", "Psychosis", "Insomnia", "Epilepsy"]'::jsonb, 'Generalised anxiety disorder', '[]'::jsonb, 'Buspirone relieves generalised anxiety after a delay of one to two weeks without sedation, dependence or muscle relaxation. It is not hypnotic or anticonvulsant, which distinguishes it from the benzodiazepines. Because of the slow onset it is unsuitable for acute panic or for benzodiazepine withdrawal.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.086 Q6, Serotonin (5-HT) Agonists and Antagonists. Tidied the correct option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-c3c57cdc7d', 'pharm-serotonin-receptors-and-agonists', 'mcq', 'The ''serotonin syndrome'' is characterised by:', '["Hypothermia and constipation", "Hyperthermia, muscle rigidity and myoclonus", "Bradycardia and dry skin", "Hypotension and sleepiness", "Loss of appetite and hair loss"]'::jsonb, 'Hyperthermia, muscle rigidity and myoclonus', '[]'::jsonb, 'Excess synaptic 5-HT (for example an SSRI combined with an MAO inhibitor) produces hyperthermia, neuromuscular excitation (clonus, hyperreflexia, rigidity), agitation and autonomic instability with sweating, tachycardia and diarrhoea. Cold, dry, slow features point away from it.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.086 Q7, Serotonin (5-HT) Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-antagonists-and-ergot-alkalo-209848bbe8', 'pharm-serotonin-antagonists-and-ergot-alkaloids', 'mcq', 'Which 5-HT2 antagonist is used in the management of carcinoid syndrome?', '["Ondansetron", "Cyproheptadine", "Sumatriptan", "Buspirone", "Fluoxetine"]'::jsonb, 'Cyproheptadine', '[]'::jsonb, 'Cyproheptadine blocks 5-HT2 and H1 receptors and reduces the diarrhoea and other smooth-muscle effects of serotonin released by carcinoid tumours. Ondansetron is also a serotonin antagonist but at 5-HT3 receptors, so it does not fit the question.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.087 Q8, Serotonin (5-HT) Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-04516e91f0', 'pharm-serotonin-receptors-and-agonists', 'mcq', 'Fluoxetine belongs to which class of drugs?', '["Monoamine oxidase inhibitors", "Selective serotonin reuptake inhibitors (SSRIs)", "Tricyclic antidepressants", "5-HT3 antagonists", "Dopamine agonists"]'::jsonb, 'Selective serotonin reuptake inhibitors (SSRIs)', '[]'::jsonb, 'Fluoxetine selectively blocks the serotonin transporter (SERT), raising synaptic 5-HT. Unlike tricyclics it has little antimuscarinic, antihistamine or alpha-blocking action, so it is safer in overdose. MAO inhibitors block breakdown of the amine instead of its reuptake, and combining the two classes risks serotonin syndrome.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.087 Q9, Serotonin (5-HT) Agonists and Antagonists. Closest autacoid topic used; could also sit under antidepressants.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-ccc7940b33', 'pharm-serotonin-receptors-and-agonists', 'mcq', 'Activation of 5-HT4 receptors in the GI tract leads to:', '["Constipation", "Increased GI motility (prokinetic effect)", "Decreased acid secretion", "Nausea", "GI bleeding"]'::jsonb, 'Increased GI motility (prokinetic effect)', '[]'::jsonb, '5-HT4 receptors on enteric neurones enhance acetylcholine release and so increase peristalsis; this is the basis of prokinetics such as cisapride, prucalopride and partly metoclopramide. Nausea is a 5-HT3-mediated effect. 5-HT3 antagonists, in contrast, tend to cause constipation.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.087 Q10, Serotonin (5-HT) Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-antagonists-and-ergot-alkalo-fa92704f6d', 'pharm-serotonin-antagonists-and-ergot-alkaloids', 'mcq', 'Ergotamine is used for migraine because of its action at:', '["5-HT receptors and alpha receptors", "Muscarinic receptors", "Histamine receptors", "GABA receptors", "Nicotinic receptors"]'::jsonb, '5-HT receptors and alpha receptors', '[]'::jsonb, 'Ergotamine is a partial agonist at 5-HT1B/1D receptors and at alpha-adrenoceptors, constricting dilated cranial vessels and reducing trigeminal neuropeptide release. It has no useful action on muscarinic, histamine or GABA receptors. The alpha-mediated vasoconstriction also explains its main toxicity, peripheral ischaemia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.087 Q11, Serotonin (5-HT) Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-f06cd21432', 'pharm-serotonin-receptors-and-agonists', 'mcq', 'Cisapride was used as a prokinetic but was withdrawn because of:', '["Liver failure", "Cardiac arrhythmias (QT prolongation)", "Severe diarrhoea", "Blindness", "Addiction"]'::jsonb, 'Cardiac arrhythmias (QT prolongation)', '[]'::jsonb, 'Cisapride blocks cardiac hERG potassium channels, prolonging the QT interval and causing torsades de pointes, particularly when CYP3A4 inhibitors such as erythromycin or ketoconazole raise its concentration. Liver failure and blindness were not the problem; prucalopride is a safer 5-HT4 agonist used today.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.087 Q12, Serotonin (5-HT) Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-334f284256', 'pharm-serotonin-receptors-and-agonists', 'mcq', 'Which serotonin receptor is involved in the ''psychedelic'' effects of drugs like LSD?', '["5-HT1A", "5-HT2A", "5-HT3", "5-HT4", "5-HT1D"]'::jsonb, '5-HT2A', '[]'::jsonb, 'LSD, psilocybin and mescaline produce hallucinations through agonism at cortical 5-HT2A receptors; 5-HT2A antagonists block the effect. 5-HT1A is the target of buspirone and is linked to anxiolysis instead. The 5-HT3 receptor is linked with vomiting, not with perception.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.087 Q13, Serotonin (5-HT) Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-8601bbfb92', 'pharm-serotonin-receptors-and-agonists', 'mcq', 'Serotonin is a precursor for the synthesis of which hormone in the pineal gland?', '["Melatonin", "Cortisol", "Insulin", "Thyroxine", "Oxytocin"]'::jsonb, 'Melatonin', '[]'::jsonb, 'In the pineal gland 5-HT is N-acetylated and then O-methylated to melatonin, which regulates the sleep-wake cycle. The other hormones are steroid, peptide or iodinated tyrosine derivatives unrelated to serotonin. Melatonin secretion rises in darkness, and synthetic melatonin is used for jet lag and insomnia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.088 Q14, Serotonin (5-HT) Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-receptors-and-agonists-4ccf2afdd0', 'pharm-serotonin-receptors-and-agonists', 'mcq', 'The enzyme responsible for the primary metabolism of serotonin is:', '["COMT", "MAO-A", "CYP3A4", "Acetylcholinesterase", "Xanthine oxidase"]'::jsonb, 'MAO-A', '[]'::jsonb, 'Monoamine oxidase A oxidatively deaminates 5-HT, and the product is converted to 5-hydroxyindoleacetic acid (5-HIAA), which is measured in urine to diagnose carcinoid. COMT metabolises catecholamines, not serotonin. MAO-A inhibitors such as moclobemide therefore raise serotonin levels and act as antidepressants.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.088 Q15, Serotonin (5-HT) Agonists and Antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-antagonists-and-ergot-alkalo-21ef7931d0', 'pharm-serotonin-antagonists-and-ergot-alkaloids', 'mcq', 'Ergot alkaloids are derived from:', '["The poppy plant", "A fungus (Claviceps purpurea) that grows on rye", "The bark of the cinchona tree", "Foxglove leaves", "Snake venom"]'::jsonb, 'A fungus (Claviceps purpurea) that grows on rye', '[]'::jsonb, 'Claviceps purpurea infects rye and other grains and produces the ergot alkaloids. The poppy gives opioids, cinchona gives quinine and foxglove gives digitalis glycosides. Ergot alkaloids share a tetracyclic ergoline ring that resembles noradrenaline, dopamine and serotonin, which explains their mixed receptor actions.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.088 Q1, Ergot Alkaloids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-antagonists-and-ergot-alkalo-3acb2d3d1a', 'pharm-serotonin-antagonists-and-ergot-alkaloids', 'mcq', 'Ergotamine is primarily used in the treatment of:', '["Hypertension", "Acute migraine attacks", "Parkinson''s disease", "Diabetes", "Postpartum haemorrhage"]'::jsonb, 'Acute migraine attacks', '[]'::jsonb, 'Ergotamine is given early in an acute migraine attack, where its 5-HT1B/1D partial agonism and vasoconstriction abort the headache. Postpartum haemorrhage is treated with ergometrine, which is more selective for the uterus. It is not used for prophylaxis, because frequent dosing causes rebound headache and ergotism.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.088 Q2, Ergot Alkaloids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-antagonists-and-ergot-alkalo-4d1ca9cc5c', 'pharm-serotonin-antagonists-and-ergot-alkaloids', 'mcq', 'Ergonovine (ergometrine) is used in obstetrics to:', '["Induce labour", "Prevent or treat postpartum haemorrhage", "Treat morning sickness", "Increase breast milk production", "Relax the uterus"]'::jsonb, 'Prevent or treat postpartum haemorrhage', '[]'::jsonb, 'Ergometrine produces a sustained contraction of the uterus that compresses bleeding vessels after delivery of the placenta. Because the contraction is tonic rather than rhythmic it must not be used to induce labour, when it would endanger the fetus.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.088 Q3, Ergot Alkaloids. Removed the mechanism hint from the correct option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-antagonists-and-ergot-alkalo-83fb6a86e3', 'pharm-serotonin-antagonists-and-ergot-alkaloids', 'mcq', 'Bromocriptine is an ergot derivative that acts as an agonist at:', '["Serotonin receptors", "Dopamine D2 receptors", "Alpha receptors", "Muscarinic receptors", "Histamine receptors"]'::jsonb, 'Dopamine D2 receptors', '[]'::jsonb, 'Bromocriptine stimulates D2 receptors, which inhibits prolactin release from the pituitary and replaces dopaminergic activity in the striatum in Parkinson''s disease. It retains only weak activity at alpha and serotonin receptors, so vasoconstriction is much less marked than with ergotamine.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.088 Q4, Ergot Alkaloids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-antagonists-and-ergot-alkalo-93b5a12041', 'pharm-serotonin-antagonists-and-ergot-alkaloids', 'mcq', 'A significant adverse effect of chronic ergotamine use is:', '["Excessive weight gain", "Peripheral gangrene", "Diarrhoea", "Hair loss", "Hypoglycaemia"]'::jsonb, 'Peripheral gangrene', '[]'::jsonb, 'Ergotamine causes intense, prolonged vasoconstriction through alpha-adrenoceptors and 5-HT receptors; with overuse this leads to cold, painful limbs and eventually gangrene (ergotism). Weekly dose limits are set for this reason, and the risk rises sharply with CYP3A4 inhibitors such as erythromycin or ritonavir.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.089 Q5, Ergot Alkaloids. Removed the mechanism hint from the correct option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-antagonists-and-ergot-alkalo-eeffbb9df6', 'pharm-serotonin-antagonists-and-ergot-alkaloids', 'mcq', 'Bromocriptine is used for the treatment of:', '["Hyperprolactinaemia and Parkinson''s disease", "Hypertension", "Asthma", "Glaucoma", "Alzheimer''s disease"]'::jsonb, 'Hyperprolactinaemia and Parkinson''s disease', '[]'::jsonb, 'As a D2 agonist, bromocriptine suppresses prolactin secretion (prolactinomas, galactorrhoea) and supplements striatal dopamine in Parkinson''s disease. It is also used in acromegaly. Nausea, postural hypotension and, at high doses, hallucinations are its main adverse effects; it has no place in hypertension or asthma.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.089 Q6, Ergot Alkaloids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-antagonists-and-ergot-alkalo-6308ab8cda', 'pharm-serotonin-antagonists-and-ergot-alkaloids', 'mcq', '''St. Anthony''s fire'' is a historical term for poisoning by:', '["Mercury", "Ergot alkaloids", "Lead", "Arsenic", "Belladonna"]'::jsonb, 'Ergot alkaloids', '[]'::jsonb, 'Epidemics of ergotism followed eating bread made from rye contaminated with Claviceps purpurea. Victims had burning pain and gangrene of the limbs from vasoconstriction, as well as convulsions and hallucinations. Heavy metals and belladonna produce quite different pictures.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.089 Q7, Ergot Alkaloids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-antagonists-and-ergot-alkalo-6992584efc', 'pharm-serotonin-antagonists-and-ergot-alkaloids', 'mcq', 'Which ergot derivative is a potent hallucinogen with no accepted medical use?', '["Ergotamine", "Lysergic acid diethylamide (LSD)", "Ergometrine", "Bromocriptine", "Cabergoline"]'::jsonb, 'Lysergic acid diethylamide (LSD)', '[]'::jsonb, 'LSD is a semisynthetic lysergic acid derivative whose 5-HT2A agonism in the cortex causes hallucinations at microgram doses. The other four are all in clinical use for migraine, obstetrics or hyperprolactinaemia. It is active by mouth and produces tolerance but little physical dependence.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.089 Q8, Ergot Alkaloids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-antagonists-and-ergot-alkalo-c16e961ce9', 'pharm-serotonin-antagonists-and-ergot-alkaloids', 'mcq', 'Ergot alkaloids have complex actions on which receptors?', '["Alpha-adrenoceptors", "Serotonin (5-HT) receptors", "Dopamine receptors", "All of the above", "None of the above"]'::jsonb, 'All of the above', '[]'::jsonb, 'Ergot alkaloids are partial agonists or antagonists at alpha-adrenoceptors, 5-HT receptors and dopamine receptors; the balance differs between members, which explains why ergotamine constricts vessels while bromocriptine mainly stimulates D2 receptors. No single receptor accounts for their effects, so choosing just one of the first three options is incomplete.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.089 Q9, Ergot Alkaloids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-antagonists-and-ergot-alkalo-cba4f86876', 'pharm-serotonin-antagonists-and-ergot-alkaloids', 'mcq', 'Ergotamine absorption from the GI tract is improved by co-administration with:', '["Milk", "Caffeine", "Antacids", "Propranolol", "Vitamin C"]'::jsonb, 'Caffeine', '[]'::jsonb, 'Oral ergotamine is poorly and erratically absorbed; caffeine increases its rate and extent of absorption, hence the combined tablets. Propranolol would add to the peripheral vasoconstriction rather than help absorption. Rectal, sublingual or inhaled routes are other ways round the poor oral absorption.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.089 Q10, Ergot Alkaloids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-antagonists-and-ergot-alkalo-2b4b5d91ad', 'pharm-serotonin-antagonists-and-ergot-alkaloids', 'mcq', 'Cabergoline is preferred over bromocriptine for hyperprolactinaemia because it:', '["Is cheaper", "Has a much longer half-life", "Is an injection", "Has no side effects", "Works on the liver"]'::jsonb, 'Has a much longer half-life', '[]'::jsonb, 'Cabergoline has a half-life of around 65 hours, so it is taken once or twice a week, and it is better tolerated and more effective at normalising prolactin. It is still an oral drug and can cause nausea and postural hypotension.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.089 Q11, Ergot Alkaloids. Removed the dosing hint from the correct option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-antagonists-and-ergot-alkalo-6a52949837', 'pharm-serotonin-antagonists-and-ergot-alkaloids', 'mcq', 'The effect of ergot alkaloids such as ergometrine on the uterus is characterised by:', '["Rhythmic contractions with relaxation", "Tetanic (sustained) contraction", "Total relaxation", "Increased blood flow to the placenta", "Thinning of the uterine wall"]'::jsonb, 'Tetanic (sustained) contraction', '[]'::jsonb, 'Ergometrine produces a prolonged, tonic contraction without relaxation between contractions. That is useful after delivery to stop bleeding, but before delivery it would cut off placental blood flow; oxytocin gives the rhythmic pattern. Sensitivity of the uterus to ergot rises towards term, so small doses suffice postpartum.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.090 Q12, Ergot Alkaloids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-antagonists-and-ergot-alkalo-1ff6f7d8d7', 'pharm-serotonin-antagonists-and-ergot-alkaloids', 'mcq', 'Ergotamine is contraindicated in patients with:', '["Peripheral vascular disease and coronary artery disease", "Asthma", "Glaucoma", "Peptic ulcers", "Obesity"]'::jsonb, 'Peripheral vascular disease and coronary artery disease', '[]'::jsonb, 'Because ergotamine is a powerful, long-lasting vasoconstrictor it can precipitate limb ischaemia, angina or infarction in people with obstructive vascular disease. It is also avoided in pregnancy and with CYP3A4 inhibitors. Asthma and glaucoma are not specific contraindications to the drug.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.090 Q13, Ergot Alkaloids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-antagonists-and-ergot-alkalo-f0e1999464', 'pharm-serotonin-antagonists-and-ergot-alkaloids', 'mcq', 'Methysergide was used for migraine prophylaxis but caused:', '["Liver failure", "Retroperitoneal and pleural fibrosis", "Sudden blindness", "Bone marrow suppression", "Seizures"]'::jsonb, 'Retroperitoneal and pleural fibrosis', '[]'::jsonb, 'Long-term methysergide, a 5-HT2 antagonist, causes retroperitoneal, pleural and cardiac valve fibrosis, so treatment had to be interrupted with drug holidays and the drug has largely been abandoned. Propranolol, amitriptyline, topiramate and valproate have replaced it; marrow suppression and seizures are not features.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.090 Q14, Ergot Alkaloids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-serotonin-antagonists-and-ergot-alkalo-43456dc26b', 'pharm-serotonin-antagonists-and-ergot-alkaloids', 'mcq', 'Which ergot derivative has been used to treat senile cognitive decline?', '["Ergotamine", "Dihydroergotoxine (co-dergocrine)", "LSD", "Ergometrine", "Methysergide"]'::jsonb, 'Dihydroergotoxine (co-dergocrine)', '[]'::jsonb, 'Co-dergocrine (ergoloid mesylates), a mixture of dihydrogenated ergot alkaloids, has been marketed for age-related cognitive impairment, although the evidence for benefit is weak. The others are used for migraine or in obstetrics, or are hallucinogenic.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.090 Q15, Ergot Alkaloids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-kinins-f65c5a1935', 'pharm-kinins', 'mcq', 'The most important kinins in humans are:', '["Histamine and serotonin", "Bradykinin and kallidin (lysyl-bradykinin)", "Angiotensin I and II", "Substance P and neurokinin A", "Endothelin and VIP"]'::jsonb, 'Bradykinin and kallidin (lysyl-bradykinin)', '[]'::jsonb, 'Bradykinin (a nonapeptide formed by plasma kallikrein) and kallidin (lysyl-bradykinin, formed by tissue kallikrein) are the principal kinins. Substance P is a tachykinin, a separate peptide family despite the similar name. Angiotensins come from a different precursor and constrict rather than dilate vessels.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.090 Q1, Kinins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-kinins-2ba8affb82', 'pharm-kinins', 'mcq', 'Kinins are formed from plasma proteins called:', '["Albumins", "Kininogens", "Globulins", "Fibrinogens", "Transferrins"]'::jsonb, 'Kininogens', '[]'::jsonb, 'High-molecular-weight kininogen is the substrate for plasma kallikrein, giving bradykinin, and low-molecular-weight kininogen is cleaved by tissue kallikrein to kallidin. They are alpha-2 globulins made in the liver; albumin, fibrinogen and transferrin have no role in kinin formation, although the names sound plausible.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.091 Q2, Kinins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-kinins-f669a86f7d', 'pharm-kinins', 'mcq', 'The enzyme responsible for the formation of kinins is:', '["ACE", "Kallikrein", "Renin", "Thrombin", "Pepsin"]'::jsonb, 'Kallikrein', '[]'::jsonb, 'Kallikreins are serine proteases that cleave kininogens to release kinins. ACE does the opposite: as kininase II it breaks bradykinin down. Plasma kallikrein is itself produced from prekallikrein by activated factor XII (Hageman factor) when blood contacts a negatively charged surface.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.091 Q3, Kinins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-kinins-66b1c0c31a', 'pharm-kinins', 'mcq', 'Bradykinin is a potent:', '["Vasoconstrictor", "Vasodilator", "Bronchodilator", "Anti-inflammatory agent", "Coagulant"]'::jsonb, 'Vasodilator', '[]'::jsonb, 'Acting on endothelial B2 receptors, bradykinin releases nitric oxide and prostacyclin, producing marked arteriolar dilatation and increased capillary permeability. In the airways it causes bronchoconstriction, not bronchodilatation. It is pro-inflammatory, not anti-inflammatory, producing redness, swelling and pain.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.091 Q4, Kinins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-kinins-d4af9500f6', 'pharm-kinins', 'mcq', 'The action of bradykinin is terminated by the enzyme:', '["Kallikrein", "Kininase II (angiotensin-converting enzyme)", "Monoamine oxidase", "Acetylcholinesterase", "Phosphodiesterase"]'::jsonb, 'Kininase II (angiotensin-converting enzyme)', '[]'::jsonb, 'Kininase II is the same enzyme as ACE; it removes the C-terminal dipeptide from bradykinin and inactivates it, mostly in the lung. Kallikrein forms kinins rather than destroying them. Kininase I (carboxypeptidase N) is a second degrading enzyme, giving the des-Arg kinins.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.091 Q5, Kinins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-kinins-50c89016e3', 'pharm-kinins', 'mcq', 'A common side effect of ACE inhibitors (such as captopril) is a dry cough, which is caused by the accumulation of:', '["Angiotensin I", "Bradykinin in the lungs", "Histamine", "Angiotensin II", "Renin"]'::jsonb, 'Bradykinin in the lungs', '[]'::jsonb, 'ACE normally degrades bradykinin; when it is inhibited, bradykinin (and substance P) accumulates in the airways and stimulates cough receptors. Angiotensin receptor blockers do not affect bradykinin breakdown, so they rarely cause cough. Angiotensin II levels fall on an ACE inhibitor, so it cannot be the cause.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.091 Q6, Kinins. Replaced the weak distractor ''Prostaglandins'' with ''Angiotensin II''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-kinins-9324fdfde5', 'pharm-kinins', 'mcq', 'Bradykinin produces pain by:', '["Blocking nerve endings", "Directly stimulating nociceptors", "Causing anaesthesia", "Inhibiting prostaglandins", "Reducing blood flow to nerves"]'::jsonb, 'Directly stimulating nociceptors', '[]'::jsonb, 'Bradykinin is one of the most potent pain-producing substances: it excites nociceptive nerve endings through B2 receptors. It also stimulates, rather than inhibits, prostaglandin synthesis, and the prostaglandins sensitise the endings further. Its pain-producing action is enhanced by PGE2, which is how NSAIDs reduce it.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.091 Q7, Kinins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-kinins-f38035c394', 'pharm-kinins', 'mcq', 'Which receptor mediates most of the pro-inflammatory and vasodilator effects of bradykinin?', '["B1 receptor", "B2 receptor", "B3 receptor", "B4 receptor", "H1 receptor"]'::jsonb, 'B2 receptor', '[]'::jsonb, 'B2 receptors are constitutively expressed and have high affinity for bradykinin and kallidin; they mediate the acute vasodilatation, oedema and pain. B1 receptors are induced only in inflamed or injured tissue. B3 and B4 receptors are not established kinin receptors in humans.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.091 Q8, Kinins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-kinins-4f0ab9ddb8', 'pharm-kinins', 'mcq', 'B1 receptors for kinins are unique because they are:', '["Present in high numbers in healthy tissue", "Induced (up-regulated) during chronic inflammation or injury", "Unresponsive to kinin metabolites", "Only found in the brain", "Ion channels"]'::jsonb, 'Induced (up-regulated) during chronic inflammation or injury', '[]'::jsonb, 'B1 receptors are scarce in normal tissue but are induced by cytokines such as IL-1 during inflammation and tissue injury; they respond to the des-Arg metabolites of the kinins. Like B2, they are G-protein-coupled receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.092 Q9, Kinins. Replaced the distractor ''Inhibited by steroids'' (arguably true of their induction) with a clearly wrong one.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-kinins-92ef56163f', 'pharm-kinins', 'mcq', 'Icatibant is a competitive B2 receptor antagonist used for the treatment of:', '["Hypertension", "Hereditary angioedema", "Asthma", "Peptic ulcers", "Migraine"]'::jsonb, 'Hereditary angioedema', '[]'::jsonb, 'Attacks of hereditary angioedema are driven by uncontrolled bradykinin production; subcutaneous icatibant blocks the B2 receptor and shortens the attack. Antihistamines and adrenaline work poorly because histamine is not the mediator. Ecallantide, a kallikrein inhibitor, and C1-inhibitor concentrate are alternatives.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.092 Q10, Kinins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-kinins-6ea1e14ef0', 'pharm-kinins', 'mcq', 'Hereditary angioedema is caused by a deficiency in:', '["ACE", "C1-esterase inhibitor", "Albumin", "Vitamin K", "Kallikrein"]'::jsonb, 'C1-esterase inhibitor', '[]'::jsonb, 'C1-esterase inhibitor normally restrains plasma kallikrein and factor XIIa as well as complement. Without it kallikrein is overactive and bradykinin is over-produced, causing recurrent swelling of skin, gut and larynx. ACE inhibitors are dangerous in these patients because they further slow bradykinin breakdown.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.092 Q11, Kinins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-kinins-33c25677b7', 'pharm-kinins', 'mcq', 'Kinins increase vascular permeability, leading to:', '["Dehydration", "Oedema", "High blood pressure", "Blood clots", "Dry skin"]'::jsonb, 'Oedema', '[]'::jsonb, 'Kinins make endothelial cells of post-capillary venules contract, opening gaps through which plasma leaks into the tissues. Together with arteriolar dilatation this gives the swelling and redness of inflammation; blood pressure falls rather than rises.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.092 Q12, Kinins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-kinins-b2a6f3d2c5', 'pharm-kinins', 'mcq', 'In the kidney, kinins act to:', '["Decrease blood flow", "Increase renal blood flow and promote sodium and water excretion", "Cause severe vasoconstriction", "Inhibit renin", "Cause kidney stones"]'::jsonb, 'Increase renal blood flow and promote sodium and water excretion', '[]'::jsonb, 'Renal kallikrein generates kinins that dilate renal vessels and inhibit sodium and water reabsorption in the collecting duct, partly through prostaglandins and nitric oxide, giving natriuresis and diuresis. This renal action is one reason ACE inhibitors, which preserve kinins, lower blood pressure more than expected from angiotensin alone.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.092 Q13, Kinins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-kinins-07ffa13845', 'pharm-kinins', 'mcq', 'Which of the following describes the kallikrein-kinin system?', '["It is part of the blood coagulation and inflammatory response", "It only works in the brain", "It is the primary cause of diabetes", "It is inhibited by caffeine", "It has no role in blood pressure"]'::jsonb, 'It is part of the blood coagulation and inflammatory response', '[]'::jsonb, 'Plasma prekallikrein is activated by factor XIIa of the contact (intrinsic coagulation) system, and the kinins released are mediators of inflammation. The system acts throughout the body and lowers blood pressure by vasodilatation. Kinin breakdown by ACE links the system to the renin-angiotensin system.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.092 Q14, Kinins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-kinins-da1479b6c5', 'pharm-kinins', 'mcq', 'Aprotinin is a drug that:', '["Stimulates kinin production", "Inhibits kallikrein and other serine proteases", "Blocks B2 receptors", "Is a synthetic kinin", "Is used for asthma"]'::jsonb, 'Inhibits kallikrein and other serine proteases', '[]'::jsonb, 'Aprotinin is a polypeptide protease inhibitor that blocks kallikrein and plasmin; it was used to reduce blood loss in cardiac surgery. The B2 receptor blocker is icatibant. It was restricted after studies linked it to renal failure and increased mortality; tranexamic acid is now usually preferred.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.093 Q15, Kinins. Removed the hint in brackets from the correct option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-the-polypeptides-697b07c6df', 'pharm-the-polypeptides', 'mcq', 'Angiotensin II is a potent:', '["Vasodilator", "Vasoconstrictor", "Diuretic", "Sedative", "Antipyretic"]'::jsonb, 'Vasoconstrictor', '[]'::jsonb, 'Angiotensin II constricts arterioles directly through AT1 receptors and also facilitates sympathetic transmission, raising blood pressure. It promotes salt and water retention through aldosterone, the opposite of a diuretic. It has no sedative or antipyretic action; ACE inhibitors and angiotensin receptor blockers lower blood pressure by removing this effect.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.093 Q1, Vasoactive Peptides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-the-polypeptides-fa58ecd34f', 'pharm-the-polypeptides', 'mcq', 'The rate-limiting enzyme in the production of angiotensin II is:', '["ACE", "Renin", "Kallikrein", "Thrombin", "Pepsin"]'::jsonb, 'Renin', '[]'::jsonb, 'Renin, released from juxtaglomerular cells, cleaves angiotensinogen to angiotensin I, and this step sets the rate of the whole cascade. ACE is abundant and converts angiotensin I to II without limiting the rate. Aliskiren inhibits renin directly; beta-blockers reduce its release.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.093 Q2, Vasoactive Peptides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-the-polypeptides-3ee79d5ef4', 'pharm-the-polypeptides', 'mcq', 'Angiotensin II acts on AT1 receptors to cause:', '["Vasodilatation and salt loss", "Vasoconstriction and release of aldosterone", "Bronchodilatation", "Decreased heart rate", "Increased urine output"]'::jsonb, 'Vasoconstriction and release of aldosterone', '[]'::jsonb, 'AT1 receptors (Gq-coupled) mediate nearly all the classical effects: arteriolar constriction, aldosterone secretion from the adrenal cortex, sodium retention, thirst and cardiac and vascular remodelling. Losartan and other sartans block this receptor. AT2 receptors, by contrast, mediate vasodilatation and antiproliferative effects.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.093 Q3, Vasoactive Peptides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-the-polypeptides-5816f7bcce', 'pharm-the-polypeptides', 'mcq', 'Vasopressin (antidiuretic hormone) primarily acts on V2 receptors in the kidney to:', '["Excrete water", "Reabsorb water", "Excrete sodium", "Constrict blood vessels", "Increase heart rate"]'::jsonb, 'Reabsorb water', '[]'::jsonb, 'V2 receptors on collecting duct cells raise cAMP, which inserts aquaporin-2 channels into the luminal membrane so water is reabsorbed and urine is concentrated. Vasoconstriction is a V1 receptor effect. Desmopressin is a selective V2 agonist used in cranial diabetes insipidus; tolvaptan blocks the receptor.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.093 Q4, Vasoactive Peptides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-the-polypeptides-e44f8054e4', 'pharm-the-polypeptides', 'mcq', 'V1 receptors for vasopressin are located on vascular smooth muscle and cause:', '["Vasodilatation", "Vasoconstriction", "Bronchospasm", "Reduced GI motility", "Skeletal muscle relaxation"]'::jsonb, 'Vasoconstriction', '[]'::jsonb, 'V1 receptors couple to Gq, raising IP3 and intracellular calcium and contracting vascular smooth muscle. This pressor effect is used in vasodilatory shock and, with terlipressin, in bleeding oesophageal varices. V1 stimulation of gut smooth muscle increases, not reduces, motility and can cause abdominal cramps.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.093 Q5, Vasoactive Peptides. Two vague distractors (''GI motility'', ''Muscle relaxation'') were made specific.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-the-polypeptides-2e0251c94d', 'pharm-the-polypeptides', 'mcq', 'Atrial natriuretic peptide (ANP) is released by the heart in response to:', '["Dehydration", "Atrial stretch from increased blood volume", "Low plasma sodium", "Low blood pressure", "Sleep"]'::jsonb, 'Atrial stretch from increased blood volume', '[]'::jsonb, 'Atrial myocytes release ANP when the atria are distended by volume expansion. The peptide then lowers volume by natriuresis and vasodilatation; dehydration and hypotension suppress its release. BNP is released in the same way from stretched ventricles and is measured as a marker of heart failure.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.094 Q6, Vasoactive Peptides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-the-polypeptides-2cbd29b349', 'pharm-the-polypeptides', 'mcq', 'The primary effect of atrial natriuretic peptide (ANP) is to:', '["Increase blood pressure", "Promote natriuresis and vasodilatation", "Conserve water", "Stimulate aldosterone", "Cause thirst"]'::jsonb, 'Promote natriuresis and vasodilatation', '[]'::jsonb, 'ANP activates membrane guanylyl cyclase, raising cGMP; this increases glomerular filtration and sodium excretion, relaxes vessels and inhibits renin and aldosterone release. It therefore opposes the renin-angiotensin system. Neprilysin breaks ANP down, so the neprilysin inhibitor sacubitril prolongs these beneficial actions in heart failure.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.094 Q7, Vasoactive Peptides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-the-polypeptides-5f3963f899', 'pharm-the-polypeptides', 'mcq', 'Endothelins are a group of peptides known as the most potent endogenous:', '["Vasodilators", "Vasoconstrictors", "Antibiotics", "Analgesics", "Anticoagulants"]'::jsonb, 'Vasoconstrictors', '[]'::jsonb, 'Endothelin-1, made by vascular endothelium, causes intense and long-lasting vasoconstriction through ETA receptors on smooth muscle, and it is more potent than angiotensin II or noradrenaline. ETB receptors on endothelium release nitric oxide and prostacyclin, which partly offsets the constriction; the peptides have no antimicrobial or analgesic role.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.094 Q8, Vasoactive Peptides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-the-polypeptides-5296fcddd3', 'pharm-the-polypeptides', 'mcq', 'Bosentan is a dual endothelin receptor antagonist used for:', '["Systemic hypertension", "Pulmonary arterial hypertension", "Heart failure", "Asthma", "Diabetes"]'::jsonb, 'Pulmonary arterial hypertension', '[]'::jsonb, 'Bosentan blocks ETA and ETB receptors, reducing pulmonary vascular resistance and remodelling in pulmonary arterial hypertension. It is hepatotoxic and teratogenic and is not used for ordinary hypertension or heart failure. Ambrisentan is selective for the ETA receptor and has the same indication.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.094 Q9, Vasoactive Peptides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-the-polypeptides-62518ccf41', 'pharm-the-polypeptides', 'mcq', 'Substance P is a peptide involved in:', '["Pain transmission and ''neurogenic'' inflammation", "Lowering blood sugar", "Strengthening bones", "Blood clotting", "Sleep"]'::jsonb, 'Pain transmission and ''neurogenic'' inflammation', '[]'::jsonb, 'Substance P is a tachykinin released from the central and peripheral endings of nociceptive C fibres. Centrally it transmits pain; peripherally it causes vasodilatation and plasma leakage (neurogenic inflammation) through NK1 receptors. Capsaicin depletes substance P from these fibres, which is the basis of its topical analgesic use.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.094 Q10, Vasoactive Peptides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-the-polypeptides-48a138779d', 'pharm-the-polypeptides', 'mcq', 'Aprepitant is a neurokinin-1 (NK1) receptor antagonist used for:', '["Pain relief", "Prevention of chemotherapy-induced nausea and vomiting", "Hypertension", "Glaucoma", "Asthma"]'::jsonb, 'Prevention of chemotherapy-induced nausea and vomiting', '[]'::jsonb, 'Aprepitant blocks substance P at NK1 receptors in the brainstem vomiting centre and is added to a 5-HT3 antagonist and dexamethasone, being particularly useful for delayed emesis after cisplatin. NK1 antagonists proved disappointing as analgesics.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.094 Q11, Vasoactive Peptides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-the-polypeptides-2ee28bc5ae', 'pharm-the-polypeptides', 'mcq', 'Vasoactive intestinal peptide (VIP) primarily causes:', '["Intense vasoconstriction", "Relaxation of smooth muscle and vasodilatation", "Decreased intestinal secretion", "Constipation", "Pupil dilatation"]'::jsonb, 'Relaxation of smooth muscle and vasodilatation', '[]'::jsonb, 'VIP raises cAMP in smooth muscle, relaxing vascular, bronchial and gut muscle, and it stimulates intestinal water and electrolyte secretion; VIP-secreting tumours cause profuse watery diarrhoea. It inhibits gastric acid secretion. It is also a co-transmitter in parasympathetic and enteric nerves.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.095 Q12, Vasoactive Peptides. Replaced the distractor ''Increased gastric acid'' with ''Decreased intestinal secretion'' for clarity.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-the-polypeptides-353daaf0e9', 'pharm-the-polypeptides', 'mcq', 'Nesiritide, used in acute heart failure, is a recombinant form of which peptide?', '["ANP", "BNP (brain natriuretic peptide)", "VIP", "Angiotensin II", "Endothelin"]'::jsonb, 'BNP (brain natriuretic peptide)', '[]'::jsonb, 'Nesiritide is recombinant human B-type natriuretic peptide; it raises cGMP, causing venous and arterial dilatation and natriuresis in acute decompensated heart failure. The recombinant ANP is carperitide. It can cause marked hypotension, and trials showed no survival benefit, so its use has declined.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.095 Q13, Vasoactive Peptides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-the-polypeptides-05770b1ce9', 'pharm-the-polypeptides', 'mcq', 'Which peptide is a potent vasodilator and is involved in the pathogenesis of migraine?', '["Calcitonin gene-related peptide (CGRP)", "Substance P", "Vasopressin", "Angiotensin III", "Endothelin-1"]'::jsonb, 'Calcitonin gene-related peptide (CGRP)', '[]'::jsonb, 'CGRP is released from trigeminal nerve endings around cranial vessels during a migraine attack, causing vasodilatation and pain signalling. Triptans reduce its release, and gepants and monoclonal antibodies block it or its receptor. Substance P is released alongside it but blocking it does not relieve migraine.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.095 Q14, Vasoactive Peptides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-the-polypeptides-717f59ed65', 'pharm-the-polypeptides', 'mcq', 'Erenumab is a monoclonal antibody that prevents migraine by blocking the receptor for which peptide?', '["Histamine", "CGRP", "VIP", "Substance P", "Neuropeptide Y"]'::jsonb, 'CGRP', '[]'::jsonb, 'Erenumab binds the calcitonin gene-related peptide receptor and is given by monthly injection for migraine prophylaxis. Fremanezumab and galcanezumab bind the CGRP peptide itself rather than its receptor. Constipation and injection-site reactions are its main adverse effects; small-molecule receptor antagonists (gepants) are used for acute attacks.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.095 Q15, Vasoactive Peptides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-nitric-oxide-990d6a2c48', 'pharm-nitric-oxide', 'mcq', 'Nitric oxide (NO) is also known as:', '["Prostacyclin", "Endothelium-derived relaxing factor (EDRF)", "Kallikrein", "Substance P", "Angiotensin"]'::jsonb, 'Endothelium-derived relaxing factor (EDRF)', '[]'::jsonb, 'Furchgott showed that acetylcholine relaxes vessels only if the endothelium is intact, through a diffusible factor called EDRF, later identified as nitric oxide. Prostacyclin is also an endothelial vasodilator but is a separate, COX-derived mediator.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.095 Q1, Nitric Oxide (NO)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-nitric-oxide-c929c6bcb4', 'pharm-nitric-oxide', 'mcq', 'Nitric oxide is synthesised from the amino acid:', '["Tyrosine", "L-arginine", "L-citrulline", "Histidine", "Tryptophan"]'::jsonb, 'L-arginine', '[]'::jsonb, 'Nitric oxide synthase oxidises the guanidino nitrogen of L-arginine using oxygen and NADPH, giving NO and L-citrulline. Citrulline is therefore the by-product, not the precursor. The competitive analogue L-NMMA inhibits the enzyme and is used experimentally to block NO production.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.095 Q2, Nitric Oxide (NO)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-nitric-oxide-b73f87e8cf', 'pharm-nitric-oxide', 'mcq', 'The enzyme responsible for the production of nitric oxide is:', '["Nitric oxide synthase (NOS)", "ACE", "Cyclooxygenase", "MAO", "NADPH oxidase"]'::jsonb, 'Nitric oxide synthase (NOS)', '[]'::jsonb, 'The three NOS isoforms (neuronal, inducible and endothelial) convert L-arginine to NO and citrulline. NADPH oxidase produces superoxide, which actually destroys NO. The enzyme needs NADPH, tetrahydrobiopterin, FAD and FMN as cofactors. Cyclooxygenase makes prostaglandins and ACE makes angiotensin II.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.096 Q3, Nitric Oxide (NO)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-nitric-oxide-bba38d1bda', 'pharm-nitric-oxide', 'mcq', 'The isoform of nitric oxide synthase that is induced during inflammation (for example in sepsis) is:', '["eNOS (endothelial)", "nNOS (neuronal)", "iNOS (inducible)", "mNOS (mitochondrial)", "pNOS (platelet)"]'::jsonb, 'iNOS (inducible)', '[]'::jsonb, 'iNOS (NOS-2) is not normally present; cytokines and bacterial endotoxin induce it in macrophages and other cells, where it makes large amounts of NO independently of calcium. eNOS and nNOS are constitutive and calcium-calmodulin dependent.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.096 Q4, Nitric Oxide (NO)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-nitric-oxide-7521ff99d4', 'pharm-nitric-oxide', 'mcq', 'Nitric oxide produces vasodilatation by activating which intracellular enzyme?', '["Adenylyl cyclase", "Soluble guanylyl cyclase", "Phosphodiesterase", "Protein kinase C", "Tyrosine kinase"]'::jsonb, 'Soluble guanylyl cyclase', '[]'::jsonb, 'NO diffuses into smooth muscle and binds the haem group of soluble guanylyl cyclase, raising cGMP; protein kinase G then lowers intracellular calcium and dephosphorylates myosin light chains. Adenylyl cyclase is the target of beta-2 agonists.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.096 Q5, Nitric Oxide (NO)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-nitric-oxide-66cb30776c', 'pharm-nitric-oxide', 'mcq', 'The second messenger produced following nitric oxide activation of its target enzyme is:', '["cAMP", "cGMP", "IP3", "DAG", "Ca2+"]'::jsonb, 'cGMP', '[]'::jsonb, 'Soluble guanylyl cyclase converts GTP to cyclic GMP, which activates protein kinase G to relax smooth muscle. The signal is ended by phosphodiesterases, notably PDE5, which is why sildenafil prolongs NO effects. cAMP is the messenger for beta-adrenoceptors, not NO.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.096 Q6, Nitric Oxide (NO)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-nitric-oxide-a38b882043', 'pharm-nitric-oxide', 'mcq', 'Nitric oxide acts to:', '["Stimulate platelet aggregation", "Inhibit platelet aggregation and adhesion", "Cause potent vasoconstriction", "Increase vascular smooth muscle proliferation", "Decrease blood flow to the brain"]'::jsonb, 'Inhibit platelet aggregation and adhesion', '[]'::jsonb, 'Endothelial NO raises cGMP in platelets, preventing their adhesion and aggregation, and it relaxes and has an antiproliferative effect on vascular smooth muscle. Loss of NO in endothelial dysfunction therefore favours thrombosis and atherosclerosis. NO also limits leucocyte adhesion to the vessel wall.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.096 Q7, Nitric Oxide (NO)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-nitric-oxide-f32a95832c', 'pharm-nitric-oxide', 'mcq', 'Organic nitrates (such as nitroglycerin) work by:', '["Blocking calcium channels", "Being converted to nitric oxide in the body", "Inhibiting COX", "Stimulating beta-2 receptors", "Blocking alpha-1 receptors"]'::jsonb, 'Being converted to nitric oxide in the body', '[]'::jsonb, 'Glyceryl trinitrate is denitrated in vascular smooth muscle (by mitochondrial aldehyde dehydrogenase) to release NO, which raises cGMP and relaxes veins more than arteries, reducing preload and myocardial oxygen demand. Continuous exposure leads to tolerance, so a daily nitrate-free interval is needed.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.096 Q8, Nitric Oxide (NO)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-nitric-oxide-ca6aadee27', 'pharm-nitric-oxide', 'mcq', 'Inhaled nitric oxide is used clinically for:', '["General anaesthesia", "Persistent pulmonary hypertension of the newborn", "Systemic hypertension", "Asthma", "Diabetes"]'::jsonb, 'Persistent pulmonary hypertension of the newborn', '[]'::jsonb, 'Inhaled NO dilates pulmonary vessels in ventilated lung and is inactivated by haemoglobin before reaching the systemic circulation, so pulmonary pressure falls without systemic hypotension. The anaesthetic gas is nitrous oxide (N2O), a different molecule.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.097 Q9, Nitric Oxide (NO)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-nitric-oxide-118d190664', 'pharm-nitric-oxide', 'mcq', 'Sildenafil works by inhibiting which enzyme to prolong the action of cGMP?', '["PDE-3", "PDE-4", "PDE-5", "NOS", "ACE"]'::jsonb, 'PDE-5', '[]'::jsonb, 'Phosphodiesterase type 5 breaks down cGMP in the corpus cavernosum and pulmonary vessels; inhibiting it enhances NO-mediated relaxation. PDE-3 inhibitors (milrinone) and PDE-4 inhibitors (roflumilast) act mainly on cAMP. Tadalafil and vardenafil act the same way; sildenafil is also licensed for pulmonary arterial hypertension.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.097 Q10, Nitric Oxide (NO)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-nitric-oxide-cda86bab82', 'pharm-nitric-oxide', 'mcq', 'A major risk of combining nitroglycerin and sildenafil is:', '["Severe hypertension", "Severe, life-threatening hypotension", "Sudden blindness", "Kidney failure", "Liver failure"]'::jsonb, 'Severe, life-threatening hypotension', '[]'::jsonb, 'Nitrates increase cGMP production while sildenafil blocks its breakdown, so the combination causes profound vasodilatation and a dangerous fall in blood pressure. Nitrates are contraindicated within 24 hours of sildenafil (48 hours for tadalafil). Riociguat, a guanylyl cyclase stimulator, carries the same warning.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.097 Q11, Nitric Oxide (NO)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-nitric-oxide-47af045d9a', 'pharm-nitric-oxide', 'mcq', 'Sodium nitroprusside is used in hypertensive emergencies because it:', '["Increases heart rate", "Releases nitric oxide spontaneously to cause rapid vasodilatation", "Blocks renin release", "Is a potent diuretic", "Acts on the brain"]'::jsonb, 'Releases nitric oxide spontaneously to cause rapid vasodilatation', '[]'::jsonb, 'Nitroprusside releases NO non-enzymatically, dilating both arterioles and veins within seconds, and its effect stops within minutes of ending the infusion, so pressure can be titrated. Prolonged use risks cyanide and thiocyanate toxicity. It must be protected from light and given with arterial pressure monitoring.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.097 Q12, Nitric Oxide (NO)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-nitric-oxide-5c89068543', 'pharm-nitric-oxide', 'mcq', 'Excessive production of nitric oxide by iNOS in septic shock contributes to:', '["Hypertension", "Severe, refractory hypotension", "Blood clots", "Bronchospasm", "Excessive urination"]'::jsonb, 'Severe, refractory hypotension', '[]'::jsonb, 'Endotoxin and cytokines induce iNOS in vessel walls and macrophages, producing large amounts of NO that cause widespread vasodilatation and poor responsiveness to vasoconstrictors, the hallmark of septic shock. The NO also depresses myocardial contractility, but non-selective NOS inhibitors worsened outcome in trials.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.097 Q13, Nitric Oxide (NO)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-nitric-oxide-4d1121aac0', 'pharm-nitric-oxide', 'mcq', 'Nitric oxide in the central nervous system functions as a:', '["Classical neurotransmitter stored in vesicles", "Retrograde messenger involved in long-term potentiation", "Hormone released into the blood", "Component of the myelin sheath", "Barrier to drug entry"]'::jsonb, 'Retrograde messenger involved in long-term potentiation', '[]'::jsonb, 'NO is a gas that cannot be stored; it is made on demand by nNOS after NMDA receptor activation and diffuses back to the presynaptic terminal to strengthen transmitter release, contributing to long-term potentiation. In excess, as in stroke, it contributes to excitotoxic neuronal damage.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.097 Q14, Nitric Oxide (NO)') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-beta-lactam-antibiotic-f6fccbb224', 'pharm-introduction-to-beta-lactam-antibiotics-penicillins-pen-g-and-pe', 'mcq', 'All of the following are true of the natural penicillins EXCEPT:', '["Oral bioavailability of penicillin G is about 30%", "Penicillin V is stable against gastric acid", "Penicillin G is excreted largely unchanged in the urine", "Reabsorption in the renal tubules is inhibited by probenecid", "They are effective against gram-positive organisms and a few gram-negative organisms"]'::jsonb, 'Reabsorption in the renal tubules is inhibited by probenecid', '[]'::jsonb, 'Penicillins are eliminated mainly by active tubular secretion, and probenecid blocks that secretion, prolonging their action; it has nothing to do with reabsorption. Penicillin G is acid-labile, so only about a third of an oral dose is absorbed, whereas penicillin V survives gastric acid.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.099 Q1, CAT 2 quiz: Penicillins. Option c reworded from ''is not metabolized in the body'' (debatable) to ''excreted largely unchanged''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-penicillins-anti-staphylococcal--881a0ee4c8', 'pharm-other-penicillins-anti-staphylococcal-penicillins-amino-penicill', 'mcq', 'Which of the following is true of piperacillin?', '["It is administered via the oral route", "It is not plasma protein bound", "It is distributed only in renal tissue", "It is completely metabolised before excretion", "Its dose should be adjusted in renal failure"]'::jsonb, 'Its dose should be adjusted in renal failure', '[]'::jsonb, 'Piperacillin is acid-labile and given only parenterally; most of the dose is excreted unchanged by the kidney, so it accumulates in renal impairment and the dose must be reduced. It distributes widely and is partly protein bound.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.099 Q3, CAT 2 quiz: Penicillins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-penicillins-anti-staphylococcal--8dd31f0bb0', 'pharm-other-penicillins-anti-staphylococcal-penicillins-amino-penicill', 'mcq', 'Which is NOT an indication for piperacillin combined with tazobactam?', '["Endocarditis prophylaxis before dental procedures in patients with heart disease", "Serious infections by gram-negative organisms", "Hospital-acquired infections", "Mixed intra-abdominal infections", "Infections in neutropenic patients"]'::jsonb, 'Endocarditis prophylaxis before dental procedures in patients with heart disease', '[]'::jsonb, 'Piperacillin-tazobactam is a broad-spectrum intravenous agent reserved for severe hospital infections, including Pseudomonas, anaerobic and neutropenic sepsis. Dental prophylaxis of endocarditis needs only cover for viridans streptococci, for which oral amoxicillin is used. Using it for prophylaxis would be unnecessary and would promote resistance.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.100 Q4, CAT 2 quiz: Penicillins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-beta-lactam-antibiotic-55685be5d5', 'pharm-introduction-to-beta-lactam-antibiotics-penicillins-pen-g-and-pe', 'mcq', 'Which penicillin is used in the prophylaxis of rheumatic fever?', '["Benzathine penicillin G", "Cloxacillin", "Amoxicillin", "Carbenicillin", "Ticarcillin"]'::jsonb, 'Benzathine penicillin G', '[]'::jsonb, 'Intramuscular benzathine penicillin forms a depot that releases penicillin G slowly, giving low but adequate levels against Streptococcus pyogenes for 3 to 4 weeks, so monthly injections prevent recurrences of rheumatic fever. Its levels are too low for acute severe infection, where benzylpenicillin is given intravenously.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.101 Q13, CAT 2 quiz: Penicillins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-beta-lactam-antibiotic-349c671925', 'pharm-introduction-to-beta-lactam-antibiotics-penicillins-pen-g-and-pe', 'mcq', 'Which is a narrow-spectrum penicillin?', '["Piperacillin", "Carbenicillin", "Amoxicillin", "Ampicillin", "Penicillin V"]'::jsonb, 'Penicillin V', '[]'::jsonb, 'Penicillin V, like penicillin G, covers mainly gram-positive cocci, gram-negative cocci and spirochaetes. The aminopenicillins, carboxypenicillins and ureidopenicillins are the extended-spectrum penicillins with added gram-negative cover. Narrow spectrum here means activity confined largely to gram-positive bacteria, and it is also destroyed by beta-lactamase.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.102 Q17, CAT 2 quiz: Penicillins. Replaced option ''Cloxacillin'' (also narrow spectrum, so two answers were right) with ''Amoxicillin''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cephalosporins-and-cephamycins-6bf3708bab', 'pharm-cephalosporins-and-cephamycins', 'mcq', 'Which of the following is a third-generation cephalosporin?', '["Cephalexin", "Ceftazidime", "Cefuroxime", "Loracarbef", "Cefepime"]'::jsonb, 'Ceftazidime', '[]'::jsonb, 'Ceftazidime, ceftriaxone and cefotaxime are third-generation agents with expanded gram-negative cover. Cephalexin is first generation, cefuroxime and loracarbef second, and cefepime fourth. A useful rule: gram-negative activity and beta-lactamase stability increase from the first to the third generation, while activity against staphylococci declines somewhat.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.102 Q1, CAT 2 quiz: Cephalosporins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cephalosporins-and-cephamycins-68fcccf159', 'pharm-cephalosporins-and-cephamycins', 'mcq', 'Which one of the following statements about cefotetan is accurate?', '["It is active against MRSA strains", "It is the drug of choice in community-acquired pneumonia", "It is a fourth-generation cephalosporin", "It decreases prothrombin time", "Its antibacterial spectrum includes Bacteroides fragilis"]'::jsonb, 'Its antibacterial spectrum includes Bacteroides fragilis', '[]'::jsonb, 'Cefotetan is a second-generation cephamycin with good anaerobic activity, including Bacteroides fragilis, so it is used in abdominal and pelvic infections. Its methylthiotetrazole side chain can prolong, not shorten, the prothrombin time. It does not cover MRSA, and it can cause a disulfiram-like reaction with alcohol.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.102 Q2, CAT 2 quiz: Cephalosporins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cephalosporins-and-cephamycins-559af9f734', 'pharm-cephalosporins-and-cephamycins', 'mcq', 'Cefotaxime has all of the following properties EXCEPT:', '["It is highly active against aerobic gram-negative bacteria", "It is the most active cephalosporin against Pseudomonas aeruginosa", "It produces an active metabolite", "It has achieved high cure rates in serious hospital-acquired infections", "It is widely distributed to body tissues and fluids"]'::jsonb, 'It is the most active cephalosporin against Pseudomonas aeruginosa', '[]'::jsonb, 'Cefotaxime has poor antipseudomonal activity; ceftazidime (and cefepime) are the cephalosporins for Pseudomonas. Cefotaxime is deacetylated to an active metabolite and penetrates tissues and CSF well. It is nevertheless valuable in meningitis and gram-negative sepsis, particularly in neonates where ceftriaxone is avoided.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.102 Q3, CAT 2 quiz: Cephalosporins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cephalosporins-and-cephamycins-28bc2888bb', 'pharm-cephalosporins-and-cephamycins', 'mcq', 'The most common cause of resistance to ceftriaxone is:', '["Alteration of the porin structure", "Efflux pump", "Alteration of the penicillin-binding protein", "Beta-lactamase production", "Inactivation by transferases"]'::jsonb, 'Beta-lactamase production', '[]'::jsonb, 'Hydrolysis of the beta-lactam ring by beta-lactamases, particularly extended-spectrum (ESBL) and AmpC enzymes in gram-negative bacilli, is the commonest resistance mechanism to third-generation cephalosporins. Altered PBPs matter mainly in pneumococci and MRSA. Carbapenems are used when ESBL-producing organisms are suspected.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.102 Q4, CAT 2 quiz: Cephalosporins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cephalosporins-and-cephamycins-efc4b8a740', 'pharm-cephalosporins-and-cephamycins', 'mcq', 'Which is a second-generation cephalosporin?', '["Cefadroxil", "Cefazolin", "Cephalexin", "Cephalothin", "Cefuroxime"]'::jsonb, 'Cefuroxime', '[]'::jsonb, 'Cefuroxime, cefaclor, cefamandole and the cephamycins cefoxitin and cefotetan form the second generation, with better activity against Haemophilus and some Enterobacteriaceae. The other four options are all first generation. Cefuroxime axetil is the oral prodrug form.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.103 Q10, CAT 2 quiz: Cephalosporins') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-carbapenems-and-monobactams-fe43e14f97', 'pharm-carbapenems-and-monobactams', 'mcq', 'Which statement regarding carbapenems is FALSE?', '["Meropenem is more likely to cause seizures than imipenem", "Ertapenem can be administered once daily", "Mechanisms of resistance include drug efflux pumps and carbapenemases", "Imipenem is combined with cilastatin to inhibit renal metabolism of imipenem", "Doripenem has greater antipseudomonal activity than imipenem"]'::jsonb, 'Meropenem is more likely to cause seizures than imipenem', '[]'::jsonb, 'Imipenem is the carbapenem most associated with seizures, especially at high dose or in renal failure; meropenem is less epileptogenic and is preferred for meningitis. Cilastatin inhibits renal dehydropeptidase I, which would otherwise inactivate imipenem.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.104 Q1, CAT 2 quiz: Carbapenems') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-carbapenems-and-monobactams-439e35cf9e', 'pharm-carbapenems-and-monobactams', 'mcq', 'Which statement regarding carbapenems is TRUE?', '["Enterococcus faecium is susceptible to imipenem", "Ertapenem has inferior activity against Pseudomonas aeruginosa", "Meropenem can cause seizures in up to 5% of patients", "Ertapenem is combined with cilastatin to prevent renal tubular degradation", "Imipenem can be administered via the oral route"]'::jsonb, 'Ertapenem has inferior activity against Pseudomonas aeruginosa', '[]'::jsonb, 'Ertapenem has a long half-life allowing once-daily dosing but lacks useful activity against Pseudomonas and Acinetobacter. Only imipenem needs cilastatin, all carbapenems are parenteral, and Enterococcus faecium and MRSA are resistant. It suits community-acquired mixed infections treated once daily.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.104 Q2, CAT 2 quiz: Carbapenems') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-carbapenems-and-monobactams-e30cf0bf36', 'pharm-carbapenems-and-monobactams', 'mcq', 'Which of the following is NOT a monobactam?', '["Aztreonam", "Tigemonam", "Nocardicin A", "Tabtoxin", "Streptogramin B"]'::jsonb, 'Streptogramin B', '[]'::jsonb, 'Monobactams have a single beta-lactam ring not fused to a second ring; aztreonam is the clinical example, and tigemonam, nocardicin A and tabtoxin are other monocyclic beta-lactams. Streptogramin B (quinupristin) is a protein synthesis inhibitor acting on the 50S subunit.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.104 Q1, CAT 2 quiz: Monobactams') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-carbapenems-and-monobactams-e531ce3cc9', 'pharm-carbapenems-and-monobactams', 'mcq', 'Which statement regarding monobactams is INCORRECT?', '["They are bacteriostatic", "Aztreonam is an example", "They are active against gram-negative bacteria", "They require dose adjustment in renal impairment", "They may exhibit cross-sensitivity with ceftazidime"]'::jsonb, 'They are bacteriostatic', '[]'::jsonb, 'Aztreonam binds PBP3 of aerobic gram-negative rods and is bactericidal, like other beta-lactams. It is renally excreted, and although it is generally safe in penicillin allergy it shares a side chain with ceftazidime, so cross-reactivity can occur.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.104 Q2, CAT 2 quiz: Monobactams') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-beta-lactam-antibiotic-2e1a9b0a1b', 'pharm-introduction-to-beta-lactam-antibiotics-penicillins-pen-g-and-pe', 'mcq', 'Which statement about beta-lactamase inhibitors is TRUE?', '["They are effective antibacterial agents on their own", "They inhibit all bacterial beta-lactamases", "They protect hydrolysable penicillins from destruction by beta-lactamases", "The antibacterial spectrum is determined by the inhibitor in fixed combinations", "In fixed combinations with a penicillin, dosage adjustment is based on both components"]'::jsonb, 'They protect hydrolysable penicillins from destruction by beta-lactamases', '[]'::jsonb, 'Clavulanic acid, sulbactam and tazobactam have weak antibacterial action; they bind and inactivate mainly class A beta-lactamases so the partner penicillin survives. The spectrum and the dosing are determined by the penicillin, not the inhibitor.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.104 Q1, CAT 2 quiz: Beta lactamase inhibitors') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-beta-lactam-antibiotic-18fa187bca', 'pharm-introduction-to-beta-lactam-antibiotics-penicillins-pen-g-and-pe', 'mcq', 'All of the following are true of beta-lactamase inhibitors EXCEPT:', '["They inhibit all beta-lactamases", "The antibacterial spectrum is determined by the penicillin in the combination", "Combinations are indicated for mixed infections", "They are most active against Ambler class A beta-lactamases", "They have weak antibacterial action"]'::jsonb, 'They inhibit all beta-lactamases', '[]'::jsonb, 'The classical inhibitors are active mainly against plasmid-encoded class A enzymes; they are poor inhibitors of class C (AmpC) cephalosporinases and of metallo-beta-lactamases. So they do not inhibit all beta-lactamases. Newer inhibitors such as avibactam extend cover to class C and some class D enzymes.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.105 Q2, CAT 2 quiz: Beta lactamase inhibitors') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-beta-lactam-antibiotic-d02411f22d', 'pharm-introduction-to-beta-lactam-antibiotics-penicillins-pen-g-and-pe', 'mcq', 'Which beta-lactamase inhibitor is used in combination with amoxicillin to treat infections caused by beta-lactamase-producing bacteria?', '["Nalidixic acid", "Clavulanic acid", "Ticarcillin", "Mezlocillin", "Azlocillin"]'::jsonb, 'Clavulanic acid', '[]'::jsonb, 'Clavulanic acid is a ''suicide'' inhibitor that binds beta-lactamase irreversibly, protecting amoxicillin (co-amoxiclav). Ticarcillin, mezlocillin and azlocillin are themselves penicillins, and nalidixic acid is a quinolone. Clavulanate adds a risk of cholestatic jaundice and more diarrhoea than amoxicillin alone.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.105 Q3, CAT 2 quiz: Beta lactamase inhibitors') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-cell-wall-synthesis-inhibitors-s-84075e5d3f', 'pharm-other-cell-wall-synthesis-inhibitors-streptogramins-oxazolidinon', 'mcq', 'Which of the following statements about vancomycin is accurate?', '["It is bacteriostatic", "It binds to penicillin-binding proteins (PBPs)", "It is not susceptible to penicillinase", "It has the advantage of oral bioavailability", "Staphylococcal enterocolitis occurs commonly with its use"]'::jsonb, 'It is not susceptible to penicillinase', '[]'::jsonb, 'Vancomycin is a glycopeptide, not a beta-lactam, so beta-lactamases cannot attack it. It binds the D-Ala-D-Ala end of peptidoglycan precursors rather than PBPs, is bactericidal, and is not absorbed orally; oral vancomycin actually treats staphylococcal and C. difficile enterocolitis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.105 Q1, CAT 2 quiz: Vancomycin') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-cell-wall-synthesis-inhibitors-s-0d933e75e3', 'pharm-other-cell-wall-synthesis-inhibitors-streptogramins-oxazolidinon', 'mcq', '''Red man syndrome'' has been associated with rapid intravenous injection of which antibiotic?', '["Vancomycin", "Clindamycin", "Cefoperazone", "Piperacillin", "Levofloxacin"]'::jsonb, 'Vancomycin', '[]'::jsonb, 'Rapid infusion of vancomycin causes direct, non-immunological release of histamine from mast cells, with flushing of the face and upper trunk and hypotension. It is prevented by infusing slowly over at least an hour. Antihistamine premedication also helps; it is not true allergy.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.105 Q2, CAT 2 quiz: Vancomycin') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-cell-wall-synthesis-inhibitors-s-4b7228434d', 'pharm-other-cell-wall-synthesis-inhibitors-streptogramins-oxazolidinon', 'mcq', 'Which is correct about vancomycin?', '["It inhibits cell wall synthesis", "It is primarily effective against gram-negative organisms", "It is usually administered orally", "It can cause Fanconi syndrome", "It can cause grey baby syndrome"]'::jsonb, 'It inhibits cell wall synthesis', '[]'::jsonb, 'Vancomycin blocks transglycosylation by binding D-Ala-D-Ala, inhibiting peptidoglycan synthesis in gram-positive bacteria. It is too large to cross the gram-negative outer membrane and is given intravenously for systemic infection. Nephrotoxicity and ototoxicity are its recognised toxicities, so trough levels are monitored; Fanconi and grey baby syndromes belong to other drugs.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.105 Q3, CAT 2 quiz: Vancomycin') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-cell-wall-synthesis-inhibitors-s-4c13d62dfe', 'pharm-other-cell-wall-synthesis-inhibitors-streptogramins-oxazolidinon', 'mcq', 'The following statements are true EXCEPT:', '["Bacitracin is a peptide antibiotic", "Bacitracin is broad spectrum in bacterial coverage", "Teicoplanin can be given intramuscularly as well as intravenously", "Resistance to fosfomycin can be due to inadequate transport by the glucose-6-phosphate transport system", "Cycloserine acts by inhibition of alanine racemase and D-alanine-D-alanine ligase"]'::jsonb, 'Bacitracin is broad spectrum in bacterial coverage', '[]'::jsonb, 'Bacitracin is a polypeptide that blocks dephosphorylation of the lipid carrier of peptidoglycan subunits; it is active only against gram-positive organisms and is used topically because it is nephrotoxic. Fosfomycin enters bacteria via glycerophosphate and glucose-6-phosphate transporters.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.106 Q1, CAT 2 quiz: Bacitracin. Original option c (''Teicoplanin is only given intravenously'') was also false; rewritten as a true statement so only one option is wrong. Human check advised.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-cell-wall-synthesis-inhibitors-s-df0ce56343', 'pharm-other-cell-wall-synthesis-inhibitors-streptogramins-oxazolidinon', 'mcq', 'Which antimicrobial has no activity against gram-positive organisms?', '["Neomycin", "Mupirocin", "Polymyxin B", "Bacitracin", "Ozenoxacin"]'::jsonb, 'Polymyxin B', '[]'::jsonb, 'Polymyxins are cationic detergents that bind lipopolysaccharide in the outer membrane of gram-negative bacteria; gram-positive organisms lack this target. Mupirocin, bacitracin and ozenoxacin are mainly anti-gram-positive topical agents. Neomycin, an aminoglycoside, has some activity against staphylococci, so it is not the answer; polymyxin''s main toxicities are renal and neurological.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.106 Q1, CAT 2 quiz: Polymixin') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-other-cell-wall-synthesis-inhibitors-s-2856db1086', 'pharm-other-cell-wall-synthesis-inhibitors-streptogramins-oxazolidinon', 'mcq', 'All of the following inhibit cell wall synthesis EXCEPT:', '["Bacitracin", "Cycloserine", "Cefepime", "Vancomycin", "Polymyxin"]'::jsonb, 'Polymyxin', '[]'::jsonb, 'Polymyxins disrupt the bacterial outer and cytoplasmic membranes, causing leakage of cell contents. Bacitracin, cycloserine, cefepime and vancomycin each block a different step of peptidoglycan synthesis. Colistin (polymyxin E) is reserved for multidrug-resistant gram-negative infections because of nephrotoxicity and neurotoxicity.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.107 Q2, CAT 2 quiz: Polymixin') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-macrolides-bf853d1fcb', 'pharm-macrolides', 'mcq', 'All of the following are true of erythromycin EXCEPT:', '["It is a natural compound", "It is effective against Mycoplasma and Chlamydia", "Resistance is usually plasmid mediated", "It is stable against gastric acid", "It is mainly excreted in bile"]'::jsonb, 'It is stable against gastric acid', '[]'::jsonb, 'Erythromycin base is destroyed by gastric acid, so it is given as enteric-coated tablets or as esters (stearate, estolate, ethylsuccinate). It is a natural product of Saccharopolyspora erythraea, concentrated in the liver and excreted in bile.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.107 Q1, CAT 2 quiz: Macrolides. Original option e (''mainly excreted renally'') was also false; changed to the true statement so only one option is wrong.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-macrolides-e724c3922d', 'pharm-macrolides', 'mcq', 'Clarithromycin and erythromycin have very similar spectra of antimicrobial activity. The major advantage of clarithromycin is that it:', '["Eradicates mycoplasmal infections in a single dose", "Is active against strains of streptococci that are resistant to erythromycin", "Is more active against Mycobacterium avium complex", "Does not inhibit liver drug-metabolising enzymes", "Acts on methicillin-resistant strains of staphylococci"]'::jsonb, 'Is more active against Mycobacterium avium complex', '[]'::jsonb, 'Clarithromycin is more active against Mycobacterium avium complex (and H. pylori), is acid-stable and has a longer half-life. It still inhibits CYP3A4, and bacteria resistant to erythromycin are cross-resistant to it. Its long tissue half-life does not allow single-dose cure; that is azithromycin''s feature.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.107 Q2, CAT 2 quiz: Macrolides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-macrolides-c888cb1afd', 'pharm-macrolides', 'mcq', 'All of the following are true of clindamycin EXCEPT:', '["It crosses the blood-brain barrier", "It is used in the treatment of Pneumocystis jirovecii pneumonia", "It is used in the treatment of malaria", "It is applied topically for the treatment of inflammatory acne", "Resistance may be due to enzymatic inactivation"]'::jsonb, 'It crosses the blood-brain barrier', '[]'::jsonb, 'Clindamycin penetrates most tissues, including bone and abscesses, but reaches the CSF poorly even when the meninges are inflamed. It is used with primaquine for Pneumocystis pneumonia and with quinine or artesunate for malaria. Topical clindamycin is widely used for acne.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.108 Q1, CAT 2 quiz: Clindamycin. No dedicated topic for this drug class in the topic list; closest topic used.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anti-microbials-classi-9220caa0b1', 'pharm-introduction-to-anti-microbials-classification-and-resistance', 'mcq', 'Which statement about chloramphenicol is FALSE?', '["It may cause aplastic anaemia", "It causes grey baby syndrome in neonates", "It is effective against rickettsiae", "It is an enzyme inducer", "It inhibits bacterial protein synthesis"]'::jsonb, 'It is an enzyme inducer', '[]'::jsonb, 'Chloramphenicol inhibits hepatic cytochrome P450 enzymes, raising levels of phenytoin, warfarin and sulfonylureas; it does not induce them. The other statements are true: it blocks peptidyl transferase on the 50S subunit and is toxic to bone marrow.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.108 Q1, CAT 2 quiz: Chloramphenicol. No dedicated topic for this drug class in the topic list; closest topic used.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anti-microbials-classi-7da32f6f54', 'pharm-introduction-to-anti-microbials-classification-and-resistance', 'mcq', 'Which antibiotic may cause grey baby syndrome in neonates, especially premature babies?', '["Ampicillin", "Chloramphenicol", "Gentamicin", "Cephalexin", "Clindamycin"]'::jsonb, 'Chloramphenicol', '[]'::jsonb, 'Neonates have low glucuronyl transferase activity and immature renal excretion, so chloramphenicol accumulates, causing vomiting, abdominal distension, grey cyanosis, hypothermia and circulatory collapse. Doses must therefore be reduced and levels monitored if it has to be used in newborns; gentamicin and ampicillin are the usual neonatal choices.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.109 Q3, CAT 2 quiz: Chloramphenicol. No dedicated topic for this drug class in the topic list; closest topic used.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anti-microbials-classi-b557dfd86c', 'pharm-introduction-to-anti-microbials-classification-and-resistance', 'mcq', 'Which of the following antibiotics inhibits hepatic microsomal cytochrome P450 enzymes?', '["Rifampicin", "Ampicillin", "Cephalexin", "Chloramphenicol", "Tetracycline"]'::jsonb, 'Chloramphenicol', '[]'::jsonb, 'Chloramphenicol is an enzyme inhibitor and prolongs the action of drugs such as phenytoin and warfarin. Rifampicin does the reverse: it is a powerful inducer of cytochrome P450. Erythromycin, ciprofloxacin, isoniazid and the azoles are other antimicrobial enzyme inhibitors worth remembering.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.109 Q5, CAT 2 quiz: Chloramphenicol. No dedicated topic for this drug class in the topic list; closest topic used.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anti-microbials-classi-b1488ad300', 'pharm-introduction-to-anti-microbials-classification-and-resistance', 'mcq', 'Which statement regarding tetracyclines is TRUE?', '["Acidic pH impairs absorption", "Doxycycline is excreted mainly unchanged in the urine", "Minocycline exhibits a pharmacokinetic drug interaction with aluminium antacids", "They do not cross the placenta", "They reduce urinary excretion of the B vitamins"]'::jsonb, 'Minocycline exhibits a pharmacokinetic drug interaction with aluminium antacids', '[]'::jsonb, 'Tetracyclines chelate divalent and trivalent cations, so aluminium, calcium and magnesium antacids, iron and milk reduce their absorption; this applies to minocycline too. Absorption is impaired by alkaline, not acidic, pH, and they cross the placenta and deposit in fetal teeth and bone.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.109 Q1, CAT 2 quiz: Tetracyclines. Original option b (''Presence of food reduces absorption of doxycycline'') is partly true, so it was replaced with a clearly false statement. No dedicated topic for this drug class in the topic list; closest topic used.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anti-microbials-classi-82596444d7', 'pharm-introduction-to-anti-microbials-classification-and-resistance', 'mcq', 'Fanconi syndrome may be caused by taking which of the following antibiotics after their expiry date?', '["Penicillin V", "Erythromycin", "Tetracycline", "Chloramphenicol", "Clindamycin"]'::jsonb, 'Tetracycline', '[]'::jsonb, 'Outdated tetracycline degrades to epitetracycline and anhydrotetracycline products that damage the proximal renal tubule, causing a Fanconi-type syndrome with loss of glucose, amino acids, phosphate and bicarbonate in urine. Expired tetracycline should therefore be discarded; it is the classic example of a drug becoming toxic on storage.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.110 Q4, CAT 2 quiz: Tetracyclines. No dedicated topic for this drug class in the topic list; closest topic used.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anti-microbials-classi-434cf1e24c', 'pharm-introduction-to-anti-microbials-classification-and-resistance', 'mcq', 'Which is a long-acting tetracycline?', '["Methacycline", "Doxycycline", "Tetracycline", "Oxytetracycline", "Demeclocycline"]'::jsonb, 'Doxycycline', '[]'::jsonb, 'Doxycycline and minocycline are the long-acting tetracyclines (half-life 16 to 18 hours), allowing once- or twice-daily dosing. Tetracycline and oxytetracycline are short acting; demeclocycline and methacycline are intermediate. They are also more lipid soluble and better absorbed, even with food.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.110 Q5, CAT 2 quiz: Tetracyclines. No dedicated topic for this drug class in the topic list; closest topic used.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aminoglycosides-199007f981', 'pharm-aminoglycosides', 'mcq', 'The following are adverse effects of aminoglycosides EXCEPT:', '["Nephrotoxicity", "Skin rash", "Ototoxicity", "Muscle paralysis", "Hepatotoxicity"]'::jsonb, 'Hepatotoxicity', '[]'::jsonb, 'Aminoglycosides are not metabolised by the liver and are not hepatotoxic. Their characteristic toxicities are renal tubular damage, cochlear and vestibular damage and neuromuscular blockade; allergic rashes occur occasionally. Toxicity is related to trough concentrations and duration, which is why levels are monitored.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.110 Q1, CAT 2 quiz: Aminoglycosides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aminoglycosides-0daff69bad', 'pharm-aminoglycosides', 'mcq', 'All of the following are true of aminoglycosides EXCEPT:', '["Amikacin is a semisynthetic derivative of kanamycin", "Gentamicin is a semisynthetic derivative of sisomicin", "Streptomycin is a reserve drug for TB", "Neomycin is limited to topical and oral (gut) use", "They have a concentration-dependent killing effect"]'::jsonb, 'Gentamicin is a semisynthetic derivative of sisomicin', '[]'::jsonb, 'Gentamicin is a natural product of Micromonospora purpurea; the semisynthetic derivative of sisomicin is netilmicin. Amikacin is derived from kanamycin and resists many inactivating enzymes. Neomycin is too toxic for parenteral use. Streptomycin is now a second-line antituberculous drug because of toxicity and injection.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.110 Q2, CAT 2 quiz: Aminoglycosides. Option d clarified to ''topical and oral (gut) use''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aminoglycosides-0bf1106b69', 'pharm-aminoglycosides', 'mcq', 'Which is true of the antibacterial activity of aminoglycosides?', '["They are most effective in the treatment of gram-positive organisms", "They are active against anaerobes", "They are effective against gram-negative cocci as first-line agents", "They have no post-antibiotic effect", "They are bactericidal"]'::jsonb, 'They are bactericidal', '[]'::jsonb, 'Aminoglycosides cause misreading of mRNA at the 30S subunit and are rapidly bactericidal, mainly against aerobic gram-negative bacilli, with a long post-antibiotic effect. Their uptake needs oxygen-dependent transport, so anaerobes are resistant. They are combined with penicillins for synergy against enterococci and streptococci.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.111 Q3, CAT 2 quiz: Aminoglycosides. Options b and c in the paper (''active against gram-positive cocci'', ''effective against gram-negative cocci'') were partly defensible, so both were reworded to be clearly false. Human check advised.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aminoglycosides-f199f2810d', 'pharm-aminoglycosides', 'mcq', 'Which of the following antibiotics is used orally to reduce ammonia-producing organisms in patients with hepatic encephalopathy?', '["Penicillin G", "Tetracycline", "Neomycin", "Chloramphenicol", "Cefotaxime"]'::jsonb, 'Neomycin', '[]'::jsonb, 'Oral neomycin is not absorbed and stays in the gut lumen, where it suppresses urease-producing bacteria and so reduces ammonia formation. Rifaximin and lactulose are now generally preferred. Enough may be absorbed in renal failure to cause ototoxicity with prolonged use.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.111 Q8, CAT 2 quiz: Aminoglycosides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-quinolones-6bdaadc18e', 'pharm-quinolones', 'mcq', 'Which fluoroquinolone should not be used for the treatment of pneumonia?', '["Levofloxacin", "Norfloxacin", "Gatifloxacin", "Gemifloxacin", "Moxifloxacin"]'::jsonb, 'Norfloxacin', '[]'::jsonb, 'Norfloxacin achieves low serum and tissue concentrations and has weak gram-positive activity, so it is confined to urinary and gut infections. Levofloxacin, moxifloxacin, gemifloxacin and gatifloxacin are the ''respiratory'' quinolones. Ciprofloxacin is also a poor choice for pneumococcal pneumonia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.112 Q1, CAT 2 quiz: Quinolones and fluoroquinolones') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-quinolones-82bd96748e', 'pharm-quinolones', 'mcq', 'Which is NOT a second-generation quinolone?', '["Norfloxacin", "Ciprofloxacin", "Enoxacin", "Ofloxacin", "Sparfloxacin"]'::jsonb, 'Sparfloxacin', '[]'::jsonb, 'Sparfloxacin is a third-generation quinolone with improved gram-positive and atypical activity (withdrawn in many countries for QT prolongation and phototoxicity). Norfloxacin, ciprofloxacin, enoxacin and ofloxacin are second generation. Generations reflect spectrum: first (nalidixic acid) urinary only, second mainly gram-negative, third and fourth adding gram-positive and anaerobic cover.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.113 Q2, CAT 2 quiz: Quinolones and fluoroquinolones') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-quinolones-390a7583a7', 'pharm-quinolones', 'mcq', 'In which of the following does the concentration of quinolones NOT exceed that in serum?', '["Prostatic fluid", "Bile", "Lung", "Kidneys", "CSF"]'::jsonb, 'CSF', '[]'::jsonb, 'Fluoroquinolones have a large volume of distribution and concentrate in prostate, lung, bile, kidney and phagocytes, but CSF concentrations are lower than in serum. This tissue penetration underlies their use in prostatitis and respiratory infection.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.113 Q3, CAT 2 quiz: Quinolones and fluoroquinolones') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sulfonamides-and-related-compounds-06d78067b1', 'pharm-sulfonamides-and-related-compounds', 'mcq', 'Which is NOT an adverse effect of sulfonamides?', '["Anaemia", "Crystalluria", "Granulocytopenia", "Skin rash", "Hypertension"]'::jsonb, 'Hypertension', '[]'::jsonb, 'Sulfonamides cause hypersensitivity rashes (including Stevens-Johnson syndrome), crystalluria, haemolytic anaemia in G6PD deficiency, and marrow depression with granulocytopenia. They have no effect on blood pressure. Kernicterus in the newborn and photosensitivity are other recognised problems; a high fluid intake prevents crystal formation in the urine.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.114 Q1, CAT 2 quiz: Sulfonamides and trimethoprim') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sulfonamides-and-related-compounds-bd2f9722ee', 'pharm-sulfonamides-and-related-compounds', 'mcq', 'Kernicterus in neonates, especially premature infants, treated with sulfonamides is due to:', '["Enhanced synthesis of bilirubin", "Inhibition of bilirubin degradation", "Inhibition of urinary excretion of bilirubin", "Displacement of bound bilirubin from albumin", "Impaired bilirubin excretion into the hepatic canaliculi"]'::jsonb, 'Displacement of bound bilirubin from albumin', '[]'::jsonb, 'Sulfonamides compete with bilirubin for binding sites on plasma albumin. The freed unconjugated bilirubin crosses the immature blood-brain barrier and deposits in the basal ganglia, so sulfonamides are avoided near term and in neonates. They do not alter bilirubin synthesis or excretion.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.114 Q3, CAT 2 quiz: Sulfonamides and trimethoprim') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sulfonamides-and-related-compounds-34888ee65e', 'pharm-sulfonamides-and-related-compounds', 'mcq', 'Which is NOT a clinical indication of co-trimoxazole?', '["Treatment of shigellosis", "Topical application on burn wounds to prevent microbial colonisation", "Treatment of recurrent urinary tract infection", "Prophylaxis against Pneumocystis jirovecii", "Treatment of respiratory tract infection caused by H. influenzae"]'::jsonb, 'Topical application on burn wounds to prevent microbial colonisation', '[]'::jsonb, 'The sulfonamides applied to burns are silver sulfadiazine and mafenide; co-trimoxazole is a systemic (oral or intravenous) combination. Its indications include urinary, respiratory and enteric infections and Pneumocystis prophylaxis. Resistance among Shigella and urinary pathogens is now common, so local sensitivities matter.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.114 Q6, CAT 2 quiz: Sulfonamides and trimethoprim') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-31c63c4cc5', 'pharm-anti-tb-drugs', 'mcq', 'Which of the following antituberculosis drugs inhibits mycobacterial ATP synthase?', '["Cycloserine", "Pyrazinamide", "Ethionamide", "Bedaquiline", "Clofazimine"]'::jsonb, 'Bedaquiline', '[]'::jsonb, 'Bedaquiline, a diarylquinoline, binds subunit c of mycobacterial ATP synthase and starves the bacillus of energy; it is used for multidrug-resistant TB and prolongs the QT interval. Cycloserine blocks D-alanine incorporation into the cell wall and ethionamide inhibits mycolic acid synthesis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.115 Q1, CAT 2 quiz: Anti TB drugs. Stem corrected from ''adenosine synthase'' to ATP synthase (adenosine triphosphate synthase).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-ff0bae22c1', 'pharm-anti-tb-drugs', 'mcq', 'Which of the following is true of rifampicin?', '["It is only indicated for tuberculosis therapy", "It is bacteriostatic", "It has a small volume of distribution", "It penetrates the central nervous system compartment", "It is poorly bound to plasma protein"]'::jsonb, 'It penetrates the central nervous system compartment', '[]'::jsonb, 'Rifampicin is lipid soluble and widely distributed, reaching therapeutic concentrations in CSF (particularly with inflamed meninges), abscesses and inside macrophages. It is bactericidal, highly protein bound, and also used for leprosy, meningococcal prophylaxis and staphylococcal infections.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.115 Q3, CAT 2 quiz: Anti TB drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-0bb3aaa3e7', 'pharm-anti-tb-drugs', 'mcq', 'Which statement regarding isoniazid is INCORRECT?', '["Its action on atypical mycobacteria is as effective as on Mycobacterium tuberculosis", "Combination with rifampicin confers high cure rates for susceptible mycobacteria in 9 months", "It is structurally similar to pyridoxine", "Cross-resistance to ethionamide occurs", "It penetrates the central nervous system"]'::jsonb, 'Its action on atypical mycobacteria is as effective as on Mycobacterium tuberculosis', '[]'::jsonb, 'Isoniazid is highly selective for Mycobacterium tuberculosis; most atypical (non-tuberculous) mycobacteria are resistant. Mutations in inhA give cross-resistance with ethionamide, and the drug diffuses freely into CSF and caseous tissue. Mycobacterium kansasii is the main atypical species that may respond to isoniazid.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.115 Q4, CAT 2 quiz: Anti TB drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-524af387d6', 'pharm-anti-tb-drugs', 'mcq', 'A 37-year-old man on anti-TB therapy presents with acute gouty arthritis. This is most likely associated with which of his medications?', '["Streptomycin", "Pyrazinamide", "Isoniazid", "Cycloserine", "Rifampicin"]'::jsonb, 'Pyrazinamide', '[]'::jsonb, 'Pyrazinoic acid, the metabolite of pyrazinamide, inhibits renal tubular secretion of uric acid, causing hyperuricaemia in most patients and occasionally acute gout. Ethambutol can also raise urate, though less often. Aspirin and other NSAIDs relieve the arthralgia; the drug is stopped only if gout is severe.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.115 Q5, CAT 2 quiz: Anti TB drugs. Paper had 4 options: added a fifth option (Rifampicin). Replaced option ''Ethambutol'' with ''Streptomycin'' because ethambutol also causes hyperuricaemia.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-d01ea4b3f0', 'pharm-anti-tb-drugs', 'mcq', 'Which antituberculous drug characteristically causes optic neuritis?', '["Ethambutol", "Rifampicin", "Pyrazinamide", "Cycloserine", "Streptomycin"]'::jsonb, 'Ethambutol', '[]'::jsonb, 'Ethambutol causes a dose-related retrobulbar neuritis with reduced visual acuity and red-green colour blindness, so vision is checked before and during treatment and the drug is used cautiously in young children. The effect is usually reversible if the drug is stopped early; the dose is reduced in renal impairment.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.116 Q10, CAT 2 quiz: Anti TB drugs. Duplicate of Q20 on p.118 (kept this one). Replaced option ''Isoniazid'' (rarely causes optic neuritis) with ''Cycloserine''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-1941daf33c', 'pharm-anti-tb-drugs', 'mcq', 'Which statement is FALSE regarding TB agents?', '["Both ethambutol and isoniazid can cause optic neuritis", "Patients on isoniazid excrete red-coloured urine", "Isoniazid monotherapy is used for prophylaxis against tuberculosis", "Rifampicin has bactericidal activity", "Rifampicin inhibits DNA-dependent RNA polymerase"]'::jsonb, 'Patients on isoniazid excrete red-coloured urine', '[]'::jsonb, 'It is rifampicin, not isoniazid, that colours urine, tears, sweat and saliva orange-red. Isoniazid alone for 6 to 9 months is standard treatment of latent infection, and it can rarely cause optic neuritis. Patients should be warned so the harmless discoloration is not mistaken for blood.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.117 Q12, CAT 2 quiz: Anti TB drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-98117841c8', 'pharm-anti-tb-drugs', 'mcq', 'The following adverse effects are correctly paired with the causative antituberculous drug EXCEPT:', '["Peripheral neuropathy: isoniazid", "Ototoxicity: rifampicin", "Optic neuritis: ethambutol", "Hyperuricaemia: pyrazinamide", "Vestibular dysfunction: streptomycin"]'::jsonb, 'Ototoxicity: rifampicin', '[]'::jsonb, 'Ototoxicity belongs to streptomycin and the other injectable agents. Rifampicin causes hepatitis, orange body fluids, flu-like syndrome and enzyme induction, but does not damage the ear. Streptomycin mainly damages vestibular function, and all of these pairings are favourite examination material for the first-line drugs.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.117 Q13, CAT 2 quiz: Anti TB drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-f7e2f06800', 'pharm-anti-tb-drugs', 'mcq', 'First-line drugs for treatment of tuberculosis include all of the following EXCEPT:', '["Isoniazid", "Rifampicin", "Ethionamide", "Ethambutol", "Pyrazinamide"]'::jsonb, 'Ethionamide', '[]'::jsonb, 'Ethionamide is a second-line drug kept for resistant disease because of poor tolerability (severe gastric upset, hepatotoxicity, neurotoxicity). The first-line regimen is rifampicin, isoniazid, pyrazinamide and ethambutol. Streptomycin was formerly counted as first line for retreatment and is the only injectable among the older standard drugs.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.117 Q15, CAT 2 quiz: Anti TB drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-tb-drugs-c51f1bf1a8', 'pharm-anti-tb-drugs', 'mcq', 'Toxic effects of isoniazid involving the peripheral and central nervous system can be prevented by administration of:', '["Folic acid", "Thiamine", "Pyridoxine", "Cyanocobalamin", "Phytomenadione"]'::jsonb, 'Pyridoxine', '[]'::jsonb, 'Isoniazid interferes with pyridoxal phosphate, which is needed for neurotransmitter synthesis including GABA. Pyridoxine (vitamin B6) 10 to 25 mg daily prevents neuropathy, and large doses treat the seizures of isoniazid overdose. Folic acid, thiamine and vitamin B12 do not correct this drug-induced deficiency.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.117 Q16, CAT 2 quiz: Anti TB drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-leprosy-drugs-2230568aaf', 'pharm-anti-leprosy-drugs', 'mcq', 'The following drugs can be used in the treatment of leprosy EXCEPT:', '["Clofazimine", "Rifampicin", "Ethionamide", "Moxifloxacin", "Isoniazid"]'::jsonb, 'Isoniazid', '[]'::jsonb, 'Isoniazid has no activity against Mycobacterium leprae. Standard therapy is dapsone, rifampicin and clofazimine; ethionamide, fluoroquinolones, minocycline and clarithromycin are alternatives. The examiner expects candidates to remember that isoniazid''s spectrum is essentially restricted to Mycobacterium tuberculosis and a few closely related species.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.119 Q1, CAT 2 quiz: Anti leprosy') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-leprosy-drugs-b46babba6d', 'pharm-anti-leprosy-drugs', 'mcq', 'All of the following are true about dapsone in the treatment of leprosy EXCEPT:', '["It inhibits dihydropteroate synthase", "It is well absorbed orally", "It can cause photosensitivity skin reactions", "It is safe to use in patients with severe anaemia", "It is a drug of choice"]'::jsonb, 'It is safe to use in patients with severe anaemia', '[]'::jsonb, 'Dapsone causes dose-related haemolysis (severe in G6PD deficiency) and methaemoglobinaemia, so it is contraindicated in severe anaemia. Like sulfonamides it inhibits dihydropteroate synthase in the folate pathway. A full blood count and, ideally, a G6PD screen are done before starting, and treatment is combined with rifampicin and clofazimine.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.119 Q2, CAT 2 quiz: Anti leprosy. Original option b (''poor CSF penetration'') was uncertain, so it was replaced with a clearly true statement. Human check advised.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-leprosy-drugs-f4c3f0bc61', 'pharm-anti-leprosy-drugs', 'mcq', 'Which statement about anti-leprosy drugs is TRUE?', '["Dapsone acts by inhibiting dihydrofolate reductase", "The half-life of dapsone is 10-12 hours", "Rifampicin can be used alone in the treatment of leprosy as an alternative to dapsone", "Dapsone does not reach the skin", "Clofazimine has a half-life of about 2 months"]'::jsonb, 'Clofazimine has a half-life of about 2 months', '[]'::jsonb, 'Clofazimine is a lipophilic dye stored in fat and macrophages and released very slowly, giving a half-life of about 70 days. Dapsone inhibits dihydropteroate synthase with a half-life of 1 to 2 days, and leprosy is never treated with one drug.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.119 Q3, CAT 2 quiz: Anti leprosy. Original option d (''skin concentration of dapsone is similar to that of plasma'') was ambiguous and was replaced with a clearly false statement.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-d751fc0767', 'pharm-anti-fungals', 'mcq', 'The following topical antifungal agents are useful in the treatment of dermatophyte infections EXCEPT:', '["Ketoconazole", "Ciclopirox olamine", "Terbinafine", "Tolnaftate", "Nystatin"]'::jsonb, 'Nystatin', '[]'::jsonb, 'Nystatin is a polyene active against Candida but not against dermatophytes (Trichophyton, Microsporum, Epidermophyton). Azoles, terbinafine, tolnaftate and ciclopirox all treat tinea. The reverse holds for griseofulvin and tolnaftate, which treat dermatophytes but not Candida; azoles and ciclopirox cover both groups.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.119 Q1, CAT 2 quiz: Antifungals') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-04b95c70d4', 'pharm-anti-fungals', 'mcq', 'Which of the following antifungal drugs is NOT appropriately matched with its class?', '["Polyene antifungal: nystatin", "Triazole: ketoconazole", "Echinocandin: anidulafungin", "Allylamine: terbinafine", "Antimetabolite: flucytosine"]'::jsonb, 'Triazole: ketoconazole', '[]'::jsonb, 'Ketoconazole is an imidazole (two nitrogens in the azole ring), like clotrimazole and miconazole. The triazoles (three nitrogens) are fluconazole, itraconazole, voriconazole and posaconazole, and are more selective for fungal CYP450. Ketoconazole inhibits human steroid synthesis and CYP3A4 strongly.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.120 Q5, CAT 2 quiz: Antifungals') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-196f6063ee', 'pharm-anti-fungals', 'mcq', 'All of the following are true of flucytosine EXCEPT:', '["It has a wide therapeutic window", "It is given orally", "It requires dosage adjustment in renal impairment", "It is a prodrug", "It is effective for the treatment of cryptococcal meningitis"]'::jsonb, 'It has a wide therapeutic window', '[]'::jsonb, 'Flucytosine has a narrow therapeutic window: high levels cause bone marrow suppression and hepatotoxicity, so levels are monitored and the dose reduced in renal impairment. It is converted in fungi to 5-fluorouracil and is combined with amphotericin B for cryptococcal meningitis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.120 Q6, CAT 2 quiz: Antifungals. Option b softened from ''only administered orally'' (an IV form exists in some countries).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-09d4f4ac18', 'pharm-anti-fungals', 'mcq', 'Which one of the following statements about flucytosine is accurate?', '["It is bioactivated by fungal cytosine deaminase", "It does not cross the blood-brain barrier", "It inhibits cytochrome P450", "It is useful in oesophageal candidiasis", "It has a wide spectrum of antifungal activity"]'::jsonb, 'It is bioactivated by fungal cytosine deaminase', '[]'::jsonb, 'Fungal cytosine deaminase converts flucytosine to 5-fluorouracil, which inhibits thymidylate synthase and RNA function; human cells lack the enzyme, giving selectivity. It enters CSF well and has a narrow spectrum (Cryptococcus, some Candida). Resistance develops quickly, so it is never used alone.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.120 Q7, CAT 2 quiz: Antifungals') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-e4ab89189b', 'pharm-anti-fungals', 'mcq', 'All of the following are true of nystatin EXCEPT:', '["It is a topical antifungal", "It treats dermatophyte infections after 2-3 weeks of application", "It is used for treatment of oral Candida albicans infection", "Oral administration may cause GIT adverse effects", "Topical application is usually non-irritating"]'::jsonb, 'It treats dermatophyte infections after 2-3 weeks of application', '[]'::jsonb, 'Nystatin binds ergosterol and is effective only against Candida and other yeasts; it has no useful activity against dermatophytes however long it is applied. It is not absorbed, so adverse effects are limited to mild gut upset.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.121 Q8, CAT 2 quiz: Antifungals') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-b02f08ee66', 'pharm-anti-fungals', 'mcq', 'Among the following, the drug of choice for tinea corporis infection is:', '["Griseofulvin", "Nystatin", "Amphotericin", "Neomycin", "Fluconazole"]'::jsonb, 'Griseofulvin', '[]'::jsonb, 'Griseofulvin is active only against dermatophytes: it is deposited in new keratin and disrupts fungal microtubules. Nystatin does not cover dermatophytes, and amphotericin is reserved for systemic mycoses. Neomycin is an antibacterial; griseofulvin needs weeks of treatment and induces liver enzymes.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.121 Q9, CAT 2 quiz: Antifungals. Guideline-dependent: localised tinea corporis is normally treated with a topical azole or terbinafine (not offered); griseofulvin is the paper''s likely intended answer, but oral fluconazole is also used. Human check needed.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-1e242e2f2f', 'pharm-anti-fungals', 'mcq', 'Regarding the lipid formulations of amphotericin B, which one of the following statements is accurate?', '["Affinity of amphotericin B for these lipids is greater than its affinity for ergosterol", "They are less expensive to use than conventional amphotericin B", "They are more effective in fungal infections because they increase tissue uptake of amphotericin B", "They may decrease the nephrotoxicity of amphotericin B", "They have a wider spectrum of antifungal activity than conventional formulations"]'::jsonb, 'They may decrease the nephrotoxicity of amphotericin B', '[]'::jsonb, 'Packaging amphotericin in liposomes or lipid complexes reduces its binding to human cell membranes, especially in the kidney, so larger doses can be given with less nephrotoxicity. They are far more expensive and are not more effective or broader in spectrum.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.121 Q10, CAT 2 quiz: Antifungals') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-8b59a546a4', 'pharm-anti-fungals', 'mcq', 'Interactions between this drug and cell membrane components result in the formation of pores lined by hydrophilic groups present in the drug molecule:', '["Itraconazole", "Flucytosine", "Amphotericin B", "Griseofulvin", "Terbinafine"]'::jsonb, 'Amphotericin B', '[]'::jsonb, 'Amphotericin B is an amphipathic polyene: its lipophilic side binds ergosterol while its hydroxyl-rich side lines a pore, through which potassium and other ions leak and the fungus dies. Itraconazole and terbinafine reduce ergosterol synthesis instead of forming pores.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.122 Q15, Antifungals') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-fungals-c4f1e0cf80', 'pharm-anti-fungals', 'mcq', 'Amphotericin B has the following properties EXCEPT:', '["It can cause renal damage", "It is poorly absorbed orally", "It is used for systemic fungal infection", "It binds to ergosterol of the fungal membrane", "It is an enzyme activator"]'::jsonb, 'It is an enzyme activator', '[]'::jsonb, 'Amphotericin B is a polyene that binds ergosterol and forms membrane pores; it is not absorbed from the gut, so it is infused intravenously for systemic mycoses, and nephrotoxicity is its main dose-limiting effect. It has no enzyme-activating or enzyme-inducing action.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.122 Q15b, Antifungals. Second question numbered 15 on the page.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-d7a7c0ac23', 'pharm-antivirals', 'mcq', 'Which drug is used for the treatment of cytomegalovirus (CMV)?', '["Acyclovir", "Penciclovir", "Ganciclovir", "Idoxuridine", "Amantadine"]'::jsonb, 'Ganciclovir', '[]'::jsonb, 'Ganciclovir is phosphorylated in CMV-infected cells by the viral kinase UL97 and then inhibits CMV DNA polymerase, making it first-line for CMV retinitis and colitis. Acyclovir depends on thymidine kinase, which CMV lacks, so it is much weaker against CMV.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.123 Q1, Antivirals') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antivirals-7a33f726b9', 'pharm-antivirals', 'mcq', 'The following are true about interferon EXCEPT:', '["Promotes formation of natural killer cells", "Well absorbed when taken orally", "Used for treatment of chronic hepatitis B (HBV) infection", "Causes severe depression", "Contraindicated in pregnancy"]'::jsonb, 'Well absorbed when taken orally', '[]'::jsonb, 'Interferons are proteins that would be digested in the gut, so they are injected subcutaneously or intramuscularly. They enhance natural killer cell activity, are used in chronic hepatitis B and C, and cause flu-like symptoms, marrow suppression and neuropsychiatric effects including severe depression.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.123 Q2, Antivirals') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-62c4e31239', 'pharm-antiretroviral-i', 'mcq', 'All the following are mitochondrial toxic effects of nucleoside reverse transcriptase inhibitors used in HIV treatment EXCEPT:', '["Peripheral neuropathy", "Lactic acidosis", "Skin rash", "Lipodystrophy", "Pancreatitis"]'::jsonb, 'Skin rash', '[]'::jsonb, 'Older nucleoside analogues inhibit mitochondrial DNA polymerase gamma, which produces peripheral neuropathy, pancreatitis, lactic acidosis with hepatic steatosis, and lipoatrophy. Skin rash is a hypersensitivity effect, typical of non-nucleoside inhibitors and abacavir, not a result of mitochondrial damage.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.123 Q3, Antivirals. Paper says ''integrase inhibitors'', which do not cause mitochondrial toxicity; reworded to nucleoside reverse transcriptase inhibitors. Human should confirm the rewording.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-ii-67165d709e', 'pharm-antiretroviral-ii', 'mcq', 'Which of the following antiretroviral drugs is a maturation inhibitor?', '["Bevirimat", "Lopinavir", "Zidovudine", "Dolutegravir", "Efavirenz"]'::jsonb, 'Bevirimat', '[]'::jsonb, 'Bevirimat binds the Gag polyprotein and blocks the final cleavage of the capsid precursor, so immature non-infectious virions are released. Lopinavir also disturbs maturation, but it does so by inhibiting the viral protease itself and is classed as a protease inhibitor.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.123 Q4, Antivirals') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-ii-8e426933c9', 'pharm-antiretroviral-ii', 'mcq', 'John is on first-line HIV therapy using a tenofovir, lamivudine and dolutegravir fixed-dose combination once daily. He is found to have tuberculosis and first-line TB therapy is initiated. Which of the following is correct?', '["His current regimen is optimal if he has no resistance mutations", "He should switch to abacavir", "He should double the dose of dolutegravir", "He should stop antiretroviral therapy for 2 months", "Atazanavir should be used in place of dolutegravir"]'::jsonb, 'He should double the dose of dolutegravir', '[]'::jsonb, 'Rifampicin induces UGT1A1 and CYP3A4, which lowers dolutegravir levels, so an extra 50 mg dose is given 12 hours after the fixed-dose tablet. Switching to atazanavir would be worse, because rifampicin reduces protease inhibitor levels far more, and stopping therapy risks disease progression.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.123 Q6, Antivirals') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-ecd7147580', 'pharm-antiretroviral-i', 'mcq', 'In a patient with end-stage renal disease, which would be your least preferred antiretroviral drug?', '["Tenofovir alafenamide", "Abacavir", "Dolutegravir", "Tenofovir disoproxil fumarate", "Efavirenz"]'::jsonb, 'Tenofovir disoproxil fumarate', '[]'::jsonb, 'Tenofovir disoproxil gives high plasma tenofovir levels, which injure the proximal tubule (Fanconi syndrome, falling GFR) and accumulate in renal failure. Tenofovir alafenamide delivers the drug into cells with about 90% lower plasma levels, so it is much kinder to the kidney; abacavir, dolutegravir and efavirenz are cleared by the liver.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.124 Q7, Antivirals') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-4cbfc6a080', 'pharm-antiretroviral-i', 'mcq', 'A hypersensitivity drug reaction in patients on treatment for HIV who express HLA-B*5701 can be associated with which of these medicines?', '["Lopinavir", "Dolutegravir", "Enfuvirtide", "Abacavir", "Stavudine"]'::jsonb, 'Abacavir', '[]'::jsonb, 'Abacavir causes a potentially fatal multisystem hypersensitivity reaction (fever, rash, gastrointestinal and respiratory symptoms) almost only in carriers of HLA-B*5701, so patients are screened before starting and never rechallenged. Stavudine''s toxicity is mitochondrial, not immune-mediated.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.124 Q10, Antivirals') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-0c5df8ed6e', 'pharm-antiretroviral-i', 'mcq', 'The following drugs are non-nucleoside reverse transcriptase inhibitors (NNRTIs) EXCEPT:', '["Etravirine", "Efavirenz", "Abacavir", "Doravirine", "Rilpivirine"]'::jsonb, 'Abacavir', '[]'::jsonb, 'Abacavir is a guanosine analogue, a nucleoside reverse transcriptase inhibitor that must be phosphorylated and then terminates the DNA chain. The other four bind directly to an allosteric site on reverse transcriptase without needing activation, which defines the non-nucleoside class.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.124 Q11, Antivirals') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-retrovirals-4c7da9c73a', 'pharm-anti-retrovirals', 'mcq', 'Which of the following is true regarding antiretroviral drugs?', '["Efavirenz is safe in patients with a history of suicidal tendencies", "Enfuvirtide is given subcutaneously", "Abacavir should be avoided in patients with chronic renal failure", "Darunavir is an integrase inhibitor", "Dolutegravir causes weight loss on long-term therapy"]'::jsonb, 'Enfuvirtide is given subcutaneously', '[]'::jsonb, 'Enfuvirtide is a 36-amino-acid peptide fusion inhibitor, so it must be injected subcutaneously twice daily. Abacavir is metabolised in the liver and needs no renal adjustment, efavirenz causes neuropsychiatric effects, darunavir is a protease inhibitor and dolutegravir is linked to weight gain.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.125 Q13, Antivirals') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anti-retrovirals-6f37755470', 'pharm-anti-retrovirals', 'mcq', 'Which antiretroviral drug is not effective in the treatment of hepatitis B virus/HIV co-infection as an agent active against hepatitis B?', '["Tenofovir alafenamide", "Emtricitabine", "Tenofovir disoproxil fumarate", "Lamivudine", "Dolutegravir"]'::jsonb, 'Dolutegravir', '[]'::jsonb, 'Hepatitis B virus has a polymerase with reverse transcriptase activity, which tenofovir, lamivudine and emtricitabine inhibit. Dolutegravir blocks HIV integrase, an enzyme hepatitis B does not use, so it adds nothing against that virus even though it is part of the regimen.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.125 Q14, Antivirals. Stem slightly clarified (''as an agent active against hepatitis B'').') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-a92eda4e3e', 'pharm-antiretroviral-i', 'mcq', 'Which of the following is an antiretroviral agent used in the treatment of HIV infection?', '["Acyclovir", "Rifampicin", "Zidovudine (AZT)", "Vidarabine", "Amantadine"]'::jsonb, 'Zidovudine (AZT)', '[]'::jsonb, 'Zidovudine is a thymidine analogue that inhibits HIV reverse transcriptase and was the first antiretroviral. Acyclovir and vidarabine act on herpesviruses, amantadine on influenza A, and rifampicin is antibacterial; none of them suppresses HIV replication.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.125 Q17, Antivirals. Paper asks for ''the agent of choice in HIV'' (outdated: zidovudine alone is no longer the treatment of choice); reworded.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-acf3ae725b', 'pharm-antiretroviral-i', 'mcq', 'Peripheral neuropathy is most commonly associated with:', '["Stavudine", "Indinavir", "Nevirapine", "Abacavir", "Dolutegravir"]'::jsonb, 'Stavudine', '[]'::jsonb, 'Stavudine, like didanosine and zalcitabine, strongly inhibits mitochondrial DNA polymerase gamma, giving a painful dose-related sensory neuropathy as well as lipoatrophy and lactic acidosis. Abacavir is a nucleoside analogue too, but it has little mitochondrial toxicity; its problem is hypersensitivity.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.126 Q19, Antivirals') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiretroviral-i-4c4ad0d136', 'pharm-antiretroviral-i', 'mcq', 'The following are true of zidovudine EXCEPT:', '["Causes anaemia", "Inhibits reverse transcriptase", "Resistance is due to thymidine analogue mutations (TAMs)", "Has a synergistic effect with stavudine", "Active against both HIV-1 and HIV-2"]'::jsonb, 'Has a synergistic effect with stavudine', '[]'::jsonb, 'Zidovudine and stavudine are both thymidine analogues that compete for the same thymidine kinase, so they antagonise each other and are never combined. Zidovudine does cause marrow suppression with macrocytic anaemia and, unlike the non-nucleoside inhibitors, is active against HIV-2 as well as HIV-1.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.126 Q22, Antivirals') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-73bb8c0c16', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which of the following drugs is not correctly matched with its clinical indication?', '["Babesia : Clindamycin", "Balantidium coli : Tetracycline", "Cryptosporidium : Metronidazole", "Giardia lamblia : Tinidazole", "Toxoplasma gondii : Pyrimethamine plus clindamycin"]'::jsonb, 'Cryptosporidium : Metronidazole', '[]'::jsonb, 'Cryptosporidium does not respond to metronidazole; nitazoxanide is the drug used, together with immune restoration in HIV. The other pairings are standard: clindamycin with quinine for babesiosis, tetracycline for balantidiasis, tinidazole for giardiasis, and pyrimethamine with clindamycin for toxoplasmosis in sulfonamide-allergic patients.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.126 Q1, Anti amoebic and other antiprotozoals') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-d282950a26', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Identify the antiprotozoal drug that is effective in the treatment of trypanosomiasis with central nervous system involvement:', '["Sodium stibogluconate", "Metronidazole", "Suramin", "Pentamidine", "Melarsoprol"]'::jsonb, 'Melarsoprol', '[]'::jsonb, 'Melarsoprol is a trivalent arsenical that crosses the blood-brain barrier, so it treats late-stage sleeping sickness, especially the East African form. Suramin and pentamidine are highly charged and do not enter the cerebrospinal fluid, so they work only in the early haemolymphatic stage.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.127 Q2, Anti amoebic and other antiprotozoals') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-8753a38057', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which of the following drugs is used for the treatment of amoebiasis?', '["Nitrofurantoin", "Iodoquinol", "Pyrazinamide", "Mefloquine", "Praziquantel"]'::jsonb, 'Iodoquinol', '[]'::jsonb, 'Iodoquinol is a halogenated hydroxyquinoline that kills Entamoeba histolytica in the bowel lumen, so it is used for cyst carriers and after metronidazole. Nitrofurantoin is a urinary antiseptic, pyrazinamide an antituberculous drug and mefloquine an antimalarial.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.127 Q4, Anti amoebic and other antiprotozoals. Paper has 4 options; added a fifth option (Praziquantel).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-e5f0296e58', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which amoebicide is used for the treatment of the asymptomatic intestinal form of amoebiasis?', '["Chloroquine", "Diloxanide", "Emetine", "Doxycycline", "Dehydroemetine"]'::jsonb, 'Diloxanide', '[]'::jsonb, 'Asymptomatic cyst passers have organisms only in the bowel lumen, so a poorly absorbed luminal amoebicide such as diloxanide furoate is enough. Chloroquine and emetine act in tissues, mainly the liver, and do not clear luminal cysts.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.127 Q5, Anti amoebic and other antiprotozoals. Paper has 4 options; added a fifth option (Dehydroemetine).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-1f231dcc19', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which drugs are used together for the treatment of symptomatic intestinal amoebiasis (amoebic dysentery)?', '["Metronidazole and diloxanide", "Diloxanide and streptomycin", "Diloxanide and iodoquinol", "Emetine and metronidazole", "Chloroquine and emetine"]'::jsonb, 'Metronidazole and diloxanide', '[]'::jsonb, 'Invasive intestinal disease needs a tissue amoebicide (metronidazole) to kill trophozoites in the bowel wall, followed by a luminal agent (diloxanide) to clear cysts and prevent relapse. Diloxanide with iodoquinol gives two luminal drugs and no tissue cover; emetine with metronidazole gives two tissue drugs and no luminal cover.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.127 Q6, Anti amoebic and other antiprotozoals. Paper has 4 options; added a fifth option. Stem clarified to ''symptomatic intestinal amoebiasis''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-79e4fdefc1', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which drugs are used for the treatment of the hepatic form of amoebiasis?', '["Diloxanide or iodoquinol", "Tetracycline or doxycycline", "Metronidazole or emetine", "Erythromycin or azithromycin", "Paromomycin or diloxanide"]'::jsonb, 'Metronidazole or emetine', '[]'::jsonb, 'An amoebic liver abscess needs a well-absorbed tissue amoebicide: metronidazole is first choice, with emetine or dehydroemetine (and chloroquine) as alternatives. Diloxanide, iodoquinol and paromomycin stay in the gut lumen and never reach the liver.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.127 Q7, Anti amoebic and other antiprotozoals. Paper has 4 options; added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-47a62a34aa', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which is the drug of choice for the treatment of extraluminal (tissue) amoebiasis?', '["Iodoquinol", "Metronidazole", "Diloxanide", "Tetracycline", "Paromomycin"]'::jsonb, 'Metronidazole', '[]'::jsonb, 'Metronidazole is well absorbed, penetrates the bowel wall and liver, and kills trophozoites there, so it is first choice for amoebic dysentery and liver abscess. Iodoquinol, diloxanide and paromomycin act only in the lumen and are added afterwards to eradicate cysts.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.128 Q9, Anti amoebic and other antiprotozoals. Paper has 4 options; added a fifth option (Paromomycin).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-75f9e0b258', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which drug is used for the treatment of trichomoniasis?', '["Metronidazole", "Suramin", "Pyrimethamine", "Diloxanide", "Chloroquine"]'::jsonb, 'Metronidazole', '[]'::jsonb, 'Trichomonas vaginalis is an anaerobic protozoon that reduces metronidazole to cytotoxic radicals; a single 2 g dose given to the patient and the partner is curative. Tinidazole is the alternative. Diloxanide is a nitro-free luminal amoebicide with no activity against Trichomonas.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.128 Q10, Anti amoebic and other antiprotozoals. Paper has 3 options; added two options.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-652e766661', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which drug is used for the treatment of toxoplasmosis?', '["Chloroquine", "Tetracycline", "Suramin", "Pyrimethamine", "Metronidazole"]'::jsonb, 'Pyrimethamine', '[]'::jsonb, 'Pyrimethamine inhibits protozoal dihydrofolate reductase and is combined with sulfadiazine (or clindamycin) for a sequential folate blockade against Toxoplasma gondii, with folinic acid to protect the marrow. Chloroquine and metronidazole have no useful activity against this tissue parasite.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.128 Q11, Anti amoebic and other antiprotozoals. Paper has 4 options; added a fifth option (Metronidazole).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-29e088ddee', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which drug is used for the treatment of balantidiasis?', '["Azithromycin", "Tetracycline", "Quinine", "Trimethoprim", "Pyrimethamine"]'::jsonb, 'Tetracycline', '[]'::jsonb, 'Balantidium coli, a ciliate that causes dysentery, is treated with tetracycline for 10 days; metronidazole is the alternative. The other options are not used for this infection.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.128 Q12, Anti amoebic and other antiprotozoals. Paper has 4 options; added a fifth option (Pyrimethamine).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-18a47fe585', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which drug is used for the treatment of leishmaniasis?', '["Pyrimethamine", "Albendazole", "Sodium stibogluconate", "Tinidazole", "Melarsoprol"]'::jsonb, 'Sodium stibogluconate', '[]'::jsonb, 'Sodium stibogluconate is a pentavalent antimonial given parenterally for visceral and cutaneous leishmaniasis; liposomal amphotericin B, miltefosine and paromomycin are the other options. Melarsoprol is also a heavy-metal compound, but it is an arsenical used for sleeping sickness.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.128 Q13, Anti amoebic and other antiprotozoals. Paper has 4 options; added a fifth option (Melarsoprol).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-158034618c', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'Which of the following is correctly matched?', '["Early West African trypanosomiasis : Suramin", "CNS West African trypanosomiasis : Eflornithine", "Amoebic colitis : Kanamycin", "Visceral leishmaniasis : Nifurtimox", "CNS East African trypanosomiasis : Suramin"]'::jsonb, 'CNS West African trypanosomiasis : Eflornithine', '[]'::jsonb, 'Eflornithine, an ornithine decarboxylase inhibitor, enters the cerebrospinal fluid and is used (with nifurtimox) for late-stage Trypanosoma brucei gambiense. Suramin is for early East African disease and does not reach the CNS; early West African disease is treated with pentamidine and late East African disease with melarsoprol.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.129 Q15b, Anti amoebic and other antiprotozoals. Second question numbered 15.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-amebiasis-giardiasis-trichom-14d8c30d6b', 'pharm-drugs-for-amebiasis-giardiasis-trichomoniasis-and-other-antiprot', 'mcq', 'The following are true of sodium stibogluconate EXCEPT:', '["Is a prodrug", "Chemical pancreatitis is rare", "Indicated in visceral leishmaniasis", "Electrocardiogram monitoring is recommended during therapy", "Is a pentavalent antimony derivative"]'::jsonb, 'Chemical pancreatitis is rare', '[]'::jsonb, 'A rise in amylase and lipase (chemical pancreatitis) occurs in most patients given pentavalent antimonials, although it is usually asymptomatic. The drug is reduced to active trivalent antimony inside macrophages and parasites, and it prolongs the QT interval, hence ECG monitoring.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.129 Q16, Anti amoebic and other antiprotozoals') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antiprotozoals-antimal-5731509055', 'pharm-introduction-to-antiprotozoals-antimalarials-artemisinin-compoun', 'mcq', 'Which statement about the artemisinins is false?', '["Artemisinin is insoluble and can only be given orally", "Artesunate can be given orally, intravenously, intramuscularly and rectally", "Artemether can be given intramuscularly and intravenously", "Oral absorption of artemisinin is good", "Artemisinins are rapidly acting blood schizonticides"]'::jsonb, 'Artemether can be given intramuscularly and intravenously', '[]'::jsonb, 'Artemether is lipid soluble and is formulated in oil, so it can be given orally, rectally or intramuscularly but not into a vein. Artesunate is the water-soluble derivative and the only one given intravenously, which is why it is the drug for severe malaria.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.130 Q1, Antimalarials') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antibiotic-antimalarials-malarial-prop-76dd47a84e', 'pharm-antibiotic-antimalarials-malarial-prophylaxis', 'mcq', 'Which is the incorrect statement regarding the use of drugs in malaria prophylaxis?', '["Mefloquine can be safely administered in the second trimester of pregnancy", "Suppressive prophylaxis involves administration of tissue schizonticide agents", "Daily oral doxycycline can be used for malaria prophylaxis in a 10-year-old child", "If travelling to an area with chloroquine-sensitive Plasmodium falciparum, chloroquine should be started one week before travel", "Terminal prophylaxis involves administration of daily primaquine for two weeks after leaving an area endemic for Plasmodium vivax"]'::jsonb, 'Suppressive prophylaxis involves administration of tissue schizonticide agents', '[]'::jsonb, 'Suppressive prophylaxis uses blood schizonticides (chloroquine, mefloquine, doxycycline) to kill parasites as they emerge from the liver, so no clinical attack occurs. Tissue schizonticides acting on liver stages give causal prophylaxis. Doxycycline is acceptable from 8 years of age.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.130 Q2, Antimalarials') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sulfonamides-antifolate-antimalarials-475ab566b4', 'pharm-sulfonamides-antifolate-antimalarials', 'mcq', 'Which of the following antimalarial combinations is recommended for intermittent preventive therapy in high-risk pregnant women?', '["Pyrimethamine and sulfadiazine", "Pyrimethamine and clindamycin", "Pyrimethamine and dapsone", "Pyrimethamine and sulfadoxine", "Artemether and lumefantrine"]'::jsonb, 'Pyrimethamine and sulfadoxine', '[]'::jsonb, 'Sulfadoxine-pyrimethamine is given at each antenatal visit from the second trimester, at least a month apart, in areas of stable transmission; both drugs have long half-lives, giving weeks of protection. Pyrimethamine with sulfadiazine is the toxoplasmosis regimen, and artemether-lumefantrine is for treatment, not prevention.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.130 Q3, Antimalarials') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-5229036931', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'Clinical uses of chloroquine include the following EXCEPT:', '["Treatment of non-falciparum malaria", "Chemoprophylaxis of chloroquine-sensitive falciparum malaria", "Treatment of amoebic liver abscess", "Treatment of rheumatoid arthritis", "Treatment of cardiac arrhythmias"]'::jsonb, 'Treatment of cardiac arrhythmias', '[]'::jsonb, 'Chloroquine is used for sensitive malaria, as an adjunct in amoebic liver abscess because it concentrates in the liver, and as a disease-modifying drug in rheumatoid arthritis and lupus. It is not an antiarrhythmic; it prolongs the QT interval and can cause arrhythmias. Quinidine is the quinoline used for arrhythmias.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.130 Q4, Antimalarials') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-aac16acbe5', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'Which is the false statement about quinine?', '["It is more potent than quinidine", "It has no significant effect on hypnozoites", "It antagonises the effect of physostigmine", "It is extensively metabolised", "It causes hypoglycaemia"]'::jsonb, 'It is more potent than quinidine', '[]'::jsonb, 'Quinidine, the dextrorotatory isomer, is the more potent antimalarial and also the more cardiotoxic of the two. Quinine is a blood schizonticide only, is metabolised in the liver, stimulates insulin release, and has a curare-like action on skeletal muscle that opposes physostigmine.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.130 Q5, Antimalarials') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-0dbd473eb1', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'Which of the following antimalarial drugs causes a dose-dependent toxic state that includes flushed and sweaty skin, dizziness, nausea, diarrhoea, tinnitus, blurred vision and impaired hearing?', '["Amodiaquine", "Primaquine", "Pyrimethamine", "Quinine", "Sulfadoxine"]'::jsonb, 'Quinine', '[]'::jsonb, 'This syndrome is cinchonism, named after the cinchona bark from which quinine and quinidine come. Mild forms (tinnitus, headache, nausea) are common at therapeutic levels and are not a reason to stop treatment; severe visual or auditory symptoms are.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.132 Q12b, Antimalarials. Second question numbered 12.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-53f803d943', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'Which drug is used for both malaria chemoprophylaxis and treatment?', '["Chloroquine", "Quinidine", "Quinine", "Sulfonamides", "Artesunate"]'::jsonb, 'Chloroquine', '[]'::jsonb, 'Chloroquine has a long half-life, so a weekly dose prevents attacks in areas with sensitive parasites, and a three-day course treats them. Quinine and quinidine are too toxic and short-acting for prophylaxis, and artesunate is used only for treatment.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.132 Q13, Antimalarials. Paper has 4 options; added a fifth option (Artesunate).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-1cd6d34962', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'Which antimalarial drug belongs to the 8-aminoquinoline derivatives?', '["Doxycycline", "Quinidine", "Primaquine", "Chloroquine", "Mefloquine"]'::jsonb, 'Primaquine', '[]'::jsonb, 'Primaquine and tafenoquine carry the amino side chain at position 8 of the quinoline ring; this group gives activity against liver hypnozoites and gametocytes, and also the haemolysis seen in G6PD deficiency. Chloroquine is a 4-aminoquinoline.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.132 Q14, Antimalarials. Paper has 4 options; added a fifth option (Mefloquine).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-a39f84a93a', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'All of the following antimalarial drugs act on blood schizonts EXCEPT:', '["Mefloquine", "Chloroquine", "Primaquine", "Quinidine", "Quinine"]'::jsonb, 'Primaquine', '[]'::jsonb, 'Primaquine has only weak activity against asexual erythrocytic parasites, so it cannot be used alone to treat an acute attack; it is added to a blood schizonticide for radical cure. Mefloquine, chloroquine, quinine and quinidine all kill blood schizonts.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.132 Q18, Antimalarials. Paper has 4 options; added a fifth option (Quinine).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-416d237c8e', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'Which antimalarial drug acts on tissue (liver) schizonts?', '["Mefloquine", "Chloroquine", "Quinidine", "Primaquine", "Artesunate"]'::jsonb, 'Primaquine', '[]'::jsonb, 'Primaquine kills primary liver schizonts and the dormant hypnozoites of P. vivax and P. ovale, which is why it gives radical cure. Mefloquine, chloroquine, quinidine and artesunate work only once parasites are in red cells.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.133 Q19, Antimalarials. Paper has 4 options; added a fifth option (Artesunate).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-7e1d3fce66', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'The following are true about primaquine EXCEPT:', '["Is well absorbed orally", "Is excreted unchanged in the urine", "Is effective against hypnozoites", "Is gametocidal to all Plasmodium species", "Is effective in the treatment of Pneumocystis jirovecii pneumonia"]'::jsonb, 'Is excreted unchanged in the urine', '[]'::jsonb, 'Primaquine is rapidly and extensively metabolised in the liver (its activity and its haemolytic toxicity depend on metabolites), and very little parent drug reaches the urine. It is used with clindamycin as an alternative regimen for Pneumocystis pneumonia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.133 Q23, Antimalarials') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sulfonamides-antifolate-antimalarials-213f3f97d3', 'pharm-sulfonamides-antifolate-antimalarials', 'mcq', 'Which statement is false about antifolate drugs used for the treatment of malaria?', '["Proguanil is a biguanide derivative", "Proguanil is a prodrug", "Proguanil is administered weekly for malaria chemoprophylaxis", "Sulfadoxine has a half-life of 7 days", "They are effective for treatment of chloroquine-resistant malaria when used in combination therapy"]'::jsonb, 'Proguanil is administered weekly for malaria chemoprophylaxis', '[]'::jsonb, 'Proguanil has a half-life of about 16 hours, so it must be taken daily. It is a biguanide converted by CYP2C19 to cycloguanil, the dihydrofolate reductase inhibitor. The long-acting pair sulfadoxine and pyrimethamine is the antifolate combination that can be given at long intervals.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.133 Q24, Antimalarials') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-a1ea353c23', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'The following are true of atovaquone EXCEPT:', '["Is a quinine derivative", "It inhibits the malarial parasite''s electron transport chain", "Is synergistic with proguanil", "It is given daily for malarial chemoprophylaxis", "It is used for treatment of Pneumocystis jirovecii pneumonia"]'::jsonb, 'Is a quinine derivative', '[]'::jsonb, 'Atovaquone is a hydroxynaphthoquinone, an analogue of ubiquinone, not a quinoline. It blocks the cytochrome bc1 complex in parasite mitochondria, and proguanil lowers the concentration at which it collapses the mitochondrial membrane potential, hence the fixed combination taken daily.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.134 Q25, Antimalarials. Paper had two false options (''given weekly'' is also false); changed that option to ''given daily'' so only one answer fits.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-i-1f4568d95e', 'pharm-antihelminthics-i', 'mcq', 'Which of the following is not an adverse effect of albendazole?', '["Nephrotoxicity", "Hepatotoxicity", "Alopecia", "Pancytopenia", "Fever"]'::jsonb, 'Nephrotoxicity', '[]'::jsonb, 'Short courses of albendazole are almost free of side effects. With the long courses used for hydatid disease or neurocysticercosis it can raise liver enzymes, suppress the bone marrow, and cause reversible hair loss and fever, so blood counts and liver function are monitored. Kidney damage is not a feature.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.134 Q2, Antihelminthics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-i-97520cabc2', 'pharm-antihelminthics-i', 'mcq', 'Which of the following drugs enhances GABA actions at the neuromuscular junctions of nematodes?', '["Glutamic acid", "Ivermectin", "Picrotoxin", "Pyrantel pamoate", "Pyrimethamine"]'::jsonb, 'Ivermectin', '[]'::jsonb, 'Ivermectin opens glutamate-gated chloride channels and intensifies GABA-mediated transmission in nematode nerve and muscle, hyperpolarising the cells and paralysing the worm. Pyrantel also paralyses worms, but by depolarising nicotinic receptors (spastic paralysis), not through GABA.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.135 Q5, Antihelminthics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-i-52c875a916', 'pharm-antihelminthics-i', 'mcq', 'The following are true of albendazole EXCEPT:', '["Is a broad-spectrum anthelmintic", "Is the drug of choice for treatment of cysticercosis", "Inhibits microtubule synthesis", "May cause pancytopenia", "Well absorbed from the gastrointestinal tract"]'::jsonb, 'Well absorbed from the gastrointestinal tract', '[]'::jsonb, 'Albendazole is poorly and erratically absorbed; a fatty meal increases absorption several-fold, so it is taken with food for tissue infections and on an empty stomach for luminal worms. Long courses can cause marrow suppression, hence the pancytopenia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.136 Q13, Antihelminthics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-ii-ectoparasites-f1e9cb766a', 'pharm-antihelminthics-ii-ectoparasites', 'mcq', 'Which of the following ectoparasiticides is indicated for the treatment of both scabies and pediculosis?', '["Pyrethrins with piperonyl butoxide", "Crotamiton", "Malathion", "Lindane", "Benzyl alcohol"]'::jsonb, 'Lindane', '[]'::jsonb, 'Lindane (gamma benzene hexachloride) is absorbed through the chitin of both mites and lice and is licensed as a second-line agent for scabies and for pediculosis; neurotoxicity limits its use. Pyrethrins with piperonyl butoxide and benzyl alcohol are for lice only, and crotamiton is a scabicide.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.137 Q1, Ectoparasiticides. Answer follows Katzung. In the BNF malathion is also used for both scabies and lice, so two options could be defended.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antihelminthics-ii-ectoparasites-96de8edc45', 'pharm-antihelminthics-ii-ectoparasites', 'mcq', 'Which agent is not scabicidal?', '["Permethrin cream", "Sulphur in petrolatum", "Whitfield''s ointment", "Oral ivermectin", "Crotamiton lotion"]'::jsonb, 'Whitfield''s ointment', '[]'::jsonb, 'Whitfield''s ointment is benzoic acid with salicylic acid, a keratolytic and fungistatic preparation for dermatophyte infections such as tinea pedis. Permethrin, sulphur ointment, crotamiton and oral ivermectin all kill Sarcoptes scabiei.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.137 Q3, Ectoparasiticides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-topical-antimicrobials-daf7db5532', 'pharm-topical-antimicrobials', 'mcq', 'Which one of the following topical antimicrobials disrupts bacterial cell membranes and also binds and inactivates endotoxin?', '["Bacitracin", "Neomycin", "Polymyxin B sulphate", "Mupirocin", "Metronidazole"]'::jsonb, 'Polymyxin B sulphate', '[]'::jsonb, 'Polymyxin B is a cationic detergent-like peptide that binds the lipid A part of lipopolysaccharide, disrupting the outer and inner membranes of Gram-negative bacteria and neutralising endotoxin. Bacitracin acts on cell wall synthesis and mupirocin on isoleucyl-tRNA synthetase.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.138 Q4, Topical antimicrobials') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-disinfectants-and-antiseptics-a9ba76780d', 'pharm-disinfectants-and-antiseptics', 'mcq', 'The following disinfectants/antiseptics can be used as sterilants EXCEPT:', '["Ethylene oxide", "Glutaraldehyde", "Peracetic acid", "Chlorine dioxide", "Quaternary ammonium compounds"]'::jsonb, 'Quaternary ammonium compounds', '[]'::jsonb, 'Quaternary ammonium compounds are low-level disinfectants: they do not kill spores, mycobacteria or hydrophilic viruses, and Pseudomonas can even grow in them. Ethylene oxide, glutaraldehyde, peracetic acid and chlorine dioxide are sporicidal and can sterilise with adequate contact time.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.138 Q2, Antiseptics and Disinfectants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-disinfectants-and-antiseptics-3e844ed537', 'pharm-disinfectants-and-antiseptics', 'mcq', 'The following are disadvantages of antiseptics EXCEPT:', '["General biocidal activity", "May accumulate in the body of the patient or caregiver", "All are prodrugs", "May be contaminated with organisms or spores and transmit infection", "Most interfere with wound healing"]'::jsonb, 'All are prodrugs', '[]'::jsonb, 'Antiseptics act directly on microbial proteins and membranes; they need no metabolic activation. Their real drawbacks are that they are non-selective, so they damage host cells and delay wound healing, may be absorbed and accumulate, and their solutions can become contaminated with resistant organisms.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.138 Q5, Antiseptics and Disinfectants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-disinfectants-and-antiseptics-0c95196708', 'pharm-disinfectants-and-antiseptics', 'mcq', 'Which one of the following antiseptics/disinfectants kills Gram-positive and Gram-negative cocci and bacilli, acid-fast bacteria, spores, lipophilic and hydrophilic viruses, fungi, amoebic cysts and prions?', '["Sodium hypochlorite", "Povidone iodine", "Cresols", "Chlorhexidine", "Glutaraldehyde"]'::jsonb, 'Sodium hypochlorite', '[]'::jsonb, 'Hypochlorite releases hypochlorous acid, a strong oxidising agent with the broadest spectrum of the common disinfectants; at high concentration it also inactivates prions, which resist aldehydes. Glutaraldehyde is sporicidal but actually fixes and stabilises prion protein.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.139 Q6, Antiseptics and Disinfectants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-disinfectants-and-antiseptics-db98aaf1ac', 'pharm-disinfectants-and-antiseptics', 'mcq', 'The following are true of alcohols as antiseptics/disinfectants EXCEPT:', '["Do not penetrate protein-containing organic materials", "Have a rapid killing effect", "Reliably inactivate both hydrophilic and lipophilic viruses", "The most commonly used are ethanol and isopropyl alcohol", "Optimal bactericidal concentration is 60-90% by volume in water"]'::jsonb, 'Reliably inactivate both hydrophilic and lipophilic viruses', '[]'::jsonb, 'Alcohols dissolve lipid envelopes, so lipophilic (enveloped) viruses are readily inactivated, but hydrophilic non-enveloped viruses such as poliovirus and norovirus are much less susceptible. Alcohols act fast, need water to denature proteins (hence 60 to 90%), and are inactivated by organic matter.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.139 Q7, Antiseptics and Disinfectants. Follows Katzung (alcohols ''may not be active against hydrophilic viruses''); added ''reliably'' to the option. Other sources credit high-concentration ethanol with activity against many hydrophilic viruses.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-disinfectants-and-antiseptics-00ecae6827', 'pharm-disinfectants-and-antiseptics', 'mcq', 'The following are true about the antiseptic chlorhexidine EXCEPT:', '["Active against vegetative bacteria and mycobacteria", "Action is slower than that of alcohols", "Has residual activity when used repeatedly", "Blood and organic materials inhibit its activity", "Soaps neutralise its action"]'::jsonb, 'Blood and organic materials inhibit its activity', '[]'::jsonb, 'Chlorhexidine is a cationic biguanide that binds to skin and keeps working for hours, and it remains active in the presence of blood and organic matter, unlike iodine or hypochlorite. Because it is cationic, anionic soaps and detergents neutralise it.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.139 Q9, Antiseptics and Disinfectants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-azathioprine-sulfasalazine-leflunomide-53f138d310', 'pharm-azathioprine-sulfasalazine-leflunomide-and-other-conventional-dm', 'mcq', 'The following are true of leflunomide EXCEPT:', '["Safe in pregnancy", "Is a disease-modifying antirheumatic drug (DMARD)", "Cholestyramine enhances its excretion", "Is a prodrug", "Inhibits T cell proliferation"]'::jsonb, 'Safe in pregnancy', '[]'::jsonb, 'Leflunomide is teratogenic and its active metabolite persists for up to two years because of enterohepatic recycling, so pregnancy must be excluded and a cholestyramine washout given before conception. It is a prodrug of teriflunomide, which inhibits dihydroorotate dehydrogenase and so halts pyrimidine synthesis in proliferating T cells.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.139 Q1, DMARDs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-dmards-49c94ac62d', 'pharm-introduction-to-dmards', 'mcq', 'Which of the following is not a conventional synthetic DMARD?', '["Chloroquine", "Abatacept", "Mycophenolate mofetil", "Sulfasalazine", "Methotrexate"]'::jsonb, 'Abatacept', '[]'::jsonb, 'Abatacept is a biologic: a fusion protein of CTLA-4 and the Fc part of IgG that binds CD80/86 and blocks T cell co-stimulation. Conventional synthetic DMARDs are small molecules made chemically, such as methotrexate, sulfasalazine, the antimalarials and mycophenolate mofetil.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.140 Q2, DMARDs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methotrexate-chloroquine-hydroxychloro-2d649d44cb', 'pharm-methotrexate-chloroquine-hydroxychloroquine', 'mcq', 'Which statement is not true about chloroquine and hydroxychloroquine?', '["May be used for the management of rheumatoid arthritis that has been unresponsive to NSAIDs", "Recommended for psoriatic arthritis", "May cause ocular toxicity", "Their clinical effect becomes apparent 12-24 weeks after initiation of treatment", "Extensively bound to tissues"]'::jsonb, 'Recommended for psoriatic arthritis', '[]'::jsonb, 'Antimalarials can precipitate or worsen psoriasis, including exfoliative dermatitis, so they are avoided in psoriatic arthritis. They are slow-acting drugs for mild rheumatoid arthritis and lupus, bind avidly to melanin-containing tissue, and need regular eye checks because of retinopathy.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.140 Q3, DMARDs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methotrexate-chloroquine-hydroxychloro-31f49e6e51', 'pharm-methotrexate-chloroquine-hydroxychloroquine', 'mcq', 'Which is the false statement about the use of methotrexate for the treatment of rheumatoid arthritis?', '["It has a bioavailability of about 70% after oral administration", "It has a half-life of 6-9 hours", "It is often administered once weekly", "It is excreted mainly in bile", "Lower doses are used than those required in cancer chemotherapy"]'::jsonb, 'It is excreted mainly in bile', '[]'::jsonb, 'Methotrexate is excreted mainly unchanged in the urine, with only a minor fraction in bile, which is why renal impairment and drugs that reduce its tubular secretion (NSAIDs, probenecid) raise toxicity. In rheumatoid arthritis 7.5 to 25 mg is taken once a week.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.140 Q4, DMARDs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biologic-dmards-7c397f47b5', 'pharm-biologic-dmards', 'mcq', 'Tumour necrosis factor alpha (TNF-alpha) blocking drugs are associated with an increase in the following adverse effects EXCEPT:', '["Malignant melanoma", "Hepatitis B virus reactivation", "Gastrointestinal ulcers", "Drug-induced lupus erythematosus", "Injection site reactions"]'::jsonb, 'Gastrointestinal ulcers', '[]'::jsonb, 'TNF blockers impair granuloma maintenance and immune surveillance, so they reactivate tuberculosis and hepatitis B, increase skin cancers including melanoma, induce antinuclear antibodies with a lupus-like syndrome, and cause injection or infusion reactions. Peptic ulceration is an effect of NSAIDs and corticosteroids, not of these agents.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.140 Q5, DMARDs. Options b and d reworded slightly for accuracy (reactivation of hepatitis B; drug-induced lupus).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-azathioprine-sulfasalazine-leflunomide-a53dbeaa88', 'pharm-azathioprine-sulfasalazine-leflunomide-and-other-conventional-dm', 'mcq', 'The following are true about leflunomide EXCEPT:', '["Is a prodrug", "Cholestyramine reduces its intestinal reabsorption", "Its plasma half-life is about 19 days", "Rarely causes myelosuppression", "Is less effective than methotrexate in the treatment of rheumatoid arthritis"]'::jsonb, 'Is less effective than methotrexate in the treatment of rheumatoid arthritis', '[]'::jsonb, 'In trials leflunomide was as effective as methotrexate in rheumatoid arthritis, including in slowing joint damage. It is converted to teriflunomide, which recirculates through bile, giving a half-life of about 19 days; cholestyramine interrupts this cycle. Diarrhoea and raised liver enzymes are its usual problems.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.142 Q16, DMARDs. Option B reworded (''reabsorption'' for ''absorption''). Relative efficacy vs methotrexate is a Katzung statement; human check advised.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biologic-dmards-dc48ca9402', 'pharm-biologic-dmards', 'mcq', 'Choose the odd one out:', '["Rituximab", "Certolizumab", "Infliximab", "Etanercept", "Golimumab"]'::jsonb, 'Rituximab', '[]'::jsonb, 'Rituximab is a chimeric antibody against CD20 that depletes B lymphocytes. The other four all neutralise TNF-alpha: infliximab and golimumab are antibodies, certolizumab is a pegylated Fab fragment, and etanercept is a soluble TNF receptor fusion protein.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.142 Q18, DMARDs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-dmards-ad52449a3a', 'pharm-introduction-to-dmards', 'mcq', 'Which of the following is true regarding disease-modifying antirheumatic drugs?', '["Their effect is evident after one week of therapy", "Chloroquine is safer than hydroxychloroquine", "Methotrexate is associated with dose-related hepatotoxicity", "Cyclosporine is the preferred agent in patients with renal injury", "Organic gold compounds are the safest disease-modifying agents"]'::jsonb, 'Methotrexate is associated with dose-related hepatotoxicity', '[]'::jsonb, 'Methotrexate raises liver enzymes and with cumulative dosing can cause fibrosis, so liver function is monitored and alcohol restricted. DMARDs take weeks to months to act, hydroxychloroquine is less toxic to the retina than chloroquine, cyclosporine is nephrotoxic, and gold is among the most toxic.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.143 Q23, DMARDs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methotrexate-chloroquine-hydroxychloro-fce6eb1553', 'pharm-methotrexate-chloroquine-hydroxychloroquine', 'mcq', 'The following are true about the DMARDs chloroquine and hydroxychloroquine EXCEPT:', '["Elimination half-life of up to 45 days", "Have an anti-inflammatory effect", "May cause ocular toxicity", "Effect becomes apparent in 12-24 hours", "Should not be used for psoriatic arthritis"]'::jsonb, 'Effect becomes apparent in 12-24 hours', '[]'::jsonb, 'The antimalarials are slow-acting: benefit in rheumatoid arthritis or lupus takes 3 to 6 months (12 to 24 weeks), partly because their huge tissue binding and half-life of up to 45 days mean steady state is reached slowly.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.143 Q24, DMARDs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-azathioprine-sulfasalazine-leflunomide-68a198b78d', 'pharm-azathioprine-sulfasalazine-leflunomide-and-other-conventional-dm', 'mcq', 'Regarding drug interactions, azathioprine reduces the effect of one of the following drugs:', '["Co-trimoxazole", "Ribavirin", "5-aminosalicylate", "Allopurinol", "Warfarin"]'::jsonb, 'Warfarin', '[]'::jsonb, 'Azathioprine reduces the anticoagulant effect of warfarin, so the INR falls and warfarin needs may rise. The other interactions run the other way: allopurinol blocks xanthine oxidase and aminosalicylates inhibit TPMT, both raising thiopurine toxicity, while co-trimoxazole and ribavirin add to its myelosuppression.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.143 Q25, DMARDs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-1600f76dfc', 'pharm-drugs-used-in-the-management-of-gout', 'mcq', 'Which one of the following is a xanthine oxidase inhibitor that is useful in the management of gout?', '["Uricase", "Colchicine", "Probenecid", "Febuxostat", "Indomethacin"]'::jsonb, 'Febuxostat', '[]'::jsonb, 'Febuxostat is a non-purine selective inhibitor of xanthine oxidase, used when allopurinol is not tolerated. Uricase preparations lower urate too, but by converting uric acid to soluble allantoin rather than by blocking its synthesis; probenecid increases renal excretion.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.144 Q1, Anti gout') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-ffcf6289b5', 'pharm-drugs-used-in-the-management-of-gout', 'mcq', 'Which statement is false regarding colchicine?', '["Undergoes significant enterohepatic circulation", "Has a large volume of distribution", "Is a substrate of the P-glycoprotein pump", "Inhibits production of interleukin-1 beta", "Absorption is affected by food"]'::jsonb, 'Absorption is affected by food', '[]'::jsonb, 'Colchicine is absorbed rapidly whether or not food is present. It is widely distributed, recycled through bile, and exported by P-glycoprotein and metabolised by CYP3A4, so inhibitors such as clarithromycin and cyclosporine can cause fatal toxicity. It blocks microtubules and the NLRP3 inflammasome, reducing interleukin-1 beta.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.144 Q2, Anti gout. Option d on the paper reads ''interleukin 1B and IL-1B'' (typo); tidied.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-1af9455995', 'pharm-drugs-used-in-the-management-of-gout', 'mcq', 'The following are true of colchicine in the treatment of gout EXCEPT:', '["Is rapidly absorbed after oral administration", "Is mainly excreted in stool", "Prevents polymerisation of tubulin into microtubules", "May be used for prophylaxis of recurrent episodes", "Should be given intravenously for terminating acute attacks"]'::jsonb, 'Should be given intravenously for terminating acute attacks', '[]'::jsonb, 'Intravenous colchicine has been abandoned because of fatal bone marrow failure and tissue necrosis; it is given orally in low doses (for example 1 mg then 0.5 mg an hour later) within the first day of an attack. Low daily doses prevent attacks while urate-lowering therapy is started.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.145 Q10, Anti gout') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-the-management-of-gout-d7096a7ec3', 'pharm-drugs-used-in-the-management-of-gout', 'saq', 'True or false: Acute attacks of gouty arthritis occur early in treatment with allopurinol.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'A rapid fall in serum urate mobilises crystals from tissue deposits and can trigger attacks in the first weeks. Allopurinol is therefore started at a low dose with colchicine or an NSAID as prophylaxis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.145 Q10tf-b, Anti gout True/False') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-immunosuppressant-2100dcffe9', 'pharm-corticosteroids-immunosuppressant', 'mcq', 'Which is not an adverse effect of glucocorticoids?', '["Weight loss", "Hyperglycaemia", "Easy bruisability", "Skin striae", "Myopathy"]'::jsonb, 'Weight loss', '[]'::jsonb, 'Glucocorticoids increase appetite and redistribute fat to the trunk and face, so weight gain is the rule. Their catabolic effect on protein thins the skin (bruising, striae) and wastes proximal muscles, and increased gluconeogenesis raises blood glucose.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.146 Q2, Corticosteroids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-immunosuppressant-dbb146bbee', 'pharm-corticosteroids-immunosuppressant', 'mcq', 'Which corticosteroid has predominant salt- and water-retaining properties?', '["Hydrocortisone", "Methylprednisolone", "Budesonide", "Fludrocortisone", "Dexamethasone"]'::jsonb, 'Fludrocortisone', '[]'::jsonb, 'Fludrocortisone has about 125 times the mineralocorticoid potency of hydrocortisone, so at replacement doses it acts almost purely on sodium and water retention; it is used in Addison''s disease. Hydrocortisone has some mineralocorticoid action, but equal to its glucocorticoid action, and dexamethasone has none.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.146 Q4, Corticosteroids. Stem tidied (''glucocorticoid with predominant water retention'' → corticosteroid with salt- and water-retaining properties).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcineurin-inhibitors-antiproliferati-b5f0bdc535', 'pharm-calcineurin-inhibitors-antiproliferative-antimetabolite-drugs', 'mcq', 'The following are true of sirolimus EXCEPT:', '["Used to prevent organ transplant rejection", "Causes hypokalaemia", "Inhibits calcineurin", "Has anticancer effects", "Is a substrate of CYP3A4 and P-glycoprotein"]'::jsonb, 'Inhibits calcineurin', '[]'::jsonb, 'Sirolimus binds FKBP-12 like tacrolimus, but the complex inhibits mTOR, not calcineurin, so T cells fail to respond to interleukin-2 and stop in G1. This antiproliferative action also explains its anticancer use and its use on coronary stents.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.146 Q1, Calcineurin Inhibitors. Paper''s option e (''peak concentration is increased by fatty meals'') is also false (a fatty meal lowers the peak), so it was replaced to leave one correct answer.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcineurin-inhibitors-antiproliferati-7b4fea3bcd', 'pharm-calcineurin-inhibitors-antiproliferative-antimetabolite-drugs', 'mcq', 'The following are true of tacrolimus EXCEPT:', '["It is a calcineurin inhibitor", "It binds to albumin", "It binds to alpha-1-acid glycoprotein", "It is used for prophylaxis of organ transplant rejection", "It causes hypokalaemia"]'::jsonb, 'It causes hypokalaemia', '[]'::jsonb, 'Calcineurin inhibitors reduce potassium secretion in the distal nephron, so tacrolimus causes hyperkalaemia (with hypomagnesaemia), together with nephrotoxicity, neurotoxicity and hyperglycaemia. In plasma it is bound to albumin and alpha-1-acid glycoprotein.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.147 Q3, Calcineurin Inhibitors') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcineurin-inhibitors-antiproliferati-66a4a9ae1b', 'pharm-calcineurin-inhibitors-antiproliferative-antimetabolite-drugs', 'mcq', 'Which one of the following immunosuppressants is a calcineurin inhibitor?', '["Prednisone", "Cyclosporine", "Azathioprine", "Cyclophosphamide", "Mycophenolate mofetil"]'::jsonb, 'Cyclosporine', '[]'::jsonb, 'Cyclosporine binds cyclophilin, and the complex inhibits calcineurin, so NFAT is not dephosphorylated and the interleukin-2 gene is not transcribed. Azathioprine and mycophenolate are antiproliferative antimetabolites and cyclophosphamide is an alkylating agent.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.147 Q4, Calcineurin Inhibitors') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antibody-preparations-d343b5dee1', 'pharm-antibody-preparations', 'mcq', 'The following are true of anti-lymphocyte globulin (ALG) and anti-thymocyte globulin (ATG) preparations EXCEPT:', '["They suppress rejection reactions in solid organ transplants while preserving antibody formation", "They increase the incidence of lymphomas in kidney transplant recipients", "They are useful in the treatment of glomerulonephritis", "They can be used in combination with cyclosporine", "They can cause anaphylaxis"]'::jsonb, 'They are useful in the treatment of glomerulonephritis', '[]'::jsonb, 'These animal antisera deplete circulating T lymphocytes, impairing cell-mediated immunity while humoral immunity is relatively spared. Being foreign proteins they can cause anaphylaxis and serum sickness, and immune-complex nephritis is one of their adverse effects, not an indication.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.147 Q2, Antibody preparation. Paper asks ''True of ALG and ATG:'' but four of the five options are true, so it was reworded as an EXCEPT question; option a''s truncated ending (''while preserving antibody'') completed as ''antibody formation''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antibody-preparations-3847b4ff56', 'pharm-antibody-preparations', 'mcq', 'Examples of conditions treated with hyperimmune globulins include the following EXCEPT:', '["Respiratory syncytial virus infection", "Hepatitis B", "Rabies", "Tetanus", "Graft rejection reaction"]'::jsonb, 'Graft rejection reaction', '[]'::jsonb, 'Hyperimmune globulins are pooled from donors with high antibody titres against a specific pathogen or toxin and give passive immunity, as with RSV, hepatitis B, rabies and tetanus immunoglobulins. Graft rejection is treated with antibodies against the patient''s own lymphocytes, such as anti-thymocyte globulin.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.148 Q3, Antibody preparation') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-the-immune-response-introduction-to-im-d9e2a7413a', 'pharm-the-immune-response-introduction-to-immunosuppressants', 'mcq', 'The following are true of the immune system EXCEPT:', '["TH1 T-lymphocytes suppress TH2 cell proliferation", "TH1 T-lymphocytes induce cell-mediated immunity by activating macrophages, cytotoxic T-lymphocytes and natural killer cells", "TH2 T-lymphocytes induce B-cell proliferation and differentiation to plasma cells", "TH2 T-lymphocytes suppress TH1 cell proliferation", "CD8 cells are responsible for recognition and attack of extracellular pathogens"]'::jsonb, 'CD8 cells are responsible for recognition and attack of extracellular pathogens', '[]'::jsonb, 'CD8 cytotoxic T cells recognise peptides presented on MHC class I and kill cells harbouring intracellular pathogens such as viruses, as well as tumour cells. Extracellular organisms are dealt with by antibody, complement and phagocytes. TH1 and TH2 subsets inhibit each other through interferon-gamma and interleukins 4 and 10.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.148 Q1, Immunostimulants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-the-immune-response-introduction-to-im-3181aeb42c', 'pharm-the-immune-response-introduction-to-immunosuppressants', 'mcq', 'The following are components of the non-specific (innate) immune system EXCEPT:', '["Complement system", "Lysozymes", "Macrophages", "Interferons", "CD4 cells"]'::jsonb, 'CD4 cells', '[]'::jsonb, 'CD4 helper T cells carry antigen-specific receptors and belong to the adaptive immune system. Complement, lysozyme, phagocytes such as macrophages, and interferons act immediately without prior exposure or antigen specificity, which defines innate immunity.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.148 Q4, Immunostimulants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-432d735f98', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'mcq', 'Which statement is false regarding cyclooxygenase-2 (COX-2) selective non-steroidal anti-inflammatory drugs (NSAIDs)?', '["Lumiracoxib is the most selective for COX-2", "Celecoxib is five times more selective for COX-2 than COX-1", "Etodolac is an example", "Rofecoxib increases the risk of myocardial infarction", "COX-2 selective NSAIDs cause less gastric ulceration"]'::jsonb, 'Celecoxib is five times more selective for COX-2 than COX-1', '[]'::jsonb, 'Celecoxib is about 10 to 20 times more selective for COX-2 than for COX-1. Selective inhibitors spare gastric COX-1 and so cause fewer ulcers, but they reduce endothelial prostacyclin without affecting platelet thromboxane, which explains the excess of myocardial infarction that led to withdrawal of rofecoxib.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.149 Q2, NSAIDs and paracetamol. Selectivity ratios vary between assays and textbooks (answer uses Katzung''s 10-20 fold); etodolac as a ''COX-2 selective'' drug is also debatable.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-acetaminophen-acetylsalicylic-acid-poi-81c92039cf', 'pharm-acetaminophen-acetylsalicylic-acid-poisoning', 'mcq', 'A 16-year-old girl comes to the emergency department suffering from the effects of an aspirin overdose. Which of the following syndromes is this patient most likely to exhibit as a result of this overdose?', '["Bone marrow suppression and possibly aplastic anaemia", "Fever, hepatic dysfunction and encephalopathy", "Hyperthermia, metabolic acidosis and coma", "Rapid, fulminant hepatic failure", "Rash, interstitial nephritis and acute renal failure"]'::jsonb, 'Hyperthermia, metabolic acidosis and coma', '[]'::jsonb, 'Toxic doses of salicylate uncouple oxidative phosphorylation, so energy is lost as heat and lactic and keto acids accumulate, on top of an initial respiratory alkalosis from direct stimulation of the respiratory centre. Fever with liver dysfunction and encephalopathy describes Reye''s syndrome, which follows therapeutic doses in children with viral illness.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.149 Q6, NSAIDs and paracetamol') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-salicylates-enolic-acids-nalbumetone-a-1ec863c329', 'pharm-salicylates-enolic-acids-nalbumetone-and-pyrazolone-derivatives', 'mcq', 'Aspirin could be used prophylactically for which one of the following conditions?', '["Bronchial asthma", "Thromboembolism", "Paroxysmal atrial tachycardia", "Peptic ulcer", "Hypertension"]'::jsonb, 'Thromboembolism', '[]'::jsonb, 'Low-dose aspirin (75 to 150 mg daily) irreversibly blocks platelet thromboxane synthesis and is used for secondary prevention of myocardial infarction and ischaemic stroke. It would worsen peptic ulcer and can provoke asthma.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.150 Q10, NSAIDs and paracetamol') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraminophenols-indole-acetic-acids-de-910919d66f', 'pharm-paraminophenols-indole-acetic-acids-derivatives-heteroarylacetic', 'mcq', 'The following are true of paracetamol EXCEPT:', '["Is a potent inhibitor of COX-1 and COX-2 in peripheral tissues", "May be administered rectally", "Is converted to inactive metabolites", "Requires dosage adjustment in liver disease", "Acetylcysteine is the antidote in cases of poisoning"]'::jsonb, 'Is a potent inhibitor of COX-1 and COX-2 in peripheral tissues', '[]'::jsonb, 'Paracetamol is only a weak inhibitor of cyclooxygenase in peripheral tissues, where high peroxide levels at inflamed sites block its action; this is why it lacks anti-inflammatory and antiplatelet effects. It is mostly conjugated to inactive glucuronide and sulphate.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.152 Q23, NSAIDs and paracetamol') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-salicylates-enolic-acids-nalbumetone-a-9f6a978308', 'pharm-salicylates-enolic-acids-nalbumetone-and-pyrazolone-derivatives', 'saq', 'True or false: Aspirin produces reversible competitive inhibition of the cyclooxygenase enzyme.', '[]'::jsonb, 'False', '["F"]'::jsonb, 'Aspirin irreversibly acetylates a serine residue in the active site of cyclooxygenase. Platelets have no nucleus and cannot make new enzyme, so the antiplatelet effect lasts for the life of the platelet. Other NSAIDs are reversible competitive inhibitors.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.153 Q23tf, NSAIDs True/False') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-salicylates-enolic-acids-nalbumetone-a-dfb7e43246', 'pharm-salicylates-enolic-acids-nalbumetone-and-pyrazolone-derivatives', 'saq', 'True or false: In low doses, elimination of salicylates follows first-order kinetics, but with high doses elimination follows zero-order kinetics.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'The conjugation pathways for salicylate with glycine and glucuronic acid become saturated at anti-inflammatory doses, so the half-life rises from about 3 hours to 15 hours or more and small dose increases cause large rises in plasma level.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.153 Q24tf, NSAIDs True/False') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-and-classification-of-ana-26e12c6ce7', 'pharm-introduction-and-classification-of-analgesia-introduction-to-nsa', 'mcq', 'Which of the following is used for the treatment of neuropathic pain?', '["Aspirin", "Paracetamol", "Codeine", "Carbamazepine", "Ibuprofen"]'::jsonb, 'Carbamazepine', '[]'::jsonb, 'Neuropathic pain arises from abnormal firing of damaged nerves and responds poorly to ordinary analgesics. Carbamazepine blocks voltage-gated sodium channels and suppresses this ectopic firing; it is first choice in trigeminal neuralgia. Amitriptyline, gabapentin and pregabalin are other adjuvant analgesics.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.153 Q1, Opioids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-1983e3a4c6', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'Which of the following opioids is not a strong agonist?', '["Pethidine", "Levorphanol", "Butorphanol", "Alfentanil", "Morphine"]'::jsonb, 'Butorphanol', '[]'::jsonb, 'Butorphanol is a mixed agonist-antagonist: a kappa agonist with partial agonist or antagonist action at mu receptors, so its analgesia and respiratory depression reach a ceiling and it can precipitate withdrawal in dependent patients. The other four are full mu agonists.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.153 Q2, Opioids. Repeated as p.155 Q15; one copy kept.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-c20c414410', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Which of the following is not an effect of morphine?', '["Mydriasis", "Euphoria", "Emesis", "Increased CSF pressure", "Decreased testosterone concentration"]'::jsonb, 'Mydriasis', '[]'::jsonb, 'Morphine stimulates the Edinger-Westphal nucleus, producing miosis; pinpoint pupils are a sign of overdose. Carbon dioxide retention from respiratory depression dilates cerebral vessels and raises CSF pressure, and chronic use suppresses GnRH and LH, lowering testosterone.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.153 Q4, Opioids. Repeated as p.155 Q17; one copy kept.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-fentanyl-and-congeners-levorphanol-and-91fc1a626e', 'pharm-fentanyl-and-congeners-levorphanol-and-congeners-pethidine-and-c', 'mcq', 'The following are true about meperidine (pethidine) EXCEPT:', '["Is mainly a kappa receptor agonist", "Has a mild spasmogenic effect in the biliary system", "Does not antagonise the effect of oxytocin on the uterus", "Causes tremors", "Is less potent than morphine"]'::jsonb, 'Is mainly a kappa receptor agonist', '[]'::jsonb, 'Pethidine is predominantly a mu receptor agonist, about one-tenth as potent as morphine. Its metabolite norpethidine is a CNS stimulant causing tremor, myoclonus and seizures, especially in renal failure. It does not delay labour, which is why it has been popular in obstetrics.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.153 Q5, Opioids. Paper''s option c reads ''has synergistic effect with oxytocin in the uterus'', which is doubtful; reworded to the accepted statement that it does not oppose oxytocin. Repeated as p.156 Q18.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-6570bb653a', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'The following are true about opioid antagonists EXCEPT:', '["Have high affinity for mu receptors", "Can reverse opioid activity at mu, kappa and delta receptors", "Naloxone is a morphine derivative", "The duration of action of naloxone is 6-8 hours", "The duration of action of naltrexone is up to 48 hours"]'::jsonb, 'The duration of action of naloxone is 6-8 hours', '[]'::jsonb, 'Naloxone acts for only 1 to 2 hours after injection, shorter than most opioids, so patients can slip back into coma and need repeated doses or an infusion. Naltrexone is active orally, with a half-life of about 10 hours and a blocking effect lasting up to 48 hours.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.154 Q6, Opioids. Repeated as p.156 Q19; one copy kept.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-ba71062d96', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'The following are opioid partial agonists or mixed agonist-antagonists EXCEPT:', '["Nalbuphine", "Buprenorphine", "Tramadol", "Butorphanol", "Pentazocine"]'::jsonb, 'Tramadol', '[]'::jsonb, 'Tramadol is a weak full agonist at mu receptors (through its O-desmethyl metabolite) that also inhibits reuptake of serotonin and noradrenaline. Buprenorphine is a partial mu agonist, and nalbuphine, butorphanol and pentazocine are kappa agonists with weak or antagonist action at mu receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.155 Q12, Opioids. Stem widened from ''partial agonists'' to ''partial agonists or mixed agonist-antagonists''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-7278fe1aba', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'The following are true of methadone EXCEPT:', '["Tolerance and dependence develop much more slowly than with morphine", "Can be given intramuscularly and subcutaneously", "Oral bioavailability is higher than that of morphine", "Is a potent mu receptor agonist", "Half-life is 8-12 hours"]'::jsonb, 'Half-life is 8-12 hours', '[]'::jsonb, 'Methadone has a long and variable half-life of about 25 to 52 hours, which allows once-daily dosing in maintenance programmes but means it accumulates over the first days, with a risk of delayed respiratory depression. Its long action makes withdrawal slower in onset and milder than with morphine.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.155 Q13, Opioids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-acute-opioid-toxicity-ee16fc63ec', 'pharm-acute-opioid-toxicity', 'mcq', 'Identify the group of signs that suggests opioid poisoning:', '["Coma, mydriasis, tachypnoea", "Coma, hyperthermia, diarrhoea", "Coma, miosis, respiratory depression", "Tachypnoea, convulsions, lacrimation", "Hypertension, coma, hyperactivity"]'::jsonb, 'Coma, miosis, respiratory depression', '[]'::jsonb, 'The triad of coma, pinpoint pupils and slow, shallow breathing is characteristic of opioid overdose and is an indication for naloxone. Mydriasis, tachypnoea, lacrimation and diarrhoea are features of opioid withdrawal, the opposite state.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.155 Q14, Opioids. Near-identical question at p.158 Q34 dropped.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-fentanyl-and-congeners-levorphanol-and-b86d8b9e5e', 'pharm-fentanyl-and-congeners-levorphanol-and-congeners-pethidine-and-c', 'mcq', 'Which of the following opioid analgesics is about 80 to 100 times more potent than morphine as an analgesic?', '["Fentanyl", "Methadone", "Meperidine", "Pentazocine", "Propoxyphene"]'::jsonb, 'Fentanyl', '[]'::jsonb, 'Fentanyl is a highly lipid-soluble phenylpiperidine, roughly 80 to 100 times as potent as morphine, with rapid onset and short action after a single dose. Methadone is about equipotent with morphine, and pethidine, pentazocine and propoxyphene are weaker.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.159 Q38, Opioids. Stem widened from ''about 80 times'' to ''about 80 to 100 times'' (textbooks vary).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-63b17b7787', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'Mixed agonist-antagonist (or partial agonist) opioids include:', '["Butorphanol", "Buprenorphine", "Nalbuphine", "Pentazocine", "All of the above"]'::jsonb, 'All of the above', '[]'::jsonb, 'Butorphanol, nalbuphine and pentazocine are kappa agonists with antagonist or weak partial agonist action at mu receptors, and buprenorphine is a partial mu agonist and kappa antagonist. All show a ceiling to respiratory depression and can precipitate withdrawal in patients dependent on full agonists.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.159 Q41, Opioids. Buprenorphine is strictly a partial agonist rather than a mixed agonist-antagonist; stem widened to cover it. Human check advised.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anesthesia-classificat-6ec9e7272c', 'pharm-introduction-to-anesthesia-classification-and-mechanism-of-actio', 'mcq', 'Which is not a feature of Stage II of general anaesthesia?', '["Vomiting", "Amnesia", "Irregular respiratory rate", "Hypotension", "Loss of consciousness"]'::jsonb, 'Hypotension', '[]'::jsonb, 'Stage II is the stage of excitement: the patient has lost consciousness and is amnesic but shows delirium, irregular breathing, retching or vomiting, and sympathetic overactivity with tachycardia and a raised blood pressure. Hypotension belongs to the deeper planes of stage III and to stage IV, when the vasomotor centre is depressed.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.162 Q2, Anaesthesia: Grades') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anesthesia-classificat-04c44cc0c7', 'pharm-introduction-to-anesthesia-classification-and-mechanism-of-actio', 'mcq', 'Which drug is indicated for post-anaesthetic shivering?', '["Meperidine", "Methylphenidate", "Methotrexate", "Morphine", "Metoclopramide"]'::jsonb, 'Meperidine', '[]'::jsonb, 'Meperidine (pethidine) in small intravenous doses stops post-anaesthetic shivering, an effect attributed to its action on kappa opioid and alpha-2 receptors that lowers the shivering threshold. Morphine at equianalgesic doses is far less effective, so it is not the drug chosen for this purpose.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.162 Q3, Anaesthesia: Grades') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhalational-anesthetic-agents-beaf612c55', 'pharm-inhalational-anesthetic-agents', 'mcq', 'Which inhaled anaesthetic agent can cause hepatotoxicity?', '["Enflurane", "Halothane", "Neostigmine", "Nitrous oxide", "Flumazenil"]'::jsonb, 'Halothane', '[]'::jsonb, 'About 20% of halothane is metabolised in the liver to trifluoroacetylated products that can provoke immune-mediated hepatic necrosis (''halothane hepatitis''), especially after repeated exposure. Enflurane is metabolised far less (about 2%) and hepatitis with it is very rare; nitrous oxide is not hepatotoxic.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.162 Q1, Anaesthesia: Inhaled agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhalational-anesthetic-agents-e542704b52', 'pharm-inhalational-anesthetic-agents', 'mcq', 'Which of the following drugs is a volatile substance that is administered by inhalation?', '["Thiopental", "Halothane", "Alprazolam", "Buspirone", "Phenytoin"]'::jsonb, 'Halothane', '[]'::jsonb, 'Halothane is a halogenated hydrocarbon that is liquid at room temperature and is vaporised for delivery to the lungs as a general anaesthetic. Thiopental is also an anaesthetic but is a barbiturate given intravenously; the other options are oral or parenteral drugs with no anaesthetic use.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.162 Q2, Anaesthesia: Inhaled agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhalational-anesthetic-agents-b95e78cf52', 'pharm-inhalational-anesthetic-agents', 'mcq', 'Which statement about halothane is false?', '["It is eliminated via the lungs", "It is hepatotoxic", "It causes respiratory depression", "It causes hypertension", "It is not flammable"]'::jsonb, 'It causes hypertension', '[]'::jsonb, 'Halothane lowers blood pressure in a dose-dependent way by depressing myocardial contractility and slowing the heart. It is non-flammable, is mostly exhaled unchanged, depresses respiration and can cause hepatitis. Hypertension is therefore the false statement.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.163 Q5, Anaesthesia: Inhaled agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhalational-anesthetic-agents-0b28e50ead', 'pharm-inhalational-anesthetic-agents', 'mcq', 'Which of the following inhalation anaesthetics has the largest minimum alveolar concentration (MAC)?', '["Halothane", "Enflurane", "Isoflurane", "Nitrous oxide", "Sevoflurane"]'::jsonb, 'Nitrous oxide', '[]'::jsonb, 'MAC is inversely related to potency. Nitrous oxide is the least potent agent, with a MAC above 100%, so it cannot produce surgical anaesthesia on its own at atmospheric pressure. Halothane is the most potent of those listed, with a MAC of about 0.75%.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.163 Q7, Anaesthesia: Inhaled agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhalational-anesthetic-agents-78353a50e0', 'pharm-inhalational-anesthetic-agents', 'mcq', 'Repeated administration of which of the following anaesthetic agents is associated with a risk of liver damage?', '["Halothane", "Nitrous oxide", "Desflurane", "Thiopentone", "Ketamine"]'::jsonb, 'Halothane', '[]'::jsonb, 'Halothane hepatitis is an immune reaction to liver proteins modified by the reactive metabolite trifluoroacetyl chloride, and the risk rises sharply with repeated exposure at short intervals. Desflurane undergoes almost no metabolism (about 0.02%), so it carries a negligible risk.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.163 Q8, Anaesthesia: Inhaled agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhalational-anesthetic-agents-8957fd8fc0', 'pharm-inhalational-anesthetic-agents', 'mcq', 'Cardiovascular effects of halothane include all of the following EXCEPT:', '["Bradycardia", "Vasodilatation", "Hypotension", "Positive inotropic effect", "Cardiac arrhythmias"]'::jsonb, 'Positive inotropic effect', '[]'::jsonb, 'Halothane is a direct myocardial depressant, so it has a negative, not a positive, inotropic effect. It also slows the heart, lowers blood pressure and sensitises the myocardium to catecholamines, which predisposes to ventricular arrhythmias.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.164 Q9, Anaesthesia: Inhaled agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhalational-anesthetic-agents-8f64a13893', 'pharm-inhalational-anesthetic-agents', 'mcq', 'Halothane produces all of the following EXCEPT:', '["Bronchiolar dilatation", "Uterine relaxation", "Powerful analgesic action", "Cardiac arrhythmias", "Inadequate skeletal muscle relaxation"]'::jsonb, 'Powerful analgesic action', '[]'::jsonb, 'Halothane is a potent anaesthetic but a weak analgesic, so it is usually given with nitrous oxide or an opioid. It relaxes bronchial and uterine smooth muscle, gives only modest skeletal muscle relaxation and can provoke arrhythmias by sensitising the heart to catecholamines.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.164 Q10, Anaesthesia: Inhaled agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhalational-anesthetic-agents-f69ff40502', 'pharm-inhalational-anesthetic-agents', 'mcq', 'Diffusion hypoxia is most likely during recovery from anaesthesia with:', '["Halothane", "Enflurane", "Desflurane", "Isoflurane", "Nitrous oxide"]'::jsonb, 'Nitrous oxide', '[]'::jsonb, 'Nitrous oxide is given in high concentrations and is poorly soluble in blood, so when it is stopped a large volume diffuses rapidly from blood into the alveoli and dilutes alveolar oxygen. Giving 100% oxygen for a few minutes prevents this. The volatile agents are used at concentrations too low to do the same.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.164 Q11, Anaesthesia: Inhaled agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhalational-anesthetic-agents-2197be29a3', 'pharm-inhalational-anesthetic-agents', 'mcq', 'Advantages of nitrous oxide as a general anaesthetic include all of the following EXCEPT:', '["Rapid induction and recovery", "Powerful skeletal muscle relaxant", "Powerful analgesic", "Non-irritant to the respiratory tract", "Non-flammable and non-explosive"]'::jsonb, 'Powerful skeletal muscle relaxant', '[]'::jsonb, 'Nitrous oxide gives no skeletal muscle relaxation, and it is too weak (MAC above 100%) to be a sole anaesthetic. Its strengths are good analgesia, rapid onset and recovery because of its low blood solubility, and a pleasant non-irritant smell.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.164 Q12, Anaesthesia: Inhaled agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-anesthetic-agents-53655cb4c5', 'pharm-intravenous-anesthetic-agents', 'mcq', 'Which intravenous anaesthetic agent is associated with less postoperative vomiting and a quick recovery time?', '["Etomidate", "Remifentanil", "Thiopental", "Enflurane", "Propofol"]'::jsonb, 'Propofol', '[]'::jsonb, 'Propofol has an antiemetic action and is cleared rapidly, so patients wake quickly and clear-headed with little nausea, which makes it the standard agent for day-case surgery. Etomidate also wears off fast but causes a high incidence of postoperative nausea and vomiting.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.164 Q1, Anaesthesia: IV agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-anesthetic-agents-d7198c825f', 'pharm-intravenous-anesthetic-agents', 'mcq', 'Use of which agent is associated with a high incidence of disorientation, sensory and perceptual illusions, and vivid dreams during recovery from anaesthesia?', '["Diazepam", "Fentanyl", "Ketamine", "Midazolam", "Thiopental"]'::jsonb, 'Ketamine', '[]'::jsonb, 'Ketamine, an NMDA receptor antagonist, produces dissociative anaesthesia and is followed in many adults by emergence phenomena: vivid dreams, hallucinations and disorientation. A benzodiazepine such as midazolam or diazepam is given with it to reduce these reactions rather than causing them.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.165 Q2, Anaesthesia: IV agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-anesthetic-agents-d6a199d2e6', 'pharm-intravenous-anesthetic-agents', 'mcq', 'Which is not an effect of thiopental?', '["Anticonvulsant", "Hypotension", "Tachycardia", "Increased intracranial pressure", "Respiratory depression"]'::jsonb, 'Increased intracranial pressure', '[]'::jsonb, 'Thiopental reduces cerebral metabolism and cerebral blood flow, so it lowers intracranial pressure and was valued in neurosurgery. It is anticonvulsant, depresses respiration and drops blood pressure by venodilatation and myocardial depression, with a compensatory rise in heart rate.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.165 Q4, Anaesthesia: IV agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-anesthetic-agents-1f4e926fb0', 'pharm-intravenous-anesthetic-agents', 'mcq', 'Which is not an effect of ketamine?', '["Bronchodilatation", "Bradycardia", "Analgesia", "Hypertension", "Dissociative anaesthesia"]'::jsonb, 'Bradycardia', '[]'::jsonb, 'Ketamine stimulates the sympathetic nervous system centrally and inhibits noradrenaline reuptake, so heart rate, blood pressure and cardiac output rise. It is also a bronchodilator and a strong analgesic. Bradycardia is therefore not expected.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.165 Q5, Anaesthesia: IV agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-anesthetic-agents-1d699abdac', 'pharm-intravenous-anesthetic-agents', 'mcq', 'Which statement about thiopental sodium is false?', '["It decreases brain metabolism", "It is not metabolised in the body", "Its use is safe in brain surgery", "It has a rapid onset of action", "It decreases blood pressure"]'::jsonb, 'It is not metabolised in the body', '[]'::jsonb, 'Thiopental is extensively metabolised in the liver, with less than 1% excreted unchanged. Its brief action after a single dose is due to redistribution from brain to muscle and fat, not to metabolism or excretion. It lowers cerebral metabolism and intracranial pressure, and causes hypotension.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.165 Q6, Anaesthesia: IV agents. Paper''s option d ''Has a very short half life'' is also false (elimination half-life is several hours); replaced it with ''It has a rapid onset of action'' so only one option is false.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-anesthetic-agents-0c63b53114', 'pharm-intravenous-anesthetic-agents', 'mcq', 'All of the following drugs are useful as intravenous anaesthetics EXCEPT:', '["Desflurane", "Propofol", "Midazolam", "Droperidol / fentanyl combination", "Ketamine"]'::jsonb, 'Desflurane', '[]'::jsonb, 'Desflurane is a volatile halogenated ether delivered by inhalation through a special heated vaporiser. Propofol, midazolam and ketamine are intravenous agents, and droperidol with fentanyl is the classic intravenous combination for neuroleptanalgesia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.165 Q8, Anaesthesia: IV agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-anesthetic-agents-623533ed2e', 'pharm-intravenous-anesthetic-agents', 'mcq', 'Correct statements concerning thiopental sodium include all of the following EXCEPT that:', '["It is an ultrashort-acting barbiturate", "It is used as an intravenous anaesthetic", "It is a poor analgesic", "It is absolutely contraindicated in acute intermittent porphyria", "It has a short duration of action due to renal excretion"]'::jsonb, 'It has a short duration of action due to renal excretion', '[]'::jsonb, 'The short action of a single dose of thiopental is due to redistribution from the highly perfused brain to muscle and then fat. It is eliminated slowly by hepatic metabolism, not by renal excretion. Barbiturates induce ALA synthase, hence the contraindication in porphyria.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.166 Q9, Anaesthesia: IV agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-anesthetic-agents-1b4c3c0f5c', 'pharm-intravenous-anesthetic-agents', 'mcq', 'Dissociative anaesthesia is produced by intravenous or intramuscular injection of which of the following drugs?', '["Droperidol / fentanyl combination", "Midazolam", "Ketamine", "Etomidate", "Propofol"]'::jsonb, 'Ketamine', '[]'::jsonb, 'Ketamine blocks NMDA glutamate receptors and produces a state in which the patient appears awake but is detached from the surroundings, with profound analgesia and amnesia. Droperidol with fentanyl produces neuroleptanalgesia, a different state of calm indifference with analgesia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.166 Q10, Anaesthesia: IV agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-anesthetic-agents-4242c93f72', 'pharm-intravenous-anesthetic-agents', 'mcq', 'Ketamine produces all of the following EXCEPT:', '["Marked analgesia and amnesia", "Increased skeletal muscle tone", "Increased intracranial pressure", "Decreased arterial blood pressure and heart rate", "Vivid dreams during recovery"]'::jsonb, 'Decreased arterial blood pressure and heart rate', '[]'::jsonb, 'Ketamine is the only intravenous anaesthetic that stimulates the circulation: blood pressure and heart rate rise through central sympathetic activation. It also increases muscle tone, cerebral blood flow and intracranial pressure, and causes emergence dreams.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.166 Q11, Anaesthesia: IV agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-preanesthetic-agent-d39f7ae06a', 'pharm-preanesthetic-agent', 'mcq', 'Which is not an aim of preanaesthetic medication?', '["Supplement analgesia", "Increase vagal stimulation", "Decrease gastric acidity", "Amnesia for pre- and postoperative events", "Relief of anxiety"]'::jsonb, 'Increase vagal stimulation', '[]'::jsonb, 'Premedication aims to reduce vagal activity, not increase it: antimuscarinics such as atropine or glycopyrrolate prevent reflex bradycardia and dry secretions. The other aims are anxiolysis and amnesia (benzodiazepines), added analgesia (opioids) and a lower risk of acid aspiration (H2 blockers, antacids).', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.166 Q1, Anaesthesia: Pre-anaesthetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-local-anesthetic-agents-fc41af135c', 'pharm-local-anesthetic-agents', 'mcq', 'All of the following are true about local anaesthetic agents EXCEPT:', '["Pain sensation is blocked before motor nerves", "Bupivacaine is cardiotoxic", "Lignocaine blocks both sodium and calcium ion channels", "Sedation is a sign of toxicity", "Prilocaine can induce methaemoglobinaemia"]'::jsonb, 'Lignocaine blocks both sodium and calcium ion channels', '[]'::jsonb, 'Local anaesthetics act by blocking voltage-gated sodium channels from the inside of the axon, which stops action potential conduction. Small pain fibres are blocked before large motor fibres, drowsiness is an early sign of systemic toxicity, and prilocaine''s metabolite o-toluidine oxidises haemoglobin.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.166 Q1, Anaesthesia: Local anaesthetics. Intended false statement is c (mechanism is sodium channel block), but at high concentrations local anaesthetics do have some effect on other channels, so a human should confirm.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-local-anesthetic-agents-0fd6c6d745', 'pharm-local-anesthetic-agents', 'mcq', 'Which local anaesthetic has the highest risk of cardiotoxicity?', '["Bupivacaine", "Chloroprocaine", "Lignocaine", "Cocaine", "Benzocaine"]'::jsonb, 'Bupivacaine', '[]'::jsonb, 'Bupivacaine binds avidly to cardiac sodium channels and dissociates slowly, so accidental intravenous injection can cause refractory ventricular arrhythmias and cardiovascular collapse. Lignocaine dissociates quickly from the channel and is much safer, to the point of being used as an antiarrhythmic.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.167 Q2, Anaesthesia: Local anaesthetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-local-anesthetic-agents-c4e335d012', 'pharm-local-anesthetic-agents', 'mcq', 'All of the following are true of local anaesthetics EXCEPT:', '["They are bound to alpha-1 acid glycoprotein", "Cocaine causes vasoconstriction", "They cause drowsiness", "Pain sensation disappears first", "Lignocaine is metabolised by blood esterases"]'::jsonb, 'Lignocaine is metabolised by blood esterases', '[]'::jsonb, 'Lignocaine is an amide and is metabolised in the liver by cytochrome P450 enzymes. It is the ester local anaesthetics (procaine, tetracaine, chloroprocaine) that are hydrolysed by plasma pseudocholinesterase. Cocaine is the only local anaesthetic that vasoconstricts, because it blocks noradrenaline reuptake.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.167 Q3, Anaesthesia: Local anaesthetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-local-anesthetic-agents-012d45a5d3', 'pharm-local-anesthetic-agents', 'mcq', 'Which statement is true of lignocaine?', '["It is an ester", "It has a slow onset of action", "Medical procedures are performed at stage 3 of anaesthesia", "It is metabolised in the liver", "It is 90% bound to albumin in plasma"]'::jsonb, 'It is metabolised in the liver', '[]'::jsonb, 'Lignocaine is an amide local anaesthetic that is dealkylated in the liver by CYP enzymes, so its clearance falls in liver disease and heart failure. It acts quickly, and in plasma it is about 65% bound, mainly to alpha-1 acid glycoprotein rather than albumin.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.167 Q4, Anaesthesia: Local anaesthetics. Paper''s option b ''Rapidly acting agent'' is also true; changed it to ''It has a slow onset of action'' so only one option is true.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-local-anesthetic-agents-b400b15a2c', 'pharm-local-anesthetic-agents', 'mcq', 'All of the following are true of lignocaine EXCEPT:', '["It is bound to alpha-1 acid glycoprotein", "It is excreted mainly in the urine", "It is metabolised in the liver", "Sodium bicarbonate increases its ionisation in urine", "It is administered parenterally"]'::jsonb, 'Sodium bicarbonate increases its ionisation in urine', '[]'::jsonb, 'Lignocaine is a weak base, so alkalinising the urine with sodium bicarbonate decreases its ionisation and favours reabsorption; acid urine would trap it. It is metabolised in the liver and the metabolites are excreted in urine.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.167 Q5, Anaesthesia: Local anaesthetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-local-anesthetic-agents-53f293ca35', 'pharm-local-anesthetic-agents', 'mcq', 'The most important effect of inadvertent intravenous administration of a large dose of an amide local anaesthetic is:', '["Bronchoconstriction", "Seizures", "Hepatic damage", "Renal failure", "Tachycardia"]'::jsonb, 'Seizures', '[]'::jsonb, 'High plasma levels of a local anaesthetic first depress inhibitory cortical pathways, giving circumoral numbness, tinnitus, tremor and then generalised convulsions, followed by coma and cardiovascular depression. Cardiac toxicity produces bradycardia and conduction block rather than tachycardia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.167 Q6, Anaesthesia: Local anaesthetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-local-anesthetic-agents-e6d1de4fa1', 'pharm-local-anesthetic-agents', 'mcq', 'The injection of a local anaesthetic directly into tissue without taking into consideration the course of cutaneous nerves is referred to as:', '["Nerve block anaesthesia", "Infiltration anaesthesia", "Bier''s block", "Epidural anaesthesia", "Topical anaesthesia"]'::jsonb, 'Infiltration anaesthesia', '[]'::jsonb, 'In infiltration anaesthesia the solution is injected into the tissue to be operated on and blocks the fine nerve endings there. A nerve block, by contrast, places the drug beside a named nerve trunk to anaesthetise its whole territory, and Bier''s block is intravenous regional anaesthesia under a tourniquet.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.167 Q7, Anaesthesia: Local anaesthetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-local-anesthetic-agents-1c35542528', 'pharm-local-anesthetic-agents', 'mcq', 'Which of the following local anaesthetics is an amide?', '["Cocaine", "Procaine", "Lidocaine", "Tetracaine", "Benzocaine"]'::jsonb, 'Lidocaine', '[]'::jsonb, 'Lidocaine has an amide link between its aromatic ring and amine group, so it is stable in plasma and is metabolised in the liver. A handy rule: amides have two letter i''s in the name (lidocaine, bupivacaine, prilocaine), whereas esters such as procaine and cocaine have one.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.168 Q8, Anaesthesia: Local anaesthetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-local-anesthetic-agents-16b7e57de2', 'pharm-local-anesthetic-agents', 'mcq', 'Which of the following is a local anaesthetic of very low solubility that is useful only for surface anaesthesia?', '["Lignocaine hydrochloride", "Benzocaine", "Bupivacaine hydrochloride", "Mepivacaine hydrochloride", "Prilocaine hydrochloride"]'::jsonb, 'Benzocaine', '[]'::jsonb, 'Benzocaine lacks the terminal amine group, so it is not ionised and is almost insoluble in water. It cannot be injected and is used only on mucous membranes and skin, as lozenges, gels and sprays. The hydrochloride salts listed are water soluble and injectable.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.168 Q9, Anaesthesia: Local anaesthetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-neuromuscular-blocking-agents-spasmoly-02e90e9ed4', 'pharm-neuromuscular-blocking-agents-spasmolytics', 'mcq', 'All of the following are true about succinylcholine EXCEPT:', '["Its duration of action is 5 to 10 minutes", "Its action is mainly terminated by metabolism by cholinesterase at the motor end plate", "Its major metabolite is succinylmonocholine", "The higher the dibucaine number, the safer it is to use", "It is less potent than d-tubocurarine"]'::jsonb, 'Its action is mainly terminated by metabolism by cholinesterase at the motor end plate', '[]'::jsonb, 'Succinylcholine is not broken down by acetylcholinesterase at the end plate. It is hydrolysed in plasma by butyrylcholinesterase (pseudocholinesterase), and its action at the junction ends when it diffuses away. A low dibucaine number indicates atypical enzyme and a risk of prolonged apnoea.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.168 Q1, Anaesthesia: Muscle drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-neuromuscular-blocking-agents-spasmoly-2d83816d7c', 'pharm-neuromuscular-blocking-agents-spasmolytics', 'mcq', 'All of the following are true about dantrolene EXCEPT:', '["It acts by interfering with excitation-contraction coupling in muscle fibres", "Cardiac muscle is relaxed to the same extent as skeletal muscle", "It may cause hepatitis", "Motor units that contract rapidly are more sensitive to its action", "Oral absorption is about one third of the dose"]'::jsonb, 'Cardiac muscle is relaxed to the same extent as skeletal muscle', '[]'::jsonb, 'Dantrolene blocks the RyR1 ryanodine receptor, which releases calcium from the sarcoplasmic reticulum of skeletal muscle. Cardiac muscle uses a different isoform (RyR2), so it is hardly affected. Hepatotoxicity is the most serious adverse effect.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.168 Q2, Anaesthesia: Muscle drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-neuromuscular-blocking-agents-spasmoly-859aa651b1', 'pharm-neuromuscular-blocking-agents-spasmolytics', 'mcq', 'The following neuromuscular blockers are safe to use in liver disease EXCEPT:', '["Mivacurium", "Atracurium", "Vecuronium", "Succinylcholine", "Cisatracurium"]'::jsonb, 'Vecuronium', '[]'::jsonb, 'Vecuronium is a steroidal relaxant that depends mainly on hepatic uptake and biliary excretion, so its action is prolonged in liver disease. Atracurium and cisatracurium undergo spontaneous Hofmann elimination in plasma, independent of the liver, and are the relaxants of choice in hepatic failure.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.168 Q4, Anaesthesia: Muscle drugs. Mivacurium and succinylcholine are hydrolysed by plasma cholinesterase, which is made in the liver, so their action can also be prolonged in severe liver disease; vecuronium is the best single answer but two options could be argued.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-neuromuscular-blocking-agents-spasmoly-427b12aa30', 'pharm-neuromuscular-blocking-agents-spasmolytics', 'mcq', 'Which antibiotics may enhance the neuromuscular blockade caused by pancuronium?', '["Nitrofurantoin", "Gentamicin and streptomycin", "Cefaclor", "Erythromycin", "Trimethoprim"]'::jsonb, 'Gentamicin and streptomycin', '[]'::jsonb, 'Aminoglycosides inhibit presynaptic calcium entry and so reduce acetylcholine release at the neuromuscular junction, and they also lower postjunctional sensitivity. This adds to the block produced by non-depolarising relaxants and can cause prolonged postoperative paralysis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.169 Q5, Anaesthesia: Muscle drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-neuromuscular-blocking-agents-spasmoly-4844b5b0b8', 'pharm-neuromuscular-blocking-agents-spasmolytics', 'mcq', 'Which of the following drugs is a competitive antagonist at the nicotinic cholinoceptor of the neuromuscular junction?', '["Succinylcholine", "Atracurium", "Mecamylamine", "Echothiophate", "Dantrolene"]'::jsonb, 'Atracurium', '[]'::jsonb, 'Atracurium is a non-depolarising blocker that competes with acetylcholine for the nicotinic (Nm) receptor on the end plate. Succinylcholine is an agonist that causes depolarising block, and mecamylamine blocks nicotinic receptors in autonomic ganglia rather than at muscle.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.169 Q6, Anaesthesia: Muscle drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-neuromuscular-blocking-agents-spasmoly-4698b5f7c4', 'pharm-neuromuscular-blocking-agents-spasmolytics', 'mcq', 'All of the following are pharmacological actions of tubocurarine EXCEPT:', '["Competitive (non-depolarising) neuromuscular blocking action", "Histamine release", "No effect on the CNS in humans", "Fall in blood pressure", "Blockade of muscarinic receptors in the heart"]'::jsonb, 'Blockade of muscarinic receptors in the heart', '[]'::jsonb, 'Tubocurarine lowers blood pressure by releasing histamine and blocking autonomic ganglia, and as a quaternary compound it does not enter the brain. Blocking cardiac muscarinic receptors, which causes tachycardia, is a property of pancuronium and gallamine, not tubocurarine.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.169 Q7, Anaesthesia: Muscle drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-neuromuscular-blocking-agents-spasmoly-6ec0b212fc', 'pharm-neuromuscular-blocking-agents-spasmolytics', 'mcq', 'Which of the following is the last to be paralysed by tubocurarine?', '["Eye muscles", "Small muscles of the face", "Muscles of the limbs", "Intercostal muscles", "Diaphragm"]'::jsonb, 'Diaphragm', '[]'::jsonb, 'Non-depolarising blockers paralyse small, rapidly moving muscles of the eyes and face first, then limbs and trunk, then the intercostals and finally the diaphragm. Recovery occurs in the reverse order, so the diaphragm is the first to recover.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.169 Q8, Anaesthesia: Muscle drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-neuromuscular-blocking-agents-spasmoly-a0a0d21a43', 'pharm-neuromuscular-blocking-agents-spasmolytics', 'mcq', 'Competitive antagonists at neuromuscular junction nicotinic cholinoceptors include all of the following EXCEPT:', '["Pancuronium", "Alcuronium", "Vecuronium", "Suxamethonium", "Atracurium"]'::jsonb, 'Suxamethonium', '[]'::jsonb, 'Suxamethonium (succinylcholine) is two acetylcholine molecules joined together: it activates the nicotinic receptor and produces a persistent depolarisation, seen as fasciculations followed by flaccid paralysis. The others are non-depolarising competitive antagonists.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.169 Q9, Anaesthesia: Muscle drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-neuromuscular-blocking-agents-spasmoly-4d2dd9939f', 'pharm-neuromuscular-blocking-agents-spasmolytics', 'mcq', 'Competitive neuromuscular blockers can be antagonised by:', '["Pancuronium", "Gallamine", "Neostigmine", "Pilocarpine", "Bethanechol"]'::jsonb, 'Neostigmine', '[]'::jsonb, 'Neostigmine inhibits acetylcholinesterase, so acetylcholine accumulates at the end plate and outcompetes the non-depolarising blocker. It is given with atropine or glycopyrrolate to prevent muscarinic effects. Pilocarpine and bethanechol are muscarinic agonists with no action at the neuromuscular junction.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.169 Q10, Anaesthesia: Muscle drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-neuromuscular-blocking-agents-spasmoly-cf6ee9bef7', 'pharm-neuromuscular-blocking-agents-spasmolytics', 'mcq', 'Neuromuscular blockade from non-depolarising muscle relaxants is augmented by all of the following EXCEPT:', '["Edrophonium", "Halothane", "Enflurane", "Isoflurane", "Streptomycin"]'::jsonb, 'Edrophonium', '[]'::jsonb, 'Edrophonium is a short-acting anticholinesterase that raises acetylcholine at the end plate and so reverses a competitive block. Volatile anaesthetics and aminoglycosides potentiate the block, so relaxant doses must be reduced when they are used.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.170 Q11, Anaesthesia: Muscle drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-neuromuscular-blocking-agents-spasmoly-203168631a', 'pharm-neuromuscular-blocking-agents-spasmolytics', 'mcq', 'All of the following statements concerning succinylcholine are correct EXCEPT that it:', '["Is a depolarising neuromuscular blocker", "Produces relaxation preceded by muscle fasciculations", "Has a short duration of action", "Decreases intraocular pressure", "May cause malignant hyperthermia in patients receiving halothane"]'::jsonb, 'Decreases intraocular pressure', '[]'::jsonb, 'Succinylcholine raises intraocular pressure for several minutes, probably through contraction of the extraocular muscles, so it is avoided in penetrating eye injuries. Its other features are true: depolarising block with fasciculations, action lasting 5 to 10 minutes, and triggering of malignant hyperthermia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.170 Q12, Anaesthesia: Muscle drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-neuromuscular-blocking-agents-spasmoly-a4a49fe705', 'pharm-neuromuscular-blocking-agents-spasmolytics', 'mcq', 'All of the following are side effects of succinylcholine EXCEPT:', '["Apnoea", "Postoperative muscle pain", "Increased intraocular pressure", "Malignant hyperthermia", "Hypokalaemia"]'::jsonb, 'Hypokalaemia', '[]'::jsonb, 'Depolarisation of the end plate lets potassium leave muscle cells, so succinylcholine causes hyperkalaemia, which can be fatal in patients with burns, denervation or major trauma. Muscle pains, raised intraocular pressure, prolonged apnoea and malignant hyperthermia are all recognised effects.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.170 Q13, Anaesthesia: Muscle drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-neuromuscular-blocking-agents-spasmoly-6f5164a190', 'pharm-neuromuscular-blocking-agents-spasmolytics', 'mcq', 'Which drug produces skeletal muscle relaxation by stimulating alpha-2 receptors?', '["Diazepam", "Clonazepam", "Tizanidine", "Baclofen", "Dantrolene"]'::jsonb, 'Tizanidine', '[]'::jsonb, 'Tizanidine is a clonidine congener that stimulates alpha-2 adrenoceptors in the spinal cord, enhancing presynaptic inhibition of motor neurones and reducing spasticity. Baclofen acts on GABA-B receptors, the benzodiazepines on GABA-A receptors, and dantrolene directly on muscle.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.170 Q14, Anaesthesia: Muscle drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-neuromuscular-blocking-agents-spasmoly-ce7bba7970', 'pharm-neuromuscular-blocking-agents-spasmolytics', 'mcq', 'The release of calcium from the sarcoplasmic reticulum of skeletal muscle is prevented by:', '["Dantrolene", "Tubocurarine", "Baclofen", "Succinylcholine", "Pyridostigmine"]'::jsonb, 'Dantrolene', '[]'::jsonb, 'Dantrolene binds the ryanodine receptor (RyR1) channel and stops calcium leaving the sarcoplasmic reticulum, uncoupling excitation from contraction. This is why it is the specific treatment for malignant hyperthermia. Tubocurarine and succinylcholine act at the nicotinic receptor, upstream of calcium release.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.170 Q15, Anaesthesia: Muscle drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-renal-pharmacology-dru-d57316360e', 'pharm-introduction-to-renal-pharmacology-drugs-affecting-renal-water-c', 'mcq', 'Indications for the use of tolvaptan include the following EXCEPT:', '["Autosomal dominant polycystic kidney disease", "Hypervolaemic hyponatraemia", "Euvolaemic hyponatraemia", "Nephrogenic diabetes insipidus", "Syndrome of inappropriate antidiuretic hormone secretion"]'::jsonb, 'Nephrogenic diabetes insipidus', '[]'::jsonb, 'Tolvaptan blocks V2 receptors in the collecting duct and causes loss of free water, which corrects dilutional hyponatraemia and slows cyst growth in polycystic kidney disease. In nephrogenic diabetes insipidus the kidney already fails to respond to ADH, so a V2 antagonist would be useless and harmful.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.171 Q1, Renal: ADH antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-renal-pharmacology-dru-04ce8be2cb', 'pharm-introduction-to-renal-pharmacology-drugs-affecting-renal-water-c', 'mcq', 'Which one of the following is not an antagonist of vasopressin?', '["Lixivaptan", "Satavaptan", "Saxagliptin", "Lithium", "Demeclocycline"]'::jsonb, 'Saxagliptin', '[]'::jsonb, 'Saxagliptin is a DPP-4 inhibitor used in type 2 diabetes. The ''vaptans'' block V2 receptors directly, while lithium and demeclocycline interfere with ADH signalling in the collecting duct beyond the receptor, which is why both can cause nephrogenic diabetes insipidus.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.171 Q2, Renal: ADH antagonists') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-e7be9baddc', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'A drug that is useful in preventing high-altitude sickness is:', '["Amiloride", "Acetazolamide", "Ethacrynic acid", "Demeclocycline", "Desmopressin"]'::jsonb, 'Acetazolamide', '[]'::jsonb, 'Acetazolamide inhibits carbonic anhydrase, causing bicarbonate loss and a mild metabolic acidosis that stimulates ventilation and offsets the respiratory alkalosis of altitude. It also reduces CSF formation. None of the other diuretics produces this acidosis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.171 Q1, Renal: Carbonic anhydrase inhibitors') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-9b2b244c5f', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Clinical indications for acetazolamide include the following EXCEPT:', '["Severe metabolic alkalosis", "Calcium stones", "Acute mountain sickness", "Glaucoma", "Cystinuria"]'::jsonb, 'Calcium stones', '[]'::jsonb, 'Acetazolamide makes the urine alkaline and increases phosphate and calcium excretion, which promotes calcium phosphate stones, so it is not used for them. The same alkaline urine helps dissolve cystine and uric acid, and the drug also treats glaucoma, mountain sickness and metabolic alkalosis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.171 Q2, Renal: Carbonic anhydrase inhibitors') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-7478618725', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Effects of carbonic anhydrase inhibitors include the following EXCEPT:', '["Decrease in urinary pH", "Development of metabolic acidosis", "Increased phosphate excretion", "Increased afferent arteriolar resistance", "Decreased formation of aqueous humour"]'::jsonb, 'Decrease in urinary pH', '[]'::jsonb, 'Blocking carbonic anhydrase in the proximal tubule prevents bicarbonate reabsorption, so the urine becomes alkaline (pH rises) while the blood becomes acidotic. The extra solute reaching the macula densa triggers tubuloglomerular feedback and afferent constriction.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.171 Q3, Renal: Carbonic anhydrase inhibitors') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-8bf65601e1', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Acetazolamide increases urinary excretion of all of the following EXCEPT:', '["Sodium", "Potassium", "Bicarbonate", "Chloride", "Water"]'::jsonb, 'Chloride', '[]'::jsonb, 'Acetazolamide causes sodium to be lost with bicarbonate rather than with chloride, so chloride is retained and a hyperchloraemic metabolic acidosis develops. Potassium loss rises because more sodium and bicarbonate reach the collecting duct.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.171 Q4, Renal: Carbonic anhydrase inhibitors') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-3d076c5e3c', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Acidification of urine can be achieved by:', '["Sodium bicarbonate", "Potassium citrate", "Sodium citrate", "Ammonium chloride", "Acetazolamide"]'::jsonb, 'Ammonium chloride', '[]'::jsonb, 'Ammonium chloride is converted in the liver to urea with release of hydrogen and chloride ions, giving an acid load that is excreted in the urine. Bicarbonate, citrates (metabolised to bicarbonate) and acetazolamide all make the urine alkaline.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.172 Q5, Renal: Carbonic anhydrase inhibitors') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-3c0259b7be', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Which of the following drugs can cause hyperchloraemic metabolic acidosis?', '["Ethacrynic acid", "Hydrochlorothiazide", "Acetazolamide", "Mannitol", "Theophylline"]'::jsonb, 'Acetazolamide', '[]'::jsonb, 'Acetazolamide wastes bicarbonate in the urine while chloride is retained, producing a normal anion gap (hyperchloraemic) acidosis. Loop diuretics such as ethacrynic acid and the thiazides do the opposite, causing hypochloraemic metabolic alkalosis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.172 Q6, Renal: Carbonic anhydrase inhibitors') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-diuretics-osmotic-diur-13001d869e', 'pharm-introduction-to-diuretics-osmotic-diuretics', 'mcq', 'Which of the following diuretics would be most useful in the acute treatment of a comatose patient with brain injury and cerebral oedema?', '["Furosemide", "Acetazolamide", "Ethacrynic acid", "Amiloride", "Mannitol"]'::jsonb, 'Mannitol', '[]'::jsonb, 'Intravenous mannitol stays in the extracellular space and raises plasma osmolality, drawing water out of brain tissue and lowering intracranial pressure within minutes. Furosemide removes salt and water from the circulation but does not create this osmotic gradient across the blood-brain barrier.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.172 Q1, Renal: Osmotic diuretics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-diuretics-osmotic-diur-fa34d82ae4', 'pharm-introduction-to-diuretics-osmotic-diuretics', 'mcq', 'Which statement regarding mannitol is false?', '["It is an aquaretic", "It is well absorbed from the gastrointestinal tract", "It is not metabolised", "It is useful in the reduction of intracranial pressure after head injury", "It may cause hypernatraemia"]'::jsonb, 'It is well absorbed from the gastrointestinal tract', '[]'::jsonb, 'Mannitol is poorly absorbed from the gut, where it would act as an osmotic laxative, so it must be given intravenously. It is filtered but not reabsorbed or metabolised, and because it removes more water than sodium it can cause hypernatraemia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.172 Q2, Renal: Osmotic diuretics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-diuretics-osmotic-diur-3d2392cdc2', 'pharm-introduction-to-diuretics-osmotic-diuretics', 'mcq', 'Which of the following is an aquaretic agent?', '["Acetazolamide", "Mannitol", "Triamterene", "Furosemide", "Hydrochlorothiazide"]'::jsonb, 'Mannitol', '[]'::jsonb, 'An aquaretic increases the excretion of water more than that of sodium. Mannitol holds water in the tubular lumen by osmosis, so the urine contains relatively little sodium. The other drugs are saluretics: they act by blocking sodium reabsorption.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.172 Q3, Renal: Osmotic diuretics. ''Aquaretic'' is more often used for vasopressin antagonists (vaptans); among these options only mannitol fits.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-diuretics-osmotic-diur-928fc3657f', 'pharm-introduction-to-diuretics-osmotic-diuretics', 'mcq', 'Mannitol is used in the treatment of:', '["Acute pulmonary oedema", "Hyperkalaemia", "Acutely raised intracranial or intraocular pressure", "Primary or secondary hyperaldosteronism", "Idiopathic hypercalciuria"]'::jsonb, 'Acutely raised intracranial or intraocular pressure', '[]'::jsonb, 'By raising plasma osmolality, mannitol pulls water out of the brain and the eye. It is contraindicated in pulmonary oedema and heart failure because it first expands the extracellular volume and can worsen the congestion.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.172 Q4, Renal: Osmotic diuretics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-c0f3ea738a', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Which of the following is an important effect of chronic therapy with loop diuretics?', '["Ototoxicity", "Elevation of blood pressure", "Decreased urinary excretion of calcium", "Metabolic acidosis", "Elevation of pulmonary vascular pressure"]'::jsonb, 'Ototoxicity', '[]'::jsonb, 'Loop diuretics inhibit the NKCC transporter in the stria vascularis as well as in the kidney, and can cause dose-related hearing loss, especially with aminoglycosides or renal failure. They increase calcium excretion and cause metabolic alkalosis, the opposite of two of the distractors.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.173 Q1, Renal: Loop diuretics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-ab6c3ed309', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Which of the following diuretics is useful in advanced renal failure?', '["Mannitol", "Hydrochlorothiazide", "Spironolactone", "None of the above", "Torsemide"]'::jsonb, 'Torsemide', '[]'::jsonb, 'Loop diuretics such as torsemide and furosemide have a high ceiling and still work when the glomerular filtration rate is very low, provided the dose is increased. Thiazides lose their effect below a GFR of about 30 mL/min, and spironolactone risks dangerous hyperkalaemia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.173 Q2, Renal: Loop diuretics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-517338444e', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Which of the following diuretics is useful in the treatment of acute pulmonary oedema?', '["Frusemide", "Hydrochlorothiazide", "Spironolactone", "Triamterene", "Acetazolamide"]'::jsonb, 'Frusemide', '[]'::jsonb, 'Intravenous frusemide causes venodilatation within minutes, lowering preload before the diuresis even begins, and then removes fluid rapidly and powerfully. Thiazides and potassium-sparing diuretics are too weak and too slow for this emergency.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.173 Q4, Renal: Loop diuretics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-931ff00b0f', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Adverse effects of furosemide include all of the following EXCEPT:', '["Hypercalcaemia", "Hyperlipidaemia", "Hypokalaemia", "Ototoxicity", "Hypotension and dehydration"]'::jsonb, 'Hypercalcaemia', '[]'::jsonb, 'Loop diuretics abolish the lumen-positive potential in the thick ascending limb that drives paracellular calcium and magnesium reabsorption, so they increase calcium excretion; this is why they are used to treat hypercalcaemia. Hypercalcaemia is a feature of thiazides.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.173 Q5, Renal: Loop diuretics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-9e8e452c5f', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Adverse effects associated with furosemide include the following EXCEPT:', '["Hyperglycaemia", "Tinnitus", "Fluid and electrolyte imbalance", "Metabolic acidosis", "Hypotension"]'::jsonb, 'Metabolic acidosis', '[]'::jsonb, 'Furosemide causes hypokalaemic metabolic alkalosis: more sodium reaches the collecting duct, where it is exchanged for potassium and hydrogen ions under the influence of aldosterone. Tinnitus reflects its ototoxicity, and mild hyperglycaemia can occur.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.173 Q6, Renal: Loop diuretics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-56f2371ad4', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Which is not an adverse effect of thiazide diuretics?', '["Hypokalaemia", "Hyperuricaemia", "Glucose intolerance", "Metabolic acidosis", "Hyperlipidaemia"]'::jsonb, 'Metabolic acidosis', '[]'::jsonb, 'Thiazides cause hypokalaemic metabolic alkalosis, not acidosis, because increased distal sodium delivery promotes potassium and hydrogen ion secretion. Their metabolic effects are remembered as ''hyperGLUC'': raised glucose, lipids, uric acid and calcium.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.174 Q1, Renal: Thiazides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-a8913dcc9a', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Which of the following is not useful in the management of hypercalcaemia?', '["Loop diuretics", "Calcitonin", "Prednisone", "Pamidronate", "Thiazide diuretics"]'::jsonb, 'Thiazide diuretics', '[]'::jsonb, 'Thiazides increase calcium reabsorption in the distal convoluted tubule and so raise serum calcium, which would worsen hypercalcaemia. Loop diuretics with saline increase calcium excretion, while calcitonin, bisphosphonates and glucocorticoids lower calcium by other routes.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.174 Q3, Renal: Thiazides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-33506ce57b', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Which is not a clinical use of thiazide diuretics?', '["Nephrolithiasis due to idiopathic hypercalciuria", "Nephrogenic diabetes insipidus", "Hypertension", "Heart failure", "Hyperuricaemia"]'::jsonb, 'Hyperuricaemia', '[]'::jsonb, 'Thiazides compete with uric acid for the organic acid secretory system and increase its proximal reabsorption, so they cause hyperuricaemia and can precipitate gout. Their paradoxical antidiuretic effect in nephrogenic diabetes insipidus is a genuine use.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.174 Q4, Renal: Thiazides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-eacc253a80', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Thiazides increase renal excretion of all of the following EXCEPT:', '["Sodium", "Chloride", "Potassium", "Calcium", "Magnesium"]'::jsonb, 'Calcium', '[]'::jsonb, 'Blocking the Na-Cl cotransporter lowers sodium inside the distal tubule cell, which speeds up the basolateral sodium-calcium exchanger and pulls more calcium out of the urine. Urinary calcium therefore falls, whereas magnesium excretion rises.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.174 Q5, Renal: Thiazides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-2fbfd12bd9', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Hydrochlorothiazide produces all of the following actions EXCEPT:', '["Diuresis", "Antihypertensive effect", "Hyperchloraemic acidosis", "Increased serum cholesterol", "Reduced polyuria and polydipsia in patients with nephrogenic diabetes insipidus"]'::jsonb, 'Hyperchloraemic acidosis', '[]'::jsonb, 'Thiazides cause loss of chloride with sodium and enhance hydrogen ion secretion, so the result is a hypochloraemic metabolic alkalosis. Hyperchloraemic acidosis is characteristic of carbonic anhydrase inhibitors such as acetazolamide.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.175 Q7, Renal: Thiazides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-3e6d13e479', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'The most useful agent in the management of hypercalciuria in patients who have recurrent urinary calculi composed of calcium salts is:', '["Mannitol", "Frusemide", "Spironolactone", "Hydrochlorothiazide", "Acetazolamide"]'::jsonb, 'Hydrochlorothiazide', '[]'::jsonb, 'Thiazides increase calcium reabsorption in the distal convoluted tubule, lowering the calcium concentration of urine and the tendency to form stones. Frusemide does the reverse and raises urinary calcium, and acetazolamide promotes calcium phosphate stones by alkalinising the urine.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.175 Q8, Renal: Thiazides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-358d7183fd', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Which is the false statement about potassium-sparing diuretics?', '["They include direct mineralocorticoid receptor antagonists like triamterene", "Amiloride has a longer half-life than triamterene", "Eplerenone has greater mineralocorticoid receptor selectivity than spironolactone", "Spironolactone can cause gynaecomastia", "They antagonise the effects of aldosterone in the collecting tubules"]'::jsonb, 'They include direct mineralocorticoid receptor antagonists like triamterene', '[]'::jsonb, 'Triamterene and amiloride do not act on the mineralocorticoid receptor: they block the epithelial sodium channel (ENaC) in the luminal membrane. The receptor antagonists are spironolactone and eplerenone. Spironolactone''s antiandrogen action explains the gynaecomastia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.175 Q1, Renal: Potassium sparing diuretics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-7a473565dc', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Which statement about eplerenone is false?', '["It is a spironolactone analogue", "It is less active on androgen receptors than spironolactone", "It has greater selectivity for the mineralocorticoid receptor than spironolactone", "It has more adverse effects than spironolactone", "It can be used for the management of heart failure"]'::jsonb, 'It has more adverse effects than spironolactone', '[]'::jsonb, 'Eplerenone was developed to be more selective for the mineralocorticoid receptor, with very little affinity for androgen and progesterone receptors. It therefore causes far less gynaecomastia, impotence and menstrual disturbance than spironolactone, though hyperkalaemia remains a risk.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.175 Q2, Renal: Potassium sparing diuretics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-3a645b6aa2', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Which diuretic acts by interfering with hormone receptors?', '["Frusemide", "Mannitol", "Amiloride", "Hydrochlorothiazide", "Eplerenone"]'::jsonb, 'Eplerenone', '[]'::jsonb, 'Eplerenone competitively blocks the intracellular mineralocorticoid receptor, preventing aldosterone from inducing sodium channels and Na/K-ATPase in the collecting duct. Amiloride is also potassium sparing but blocks the sodium channel itself, not a receptor.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.175 Q3, Renal: Potassium sparing diuretics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-956524bdff', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Which diuretic is secreted into the renal tubular lumen via organic cation transporters?', '["Acetazolamide", "Bumetanide", "Torsemide", "Chlorthalidone", "Amiloride"]'::jsonb, 'Amiloride', '[]'::jsonb, 'Amiloride and triamterene are organic bases and reach the lumen through the proximal tubule''s organic cation transporters. Loop diuretics, thiazides and acetazolamide are organic acids and use the organic anion transporters, which is why they compete with uric acid.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.175 Q4, Renal: Potassium sparing diuretics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-5385a79f87', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Hyperkalaemia is a contraindication to the use of which of the following drugs?', '["Acetazolamide", "Chlorothiazide", "Ethacrynic acid", "Chlorthalidone", "Spironolactone"]'::jsonb, 'Spironolactone', '[]'::jsonb, 'Spironolactone blocks aldosterone-driven potassium secretion in the collecting duct and so raises serum potassium; giving it to a patient who is already hyperkalaemic risks fatal arrhythmias. The other four diuretics all waste potassium.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.176 Q5, Renal: Potassium sparing diuretics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-196788d0c5', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'All of the following diuretics can produce hypokalaemia EXCEPT:', '["Bumetanide", "Ethacrynic acid", "Amiloride", "Hydrochlorothiazide", "Frusemide"]'::jsonb, 'Amiloride', '[]'::jsonb, 'Amiloride blocks the epithelial sodium channel in the collecting duct, which removes the electrical drive for potassium secretion, so potassium is retained. Loop and thiazide diuretics deliver more sodium to this segment and increase potassium loss.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.176 Q6, Renal: Potassium sparing diuretics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-fluids-7214129031', 'pharm-intravenous-fluids', 'mcq', 'Which intravenous fluid contains sodium, potassium, calcium, chloride and lactate (a bicarbonate precursor)?', '["Sodium lactate solution", "Normal saline", "Darrow''s solution", "5% dextrose", "Hartmann''s solution"]'::jsonb, 'Hartmann''s solution', '[]'::jsonb, 'Hartmann''s solution (compound sodium lactate, Ringer''s lactate) contains sodium, potassium, calcium, chloride and lactate, which the liver converts to bicarbonate. Darrow''s solution has sodium, potassium, chloride and lactate but no calcium, and normal saline has only sodium and chloride.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.176 Q1, Renal: IV fluids. Paper asked for the fluid with ''sodium, calcium, chloride and bicarbonate'' and listed both Ringer''s and Hartmann''s; no listed fluid contains bicarbonate itself. Reworded the stem to describe Hartmann''s and replaced ''Ringer''s solution'' with ''5% dextrose''. Human should confirm the intended answer.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiarrhythmic-drugs-0ea05dadbd', 'pharm-antiarrhythmic-drugs', 'mcq', 'Which statement about amiodarone is untrue?', '["Dronedarone is its analogue", "It is the most proarrhythmic class III antiarrhythmic drug", "It inhibits the metabolism of warfarin", "It is effective in the treatment of severe refractory ventricular tachyarrhythmias", "It has a half-life of several weeks"]'::jsonb, 'It is the most proarrhythmic class III antiarrhythmic drug', '[]'::jsonb, 'Although amiodarone prolongs the QT interval, it rarely causes torsades de pointes and is the least proarrhythmic of the class III drugs; sotalol, dofetilide and ibutilide are much worse. It inhibits CYP2C9 and so potentiates warfarin, and its half-life is weeks.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.176 Q1, CVS: Anti-arrhythmics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiarrhythmic-drugs-350d37c717', 'pharm-antiarrhythmic-drugs', 'mcq', 'Which is not a sodium channel blocking antiarrhythmic drug?', '["Ibutilide", "Mexiletine", "Flecainide", "Procainamide", "Quinidine"]'::jsonb, 'Ibutilide', '[]'::jsonb, 'Ibutilide is a class III drug that prolongs repolarisation by blocking the rapid delayed rectifier potassium current. Procainamide and quinidine (IA), mexiletine (IB) and flecainide (IC) are all class I sodium channel blockers.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.177 Q2, CVS: Anti-arrhythmics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiarrhythmic-drugs-2ea2e46806', 'pharm-antiarrhythmic-drugs', 'mcq', 'Which statement regarding amiodarone is false?', '["It may cause pulmonary fibrosis", "It is a potassium channel blocking antiarrhythmic drug", "It is useful in the management of supraventricular and ventricular arrhythmias", "Dronedarone is an analogue with a shorter serum half-life", "It decreases the QT interval of the electrocardiogram"]'::jsonb, 'It decreases the QT interval of the electrocardiogram', '[]'::jsonb, 'As a class III drug, amiodarone blocks potassium channels, lengthening the action potential and therefore the QT interval. Dronedarone lacks the iodine atoms, has a half-life of about a day and spares the thyroid and lungs.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.177 Q3, CVS: Anti-arrhythmics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiarrhythmic-drugs-fd95599718', 'pharm-antiarrhythmic-drugs', 'mcq', 'Which antiarrhythmic drug causes hypothyroidism?', '["Flecainide", "Verapamil", "Sotalol", "Amiodarone", "Lidocaine"]'::jsonb, 'Amiodarone', '[]'::jsonb, 'Amiodarone is about 37% iodine by weight and resembles thyroxine. It blocks peripheral conversion of T4 to T3 and the iodine load can cause either hypothyroidism or thyrotoxicosis, so thyroid function is checked before and during treatment.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.177 Q4, CVS: Anti-arrhythmics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiarrhythmic-drugs-11f5c5e063', 'pharm-antiarrhythmic-drugs', 'mcq', 'Which of the following antiarrhythmic agents is INCORRECTLY matched with its class?', '["Lidocaine - class IB", "Phenytoin - class IC", "Propranolol - class II", "Bretylium - class III", "Verapamil - class IV"]'::jsonb, 'Phenytoin - class IC', '[]'::jsonb, 'Phenytoin behaves like lidocaine and mexiletine: it is a class IB agent with fast binding kinetics that shortens the action potential. Class IC drugs, which dissociate slowly and markedly slow conduction, are flecainide and propafenone.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.177 Q5, CVS: Anti-arrhythmics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiarrhythmic-drugs-a1de02c481', 'pharm-antiarrhythmic-drugs', 'mcq', 'The drug of choice in the treatment of ventricular arrhythmias complicating acute myocardial infarction is:', '["Lidocaine", "Digoxin", "Verapamil", "Quinidine", "Atropine"]'::jsonb, 'Lidocaine', '[]'::jsonb, 'Lidocaine binds preferentially to inactivated sodium channels in depolarised, ischaemic tissue, so it suppresses ventricular arrhythmias arising from infarcted myocardium with little effect on normal tissue. Verapamil is dangerous in ventricular tachycardia, and digoxin and quinidine are themselves proarrhythmic.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.177 Q6, CVS: Anti-arrhythmics. Classic textbook answer; current resuscitation guidelines often prefer amiodarone, which is not among the options.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiarrhythmic-drugs-27c94ec54a', 'pharm-antiarrhythmic-drugs', 'mcq', 'All of the following statements are accurate EXCEPT:', '["Quinidine blocks sodium channels", "Disopyramide has atropine-like action", "Lidocaine prolongs the duration of the action potential", "Phenytoin is used as a cardiac antidysrhythmic as well as an antiepileptic drug", "Amiodarone has antiarrhythmic and antianginal effects"]'::jsonb, 'Lidocaine prolongs the duration of the action potential', '[]'::jsonb, 'Class IB drugs such as lidocaine shorten, or leave unchanged, the action potential duration. Prolongation is a feature of class IA drugs (quinidine, procainamide, disopyramide) and class III drugs. Disopyramide''s antimuscarinic effects cause urinary retention and dry mouth.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.177 Q7, CVS: Anti-arrhythmics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiarrhythmic-drugs-9d1fed5f50', 'pharm-antiarrhythmic-drugs', 'mcq', 'Which of the following antiarrhythmics has class I, II, III and IV activity?', '["Quinidine", "Lidocaine", "Disopyramide", "Verapamil", "Amiodarone"]'::jsonb, 'Amiodarone', '[]'::jsonb, 'Amiodarone is classified as class III because it blocks potassium channels, but it also blocks inactivated sodium channels, has non-competitive beta-blocking action and weakly blocks calcium channels. This breadth explains its efficacy in both atrial and ventricular arrhythmias.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.178 Q8, CVS: Anti-arrhythmics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiarrhythmic-drugs-fc51ab619a', 'pharm-antiarrhythmic-drugs', 'mcq', 'Cinchonism is caused by large doses of:', '["Quinidine", "Lidocaine", "Propranolol", "Amiodarone", "Verapamil"]'::jsonb, 'Quinidine', '[]'::jsonb, 'Quinidine, like its isomer quinine, is a cinchona alkaloid. High doses produce cinchonism: tinnitus, deafness, headache, blurred vision, dizziness and nausea. None of the other antiarrhythmics is derived from cinchona bark.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.178 Q9, CVS: Anti-arrhythmics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcium-channel-blocker-4ea91616e4', 'pharm-calcium-channel-blocker', 'mcq', 'Which calcium channel blocker has a long half-life and is administered once daily?', '["Diltiazem", "Nifedipine", "Verapamil", "Amlodipine", "Nicardipine"]'::jsonb, 'Amlodipine', '[]'::jsonb, 'Amlodipine has a half-life of 30 to 50 hours, so one daily dose gives smooth blood pressure control without reflex tachycardia. Nifedipine, verapamil and diltiazem have half-lives of only a few hours and need modified-release preparations to be given once daily.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.178 Q1, CVS: Calcium channel blockers') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcium-channel-blocker-ba7c05005c', 'pharm-calcium-channel-blocker', 'mcq', 'All of the following are true of calcium channel blockers EXCEPT:', '["Diltiazem is used for the treatment of atrial fibrillation", "The dihydropyridines are more selective as vasodilators than the other classes of calcium channel blockers", "Nicardipine may be administered intravenously", "Amlodipine is administered using a sustained-release formulation", "They are preferred to beta blockers for the treatment of hypertensive patients with asthma"]'::jsonb, 'Amlodipine is administered using a sustained-release formulation', '[]'::jsonb, 'Amlodipine''s intrinsic half-life is so long that an ordinary tablet is enough for once-daily dosing; it is nifedipine that needs a sustained-release formulation. Calcium channel blockers do not constrict the bronchi, so they are safe in asthma.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.178 Q2, CVS: Calcium channel blockers') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcium-channel-blocker-4a8a73b4b3', 'pharm-calcium-channel-blocker', 'mcq', 'Calcium channel blocking drugs could be used in the treatment of all of the following EXCEPT:', '["Hypertension", "Angina pectoris", "Migraine", "Paroxysmal supraventricular tachycardia", "Partial atrioventricular block"]'::jsonb, 'Partial atrioventricular block', '[]'::jsonb, 'Verapamil and diltiazem slow conduction through the AV node, which terminates supraventricular tachycardia but would worsen an existing AV block and could cause complete heart block. Hypertension, angina and migraine prophylaxis are accepted uses.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.178 Q3, CVS: Calcium channel blockers') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcium-channel-blocker-a7704ffb31', 'pharm-calcium-channel-blocker', 'mcq', 'Verapamil produces all of the following actions EXCEPT:', '["Decrease in myocardial contractile force", "Decrease in heart rate", "Decrease in AV nodal conduction", "Decrease in afterload", "Bronchoconstriction"]'::jsonb, 'Bronchoconstriction', '[]'::jsonb, 'Calcium channel blockers relax smooth muscle, including bronchial muscle, so they do not cause bronchoconstriction. Verapamil is the most cardioselective: it is negatively inotropic, chronotropic and dromotropic, and it lowers afterload by dilating arterioles.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.178 Q4, CVS: Calcium channel blockers') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcium-channel-blocker-83c83dcb4d', 'pharm-calcium-channel-blocker', 'mcq', 'The calcium channel blocker of choice in the treatment of cerebral vasospasm following subarachnoid haemorrhage is:', '["Isradipine", "Nicardipine", "Nimodipine", "Nitrendipine", "Amlodipine"]'::jsonb, 'Nimodipine', '[]'::jsonb, 'Nimodipine is a highly lipid-soluble dihydropyridine that crosses the blood-brain barrier and acts preferentially on cerebral arteries. Given for 21 days after subarachnoid haemorrhage, it reduces ischaemic neurological deficits from vasospasm.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.179 Q5, CVS: Calcium channel blockers') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhibitors-of-angiotensin-raas-inhibit-03229211ca', 'pharm-inhibitors-of-angiotensin-raas-inhibitors', 'mcq', 'Which statement is true about losartan?', '["It is more frequently associated with angioedema than captopril", "It can safely be used in pregnancy", "It produces arteriolar and venous dilation", "It causes increased bradykinin levels", "It lowers blood pressure more effectively than aliskiren"]'::jsonb, 'It produces arteriolar and venous dilation', '[]'::jsonb, 'Blocking AT1 receptors removes angiotensin II''s constrictor effect on both arterioles and veins, so losartan lowers afterload and preload. Unlike ACE inhibitors it does not raise bradykinin, so cough and angioedema are much less common. It is fetotoxic and contraindicated in pregnancy.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.179 Q1, CVS: ARBs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhibitors-of-angiotensin-raas-inhibit-9bb56a2fbe', 'pharm-inhibitors-of-angiotensin-raas-inhibitors', 'mcq', 'All of the following are true about inhibitors of angiotensin EXCEPT:', '["Angiotensin II receptor blocking drugs (ARBs) act at angiotensin II type 1 (AT1) receptors", "Angiotensin converting enzyme (ACE) inhibitors cause less cough than the ARBs", "Enalapril is a prodrug", "Aliskiren has equivalent antihypertensive efficacy to ARBs", "ACE inhibitors are used in the treatment of heart failure"]'::jsonb, 'Angiotensin converting enzyme (ACE) inhibitors cause less cough than the ARBs', '[]'::jsonb, 'ACE also breaks down bradykinin, so ACE inhibitors raise bradykinin levels and cause a dry cough in up to 20% of patients. ARBs leave the enzyme alone and are the standard substitute for patients who cough on an ACE inhibitor.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.179 Q2, CVS: ARBs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhibitors-of-angiotensin-raas-inhibit-e6030253f6', 'pharm-inhibitors-of-angiotensin-raas-inhibitors', 'mcq', 'Which is not an adverse effect of captopril?', '["Hyperkalaemia", "Wet cough", "Teratogenicity", "Altered taste", "Angioedema"]'::jsonb, 'Wet cough', '[]'::jsonb, 'The cough caused by ACE inhibitors is characteristically dry and non-productive, due to bradykinin accumulation in the airways. Captopril also causes hyperkalaemia (less aldosterone), taste disturbance from its sulfhydryl group, angioedema and fetal renal damage.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.179 Q2, CVS: ACE inhibitors') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhibitors-of-angiotensin-raas-inhibit-b3b771bc98', 'pharm-inhibitors-of-angiotensin-raas-inhibitors', 'mcq', 'Captopril produces all of the following EXCEPT:', '["Inhibition of angiotensin converting enzyme", "Inhibition of degradation of bradykinin", "Inhibition of secretion of aldosterone", "Reflex sympathetic stimulation", "Lowering of blood pressure in hypertensive patients"]'::jsonb, 'Reflex sympathetic stimulation', '[]'::jsonb, 'ACE inhibitors lower blood pressure without reflex tachycardia, partly because baroreceptors are reset and angiotensin II''s facilitation of sympathetic transmission is removed. This distinguishes them from direct vasodilators such as hydralazine.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.180 Q3, CVS: ACE inhibitors') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhibitors-of-angiotensin-raas-inhibit-0c606b6206', 'pharm-inhibitors-of-angiotensin-raas-inhibitors', 'mcq', 'Angiotensin converting enzyme inhibitors are contraindicated in:', '["Hypertension", "Congestive heart failure", "Bilateral renal artery stenosis", "Diabetes mellitus", "Angina pectoris"]'::jsonb, 'Bilateral renal artery stenosis', '[]'::jsonb, 'With both renal arteries narrowed, glomerular filtration depends on angiotensin II constricting the efferent arteriole. An ACE inhibitor removes this and can precipitate acute renal failure. In diabetes the same efferent dilatation is protective, slowing nephropathy.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.180 Q4, CVS: ACE inhibitors') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-6be5383f4e', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'saq', 'Which combined alpha-1 and beta adrenoceptor blocker is used in the treatment of chronic heart failure?', '[]'::jsonb, 'Carvedilol', '["carvedilol", "Coreg"]'::jsonb, 'Carvedilol blocks beta-1, beta-2 and alpha-1 receptors, so it reduces sympathetic drive to the heart and also lowers afterload. It reduces mortality in chronic heart failure. Labetalol has a similar receptor profile but is used for hypertension, not heart failure.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.180 Q5, CVS: ACE inhibitors. From a matching question (options list not on the page); written as a short-answer question using the answer given.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-angina-4ba5ede892', 'pharm-drugs-used-in-angina', 'saq', 'Which class of drugs used for erectile dysfunction causes dangerous hypotension when taken with nitroglycerin?', '[]'::jsonb, 'PDE5 inhibitors', '["phosphodiesterase 5 inhibitors", "phosphodiesterase-5 inhibitors", "PDE-5 inhibitors", "PDE5 inhibitor", "sildenafil", "tadalafil", "vardenafil", "phosphodiesterase type 5 inhibitors"]'::jsonb, 'Nitrates raise cGMP in vascular smooth muscle, and sildenafil and its relatives stop cGMP being broken down by phosphodiesterase type 5. Together they cause profound vasodilatation and hypotension, so nitrates must not be given within 24 hours of sildenafil.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.180 Q6, CVS: ACE inhibitors. From a matching question whose answer was sildenafil; reworded as a short-answer question.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-8156467bd9', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'mcq', 'Which statement regarding digoxin is false?', '["It increases vagal activity", "It reduces the rate of AV node conduction", "Atrial fibrillation is a common adverse effect", "It is positively inotropic", "It inhibits Na+/K+ ATPase"]'::jsonb, 'Atrial fibrillation is a common adverse effect', '[]'::jsonb, 'Atrial fibrillation is an indication for digoxin, not an adverse effect: its vagal action slows AV conduction and controls the ventricular rate. Toxicity typically causes ventricular ectopics, bigeminy, atrial tachycardia with block and AV block.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.180 Q1, CVS: Cardiac glycosides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-3dbcf44cf3', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'mcq', 'Which statement is true regarding cardiac glycosides?', '["Digoxin may cause aberration of colour perception", "Digoxin is preferred over digitoxin in patients with acute renal failure", "They activate Na+/K+ ATPase", "Atrial fibrillation is a common adverse effect of digoxin", "Ouabain is used in emergencies due to its rapid oral absorption"]'::jsonb, 'Digoxin may cause aberration of colour perception', '[]'::jsonb, 'Digoxin toxicity can cause xanthopsia, a yellow-green tinge to vision, along with halos. Digoxin is cleared by the kidneys, so in renal failure the hepatically cleared digitoxin would be preferred. Ouabain is poorly absorbed orally and is given intravenously.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.180 Q2, CVS: Cardiac glycosides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-0c09e3a1fd', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'mcq', 'Which statement is true regarding digoxin?', '["It is contraindicated in atrial fibrillation", "It has a positive inotropic effect", "It has largely hepatobiliary clearance", "It has a wide therapeutic index", "It has no effect on any muscle other than the heart"]'::jsonb, 'It has a positive inotropic effect', '[]'::jsonb, 'By inhibiting Na+/K+ ATPase, digoxin raises intracellular sodium, which reduces calcium extrusion by the sodium-calcium exchanger and increases contractility. It is excreted mostly unchanged by the kidneys and has a narrow therapeutic index.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.180 Q3, CVS: Cardiac glycosides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-d8026b24ee', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'mcq', 'In the therapy of congestive heart failure, the most important pharmacological action of digitalis is its ability to:', '["Produce diuresis", "Decrease venous pressure", "Increase myocardial contractile force", "Slow conduction in the AV node", "Increase myocardial excitability"]'::jsonb, 'Increase myocardial contractile force', '[]'::jsonb, 'The benefit in heart failure comes from the positive inotropic effect, which raises cardiac output; the diuresis and fall in venous pressure follow from the improved circulation. AV nodal slowing matters in atrial fibrillation, and increased excitability is a toxic effect.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.181 Q4, CVS: Cardiac glycosides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-ba8fd0e5b5', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'mcq', 'Therapeutic doses of cardiac glycosides produce all of the following actions EXCEPT:', '["An increase in intracellular calcium in cardiac cells", "An increase in the effective refractory period of the AV node", "A decrease in the effective refractory period of the ventricles", "Shortening of the Q-T interval on the ECG", "A decrease in vagal tone to the heart"]'::jsonb, 'A decrease in vagal tone to the heart', '[]'::jsonb, 'Digitalis increases vagal tone by sensitising baroreceptors and stimulating central vagal nuclei, which slows the sinus rate and prolongs AV nodal refractoriness. Its direct effect shortens the ventricular action potential, hence the shortened QT interval.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.181 Q5, CVS: Cardiac glycosides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-5d9c573697', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'mcq', 'Therapeutic doses of digoxin given to a patient with congestive heart failure produce all of the following actions on the heart EXCEPT:', '["A positive inotropic effect", "A positive chronotropic effect", "Slowing of conduction in the AV node", "Increased cardiac output", "Reduced heart size"]'::jsonb, 'A positive chronotropic effect', '[]'::jsonb, 'Digoxin slows the heart (negative chronotropy) through increased vagal tone and withdrawal of the reflex sympathetic drive as cardiac output improves. The stronger contraction empties the ventricle better, so the dilated heart becomes smaller.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.181 Q6, CVS: Cardiac glycosides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-734f5ba17e', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'mcq', 'Digitalis glycosides are used in all of the following conditions EXCEPT:', '["Atrial fibrillation", "Atrial flutter", "Paroxysmal atrial tachycardia", "Paroxysmal ventricular tachycardia", "Congestive heart failure"]'::jsonb, 'Paroxysmal ventricular tachycardia', '[]'::jsonb, 'Digitalis increases ventricular automaticity and can itself cause ventricular tachycardia and fibrillation, so it is contraindicated in ventricular tachyarrhythmias. Its vagal slowing of the AV node is useful only in supraventricular arrhythmias.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.181 Q7, CVS: Cardiac glycosides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-965c4e4c14', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'mcq', 'The positive inotropic action of cardiac glycosides is the result of inhibition of:', '["Phosphodiesterase", "Phospholipase A2", "Phospholipase C", "Membrane-bound Na+/K+-activated ATPase", "Adenylate cyclase"]'::jsonb, 'Membrane-bound Na+/K+-activated ATPase', '[]'::jsonb, 'Inhibiting the sodium pump raises intracellular sodium, which reduces the gradient driving the sodium-calcium exchanger, so more calcium stays in the cell and is stored in the sarcoplasmic reticulum for release. Phosphodiesterase inhibition is the mechanism of milrinone, not digoxin.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.181 Q8, CVS: Cardiac glycosides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-3d4d625073', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'mcq', 'The ECG of a patient who is receiving digitalis in the therapeutic range would show:', '["Prolongation of the Q-T interval", "Prolongation of the P-R interval", "Widening of the QRS complex", "Tall peaked T waves", "None of the above"]'::jsonb, 'Prolongation of the P-R interval', '[]'::jsonb, 'Slowed AV nodal conduction lengthens the PR interval. The other therapeutic ECG changes are a shortened QT interval, down-sloping ST depression (''reverse tick'') and flattened or inverted T waves. Tall peaked T waves suggest hyperkalaemia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.181 Q9, CVS: Cardiac glycosides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-7450789afb', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'mcq', 'All of the following measures can be used in the treatment of digoxin-induced cardiac dysrhythmias EXCEPT:', '["Stopping digoxin administration", "Phenytoin administration", "Lidocaine administration", "Electrical cardioversion", "Fab fragments of digoxin-specific antibody"]'::jsonb, 'Electrical cardioversion', '[]'::jsonb, 'DC cardioversion in a digitalised, toxic heart can provoke intractable ventricular fibrillation or asystole and is avoided. Treatment is to stop the drug, correct potassium, give lidocaine or phenytoin for ventricular arrhythmias, and use digoxin-specific Fab fragments in severe cases.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.182 Q10, CVS: Cardiac glycosides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-902da8551b', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'mcq', 'All of the following predispose to digoxin toxicity EXCEPT:', '["Hypokalaemia", "Hypomagnesaemia", "Hypocalcaemia", "Hypothyroidism", "Impaired kidney function"]'::jsonb, 'Hypocalcaemia', '[]'::jsonb, 'It is hypercalcaemia, not hypocalcaemia, that enhances digoxin toxicity, because the drug''s effects depend on intracellular calcium overload. Hypokalaemia increases digoxin binding to the sodium pump, and renal impairment and hypothyroidism reduce its clearance.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.182 Q11, CVS: Cardiac glycosides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-ca903bc8f8', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'mcq', 'The preferred agent to combat extreme digitalis overdose is:', '["Potassium", "Calcium", "Phenytoin", "Digoxin-specific antibody Fab fragments", "Magnesium"]'::jsonb, 'Digoxin-specific antibody Fab fragments', '[]'::jsonb, 'Digoxin-specific Fab fragments bind digoxin in plasma with very high affinity, drawing it off the sodium pump; the complex is excreted by the kidneys and toxicity reverses within an hour. In massive overdose serum potassium is already high, so giving potassium would be dangerous, and calcium worsens toxicity.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.182 Q12, CVS: Cardiac glycosides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-27cb16c7ca', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'All of the following are true of hydralazine EXCEPT:', '["It causes an SLE-like syndrome", "It dilates both arteries and veins", "In ischaemic heart disease it may provoke angina", "Its oral bioavailability is about 25%", "It may cause peripheral neuropathy"]'::jsonb, 'It dilates both arteries and veins', '[]'::jsonb, 'Hydralazine relaxes arteriolar smooth muscle only and has little effect on veins, so postural hypotension is uncommon. The fall in afterload triggers reflex tachycardia, which can provoke angina. It can cause pyridoxine-responsive neuropathy and a lupus-like syndrome.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.182 Q1, CVS: Vasodilators') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-4a8fa22e8f', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'Which statement is true regarding hydralazine?', '["It causes predominantly venous vasodilation", "It acts via activation of potassium channels", "It is more potent than minoxidil", "It has high oral bioavailability", "It is associated with drug-induced lupus in slow acetylators"]'::jsonb, 'It is associated with drug-induced lupus in slow acetylators', '[]'::jsonb, 'Hydralazine is inactivated by N-acetylation in the liver. Slow acetylators have higher plasma levels and are the ones who develop the lupus-like syndrome, usually at doses above 200 mg a day. Potassium channel opening is the mechanism of minoxidil, which is the more potent vasodilator.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.182 Q2, CVS: Vasodilators') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-b3d6ff6c4e', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'Which of the vasodilators below acts on both arteries and veins?', '["Hydralazine", "Minoxidil", "Diazoxide", "Fenoldopam", "Sodium nitroprusside"]'::jsonb, 'Sodium nitroprusside', '[]'::jsonb, 'Sodium nitroprusside releases nitric oxide in both arterial and venous smooth muscle, lowering afterload and preload together. Hydralazine, minoxidil, diazoxide and fenoldopam are predominantly arteriolar dilators. This balanced action makes nitroprusside useful in hypertensive emergencies and acute heart failure.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.182 Q3, CVS: Vasodilators') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-c60a22de8e', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'Use of high doses of which one of the following is associated with drug-induced lupus?', '["Hydralazine", "Prazosin", "Minoxidil", "Methyldopa", "Sodium nitroprusside"]'::jsonb, 'Hydralazine', '[]'::jsonb, 'Hydralazine causes a reversible lupus-like syndrome with arthralgia, fever and positive antinuclear antibodies, mainly at high doses and in slow acetylators. Methyldopa is tempting because it causes a positive Coombs test, but that is an autoimmune haemolytic picture rather than lupus.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.183 Q4, CVS: Vasodilators') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-6b60ebba12', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'Which statement is true regarding sodium nitroprusside?', '["It increases intracellular cyclic GMP", "It can be administered orally", "Its hypotensive action begins within 30 minutes of administration", "It only dilates arterioles", "The metabolite thiocyanate accumulates rapidly in patients with hepatic insufficiency"]'::jsonb, 'It increases intracellular cyclic GMP', '[]'::jsonb, 'Nitroprusside releases nitric oxide, which activates guanylyl cyclase and raises cGMP in vascular smooth muscle. It is given only by intravenous infusion and acts within seconds. Thiocyanate is excreted by the kidneys, so it accumulates in renal, not hepatic, failure.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.183 Q5, CVS: Vasodilators') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-nitric-oxide-f304d7f2cb', 'pharm-nitric-oxide', 'mcq', 'Which statement regarding nitric oxide is false?', '["It is not found in the central nervous system", "Sildenafil potentiates its action by slowing the breakdown of cyclic GMP", "It is abundant in the endothelial cell", "It is synthesised from L-arginine", "Hypotension is associated with its excess production"]'::jsonb, 'It is not found in the central nervous system', '[]'::jsonb, 'Nitric oxide is made in the brain by neuronal nitric oxide synthase (nNOS) and acts as a neurotransmitter and neuromodulator. Endothelial NOS makes it from L-arginine in blood vessels, and excess production by inducible NOS underlies the hypotension of septic shock.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.183 Q6, CVS: Vasodilators. Paper''s option b ''Sildenafil reactivates its production'' is also false (sildenafil inhibits PDE5 and does not affect NO production); reworded b into a true statement so only one option is false.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-angina-453744182a', 'pharm-drugs-used-in-angina', 'mcq', 'Which is a potassium channel activator?', '["Spironolactone", "Nicorandil", "Diltiazem", "Isosorbide mononitrate", "Amlodipine"]'::jsonb, 'Nicorandil', '[]'::jsonb, 'Nicorandil opens ATP-sensitive potassium channels in vascular smooth muscle, hyperpolarising the cell and dilating arteries; it also has a nitrate group that donates nitric oxide and dilates veins. Isosorbide mononitrate has only the nitrate action.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.183 Q7, CVS: Vasodilators') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-257a3b57b2', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'Minoxidil produces:', '["Dilatation of arterioles but not veins", "Bradycardia", "Decrease in cardiac output", "Decrease in plasma renin", "Stimulation of central alpha-2 adrenoceptors"]'::jsonb, 'Dilatation of arterioles but not veins', '[]'::jsonb, 'Minoxidil sulfate opens potassium channels in arteriolar smooth muscle and has no effect on veins. The fall in blood pressure causes reflex tachycardia, increased cardiac output and renin release with fluid retention, so it is given with a beta blocker and a loop diuretic.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.183 Q8, CVS: Vasodilators') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-e6e8461a9b', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'Diazoxide produces all of the following actions EXCEPT:', '["Dilatation of arterioles", "Tachycardia", "Hyperglycaemia", "Hyperuricaemia", "Diuresis"]'::jsonb, 'Diuresis', '[]'::jsonb, 'Although diazoxide is chemically a thiazide, it causes sodium and water retention rather than diuresis. It opens potassium channels in arterioles (vasodilatation with reflex tachycardia) and in pancreatic beta cells (reduced insulin release and hyperglycaemia).', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.183 Q9, CVS: Vasodilators') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-angina-2bfbff0dbd', 'pharm-drugs-used-in-angina', 'mcq', 'Actions of nitroglycerin include all of the following EXCEPT:', '["Coronary vasodilatation", "Venodilatation", "Relaxation of biliary tract smooth muscle", "Increased pulse pressure", "Tachycardia"]'::jsonb, 'Increased pulse pressure', '[]'::jsonb, 'Venodilatation by nitroglycerin reduces venous return and stroke volume, so pulse pressure narrows rather than widens. The fall in blood pressure causes reflex tachycardia. Nitrates relax nearly all smooth muscle, including biliary and oesophageal.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.184 Q10, CVS: Vasodilators') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-efdb151c95', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'saq', 'Which dopamine D1 receptor agonist is given by intravenous infusion in hypertensive emergencies?', '[]'::jsonb, 'Fenoldopam', '["fenoldopam mesylate", "Corlopam"]'::jsonb, 'Fenoldopam selectively stimulates D1 receptors, dilating peripheral, renal and mesenteric arterioles; it lowers blood pressure rapidly while maintaining renal blood flow and promoting natriuresis. Its short half-life (about 10 minutes) allows fine control by infusion.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.184 Q11, CVS: Vasodilators. From a matching question (options list not on the page); written as a short-answer question using the answer given.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-20db5f1cc6', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'saq', 'Sodium thiosulphate is given to reduce the cyanide toxicity of which intravenous vasodilator?', '[]'::jsonb, 'Sodium nitroprusside', '["nitroprusside", "SNP", "Nipride"]'::jsonb, 'Each nitroprusside molecule releases five cyanide ions as it is broken down. The enzyme rhodanese converts cyanide to less toxic thiocyanate but needs a sulphur donor; sodium thiosulphate supplies it. Hydroxocobalamin is an alternative antidote.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.184 Q12, CVS: Vasodilators. From a matching question (options list not on the page); written as a short-answer question using the answer given.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-angina-a199e840b4', 'pharm-drugs-used-in-angina', 'mcq', 'All of the following are true regarding organic nitrates EXCEPT:', '["They relax vascular smooth muscle", "They act as nitric oxide donors", "They can cause postural hypotension", "They relax oesophageal smooth muscle", "They have more effect on small resistance vessels than on larger muscular vessels"]'::jsonb, 'They have more effect on small resistance vessels than on larger muscular vessels', '[]'::jsonb, 'Nitrates act mainly on veins and large conductance arteries, including the epicardial coronary arteries, with little effect on arterioles at usual doses. This is why they lower preload without causing coronary steal, unlike arteriolar dilators such as dipyridamole.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.184 Q1, CVS: Anti-anginal drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-angina-c10e7e5cc6', 'pharm-drugs-used-in-angina', 'mcq', 'Which drug is contraindicated in variant angina?', '["Antiplatelets", "HMG-CoA reductase inhibitors", "Calcium channel blocking drugs", "Organic nitrates", "Beta-adrenoceptor blockers"]'::jsonb, 'Beta-adrenoceptor blockers', '[]'::jsonb, 'Variant (Prinzmetal) angina is caused by coronary artery spasm. Beta blockers remove beta-2 mediated vasodilatation and leave alpha-mediated constriction unopposed, which can worsen the spasm. Calcium channel blockers and nitrates relieve it and are the treatment of choice.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.184 Q2, CVS: Anti-anginal drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-angina-baf448179f', 'pharm-drugs-used-in-angina', 'mcq', 'Beta-receptor antagonists are beneficial in angina pectoris because they produce all of the following EXCEPT:', '["Slowing of the heart rate", "Lowering of blood pressure", "Buffering of the heart against sympathetic stimulation", "Peripheral vasodilatation", "Reduction of myocardial contractility"]'::jsonb, 'Peripheral vasodilatation', '[]'::jsonb, 'Beta blockers reduce myocardial oxygen demand by lowering heart rate, contractility and blood pressure, especially during exercise. They do not dilate vessels; blocking beta-2 receptors tends to cause peripheral vasoconstriction and cold extremities.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.184 Q3, CVS: Anti-anginal drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-1c716ed8e9', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'All of the following are true of alpha-adrenergic antagonists EXCEPT:', '["Prazosin reduces total and LDL cholesterol, and increases HDL cholesterol", "Tamsulosin is mainly used in the treatment of benign prostatic hypertrophy", "Phenoxybenzamine has equal activity on alpha-1 and alpha-2 receptors", "Prazosin dilates both arteries and veins", "Phentolamine is only given parenterally"]'::jsonb, 'Phenoxybenzamine has equal activity on alpha-1 and alpha-2 receptors', '[]'::jsonb, 'Phenoxybenzamine binds irreversibly to alpha receptors and is somewhat selective for alpha-1 over alpha-2. Phentolamine is the antagonist with roughly equal affinity for both subtypes. Prazosin''s balanced arterial and venous dilatation explains its first-dose hypotension.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.184 Q1, CVS: Adrenoceptor blocking drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-e7b76c3924', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'All of the following are true of beta-adrenergic antagonists EXCEPT:', '["They reduce HDL cholesterol and increase triglycerides", "They are contraindicated in Raynaud''s phenomenon", "Labetalol has intrinsic sympathomimetic activity", "They are more effective in Africans", "Abrupt withdrawal may cause myocardial infarction"]'::jsonb, 'They are more effective in Africans', '[]'::jsonb, 'Hypertension in people of African descent tends to be low-renin, so beta blockers and ACE inhibitors are less effective as monotherapy than thiazides and calcium channel blockers. Sudden withdrawal causes rebound because beta receptors are up-regulated during treatment.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.185 Q2, CVS: Adrenoceptor blocking drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antihypertensive-drugs-77b1820300', 'pharm-introduction-to-antihypertensive-drugs-centrally-acting-sympatho', 'mcq', 'Which is the false statement about methyldopa?', '["It is metabolised to methyldopamine", "It is contraindicated in pregnancy", "It can cause gynaecomastia", "It is a centrally acting drug", "It is a prodrug"]'::jsonb, 'It is contraindicated in pregnancy', '[]'::jsonb, 'Methyldopa has a long safety record in pregnancy and is a first-line drug for hypertension in pregnancy. It is a prodrug converted in the brain to alpha-methyldopamine and then alpha-methylnoradrenaline, which stimulates central alpha-2 receptors. Raised prolactin explains gynaecomastia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.185 Q3, CVS: Adrenoceptor blocking drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-fa7e35eb6d', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'Which of the following is a beta-1 selective adrenoceptor blocker?', '["Pindolol", "Propranolol", "Labetalol", "Atenolol", "Sotalol"]'::jsonb, 'Atenolol', '[]'::jsonb, 'Atenolol is cardioselective, blocking beta-1 receptors at lower doses than beta-2. Propranolol, pindolol and sotalol are non-selective, and labetalol blocks alpha-1 as well as both beta subtypes. Selectivity is relative and is lost at high doses.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.185 Q4, CVS: Adrenoceptor blocking drugs. Q4 and Q6 on the page are the same question; kept one.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenergic-neurone-blocking-drugs-79f64ddb30', 'pharm-adrenergic-neurone-blocking-drugs', 'mcq', 'Which is the false statement about reserpine?', '["It is contraindicated in patients with peptic ulcer disease", "It can cause severe depression", "It depletes noradrenaline levels", "It blocks the ability of aminergic transmitter vesicles to take up and store biogenic amines", "Its effect is reversible"]'::jsonb, 'Its effect is reversible', '[]'::jsonb, 'Reserpine binds irreversibly to the vesicular monoamine transporter (VMAT), so its effect persists for days to weeks until new vesicles are synthesised. Unstored amines are destroyed by MAO, depleting noradrenaline, dopamine and serotonin, which explains the depression.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.185 Q5, CVS: Adrenoceptor blocking drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-3c3a7b490d', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'Which one of the following is a non-selective beta blocker?', '["Timolol", "Acebutolol", "Esmolol", "Metoprolol", "Atenolol"]'::jsonb, 'Timolol', '[]'::jsonb, 'Timolol blocks beta-1 and beta-2 receptors equally; it is used as eye drops in glaucoma and can still precipitate bronchospasm in asthmatics. Acebutolol, esmolol, metoprolol and atenolol are all beta-1 selective.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.185 Q7, CVS: Adrenoceptor blocking drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-28f729afc7', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'Which of the following drugs produces most of its antihypertensive effect by blocking alpha-1 adrenoceptors in arterioles and veins?', '["Hydrochlorothiazide", "Hydralazine", "Minoxidil", "Prazosin", "Atenolol"]'::jsonb, 'Prazosin', '[]'::jsonb, 'Prazosin selectively blocks postsynaptic alpha-1 receptors, relaxing both resistance and capacitance vessels. Because presynaptic alpha-2 receptors are spared, there is little reflex tachycardia. Hydralazine and minoxidil act directly on arteriolar muscle, not through receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.186 Q8, CVS: Adrenoceptor blocking drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antihypertensive-drugs-7e02fe89a3', 'pharm-introduction-to-antihypertensive-drugs-centrally-acting-sympatho', 'mcq', 'Which is the preferred drug in the treatment of pregnancy-induced hypertension?', '["Methyldopa", "Guanethidine", "Enalapril", "Losartan", "Furosemide"]'::jsonb, 'Methyldopa', '[]'::jsonb, 'Methyldopa has the longest record of fetal safety and is a standard first-line drug for hypertension in pregnancy, alongside labetalol and nifedipine. ACE inhibitors and ARBs are contraindicated because they cause fetal renal failure and oligohydramnios.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.186 Q1, CVS: Anti-hypertensives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antihypertensive-drugs-fba092d4a6', 'pharm-introduction-to-antihypertensive-drugs-centrally-acting-sympatho', 'mcq', 'Which antihypertensive is wrongly classified?', '["Diuretic: hydrochlorothiazide", "Vasodilator: atenolol", "Direct renin inhibitor: aliskiren", "Sympatholytic drug: clonidine", "Calcium channel blocker: verapamil"]'::jsonb, 'Vasodilator: atenolol', '[]'::jsonb, 'Atenolol is a beta-1 selective adrenoceptor blocker; it lowers blood pressure by reducing cardiac output and renin release, not by dilating vessels. Direct vasodilators are drugs such as hydralazine, minoxidil and nitroprusside.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.186 Q2, CVS: Anti-hypertensives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antihypertensive-drugs-f2b3d023e6', 'pharm-introduction-to-antihypertensive-drugs-centrally-acting-sympatho', 'mcq', 'Which is not a centrally acting sympathoplegic antihypertensive drug?', '["Clonidine", "Reserpine", "Guanfacine", "Methyldopa", "Guanabenz"]'::jsonb, 'Reserpine', '[]'::jsonb, 'Reserpine is classed as an adrenergic neurone blocker: it depletes noradrenaline from peripheral sympathetic nerve endings by blocking vesicular uptake. Clonidine, guanfacine, guanabenz and methyldopa all lower sympathetic outflow by stimulating alpha-2 receptors in the brainstem.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.186 Q3, CVS: Anti-hypertensives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antihypertensive-drugs-c7e20977b2', 'pharm-introduction-to-antihypertensive-drugs-centrally-acting-sympatho', 'mcq', 'Which of the following drugs is effective in the control of hypertension as well as in the prophylaxis of migraine?', '["Indapamide", "Clonidine", "Hydralazine", "Minoxidil", "Captopril"]'::jsonb, 'Clonidine', '[]'::jsonb, 'Clonidine, a central alpha-2 agonist, has been used in low doses for migraine prophylaxis and menopausal flushing as well as hypertension. Vasodilators such as hydralazine and minoxidil cause headache rather than preventing it.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.186 Q4, CVS: Anti-hypertensives. Clonidine is the classic textbook answer, but it is no longer recommended for migraine prophylaxis (beta blockers such as propranolol are the usual antihypertensive used); human should decide whether to keep.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antihypertensive-drugs-af4070fc77', 'pharm-introduction-to-antihypertensive-drugs-centrally-acting-sympatho', 'mcq', 'Which of the following antihypertensive drugs reduces blood pressure by activation of central alpha-2 adrenoceptors?', '["Guanethidine", "Reserpine", "Trimethaphan", "Prazosin", "Clonidine"]'::jsonb, 'Clonidine', '[]'::jsonb, 'Clonidine stimulates alpha-2 (and imidazoline) receptors in the medulla, reducing sympathetic outflow to the heart and vessels. Guanethidine and reserpine act at the peripheral nerve ending, trimethaphan blocks ganglia and prazosin blocks alpha-1 receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.186 Q5, CVS: Anti-hypertensives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antihypertensive-drugs-89bd11b489', 'pharm-introduction-to-antihypertensive-drugs-centrally-acting-sympatho', 'mcq', 'A life-threatening hypertensive crisis can result from sudden withdrawal of:', '["Prazosin", "Nifedipine", "Captopril", "Clonidine", "Hydrochlorothiazide"]'::jsonb, 'Clonidine', '[]'::jsonb, 'Stopping clonidine abruptly releases the suppressed sympathetic outflow, causing a surge of catecholamines with severe rebound hypertension, tachycardia, sweating and anxiety. The dose must be tapered, and the crisis is treated by restarting clonidine or with alpha and beta blockade.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.187 Q6, CVS: Anti-hypertensives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-ecf43e3166', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Indapamide is used in the treatment of:', '["Angina pectoris", "Cardiac dysrhythmias", "Hypertension", "Acute pulmonary oedema", "Coronary thrombosis"]'::jsonb, 'Hypertension', '[]'::jsonb, 'Indapamide is a thiazide-like diuretic with additional direct vasodilator action. It lowers blood pressure at doses that cause little diuresis and has fewer metabolic effects than thiazides. It is too weak for acute pulmonary oedema, which needs a loop diuretic.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.187 Q7, CVS: Anti-hypertensives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcium-channel-blocker-15a74333c6', 'pharm-calcium-channel-blocker', 'mcq', 'Which of the following antihypertensive drugs produces tachycardia?', '["Clonidine", "Nifedipine", "Atenolol", "Reserpine", "Captopril"]'::jsonb, 'Nifedipine', '[]'::jsonb, 'Nifedipine is a potent arteriolar dilator with little direct effect on the sinus or AV node, so the fall in blood pressure triggers baroreceptor-mediated reflex tachycardia, especially with short-acting preparations. Clonidine, atenolol and reserpine slow the heart, and captopril does not change heart rate.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.187 Q8, CVS: Anti-hypertensives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antihypertensive-drugs-d3b4e2b91a', 'pharm-introduction-to-antihypertensive-drugs-centrally-acting-sympatho', 'mcq', 'Correct statements concerning adverse effects of antihypertensives include all of the following EXCEPT that:', '["Hydralazine can induce a lupus erythematosus-like syndrome", "Diazoxide causes sodium and water retention", "Clonidine causes xerostomia", "Reserpine can cause proteinuria", "Minoxidil causes hypertrichosis"]'::jsonb, 'Reserpine can cause proteinuria', '[]'::jsonb, 'Reserpine''s adverse effects are depression, sedation, parkinsonism, nasal stuffiness, diarrhoea and peptic ulceration; it does not damage the kidney. Proteinuria is associated with captopril and penicillamine. Minoxidil''s hair growth is exploited topically for baldness.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.187 Q9, CVS: Anti-hypertensives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antihypertensive-drugs-66af866501', 'pharm-introduction-to-antihypertensive-drugs-centrally-acting-sympatho', 'mcq', 'All of the following drugs may be used in hypertensive emergencies EXCEPT:', '["Furosemide", "Nifedipine", "Sodium nitroprusside", "Labetalol", "Pindolol"]'::jsonb, 'Pindolol', '[]'::jsonb, 'Pindolol is an oral beta blocker with marked intrinsic sympathomimetic activity, so it lowers blood pressure slowly and modestly and has no place in emergencies. Nitroprusside and labetalol are given intravenously, with furosemide added when there is fluid overload.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.187 Q10, CVS: Anti-hypertensives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antihypertensive-drugs-1c69587607', 'pharm-introduction-to-antihypertensive-drugs-centrally-acting-sympatho', 'mcq', 'For monotherapy of mild hypertension all of the following are used EXCEPT:', '["Atenolol", "Verapamil", "Losartan", "Hydralazine", "Hydrochlorothiazide"]'::jsonb, 'Hydralazine', '[]'::jsonb, 'Hydralazine used alone provokes reflex tachycardia, renin release and fluid retention, which cancel its effect and can precipitate angina. It is therefore always combined with a beta blocker and a diuretic, and is reserved for resistant hypertension or pregnancy.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.187 Q11, CVS: Anti-hypertensives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenergic-neurone-blocking-drugs-b6da0739ec', 'pharm-adrenergic-neurone-blocking-drugs', 'mcq', 'Which of the following drugs depletes catecholamine stores in the CNS and in sympathetic nerve endings?', '["Guanethidine", "Reserpine", "Clonidine", "Propranolol", "Phenylpropanolamine"]'::jsonb, 'Reserpine', '[]'::jsonb, 'Reserpine is lipid soluble, crosses the blood-brain barrier and blocks VMAT in both central and peripheral neurones, so stores of noradrenaline, dopamine and serotonin are depleted everywhere. Guanethidine also depletes noradrenaline but is too polar to enter the brain.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.188 Q12, CVS: Anti-hypertensives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenergic-neurone-blocking-drugs-7d1f8b4286', 'pharm-adrenergic-neurone-blocking-drugs', 'mcq', 'Side effects of reserpine include all of the following EXCEPT:', '["Psychic depression", "Diarrhoea", "Activation of peptic ulcer", "Weight loss", "Parkinsonism"]'::jsonb, 'Weight loss', '[]'::jsonb, 'Reserpine removes sympathetic tone and leaves the parasympathetic unopposed, causing diarrhoea, increased gastric acid and bradycardia. Central amine depletion causes depression and parkinsonism. Patients tend to gain weight, from increased appetite and fluid retention.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.188 Q13, CVS: Anti-hypertensives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenergic-neurone-blocking-drugs-6bf6bb0f74', 'pharm-adrenergic-neurone-blocking-drugs', 'mcq', 'All of the following are correct about reserpine EXCEPT that:', '["It is effective orally", "It passes the blood-brain barrier", "It inhibits the enzyme dopa decarboxylase", "It causes bradycardia", "It is used in hypertension"]'::jsonb, 'It inhibits the enzyme dopa decarboxylase', '[]'::jsonb, 'Reserpine does not inhibit any synthetic enzyme; it blocks the vesicular monoamine transporter so that transmitters cannot be stored. Dopa decarboxylase is inhibited by carbidopa and benserazide, and is the enzyme that converts methyldopa to its active form.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.188 Q14, CVS: Anti-hypertensives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenergic-neurone-blocking-drugs-4f8f612943', 'pharm-adrenergic-neurone-blocking-drugs', 'mcq', 'All of the following are side effects of guanethidine EXCEPT:', '["Postural hypotension", "Failure of ejaculation", "Nasal congestion", "Parkinsonism", "Diarrhoea"]'::jsonb, 'Parkinsonism', '[]'::jsonb, 'Guanethidine is highly polar and does not enter the brain, so it has no central effects such as sedation, depression or parkinsonism. Its side effects all reflect loss of peripheral sympathetic function with unopposed parasympathetic activity.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.188 Q15, CVS: Anti-hypertensives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antihypertensive-drugs-80518f54f1', 'pharm-introduction-to-antihypertensive-drugs-centrally-acting-sympatho', 'mcq', 'All of the following are toxic effects of methyldopa EXCEPT:', '["Sedation", "Drug fever", "Hepatitis", "Haemolytic anaemia", "Prolonged vasospasm leading to gangrene"]'::jsonb, 'Prolonged vasospasm leading to gangrene', '[]'::jsonb, 'Vasospasm with gangrene is the toxic effect of ergot alkaloids, not of methyldopa, which lowers vascular tone. Methyldopa causes sedation, a positive Coombs test with occasional haemolytic anaemia, hepatitis and drug fever.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.188 Q16, CVS: Anti-hypertensives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antihypertensive-drugs-5f4bbf857e', 'pharm-introduction-to-antihypertensive-drugs-centrally-acting-sympatho', 'mcq', 'All of the following are selective alpha-2 adrenergic agonists in the CNS EXCEPT:', '["Clonidine", "Alpha-methylnoradrenaline", "Guanfacine", "Guanethidine", "Guanabenz"]'::jsonb, 'Guanethidine', '[]'::jsonb, 'Despite the similar name, guanethidine is a peripheral adrenergic neurone blocker: it is taken up by the noradrenaline transporter, replaces noradrenaline in vesicles and prevents its release. Alpha-methylnoradrenaline is the active metabolite of methyldopa.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.188 Q17, CVS: Anti-hypertensives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiarrhythmic-drugs-a3f8923adf', 'pharm-antiarrhythmic-drugs', 'mcq', 'Which of the following drugs is capable of producing a syndrome that resembles systemic lupus erythematosus?', '["Digoxin", "Minoxidil", "Procainamide", "Reserpine", "Disopyramide"]'::jsonb, 'Procainamide', '[]'::jsonb, 'Procainamide causes antinuclear antibodies in most patients on long-term therapy and a lupus-like syndrome with arthralgia, pleuritis and rash in up to a third, especially slow acetylators. Hydralazine and isoniazid are the other classic causes.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.189 Q18, CVS: Anti-hypertensives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-lipid-lowering-agents-9e67a2f57a', 'pharm-lipid-lowering-agents', 'mcq', 'Which statement regarding statins is untrue?', '["They are mainly excreted in the bile and stool", "Rosuvastatin is the most efficacious statin for severe hypercholesterolaemia", "They cause osteoporosis", "Lovastatin is a prodrug", "They competitively inhibit the enzyme HMG-CoA reductase"]'::jsonb, 'They cause osteoporosis', '[]'::jsonb, 'Statins do not cause osteoporosis. Their important adverse effects are myopathy, occasionally rhabdomyolysis, and raised liver transaminases. Lovastatin and simvastatin are inactive lactone prodrugs hydrolysed to the active form after absorption.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.189 Q1, CVS: Lipid lowering agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-lipid-lowering-agents-1f764049b6', 'pharm-lipid-lowering-agents', 'mcq', 'Which of the following is the most effective agent for increasing HDL cholesterol?', '["Niacin", "Gemfibrozil", "Fenofibrate", "Cholestyramine", "Colestipol"]'::jsonb, 'Niacin', '[]'::jsonb, 'Niacin (nicotinic acid) raises HDL cholesterol by 25 to 35%, more than any other lipid drug, by reducing hepatic removal of apoA-I; it also lowers triglycerides, LDL and lipoprotein(a). Fibrates raise HDL by only 10 to 20%.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.189 Q2, CVS: Lipid lowering agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-dba18ab9d3', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'Which statement is true about sympathomimetics used in asthma?', '["They inhibit phosphodiesterase", "Inhalation is the recommended route of administration", "The commonest adverse effect is smooth muscle tremor", "Epinephrine is selective for the beta-2 adrenergic receptor", "Salmeterol is the most effective bronchodilator for acute attacks"]'::jsonb, 'Inhalation is the recommended route of administration', '[]'::jsonb, 'Inhalation delivers the drug straight to the airways, giving rapid bronchodilatation with much less tachycardia and tremor than oral or parenteral dosing. Beta-2 agonists act by stimulating adenylyl cyclase, and the tremor they cause is of skeletal, not smooth, muscle.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.189 Q2, Respiratory: Drugs in asthma. Option e clarified with ''for acute attacks'' (paper: ''Salmeterol is the most effective bronchodilator'').') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antimuscarinic-agents-291264c5d6', 'pharm-antimuscarinic-agents', 'mcq', 'Which statement is true of the cholinolytics (antimuscarinics) used in airway disease?', '["Tiotropium has a longer duration of action than ipratropium", "They are atropine antagonists", "Only ipratropium has a bronchodilator effect", "Ipratropium has been associated with causation of chronic obstructive airway disease", "They are ineffective as inhalational agents"]'::jsonb, 'Tiotropium has a longer duration of action than ipratropium', '[]'::jsonb, 'Tiotropium dissociates very slowly from M3 receptors and bronchodilates for 24 hours, allowing once-daily dosing in COPD. Ipratropium lasts only 4 to 6 hours. Both are quaternary atropine derivatives given by inhalation.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.190 Q5, Respiratory: Drugs in asthma') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-bb85536dba', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'Which adverse effect is associated with salbutamol?', '["Hoarse voice", "Seizures", "Oral candidiasis", "Dry mouth", "Skeletal muscle tremors"]'::jsonb, 'Skeletal muscle tremors', '[]'::jsonb, 'Stimulation of beta-2 receptors on skeletal muscle causes a fine tremor, the commonest side effect of salbutamol, together with tachycardia and hypokalaemia at high doses. Hoarseness and oral candidiasis are local effects of inhaled corticosteroids.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.191 Q14, Respiratory: Drugs in asthma') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-67ca4dc119', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'Which of the following statements is CORRECT regarding salbutamol?', '["It is a selective beta-2 adrenoceptor antagonist", "It is not metabolised by COMT but by MAO", "It is administered sublingually", "Tachycardia and muscle tremors may occur as side effects", "It inhibits the enzyme adenylyl cyclase"]'::jsonb, 'Tachycardia and muscle tremors may occur as side effects', '[]'::jsonb, 'Salbutamol is a beta-2 agonist that activates adenylyl cyclase through Gs. Tremor comes from beta-2 receptors in skeletal muscle and tachycardia from reflex and direct cardiac stimulation. It is not a catecholamine, so neither COMT nor MAO metabolises it; it is conjugated to a sulphate.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.192 Q18, Respiratory: Drugs in asthma') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-124f10e05e', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'Which of the following statements is INCORRECT regarding salbutamol?', '["It produces minimal action on the heart rate if used in therapeutic doses", "It causes bronchodilatation", "It is effective when swallowed", "It contracts uterine smooth muscle", "It causes skeletal muscle tremors"]'::jsonb, 'It contracts uterine smooth muscle', '[]'::jsonb, 'Beta-2 stimulation relaxes the uterus, and salbutamol and ritodrine have been used as tocolytics to delay premature labour. Because it resists COMT and gut sulphatases only partly inactivate it, salbutamol is also active by mouth.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.192 Q19, Respiratory: Drugs in asthma') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-1e0e85e546', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'Pharmacological effects of beta-2 selective adrenoceptor agonists include all of the following EXCEPT:', '["Relaxation of bronchial smooth muscle", "Inhibition of mediator release from mast cells", "Vasoconstriction", "Activation of the enzyme adenylyl cyclase", "Enhanced mucociliary function"]'::jsonb, 'Vasoconstriction', '[]'::jsonb, 'Beta-2 receptors on vascular smooth muscle, especially in skeletal muscle beds, cause vasodilatation, which can lower diastolic pressure and provoke reflex tachycardia. Vasoconstriction is an alpha-1 effect. The other options are genuine beta-2 effects, all mediated by a rise in cyclic AMP.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.192 Q20, Respiratory: Drugs in asthma') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-ec5db220ea', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'Theophylline is a competitive antagonist at which of the following receptors?', '["Adenosine receptors", "Muscarinic receptors", "Beta-2 receptors", "H1 receptors", "5-HT2 receptors"]'::jsonb, 'Adenosine receptors', '[]'::jsonb, 'At therapeutic concentrations theophylline blocks A1 and A2 adenosine receptors, which contributes to bronchodilatation and explains CNS stimulation, diuresis and the risk of seizures and arrhythmias. Its other main action is non-selective phosphodiesterase inhibition.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.193 Q22, Respiratory: Drugs in asthma') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-eb622e0fa0', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'Adverse effects associated with the use of theophylline include all of the following EXCEPT:', '["Nausea and vomiting", "Convulsions", "Cardiac arrhythmias", "Hypotension", "Sedation"]'::jsonb, 'Sedation', '[]'::jsonb, 'Theophylline is a CNS stimulant like caffeine: it causes insomnia, restlessness, tremor and, in overdose, convulsions. Nausea and vomiting are early signs of toxicity, and arrhythmias and hypotension occur at higher levels.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.193 Q23, Respiratory: Drugs in asthma') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-86d152edd7', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'Plasma clearance of theophylline is reduced by all of the following EXCEPT:', '["Erythromycin", "Ciprofloxacin", "Phenytoin", "Heart failure", "Hepatic cirrhosis"]'::jsonb, 'Phenytoin', '[]'::jsonb, 'Phenytoin induces CYP1A2 and so increases theophylline clearance, as do rifampicin, carbamazepine and smoking. Erythromycin and ciprofloxacin inhibit the enzyme, and heart failure and cirrhosis reduce hepatic metabolism, all raising theophylline levels.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.193 Q24, Respiratory: Drugs in asthma') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antimuscarinic-agents-76a95b26b1', 'pharm-antimuscarinic-agents', 'mcq', 'Which of the following statements concerning ipratropium bromide is INCORRECT?', '["It is a muscarinic receptor antagonist", "It does not decrease mucociliary clearance of bronchial secretions", "It is given by aerosol inhalation", "It does not cross the blood-brain barrier", "It has an H1 blocking effect"]'::jsonb, 'It has an H1 blocking effect', '[]'::jsonb, 'Ipratropium is a quaternary derivative of atropine that blocks muscarinic receptors only; it has no antihistamine action. Its permanent charge prevents absorption and entry into the brain, and unlike atropine it does not impair mucociliary clearance.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.193 Q25, Respiratory: Drugs in asthma') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-in-asthma-mast-cell-st-21953f7826', 'pharm-corticosteroids-in-asthma-mast-cell-stabilisers', 'mcq', 'Sodium cromoglycate (cromolyn sodium) is:', '["Completely absorbed from the gastrointestinal tract", "Effective in terminating acute asthmatic attacks", "A direct relaxant of airway smooth muscle", "Given by inhalation for prophylaxis of bronchial asthma", "A competitive antagonist at adenosine receptors"]'::jsonb, 'Given by inhalation for prophylaxis of bronchial asthma', '[]'::jsonb, 'Cromoglycate stabilises mast cells and prevents mediator release, so it works only when inhaled regularly before exposure to the trigger. It has no bronchodilator action and is useless in an acute attack. Less than 1% is absorbed from the gut.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.193 Q26, Respiratory: Drugs in asthma') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-in-asthma-mast-cell-st-689aa9860b', 'pharm-corticosteroids-in-asthma-mast-cell-stabilisers', 'mcq', 'Which statement is correct regarding nedocromil?', '["It is a competitive antagonist at adenosine receptors", "It is a direct relaxant of airway smooth muscle", "It inhibits the enzyme phosphodiesterase", "It is completely absorbed orally", "It is used prophylactically to prevent attacks of asthma"]'::jsonb, 'It is used prophylactically to prevent attacks of asthma', '[]'::jsonb, 'Nedocromil, like cromoglycate, inhibits the release of mediators from mast cells and other inflammatory cells. It is inhaled regularly as a preventer and has no bronchodilator effect. Adenosine antagonism and phosphodiesterase inhibition describe theophylline.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.193 Q27, Respiratory: Drugs in asthma') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-in-asthma-mast-cell-st-8a0faf7fe2', 'pharm-corticosteroids-in-asthma-mast-cell-stabilisers', 'mcq', 'Inhaled glucocorticoids used in bronchial asthma include all of the following EXCEPT:', '["Beclomethasone dipropionate", "Budesonide", "Prednisolone", "Flunisolide", "Fluticasone"]'::jsonb, 'Prednisolone', '[]'::jsonb, 'Prednisolone is given orally for acute severe or very difficult asthma. The inhaled steroids are designed for high topical potency with extensive first-pass metabolism of any swallowed fraction, which keeps systemic effects low.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.194 Q28, Respiratory: Drugs in asthma') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-in-asthma-mast-cell-st-1290bb53ab', 'pharm-corticosteroids-in-asthma-mast-cell-stabilisers', 'mcq', 'Inhaled glucocorticoids produce which of the following adverse effects?', '["Tremors", "Oropharyngeal candidiasis", "Tachycardia", "Drowsiness", "Nausea and vomiting"]'::jsonb, 'Oropharyngeal candidiasis', '[]'::jsonb, 'Steroid deposited in the mouth and throat suppresses local immunity, allowing Candida to overgrow, and can also cause hoarseness. Using a spacer and rinsing the mouth after each dose reduces the risk. Tremor and tachycardia are effects of beta-2 agonists.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.194 Q29, Respiratory: Drugs in asthma') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-in-asthma-mast-cell-st-b018f50c52', 'pharm-corticosteroids-in-asthma-mast-cell-stabilisers', 'mcq', 'In status asthmaticus (severe acute asthma), it is dangerous to use all of the following EXCEPT:', '["Morphine", "Barbiturates", "Intravenous adrenocorticosteroids", "Propranolol", "Nadolol"]'::jsonb, 'Intravenous adrenocorticosteroids', '[]'::jsonb, 'Intravenous hydrocortisone is a cornerstone of treatment of severe acute asthma, alongside oxygen and nebulised bronchodilators. Morphine and barbiturates depress respiration, and the non-selective beta blockers propranolol and nadolol cause bronchoconstriction.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.194 Q30, Respiratory: Drugs in asthma') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cough-suppressants-and-expectorants-662df6ee48', 'pharm-cough-suppressants-and-expectorants', 'mcq', 'Which drug is a mucolytic?', '["Ethylmorphine", "Liquorice", "Noscapine", "Ambroxol", "Promethazine"]'::jsonb, 'Ambroxol', '[]'::jsonb, 'Ambroxol, the active metabolite of bromhexine, thins bronchial secretions and stimulates surfactant production. Ethylmorphine and noscapine are centrally acting antitussives, liquorice is a demulcent and promethazine is a sedating antihistamine used in cough mixtures.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.194 Q2, Respiratory: Cough suppressants and expectorants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cough-suppressants-and-expectorants-2df90d6329', 'pharm-cough-suppressants-and-expectorants', 'mcq', 'Central antitussives include all of the following EXCEPT:', '["Noscapine", "Pholcodine", "Codeine", "Diphenoxylate", "Dextromethorphan"]'::jsonb, 'Diphenoxylate', '[]'::jsonb, 'Diphenoxylate is a pethidine congener used, combined with atropine, as an antidiarrhoeal; it has no role in cough. Codeine, pholcodine, noscapine and dextromethorphan all raise the threshold of the medullary cough centre.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.194 Q3, Respiratory: Cough suppressants and expectorants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cough-suppressants-and-expectorants-8847f775f9', 'pharm-cough-suppressants-and-expectorants', 'mcq', 'Concerning dextromethorphan hydrobromide, all of the following are true EXCEPT that it:', '["Is a central antitussive", "Is non-addictive", "Is a powerful analgesic", "Does not inhibit mucociliary clearance", "Does not produce constipation"]'::jsonb, 'Is a powerful analgesic', '[]'::jsonb, 'Dextromethorphan is the d-isomer of a codeine analogue: it retains antitussive activity but has no analgesic effect and, at therapeutic doses, no addictive, constipating or respiratory depressant actions. It acts on sigma and NMDA receptors rather than mu receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.195 Q4, Respiratory: Cough suppressants and expectorants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cough-suppressants-and-expectorants-2e4871ad52', 'pharm-cough-suppressants-and-expectorants', 'mcq', 'Which of the following is a nauseant expectorant?', '["Tincture of ipecacuanha", "Acetylcysteine", "Bromhexine", "Pholcodine", "Benzonatate"]'::jsonb, 'Tincture of ipecacuanha', '[]'::jsonb, 'In sub-emetic doses ipecacuanha irritates the gastric mucosa and reflexly, through the vagus, increases bronchial secretion; ammonium chloride and guaifenesin act similarly. Acetylcysteine and bromhexine are mucolytics, and pholcodine and benzonatate are antitussives.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.195 Q5, Respiratory: Cough suppressants and expectorants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cough-suppressants-and-expectorants-02c848f4ec', 'pharm-cough-suppressants-and-expectorants', 'mcq', 'Bromhexine is prescribed to:', '["Reduce the viscosity of bronchial secretions", "Stimulate the respiratory centre", "Depress the cough centre", "Suppress appetite", "Relieve colonic spasm"]'::jsonb, 'Reduce the viscosity of bronchial secretions', '[]'::jsonb, 'Bromhexine is a mucolytic: it breaks up the mucopolysaccharide fibres of sputum and increases lysosomal enzyme activity, making thick secretions thinner and easier to cough up. It does not act on the cough or respiratory centres.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.195 Q6, Respiratory: Cough suppressants and expectorants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-gabapentin-vigabatrin-and-others-f9034276fc', 'pharm-gabapentin-vigabatrin-and-others', 'mcq', 'Oligohidrosis is associated with which one of the following anticonvulsants?', '["Phenytoin", "Valproic acid", "Zonisamide", "Primidone", "Clonazepam"]'::jsonb, 'Zonisamide', '[]'::jsonb, 'Zonisamide is a sulphonamide derivative with weak carbonic anhydrase inhibiting action; it can reduce sweating and cause hyperthermia, especially in children, as well as kidney stones. Topiramate shares these effects for the same reason.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.195 Q1, CNS: Anti-convulsants. Paper listed both topiramate and zonisamide, and both cause oligohidrosis; replaced topiramate with phenytoin so only one option is correct.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-gabapentin-vigabatrin-and-others-af50d3bd4f', 'pharm-gabapentin-vigabatrin-and-others', 'mcq', 'Which of the following works by binding to the synaptic vesicle protein SV2A?', '["Levetiracetam", "Retigabine", "Felbamate", "Perampanel", "Tiagabine"]'::jsonb, 'Levetiracetam', '[]'::jsonb, 'Levetiracetam binds SV2A on synaptic vesicles and reduces neurotransmitter release during high-frequency firing. Retigabine opens KCNQ potassium channels, felbamate blocks NMDA receptors, perampanel blocks AMPA receptors and tiagabine inhibits GABA reuptake.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.196 Q3, CNS: Anti-convulsants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-gabapentin-vigabatrin-and-others-1f8f053c03', 'pharm-gabapentin-vigabatrin-and-others', 'mcq', 'Which one of the following is useful in the management of catamenial seizures?', '["Gabapentin", "Oxcarbazepine", "Acetazolamide", "Mannitol", "Vigabatrin"]'::jsonb, 'Acetazolamide', '[]'::jsonb, 'Catamenial seizures cluster around menstruation. Acetazolamide, a carbonic anhydrase inhibitor, is given intermittently around that time; the mild acidosis it produces in the brain reduces neuronal excitability. Tolerance limits its continuous use.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.196 Q4, CNS: Anti-convulsants. Appears twice (p.196 Q4 and p.197 Q11); kept one.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-valproic-acid-oxazolidinediones-benzod-eaf7f85312', 'pharm-valproic-acid-oxazolidinediones-benzodiazepines', 'mcq', 'Which statement regarding valproic acid is false?', '["It stimulates GABA transaminase", "It displaces phenytoin from albumin binding sites", "It is contraindicated in the first trimester of pregnancy", "It is a broad-spectrum anticonvulsant", "L-carnitine is used for the management of valproic acid-induced hepatotoxicity"]'::jsonb, 'It stimulates GABA transaminase', '[]'::jsonb, 'Valproate inhibits GABA transaminase, the enzyme that breaks down GABA, so brain GABA rises; it also blocks sodium and T-type calcium channels. It causes neural tube defects, hence the first-trimester contraindication.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.196 Q5, CNS: Anti-convulsants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-valproic-acid-oxazolidinediones-benzod-54401a55af', 'pharm-valproic-acid-oxazolidinediones-benzodiazepines', 'mcq', 'Which antiseizure drug inhibits the metabolism of carbamazepine?', '["Lamotrigine", "Gabapentin", "Ethosuximide", "Valproic acid", "Clonazepam"]'::jsonb, 'Valproic acid', '[]'::jsonb, 'Valproic acid is an enzyme inhibitor: it blocks epoxide hydrolase, raising levels of the active and toxic carbamazepine-10,11-epoxide, and also inhibits the metabolism of lamotrigine and phenobarbital. Most other older anticonvulsants are enzyme inducers.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.196 Q6, CNS: Anti-convulsants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-gabapentin-vigabatrin-and-others-dc33dcf194', 'pharm-gabapentin-vigabatrin-and-others', 'mcq', 'Which one of the following is excreted unchanged?', '["Gabapentin", "Dimethadione", "Phenytoin", "Clonazepam", "Valproic acid"]'::jsonb, 'Gabapentin', '[]'::jsonb, 'Gabapentin is not metabolised and not protein bound; it is eliminated entirely by the kidneys, so the dose must be reduced in renal impairment and it has almost no drug interactions. Phenytoin, clonazepam and valproic acid are cleared by hepatic metabolism.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.196 Q7, CNS: Anti-convulsants. Paper listed both gabapentin and vigabatrin, and both are excreted unchanged in urine; replaced vigabatrin with phenytoin so only one option is correct.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-iminostilbenes-succinimides-lamotrigin-2ddb6fbada', 'pharm-iminostilbenes-succinimides-lamotrigine', 'mcq', 'Which is not a clinical indication for carbamazepine?', '["Myoclonic seizures", "Trigeminal neuralgia", "Focal to bilateral tonic-clonic seizures", "Mania in bipolar mood disorder", "Focal seizures"]'::jsonb, 'Myoclonic seizures', '[]'::jsonb, 'Carbamazepine can worsen myoclonic and absence seizures and is avoided in them; valproate is preferred. It is a drug of choice for focal seizures and trigeminal neuralgia, and is a mood stabiliser in bipolar disorder.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.196 Q8, CNS: Anti-convulsants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anticonvulsant-drugs-c-3b062fedbb', 'pharm-introduction-to-anticonvulsant-drugs-classification-of-seizures', 'mcq', 'Which statement concerning the proposed mechanisms of action of anticonvulsant drugs is inaccurate?', '["Phenobarbital has multiple actions, including enhancement of the effects of GABA, antagonism of glutamate receptors, and blockade of sodium channels", "Phenytoin prolongs the inactivated state of the sodium channel", "Zonisamide blocks voltage-gated sodium channels", "Ethosuximide selectively blocks potassium channels in thalamic neurons", "Diazepam facilitates GABA-mediated inhibitory actions"]'::jsonb, 'Ethosuximide selectively blocks potassium channels in thalamic neurons', '[]'::jsonb, 'Ethosuximide blocks low-threshold T-type calcium channels in thalamic neurones, interrupting the thalamocortical rhythm that generates the 3 Hz spike-and-wave discharges of absence seizures. It has no action on potassium channels.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.196 Q9, CNS: Anti-convulsants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiseizure-barbiturates-hydantoin-ea1fd0a444', 'pharm-antiseizure-barbiturates-hydantoin', 'mcq', 'Which is not a likely association with phenytoin sodium?', '["Nystagmus", "Gingival hypertrophy", "Alopecia", "Lymphadenopathy", "Cytochrome P450 induction"]'::jsonb, 'Alopecia', '[]'::jsonb, 'Phenytoin causes excess hair growth (hirsutism) and coarsening of the facial features, not hair loss; alopecia is associated with valproate. Nystagmus is an early dose-related sign, and gum hypertrophy and lymphadenopathy occur with long-term use.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.197 Q10, CNS: Anti-convulsants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiseizure-barbiturates-hydantoin-94b46ec2ad', 'pharm-antiseizure-barbiturates-hydantoin', 'mcq', 'Gingival hyperplasia and hirsutism are side effects of which one of the following anticonvulsant drugs?', '["Carbamazepine", "Phenytoin", "Valproic acid", "Phenobarbital", "Clonazepam"]'::jsonb, 'Phenytoin', '[]'::jsonb, 'Phenytoin stimulates fibroblast proliferation in the gums, causing overgrowth in about a fifth of patients, and also causes hirsutism and coarse facies. These cosmetic effects make it unpopular in adolescents. Valproate causes hair thinning instead.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.197 Q12, CNS: Anti-convulsants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-iminostilbenes-succinimides-lamotrigin-3a01cde5c2', 'pharm-iminostilbenes-succinimides-lamotrigine', 'mcq', 'All of the following antiepileptic drugs are useful against generalised tonic-clonic (grand mal) seizures EXCEPT:', '["Ethosuximide", "Phenytoin", "Carbamazepine", "Phenobarbitone", "Primidone"]'::jsonb, 'Ethosuximide', '[]'::jsonb, 'Ethosuximide has a narrow spectrum: it blocks T-type calcium channels and is effective only in absence seizures. A patient with both absence and tonic-clonic seizures needs valproate instead. The other four drugs all control tonic-clonic seizures.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.197 Q13, CNS: Anti-convulsants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-valproic-acid-oxazolidinediones-benzod-68247a4ba4', 'pharm-valproic-acid-oxazolidinediones-benzodiazepines', 'mcq', 'The preferred treatment of status epilepticus is intravenous administration of which of the following drugs?', '["Benztropine", "Meperidine", "Trimethadione", "Chlorpromazine", "Diazepam"]'::jsonb, 'Diazepam', '[]'::jsonb, 'An intravenous benzodiazepine (diazepam or lorazepam) is first-line because it enters the brain rapidly and enhances GABA-A receptor chloride currents, stopping the seizure within minutes. Chlorpromazine and meperidine lower the seizure threshold and would make matters worse.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.197 Q14, CNS: Anti-convulsants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-iminostilbenes-succinimides-lamotrigin-88cd23602b', 'pharm-iminostilbenes-succinimides-lamotrigine', 'mcq', 'The drug of choice in the treatment of petit mal epilepsy (absence seizures) is:', '["Phenytoin", "Primidone", "Carbamazepine", "Ethosuximide", "Imipramine"]'::jsonb, 'Ethosuximide', '[]'::jsonb, 'Ethosuximide blocks T-type calcium channels in thalamic neurones, abolishing the 3 Hz spike-and-wave rhythm of absence seizures. Phenytoin and carbamazepine are sodium channel blockers that are ineffective in absence seizures and may even make them worse.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.198 Q5, CNS Pharmacology: Anti-convulsants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-iminostilbenes-succinimides-lamotrigin-d43a6debe4', 'pharm-iminostilbenes-succinimides-lamotrigine', 'mcq', 'Which of the following drugs is used to treat trigeminal neuralgia?', '["Carbamazepine", "Trimethadione", "Ethosuximide", "Acetazolamide", "Phenobarbitone"]'::jsonb, 'Carbamazepine', '[]'::jsonb, 'Carbamazepine stabilises the inactivated state of voltage-gated sodium channels, damping the paroxysmal firing of trigeminal afferents; it is the drug of choice for trigeminal neuralgia. Ethosuximide and trimethadione act on T-type calcium channels and are useful only in absence seizures.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.198 Q6, CNS Pharmacology: Anti-convulsants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-valproic-acid-oxazolidinediones-benzod-989532ed4c', 'pharm-valproic-acid-oxazolidinediones-benzodiazepines', 'mcq', 'Sodium valproate is:', '["An inducer of the hepatic microsomal enzyme system", "A dopamine antagonist", "Safe in pregnancy", "Effective against absence seizures", "Metabolised to phenobarbital"]'::jsonb, 'Effective against absence seizures', '[]'::jsonb, 'Valproate is a broad-spectrum antiepileptic effective in absence, myoclonic, tonic-clonic and focal seizures. It inhibits rather than induces hepatic drug metabolism, and it is the most teratogenic antiepileptic (neural tube defects). Primidone, not valproate, is metabolised to phenobarbital.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.198 Q7, CNS Pharmacology: Anti-convulsants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-valproic-acid-oxazolidinediones-benzod-972da5ac9f', 'pharm-valproic-acid-oxazolidinediones-benzodiazepines', 'mcq', 'Which of the following drug groups has an anticonvulsant effect?', '["Tricyclic antidepressants", "Opioid analgesics", "Phenothiazines", "Monoamine oxidase inhibitors", "Benzodiazepines"]'::jsonb, 'Benzodiazepines', '[]'::jsonb, 'Benzodiazepines enhance GABA-A mediated chloride conductance and so suppress seizure spread; diazepam and lorazepam are first-line in status epilepticus, with clonazepam used for myoclonic seizures. Tricyclic antidepressants and phenothiazines do the opposite: they lower the seizure threshold.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.198 Q8, CNS Pharmacology: Anti-convulsants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-2656da17a3', 'pharm-antidepressants-and-lithium', 'mcq', 'Which antidepressant drug is NOT appropriately matched with its mechanism of action?', '["Brexanolone: GABA-A receptor modulator", "Duloxetine: selective serotonin reuptake inhibitor", "Trazodone: postsynaptic 5-HT2A receptor antagonist", "Isocarboxazid: monoamine oxidase inhibitor", "Mirtazapine: presynaptic alpha-2 adrenoceptor antagonist"]'::jsonb, 'Duloxetine: selective serotonin reuptake inhibitor', '[]'::jsonb, 'Duloxetine, like venlafaxine, is a serotonin-noradrenaline reuptake inhibitor (SNRI): it blocks both transporters, which is why it also helps neuropathic pain. The other pairings are correct, including brexanolone, a neurosteroid GABA-A modulator used for postpartum depression.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.198 Q2, CNS Pharmacology: Anti-depressants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-d6c27eaef1', 'pharm-antidepressants-and-lithium', 'mcq', 'All of the following are true of the selective serotonin reuptake inhibitors (SSRIs) EXCEPT:', '["They usually require 2 weeks or more to produce a significant improvement in mood", "The absorption of sertraline is enhanced by food", "Paroxetine may cause significant weight gain", "Sertraline is recommended for depressed patients with excessive somnolence", "Fluoxetine has the highest risk of causing the SSRI discontinuation syndrome"]'::jsonb, 'Fluoxetine has the highest risk of causing the SSRI discontinuation syndrome', '[]'::jsonb, 'Fluoxetine and its active metabolite norfluoxetine have very long half-lives, so the drug tapers itself and carries the lowest risk of a discontinuation syndrome. The risk is highest with short half-life agents, especially paroxetine. The remaining statements are accepted features of the class.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.199 Q3, CNS Pharmacology: Anti-depressants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-faccee9315', 'pharm-antidepressants-and-lithium', 'mcq', 'Which is NOT an adverse effect of amitriptyline?', '["Dry mouth", "Blurred vision", "Constipation", "Sedation", "Urinary incontinence"]'::jsonb, 'Urinary incontinence', '[]'::jsonb, 'Amitriptyline is strongly antimuscarinic, so it relaxes the detrusor and causes urinary retention, not incontinence; this is why tricyclics are used for enuresis. Dry mouth, blurred vision and constipation are the same atropine-like effects, and sedation comes from H1 blockade.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.199 Q4, CNS Pharmacology: Anti-depressants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-c400fdde3c', 'pharm-antidepressants-and-lithium', 'mcq', 'Which of the following drugs has no role in the treatment of mania?', '["Carbamazepine", "Lithium carbonate", "Trazodone", "Olanzapine", "Sodium valproate"]'::jsonb, 'Trazodone', '[]'::jsonb, 'Trazodone is an antidepressant; like other antidepressants it can precipitate a switch into mania in bipolar patients. Lithium, valproate, carbamazepine and atypical antipsychotics such as olanzapine are all established antimanic agents, and lithium remains the standard for long-term prophylaxis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.199 Q5, CNS Pharmacology: Anti-depressants. Replaced the option ''Lamotrigine'' (ineffective in acute mania, so a second defensible answer) with ''Olanzapine''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-136168ce91', 'pharm-antidepressants-and-lithium', 'mcq', 'Which drug is a tricyclic antidepressant?', '["Escitalopram", "Imipramine", "Fluvoxamine", "Sertraline", "Fluoxetine"]'::jsonb, 'Imipramine', '[]'::jsonb, 'Imipramine is the prototype tricyclic antidepressant, blocking reuptake of noradrenaline and serotonin and also muscarinic, H1 and alpha-1 receptors. Escitalopram, fluvoxamine, sertraline and fluoxetine are all selective serotonin reuptake inhibitors with far fewer receptor-blocking effects.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.199 Q6, CNS Pharmacology: Anti-depressants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-272afb7877', 'pharm-antidepressants-and-lithium', 'mcq', 'Which statement regarding antidepressants is true?', '["Amitriptyline is non-sedative", "Peripheral neuropathy is a common amitriptyline-induced adverse effect", "Fluoxetine inhibits reuptake of both 5-hydroxytryptamine and noradrenaline", "Bupropion is used in the treatment of nicotine dependence", "Overdose of SSRIs is more dangerous than that of tricyclic antidepressants"]'::jsonb, 'Bupropion is used in the treatment of nicotine dependence', '[]'::jsonb, 'Bupropion inhibits dopamine and noradrenaline reuptake and is licensed as an aid to smoking cessation. Tricyclic overdose is far more dangerous than SSRI overdose because of arrhythmias, convulsions and coma; amitriptyline is strongly sedating and is in fact used to treat neuropathic pain.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.199 Q7, CNS Pharmacology: Anti-depressants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-a66cc82c80', 'pharm-antidepressants-and-lithium', 'mcq', 'Tricyclic antidepressants produce all of the following EXCEPT:', '["Inhibition of reuptake of norepinephrine and 5-HT by nerve terminals", "Inhibition of the monoamine oxidase enzyme", "Atropine-like effects", "H1-receptor blocking effect", "Alpha-1 adrenoceptor blocking effects"]'::jsonb, 'Inhibition of the monoamine oxidase enzyme', '[]'::jsonb, 'Tricyclics block the neuronal reuptake transporters for noradrenaline and serotonin; they do not inhibit monoamine oxidase, which is the action of drugs such as phenelzine. Their muscarinic, H1 and alpha-1 blockade explains dry mouth, sedation and postural hypotension.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.199 Q8, CNS Pharmacology: Anti-depressants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-d1cd9bff81', 'pharm-antidepressants-and-lithium', 'mcq', 'Which of the following is INCORRECTLY matched?', '["Fluoxetine: selective serotonin reuptake inhibitor", "Maprotiline: blocks noradrenaline uptake", "Cocaine: blocks uptake-1 of noradrenaline", "Amineptine: blocks dopamine uptake", "Desipramine: inhibits monoamine oxidase"]'::jsonb, 'Desipramine: inhibits monoamine oxidase', '[]'::jsonb, 'Desipramine is a tricyclic antidepressant that selectively blocks neuronal noradrenaline reuptake; it has no action on monoamine oxidase. The other pairs are correct: maprotiline is a noradrenaline-selective uptake blocker and amineptine a dopamine uptake inhibitor.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.199 Q9, CNS Pharmacology: Anti-depressants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-30a471d096', 'pharm-antidepressants-and-lithium', 'mcq', 'Eating cheese can precipitate a hypertensive crisis in a patient treated with which of the following drugs?', '["Phenothiazines", "Benzodiazepines", "Tricyclic antidepressants", "Monoamine oxidase inhibitors", "Hypnotics"]'::jsonb, 'Monoamine oxidase inhibitors', '[]'::jsonb, 'Tyramine in mature cheese is normally destroyed by monoamine oxidase A in the gut wall and liver. With an MAO inhibitor it reaches sympathetic nerve endings and releases the enlarged stores of noradrenaline, producing a hypertensive crisis. Tricyclics instead block tyramine uptake into the neurone.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.200 Q10, CNS Pharmacology: Anti-depressants') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-466160f4ad', 'pharm-sedative-hypnotic-drugs', 'mcq', 'Which statement concerning the barbiturates is accurate?', '["Respiratory depression caused by barbiturate overdosage can be reversed by flumazenil", "Alkalinisation of the urine accelerates the elimination of phenobarbital", "Barbiturates may increase the half-lives of drugs metabolised by the liver", "Abstinence syndromes are more severe during withdrawal from phenobarbital than from secobarbital", "Compared with barbiturates, the benzodiazepines exhibit a steeper dose-response relationship"]'::jsonb, 'Alkalinisation of the urine accelerates the elimination of phenobarbital', '[]'::jsonb, 'Phenobarbital is a weak acid; alkaline urine ionises it and traps it in the tubule, speeding excretion. Flumazenil antagonises only the benzodiazepine site. Barbiturates induce liver enzymes, so they shorten other drugs'' half-lives, and withdrawal is worse with short-acting agents.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.200 Q1, CNS Pharmacology: Sedatives and anxiolytics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-2dab1691e8', 'pharm-sedative-hypnotic-drugs', 'mcq', 'Indications for benzodiazepines include the following EXCEPT:', '["Anxiety disorders", "Pre-anaesthetic medication", "Seizures", "Narcolepsy", "Panic disorder"]'::jsonb, 'Narcolepsy', '[]'::jsonb, 'Narcolepsy is a disorder of excessive daytime sleepiness treated with CNS stimulants such as modafinil or methylphenidate; a sedative would worsen it. Benzodiazepines are used for anxiety and panic disorders, premedication, seizures, insomnia and alcohol withdrawal.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.200 Q3, CNS Pharmacology: Sedatives and anxiolytics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-7c018b57ae', 'pharm-sedative-hypnotic-drugs', 'mcq', 'Which statement is accurate?', '["Clonazepam is a useful antiseizure drug", "Symptoms of alcohol withdrawal may be alleviated by buspirone", "Ramelteon is used in status epilepticus", "Diazepam is a drug of choice for bipolar affective disorder", "Alprazolam is effective in obsessive-compulsive disorder"]'::jsonb, 'Clonazepam is a useful antiseizure drug', '[]'::jsonb, 'Clonazepam is a long-acting benzodiazepine used in absence and myoclonic seizures. Buspirone lacks cross-tolerance with alcohol and has no anticonvulsant action, so it cannot treat alcohol withdrawal; ramelteon is a melatonin receptor agonist hypnotic with no antiseizure effect.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.200 Q4, CNS Pharmacology: Sedatives and anxiolytics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-d63e22ec5a', 'pharm-sedative-hypnotic-drugs', 'mcq', 'The mechanism of action of zolpidem is:', '["Blockade of the action of glutamic acid", "Inhibition of GABA aminotransferase", "Activation of GABA-B receptors", "Antagonism of glycine receptors in the spinal cord", "Increased GABA-mediated chloride ion conductance"]'::jsonb, 'Increased GABA-mediated chloride ion conductance', '[]'::jsonb, 'Zolpidem is not a benzodiazepine chemically, but it binds the benzodiazepine site of GABA-A receptors containing the alpha-1 subunit and increases GABA-mediated chloride conductance. Baclofen activates GABA-B receptors, and vigabatrin is the drug that inhibits GABA aminotransferase.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.201 Q5, CNS Pharmacology: Sedatives and anxiolytics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-5cad5698be', 'pharm-sedative-hypnotic-drugs', 'mcq', 'All of the following are true of diazepam EXCEPT:', '["It causes physical dependence", "It is an anticonvulsant", "It is a controlled substance", "It reduces anxiety", "It acts on nicotinic receptors in the brain"]'::jsonb, 'It acts on nicotinic receptors in the brain', '[]'::jsonb, 'Diazepam binds the benzodiazepine site of the GABA-A receptor and increases the frequency of chloride channel opening; it has no action on nicotinic receptors. It is anxiolytic, anticonvulsant and muscle relaxant, and long-term use produces dependence, hence its controlled status.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.201 Q6, CNS Pharmacology: Sedatives and anxiolytics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-8fab44ff60', 'pharm-sedative-hypnotic-drugs', 'mcq', 'Benzodiazepines can produce the following effects on the CNS EXCEPT:', '["Anxiolytic", "Anticonvulsant", "Hypnotic", "Akathisia", "Muscle relaxant"]'::jsonb, 'Akathisia', '[]'::jsonb, 'Akathisia, a distressing motor restlessness, is an extrapyramidal effect of dopamine D2 antagonists such as haloperidol; benzodiazepines are actually used to relieve it. Their own actions are anxiolytic, sedative-hypnotic, anticonvulsant, centrally muscle relaxant and amnesic.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.201 Q8, CNS Pharmacology: Sedatives and anxiolytics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-e4719e4e58', 'pharm-sedative-hypnotic-drugs', 'mcq', 'Benzodiazepines produce their actions on the CNS by:', '["Blocking the chloride channel associated with the GABA-A receptor", "Potentiating the effect of GABA on GABA-A receptors", "Reducing the effect of GABA on GABA-A receptors", "Acting as agonists at GABA-B receptors", "Acting as antagonists at GABA-B receptors"]'::jsonb, 'Potentiating the effect of GABA on GABA-A receptors', '[]'::jsonb, 'Benzodiazepines are positive allosteric modulators of the GABA-A receptor: they increase the frequency of chloride channel opening in response to GABA but do nothing without it. Picrotoxin blocks the chloride channel, and baclofen is the GABA-B agonist.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.201 Q9, CNS Pharmacology: Sedatives and anxiolytics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-8957609073', 'pharm-sedative-hypnotic-drugs', 'mcq', 'Which of the following benzodiazepines has the shortest elimination half-life?', '["Diazepam", "Alprazolam", "Triazolam", "Lorazepam", "Nitrazepam"]'::jsonb, 'Triazolam', '[]'::jsonb, 'Triazolam has a half-life of only 2 to 4 hours and no active metabolites, so it is used for sleep-onset insomnia. Alprazolam and lorazepam are intermediate (10 to 20 hours), while diazepam is long-acting through its metabolite desmethyldiazepam.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.201 Q10, CNS Pharmacology: Sedatives and anxiolytics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-0a151d7a3c', 'pharm-sedative-hypnotic-drugs', 'mcq', 'Which of the following benzodiazepines is a prodrug?', '["Temazepam", "Lorazepam", "Oxazepam", "Clorazepate", "Triazolam"]'::jsonb, 'Clorazepate', '[]'::jsonb, 'Clorazepate is inactive until it is decarboxylated in the acid of the stomach to desmethyldiazepam (nordazepam), which is then absorbed. Lorazepam, oxazepam and temazepam are active as given and are simply conjugated to inactive glucuronides.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.202 Q11, CNS Pharmacology: Sedatives and anxiolytics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-10b7b0eb31', 'pharm-sedative-hypnotic-drugs', 'mcq', 'All of the following drugs are used for the treatment of anxiety EXCEPT:', '["Buspirone", "Alprazolam", "Oxazepam", "Amantadine", "Clorazepate"]'::jsonb, 'Amantadine', '[]'::jsonb, 'Amantadine is an antiviral that also enhances dopaminergic transmission and blocks NMDA receptors; it is used in Parkinson''s disease, not anxiety. Buspirone is a 5-HT1A partial agonist anxiolytic and the other three are benzodiazepines.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.202 Q12, CNS Pharmacology: Sedatives and anxiolytics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-3320f0230c', 'pharm-sedative-hypnotic-drugs', 'mcq', 'Which of the following drugs acts as a competitive benzodiazepine receptor antagonist?', '["Naloxone", "Flumazenil", "Flurazepam", "Flunitrazepam", "Disulfiram"]'::jsonb, 'Flumazenil', '[]'::jsonb, 'Flumazenil competes for the benzodiazepine binding site on the GABA-A receptor and reverses benzodiazepine sedation and overdose; its short half-life means sedation can return. Naloxone is the corresponding antagonist at opioid receptors, while flurazepam and flunitrazepam are benzodiazepine agonists.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.202 Q13, CNS Pharmacology: Sedatives and anxiolytics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-b758c4bcfc', 'pharm-sedative-hypnotic-drugs', 'mcq', 'Benzodiazepines are used in the treatment of all of the following EXCEPT:', '["Anxiety", "Insomnia", "Epilepsy", "Alcohol withdrawal symptoms", "Acute migraine attacks"]'::jsonb, 'Acute migraine attacks', '[]'::jsonb, 'Acute migraine is treated with analgesics, triptans or ergot alkaloids, which act on the trigeminovascular system; benzodiazepines have no effect on it. Their cross-tolerance with ethanol makes them the standard treatment for alcohol withdrawal, alongside their anxiolytic, hypnotic and anticonvulsant uses.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.202 Q14, CNS Pharmacology: Sedatives and anxiolytics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-2c48cf0786', 'pharm-sedative-hypnotic-drugs', 'mcq', 'Disadvantages of benzodiazepines include the following EXCEPT:', '["Cardiac arrhythmias", "Tolerance", "Physical dependence", "Anterograde amnesia", "Confusion in the elderly"]'::jsonb, 'Cardiac arrhythmias', '[]'::jsonb, 'Benzodiazepines have very little effect on the cardiovascular system, which is one reason they are much safer in overdose than barbiturates or tricyclics. Their real drawbacks are tolerance, dependence with a withdrawal syndrome, anterograde amnesia, and confusion and falls in the elderly.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.202 Q15, CNS Pharmacology: Sedatives and anxiolytics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-b52f6ad450', 'pharm-sedative-hypnotic-drugs', 'mcq', 'The activity of hepatic microsomal drug-metabolising enzymes is NOT changed with continuous use of:', '["Carbamazepine", "Phenytoin", "Ethanol", "Benzodiazepines", "Barbiturates"]'::jsonb, 'Benzodiazepines', '[]'::jsonb, 'Benzodiazepines do not induce cytochrome P450 enzymes, so they cause few pharmacokinetic interactions. Carbamazepine, phenytoin and barbiturates are classic enzyme inducers, and chronic ethanol intake induces CYP2E1, so all four alter the metabolism of other drugs given with them.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.202 Q16, CNS Pharmacology: Sedatives and anxiolytics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-985a89d5d2', 'pharm-sedative-hypnotic-drugs', 'mcq', 'Which of the following anxiolytic drugs is an agonist at presynaptic 5-HT1A autoreceptors in the brain?', '["Diazepam", "Chlordiazepoxide", "Buspirone", "Clorazepate", "Alprazolam"]'::jsonb, 'Buspirone', '[]'::jsonb, 'Buspirone is a partial agonist at 5-HT1A receptors; it relieves generalised anxiety after a delay of one to two weeks without sedation, muscle relaxation or dependence. The other four are benzodiazepines, which act through the GABA-A receptor.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.203 Q17, CNS Pharmacology: Sedatives and anxiolytics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-e011e79385', 'pharm-sedative-hypnotic-drugs', 'mcq', 'Which of the following hypnotics is converted to the active metabolite trichloroethanol in the liver?', '["Paraldehyde", "Pentobarbital", "Zolpidem", "Temazepam", "Chloral hydrate"]'::jsonb, 'Chloral hydrate', '[]'::jsonb, 'Chloral hydrate is a prodrug rapidly reduced by alcohol dehydrogenase to trichloroethanol, which produces the hypnotic effect. Paraldehyde is a separate old hypnotic that is partly exhaled unchanged, giving the breath a characteristic smell.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.203 Q18, CNS Pharmacology: Sedatives and anxiolytics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-4ff66b4df7', 'pharm-sedative-hypnotic-drugs', 'mcq', 'Which of the following drugs is a non-benzodiazepine sedative-hypnotic used for short-term treatment of insomnia?', '["Triazolam", "Zaleplon", "Flurazepam", "Temazepam", "Estazolam"]'::jsonb, 'Zaleplon', '[]'::jsonb, 'Zaleplon is one of the ''Z-drugs'' (with zolpidem and zopiclone): chemically unrelated to benzodiazepines but acting at the alpha-1 benzodiazepine site of GABA-A receptors, with a very short half-life of about one hour. The other options all end in ''-azolam'' or ''-azepam'' and are benzodiazepines.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.203 Q19, CNS Pharmacology: Sedatives and anxiolytics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pharmacologic-management-of-parkinsoni-9225a87985', 'pharm-pharmacologic-management-of-parkinsonism-and-other-movement-diso', 'mcq', 'Which antiparkinsonian drug has a preferential high affinity for the dopamine D3 receptor?', '["Ropinirole", "Bromocriptine", "Rotigotine", "Apomorphine", "Pramipexole"]'::jsonb, 'Pramipexole', '[]'::jsonb, 'Pramipexole is a non-ergot dopamine agonist described as having preferential affinity for the D3 member of the D2 receptor family. Bromocriptine is an ergot D2 agonist, and ropinirole is usually described as a relatively pure D2 agonist.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.203 Q1, CNS Pharmacology: Parkinson drugs. Textbook (Katzung) answer is pramipexole, but ropinirole and rotigotine also bind D3 with high affinity; added ''preferential'' to the stem.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pharmacologic-management-of-parkinsoni-43b4f0726a', 'pharm-pharmacologic-management-of-parkinsonism-and-other-movement-diso', 'mcq', 'Which statement is true of benztropine?', '["It improves the extrapyramidal symptoms caused by antipsychotic drugs", "It is well tolerated by elderly patients", "It is highly effective in the treatment of the bradykinesia of parkinsonism", "It worsens the rigidity of parkinsonism", "It improves the tardive dyskinesia that results from prolonged use of antipsychotic drugs"]'::jsonb, 'It improves the extrapyramidal symptoms caused by antipsychotic drugs', '[]'::jsonb, 'Benztropine is a centrally acting antimuscarinic that restores the dopamine-acetylcholine balance in the striatum, relieving drug-induced parkinsonism and acute dystonia. It helps tremor and rigidity more than bradykinesia, causes confusion in the elderly, and tends to worsen tardive dyskinesia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.203 Q2, CNS Pharmacology: Parkinson drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pharmacologic-management-of-parkinsoni-3437ce6a9e', 'pharm-pharmacologic-management-of-parkinsonism-and-other-movement-diso', 'mcq', 'Which dopamine receptor agonist causes severe nausea that requires pre-treatment with an antiemetic?', '["Rotigotine", "Ropinirole", "Bromocriptine", "Pramipexole", "Apomorphine"]'::jsonb, 'Apomorphine', '[]'::jsonb, 'Apomorphine is a potent dopamine agonist given subcutaneously for ''off'' episodes; it strongly stimulates the chemoreceptor trigger zone, so patients are pre-treated with an antiemetic such as domperidone or trimethobenzamide. The other agonists cause milder nausea that settles with dose titration.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.203 Q3, CNS Pharmacology: Parkinson drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pharmacologic-management-of-parkinsoni-4fc969c067', 'pharm-pharmacologic-management-of-parkinsonism-and-other-movement-diso', 'mcq', 'All of the following are true of levodopa EXCEPT:', '["It causes miosis", "It is broken down by DOPA decarboxylase peripherally", "It is readily and rapidly absorbed orally", "Its most common adverse effects are gastrointestinal", "It is indicated for parkinsonism"]'::jsonb, 'It causes miosis', '[]'::jsonb, 'Levodopa is converted to dopamine and then noradrenaline, so it causes mydriasis, not miosis, and can precipitate acute glaucoma. It is rapidly absorbed from the small intestine, extensively decarboxylated in the periphery, and nausea and vomiting are its commonest early adverse effects.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.204 Q4, CNS Pharmacology: Parkinson drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pharmacologic-management-of-parkinsoni-69864c98fc', 'pharm-pharmacologic-management-of-parkinsonism-and-other-movement-diso', 'mcq', 'Adverse effects of levodopa include all of the following EXCEPT:', '["Anorexia, nausea and vomiting", "Cardiac arrhythmias", "Postural hypotension", "Bronchoconstriction", "Involuntary choreiform movements"]'::jsonb, 'Bronchoconstriction', '[]'::jsonb, 'Levodopa does not constrict the bronchi. Peripheral dopamine formation causes nausea, arrhythmias (beta-1 stimulation) and postural hypotension, while central dopamine excess produces choreiform dyskinesias and psychiatric effects. Giving carbidopa reduces the peripheral effects but not the dyskinesias.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.204 Q5, CNS Pharmacology: Parkinson drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pharmacologic-management-of-parkinsoni-977c296504', 'pharm-pharmacologic-management-of-parkinsonism-and-other-movement-diso', 'mcq', 'Which of the following is a selective inhibitor of monoamine oxidase B?', '["Bromocriptine", "Carbidopa", "Selegiline", "Trihexyphenidyl", "Benserazide"]'::jsonb, 'Selegiline', '[]'::jsonb, 'Selegiline irreversibly inhibits MAO-B, the isoform that breaks down dopamine in the striatum, so it prolongs the effect of levodopa without causing the ''cheese reaction'' at normal doses. Carbidopa and benserazide inhibit peripheral dopa decarboxylase instead.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.204 Q6, CNS Pharmacology: Parkinson drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pharmacologic-management-of-parkinsoni-72a385c2e8', 'pharm-pharmacologic-management-of-parkinsonism-and-other-movement-diso', 'mcq', 'Agents useful in the therapy of parkinsonism include all of the following EXCEPT:', '["Haloperidol", "Carbidopa/levodopa", "Bromocriptine", "Amantadine", "Tolcapone"]'::jsonb, 'Haloperidol', '[]'::jsonb, 'Haloperidol blocks striatal D2 receptors and is a classic cause of drug-induced parkinsonism, so it worsens the disease. The others all boost dopaminergic transmission: levodopa as a precursor, bromocriptine as an agonist, amantadine by releasing dopamine and tolcapone by inhibiting COMT.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.204 Q7, CNS Pharmacology: Parkinson drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pharmacologic-management-of-parkinsoni-6216559338', 'pharm-pharmacologic-management-of-parkinsonism-and-other-movement-diso', 'mcq', 'Ankle oedema together with livedo reticularis is a characteristic side effect of which antiparkinsonian drug?', '["Levodopa", "Bromocriptine", "Pergolide", "Amantadine", "Ropinirole"]'::jsonb, 'Amantadine', '[]'::jsonb, 'Amantadine characteristically causes livedo reticularis, a mottled purplish skin discolouration of the legs, often with ankle oedema; both clear when the drug is stopped. Dopamine agonists can cause peripheral oedema too, but not livedo reticularis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.204 Q8, CNS Pharmacology: Parkinson drugs. Added ''together with livedo reticularis'' to the stem, because dopamine agonists also cause ankle oedema.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pharmacologic-management-of-parkinsoni-8ef9803414', 'pharm-pharmacologic-management-of-parkinsonism-and-other-movement-diso', 'mcq', 'In the absence of carbidopa, the therapeutic effect of levodopa may be reduced by:', '["Bromocriptine", "Benztropine", "Pyridoxine (vitamin B6)", "Cyanocobalamin (vitamin B12)", "Trihexyphenidyl"]'::jsonb, 'Pyridoxine (vitamin B6)', '[]'::jsonb, 'Pyridoxine is the cofactor for dopa decarboxylase, so extra vitamin B6 speeds the peripheral conversion of levodopa to dopamine and less reaches the brain. Carbidopa inhibits the enzyme and abolishes this interaction. The other drugs listed add to levodopa''s benefit.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.204 Q9, CNS Pharmacology: Parkinson drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pharmacologic-management-of-parkinsoni-89a4f5e703', 'pharm-pharmacologic-management-of-parkinsonism-and-other-movement-diso', 'mcq', 'Carbidopa:', '["Is a peripheral dopa decarboxylase inhibitor", "Is a selective inhibitor of monoamine oxidase type A", "Is a selective inhibitor of monoamine oxidase type B", "Promotes regeneration of dopaminergic neurones", "Prevents the breakdown of dopamine"]'::jsonb, 'Is a peripheral dopa decarboxylase inhibitor', '[]'::jsonb, 'Carbidopa inhibits aromatic L-amino acid (dopa) decarboxylase but does not cross the blood-brain barrier, so it blocks only the peripheral conversion of levodopa to dopamine. This cuts the levodopa dose needed by about 75% and reduces nausea and arrhythmias. Selegiline is the MAO-B inhibitor.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.205 Q10, CNS Pharmacology: Parkinson drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-b60fee09a0', 'pharm-major-tranquilizer', 'mcq', 'Chlorpromazine does NOT cause:', '["Jaundice", "Nasal stuffiness", "Urticaria", "Leucocytosis", "Photosensitivity"]'::jsonb, 'Leucocytosis', '[]'::jsonb, 'Chlorpromazine can depress the bone marrow, causing leucopenia or rarely agranulocytosis, never a raised white cell count. Cholestatic jaundice, urticaria and photosensitivity are hypersensitivity-type reactions to it, and nasal stuffiness follows from alpha-1 adrenoceptor blockade.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.205 Q1, CNS Pharmacology: Anti-psychotics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-4e0eb343f8', 'pharm-major-tranquilizer', 'mcq', 'Which one of the following is an atypical antipsychotic?', '["Thioridazine", "Aripiprazole", "Haloperidol", "Fluphenazine", "Thiothixene"]'::jsonb, 'Aripiprazole', '[]'::jsonb, 'Aripiprazole is a second-generation (atypical) antipsychotic acting as a D2 partial agonist with 5-HT2A antagonism, giving few extrapyramidal effects. Thioridazine and fluphenazine are phenothiazines, haloperidol a butyrophenone and thiothixene a thioxanthene: all typical agents.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.205 Q2, CNS Pharmacology: Anti-psychotics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-d8d51df0e2', 'pharm-major-tranquilizer', 'mcq', 'All of the following are true differences between chlorpromazine and haloperidol EXCEPT:', '["Haloperidol has less anticholinergic activity", "Haloperidol has more alpha-blocking activity", "Haloperidol is less sedating", "Haloperidol causes less weight gain", "Haloperidol has higher potency"]'::jsonb, 'Haloperidol has more alpha-blocking activity', '[]'::jsonb, 'Haloperidol is a high-potency butyrophenone with little alpha-1, muscarinic or H1 blockade, so it causes less hypotension, sedation and weight gain than chlorpromazine but more extrapyramidal effects. Chlorpromazine is the one with marked alpha-blocking activity and postural hypotension.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.205 Q3, CNS Pharmacology: Anti-psychotics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-bf6c1c6bd2', 'pharm-major-tranquilizer', 'mcq', 'Which one of the following is NOT a high-potency antipsychotic?', '["Haloperidol", "Olanzapine", "Fluphenazine", "Risperidone", "Chlorpromazine"]'::jsonb, 'Chlorpromazine', '[]'::jsonb, 'Chlorpromazine is the prototype low-potency antipsychotic: daily doses are in the hundreds of milligrams, with prominent sedation, antimuscarinic effects and hypotension. Haloperidol, fluphenazine, risperidone and olanzapine are effective at a few milligrams a day.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.205 Q5, CNS Pharmacology: Anti-psychotics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-ce9831c4bc', 'pharm-major-tranquilizer', 'mcq', 'Which of the following antipsychotic drugs has the highest affinity for dopamine D2 receptors?', '["Olanzapine", "Aripiprazole", "Quetiapine", "Clozapine", "Chlorpromazine"]'::jsonb, 'Aripiprazole', '[]'::jsonb, 'Aripiprazole binds D2 receptors with very high affinity but as a partial agonist, which stabilises dopaminergic tone rather than fully blocking it. Clozapine and quetiapine have low D2 affinity and dissociate quickly, which explains their minimal extrapyramidal effects.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.205 Q4, CNS Pharmacology: Anti-psychotics. Stem reworded from ''Which tranquilizer has a high affinity for D2 receptors?''; chlorpromazine and olanzapine also bind D2 reasonably well, so the intended answer is uncertain.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-8665bd1c88', 'pharm-major-tranquilizer', 'mcq', 'Therapeutic uses of phenothiazines include all of the following EXCEPT:', '["Schizophrenia", "Vomiting", "Pruritus", "Intractable hiccup", "Petit mal epilepsy"]'::jsonb, 'Petit mal epilepsy', '[]'::jsonb, 'Phenothiazines lower the seizure threshold, so they have no place in epilepsy and can provoke fits. They are used as antipsychotics, as antiemetics (D2 blockade at the chemoreceptor trigger zone), for pruritus (H1 blockade, e.g. promethazine) and chlorpromazine for intractable hiccup.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.206 Q6, CNS Pharmacology: Anti-psychotics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-044a300939', 'pharm-major-tranquilizer', 'mcq', 'Phenothiazine antipsychotics increase the secretion of:', '["Growth hormone", "Prolactin", "Thyroxine", "Insulin", "Corticotropin-releasing hormone"]'::jsonb, 'Prolactin', '[]'::jsonb, 'Dopamine from the tuberoinfundibular pathway tonically inhibits prolactin release through D2 receptors on pituitary lactotrophs. Phenothiazines block these receptors, causing hyperprolactinaemia with galactorrhoea, amenorrhoea and gynaecomastia. Growth hormone secretion, if anything, falls, and the other hormones listed are not under dopaminergic control.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.206 Q7, CNS Pharmacology: Anti-psychotics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-7dca34f33b', 'pharm-major-tranquilizer', 'mcq', 'Neurological side effects of neuroleptic drugs include:', '["Parkinsonism", "Akathisia", "Acute dystonic reactions", "Tardive dyskinesia", "All of the above"]'::jsonb, 'All of the above', '[]'::jsonb, 'Blockade of D2 receptors in the nigrostriatal pathway produces all four extrapyramidal syndromes: acute dystonia within days, akathisia and parkinsonism within weeks, and tardive dyskinesia after months to years, attributed to dopamine receptor supersensitivity. They are commonest with high-potency typical agents such as haloperidol.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.206 Q8, CNS Pharmacology: Anti-psychotics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-ba90e5641c', 'pharm-major-tranquilizer', 'mcq', 'Unwanted endocrine effects of phenothiazine neuroleptics include all of the following EXCEPT:', '["Amenorrhoea", "Nephrogenic diabetes insipidus", "Galactorrhoea", "Gynaecomastia", "Loss of libido in men"]'::jsonb, 'Nephrogenic diabetes insipidus', '[]'::jsonb, 'Nephrogenic diabetes insipidus is an adverse effect of lithium, which uncouples the V2 receptor from adenylyl cyclase in the collecting duct. The phenothiazine endocrine effects all stem from hyperprolactinaemia due to D2 blockade: amenorrhoea, galactorrhoea, gynaecomastia and reduced libido.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.206 Q9, CNS Pharmacology: Anti-psychotics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-a2037d0a9c', 'pharm-antidepressants-and-lithium', 'mcq', 'Which is correct regarding lithium carbonate?', '["It is an antimanic mood-stabilising agent", "It produces polydipsia, polyuria and hypothyroidism as side effects", "Monitoring of the plasma level is indicated", "Its renal clearance is reduced by hydrochlorothiazide", "All of the above"]'::jsonb, 'All of the above', '[]'::jsonb, 'Lithium is a mood stabiliser with a narrow therapeutic range (about 0.6 to 1.2 mmol/L), so levels must be monitored. It causes nephrogenic diabetes insipidus and hypothyroidism. Thiazides cause sodium depletion, which increases proximal reabsorption of lithium and can produce toxicity.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.206 Q10, CNS Pharmacology: Anti-psychotics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-addiction-and-abuse-addiction-to--31d7f6d9d4', 'pharm-drug-addiction-and-abuse-addiction-to-cannabinoids-inhalants', 'mcq', 'Death from the use of inhalational drugs of abuse usually results from the following EXCEPT:', '["Hyperkalaemia", "Direct toxicity", "Gastric aspiration", "Anoxia", "Related trauma"]'::jsonb, 'Hyperkalaemia', '[]'::jsonb, 'Deaths from solvent and inhalant abuse are due to direct cardiac toxicity (sudden sniffing death from arrhythmia), anoxia or suffocation, aspiration of vomit, and accidents while intoxicated. Hyperkalaemia is not a feature; chronic toluene abuse in fact tends to cause hypokalaemia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.206 Q1, CNS Pharmacology: Addiction. Same question repeated as Q9 on p.208; kept once.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-addiction-and-abuse-addiction-to--6c0265a9d1', 'pharm-drug-addiction-and-abuse-addiction-to-cannabinoids-inhalants', 'mcq', 'Chronic cannabinoid use causes the following EXCEPT:', '["Apathetic (amotivational) syndrome", "Bradycardia", "Hypertension", "Angina", "Psychosis"]'::jsonb, 'Bradycardia', '[]'::jsonb, 'Cannabis characteristically produces tachycardia, which raises myocardial oxygen demand and can provoke angina in people with coronary disease. Long-term heavy use is associated with an amotivational syndrome and with psychosis, especially in adolescents and those predisposed to schizophrenia.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.207 Q2, CNS Pharmacology: Addiction. Intended answer bradycardia, but tolerance to the tachycardia (and even bradycardia) is described with chronic heavy use, and cannabis more often causes postural hypotension than hypertension.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-addiction-to-opioids-cocaine-amphetami-1ae506304b', 'pharm-addiction-to-opioids-cocaine-amphetamines', 'mcq', 'Which is NOT a symptom of the opioid withdrawal syndrome?', '["Mydriasis", "Constipation", "Lacrimation", "Dysphoria", "Rhinorrhoea"]'::jsonb, 'Constipation', '[]'::jsonb, 'Withdrawal is the mirror image of opioid effects: opioids constipate, so withdrawal brings diarrhoea and abdominal cramps. Dilated pupils, lacrimation, rhinorrhoea, yawning, gooseflesh and dysphoria are all typical features of the abstinence syndrome.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.207 Q4, CNS Pharmacology: Addiction') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-addiction-to-opioids-cocaine-amphetami-49dd3f039e', 'pharm-addiction-to-opioids-cocaine-amphetamines', 'mcq', 'Which statement regarding cocaine is FALSE?', '["It increases dopaminergic stimulation in the brain", "It blocks serotonin reuptake", "It causes arousal", "It causes drowsiness", "It blocks norepinephrine reuptake"]'::jsonb, 'It causes drowsiness', '[]'::jsonb, 'Cocaine blocks the reuptake transporters for dopamine, noradrenaline and serotonin, producing euphoria, arousal, alertness and insomnia, the opposite of drowsiness. Drowsiness and depression appear only in the ''crash'' after the drug wears off.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.207 Q5, CNS Pharmacology: Addiction. Options b and e reworded from ''Blocks serotonin/norepinephrine'' to ''...reuptake''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-addiction-and-abuse-addiction-to--47af7d1912', 'pharm-drug-addiction-and-abuse-addiction-to-cannabinoids-inhalants', 'mcq', 'Withdrawal from cannabinoids may present with the following EXCEPT:', '["Irritability", "Insomnia", "Nausea", "ECG changes", "Muscle cramps"]'::jsonb, 'ECG changes', '[]'::jsonb, 'Cannabis withdrawal is mild and largely subjective: irritability, restlessness, insomnia, loss of appetite, nausea and cramps, peaking within the first week. It does not produce objective cardiac or ECG changes, unlike the autonomic storm of alcohol or opioid withdrawal.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.207 Q6, CNS Pharmacology: Addiction. Lecture-based list; ECG changes is the clear outlier but the precise list of withdrawal symptoms varies between sources.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-addiction-and-abuse-addiction-to--ec94884a9e', 'pharm-drug-addiction-and-abuse-addiction-to-cannabinoids-inhalants', 'mcq', 'Cannabis sativa (bhang) causes the following EXCEPT:', '["Grandiosity", "Euphoria", "Memory improvement", "Pain relief", "Visual distortions"]'::jsonb, 'Memory improvement', '[]'::jsonb, 'THC acts on CB1 receptors, which are dense in the hippocampus, and impairs short-term memory and learning. Euphoria, altered perception including visual distortions, a sense of grandiosity and analgesia are all recognised effects of cannabis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.207 Q7, CNS Pharmacology: Addiction') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-addiction-to-opioids-cocaine-amphetami-fa23afe2ea', 'pharm-addiction-to-opioids-cocaine-amphetamines', 'mcq', 'Which drug is NOT used in the treatment of heroin addiction?', '["Levomethadyl acetate", "Naltrexone", "Heroin", "Methadone", "Buprenorphine"]'::jsonb, 'Heroin', '[]'::jsonb, 'Maintenance therapy replaces heroin with a long-acting oral or sublingual opioid (methadone, levomethadyl acetate or buprenorphine) that prevents withdrawal without the ''rush''. Naltrexone, an oral antagonist, is used to prevent relapse after detoxification.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.208 Q8, CNS Pharmacology: Addiction. Paper''s option was ''Naloxone'' (used for overdose and combined with buprenorphine, but not itself a treatment of addiction); changed to naltrexone. Supervised heroin (diamorphine) prescribing does exist in a few countries. Similar question at p.207 Q3 dropped as a duplicate.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cytoprotective-agents-bismuth-compound-be90c5066b', 'pharm-cytoprotective-agents-bismuth-compounds-sucralfate-etc', 'mcq', 'Healing of peptic ulcers is promoted by all of the following EXCEPT:', '["Sucralfate", "Colloidal bismuth compounds", "Carbenoxolone", "Indomethacin", "Misoprostol"]'::jsonb, 'Indomethacin', '[]'::jsonb, 'Indomethacin is an NSAID: by inhibiting COX-1 it removes the protective prostaglandins that maintain mucus, bicarbonate and mucosal blood flow, so it causes ulcers. Misoprostol replaces those prostaglandins, while sucralfate, bismuth and carbenoxolone strengthen the mucosal barrier.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.209 Q5, GIT Pharmacology: PUD drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-git-pharmacology-class-df380d0f56', 'pharm-introduction-to-git-pharmacology-classification-of-drugs-for-pep', 'mcq', 'Drugs used in the treatment of peptic ulcer include all of the following EXCEPT:', '["H1 receptor antagonists", "H2 receptor antagonists", "Anticholinergic drugs", "Proton pump inhibitors", "Colloidal bismuth compounds"]'::jsonb, 'H1 receptor antagonists', '[]'::jsonb, 'Histamine stimulates the parietal cell through H2 receptors, so only H2 antagonists such as ranitidine reduce acid. H1 antagonists are antiallergic drugs with no effect on acid secretion. Selective M1 anticholinergics like pirenzepine were formerly used for ulcers.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.209 Q6, GIT Pharmacology: PUD drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h2-receptor-antagonist-proton-pump-inh-0544d381f9', 'pharm-h2-receptor-antagonist-proton-pump-inhibitor', 'mcq', 'H2-receptor antagonists produce all of the following actions EXCEPT:', '["Inhibition of gastric acid secretion elicited by gastrin", "Inhibition of nocturnal gastric acid secretion", "Inhibition of gastric acid secretion stimulated by food", "Reduction in secretion of intrinsic factor", "Prolongation of gastric emptying time"]'::jsonb, 'Prolongation of gastric emptying time', '[]'::jsonb, 'H2 antagonists have no effect on gastric motility or emptying. They block histamine-driven acid secretion and so also blunt the response to gastrin and food, are especially effective against nocturnal basal secretion, and modestly reduce pepsin and intrinsic factor output.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.209 Q7, GIT Pharmacology: PUD drugs. Reduction of intrinsic factor is small and clinically insignificant, so some sources would regard option D as the exception.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h2-receptor-antagonist-proton-pump-inh-72241ae840', 'pharm-h2-receptor-antagonist-proton-pump-inhibitor', 'mcq', 'Famotidine is used in the treatment of all of the following EXCEPT:', '["Duodenal ulcer", "Gastric ulcer", "Reflux oesophagitis", "Colonic hypomotility", "Zollinger-Ellison syndrome"]'::jsonb, 'Colonic hypomotility', '[]'::jsonb, 'Famotidine is an H2 antagonist: it only lowers gastric acid, so it is useful in acid-related disease (ulcers, reflux, hypersecretory states). It has no prokinetic action on the colon; hypomotility needs prokinetic or laxative drugs.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.209 Q8, GIT Pharmacology: PUD drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h2-receptor-antagonist-proton-pump-inh-b4bcf04014', 'pharm-h2-receptor-antagonist-proton-pump-inhibitor', 'mcq', 'Adverse effects of cimetidine include all of the following EXCEPT:', '["Mental confusion in the elderly", "Reduced activity of warfarin", "Galactorrhoea", "Gynaecomastia", "Muscular pain"]'::jsonb, 'Reduced activity of warfarin', '[]'::jsonb, 'Cimetidine inhibits several cytochrome P450 enzymes, so it slows warfarin metabolism and increases its anticoagulant effect. Its antiandrogenic action and raised prolactin cause gynaecomastia and galactorrhoea, and confusion occurs in the elderly, especially with intravenous use.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.209 Q9, GIT Pharmacology: PUD drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h2-receptor-antagonist-proton-pump-inh-55e86ae8e5', 'pharm-h2-receptor-antagonist-proton-pump-inhibitor', 'mcq', 'Which of the following drugs inhibits H+/K+-ATPase in the gastric parietal cell?', '["Cimetidine", "Pirenzepine", "Sucralfate", "Carbenoxolone", "Pantoprazole"]'::jsonb, 'Pantoprazole', '[]'::jsonb, 'Pantoprazole is a proton pump inhibitor: it irreversibly blocks the H+/K+-ATPase, the final common step of acid secretion, whatever the stimulus. Cimetidine blocks only the histamine H2 input and pirenzepine only the muscarinic M1 input.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.210 Q11, GIT Pharmacology: PUD drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cytoprotective-agents-bismuth-compound-1e904915ad', 'pharm-cytoprotective-agents-bismuth-compounds-sucralfate-etc', 'mcq', 'Correct statements about sucralfate include all of the following EXCEPT that:', '["It contains aluminium", "It is a mucosal protective agent", "It is used for duodenal ulcer", "It may cause constipation", "It increases the bioavailability of quinolone antibiotics"]'::jsonb, 'It increases the bioavailability of quinolone antibiotics', '[]'::jsonb, 'Sucralfate binds quinolones, tetracyclines, digoxin and phenytoin in the gut lumen and reduces their absorption, so doses should be separated by two hours. Its aluminium content explains the constipation, the commonest adverse effect.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.210 Q12, GIT Pharmacology: PUD drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cytoprotective-agents-bismuth-compound-104f081182', 'pharm-cytoprotective-agents-bismuth-compounds-sucralfate-etc', 'mcq', 'Misoprostol is a synthetic analogue of:', '["PGD2", "PGE1", "PGE2", "PGF2-alpha", "PGI2"]'::jsonb, 'PGE1', '[]'::jsonb, 'Misoprostol is a stable methyl analogue of prostaglandin E1. It inhibits acid secretion and stimulates mucus and bicarbonate, and it contracts the uterus. Dinoprostone is the PGE2 preparation and epoprostenol is PGI2.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.210 Q13, GIT Pharmacology: PUD drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cytoprotective-agents-bismuth-compound-facffc5dbd', 'pharm-cytoprotective-agents-bismuth-compounds-sucralfate-etc', 'mcq', 'Which of the following is a side effect of misoprostol?', '["Sodium retention", "Insomnia", "Diarrhoea", "Hypertension", "Bronchoconstriction"]'::jsonb, 'Diarrhoea', '[]'::jsonb, 'Diarrhoea and cramping abdominal pain occur in 10 to 20% of patients because E-series prostaglandins stimulate intestinal secretion and motility. Misoprostol also contracts the uterus, so it is contraindicated in pregnancy unless abortion or induction is intended.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.210 Q14, GIT Pharmacology: PUD drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cytoprotective-agents-bismuth-compound-e5a87e7a97', 'pharm-cytoprotective-agents-bismuth-compounds-sucralfate-etc', 'mcq', 'Which of the following is used to prevent the development of NSAID-induced gastric ulcers?', '["Cisapride", "Ondansetron", "Domperidone", "Metoclopramide", "Misoprostol"]'::jsonb, 'Misoprostol', '[]'::jsonb, 'NSAIDs cause ulcers by depleting mucosal prostaglandins; misoprostol, a PGE1 analogue, replaces them and is licensed for prevention of NSAID-induced ulcers in high-risk patients. The other options are prokinetic or antiemetic drugs with no mucosal protective action.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.210 Q15, GIT Pharmacology: PUD drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cytoprotective-agents-bismuth-compound-45b02e126d', 'pharm-cytoprotective-agents-bismuth-compounds-sucralfate-etc', 'mcq', 'Which of the following drugs has an antibacterial effect against Helicobacter pylori in the gastroduodenal mucosa?', '["Pirenzepine", "Carbenoxolone", "Metoclopramide", "Tripotassium dicitrato bismuthate", "Aluminium hydroxide"]'::jsonb, 'Tripotassium dicitrato bismuthate', '[]'::jsonb, 'Colloidal bismuth (tripotassium dicitrato bismuthate) is directly bactericidal to H. pylori and prevents its adhesion to the mucosa, so it is part of quadruple eradication therapy. Carbenoxolone only increases mucus production and has no antibacterial effect.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.210 Q16, GIT Pharmacology: PUD drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-git-pharmacology-class-34e51c1730', 'pharm-introduction-to-git-pharmacology-classification-of-drugs-for-pep', 'mcq', 'Which antacid and adverse effect relationship is INCORRECT?', '["Sodium bicarbonate: systemic alkalosis", "Magnesium hydroxide: diarrhoea", "Magnesium trisilicate: increased digoxin absorption", "Aluminium hydroxide: hypophosphataemia", "Calcium carbonate: hypercalcaemia"]'::jsonb, 'Magnesium trisilicate: increased digoxin absorption', '[]'::jsonb, 'Antacids such as magnesium trisilicate adsorb digoxin and reduce, not increase, its absorption. The others are correct: absorbed bicarbonate causes alkalosis, magnesium salts are osmotic laxatives, aluminium binds phosphate in the gut, and calcium carbonate can cause milk-alkali syndrome.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.211 Q17, GIT Pharmacology: PUD drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-git-pharmacology-class-a3f5c534a3', 'pharm-introduction-to-git-pharmacology-classification-of-drugs-for-pep', 'mcq', 'Agents contraindicated in peptic ulcer patients include all of the following EXCEPT:', '["Xanthine beverages", "Pirenzepine", "Tobacco smoking", "NSAIDs", "Glucocorticoids"]'::jsonb, 'Pirenzepine', '[]'::jsonb, 'Pirenzepine is a selective M1 muscarinic antagonist that reduces vagally mediated acid secretion and was used to treat ulcers. Caffeine-containing drinks stimulate acid, smoking delays healing, and NSAIDs and glucocorticoids impair mucosal defence.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.211 Q18, GIT Pharmacology: PUD drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-git-pharmacology-class-36fd6eeb8f', 'pharm-introduction-to-git-pharmacology-classification-of-drugs-for-pep', 'mcq', 'Which of the following agents stimulates gastric acid secretion?', '["Propantheline", "Pirenzepine", "Pentagastrin", "Omeprazole", "Ranitidine"]'::jsonb, 'Pentagastrin', '[]'::jsonb, 'Pentagastrin is a synthetic peptide containing the active C-terminal sequence of gastrin; it stimulates parietal cells and was used to test maximal acid output. The other four all reduce acid: two antimuscarinics, a proton pump inhibitor and an H2 antagonist.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.211 Q19, GIT Pharmacology: PUD drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-inflammatory-and-irritable-b-ee4b5570e4', 'pharm-drugs-for-inflammatory-and-irritable-bowel-disease', 'mcq', 'Which one of the following is a monoclonal antibody against integrin that is useful in the management of inflammatory bowel disease?', '["Rituximab", "Infliximab", "Certolizumab", "Natalizumab", "Canakinumab"]'::jsonb, 'Natalizumab', '[]'::jsonb, 'Natalizumab binds the alpha-4 integrin subunit on leucocytes and stops them adhering to the endothelium and migrating into the gut wall; it is used in refractory Crohn''s disease but risks progressive multifocal leucoencephalopathy. Infliximab and certolizumab neutralise TNF-alpha instead.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.211 Q1, GIT Pharmacology: IBD and IBS') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-inflammatory-and-irritable-b-2dff9e7dd1', 'pharm-drugs-for-inflammatory-and-irritable-bowel-disease', 'mcq', 'Which statement is true regarding drugs used in the management of inflammatory bowel disease?', '["Sulfasalazine consists of two 5-aminosalicylic acid molecules bound together", "Asacol contains timed-release microgranules that release 5-aminosalicylic acid in the small intestine", "Adverse effects of sulfasalazine are more common among rapid acetylators", "Balsalazide can cause oligospermia", "Sulfasalazine impairs folate absorption"]'::jsonb, 'Sulfasalazine impairs folate absorption', '[]'::jsonb, 'Sulfasalazine inhibits intestinal folate absorption, so folate supplements are advised. It is 5-ASA linked to sulfapyridine (olsalazine is the 5-ASA dimer); the sulfapyridine causes most toxicity, including reversible oligospermia, and is worse in slow acetylators. Asacol is pH-dependent, releasing in the distal ileum and colon.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.211 Q3, GIT Pharmacology: IBD and IBS') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emetics-antiemetics-and-prokinetic-age-8f8054cbbb', 'pharm-emetics-antiemetics-and-prokinetic-agents', 'mcq', 'Which statement regarding ondansetron is FALSE?', '["It causes constipation", "It inhibits 5-HT3 receptors on vagal nerve afferents", "Its predominant antiemetic effect is via central 5-HT3 receptor antagonism", "It causes QT prolongation within 1 to 2 hours of administration", "It does not require dose adjustment in renal impairment"]'::jsonb, 'Its predominant antiemetic effect is via central 5-HT3 receptor antagonism', '[]'::jsonb, 'Chemotherapy releases serotonin from enterochromaffin cells, which fires 5-HT3 receptors on intestinal vagal afferents; ondansetron''s antiemetic action is mainly this peripheral blockade, with a lesser central contribution. It is cleared by the liver, so only hepatic impairment needs a dose reduction.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.212 Q3, GIT Pharmacology: Emetics and antiemetics. Follows Katzung (action mainly peripheral); other texts give central and peripheral blockade equal weight.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emetics-antiemetics-and-prokinetic-age-1712dc5dd0', 'pharm-emetics-antiemetics-and-prokinetic-agents', 'mcq', 'Which of the following drugs can be used for prophylaxis of motion sickness?', '["Metoclopramide", "Scopolamine", "Famotidine", "Haloperidol", "Chlorpromazine"]'::jsonb, 'Scopolamine', '[]'::jsonb, 'Motion sickness arises in the vestibular apparatus, whose pathway to the vomiting centre uses muscarinic and H1 receptors. Scopolamine (hyoscine), given as a transdermal patch, is the most effective prophylactic. D2 antagonists such as metoclopramide act at the chemoreceptor trigger zone and do not help.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.212 Q4, GIT Pharmacology: Emetics and antiemetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emetics-antiemetics-and-prokinetic-age-018023fda7', 'pharm-emetics-antiemetics-and-prokinetic-agents', 'mcq', 'Ondansetron is:', '["A 5-HT3 antagonist", "A D2 antagonist", "A D2 and 5-HT3 antagonist", "An H1 antagonist", "An antimuscarinic agent"]'::jsonb, 'A 5-HT3 antagonist', '[]'::jsonb, 'Ondansetron is a selective 5-HT3 receptor antagonist used for chemotherapy-induced, radiation-induced and postoperative vomiting. Metoclopramide is the drug that blocks D2 receptors and, at high doses, 5-HT3 receptors as well.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.212 Q5, GIT Pharmacology: Emetics and antiemetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emetics-antiemetics-and-prokinetic-age-cb036b9324', 'pharm-emetics-antiemetics-and-prokinetic-agents', 'mcq', 'Pharmacological effects of metoclopramide include all of the following EXCEPT:', '["Antiemetic", "Prokinetic", "Blockade of muscarinic receptors", "Extrapyramidal dystonia", "Hyperprolactinaemia"]'::jsonb, 'Blockade of muscarinic receptors', '[]'::jsonb, 'Metoclopramide blocks D2 receptors (antiemetic, dystonia, raised prolactin) and is a 5-HT4 agonist that increases acetylcholine release in the myenteric plexus. Its prokinetic effect is therefore cholinergic and is abolished, not mimicked, by muscarinic blockers such as atropine.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.213 Q1, GIT Pharmacology: Pro-kinetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emetics-antiemetics-and-prokinetic-age-6d42cbb149', 'pharm-emetics-antiemetics-and-prokinetic-agents', 'mcq', 'Adverse effects of metoclopramide include all of the following EXCEPT:', '["Dystonic reactions", "Hypokalaemia", "Drowsiness", "Galactorrhoea", "Menstrual disorders"]'::jsonb, 'Hypokalaemia', '[]'::jsonb, 'Metoclopramide does not disturb potassium balance. Its adverse effects follow from central D2 blockade: acute dystonia (especially in children and young women), drowsiness and restlessness, and hyperprolactinaemia leading to galactorrhoea and menstrual disturbance.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.213 Q2, GIT Pharmacology: Pro-kinetics') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-99a60a71ee', 'pharm-antidiarrheal-agents-laxatives', 'mcq', 'Which statement is true of loperamide?', '["Its bioavailability is 100%", "It is not analgesic", "It binds to muscarinic receptors", "It is addictive", "It is a laxative"]'::jsonb, 'It is not analgesic', '[]'::jsonb, 'Loperamide is a mu-opioid agonist that is pumped out of the brain by P-glycoprotein and has heavy first-pass metabolism, so at usual doses it has no analgesic or euphoric action and no addiction liability. Its bioavailability is very low.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.214 Q5, GIT Pharmacology: Anti-diarrheals') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-b4dd10371a', 'pharm-antidiarrheal-agents-laxatives', 'mcq', 'All of the following drugs are used in the symptomatic treatment of diarrhoea EXCEPT:', '["Kaolin", "Pectin", "Diphenoxylate", "Ursodeoxycholic acid", "Loperamide"]'::jsonb, 'Ursodeoxycholic acid', '[]'::jsonb, 'Ursodeoxycholic acid is a bile acid used to dissolve cholesterol gallstones and in primary biliary cholangitis; diarrhoea is in fact one of its adverse effects. Kaolin and pectin are adsorbents, and diphenoxylate and loperamide are opioid antimotility agents.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.214 Q6, GIT Pharmacology: Anti-diarrheals') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-250251a307', 'pharm-antidiarrheal-agents-laxatives', 'mcq', 'All of the following drugs cause constipation EXCEPT:', '["Aluminium hydroxide", "Magnesium oxide", "Verapamil", "Loperamide", "Bismuth subsalicylate"]'::jsonb, 'Magnesium oxide', '[]'::jsonb, 'Magnesium salts are poorly absorbed and hold water in the bowel lumen osmotically, causing diarrhoea; this is why they are combined with constipating aluminium salts in antacid mixtures. Verapamil relaxes colonic smooth muscle and is a well-known cause of constipation.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.214 Q7, GIT Pharmacology: Anti-diarrheals') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-0a6e98d65f', 'pharm-antidiarrheal-agents-laxatives', 'mcq', 'All of the following are true about polyethylene glycol (PEG) electrolyte solution EXCEPT:', '["It is a balanced isotonic solution", "It is poorly absorbed", "It is a cathartic", "It is used for colonic cleansing before endoscopy", "It is the standard laxative used for hepatic encephalopathy"]'::jsonb, 'It is the standard laxative used for hepatic encephalopathy', '[]'::jsonb, 'Lactulose is the laxative used in hepatic encephalopathy: colonic bacteria ferment it to acids that trap ammonia as ammonium. PEG is a non-absorbable osmotic agent in an isotonic electrolyte solution, used as lavage for bowel preparation and in smaller doses for chronic constipation.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.214 Q2, GIT Pharmacology: Laxatives. Option e reworded from ''Used for hepatic encephalopathy'' to make it clearly the exception.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-4223bb80a9', 'pharm-antidiarrheal-agents-laxatives', 'mcq', 'Which statement about balanced polyethylene glycol (PEG) solution is FALSE?', '["It is an osmotic laxative", "It may be used for colonic cleansing before gastrointestinal endoscopic procedures", "It may be mixed with water or juices before ingestion", "It produces significant cramps and flatulence", "It causes insignificant intravascular fluid or electrolyte shifts"]'::jsonb, 'It produces significant cramps and flatulence', '[]'::jsonb, 'PEG is not fermented by colonic bacteria, so unlike lactulose and sorbitol it does not produce significant gas or cramps. Because the solution is isotonic and balanced with electrolytes, large volumes cause no significant fluid or electrolyte shifts.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.214 Q3, GIT Pharmacology: Laxatives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-digestants-and-drugs-used-to-dissolve--daa860c10c', 'pharm-digestants-and-drugs-used-to-dissolve-gallstones-bile-acids', 'mcq', 'Magnesium sulphate (2-4 g) taken orally before breakfast acts as a:', '["Sialagogue", "Cholagogue", "Antiemetic", "Non-systemic antacid", "Hydrocholeretic"]'::jsonb, 'Cholagogue', '[]'::jsonb, 'A small dose of magnesium sulphate reaching the duodenum releases cholecystokinin, which contracts the gallbladder and relaxes the sphincter of Oddi, so stored bile is expelled: a cholagogue action. Hydrocholeretics, such as dehydrocholic acid, instead increase the volume of watery bile secreted by the liver.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.215 Q4, GIT Pharmacology: Laxatives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-e2023c921d', 'pharm-antidiarrheal-agents-laxatives', 'mcq', 'Liquid paraffin has the disadvantage of:', '["Decreasing absorption of vitamins A and D", "Interfering with absorption of phosphate", "Interfering with absorption of tetracyclines", "Producing discolouration of urine", "Producing colicky pains"]'::jsonb, 'Decreasing absorption of vitamins A and D', '[]'::jsonb, 'Liquid paraffin is an indigestible mineral oil that dissolves the fat-soluble vitamins A, D, E and K and carries them out in the stool. It can also leak from the anus and cause lipoid pneumonia if aspirated. Aluminium antacids are the ones that bind phosphate and tetracyclines.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.215 Q5, GIT Pharmacology: Laxatives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-797b2ffa24', 'pharm-antidiarrheal-agents-laxatives', 'mcq', 'All of the following are bulk purgatives EXCEPT:', '["Bran", "Agar", "Psyllium seed", "Senna", "Methylcellulose"]'::jsonb, 'Senna', '[]'::jsonb, 'Senna is a stimulant (irritant) purgative: its anthraquinone glycosides are activated by colonic bacteria and stimulate the myenteric plexus, acting in 6 to 12 hours. The other four are indigestible hydrophilic colloids that swell with water.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.215 Q6, GIT Pharmacology: Laxatives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-43df6dd6d4', 'pharm-antidiarrheal-agents-laxatives', 'mcq', 'In obstructive jaundice, which of the following purgatives is inactive?', '["Liquid paraffin", "Senna", "Castor oil", "Magnesium sulphate", "Dioctyl sodium sulphosuccinate"]'::jsonb, 'Castor oil', '[]'::jsonb, 'Castor oil is itself inert; it must be hydrolysed in the small intestine by pancreatic lipase, which requires bile salts, to release the irritant ricinoleic acid. With no bile reaching the gut in obstructive jaundice it is not activated.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.215 Q7, GIT Pharmacology: Laxatives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-795738ee29', 'pharm-antidiarrheal-agents-laxatives', 'mcq', 'Which of the following purgatives is hydrolysed by pancreatic lipases in the presence of bile to ricinoleic acid?', '["Phenolphthalein", "Bisacodyl", "Castor oil", "Liquid paraffin", "Lactulose"]'::jsonb, 'Castor oil', '[]'::jsonb, 'Castor oil is a triglyceride of ricinoleic acid. Lipase releases the acid in the small intestine, where it irritates the mucosa and stimulates secretion and peristalsis, giving a rapid effect within 2 to 3 hours. Bisacodyl is activated by intestinal esterases instead.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.215 Q8, GIT Pharmacology: Laxatives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-1c9fd5009b', 'pharm-antidiarrheal-agents-laxatives', 'mcq', 'Which of the following purgatives has a prolonged action because it undergoes enterohepatic circulation?', '["Sodium sulphate", "Lactulose", "Liquid paraffin", "Agar", "Phenolphthalein"]'::jsonb, 'Phenolphthalein', '[]'::jsonb, 'About 15% of a phenolphthalein dose is absorbed, conjugated in the liver and excreted in bile back into the gut, so its action may last several days. It has been withdrawn in many countries over carcinogenicity concerns. The other options are not absorbed to any useful extent.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.215 Q9, GIT Pharmacology: Laxatives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-treating-pancreatic-disorder-aa27dc164c', 'pharm-drugs-for-treating-pancreatic-disorders-aprotinin-glucagon-use-o', 'mcq', 'Which statement about pancrelipase is FALSE?', '["It can cause mucositis if chewed", "It is rapidly inactivated by gastric acid", "It is available as an enteric-coated formulation", "It is an alcohol-derived extract of hog pancreas", "High doses can cause diarrhoea"]'::jsonb, 'It is an alcohol-derived extract of hog pancreas', '[]'::jsonb, 'The alcohol-derived extract of hog pancreas is pancreatin, which has low enzyme activity; pancrelipase is an enriched preparation with much higher lipase content. Because the enzymes are destroyed by acid, pancrelipase is given as enteric-coated microspheres, which must not be chewed.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.216 Q2, GIT Pharmacology: Pancreatic enzymes. Depends on the Katzung distinction between pancreatin and pancrelipase (both are porcine extracts).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aldosterone-oxytocin-vasopressin-8734f1bd1d', 'pharm-aldosterone-oxytocin-vasopressin', 'mcq', 'Which of the following is used in the management of pituitary diabetes insipidus?', '["Corticotropin", "Desmopressin", "HCG", "Menotropins", "Thyrotropin"]'::jsonb, 'Desmopressin', '[]'::jsonb, 'Pituitary (central) diabetes insipidus is due to lack of vasopressin. Desmopressin is a long-acting synthetic analogue selective for V2 receptors in the collecting duct, so it restores water reabsorption without the V1 pressor effect. It is useless in nephrogenic diabetes insipidus.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.218 Q1, Endocrinology: LH, FSH, Androgens & Pituitary Hormones') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-endocrine-pharmacology-b094d86b71', 'pharm-introduction-to-endocrine-pharmacology-lh-fsh-chorionic-gonadotr', 'mcq', 'Which is NOT a legitimate clinical indication of androgens in women?', '["Combined with oestrogens to reduce breast engorgement during the postpartum period", "Treatment of endometriosis", "Chemotherapy of breast tumours in postmenopausal women", "Combined with oestrogens for postmenopausal hormone replacement therapy", "To enhance libido in postmenopausal women"]'::jsonb, 'Chemotherapy of breast tumours in postmenopausal women', '[]'::jsonb, 'Androgens have been used as palliative hormonal therapy for breast cancer in premenopausal, not postmenopausal, women. Their other gynaecological uses are postpartum breast engorgement (with oestrogens), endometriosis (danazol), and with oestrogens in postmenopausal replacement to improve libido.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.218 Q2, Endocrinology: LH, FSH, Androgens & Pituitary Hormones. Answer follows the wording of Katzung (''premenopausal''); a fine distinction, and androgens have historically been used in postmenopausal breast cancer too. Repeated on p.219 Q4; kept once.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-endocrine-pharmacology-89b1916bda', 'pharm-introduction-to-endocrine-pharmacology-lh-fsh-chorionic-gonadotr', 'mcq', 'All of the following are true regarding gonadotropins and their analogues EXCEPT:', '["Continuous administration of leuprolide reduces the production of oestrogens", "FSH analogues cause ovarian atrophy", "Follitropin beta is a human FSH product manufactured using recombinant DNA technology", "Choriogonadotropin alfa has LH activity", "Menotropins is a mixture of FSH and LH"]'::jsonb, 'FSH analogues cause ovarian atrophy', '[]'::jsonb, 'FSH preparations stimulate follicle development; their main risk is ovarian hyperstimulation syndrome with enlarged ovaries and multiple pregnancy, not atrophy. Continuous GnRH agonist exposure such as leuprolide down-regulates pituitary GnRH receptors and suppresses gonadal steroids.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.218 Q3, Endocrinology: LH, FSH, Androgens & Pituitary Hormones') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-endocrine-pharmacology-5315cac9df', 'pharm-introduction-to-endocrine-pharmacology-lh-fsh-chorionic-gonadotr', 'mcq', 'Which is NOT an adverse effect of androgens in women?', '["Acne", "Clitoral enlargement", "Hirsutism", "Menorrhagia", "Deepening of the voice"]'::jsonb, 'Menorrhagia', '[]'::jsonb, 'Androgens suppress gonadotropin secretion and cause endometrial atrophy, so they produce oligomenorrhoea or amenorrhoea, not heavy periods. The other effects are virilisation: acne, hirsutism, clitoral enlargement and deepening of the voice, the last two often irreversible.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.219 Q4, Endocrinology: LH, FSH, Androgens & Pituitary Hormones') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-1548900665', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'mcq', 'Which drug has a non-selective cytotoxic action on the adrenal cortex?', '["Mifepristone", "Ketoconazole", "Aminoglutethimide", "Mitotane", "Metyrapone"]'::jsonb, 'Mitotane', '[]'::jsonb, 'Mitotane, a relative of the insecticide DDT, destroys adrenocortical cells and is used for inoperable adrenal carcinoma. Ketoconazole, aminoglutethimide and metyrapone only inhibit steroid-synthesising enzymes, and mifepristone blocks the glucocorticoid receptor.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.219 Q2, Endocrinology: Adrenocortical Steroids. Repeated as Q6 on p.220; kept once.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-8fbfaa89be', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'mcq', 'Which is NOT an adverse effect of abiraterone acetate?', '["Hepatotoxicity", "Oedema", "Hypotension", "Hypokalaemia", "Hot flushes"]'::jsonb, 'Hypotension', '[]'::jsonb, 'Abiraterone inhibits CYP17, lowering androgens and cortisol; the resulting rise in ACTH drives mineralocorticoid precursors, causing hypertension, fluid retention and hypokalaemia, not hypotension. This is why it is given with prednisone. Liver enzyme rises and hot flushes also occur.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.219 Q3, Endocrinology: Adrenocortical Steroids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-5ef5042462', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'mcq', 'All of the following are true of prednisone EXCEPT:', '["It is used for treatment of acute lymphocytic leukaemia", "It causes hyperglycaemia", "It is a prodrug of prednisolone", "It is well absorbed orally", "It has more mineralocorticoid activity than cortisol"]'::jsonb, 'It has more mineralocorticoid activity than cortisol', '[]'::jsonb, 'Prednisone has about four times the anti-inflammatory potency of cortisol but less salt-retaining activity (roughly 0.3 to 0.8 relative to cortisol). It is inactive until hepatic 11-beta-hydroxysteroid dehydrogenase converts it to prednisolone, and its lympholytic action is used in leukaemia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.220 Q4, Endocrinology: Adrenocortical Steroids. Replaced the doubtful option ''Causes hyperuricemia'' with ''causes hyperglycaemia''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-483c48addd', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'mcq', 'Which is NOT an inhibitor of adrenal steroid synthesis?', '["Metyrapone", "Mifepristone", "Aminoglutethimide", "Trilostane", "Ketoconazole"]'::jsonb, 'Mifepristone', '[]'::jsonb, 'Mifepristone does not affect steroid synthesis: it is a competitive antagonist at glucocorticoid and progesterone receptors. Metyrapone inhibits 11-beta-hydroxylase, aminoglutethimide the cholesterol side-chain cleavage enzyme, trilostane 3-beta-hydroxysteroid dehydrogenase and ketoconazole several P450 steps.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.220 Q4b, Endocrinology: Adrenocortical Steroids. Second question numbered 4 on the page.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-d6d8fda81b', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'mcq', 'Which of the following hormones has anti-inflammatory effects in pharmacological doses?', '["Calcitonin", "Vasopressin", "Cortisol", "Desoxycorticosterone", "Aldosterone"]'::jsonb, 'Cortisol', '[]'::jsonb, 'Cortisol, the natural glucocorticoid, suppresses inflammation in supraphysiological doses by inducing lipocortin (annexin-1), which inhibits phospholipase A2, and by repressing genes for COX-2 and cytokines. Aldosterone and desoxycorticosterone are mineralocorticoids with no anti-inflammatory action.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.220 Q7, Endocrinology: Adrenocortical Steroids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-c0165d478f', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'mcq', 'Metabolic effects of glucocorticoids include all of the following EXCEPT:', '["Increased gluconeogenesis", "Decreased uptake and utilisation of glucose", "Increased liver glycogen deposition", "Catabolic effects on muscles", "Inhibition of lipolysis"]'::jsonb, 'Inhibition of lipolysis', '[]'::jsonb, 'Glucocorticoids stimulate lipolysis, releasing fatty acids and glycerol, although the insulin they provoke causes fat to be redistributed to the face and trunk. They raise blood glucose by promoting gluconeogenesis from muscle protein and reducing peripheral glucose uptake, while liver glycogen increases.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.220 Q8, Endocrinology: Adrenocortical Steroids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-9d92a5fe94', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'mcq', 'Administration of glucocorticoids produces:', '["Neutropenia", "Eosinopenia", "Lymphocytosis", "Monocytosis", "Thrombocytopenia"]'::jsonb, 'Eosinopenia', '[]'::jsonb, 'Glucocorticoids lower circulating eosinophils, lymphocytes, monocytes and basophils by redistributing them out of the blood. Neutrophils do the opposite: the count rises because they are released from the marrow and demarginate, so a steroid-treated patient has neutrophilia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.220 Q9, Endocrinology: Adrenocortical Steroids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-2f8e53f142', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'mcq', 'Pharmacological actions of glucocorticoids include all of the following EXCEPT:', '["Anti-inflammatory", "Immunosuppressive", "Increased number of circulating lymphocytes", "Negative feedback effect on the secretion of CRF and ACTH", "Increased calcium excretion by the kidney"]'::jsonb, 'Increased number of circulating lymphocytes', '[]'::jsonb, 'Glucocorticoids cause lymphopenia by shifting lymphocytes into lymphoid tissue and inducing apoptosis, which contributes to immunosuppression. They also reduce intestinal calcium absorption and increase its renal excretion, promoting osteoporosis, and suppress the hypothalamic-pituitary-adrenal axis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.221 Q10, Endocrinology: Adrenocortical Steroids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-847f398a7a', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'mcq', 'Which of the following is used to treat acute adrenocortical insufficiency (Addisonian crisis)?', '["Hydrocortisone sodium succinate", "Beclomethasone dipropionate", "Fludrocortisone", "Spironolactone", "Aldosterone"]'::jsonb, 'Hydrocortisone sodium succinate', '[]'::jsonb, 'Addisonian crisis needs immediate intravenous hydrocortisone sodium succinate, the water-soluble ester, with saline and glucose; at these doses hydrocortisone supplies enough mineralocorticoid activity as well. Fludrocortisone is only available orally and is for long-term replacement.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.221 Q11, Endocrinology: Adrenocortical Steroids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-a9a3f5ef45', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'mcq', 'Oral prednisolone therapy is indicated in the treatment of:', '["Peptic ulcer", "Systemic lupus erythematosus", "Diabetes mellitus", "Osteoporosis", "Epilepsy"]'::jsonb, 'Systemic lupus erythematosus', '[]'::jsonb, 'Systemic lupus erythematosus is an autoimmune disease in which the immunosuppressive and anti-inflammatory actions of prednisolone control flares. Peptic ulcer, diabetes and osteoporosis are all made worse by glucocorticoids and are relative contraindications.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.221 Q12, Endocrinology: Adrenocortical Steroids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-a7438e65ed', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'mcq', 'Which of the following synthetic steroids is given orally as mineralocorticoid replacement in adrenocortical insufficiency?', '["Spironolactone", "Betamethasone", "Dexamethasone", "Fludrocortisone", "Triamcinolone"]'::jsonb, 'Fludrocortisone', '[]'::jsonb, 'Fludrocortisone (9-alpha-fluorohydrocortisone) has very high salt-retaining potency and is active orally, unlike aldosterone, which is destroyed on first pass. Dexamethasone, betamethasone and triamcinolone have essentially no mineralocorticoid activity; spironolactone is an aldosterone antagonist.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.221 Q13, Endocrinology: Adrenocortical Steroids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-6629748a82', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'mcq', 'Corticosteroids are usually indicated in all of the following conditions EXCEPT:', '["Nephrotic syndrome", "Collagen diseases", "Herpes simplex of the eye", "Addison''s disease", "Severe acute asthma (status asthmaticus)"]'::jsonb, 'Herpes simplex of the eye', '[]'::jsonb, 'In herpes simplex keratitis, steroids suppress local immunity, allow the virus to spread and can lead to corneal perforation, so they are contraindicated. The other conditions are standard indications: immune-mediated disease, replacement therapy and severe asthma.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.221 Q14, Endocrinology: Adrenocortical Steroids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-03ec2e579d', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'mcq', 'Which of the following steroids has virtually no sodium-retaining effect?', '["Cortisone", "Cortisol", "Aldosterone", "Fludrocortisone", "Dexamethasone"]'::jsonb, 'Dexamethasone', '[]'::jsonb, 'Dexamethasone is a fluorinated, 16-methylated steroid with about 25 to 30 times the anti-inflammatory potency of cortisol and no mineralocorticoid activity, making it suitable where fluid retention must be avoided, as in cerebral oedema. Cortisol and cortisone retain appreciable salt-retaining activity.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.221 Q15, Endocrinology: Adrenocortical Steroids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-39ed6e748c', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'mcq', 'Sudden withdrawal of glucocorticoids after prolonged therapy results in:', '["Hypertensive crisis", "Acute adrenocortical insufficiency", "Cardiac arrhythmias", "Angina pectoris", "Convulsions"]'::jsonb, 'Acute adrenocortical insufficiency', '[]'::jsonb, 'Prolonged steroid therapy suppresses CRH and ACTH, and the adrenal cortex atrophies. If the drug is stopped abruptly the gland cannot produce cortisol, causing weakness, hypotension and shock, particularly under stress. Doses must therefore be tapered slowly.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.222 Q16, Endocrinology: Adrenocortical Steroids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-178cd82221', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'mcq', 'Chronic treatment with large doses of prednisolone may result in all of the following EXCEPT:', '["Retardation of growth in children", "Iatrogenic Cushing''s syndrome", "Osteoporosis", "Parkinsonism", "Psychosis"]'::jsonb, 'Parkinsonism', '[]'::jsonb, 'Parkinsonism results from dopamine deficiency or D2 blockade and is not caused by steroids. Long-term prednisolone does cause growth suppression, Cushingoid features, osteoporosis and mood changes ranging from euphoria to frank psychosis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.222 Q17, Endocrinology: Adrenocortical Steroids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-470552daea', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'mcq', 'Prolonged therapy with glucocorticoids can lead to all of the following adverse effects EXCEPT:', '["Peptic ulceration", "Increased susceptibility to infection", "Suppression of pituitary-adrenal function", "Myopathy", "Hypoglycaemia"]'::jsonb, 'Hypoglycaemia', '[]'::jsonb, 'Glucocorticoids raise blood glucose by increasing gluconeogenesis and antagonising insulin, so they cause hyperglycaemia and may unmask diabetes. Proximal myopathy reflects their catabolic effect on muscle protein, and infection risk their immunosuppression.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.222 Q18, Endocrinology: Adrenocortical Steroids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-931ff6ff30', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'mcq', 'In human beings, the mineralocorticoid produced by the adrenal cortex is:', '["Dehydroepiandrosterone", "Androstenedione", "Aldosterone", "Cortisol", "Corticosterone"]'::jsonb, 'Aldosterone', '[]'::jsonb, 'Aldosterone, made in the zona glomerulosa under control of angiotensin II and potassium, is the principal human mineralocorticoid. Cortisol is the main glucocorticoid of the zona fasciculata, and dehydroepiandrosterone and androstenedione are adrenal androgens from the zona reticularis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.222 Q19, Endocrinology: Adrenocortical Steroids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-905fa69703', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'mcq', 'Which of the following inhibits 11-beta-hydroxylation in the adrenal cortex?', '["Metyrapone", "Spironolactone", "Clomiphene", "Mifepristone", "Cyproterone"]'::jsonb, 'Metyrapone', '[]'::jsonb, 'Metyrapone blocks 11-beta-hydroxylase, the last step in cortisol synthesis, so 11-deoxycortisol accumulates; it is used to test pituitary ACTH reserve and to control Cushing''s syndrome. Spironolactone, mifepristone and cyproterone are receptor antagonists, not enzyme inhibitors.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.222 Q20, Endocrinology: Adrenocortical Steroids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-9cddb42b8a', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'mcq', 'The dexamethasone suppression test is used to diagnose:', '["Phaeochromocytoma", "Addison''s disease", "Cushing''s syndrome", "Graves'' disease", "Pituitary dwarfism"]'::jsonb, 'Cushing''s syndrome', '[]'::jsonb, 'Dexamethasone is potent enough to suppress ACTH at a dose too small to register in cortisol assays. In healthy people morning cortisol falls after an overnight dose; failure to suppress indicates Cushing''s syndrome. Addison''s disease is tested the opposite way, with ACTH (Synacthen) stimulation.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.222 Q21, Endocrinology: Adrenocortical Steroids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-gh-prolactin-and-its-inhibitor-f536d353b3', 'pharm-gh-prolactin-and-its-inhibitor', 'mcq', 'Growth hormone is contraindicated in:', '["Idiopathic short stature", "Short bowel syndrome", "Colon cancer", "Small-for-gestational-age children who do not show catch-up growth by 2 years of age", "Growth hormone deficiency"]'::jsonb, 'Colon cancer', '[]'::jsonb, 'Growth hormone and its mediator IGF-1 are mitogenic, so somatropin is contraindicated in active malignancy. The other options are all licensed indications, including short bowel syndrome, where it improves intestinal adaptation.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.223 Q1, Endocrinology: GH, Prolactin and Its Inhibitors') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-gh-prolactin-and-its-inhibitor-400834b997', 'pharm-gh-prolactin-and-its-inhibitor', 'mcq', 'Concerning octreotide, which statement is FALSE?', '["It is a somatostatin analogue", "It inhibits the release of growth hormone", "It is indicated in diabetic diarrhoea", "It has a shorter duration of action than lanreotide", "It is a growth hormone receptor antagonist"]'::jsonb, 'It is a growth hormone receptor antagonist', '[]'::jsonb, 'Octreotide is an agonist at somatostatin receptors, reducing secretion of growth hormone and many gut peptides. The growth hormone receptor antagonist is pegvisomant, which prevents receptor dimerisation and lowers IGF-1 in acromegaly without reducing growth hormone itself.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.223 Q2, Endocrinology: GH, Prolactin and Its Inhibitors') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-gh-prolactin-and-its-inhibitor-1b827664be', 'pharm-gh-prolactin-and-its-inhibitor', 'mcq', 'The following are adverse effects of growth hormone treatment in children EXCEPT:', '["Hypothyroidism", "Scoliosis", "Intracranial hypertension", "Carpal tunnel syndrome", "Pancreatitis"]'::jsonb, 'Carpal tunnel syndrome', '[]'::jsonb, 'Carpal tunnel syndrome, with peripheral oedema, myalgia and arthralgia, is characteristic of growth hormone treatment in adults. In children the reported problems are intracranial hypertension, progression of scoliosis during rapid growth, slipped capital femoral epiphysis, hypothyroidism and pancreatitis.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.223 Q3, Endocrinology: GH, Prolactin and Its Inhibitors. Rests on Katzung''s child versus adult list of adverse effects; a fine distinction.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-gh-prolactin-and-its-inhibitor-c8f16cbe7b', 'pharm-gh-prolactin-and-its-inhibitor', 'mcq', 'Which of the following is NOT used as a prolactin inhibitor?', '["Cabergoline", "Quinagolide", "Bromocriptine", "Pramipexole", "Pergolide"]'::jsonb, 'Pramipexole', '[]'::jsonb, 'Hyperprolactinaemia is treated with D2 agonists: the ergot derivatives bromocriptine, cabergoline and pergolide, and the non-ergot quinagolide. Pramipexole is a non-ergot agonist used only for Parkinson''s disease and restless legs syndrome.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.223 Q4, Endocrinology: GH, Prolactin and Its Inhibitors. Pramipexole also lowers prolactin pharmacologically; the answer rests on clinical use, and pergolide is itself largely withdrawn.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-gh-prolactin-and-its-inhibitor-19d51c4e81', 'pharm-gh-prolactin-and-its-inhibitor', 'mcq', 'All of the following are true about growth hormone EXCEPT:', '["It causes growth at the epiphyseal ends of bone via stimulation of somatomedin C", "It causes lipolysis in adipose tissue", "Laron dwarfism is due to its deficiency", "It is both anabolic and catabolic", "Somatropin is a recombinant form of human growth hormone"]'::jsonb, 'Laron dwarfism is due to its deficiency', '[]'::jsonb, 'In Laron dwarfism growth hormone levels are normal or high; the defect is a mutated growth hormone receptor, so IGF-1 (somatomedin C) is not produced. It is treated with mecasermin (recombinant IGF-1), not with growth hormone.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.223 Q5, Endocrinology: GH, Prolactin and Its Inhibitors. Option e reworded from ''Somatotropin is a synthetic similar to human growth hormone''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-a4ee0f6e6a', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'saq', 'True or false: Glucocorticoids enter cells and bind to a cytoplasmic glucocorticoid receptor.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'Being lipid soluble, glucocorticoids diffuse through the cell membrane and bind a cytoplasmic receptor held by heat-shock proteins. The complex then moves to the nucleus and alters gene transcription, which is why their effects take hours to appear.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.223 Q22, Endocrinology: Adrenocortical Steroids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-668b5e82a2', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'saq', 'True or false: Prednisone is a prodrug.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'Prednisone has an 11-keto group and is inactive until hepatic 11-beta-hydroxysteroid dehydrogenase type 1 reduces it to prednisolone. Cortisone is converted to hydrocortisone in the same way, so in severe liver disease the active forms are preferred.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.223 Q23, Endocrinology: Adrenocortical Steroids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-8551ae8fdd', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'saq', 'True or false: After prolonged use, steroid therapy must be withdrawn gradually.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'Long courses suppress the hypothalamic-pituitary-adrenal axis and the adrenal cortex atrophies. Tapering the dose gives the axis time to recover, which may take months; abrupt withdrawal risks acute adrenal insufficiency.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.223 Q24, Endocrinology: Adrenocortical Steroids. Added ''after prolonged use'' to make the statement precise.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenocortical-steroids-synthetic-anal-a6ad6abc8a', 'pharm-adrenocortical-steroids-synthetic-analogues-inhibitor-of-synthes', 'saq', 'True or false: Prolonged treatment with prednisolone causes cataract.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'Long-term glucocorticoids, systemic or topical to the eye, cause posterior subcapsular cataracts and can also raise intraocular pressure. Patients on long courses, especially children, should have periodic eye examinations.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.223 Q25, Endocrinology: Adrenocortical Steroids') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-gh-prolactin-and-its-inhibitor-36c72feb96', 'pharm-gh-prolactin-and-its-inhibitor', 'mcq', 'Which of the following is NOT effective in the amenorrhoea-galactorrhoea syndrome?', '["Cabergoline", "Pergolide", "Quinagolide", "Ergometrine", "Bromocriptine"]'::jsonb, 'Ergometrine', '[]'::jsonb, 'The syndrome is caused by hyperprolactinaemia and responds to dopamine D2 agonists, which inhibit pituitary lactotrophs. Ergometrine is an ergot alkaloid that acts mainly on uterine smooth muscle, used for postpartum haemorrhage, and has no useful dopaminergic action.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.224 Q6, Endocrinology: GH, Prolactin and Its Inhibitors') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-gh-prolactin-and-its-inhibitor-d410cbb1b9', 'pharm-gh-prolactin-and-its-inhibitor', 'mcq', 'Which of the following hormones inhibits the release of growth hormone, insulin, glucagon and gastrin?', '["Prolactin", "Somatostatin", "Thyrotropin-releasing hormone", "Corticotropin-releasing hormone", "Gonadotropin-releasing hormone"]'::jsonb, 'Somatostatin', '[]'::jsonb, 'Somatostatin, made in the hypothalamus, pancreatic D cells and gut, is a general inhibitor of peptide secretion acting through Gi-coupled receptors. Its long-acting analogue octreotide exploits this in acromegaly, carcinoid syndrome and variceal bleeding.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.224 Q7, Endocrinology: GH, Prolactin and Its Inhibitors') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-gh-prolactin-and-its-inhibitor-0dd208ca65', 'pharm-gh-prolactin-and-its-inhibitor', 'mcq', 'Prolactin-secreting adenomas can be treated with:', '["Chlorpromazine", "Haloperidol", "Metoclopramide", "Reserpine", "Bromocriptine"]'::jsonb, 'Bromocriptine', '[]'::jsonb, 'Bromocriptine stimulates D2 receptors on lactotrophs, suppressing prolactin secretion and shrinking most prolactinomas. The other four drugs block dopamine receptors or deplete dopamine, so they raise prolactin and would make matters worse.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.224 Q8, Endocrinology: GH, Prolactin and Its Inhibitors') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-6aebc482f6', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'mcq', 'The drug of first choice in the treatment of thyrotoxicosis is:', '["Propylthiouracil", "Methimazole", "Perchlorate", "Iodides", "Thiocyanate"]'::jsonb, 'Methimazole', '[]'::jsonb, 'Methimazole (or its prodrug carbimazole) is preferred because it is about ten times more potent, is given once daily and is less hepatotoxic than propylthiouracil. Propylthiouracil is reserved for the first trimester of pregnancy and thyroid storm. Perchlorate and thiocyanate are obsolete.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.224 Q1, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-bbdecb1571', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'mcq', 'The following block the conversion of T4 to T3 EXCEPT:', '["Ipodate", "Beta blockers", "Corticosteroids", "Severe illness", "Overeating"]'::jsonb, 'Overeating', '[]'::jsonb, 'Type 1 5''-deiodinase is inhibited by iodinated contrast agents such as ipodate, propranolol, glucocorticoids, amiodarone, propylthiouracil, severe illness and starvation. Overfeeding does the opposite, increasing T3 production as part of diet-induced thermogenesis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.224 Q2, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-29547df53e', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'mcq', 'All of the following are true about antithyroid drugs EXCEPT:', '["Thiocyanate inhibits organification of iodide", "Perchlorate is 10 times as active as thiocyanate", "Lithium decreases secretion of T4 but not T3", "Iodide inhibits synthesis of iodotyrosines and iodothyronines", "Carbimazole acts by inhibiting peroxidase"]'::jsonb, 'Lithium decreases secretion of T4 but not T3', '[]'::jsonb, 'Lithium inhibits release of both T4 and T3 from the gland, so it can cause hypothyroidism and goitre. High-dose iodide acutely blocks organification (the Wolff-Chaikoff effect), and carbimazole, through methimazole, inhibits thyroid peroxidase.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.224 Q3, Endocrinology: Thyroid Physiology and Treatment. Option A is only partly true (thiocyanate mainly inhibits iodide uptake; organification only at high concentrations), so two options could be argued.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-b33cd6afb8', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'mcq', 'The following antithyroid drugs act by inhibition of iodine uptake EXCEPT:', '["Fluoroborate", "Perchlorate", "Propylthiouracil", "Thiocyanate", "Pertechnetate"]'::jsonb, 'Propylthiouracil', '[]'::jsonb, 'Propylthiouracil is a thioamide: it inhibits thyroid peroxidase, blocking organification and coupling, and also peripheral T4 to T3 conversion. The others are monovalent anions of similar size to iodide that compete with it at the sodium-iodide symporter.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.225 Q3b, Endocrinology: Thyroid Physiology and Treatment. Second question numbered 3; ''Fluborate'' corrected to fluoroborate.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-dffa287733', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'mcq', 'Which of the following is the most appropriate in the treatment of hyperthyroidism?', '["Carvedilol", "Atenolol", "Propranolol", "Labetalol", "Thyroxine"]'::jsonb, 'Propranolol', '[]'::jsonb, 'Propranolol is the beta blocker of choice: besides controlling tachycardia, tremor and anxiety through beta blockade, at high doses it inhibits peripheral conversion of T4 to the more active T3. Atenolol controls the symptoms but lacks this additional effect.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.225 Q4, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-d6d0d7a6f0', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'mcq', 'All of the following are true of thioamides EXCEPT:', '["They inhibit coupling reactions of iodotyrosyl residues", "They inhibit peroxidase", "They inhibit iodine organification", "Propylthiouracil is the prototype", "They stimulate peripheral deiodination of T4 to T3"]'::jsonb, 'They stimulate peripheral deiodination of T4 to T3', '[]'::jsonb, 'Thioamides inhibit thyroid peroxidase, and so both organification of iodide and coupling of iodotyrosines. Far from stimulating it, propylthiouracil inhibits the peripheral deiodination of T4 to T3, which is why it is favoured in thyroid storm.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.225 Q5, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-d49601769c', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'mcq', 'All of the following are true of antithyroid ionic inhibitors EXCEPT:', '["Fluoroborate is as effective as perchlorate", "Perchlorate causes aplastic anaemia in high doses", "Thiocyanate is not concentrated in the thyroid gland", "Lithium decreases levels of T3 but not T4", "Perchlorate is 10 times as active as thiocyanate"]'::jsonb, 'Lithium decreases levels of T3 but not T4', '[]'::jsonb, 'Lithium blocks the release of both T4 and T3 from the thyroid, so both fall. Perchlorate competitively blocks iodide uptake and is about ten times as active as thiocyanate, but fatal aplastic anaemia at high doses ended its routine use.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.225 Q6, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-ec17863a2b', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'mcq', 'All of the following are true about thyroid-stimulating hormone (TSH) EXCEPT:', '["Acute psychosis causes TSH release", "T3 and T4 inhibit both TSH and TRH release", "Prolonged exposure to cold causes TSH release", "Somatostatin inhibits TSH release", "Dopamine activates TSH release"]'::jsonb, 'Dopamine activates TSH release', '[]'::jsonb, 'Dopamine, like somatostatin and glucocorticoids, inhibits TSH secretion; dopamine infusions in intensive care can lower TSH. TRH is the stimulus, increased by cold exposure, and thyroid hormones exert negative feedback at both pituitary and hypothalamus.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.225 Q8, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-a3ccf18385', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'mcq', 'All of the following are true about thyroid hormone preparations EXCEPT:', '["The half-life of levothyroxine is 7 days", "Liothyronine is 3 to 4 times more potent than levothyroxine", "Liotrix contains both liothyronine and thyroxine", "Liothyronine is best avoided in patients with cardiac disease", "Desiccated thyroid is the first-choice preparation for replacement therapy in hypothyroidism"]'::jsonb, 'Desiccated thyroid is the first-choice preparation for replacement therapy in hypothyroidism', '[]'::jsonb, 'Levothyroxine is the preparation of choice: stable, uniform in content, cheap and, with a 7-day half-life, given once daily. Desiccated animal thyroid has variable hormone content and is antigenic. Liothyronine''s rapid, potent action carries a greater risk of cardiotoxicity.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.226 Q9, Endocrinology: Thyroid Physiology and Treatment. Paper''s stem was ''True about thyroid hormone preparations'' with four true options; changed to an EXCEPT question.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-62a848891a', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'mcq', 'All of the following are true about thioamide antithyroid drugs EXCEPT:', '["Carbimazole is a prodrug of methimazole", "The duration of action of methimazole is over 24 hours", "65-70% of a methimazole dose is recovered in the urine within 48 hours", "Methimazole is equally potent to propylthiouracil", "Most administered propylthiouracil is excreted as inactive products in the urine"]'::jsonb, 'Methimazole is equally potent to propylthiouracil', '[]'::jsonb, 'Methimazole is about ten times more potent than propylthiouracil (typical doses 10 to 30 mg against 100 to 300 mg). It accumulates in the thyroid, so one daily dose acts for over 24 hours, whereas propylthiouracil must be given every 6 to 8 hours.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.226 Q10, Endocrinology: Thyroid Physiology and Treatment. Option c reworded from ''65-70% of methimazole is excreted unchanged in urine'' to match the pharmacokinetic data.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-6df300efbb', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'mcq', 'Actions of TSH on the thyroid gland include:', '["Increased size and vascularity", "Increased synthesis and release of T4 and T3", "Increased iodide uptake", "Hyperplasia of thyroid cells", "All of the above"]'::jsonb, 'All of the above', '[]'::jsonb, 'TSH acts on a Gs-coupled receptor and raises cyclic AMP, which stimulates every step of hormone production: iodide trapping, organification, thyroglobulin endocytosis and hormone release. It is also trophic, producing the hyperplasia and increased vascularity seen in goitre.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.226 Q11, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-5128a27478', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'mcq', 'Effects of thyroid hormones include all of the following EXCEPT:', '["Increased oxygen consumption", "They are essential for growth and development", "Increased cardiac rate and output", "Increased sensitivity to catecholamines", "Increased plasma cholesterol"]'::jsonb, 'Increased plasma cholesterol', '[]'::jsonb, 'Thyroid hormones increase the number of hepatic LDL receptors and so lower plasma cholesterol; hypercholesterolaemia is a feature of hypothyroidism. They raise the basal metabolic rate, up-regulate beta adrenoceptors and are essential for brain and skeletal development.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.226 Q12, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-53e07ac57f', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'mcq', 'Concerning thyroxine (T4), all of the following are true EXCEPT that:', '["It is effective orally", "Its biological half-life is 7 days", "It is converted to T3 and rT3 in peripheral tissues", "It is extensively bound to plasma proteins", "It is 4 times more potent than T3"]'::jsonb, 'It is 4 times more potent than T3', '[]'::jsonb, 'The relationship is the other way round: T3 is three to four times more potent than T4 and binds the nuclear receptor with about ten times the affinity. T4 is largely a prohormone, 99.96% protein bound, deiodinated to active T3 or inactive reverse T3.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.226 Q13, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-09afee1767', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'mcq', 'Uptake of plasma iodide by thyroid follicle cells is inhibited by:', '["TSH", "Perchlorate", "Propylthiouracil", "Propranolol", "Calcitonin"]'::jsonb, 'Perchlorate', '[]'::jsonb, 'Perchlorate is an anion that competes with iodide for the sodium-iodide symporter on the basolateral membrane of the follicle cell. TSH stimulates uptake, and propylthiouracil acts at the next step, inhibiting peroxidase-mediated organification.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.226 Q14, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-017357b42c', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'mcq', 'Unwanted effects of thyroxine include all of the following EXCEPT:', '["Anginal pain", "Tremor", "Agranulocytosis", "Diarrhoea", "Weight loss"]'::jsonb, 'Agranulocytosis', '[]'::jsonb, 'Agranulocytosis is the feared adverse effect of the thioamide antithyroid drugs, not of thyroxine. Thyroxine overdosage simply mimics hyperthyroidism: tachycardia and angina, tremor, heat intolerance, diarrhoea and weight loss.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.227 Q15, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-909217c183', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'mcq', 'Which of the following is used to treat myxoedema?', '["Levothyroxine", "Reverse T3", "Bromocriptine", "Desmopressin", "Calcitonin"]'::jsonb, 'Levothyroxine', '[]'::jsonb, 'Myxoedema is severe hypothyroidism and is treated by replacement with levothyroxine, started at a low dose in the elderly and those with heart disease to avoid precipitating angina. Reverse T3 is a biologically inactive metabolite of T4.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.227 Q16, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-c2f80326ff', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'mcq', 'Drugs used in hyperthyroidism include all of the following EXCEPT:', '["Radioactive iodine", "Iodide", "Carbimazole", "Sodium etidronate", "Propranolol"]'::jsonb, 'Sodium etidronate', '[]'::jsonb, 'Etidronate is a bisphosphonate that inhibits osteoclastic bone resorption, used in Paget''s disease and osteoporosis; it has no action on the thyroid. Carbimazole blocks hormone synthesis, iodide blocks release, radioiodine destroys the gland and propranolol controls symptoms.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.227 Q17, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-5416b65044', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'mcq', 'Concerning carbimazole, all of the following are true EXCEPT that it:', '["Inhibits the thyroid peroxidase enzyme", "Blocks coupling of iodotyrosines", "Blocks uptake of iodide by thyroid follicle cells", "Is converted into methimazole in the body", "Is given orally"]'::jsonb, 'Blocks uptake of iodide by thyroid follicle cells', '[]'::jsonb, 'Thioamides do not affect iodide trapping; uptake is blocked by anions such as perchlorate. Carbimazole is rapidly converted to methimazole, which inhibits peroxidase and therefore both iodination of tyrosine residues and coupling of iodotyrosines.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.227 Q18, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-691a854cd8', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'mcq', 'Adverse reactions to thioamide antithyroid drugs include all of the following EXCEPT:', '["Agranulocytosis", "Skin rash", "Coronary vasoconstriction", "Arthralgia", "Jaundice"]'::jsonb, 'Coronary vasoconstriction', '[]'::jsonb, 'Thioamides have no vascular effects. Their adverse effects are mostly immunological: itchy maculopapular rash (commonest), arthralgia, a lupus-like vasculitis, cholestatic jaundice or hepatitis, and agranulocytosis in about 0.1 to 0.5%, which presents as sore throat and fever.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.227 Q19, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-536bd797b6', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'mcq', 'Concerning iodide treatment in hyperthyroidism, all of the following are true EXCEPT that:', '["It is used in thyrotoxic crisis", "It is used in preoperative preparation for thyroidectomy", "It decreases the size and vascularity of the thyroid gland", "Its beneficial effects are maintained with continued treatment for more than 10-15 days", "It inhibits organification of iodine"]'::jsonb, 'Its beneficial effects are maintained with continued treatment for more than 10-15 days', '[]'::jsonb, 'The gland ''escapes'' from iodide block after about two weeks, and hyperthyroidism may return worse than before, so iodide is used only short term: for 10 to 14 days before surgery to make the gland firm and less vascular, and in thyroid storm.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.227 Q20, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-3057627ca6', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'mcq', 'Peripheral deiodination of T4 to T3 is inhibited by which of the following?', '["Methimazole", "Carbimazole", "Propylthiouracil", "Potassium perchlorate", "Metformin"]'::jsonb, 'Propylthiouracil', '[]'::jsonb, 'Propylthiouracil, unlike methimazole and carbimazole, inhibits type 1 5''-deiodinase in liver and kidney, reducing conversion of T4 to active T3. This extra action gives a faster fall in T3 and is the reason it is preferred in thyroid storm.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.227 Q21, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-ca7f121980', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'mcq', 'Concerning radioactive iodine treatment of hyperthyroidism, all of the following are true EXCEPT that:', '["The isotope used is iodine-131", "It is administered orally", "It is contraindicated in pregnancy", "Its clinical effect is evident after 1-2 days", "Its chief adverse effect is delayed hypothyroidism"]'::jsonb, 'Its clinical effect is evident after 1-2 days', '[]'::jsonb, 'Iodine-131 is concentrated in the gland, where its beta particles destroy follicle cells slowly; improvement takes 6 to 12 weeks, so antithyroid drugs or beta blockers cover the interval. It crosses the placenta and would ablate the foetal thyroid.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.228 Q22, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aldosterone-oxytocin-vasopressin-5c839ebbed', 'pharm-aldosterone-oxytocin-vasopressin', 'mcq', 'Which is NOT a clinical indication of oxytocin?', '["To induce labour for conditions requiring early vaginal delivery", "To augment abnormal protracted labour", "Control of uterine haemorrhage after delivery", "Oxytocin challenge test (provides information about placental circulatory reserve)", "To augment placental delivery in a patient with placenta praevia"]'::jsonb, 'To augment placental delivery in a patient with placenta praevia', '[]'::jsonb, 'In placenta praevia the placenta lies over the cervical os, so uterine contractions cause catastrophic bleeding; vaginal delivery, and therefore oxytocin, is contraindicated and caesarean section is required. The other options are its recognised uses.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.228 Q1, Endocrinology: Aldosterone, Oxytocin, Vasopressin') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aldosterone-oxytocin-vasopressin-8884fb606a', 'pharm-aldosterone-oxytocin-vasopressin', 'mcq', 'Which is the FALSE statement about vasopressin?', '["It has both vasopressor and antidiuretic effects", "Desmopressin acetate (DDAVP) is a long-acting synthetic analogue of vasopressin", "It is contraindicated in patients with von Willebrand disease", "Conivaptan is a vasopressin receptor antagonist", "Overdosage with vasopressin can cause hyponatraemia"]'::jsonb, 'It is contraindicated in patients with von Willebrand disease', '[]'::jsonb, 'Far from being contraindicated, desmopressin is a treatment for mild von Willebrand disease and haemophilia A: through extrarenal V2 receptors it releases von Willebrand factor and factor VIII from endothelium. Excess antidiuretic action causes water retention and dilutional hyponatraemia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.228 Q2, Endocrinology: Aldosterone, Oxytocin, Vasopressin') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aldosterone-oxytocin-vasopressin-ecfb5be6eb', 'pharm-aldosterone-oxytocin-vasopressin', 'mcq', 'A 42-year-old woman developed polyuria, thirst and hypernatraemia after surgical removal of part of her pituitary gland. These signs and symptoms will be treated with which of the following?', '["Prednisone", "Somatropin", "Octreotide", "Bromocriptine", "Desmopressin"]'::jsonb, 'Desmopressin', '[]'::jsonb, 'Damage to the posterior pituitary has caused central diabetes insipidus: without vasopressin the collecting ducts cannot reabsorb water. Desmopressin, a V2-selective analogue given nasally or orally, replaces the missing hormone. Octreotide would treat growth hormone excess, not deficiency of vasopressin.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.228 Q3, Endocrinology: Aldosterone, Oxytocin, Vasopressin. Q9 on p.230 (drug of choice for central diabetes insipidus) dropped as a duplicate.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-40ad0a839f', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'saq', 'True or false: Thyroid hormones are anorexigenic (suppress appetite).', '[]'::jsonb, 'False', '["F"]'::jsonb, 'Thyroid hormones raise the metabolic rate and increase appetite; the hyperthyroid patient typically loses weight despite eating more. Reduced appetite with weight gain is a feature of hypothyroidism.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.228 Q23, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-9d8079c1d9', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'saq', 'True or false: Within cells, T4 is converted to T3.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'T4 is essentially a prohormone. Intracellular 5''-deiodinases remove an outer-ring iodine to give T3, which binds the nuclear thyroid receptor with about ten times the affinity of T4. Around 80% of circulating T3 arises this way.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.228 Q24, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-7e2aee35f1', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'saq', 'True or false: Reverse T3 (rT3) is metabolically inactive.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'Removal of an inner-ring iodine from T4 gives reverse T3, which does not activate the thyroid hormone receptor. Its production rises in starvation and severe illness, when conversion to active T3 is reduced.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.228 Q25, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-4fff28d332', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'saq', 'True or false: When TSH binds to its receptor, adenylate cyclase is stimulated.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'The TSH receptor is coupled to Gs, so binding activates adenylyl cyclase and raises cyclic AMP, which drives iodide uptake, hormone synthesis and release, and growth of the gland. Antibodies in Graves'' disease activate the same receptor.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.228 Q26, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-ce0b098e2f', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'saq', 'True or false: T4 and T3 are synthesised and stored within thyroglobulin.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'Tyrosine residues of thyroglobulin are iodinated and coupled by thyroid peroxidase, and the hormones remain part of the protein, stored as colloid in the follicle lumen. They are released only when thyroglobulin is taken up and broken down by lysosomal proteases.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.228 Q27, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-e85f1f66a8', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'saq', 'True or false: Propylthiouracil inhibits type I 5''-deiodinase activity.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'Besides blocking thyroid peroxidase, propylthiouracil inhibits type 1 5''-deiodinase in liver and kidney, reducing peripheral conversion of T4 to T3. Methimazole and carbimazole lack this action, so propylthiouracil is preferred in thyroid storm.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.228 Q28, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-c7e75ea07f', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'saq', 'True or false: Propylthiouracil inhibits thyroglobulin proteolysis.', '[]'::jsonb, 'False', '["F"]'::jsonb, 'Thioamides block hormone synthesis (peroxidase) but not the release of hormone already stored, which is why their effect takes 3 to 4 weeks. Inhibition of thyroglobulin proteolysis and hormone release is the action of iodide and of lithium.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.228 Q29, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-9980f126fe', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'saq', 'True or false: Propylthiouracil and methimazole cross the placental barrier.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'Both thioamides cross the placenta and can cause foetal goitre and hypothyroidism, so the lowest effective dose is used. Propylthiouracil, being more protein bound, crosses less and is preferred in the first trimester; methimazole is linked to aplasia cutis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.228 Q30, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-03d257fe56', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'saq', 'True or false: Perchlorate may cause fatal aplastic anaemia.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'Potassium perchlorate, which blocks iodide uptake by the thyroid, caused cases of fatal aplastic anaemia at the high doses once used for hyperthyroidism. For this reason it has been abandoned except for special situations such as amiodarone-induced thyrotoxicosis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.228 Q31, Endocrinology: Thyroid Physiology and Treatment') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aldosterone-oxytocin-vasopressin-c3753ecad9', 'pharm-aldosterone-oxytocin-vasopressin', 'mcq', 'Which one of the following antidiuretic hormone antagonists inhibits both V1a and V2 receptors?', '["Conivaptan", "Mozavaptan", "Satavaptan", "Tolvaptan", "Lixivaptan"]'::jsonb, 'Conivaptan', '[]'::jsonb, 'Conivaptan is a non-selective V1a and V2 antagonist given intravenously for euvolaemic or hypervolaemic hyponatraemia. Tolvaptan and the other ''vaptans'' listed are orally active and selective for the V2 receptor, producing excretion of free water (aquaresis).', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.229 Q4, Endocrinology: Aldosterone, Oxytocin, Vasopressin') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aldosterone-oxytocin-vasopressin-0326b418ad', 'pharm-aldosterone-oxytocin-vasopressin', 'mcq', 'Which statement regarding oxytocin is FALSE?', '["It should not be given as a bolus injection because of the risk of hypotension", "It has a serum half-life of about 5 minutes", "It is contraindicated if the foetus is in transverse lie", "It can cause postpartum haemorrhage", "It is important in causing breast milk ejection in lactating mothers"]'::jsonb, 'It can cause postpartum haemorrhage', '[]'::jsonb, 'Oxytocin contracts the uterus and is used to prevent and treat postpartum haemorrhage. Rapid boluses relax vascular smooth muscle and cause hypotension, so it is infused; it is contraindicated where vaginal delivery is impossible, as with a transverse lie.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.229 Q5, Endocrinology: Aldosterone, Oxytocin, Vasopressin. Intended answer D, but uterine atony and haemorrhage after prolonged oxytocin infusion is a listed complication, so D is not strictly false.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aldosterone-oxytocin-vasopressin-1cc6908797', 'pharm-aldosterone-oxytocin-vasopressin', 'mcq', 'Which statement about oxytocin, vasopressin and their analogues is FALSE?', '["Atosiban is an oxytocin antagonist", "DDAVP is a short-acting synthetic analogue of vasopressin", "Higher concentrations of oxytocin activate vasopressin receptors", "Oxytocin is given intravenously for initiation and augmentation of labour", "Desmopressin acetate (DDAVP) is used in the management of haemophilia"]'::jsonb, 'DDAVP is a short-acting synthetic analogue of vasopressin', '[]'::jsonb, 'Desmopressin is a long-acting analogue: deamination and a D-arginine substitution protect it from peptidases, giving a duration of 6 to 20 hours against minutes for vasopressin. High doses of oxytocin do cross-react with V2 receptors and can cause water intoxication.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.229 Q6, Endocrinology: Aldosterone, Oxytocin, Vasopressin') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aldosterone-oxytocin-vasopressin-8c0cdd1d3f', 'pharm-aldosterone-oxytocin-vasopressin', 'mcq', 'Which statement about drugs acting on vasopressin, oxytocin and mineralocorticoid receptors is FALSE?', '["Conivaptan is used in the treatment of hyponatraemia", "Fludrocortisone is widely used as a mineralocorticoid", "Desmopressin acetate is a long-acting synthetic analogue of vasopressin", "Oxytocin is given intramuscularly in the treatment of postpartum haemorrhage", "Atosiban is an oxytocin receptor agonist"]'::jsonb, 'Atosiban is an oxytocin receptor agonist', '[]'::jsonb, 'Atosiban is a competitive antagonist at oxytocin receptors, used as a tocolytic to delay preterm labour. Oxytocin can indeed be given intramuscularly after delivery of the placenta to control bleeding, as well as by intravenous infusion.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.229 Q7, Endocrinology: Aldosterone, Oxytocin, Vasopressin') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aldosterone-oxytocin-vasopressin-d04df3c7c9', 'pharm-aldosterone-oxytocin-vasopressin', 'mcq', 'A 42-year-old woman requires treatment for diabetes insipidus following surgical removal of part of her pituitary gland. The advantage of treating this patient with desmopressin instead of vasopressin is that desmopressin:', '["Is more selective for the V2 receptor subtype", "Causes less hypernatraemia", "Provides greater relief of the excessive thirst", "Causes less hyperprolactinaemia", "Causes less formation of factor VIII"]'::jsonb, 'Is more selective for the V2 receptor subtype', '[]'::jsonb, 'Desmopressin has an antidiuretic-to-pressor ratio thousands of times that of vasopressin, so it corrects the polyuria without V1-mediated vasoconstriction, coronary spasm or gut cramps; it also lasts much longer. It increases, not decreases, factor VIII release.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.229 Q8, Endocrinology: Aldosterone, Oxytocin, Vasopressin') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aldosterone-oxytocin-vasopressin-1cda9de5c4', 'pharm-aldosterone-oxytocin-vasopressin', 'mcq', 'Secretion of aldosterone from the adrenal cortex is stimulated by:', '["Propranolol", "Clonidine", "Angiotensin II", "Methyldopa", "Spironolactone"]'::jsonb, 'Angiotensin II', '[]'::jsonb, 'Angiotensin II acts on AT1 receptors in the zona glomerulosa to stimulate aldosterone synthesis; a raised plasma potassium is the other main stimulus. Propranolol, clonidine and methyldopa all reduce renin release and so tend to lower aldosterone.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.229 Q8b, Endocrinology: Aldosterone, Oxytocin, Vasopressin. Second question numbered 8.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aldosterone-oxytocin-vasopressin-3fb1d2fad3', 'pharm-aldosterone-oxytocin-vasopressin', 'mcq', 'Nephrogenic diabetes insipidus is treated with:', '["Lithium carbonate", "Demeclocycline", "Colchicine", "Thiazide diuretics", "Methoxyflurane"]'::jsonb, 'Thiazide diuretics', '[]'::jsonb, 'Thiazides paradoxically reduce urine volume: mild sodium depletion increases proximal reabsorption of salt and water, so less fluid reaches the vasopressin-insensitive collecting duct. Lithium, demeclocycline and methoxyflurane are causes of nephrogenic diabetes insipidus, not treatments.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.230 Q10, Endocrinology: Aldosterone, Oxytocin, Vasopressin') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aldosterone-oxytocin-vasopressin-495c807c97', 'pharm-aldosterone-oxytocin-vasopressin', 'mcq', 'A V1 receptor-mediated therapeutic application of vasopressin is the treatment of:', '["Postpartum haemorrhage", "Central diabetes insipidus", "Nephrogenic diabetes insipidus", "Bleeding oesophageal varices", "Primary nocturnal enuresis"]'::jsonb, 'Bleeding oesophageal varices', '[]'::jsonb, 'V1 receptors on vascular smooth muscle (Gq-coupled) cause vasoconstriction; in the splanchnic bed this lowers portal pressure and controls variceal bleeding, for which terlipressin is used. Diabetes insipidus and enuresis are treated through the renal V2 receptor.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.230 Q11, Endocrinology: Aldosterone, Oxytocin, Vasopressin') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aldosterone-oxytocin-vasopressin-e50f35ab50', 'pharm-aldosterone-oxytocin-vasopressin', 'mcq', 'The drug of choice for induction of labour is:', '["Magnesium sulphate", "Ritodrine", "Nifedipine", "Ergotamine", "Oxytocin"]'::jsonb, 'Oxytocin', '[]'::jsonb, 'Oxytocin by controlled intravenous infusion produces rhythmic, physiological contractions with relaxation in between, preserving placental blood flow. Ergot alkaloids cause sustained tetanic contraction that would asphyxiate the foetus; ritodrine, nifedipine and magnesium are tocolytics.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.230 Q12, Endocrinology: Aldosterone, Oxytocin, Vasopressin') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcitonin-bisphosphonates-and-fluorid-5b4ebb1600', 'pharm-calcitonin-bisphosphonates-and-fluorides', 'mcq', 'Which statement is true regarding calcitonin?', '["It causes bone resorption", "It is a pituitary hormone", "It is a phospholipid hormone", "It lowers serum calcium", "It has no effect on the kidney"]'::jsonb, 'It lowers serum calcium', '[]'::jsonb, 'Calcitonin, a 32-amino-acid peptide from the parafollicular C cells of the thyroid, lowers serum calcium and phosphate by inhibiting osteoclastic bone resorption and by reducing renal tubular reabsorption of both ions.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.230 Q1, Endocrinology: Calcitonin, bisphosphonates and Fluorides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aldosterone-oxytocin-vasopressin-fc5a38a90c', 'pharm-aldosterone-oxytocin-vasopressin', 'saq', 'True or false: V1 receptors mediate the antidiuretic effect of vasopressin.', '[]'::jsonb, 'False', '["F"]'::jsonb, 'The antidiuretic effect is mediated by V2 receptors in the collecting duct, which raise cyclic AMP and insert aquaporin-2 water channels into the luminal membrane. V1 receptors, coupled to Gq, mediate vasoconstriction.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.230 Q13, Endocrinology: Aldosterone, Oxytocin, Vasopressin') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aldosterone-oxytocin-vasopressin-2055b7e5cc', 'pharm-aldosterone-oxytocin-vasopressin', 'saq', 'True or false: Aldosterone decreases urinary excretion of potassium.', '[]'::jsonb, 'False', '["F"]'::jsonb, 'Aldosterone increases sodium reabsorption through epithelial sodium channels in the distal nephron in exchange for potassium and hydrogen ions, so urinary potassium excretion rises. Excess aldosterone therefore causes hypokalaemia and alkalosis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.230 Q14, Endocrinology: Aldosterone, Oxytocin, Vasopressin') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-treating-pancreatic-disorder-4395422b79', 'pharm-drugs-for-treating-pancreatic-disorders-aprotinin-glucagon-use-o', 'saq', 'True or false: Glucagon has a positive inotropic effect on the heart.', '[]'::jsonb, 'True', '["T"]'::jsonb, 'Glucagon acts on its own Gs-coupled receptors in the myocardium to raise cyclic AMP, increasing contractility and heart rate without using beta adrenoceptors. This is why it is used as an antidote in beta-blocker overdose.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.230 Q15, Endocrinology: Aldosterone, Oxytocin, Vasopressin. No endocrine topic covers glucagon; placed under the GIT topic that names it.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcitonin-bisphosphonates-and-fluorid-2f23a63c02', 'pharm-calcitonin-bisphosphonates-and-fluorides', 'mcq', 'Which of the following is a third-generation bisphosphonate?', '["Etidronate", "Alendronate", "Risedronate", "Tiludronate", "Pamidronate"]'::jsonb, 'Risedronate', '[]'::jsonb, 'Risedronate and zoledronate are third-generation agents, with a nitrogen-containing heterocyclic ring and the highest potency. Etidronate and tiludronate are first-generation non-nitrogenous compounds, and alendronate and pamidronate are second-generation aminobisphosphonates.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.231 Q2, Endocrinology: Calcitonin, bisphosphonates and Fluorides') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcitonin-bisphosphonates-and-fluorid-029ea14ebb', 'pharm-calcitonin-bisphosphonates-and-fluorides', 'mcq', 'Which statement is true of bisphosphonates?', '["They have high oral bioavailability", "They are associated with hypercalcaemia", "They are highly antigenic", "They are not effective in Paget''s disease of bone", "They may be used in the treatment of postmenopausal osteoporosis"]'::jsonb, 'They may be used in the treatment of postmenopausal osteoporosis', '[]'::jsonb, 'Bisphosphonates bind hydroxyapatite and inhibit osteoclasts, so they are first-line for postmenopausal osteoporosis, Paget''s disease and hypercalcaemia of malignancy. Less than 1% of an oral dose is absorbed, hence the fasting, upright dosing instructions.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.231 Q3, Endocrinology: Calcitonin, bisphosphonates and Fluorides. Option a changed from ''Administered intravenously'' (true of zoledronate and pamidronate, so a second correct answer) to a false statement.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oestrogens-progestins-oral-contracepti-8bc9259325', 'pharm-oestrogens-progestins-oral-contraceptives', 'mcq', 'Which is a selective oestrogen receptor downregulator?', '["Flutamide", "Tamoxifen", "Toremifene", "Bazedoxifene", "Fulvestrant"]'::jsonb, 'Fulvestrant', '[]'::jsonb, 'Fulvestrant is a pure oestrogen receptor antagonist that also accelerates degradation of the receptor, with no agonist action in any tissue; it is used in tamoxifen-resistant breast cancer. Tamoxifen, toremifene and bazedoxifene are selective modulators with tissue-dependent agonist effects.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.231 Q2, Endocrinology: Oestrogens, Progestins, Oral Contraceptives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oestrogens-progestins-oral-contracepti-713e3d4d07', 'pharm-oestrogens-progestins-oral-contraceptives', 'mcq', 'Which statement regarding the effects of oestrogen is FALSE?', '["Retention of sodium and water", "Lowering of LDL", "Maintenance of skeletal integrity", "Increase in bone resorption", "Stimulation of leptin production in adipose tissue"]'::jsonb, 'Increase in bone resorption', '[]'::jsonb, 'Oestrogens reduce bone resorption by restraining osteoclast activity and promoting osteoclast apoptosis; their loss at the menopause is what accelerates bone loss. They also raise HDL, lower LDL and cause some salt and water retention.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.231 Q3, Endocrinology: Oestrogens, Progestins, Oral Contraceptives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oestrogens-progestins-oral-contracepti-ed713815f2', 'pharm-oestrogens-progestins-oral-contraceptives', 'mcq', 'Diethylstilbestrol (DES) should never be used in pregnant women because it is associated with which of the following?', '["Miscarriages", "Deep vein thrombosis", "Infertility and development of vaginal cancer in female offspring", "Virilisation of the external genitalia of female offspring", "Feminisation of the external genitalia of male offspring"]'::jsonb, 'Infertility and development of vaginal cancer in female offspring', '[]'::jsonb, 'Daughters exposed to DES in utero developed clear cell adenocarcinoma of the vagina and cervix in adolescence, along with genital tract abnormalities and infertility. Ironically it had been prescribed to prevent miscarriage, for which it was ineffective.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.232 Q5, Endocrinology: Oestrogens, Progestins, Oral Contraceptives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oestrogens-progestins-oral-contracepti-ee86fb6479', 'pharm-oestrogens-progestins-oral-contraceptives', 'mcq', 'All of the following are true of medroxyprogesterone EXCEPT:', '["It antagonises aldosterone-induced sodium retention", "It is used as a test for oestrogen secretion", "It is used for contraception", "It acts on progesterone receptors located in both the cytoplasm and the nucleus", "It is administered intramuscularly only"]'::jsonb, 'It is administered intramuscularly only', '[]'::jsonb, 'Medroxyprogesterone acetate is active by mouth as well as by depot intramuscular or subcutaneous injection. Oral courses are used for the progestogen withdrawal test (bleeding shows the endometrium has been primed by oestrogen), and the depot is a three-monthly contraceptive.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.232 Q6, Endocrinology: Oestrogens, Progestins, Oral Contraceptives. Option a is true of natural progesterone but doubtful for medroxyprogesterone, so two options could be argued.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oestrogens-progestins-oral-contracepti-03a0ef4164', 'pharm-oestrogens-progestins-oral-contraceptives', 'mcq', 'All of the following are true of oral contraceptives EXCEPT:', '["The dose of one or more components is changed twice during the menstrual cycle in biphasic pills", "The majority of women ovulate within 3 months of discontinuation", "Hormones are administered for 21 days followed by inert pills for 7 days", "Combination pills suppress lactation", "They cause deep venous thrombosis"]'::jsonb, 'The dose of one or more components is changed twice during the menstrual cycle in biphasic pills', '[]'::jsonb, 'In biphasic pills the dose of one or both hormones is changed once in the cycle; two changes define a triphasic pill. Fertility returns quickly, with most women ovulating within three cycles, and the oestrogen component reduces milk volume and raises thrombotic risk.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.232 Q7, Endocrinology: Oestrogens, Progestins, Oral Contraceptives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oestrogens-progestins-oral-contracepti-24ca40e72f', 'pharm-oestrogens-progestins-oral-contraceptives', 'mcq', 'Which is NOT a metabolic effect of oestrogen?', '["Reduced bone resorption", "Increased levels of thyroxine-binding globulin", "Reduced levels of transferrin", "Reduced total cholesterol", "Increased high-density lipoprotein (HDL)"]'::jsonb, 'Reduced levels of transferrin', '[]'::jsonb, 'Oestrogens stimulate hepatic synthesis of many transport proteins, so transferrin rises along with thyroxine-binding, corticosteroid-binding and sex hormone-binding globulins, as do clotting factors. The lipid changes, lower LDL and higher HDL, are also hepatic effects.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.232 Q8, Endocrinology: Oestrogens, Progestins, Oral Contraceptives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oestrogens-progestins-oral-contracepti-1f4f8f8f81', 'pharm-oestrogens-progestins-oral-contraceptives', 'mcq', 'Mechanisms of action of combination oral contraceptives include all of the following EXCEPT:', '["Inhibition of ovulation", "Inhibition of release of FSH and LH", "Rendering the endometrium unsuitable for implantation", "Decreasing the viscosity of cervical mucus", "Interfering with the coordinated contractions of cervix, uterus and fallopian tubes necessary for fertilisation and implantation"]'::jsonb, 'Decreasing the viscosity of cervical mucus', '[]'::jsonb, 'The progestogen makes cervical mucus thick, scanty and viscous, which hinders sperm penetration; thin watery mucus is the oestrogen effect seen at ovulation. The main mechanism is suppression of FSH and LH, preventing follicle development and the ovulatory surge.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.232 Q9, Endocrinology: Oestrogens, Progestins, Oral Contraceptives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oestrogens-progestins-oral-contracepti-0242d6db23', 'pharm-oestrogens-progestins-oral-contraceptives', 'mcq', 'Adverse effects of combination oral contraceptives include all of the following EXCEPT:', '["Peripheral neuropathy", "Nausea", "Weight gain", "Hirsutism", "Breast tenderness"]'::jsonb, 'Peripheral neuropathy', '[]'::jsonb, 'The pill does not damage peripheral nerves. Nausea and breast tenderness are oestrogenic effects, while weight gain, acne and hirsutism are due to androgenic progestogens derived from 19-nortestosterone. The serious risks are venous thromboembolism, hypertension and stroke.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.233 Q10, Endocrinology: Oestrogens, Progestins, Oral Contraceptives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oestrogens-progestins-oral-contracepti-b394dfc5c5', 'pharm-oestrogens-progestins-oral-contraceptives', 'mcq', 'Contraindications of combination oral contraceptives include all of the following EXCEPT:', '["Presence or history of thromboembolic disease", "Impaired liver function", "Carcinoma of the breast", "Endometriosis", "Abnormal undiagnosed vaginal bleeding"]'::jsonb, 'Endometriosis', '[]'::jsonb, 'Combined pills are actually a treatment for endometriosis: continuous use suppresses ovulation and causes atrophy of ectopic endometrium. The others are true contraindications because oestrogen is thrombogenic, is cleared by the liver and stimulates hormone-dependent tumours.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.233 Q11, Endocrinology: Oestrogens, Progestins, Oral Contraceptives. Removed the hint ''(OCPs are often used to treat it)'' from option D.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oestrogens-progestins-oral-contracepti-0b07a4d7c8', 'pharm-oestrogens-progestins-oral-contraceptives', 'mcq', 'Which of the following is used as a hormonal contraceptive given by subcutaneous implantation?', '["Ethinyl oestradiol", "Diethylstilboestrol", "Tamoxifen", "Mifepristone", "Norgestrel"]'::jsonb, 'Norgestrel', '[]'::jsonb, 'Levonorgestrel, the active isomer of norgestrel, is released slowly from subdermal rods (Norplant, Jadelle) and gives up to five years of contraception; etonogestrel implants work similarly. Implants contain progestogen only, never an oestrogen.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.233 Q12, Endocrinology: Oestrogens, Progestins, Oral Contraceptives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oestrogens-progestins-oral-contracepti-f9d3c33c4d', 'pharm-oestrogens-progestins-oral-contraceptives', 'mcq', 'The anti-oestrogen used in the treatment of oestrogen-dependent breast cancer is:', '["Clomiphene", "Nandrolone", "Tamoxifen", "Cyproterone", "Mifepristone"]'::jsonb, 'Tamoxifen', '[]'::jsonb, 'Tamoxifen is a selective oestrogen receptor modulator that antagonises oestrogen in breast tissue, so it is used for receptor-positive breast cancer. Clomiphene is also an anti-oestrogen, but it acts on the hypothalamus and is used to induce ovulation.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.233 Q13, Endocrinology: Oestrogens, Progestins, Oral Contraceptives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oestrogens-progestins-oral-contracepti-5929ff6c4b', 'pharm-oestrogens-progestins-oral-contraceptives', 'mcq', 'Which of the following is used for induction of ovulation in the treatment of infertility?', '["Ethinyl oestradiol", "Diethylstilboestrol", "Oestradiol valerate", "Clomiphene", "Medroxyprogesterone acetate"]'::jsonb, 'Clomiphene', '[]'::jsonb, 'Clomiphene blocks oestrogen receptors in the hypothalamus and pituitary, removing negative feedback; the resulting surge of GnRH, FSH and LH stimulates follicle development. Multiple pregnancy and ovarian hyperstimulation are its main risks. Oestrogens and progestogens suppress ovulation.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.233 Q14, Endocrinology: Oestrogens, Progestins, Oral Contraceptives') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcium-vitamin-d-and-analogues-f4f7b4a953', 'pharm-calcium-vitamin-d-and-analogues', 'mcq', 'Which one of the following vitamin D preparations requires 25-hydroxylation in vivo?', '["Calcifediol", "Paricalcitol", "Maxacalcitol", "Doxercalciferol", "Falecalcitriol"]'::jsonb, 'Doxercalciferol', '[]'::jsonb, 'Doxercalciferol is 1-alpha-hydroxyvitamin D2, a prodrug that the liver 25-hydroxylates to the active 1,25-dihydroxy form. Calcifediol is already 25-hydroxylated, and paricalcitol, maxacalcitol and falecalcitriol are active calcitriol analogues.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.233 Q1, Endocrinology: Calcium, Vitamin D and Analogues') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcium-vitamin-d-and-analogues-2590b57bf3', 'pharm-calcium-vitamin-d-and-analogues', 'mcq', 'Which is NOT an effect of calcitriol?', '["It increases intestinal calcium absorption", "It increases levels of parathyroid hormone", "It reduces urinary excretion of phosphate", "It stimulates osteoclast activity", "It increases renal calcium reabsorption"]'::jsonb, 'It increases levels of parathyroid hormone', '[]'::jsonb, 'Calcitriol suppresses transcription of the parathyroid hormone gene, and the calcium it raises inhibits secretion further; this is why it and its analogues treat secondary hyperparathyroidism in renal failure. It increases gut absorption and renal retention of calcium and phosphate.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.234 Q2, Endocrinology: Calcium, Vitamin D and Analogues') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcium-vitamin-d-and-analogues-ccd6ae1de9', 'pharm-calcium-vitamin-d-and-analogues', 'mcq', 'Which statement regarding calcium is FALSE?', '["Glucocorticoids inhibit calcium transport", "Dietary phytates inhibit calcium absorption", "Parathyroid hormone increases renal tubular reabsorption of calcium", "Most of the calcium filtered at the glomerulus is reabsorbed in the proximal tubule", "Intravenously administered calcium gluconate has higher elemental calcium compared to calcium chloride"]'::jsonb, 'Intravenously administered calcium gluconate has higher elemental calcium compared to calcium chloride', '[]'::jsonb, 'Calcium chloride contains about 27% elemental calcium, three times the 9% in calcium gluconate, but gluconate is preferred intravenously because it is much less irritant to veins. Phytates and oxalates bind dietary calcium in the gut.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.234 Q3, Endocrinology: Calcium, Vitamin D and Analogues. Option D reworded from ''About 50% of calcium filtered... is reabsorbed in the proximal tubule'' (figure is nearer 60-70%) so that it is clearly true.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcium-vitamin-d-and-analogues-55925f0429', 'pharm-calcium-vitamin-d-and-analogues', 'mcq', 'Which one of the following vitamin D preparations requires enzymatic activation via 25-hydroxylation in the liver?', '["Calcifediol", "Maxacalcitol", "Calcitriol", "Paricalcitol", "Alfacalcidol"]'::jsonb, 'Alfacalcidol', '[]'::jsonb, 'Alfacalcidol is 1-alpha-hydroxycholecalciferol; hepatic 25-hydroxylation converts it rapidly to calcitriol. Because it bypasses the renal 1-alpha-hydroxylation step it is useful in chronic kidney disease. Calcifediol instead needs 1-hydroxylation in the kidney.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.234 Q4, Endocrinology: Calcium, Vitamin D and Analogues') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcium-vitamin-d-and-analogues-d12570e3f3', 'pharm-calcium-vitamin-d-and-analogues', 'mcq', 'The following are useful in the management of hypercalcaemia EXCEPT:', '["Mithramycin (plicamycin)", "Hydrochlorothiazide", "Furosemide", "Prednisolone", "Calcitonin"]'::jsonb, 'Hydrochlorothiazide', '[]'::jsonb, 'Thiazides increase distal tubular reabsorption of calcium and can cause or worsen hypercalcaemia. Furosemide with saline does the opposite, promoting calcium excretion. Calcitonin and plicamycin inhibit bone resorption, and steroids help in sarcoidosis, vitamin D toxicity and myeloma.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.234 Q5, Endocrinology: Calcium, Vitamin D and Analogues') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcium-vitamin-d-and-analogues-bd8187a542', 'pharm-calcium-vitamin-d-and-analogues', 'mcq', 'Which of the following calcium preparations contains the highest proportion of elemental calcium?', '["Calcium citrate", "Calcium acetate", "Calcium carbonate", "Calcium gluconate", "Calcium lactate"]'::jsonb, 'Calcium carbonate', '[]'::jsonb, 'Calcium carbonate is 40% elemental calcium by weight, the highest of the common salts, which is why it is the usual oral supplement. Acetate has about 25%, citrate 21%, lactate 13% and gluconate 9%.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.234 Q6, Endocrinology: Calcium, Vitamin D and Analogues. Replaced the option ''Calcium phosphate'' (tribasic form is about 39%, too close to carbonate) with calcium gluconate.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcium-vitamin-d-and-analogues-7fb9536c3b', 'pharm-calcium-vitamin-d-and-analogues', 'mcq', 'Which of the following vitamin D preparations does NOT require enzymatic activation?', '["Paricalcitol", "Calcifediol", "Ergocalciferol", "Doxercalciferol", "Alfacalcidol"]'::jsonb, 'Paricalcitol', '[]'::jsonb, 'Paricalcitol is a synthetic analogue of calcitriol that binds the vitamin D receptor directly. Ergocalciferol needs both 25- and 1-hydroxylation, calcifediol needs renal 1-hydroxylation, and doxercalciferol and alfacalcidol need hepatic 25-hydroxylation.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.234 Q7, Endocrinology: Calcium, Vitamin D and Analogues') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcium-vitamin-d-and-analogues-45ff78cd7e', 'pharm-calcium-vitamin-d-and-analogues', 'mcq', 'All of the following are useful in the treatment of hypercalcaemia EXCEPT:', '["Prednisone", "Calcitonin", "Etidronate", "Mithramycin", "Cholecalciferol"]'::jsonb, 'Cholecalciferol', '[]'::jsonb, 'Cholecalciferol (vitamin D3) raises serum calcium by increasing intestinal absorption and bone resorption, so it would worsen hypercalcaemia. Glucocorticoids reduce calcium absorption, calcitonin and bisphosphonates such as etidronate inhibit osteoclasts, and mithramycin (plicamycin) is a cytotoxic inhibitor of bone resorption.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.235 Q8, Calcium, Vitamin D and Analogues') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcitonin-bisphosphonates-and-fluorid-87fd995251', 'pharm-calcitonin-bisphosphonates-and-fluorides', 'mcq', 'Calcitonin is used in the treatment of:', '["Hyperaldosteronism", "Hyperthyroidism", "Hypercalcaemia", "Hyperkalaemia", "Hyperuricaemia"]'::jsonb, 'Hypercalcaemia', '[]'::jsonb, 'Calcitonin inhibits osteoclastic bone resorption and increases renal calcium excretion, lowering serum calcium within hours. It is therefore used in hypercalcaemia, Paget disease and osteoporosis. Although it is secreted by thyroid C cells, it has no role in hyperthyroidism.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.235 Q9, Calcium, Vitamin D and Analogues') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-a599b62016', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'mcq', 'Which statement regarding pramlintide (an amylin analogue) is FALSE?', '["It is usually used as monotherapy", "It delays gastric emptying", "It is metabolised in the kidney", "It is injected subcutaneously immediately before meals", "It causes anorexia"]'::jsonb, 'It is usually used as monotherapy', '[]'::jsonb, 'Pramlintide is only an adjunct to mealtime insulin in type 1 and type 2 diabetes; it is not used alone. It slows gastric emptying, suppresses glucagon and promotes satiety (anorexia), is given subcutaneously just before meals and is metabolised and excreted mainly by the kidney.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.235 Q1, Insulins and Other Parenteral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-a881c3837c', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'mcq', 'Which statement regarding parenteral antidiabetic agents is INCORRECT?', '["Albiglutide is administered once every two weeks", "Semaglutide may increase the risk of pancreatitis", "Pramlintide causes delayed gastric emptying", "Insulin can be administered via inhaler", "Insulin degludec has a duration of action of more than 42 hours"]'::jsonb, 'Albiglutide is administered once every two weeks', '[]'::jsonb, 'Albiglutide is a long-acting GLP-1 agonist fused to albumin and was given once weekly, not every two weeks. The other statements are true: GLP-1 agonists carry a pancreatitis warning, pramlintide slows gastric emptying, inhaled regular insulin exists, and degludec is ultra-long acting (over 42 hours).', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.235 Q3, Insulins and Other Parenteral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-5b47f53d80', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'mcq', 'Which statement regarding insulin is FALSE?', '["Insulin glargine is soluble in acidic solution", "It can be administered via inhalation", "Regular insulin is preferred for use in continuous subcutaneous insulin infusion devices", "Short-acting insulin should be injected half an hour before meals", "Insulin degludec has a duration of action of more than 42 hours"]'::jsonb, 'Regular insulin is preferred for use in continuous subcutaneous insulin infusion devices', '[]'::jsonb, 'Insulin pumps preferably use rapid-acting analogues (lispro, aspart, glulisine) because their fast onset and short duration allow precise basal and bolus dosing. Regular insulin forms hexamers and acts more slowly, which is also why it must be injected about 30 minutes before a meal. Glargine is soluble at pH 4 and precipitates at tissue pH.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.235 Q4, Insulins and Other Parenteral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-1ee69be244', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'mcq', 'Which statement regarding insulin is TRUE?', '["Glargine is ultrashort acting", "Intermediate-acting insulin should never be mixed with short-acting insulin", "Hyperkalaemia is a common complication of insulin therapy", "It is a derivative of arachidonic acid", "Endogenous insulin has a half-life of about 5 minutes"]'::jsonb, 'Endogenous insulin has a half-life of about 5 minutes', '[]'::jsonb, 'Circulating endogenous insulin has a plasma half-life of only 3 to 5 minutes, being cleared mainly by the liver and kidney. Glargine is long acting, NPH is routinely mixed with regular insulin, insulin drives potassium into cells (hypokalaemia), and insulin is a peptide, not an eicosanoid.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.236 Q5, Insulins and Other Parenteral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-212821a960', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'mcq', 'Identify the long-acting insulin:', '["Insulin detemir", "NPH insulin", "Regular insulin", "Inhaled insulin", "Insulin aspart"]'::jsonb, 'Insulin detemir', '[]'::jsonb, 'Insulin detemir has a fatty acid side chain that binds albumin, prolonging its action to give a basal insulin. NPH (isophane) is intermediate acting, regular insulin is short acting, and aspart and inhaled insulin are rapid acting mealtime insulins.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.236 Q6, Insulins and Other Parenteral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-aaa2173b78', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'mcq', 'Which of the following is a glucagon-like peptide 1 (GLP-1) analogue used in the management of diabetes mellitus?', '["Glimepiride", "Exenatide", "Sitagliptin", "Pramlintide", "Empagliflozin"]'::jsonb, 'Exenatide', '[]'::jsonb, 'Exenatide is an injectable GLP-1 receptor agonist that enhances glucose-dependent insulin release, suppresses glucagon and slows gastric emptying. Sitagliptin is tempting because it works through the same incretin pathway, but it is a DPP-4 inhibitor that prevents breakdown of endogenous GLP-1 rather than being an analogue.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.236 Q7, Insulins and Other Parenteral Antidiabetic Drugs. Same question repeated as Q9 on p.236 (with teriparatide and vildagliptin as distractors); one copy kept.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-acdb201713', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'mcq', 'Which of the following insulin preparations can be injected once a week?', '["NPH insulin", "Insulin glargine", "Insulin lispro", "Insulin icodec", "Regular insulin"]'::jsonb, 'Insulin icodec', '[]'::jsonb, 'Insulin icodec binds strongly and reversibly to albumin, giving a half-life of about a week, so it is injected once weekly as a basal insulin. Glargine is the tempting distractor, but it is a once-daily basal insulin lasting roughly 24 hours.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.236 Q8, Insulins and Other Parenteral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-82667e4924', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'mcq', 'Insulin secretion is stimulated by all of the following EXCEPT:', '["Beta-2 adrenergic agonists", "Arginine", "Prostaglandin E1", "Glucose", "Gastrin"]'::jsonb, 'Prostaglandin E1', '[]'::jsonb, 'Glucose, amino acids such as arginine, gut hormones (including gastrin and the incretins) and beta-2 adrenoceptor stimulation all promote insulin release. E-series prostaglandins inhibit glucose-stimulated insulin secretion from beta cells, as do alpha-2 agonists and somatostatin.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.236 Q10, Insulins and Other Parenteral Antidiabetic Drugs. The inhibitory effect is best documented for PGE2; some sources report PGE1 can stimulate insulin release. Answer follows the standard textbook key; needs a human check.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-dc9e73ac85', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'mcq', 'Actions of insulin on the liver include all of the following EXCEPT:', '["Decreased gluconeogenesis", "Decreased glycogenolysis", "Decreased triglyceride synthesis", "Decreased protein catabolism", "Increased glycogen storage"]'::jsonb, 'Decreased triglyceride synthesis', '[]'::jsonb, 'Insulin is anabolic: in the liver it promotes glycogen storage and increases triglyceride and VLDL synthesis, while suppressing gluconeogenesis, glycogenolysis and protein breakdown. A fall in triglyceride synthesis is the opposite of its lipogenic action.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.237 Q12, Insulins and Other Parenteral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-4b0c402bbb', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'mcq', 'With subcutaneous injection of soluble (regular) insulin, peak action occurs in:', '["1/2-1 hour", "2-4 hours", "6-12 hours", "16-18 hours", "20-36 hours"]'::jsonb, '2-4 hours', '[]'::jsonb, 'Regular insulin forms hexamers that must dissociate before absorption, so after subcutaneous injection it starts acting in about 30 minutes, peaks at 2 to 4 hours and lasts 5 to 8 hours. A peak within the first hour is typical of the rapid-acting analogues such as lispro.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.237 Q13, Insulins and Other Parenteral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-51c83ab478', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'mcq', 'The duration of action of NPH (isophane) insulin is:', '["1/2-1 hour", "2-4 hours", "6-12 hours", "18-24 hours", "24-36 hours"]'::jsonb, '18-24 hours', '[]'::jsonb, 'NPH insulin is complexed with protamine, which delays absorption; it is an intermediate-acting insulin with onset at 1 to 2 hours, peak at 6 to 12 hours and a total duration traditionally quoted as 18 to 24 hours. The 6 to 12 hour figure is its peak, not its duration.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.237 Q14, Insulins and Other Parenteral Antidiabetic Drugs. Textbooks disagree on the duration of NPH: Katzung gives 4-12 h, others 10-18 h or up to 24 h. The paper it came from expects 18-24 hours.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-aa137efb68', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'mcq', 'The insulin preparation that can be administered intravenously is:', '["Soluble (regular) insulin", "Isophane (NPH) insulin", "Lente insulin", "Ultralente insulin", "Semilente insulin"]'::jsonb, 'Soluble (regular) insulin', '[]'::jsonb, 'Soluble (regular) insulin is a clear solution, so it can be given intravenously, for example in diabetic ketoacidosis. NPH and the lente family are suspensions of insulin crystals or complexes designed for slow subcutaneous absorption and must never be injected into a vein.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.237 Q15, Insulins and Other Parenteral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-a191b7afdc', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'mcq', 'Adverse effects of insulin include all of the following EXCEPT:', '["Hypoglycaemia", "Lipohypertrophy or lipoatrophy at the injection site", "Hypersensitivity reactions", "Cholestatic jaundice", "Insulin resistance"]'::jsonb, 'Cholestatic jaundice', '[]'::jsonb, 'Insulin causes hypoglycaemia, weight gain, local lipodystrophy, allergy and occasionally antibody-mediated insulin resistance. It is not hepatotoxic; cholestatic jaundice is an adverse effect of sulphonylureas such as chlorpropamide, not of insulin.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.237 Q16, Insulins and Other Parenteral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-0065508ce1', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'mcq', 'Insulin requirements are increased by all of the following EXCEPT:', '["Exercise", "Infection", "Pregnancy", "Obesity", "Glucocorticoids"]'::jsonb, 'Exercise', '[]'::jsonb, 'Exercise increases insulin-independent glucose uptake by muscle and speeds insulin absorption, so the dose needed falls and hypoglycaemia may occur. Infection, pregnancy, obesity and glucocorticoids all cause insulin resistance and raise requirements.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.238 Q17, Insulins and Other Parenteral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-insulins-and-other-parenteral-antidiab-d46ac4b107', 'pharm-insulins-and-other-parenteral-antidiabetic-drugs', 'mcq', 'In severe ketoacidosis in a 12-year-old girl, the appropriate antidiabetic to be used is:', '["Glibenclamide", "NPH insulin", "Soluble (regular) insulin", "Protamine zinc insulin", "Ultralente insulin"]'::jsonb, 'Soluble (regular) insulin', '[]'::jsonb, 'Diabetic ketoacidosis needs rapidly titratable insulin given intravenously, and only soluble (regular) insulin can be infused. Intermediate and long-acting suspensions act too slowly and cannot be given intravenously; sulphonylureas are useless in the insulin-deficient patient.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.238 Q18, Insulins and Other Parenteral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-treating-pancreatic-disorder-ab40681491', 'pharm-drugs-for-treating-pancreatic-disorders-aprotinin-glucagon-use-o', 'mcq', 'Glucagon is used to treat:', '["Severe hypoglycaemia", "Ventricular arrhythmias", "Acute attacks of angina pectoris", "Acute attacks of bronchial asthma", "Thyroid storm (thyrotoxic crisis)"]'::jsonb, 'Severe hypoglycaemia', '[]'::jsonb, 'Glucagon raises blood glucose by stimulating hepatic glycogenolysis and gluconeogenesis through cyclic AMP, so it is given intramuscularly or subcutaneously for severe hypoglycaemia when intravenous glucose is not possible. It is also used in beta-blocker overdose, but not for the other listed conditions.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.238 Q19, Insulins and Other Parenteral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-f8b3790d74', 'pharm-oral-antidiabetic-drugs', 'mcq', 'Which statement is TRUE of metformin?', '["It is metabolised in the liver", "It increases body weight", "It causes hypoglycaemia", "Gastrointestinal adverse effects are the most common", "It is third-line therapy for type 2 diabetes mellitus"]'::jsonb, 'Gastrointestinal adverse effects are the most common', '[]'::jsonb, 'Nausea, diarrhoea, abdominal discomfort and anorexia affect up to a fifth of patients on metformin and are its commonest adverse effects. It is excreted unchanged by the kidney, is weight neutral or causes weight loss, does not cause hypoglycaemia alone and is first-line therapy.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.238 Q1, Oral Antidiabetic Drugs. Same question repeated as Q9 on p.239; one copy kept.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-3165d0bb47', 'pharm-oral-antidiabetic-drugs', 'mcq', 'Which drug is contraindicated in elderly patients with diabetes mellitus?', '["Metformin", "Glipizide", "Tolbutamide", "Acarbose", "Chlorpropamide"]'::jsonb, 'Chlorpropamide', '[]'::jsonb, 'Chlorpropamide has a very long half-life (about 32 hours) and is renally excreted, so it accumulates in the elderly and causes prolonged, dangerous hypoglycaemia as well as hyponatraemia. Shorter-acting sulphonylureas such as glipizide or tolbutamide are safer in older patients.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.238 Q2, Oral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-5b2b178a07', 'pharm-oral-antidiabetic-drugs', 'mcq', 'Which statement regarding metformin is TRUE?', '["It can safely be given in end-stage kidney disease if the dose is reduced", "It is 99% plasma protein bound", "It is metabolised by CYP3A4 to an active metabolite", "Hypoglycaemia is one of its significant adverse effects", "Long-term use has been associated with megaloblastic anaemia"]'::jsonb, 'Long-term use has been associated with megaloblastic anaemia', '[]'::jsonb, 'Metformin reduces vitamin B12 absorption in the terminal ileum, so long-term use can cause B12 deficiency and megaloblastic anaemia. It is not protein bound or metabolised, is excreted unchanged in urine, is contraindicated in end-stage kidney disease (lactic acidosis) and does not cause hypoglycaemia alone.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.238 Q3, Oral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-1974e6d13e', 'pharm-oral-antidiabetic-drugs', 'mcq', 'Adverse effects of thiazolidinediones include the following EXCEPT:', '["Weight gain", "Bone fractures", "Heart failure", "Macular oedema", "Kidney failure"]'::jsonb, 'Kidney failure', '[]'::jsonb, 'Thiazolidinediones cause fluid retention, which leads to weight gain, oedema, precipitation of heart failure and macular oedema; they also reduce bone density and increase fractures. They are not nephrotoxic and can be used in renal impairment.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.239 Q4, Oral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-bfe31c5c83', 'pharm-oral-antidiabetic-drugs', 'mcq', 'Which of the following is NOT a contraindication to the use of chlorpropamide?', '["Type 2 diabetes mellitus", "Pregnancy", "Geriatric age", "Renal failure", "Lactation"]'::jsonb, 'Type 2 diabetes mellitus', '[]'::jsonb, 'Chlorpropamide is a first-generation sulphonylurea whose indication is type 2 diabetes with residual beta-cell function. It is avoided in pregnancy and lactation, and in the elderly and renal failure because its long half-life and renal excretion cause prolonged hypoglycaemia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.239 Q5, Oral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-9fe0618042', 'pharm-oral-antidiabetic-drugs', 'mcq', 'Which statement about acarbose is FALSE?', '["It slows the intestinal absorption of glucose", "It does not cause hypoglycaemia when used alone", "It causes flatulence", "It is administered 30 minutes after a meal", "It is contraindicated in severe renal impairment"]'::jsonb, 'It is administered 30 minutes after a meal', '[]'::jsonb, 'Acarbose competitively inhibits intestinal alpha-glucosidases, so it must be present when carbohydrate arrives: it is taken with the first bite of a meal, not afterwards. Undigested carbohydrate fermented in the colon causes flatulence. Alone it does not cause hypoglycaemia.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.239 Q6, Oral Antidiabetic Drugs. The paper gave only "Acarbose:" with five statements and no instruction; reworded as "which is FALSE". Needs a human check.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-9195434168', 'pharm-oral-antidiabetic-drugs', 'mcq', 'Which drug is correctly paired with its class?', '["Alpha-glucosidase inhibitor: Canagliflozin", "Biguanide: Pramlintide", "Sulphonylurea: Exenatide", "Thiazolidinedione: Pioglitazone", "Dipeptidyl peptidase-4 inhibitor: Tolazamide"]'::jsonb, 'Thiazolidinedione: Pioglitazone', '[]'::jsonb, 'Pioglitazone is a thiazolidinedione, a PPAR-gamma agonist that improves insulin sensitivity. Canagliflozin is an SGLT2 inhibitor, pramlintide an amylin analogue, exenatide a GLP-1 agonist and tolazamide a first-generation sulphonylurea. Knowing the stem of each class (-gliflozin, -glitazone, -gliptin, -glutide) makes these pairings easy.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.239 Q10, Oral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-f2794b1ddd', 'pharm-oral-antidiabetic-drugs', 'mcq', 'Which statement is TRUE of thiazolidinediones (PPAR-gamma agonists)?', '["They are used in type 1 diabetes mellitus as monotherapy", "Exenatide is an example", "They are recommended in diabetic patients with hepatic disease", "Maximal effects occur after 2 hours", "They are euglycaemic"]'::jsonb, 'They are euglycaemic', '[]'::jsonb, 'Thiazolidinediones are insulin sensitisers: they lower glucose only towards normal and do not cause hypoglycaemia alone, so they are called euglycaemic. They need insulin to work (useless alone in type 1), act through gene transcription so the full effect takes weeks, and are avoided in liver disease.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.240 Q11, Oral Antidiabetic Drugs. The paper says "True ... except", but four of the five options are false; stem changed to "which is TRUE".') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-91ef721ad7', 'pharm-oral-antidiabetic-drugs', 'mcq', 'Which drug is NOT euglycaemic (that is, it can cause hypoglycaemia when used alone)?', '["Metformin", "Acarbose", "Rosiglitazone", "Glipizide", "Miglitol"]'::jsonb, 'Glipizide', '[]'::jsonb, 'Glipizide is a sulphonylurea: it releases insulin regardless of the blood glucose level, so it can cause hypoglycaemia. Metformin, the thiazolidinediones and the alpha-glucosidase inhibitors lower raised glucose without stimulating insulin secretion and are therefore euglycaemic.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.240 Q12, Oral Antidiabetic Drugs. Stem expanded to explain "euglycaemic".') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-352f91da70', 'pharm-oral-antidiabetic-drugs', 'mcq', 'Which oral antidiabetic agent lowers glucose levels by its actions in the liver, muscle and adipose tissue?', '["Metformin", "Sitagliptin", "Voglibose", "Canagliflozin", "Repaglinide"]'::jsonb, 'Metformin', '[]'::jsonb, 'Metformin activates AMP-activated protein kinase, reducing hepatic gluconeogenesis and increasing glucose uptake and use in muscle and fat. Sitagliptin acts through incretins, voglibose in the gut lumen, canagliflozin in the renal tubule and repaglinide on the pancreatic beta cell.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.240 Q13, Oral Antidiabetic Drugs. Class names in brackets removed from the options.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-b4661560bc', 'pharm-oral-antidiabetic-drugs', 'mcq', 'Which statement regarding sulphonylurea use in diabetes mellitus is FALSE?', '["Chlorpropamide is contraindicated in the elderly", "Second-generation agents have fewer drug interactions than first-generation agents", "Chlorpropamide causes an alcohol-induced flush", "They stimulate insulin secretion", "Chlorpropamide has a half-life of 30 minutes"]'::jsonb, 'Chlorpropamide has a half-life of 30 minutes', '[]'::jsonb, 'Chlorpropamide has a half-life of about 32 hours, the longest of the sulphonylureas, which is exactly why it causes prolonged hypoglycaemia in the elderly. It also causes a disulfiram-like flush with alcohol. Second-generation agents are more potent and less protein-displacement prone.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.240 Q14, Oral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-8e7022cddc', 'pharm-oral-antidiabetic-drugs', 'mcq', 'Which antidiabetic agent is associated with genital and urinary tract infections?', '["Glyburide", "Canagliflozin", "Pioglitazone", "Exenatide", "Miglitol"]'::jsonb, 'Canagliflozin', '[]'::jsonb, 'SGLT2 inhibitors such as canagliflozin block glucose reabsorption in the proximal tubule, and the resulting glycosuria encourages genital candidiasis and urinary tract infections. None of the other classes increases urinary glucose.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.240 Q15, Oral Antidiabetic Drugs. Class names and an explanatory note removed from the options.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-9cfbe37b47', 'pharm-oral-antidiabetic-drugs', 'mcq', 'Sulphonylureas cause hypoglycaemia by:', '["Reducing glucose absorption from the intestine", "Stimulating insulin release from pancreatic beta cells", "Stimulating beta-2 adrenoceptors in pancreatic beta cells", "Blocking alpha-2 adrenoceptors in pancreatic beta cells", "Direct stimulation of anaerobic metabolism of glucose to lactate"]'::jsonb, 'Stimulating insulin release from pancreatic beta cells', '[]'::jsonb, 'Sulphonylureas bind the SUR1 subunit of the ATP-sensitive potassium channel on beta cells, closing it; depolarisation opens calcium channels and insulin is released. They do not act through adrenoceptors. Reduced absorption and increased anaerobic glycolysis are effects attributed to biguanides.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.240 Q16, Oral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-eb42400ef5', 'pharm-oral-antidiabetic-drugs', 'mcq', 'Sulphonylureas act on pancreatic beta cells by blocking:', '["Na+ channels", "N-type Ca2+ channels", "L-type Ca2+ channels", "ATP-sensitive K+ channels", "Voltage-activated K+ channels"]'::jsonb, 'ATP-sensitive K+ channels', '[]'::jsonb, 'Sulphonylureas close ATP-sensitive potassium channels, mimicking the effect of a rise in intracellular ATP. The membrane depolarises, voltage-gated L-type calcium channels open (they are not blocked), calcium enters and insulin granules are released.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.241 Q17, Oral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-9bc980fa92', 'pharm-oral-antidiabetic-drugs', 'mcq', 'Unwanted effects of sulphonylureas include all of the following EXCEPT:', '["Hypoglycaemia", "Weight gain", "Allergic skin rashes", "Lactic acidosis", "Nausea and vomiting"]'::jsonb, 'Lactic acidosis', '[]'::jsonb, 'Lactic acidosis is the rare but serious adverse effect of biguanides such as metformin, not of sulphonylureas. Sulphonylureas cause hypoglycaemia, weight gain (from increased insulin), gastrointestinal upset and hypersensitivity rashes.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.241 Q18, Oral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-c4af32dd16', 'pharm-oral-antidiabetic-drugs', 'mcq', 'The hypoglycaemic effect of sulphonylureas is augmented by all of the following EXCEPT:', '["Combined oral contraceptives", "Sulphonamides", "Salicylates", "Phenylbutazone", "Dicoumarol"]'::jsonb, 'Combined oral contraceptives', '[]'::jsonb, 'Oral contraceptives impair glucose tolerance and so oppose sulphonylureas. Sulphonamides, salicylates, phenylbutazone and dicoumarol displace sulphonylureas from plasma protein or inhibit their metabolism or excretion, increasing free drug and the risk of hypoglycaemia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.241 Q19, Oral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-d91f195e99', 'pharm-oral-antidiabetic-drugs', 'mcq', 'The hypoglycaemic effect of sulphonylureas is decreased by:', '["Propranolol", "MAO inhibitors", "Sulphonamides", "Salicylates", "Thiazides"]'::jsonb, 'Thiazides', '[]'::jsonb, 'Thiazide diuretics open ATP-sensitive potassium channels in beta cells and cause hypokalaemia, reducing insulin release and raising blood glucose, so they antagonise sulphonylureas. Propranolol is tempting, but it mainly masks the warning symptoms of hypoglycaemia and delays recovery rather than reducing the effect.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.241 Q20, Oral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-39f2e79e54', 'pharm-oral-antidiabetic-drugs', 'mcq', 'Metformin acts by all of the following mechanisms EXCEPT:', '["Reducing glucose absorption from the intestine", "Reducing hepatic gluconeogenesis", "Direct stimulation of glycolysis in peripheral tissue", "Stimulating insulin release from pancreatic beta cells", "Increasing insulin binding to insulin receptors"]'::jsonb, 'Stimulating insulin release from pancreatic beta cells', '[]'::jsonb, 'Metformin does not stimulate insulin secretion, which is why it does not cause hypoglycaemia or weight gain. Its glucose-lowering actions are extrapancreatic: less hepatic gluconeogenesis, more peripheral glucose use, slower intestinal absorption and better insulin sensitivity.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.241 Q21, Oral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-oral-antidiabetic-drugs-9f8ab3c5ea', 'pharm-oral-antidiabetic-drugs', 'mcq', 'Contraindications of biguanides include all of the following EXCEPT:', '["Renal insufficiency", "Hepatocellular failure", "Congestive heart failure", "Hypertension", "Chronic hypoxic lung disease"]'::jsonb, 'Hypertension', '[]'::jsonb, 'Biguanides are contraindicated wherever lactate production is increased or its clearance reduced, because of the risk of lactic acidosis: renal or hepatic failure, cardiac failure, and hypoxic lung disease. Hypertension alone does not predispose to lactic acidosis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.241 Q22, Oral Antidiabetic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-hematinics-iron-and-ir-e61827e007', 'pharm-introduction-to-hematinics-iron-and-iron-salts-cobalamin-vit-b12', 'mcq', 'Which of the following iron salt preparations has the highest elemental iron content?', '["Hydrated ferrous sulphate", "Desiccated ferrous sulphate", "Ferrous gluconate", "Ferrous fumarate", "Ferrous succinate"]'::jsonb, 'Ferrous fumarate', '[]'::jsonb, 'Ferrous fumarate contains about 33% elemental iron by weight, the highest of the common oral salts. Desiccated (dried) ferrous sulphate is close at about 30 to 32%, hydrated ferrous sulphate has 20% and ferrous gluconate only 12%.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.242 Q2, Introduction to hematinics, Iron, Vit B12, folic acid. Replaced the option "Iron dextran" (a parenteral complex, not a salt) with ferrous succinate.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-hematinics-iron-and-ir-783cba73d7', 'pharm-introduction-to-hematinics-iron-and-iron-salts-cobalamin-vit-b12', 'mcq', 'Which of the following statements about vitamin B12 and folic acid is INCORRECT?', '["The oral route is recommended for vitamin B12 replacement therapy", "Folic acid replacement corrects vitamin B12-related megaloblastic anaemia", "Hydroxocobalamin should be administered for life in patients with pernicious anaemia", "Hydroxocobalamin is an antidote for cyanide poisoning", "Folic acid is used to prevent neural tube defects"]'::jsonb, 'The oral route is recommended for vitamin B12 replacement therapy', '[]'::jsonb, 'Most B12 deficiency is due to malabsorption (lack of intrinsic factor or ileal disease), so replacement is given by intramuscular injection, usually for life. Folic acid does correct the anaemia of B12 deficiency, which is dangerous because the neurological damage continues to progress.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.242 Q4, Introduction to hematinics, Iron, Vit B12, folic acid. Standard textbook answer (parenteral B12), but high-dose oral B12 is now accepted in some guidelines. "B12 deficiency" in option c narrowed to pernicious anaemia.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-hematinics-iron-and-ir-a0a2ecfc4c', 'pharm-introduction-to-hematinics-iron-and-iron-salts-cobalamin-vit-b12', 'mcq', 'Which statement about iron preparations in the treatment of iron deficiency anaemia is FALSE?', '["Treatment should continue for 3-6 months", "They cause constipation", "Taking them with meals worsens the adverse effects", "Oral therapy requires about 200 mg of elemental iron daily", "Ferrous fumarate has the highest concentration of elemental iron"]'::jsonb, 'Taking them with meals worsens the adverse effects', '[]'::jsonb, 'Gastrointestinal irritation from oral iron is dose related and is reduced, not worsened, by taking the tablets with or just after food, although absorption falls. Treatment continues for 3 to 6 months after haemoglobin normalises to replenish stores.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.242 Q5, Introduction to hematinics, Iron, Vit B12, folic acid. Option d simplified from "200-300 mg" to "about 200 mg".') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-hematinics-iron-and-ir-0ab04d6d06', 'pharm-introduction-to-hematinics-iron-and-iron-salts-cobalamin-vit-b12', 'mcq', 'Which statement about vitamin B12 deficiency anaemia is FALSE?', '["It causes mental aberrations", "Treatment is for 6 months", "The tongue is red, beefy and smooth", "It is megaloblastic in type", "Long-standing sub-acute combined degeneration of the cord may be irreversible"]'::jsonb, 'Treatment is for 6 months', '[]'::jsonb, 'Because the usual cause is a permanent failure of absorption (pernicious anaemia, gastrectomy, ileal disease), vitamin B12 replacement is lifelong, not a 6-month course. The deficiency causes megaloblastic anaemia, glossitis, neuropsychiatric changes and cord degeneration that may not recover if treatment is delayed.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.242 Q6, Introduction to hematinics, Iron, Vit B12, folic acid. Option e softened ("may be irreversible" for long-standing disease) because early neurological damage can recover.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-hematinics-iron-and-ir-63c81d9c59', 'pharm-introduction-to-hematinics-iron-and-iron-salts-cobalamin-vit-b12', 'mcq', 'Adverse effects of parenteral iron include the following EXCEPT:', '["Anaphylaxis", "Arthralgia", "Bronchospasm", "Light-headedness", "Hypothermia"]'::jsonb, 'Hypothermia', '[]'::jsonb, 'Parenteral iron, especially iron dextran, causes hypersensitivity reactions including anaphylaxis and bronchospasm, plus headache, light-headedness, arthralgia, back pain, flushing and fever. Fever rather than hypothermia is the temperature change seen.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.243 Q8, Introduction to hematinics, Iron, Vit B12, folic acid') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-hematinics-iron-and-ir-2dac79d91f', 'pharm-introduction-to-hematinics-iron-and-iron-salts-cobalamin-vit-b12', 'mcq', 'All of the following are true about vitamin B12 EXCEPT:', '["Deficiency of deoxythymidylate (dTMP) occurs in vitamin B12 deficiency", "Neurological symptoms of vitamin B12 deficiency are attributed to impaired methionine synthesis", "Deficiency causes accumulation of N5-methyltetrahydrofolate", "Correction of vitamin B12 deficiency is equally reliable by oral and injectable preparations", "Megaloblastic anaemia of vitamin B12 deficiency can be partially corrected with large amounts of folic acid"]'::jsonb, 'Correction of vitamin B12 deficiency is equally reliable by oral and injectable preparations', '[]'::jsonb, 'Deficiency is nearly always due to malabsorption, so oral B12 is unreliable and parenteral therapy is standard. Without B12, folate is trapped as N5-methyltetrahydrofolate (the methylfolate trap), dTMP synthesis fails and megaloblastosis results; large doses of folic acid bypass this but do not protect the nervous system.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.243 Q9, Introduction to hematinics, Iron, Vit B12, folic acid. Katzung-based key (parenteral preferred); high-dose oral B12 is accepted by some guidelines.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-hematinics-iron-and-ir-1a5ddf0f43', 'pharm-introduction-to-hematinics-iron-and-iron-salts-cobalamin-vit-b12', 'mcq', 'Which statement about iron is TRUE?', '["Iron from meat must be reduced to elemental iron before absorption", "Normal individuals without iron deficiency absorb 5-10% of dietary iron", "Iron from plants is as well absorbed as that from meat", "Ferric (Fe3+) and ferrous (Fe2+) forms are equally absorbed", "It is absorbed equally throughout the gastrointestinal tract"]'::jsonb, 'Normal individuals without iron deficiency absorb 5-10% of dietary iron', '[]'::jsonb, 'A healthy adult absorbs only 5 to 10% of dietary iron (about 0.5 to 1 mg a day), rising in deficiency. Haem iron from meat is absorbed intact and far better than plant iron; non-haem iron must be in the ferrous form, and absorption occurs in the duodenum and proximal jejunum.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.243 Q11, Introduction to hematinics, Iron, Vit B12, folic acid. Options c and e were garbled in the source and were reconstructed.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-hematinics-iron-and-ir-93592073ab', 'pharm-introduction-to-hematinics-iron-and-iron-salts-cobalamin-vit-b12', 'mcq', 'Oral iron preparations include all of the following EXCEPT:', '["Ferrous sulphate", "Ferrous gluconate", "Ferrous fumarate", "Ferrous succinate", "Iron dextran"]'::jsonb, 'Iron dextran', '[]'::jsonb, 'Iron dextran is a complex of ferric hydroxide and dextran given by deep intramuscular injection or intravenous infusion, for patients who cannot tolerate or absorb oral iron. The ferrous salts listed are all oral preparations.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.243 Q12, Introduction to hematinics, Iron, Vit B12, folic acid') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-hematinics-iron-and-ir-0d9fb7bfba', 'pharm-introduction-to-hematinics-iron-and-iron-salts-cobalamin-vit-b12', 'mcq', 'Absorption of iron is increased by:', '["Tetracyclines", "Ascorbic acid (vitamin C)", "Phosphates", "Phytates", "Tannic acid (strong tea)"]'::jsonb, 'Ascorbic acid (vitamin C)', '[]'::jsonb, 'Ascorbic acid reduces ferric iron to the absorbable ferrous form and keeps it soluble, enhancing absorption. Tetracyclines, phosphates, phytates and tannins all bind iron in the gut lumen into insoluble complexes and reduce absorption.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.244 Q13, Introduction to hematinics, Iron, Vit B12, folic acid') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-hematinics-iron-and-ir-1aaa74e7a9', 'pharm-introduction-to-hematinics-iron-and-iron-salts-cobalamin-vit-b12', 'mcq', 'Which of the following may produce megaloblastic anaemia?', '["Aspirin", "Ethosuximide", "Verapamil", "Phenytoin", "Propranolol"]'::jsonb, 'Phenytoin', '[]'::jsonb, 'Phenytoin interferes with folate absorption and metabolism, and long-term use can cause folate-deficiency megaloblastic anaemia. Other causes include methotrexate, trimethoprim, pyrimethamine and phenobarbital. Aspirin can cause iron-deficiency anaemia from occult gastrointestinal bleeding, which is microcytic, not megaloblastic.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.244 Q14, Introduction to hematinics, Iron, Vit B12, folic acid. Replaced the distractor "Valproic acid" (which can also lower folate) with propranolol so that only one answer is defensible.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-hematinics-iron-and-ir-6c68797a29', 'pharm-introduction-to-hematinics-iron-and-iron-salts-cobalamin-vit-b12', 'mcq', 'Pernicious anaemia is treated by intramuscular injection of:', '["Iron dextran", "Riboflavin", "Pyridoxine", "Cyanocobalamin", "Granulocyte-macrophage colony-stimulating factor (GM-CSF)"]'::jsonb, 'Cyanocobalamin', '[]'::jsonb, 'Pernicious anaemia is vitamin B12 deficiency caused by lack of intrinsic factor, so oral B12 is not absorbed. Lifelong intramuscular cyanocobalamin or hydroxocobalamin bypasses the defect. Iron and the other vitamins do not correct the megaloblastic change.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.244 Q15, Introduction to hematinics, Iron, Vit B12, folic acid') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-erythropoietin-myeloid-growth-factors--4a87117b28', 'pharm-erythropoietin-myeloid-growth-factors-megakaryocyte-growth-facto', 'mcq', 'Which statement regarding erythropoietin is INCORRECT?', '["Epoetin alfa is not cleared by haemodialysis", "It is useful in the treatment of pure red cell aplasia", "It can cause hypertension", "It increases the level of haemoglobin after 2 to 4 weeks", "The response is reduced in patients with iron deficiency"]'::jsonb, 'It is useful in the treatment of pure red cell aplasia', '[]'::jsonb, 'Pure red cell aplasia is a rare complication of epoetin therapy, caused by neutralising antibodies against erythropoietin; it is not an indication. Epoetin raises haemoglobin over 2 to 6 weeks provided iron stores are adequate, and commonly causes hypertension and thrombosis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.244 Q1, Erythropoietin, Myeloid and Megakaryocyte Growth Factors') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-erythropoietin-myeloid-growth-factors--6eed02ab8f', 'pharm-erythropoietin-myeloid-growth-factors-megakaryocyte-growth-facto', 'mcq', 'All of the following are useful in the management of a patient with a low platelet count EXCEPT:', '["Romiplostim", "Eltrombopag", "Oprelvekin", "Avatrombopag", "Lenograstim"]'::jsonb, 'Lenograstim', '[]'::jsonb, 'Lenograstim is a recombinant G-CSF that stimulates neutrophil production and has no effect on platelets. Romiplostim, eltrombopag and avatrombopag are thrombopoietin receptor agonists, and oprelvekin (interleukin-11) stimulates megakaryocytes. Platelet transfusion remains the treatment for acute severe thrombocytopenic bleeding.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.244 Q2, Erythropoietin, Myeloid and Megakaryocyte Growth Factors. The paper omitted "except"; added, since four of the five options raise the platelet count.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-erythropoietin-myeloid-growth-factors--b70b859b6a', 'pharm-erythropoietin-myeloid-growth-factors-megakaryocyte-growth-facto', 'mcq', 'Which of the following is NOT an effect of erythropoietin?', '["Vasoconstriction", "Increased iron absorption", "Angiogenesis", "Proliferation of smooth muscle fibres", "Dementia"]'::jsonb, 'Dementia', '[]'::jsonb, 'Besides stimulating erythroid progenitors, erythropoietin has non-haematopoietic actions: it is a vasoconstrictor (contributing to hypertension), promotes angiogenesis and smooth muscle proliferation, and by driving erythropoiesis increases iron absorption. It is neuroprotective in experimental models rather than a cause of dementia.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.244 Q3, Erythropoietin, Myeloid and Megakaryocyte Growth Factors. Odd question ("False regarding erythropoietin") reworded; the non-haematopoietic effects are not standard textbook material.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-erythropoietin-myeloid-growth-factors--5883d7e858', 'pharm-erythropoietin-myeloid-growth-factors-megakaryocyte-growth-facto', 'mcq', 'Which of the following is indicated for febrile neutropenia?', '["Leucovorin", "Darbepoetin", "Thrombopoietin", "Epoetin alfa", "Filgrastim"]'::jsonb, 'Filgrastim', '[]'::jsonb, 'Filgrastim is recombinant G-CSF; it stimulates proliferation and maturation of neutrophil precursors and shortens chemotherapy-induced neutropenia. Darbepoetin and epoetin act on red cell precursors, thrombopoietin on platelets, and leucovorin rescues cells from methotrexate.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.245 Q4, Erythropoietin, Myeloid and Megakaryocyte Growth Factors') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-erythropoietin-myeloid-growth-factors--8cf5c18320', 'pharm-erythropoietin-myeloid-growth-factors-megakaryocyte-growth-facto', 'mcq', 'Anaemia associated with chronic renal failure is treated by:', '["Pyridoxine", "Colony-stimulating factors (CSFs)", "Erythropoietin", "Vitamin C", "Vitamin B12"]'::jsonb, 'Erythropoietin', '[]'::jsonb, 'The anaemia of chronic renal failure is due mainly to loss of erythropoietin production by the diseased kidney, so recombinant erythropoietin (epoetin, darbepoetin) is the specific treatment, with iron supplementation. Colony-stimulating factors act on white cell lines.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.245 Q5, Erythropoietin, Myeloid and Megakaryocyte Growth Factors') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiplatelet-drugs-76b2701cef', 'pharm-antiplatelet-drugs', 'mcq', 'Which of the following antiplatelet agents acts by blocking the platelet ADP (P2Y12) receptor?', '["Abciximab", "Eptifibatide", "Tirofiban", "Clopidogrel", "Dipyridamole"]'::jsonb, 'Clopidogrel', '[]'::jsonb, 'Clopidogrel is a thienopyridine prodrug whose active metabolite irreversibly blocks the P2Y12 ADP receptor. Abciximab, eptifibatide and tirofiban block glycoprotein IIb/IIIa; dipyridamole inhibits phosphodiesterase and adenosine uptake. Prasugrel and ticagrelor act on the same receptor.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.245 Q1, Antiplatelet Drugs. Stem clarified ("inhibiting ADP" → blocking the ADP receptor).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiplatelet-drugs-4c7ddfdcd4', 'pharm-antiplatelet-drugs', 'mcq', 'All of the following are true for clopidogrel EXCEPT:', '["It prevents recurrent transient ischaemic attacks (TIA)", "It is indicated in completed strokes", "It should not be used with aspirin", "It may cause neutropenia", "Its antiplatelet effect lasts 7-10 days"]'::jsonb, 'It should not be used with aspirin', '[]'::jsonb, 'Clopidogrel is commonly combined with aspirin as dual antiplatelet therapy after acute coronary syndromes and stenting. Its P2Y12 blockade is irreversible, so the effect lasts the 7 to 10 day lifespan of the platelet; neutropenia is rare and much less frequent than with ticlopidine.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.245 Q2, Antiplatelet Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiplatelet-drugs-5928536b06', 'pharm-antiplatelet-drugs', 'mcq', 'All of the following inhibit platelet aggregation EXCEPT:', '["Aspirin", "Dipyridamole", "Prostacyclin", "Thromboxane A2", "Heparan sulphate"]'::jsonb, 'Thromboxane A2', '[]'::jsonb, 'Thromboxane A2, made by platelet COX-1, is a powerful promoter of platelet aggregation and a vasoconstrictor. Prostacyclin from endothelium opposes it by raising platelet cyclic AMP; aspirin blocks thromboxane synthesis and dipyridamole raises cyclic AMP.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.245 Q3, Antiplatelet Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiplatelet-drugs-7f7171a45f', 'pharm-antiplatelet-drugs', 'mcq', 'Which statement is TRUE?', '["Dipyridamole should never be combined with warfarin or aspirin", "Higher doses of aspirin do not proportionately improve its antiplatelet efficacy", "Clopidogrel exerts its antiplatelet effect via inhibition of cyclooxygenase", "The antiplatelet effect of aspirin is potentiated by aminocaproic acid", "Thromboxane A2 is a vasodilator that inhibits platelet aggregation"]'::jsonb, 'Higher doses of aspirin do not proportionately improve its antiplatelet efficacy', '[]'::jsonb, 'Low-dose aspirin (75 to 150 mg) already irreversibly acetylates platelet COX-1 almost completely; higher doses add toxicity and also inhibit endothelial prostacyclin, without more benefit. Dipyridamole is used with aspirin or warfarin, clopidogrel blocks P2Y12, and thromboxane A2 is a pro-aggregatory vasoconstrictor.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.246 Q5, Antiplatelet Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiplatelet-drugs-2de63ccb43', 'pharm-antiplatelet-drugs', 'mcq', 'All of the following are antiplatelet drugs EXCEPT:', '["Aspirin", "Dipyridamole", "Ticlopidine", "Streptokinase", "Sulphinpyrazone"]'::jsonb, 'Streptokinase', '[]'::jsonb, 'Streptokinase is a fibrinolytic: it activates plasminogen to plasmin, which dissolves existing fibrin clot. The others reduce platelet aggregation: aspirin and sulphinpyrazone via cyclooxygenase, ticlopidine via the P2Y12 receptor and dipyridamole via phosphodiesterase inhibition.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.246 Q7, Antiplatelet Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-d984f43313', 'pharm-anticoagulant-drugs', 'mcq', 'All of the following are correct regarding low molecular weight heparin EXCEPT:', '["It inhibits factor Xa", "It is fractionated", "Enoxaparin is an example", "It requires frequent aPTT monitoring", "It has predictable kinetics"]'::jsonb, 'It requires frequent aPTT monitoring', '[]'::jsonb, 'Low molecular weight heparins have high subcutaneous bioavailability and predictable, weight-based kinetics, so routine monitoring is unnecessary; they hardly prolong the aPTT. When monitoring is needed (renal failure, pregnancy, obesity) anti-factor Xa activity is measured.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.246 Q1, Anticoagulant Drugs. Same question repeated as Q12 on p.248; one copy kept.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-12ecd1a77b', 'pharm-anticoagulant-drugs', 'mcq', 'Which statement concerning warfarin is FALSE?', '["It crosses the placenta", "It is teratogenic in the first trimester and safe in the third trimester", "It has a narrow therapeutic index", "It is monitored using the INR", "Its effect is potentiated by cimetidine"]'::jsonb, 'It is teratogenic in the first trimester and safe in the third trimester', '[]'::jsonb, 'Warfarin is unsafe throughout pregnancy: in the first trimester it causes the fetal warfarin syndrome (nasal hypoplasia, stippled epiphyses), and later it causes fetal and neonatal haemorrhage, including intracranial bleeding at delivery. Heparin, which does not cross the placenta, is used instead.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.247 Q3, Anticoagulant Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-6759d559a8', 'pharm-anticoagulant-drugs', 'mcq', 'Which statement regarding heparin is TRUE?', '["Low molecular weight heparin is unfractionated", "The international normalised ratio is the index for monitoring heparin activity", "Low molecular weight heparin requires less monitoring", "Enoxaparin has a high molecular weight", "Heparin acts by inhibiting antithrombin III"]'::jsonb, 'Low molecular weight heparin requires less monitoring', '[]'::jsonb, 'Low molecular weight heparins such as enoxaparin have predictable dose-response, so routine laboratory monitoring is not needed. Unfractionated heparin is monitored by aPTT (INR is for warfarin), and heparin works by activating, not inhibiting, antithrombin III.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.247 Q4, Anticoagulant Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-agonists-and-antagonists-7e1e072cef', 'pharm-drug-agonists-and-antagonists', 'mcq', 'The binding of heparin to protamine is an example of:', '["Competitive antagonism", "Allosteric modulation", "Partial agonism", "Chemical antagonism", "Functional antagonism"]'::jsonb, 'Chemical antagonism', '[]'::jsonb, 'Protamine is a strongly basic protein that binds the strongly acidic heparin molecule in solution, forming an inactive complex. No receptor is involved, so this is chemical antagonism. Functional (physiological) antagonism would need two drugs acting on different receptors with opposite effects.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.247 Q5, Anticoagulant Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-24912677a1', 'pharm-anticoagulant-drugs', 'mcq', 'Which of the following is NOT a direct thrombin inhibitor?', '["Argatroban", "Lepirudin", "Ximelagatran", "Bivalirudin", "Enoxaparin"]'::jsonb, 'Enoxaparin', '[]'::jsonb, 'Enoxaparin is a low molecular weight heparin: it acts indirectly, by enhancing antithrombin III, and mainly inhibits factor Xa. Argatroban, lepirudin, bivalirudin and ximelagatran bind thrombin directly without needing antithrombin.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.247 Q6, Anticoagulant Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-67ee0be1fd', 'pharm-anticoagulant-drugs', 'mcq', 'Which statement regarding warfarin is FALSE?', '["It inhibits vitamin K epoxide reductase", "It is monitored using the aPTT", "Fetal warfarin syndrome presents with hypoplasia of the nose", "Vitamin K is useful for the management of warfarin-associated bleeding", "Rifampicin induces the metabolism of warfarin"]'::jsonb, 'It is monitored using the aPTT', '[]'::jsonb, 'Warfarin is monitored with the prothrombin time, expressed as the INR, because it most rapidly depresses factor VII of the extrinsic pathway. The aPTT is used for unfractionated heparin. The other statements are all true.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.247 Q7, Anticoagulant Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-5fcb70c356', 'pharm-anticoagulant-drugs', 'mcq', 'Which of the following is NOT an adverse effect of heparin?', '["Allergy", "Thrombocytopenia", "Hyperlipidaemia", "Loss of hair", "Osteoporosis"]'::jsonb, 'Hyperlipidaemia', '[]'::jsonb, 'Heparin releases lipoprotein lipase from endothelium, which clears triglyceride-rich lipoproteins from plasma, so it lowers rather than raises plasma lipids. Its adverse effects are bleeding, thrombocytopenia, hypersensitivity, reversible alopecia, osteoporosis with long use and hypoaldosteronism.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.248 Q9, Anticoagulant Drugs. Near-identical question on p.246 Q2 (with "mineralocorticoid deficiency" as a distractor); one copy kept.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-d8a484d8df', 'pharm-anticoagulant-drugs', 'mcq', 'In which of the following conditions is monitoring of the enoxaparin dose (anti-Xa level) most important?', '["Hypertension", "Recurrent deep venous thrombosis", "Renal insufficiency", "Pulmonary embolism", "Acute myocardial infarction"]'::jsonb, 'Renal insufficiency', '[]'::jsonb, 'Enoxaparin is eliminated by the kidneys, so it accumulates in renal insufficiency and may cause bleeding; anti-Xa monitoring or dose reduction is needed. Monitoring is also considered in pregnancy and extremes of body weight, but not simply because of the indication being treated.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.248 Q10, Anticoagulant Drugs. Replaced the distractor "Wasted patient" (very low body weight is also a recognised reason to monitor) with hypertension.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-ec54dc51ba', 'pharm-anticoagulant-drugs', 'mcq', 'Which statement regarding warfarin is TRUE?', '["It is poorly bound to plasma protein", "It has a small volume of distribution", "It does not cross the placenta", "It is preferred over heparin during labour", "It has a wide therapeutic index"]'::jsonb, 'It has a small volume of distribution', '[]'::jsonb, 'Because warfarin is about 99% albumin bound, it stays mostly in the vascular compartment and its volume of distribution is small. It crosses the placenta, is avoided in pregnancy and labour (heparin is used), and has a narrow therapeutic index requiring INR monitoring.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.248 Q11, Anticoagulant Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-89fbd5c3ed', 'pharm-anticoagulant-drugs', 'mcq', 'All of the following are true of apixaban EXCEPT:', '["It is indicated for prevention of stroke in non-valvular atrial fibrillation", "It inhibits factor Xa, in the final common pathway of clotting", "It has a rapid onset of action", "It has a longer half-life than warfarin", "It may require dosage adjustment in renal failure"]'::jsonb, 'It has a longer half-life than warfarin', '[]'::jsonb, 'Apixaban has a half-life of about 12 hours and is given twice daily, whereas warfarin''s half-life is around 40 hours. The direct factor Xa inhibitors act within hours, need no routine monitoring and are used for stroke prevention in non-valvular atrial fibrillation.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.248 Q13, Anticoagulant Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-794b510ab5', 'pharm-anticoagulant-drugs', 'mcq', 'Which of the following is NOT an oral anticoagulant?', '["Apixaban", "Argatroban", "Edoxaban", "Warfarin", "Rivaroxaban"]'::jsonb, 'Argatroban', '[]'::jsonb, 'Argatroban is a direct thrombin inhibitor given only by intravenous infusion, mainly for heparin-induced thrombocytopenia. Apixaban, edoxaban and rivaroxaban are oral factor Xa inhibitors, and warfarin is the oral vitamin K antagonist.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.248 Q14, Anticoagulant Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-4251266bcf', 'pharm-anticoagulant-drugs', 'mcq', 'Correct statements about heparin include all of the following EXCEPT that:', '["It is a mucopolysaccharide", "It prolongs the clotting time of blood both in vivo and in vitro", "It is not absorbed from the GIT", "It is given intramuscularly", "It is a direct-acting anticoagulant"]'::jsonb, 'It is given intramuscularly', '[]'::jsonb, 'Heparin is never given intramuscularly because it causes painful haematomas at the injection site; it is given intravenously or subcutaneously. It is a large, highly charged mucopolysaccharide, hence not absorbed orally, and works at once in vivo and in the test tube.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.248 Q15, Anticoagulant Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-6c4b70cdd4', 'pharm-anticoagulant-drugs', 'mcq', 'The mechanism of the anticoagulant effect of heparin involves:', '["Interference with vitamin K-dependent synthesis of factors II, VII, IX and X", "Increased activity of antithrombin III", "Reduced level of circulating fibrinogen without altering levels of other clotting factors", "Reduced level of ionisable calcium in blood", "None of the above"]'::jsonb, 'Increased activity of antithrombin III', '[]'::jsonb, 'Heparin binds antithrombin III and accelerates about a thousand-fold its inactivation of thrombin and factor Xa (and IXa, XIa, XIIa). Interference with vitamin K-dependent factor synthesis is the mechanism of warfarin; calcium chelation is how citrate works in vitro.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.249 Q16, Anticoagulant Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-14149368ff', 'pharm-anticoagulant-drugs', 'mcq', 'Adverse effects of heparin include all of the following EXCEPT:', '["Haemorrhage", "Fetal malformations", "Thrombocytopenia", "Alopecia", "Osteoporosis"]'::jsonb, 'Fetal malformations', '[]'::jsonb, 'Heparin is a large, charged molecule that does not cross the placenta, so it is not teratogenic and is the anticoagulant of choice in pregnancy. Warfarin is the teratogenic one. Heparin does cause bleeding, thrombocytopenia, alopecia and osteoporosis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.249 Q17, Anticoagulant Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-3fdf9109b4', 'pharm-anticoagulant-drugs', 'mcq', 'Heparin is contraindicated in all of the following situations EXCEPT:', '["Disseminated intravascular coagulopathy", "Bacterial endocarditis", "Ulcerative lesions of the GIT", "Active tuberculosis", "After brain or eye surgery"]'::jsonb, 'Disseminated intravascular coagulopathy', '[]'::jsonb, 'Heparin is avoided where bleeding would be likely or catastrophic: active peptic ulceration, infective endocarditis, active tuberculosis, and recent surgery on the brain, spinal cord or eye. In disseminated intravascular coagulation it has been used to interrupt consumption of clotting factors.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.249 Q18, Anticoagulant Drugs. Old-textbook list of contraindications; the use of heparin in DIC is itself controversial.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-eefdbf3a10', 'pharm-anticoagulant-drugs', 'mcq', 'Heparin therapy is monitored by:', '["Sedimentation rate", "Level of alpha-2-antiplasmin", "Activated partial thromboplastin time (aPTT)", "Prothrombin time", "Plasma fibrinogen concentration"]'::jsonb, 'Activated partial thromboplastin time (aPTT)', '[]'::jsonb, 'Unfractionated heparin inhibits factors of the intrinsic and common pathways, which is reflected by the aPTT; the dose is adjusted to keep it at 1.5 to 2.5 times control. The prothrombin time (INR) reflects the extrinsic pathway and is used for warfarin.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.249 Q19, Anticoagulant Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-e0b2910c86', 'pharm-anticoagulant-drugs', 'mcq', 'Which of the following drugs reverses the anticoagulant action of heparin?', '["Dimercaprol", "Penicillamine", "Protamine sulphate", "Phytonadione", "Pyridoxine"]'::jsonb, 'Protamine sulphate', '[]'::jsonb, 'Protamine sulphate is a basic protein that combines ionically with acidic heparin to form a stable, inactive complex (1 mg neutralises about 100 units). Phytonadione (vitamin K1) reverses warfarin, not heparin.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.249 Q20, Anticoagulant Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-7c97073d67', 'pharm-anticoagulant-drugs', 'mcq', 'Warfarin prevents synthesis of the following coagulation factors EXCEPT:', '["II", "V", "VII", "IX", "X"]'::jsonb, 'V', '[]'::jsonb, 'Warfarin inhibits vitamin K epoxide reductase, preventing gamma-carboxylation of the vitamin K-dependent factors II, VII, IX and X (and proteins C and S). Factor V is not vitamin K dependent.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.249 Q21, Anticoagulant Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-727223eb76', 'pharm-anticoagulant-drugs', 'mcq', 'Correct statements about the pharmacokinetics of warfarin include all of the following EXCEPT that:', '["It is readily absorbed from the GIT", "It is 99% bound to plasma albumin", "It is transformed into inactive metabolites by the liver", "It does not cross the placenta", "Cholestyramine inhibits its oral absorption"]'::jsonb, 'It does not cross the placenta', '[]'::jsonb, 'Warfarin crosses the placenta readily and causes fetal warfarin syndrome and fetal bleeding. It is completely absorbed orally (unless bound by cholestyramine), is 99% albumin bound and is inactivated by hepatic CYP2C9.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.250 Q22, Anticoagulant Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-99ce5201e5', 'pharm-anticoagulant-drugs', 'mcq', 'Metabolism of warfarin is inhibited by:', '["Griseofulvin", "Rifampicin", "Phenobarbitone", "Clonazepam", "Cimetidine"]'::jsonb, 'Cimetidine', '[]'::jsonb, 'Cimetidine inhibits hepatic cytochrome P450 enzymes, slowing warfarin clearance and raising the INR. Griseofulvin, rifampicin and phenobarbitone are enzyme inducers that speed warfarin metabolism and reduce its effect. Other important inhibitors are amiodarone, metronidazole, co-trimoxazole and fluconazole.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.250 Q23, Anticoagulant Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-39df3c59d0', 'pharm-anticoagulant-drugs', 'mcq', 'The anticoagulant effect of warfarin is increased by all of the following drugs EXCEPT:', '["Aspirin", "Amiodarone", "Rifampicin", "Phenylbutazone", "Sulphinpyrazone"]'::jsonb, 'Rifampicin', '[]'::jsonb, 'Rifampicin is a potent inducer of CYP enzymes, so it accelerates warfarin metabolism and reduces the anticoagulant effect. Amiodarone, phenylbutazone and sulphinpyrazone inhibit warfarin metabolism (and displace it from albumin), and aspirin adds an antiplatelet effect.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.250 Q24, Anticoagulant Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-c92377d7b8', 'pharm-anticoagulant-drugs', 'mcq', 'Oral anticoagulant (warfarin) therapy is monitored by:', '["Bleeding time", "Prothrombin time (PT/INR)", "Partial thromboplastin time", "Plasma fibrinogen concentration", "Platelet count"]'::jsonb, 'Prothrombin time (PT/INR)', '[]'::jsonb, 'Warfarin depletes the vitamin K-dependent factors, of which factor VII (extrinsic pathway) has the shortest half-life, so the prothrombin time is the most sensitive test. It is standardised as the INR, usually kept at 2 to 3.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.250 Q25, Anticoagulant Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticoagulant-drugs-389265ae33', 'pharm-anticoagulant-drugs', 'mcq', 'Excessive anticoagulant effect and bleeding from warfarin can be reversed by:', '["Pyridoxine", "Cyanocobalamin", "Ascorbic acid", "Phytomenadione (vitamin K1)", "Protamine sulphate"]'::jsonb, 'Phytomenadione (vitamin K1)', '[]'::jsonb, 'Vitamin K1 overcomes the block in vitamin K recycling and allows synthesis of functional clotting factors, though this takes several hours; fresh frozen plasma or prothrombin complex gives immediate reversal. Protamine neutralises heparin, not warfarin.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.250 Q26, Anticoagulant Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thrombolytic-drugs-antifibrinolytic-dr-cd9ecd01c3', 'pharm-thrombolytic-drugs-antifibrinolytic-drugs', 'mcq', 'Which of the following is the most allergenic thrombolytic agent, which can generally only be used once?', '["Urokinase", "Streptokinase", "Reteplase", "Tissue plasminogen activator", "Aminocaproic acid"]'::jsonb, 'Streptokinase', '[]'::jsonb, 'Streptokinase is a bacterial protein from streptococci, so it is antigenic: it causes allergic reactions and induces neutralising antibodies that make a repeat dose ineffective and risky. Urokinase and tissue plasminogen activator are human proteins and are not antigenic.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.250 Q1, Thrombolytic Drugs, Antifibrinolytic Drugs. Replaced the distractor "Anistreplase" (a streptokinase complex that is equally antigenic) with reteplase.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thrombolytic-drugs-antifibrinolytic-dr-1c3aa41682', 'pharm-thrombolytic-drugs-antifibrinolytic-drugs', 'mcq', 'Contraindications to thrombolytic therapy include the following EXCEPT:', '["Surgery in the last 10 days", "Aortic stenosis", "Acute pericarditis", "Haemorrhagic cerebrovascular accident", "Uncontrolled hypertension"]'::jsonb, 'Aortic stenosis', '[]'::jsonb, 'Thrombolytics are contraindicated where bleeding risk is high: recent surgery or trauma, previous haemorrhagic stroke, uncontrolled hypertension, pericarditis (risk of haemopericardium) and aortic dissection. Aortic stenosis is not a bleeding risk; it is aortic dissection that must be excluded.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.251 Q2, Thrombolytic Drugs, Antifibrinolytic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thrombolytic-drugs-antifibrinolytic-dr-462fb7e524', 'pharm-thrombolytic-drugs-antifibrinolytic-drugs', 'mcq', 'Which of the following is NOT an adverse effect of aminocaproic acid?', '["Seizures", "Hypertension", "Intravascular thrombosis", "Myopathy", "Abdominal discomfort"]'::jsonb, 'Hypertension', '[]'::jsonb, 'Aminocaproic acid causes hypotension (especially with rapid intravenous injection), not hypertension. Its other adverse effects are intravascular thrombosis from inhibited fibrinolysis, myopathy and muscle necrosis, abdominal discomfort, diarrhoea and nasal stuffiness; seizures are reported rarely.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.251 Q3, Thrombolytic Drugs, Antifibrinolytic Drugs. Option b was printed as "Hypertension Hypotension"; taken as hypertension.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thrombolytic-drugs-antifibrinolytic-dr-37961192bf', 'pharm-thrombolytic-drugs-antifibrinolytic-drugs', 'mcq', 'Which of the following is NOT a true statement regarding epsilon-aminocaproic acid?', '["It is not used orally", "Hypotension may occur following intravenous administration", "Tranexamic acid is an analogue", "It is a fibrinolysis inhibitor", "It may cause intravascular thrombosis"]'::jsonb, 'It is not used orally', '[]'::jsonb, 'Aminocaproic acid is rapidly and well absorbed by mouth and is given orally as well as intravenously. It is a lysine analogue that blocks plasminogen binding to fibrin; tranexamic acid is a more potent analogue. Thrombosis and hypotension are recognised adverse effects.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.251 Q4, Thrombolytic Drugs, Antifibrinolytic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thrombolytic-drugs-antifibrinolytic-dr-b93267efe3', 'pharm-thrombolytic-drugs-antifibrinolytic-drugs', 'mcq', 'Which statement regarding streptokinase is TRUE?', '["It forms a covalent complex with plasminogen", "It causes fewer hypersensitivity reactions than tissue plasminogen activator", "It has intrinsic enzymatic activity", "It does not require a loading dose", "It is produced by beta-haemolytic streptococci"]'::jsonb, 'It is produced by beta-haemolytic streptococci', '[]'::jsonb, 'Streptokinase is a protein made by beta-haemolytic streptococci. It has no enzymatic activity of its own: it forms a non-covalent 1:1 complex with plasminogen that then converts other plasminogen molecules to plasmin. Being foreign, it is antigenic, and a loading dose is needed to overcome antistreptococcal antibodies.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.251 Q5, Thrombolytic Drugs, Antifibrinolytic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thrombolytic-drugs-antifibrinolytic-dr-1647c0f3e3', 'pharm-thrombolytic-drugs-antifibrinolytic-drugs', 'mcq', 'Choose the INCORRECT indication for epsilon-aminocaproic acid (EACA):', '["Haemophilia", "Prophylaxis for rebleeding from intracranial aneurysms", "Postsurgical gastrointestinal bleeding", "Myocardial infarction", "Bladder haemorrhage secondary to radiation-induced cystitis"]'::jsonb, 'Myocardial infarction', '[]'::jsonb, 'Aminocaproic acid inhibits fibrinolysis and so stabilises clots; it is used to reduce bleeding. In myocardial infarction the aim is the opposite, to dissolve coronary thrombus with a fibrinolytic, and an antifibrinolytic would promote thrombosis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.251 Q6, Thrombolytic Drugs, Antifibrinolytic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thrombolytic-drugs-antifibrinolytic-dr-c075683f80', 'pharm-thrombolytic-drugs-antifibrinolytic-drugs', 'mcq', 'Which of the following is a thrombolytic agent?', '["Warfarin", "Clopidogrel", "Aminocaproic acid", "Streptokinase", "Enoxaparin"]'::jsonb, 'Streptokinase', '[]'::jsonb, 'Streptokinase activates plasminogen to plasmin, which lyses fibrin in an established thrombus. Warfarin and enoxaparin are anticoagulants and clopidogrel an antiplatelet: they prevent clot extension but do not dissolve clot. Aminocaproic acid does the opposite, inhibiting fibrinolysis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.251 Q7, Thrombolytic Drugs, Antifibrinolytic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thrombolytic-drugs-antifibrinolytic-dr-f769286504', 'pharm-thrombolytic-drugs-antifibrinolytic-drugs', 'mcq', 'The following are contraindications to thrombolytic therapy EXCEPT:', '["Dissecting aortic aneurysm", "Acute pericarditis", "Acute myocardial infarction", "Cerebrovascular accident", "Severe hypertension"]'::jsonb, 'Acute myocardial infarction', '[]'::jsonb, 'Acute ST-elevation myocardial infarction is the main indication for thrombolysis when primary angioplasty is unavailable. Aortic dissection, pericarditis, recent or haemorrhagic stroke and severe uncontrolled hypertension are contraindications because of the risk of fatal bleeding.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.252 Q8, Thrombolytic Drugs, Antifibrinolytic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thrombolytic-drugs-antifibrinolytic-dr-2c7f52d77b', 'pharm-thrombolytic-drugs-antifibrinolytic-drugs', 'mcq', 'Which of the following is a thrombolytic (fibrinolytic) agent?', '["Aminocaproic acid", "Tranexamic acid", "Tissue plasminogen activator (t-PA)", "Ticlopidine", "Enoxaparin"]'::jsonb, 'Tissue plasminogen activator (t-PA)', '[]'::jsonb, 'Tissue plasminogen activator (alteplase) preferentially activates plasminogen bound to fibrin, generating plasmin that dissolves the clot. Aminocaproic acid and tranexamic acid are antifibrinolytics with the opposite action. Ticlopidine is an antiplatelet drug and enoxaparin an anticoagulant; neither dissolves an existing clot.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.252 Q9, Thrombolytic Drugs, Antifibrinolytic Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-vitamin-k-plasma-fractions-serine-prot-948bcd46f5', 'pharm-vitamin-k-plasma-fractions-serine-protease-inhibitors-blood-prod', 'mcq', 'Cryoprecipitate contains the following EXCEPT:', '["Fibrinogen", "Von Willebrand factor", "Factor XIII", "Factor VII", "Factor VIII"]'::jsonb, 'Factor VII', '[]'::jsonb, 'Cryoprecipitate is the cold-insoluble fraction of plasma and is rich in fibrinogen, factor VIII, von Willebrand factor, factor XIII and fibronectin. Factor VII and the other vitamin K-dependent factors remain in the supernatant plasma.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.252 Q1, Vitamin K, Plasma fractions, Blood products') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-vitamin-k-plasma-fractions-serine-prot-8389abcf5d', 'pharm-vitamin-k-plasma-fractions-serine-protease-inhibitors-blood-prod', 'mcq', 'Which of the following is NOT a clinical indication for cryoprecipitate?', '["Haemophilia A", "Hypofibrinogenaemia", "Von Willebrand disease", "Disseminated intravascular coagulopathy", "Haemophilia B"]'::jsonb, 'Haemophilia B', '[]'::jsonb, 'Haemophilia B is factor IX deficiency, and cryoprecipitate contains no factor IX; it needs factor IX concentrate or plasma. Cryoprecipitate supplies fibrinogen, factor VIII and von Willebrand factor, so it can be used for hypofibrinogenaemia, DIC, and (when concentrates are unavailable) haemophilia A and von Willebrand disease.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.252 Q2, Vitamin K, Plasma fractions, Blood products. Replaced the distractor "Qualitative platelet defects" (cryoprecipitate has been used in uraemic platelet dysfunction, so it was arguable) with hypofibrinogenaemia.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-vitamin-k-plasma-fractions-serine-prot-ec7b175c8c', 'pharm-vitamin-k-plasma-fractions-serine-protease-inhibitors-blood-prod', 'mcq', 'Which statement about vitamin K is FALSE?', '["It is indicated in excessive warfarin anticoagulation", "It is well absorbed after subcutaneous injection", "It is synthesised by bacteria that colonise the human intestine", "It is a fat-soluble vitamin", "Treatment may be monitored using the international normalised ratio (INR)"]'::jsonb, 'It is well absorbed after subcutaneous injection', '[]'::jsonb, 'Absorption of vitamin K1 after subcutaneous injection is erratic and unreliable, so the oral or slow intravenous routes are preferred. It is fat soluble (needing bile salts for oral absorption), vitamin K2 is made by gut bacteria, and its effect is followed with the INR.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.252 Q3, Vitamin K, Plasma fractions, Blood products. Depends on Katzung''s statement that subcutaneous bioavailability is erratic; needs a human check.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pyridoxine-pantothenic-acid-ascorbic-a-7828ea2552', 'pharm-pyridoxine-pantothenic-acid-ascorbic-acid-biotin-inositol-carnit', 'mcq', 'All of the following can cause pyridoxine deficiency EXCEPT:', '["Infant formulas", "Penicillamine", "Cycloserine", "Isoniazid", "Rifampicin"]'::jsonb, 'Rifampicin', '[]'::jsonb, 'Isoniazid, cycloserine and penicillamine react with pyridoxal phosphate or inhibit its formation and so cause pyridoxine deficiency (peripheral neuropathy, seizures). Infants fed over-heated formula low in pyridoxine have developed deficiency seizures. Rifampicin does not affect pyridoxine.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.253 Q1, Pyridoxine, Pantothenic acid, Ascorbic acid, Biotin') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiamine-riboflavin-nicotinic-acid-6a0758a5e9', 'pharm-thiamine-riboflavin-nicotinic-acid', 'mcq', 'Niacin deficiency causes the following EXCEPT:', '["Pellagra", "Blindness", "Dermatitis", "Diarrhoea", "Dementia"]'::jsonb, 'Blindness', '[]'::jsonb, 'Niacin deficiency causes pellagra, remembered as the three Ds: dermatitis (photosensitive), diarrhoea and dementia. Blindness is a feature of vitamin A deficiency (xerophthalmia, keratomalacia), not of niacin deficiency. Maize-based diets predispose because their niacin is bound and they are low in tryptophan.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.253 Q3, Thiamine, Riboflavin, Nicotinic Acid. Near-identical question on p.253 Q1 (answer "polymenorrhoea"); one copy kept.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiamine-riboflavin-nicotinic-acid-845f8c7298', 'pharm-thiamine-riboflavin-nicotinic-acid', 'mcq', 'A 50-year-old man presents with impaired cognitive abilities and peripheral neuropathy. He is a chronic alcoholic and has not been eating well for weeks. He is most likely to be deficient in:', '["Niacin", "Pyridoxine", "Thiamine", "Biotin", "Riboflavin"]'::jsonb, 'Thiamine', '[]'::jsonb, 'Chronic alcoholism with poor diet classically causes thiamine (vitamin B1) deficiency: alcohol reduces its intake, absorption and storage. It presents with peripheral neuropathy (dry beriberi) and Wernicke-Korsakoff syndrome with confusion and memory loss. Parenteral thiamine must be given before glucose.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.254 Q6, Thiamine, Riboflavin, Nicotinic Acid') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-dermatological-preparations-introducti-e0af385ed0', 'pharm-dermatological-preparations-introduction-glucocorticoids-retinoi', 'mcq', 'Which statement regarding isotretinoin is TRUE?', '["It is usually administered topically for severe acne", "It increases sebaceous gland number and size", "It causes foetal renal agenesis when administered in pregnancy", "It has a half-life of 10 to 20 hours", "It has no effect on the lipid profile"]'::jsonb, 'It has a half-life of 10 to 20 hours', '[]'::jsonb, 'Oral isotretinoin has an elimination half-life of 10 to 20 hours, unlike etretinate, which persists for months. It shrinks sebaceous glands and reduces sebum, raises triglycerides and cholesterol, and is a potent teratogen causing craniofacial, cardiac, thymic and CNS malformations.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.254 Q1, Dermatological Preparations') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-dermatological-preparations-introducti-b5ef99ef4b', 'pharm-dermatological-preparations-introduction-glucocorticoids-retinoi', 'mcq', 'Which of the following is a third-generation retinoid?', '["Motretinide", "Isotretinoin", "Adapalene", "Alitretinoin", "Etretinate"]'::jsonb, 'Adapalene', '[]'::jsonb, 'Third-generation retinoids are the polyaromatic, receptor-selective arotinoids: adapalene, tazarotene and bexarotene. Isotretinoin, tretinoin and alitretinoin are first-generation non-aromatic retinoids; etretinate, acitretin and motretinide are second-generation monoaromatic compounds. Adapalene is used topically for acne and is less irritant than tretinoin.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.254 Q3, Dermatological Preparations') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-dermatological-preparations-introducti-4eac501e2d', 'pharm-dermatological-preparations-introduction-glucocorticoids-retinoi', 'mcq', 'The following dermatological conditions are very responsive to topical steroid therapy EXCEPT:', '["Seborrhoeic dermatitis", "Atopic dermatitis", "Lichen simplex chronicus", "Pruritus ani", "Pemphigus"]'::jsonb, 'Pemphigus', '[]'::jsonb, 'Pemphigus is an autoimmune blistering disease that responds poorly to topical steroids and needs systemic corticosteroids and other immunosuppressants. Atopic and seborrhoeic dermatitis, lichen simplex chronicus and pruritus ani are among the dermatoses most responsive to topical steroids.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.255 Q4, Dermatological Preparations. Near-identical question on p.254 Q2 (low to medium efficacy steroids, answer also pemphigus); one copy kept.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-dermatological-preparations-introducti-90fdb4d6df', 'pharm-dermatological-preparations-introduction-glucocorticoids-retinoi', 'mcq', 'Which of the following dermatological vehicles has the least ability to retard evaporation of moisture from the skin?', '["Foam", "Ointment", "Tincture", "Cream", "Lotion"]'::jsonb, 'Tincture', '[]'::jsonb, 'Vehicles are ranked by how occlusive they are: tinctures and wet dressings evaporate quickly, dry the skin and retard moisture loss least, while greasy ointments are the most occlusive. Hence tinctures suit acute weeping lesions and ointments suit chronic dry, scaly ones.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.255 Q5, Dermatological Preparations') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antipruritic-agents-keratolytic-agents-2a6adfaf27', 'pharm-antipruritic-agents-keratolytic-agents', 'mcq', 'Regarding propylene glycol, which statement is INCORRECT?', '["It is contraindicated in psoriasis", "It is minimally absorbed", "It is a humectant", "It is hygroscopic", "It is keratolytic"]'::jsonb, 'It is contraindicated in psoriasis', '[]'::jsonb, 'Propylene glycol is widely used as a vehicle; it is hygroscopic and acts as a humectant, and at 40 to 70% it is an effective keratolytic used under occlusion for hyperkeratotic conditions including psoriasis and ichthyosis. Very little is absorbed through normal skin.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.255 Q1, Phototherapy, Psoralens') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-phototherapy-psoralens-0c04a677f8', 'pharm-phototherapy-psoralens', 'mcq', 'Which statement regarding psoralens is FALSE?', '["Food enhances their absorption", "They are soluble in water", "Bergapten is an example", "They can be combined with UVA radiation (PUVA)", "They are indicated in the therapy of vitiligo"]'::jsonb, 'They are soluble in water', '[]'::jsonb, 'Psoralens such as methoxsalen and bergapten are lipophilic furocoumarins that are poorly soluble in water; taking them with food or milk improves absorption and reduces nausea. They intercalate into DNA and, when activated by UVA (PUVA), are used for psoriasis and vitiligo.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.255 Q2, Phototherapy, Psoralens. Solubility and food-effect details are not in the standard texts; needs a human check.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-topical-cytotoxic-and-immunosuppressiv-7acf4427ed', 'pharm-topical-cytotoxic-and-immunosuppressive-agents', 'mcq', 'Which statement is TRUE of podophyllin?', '["It has no adverse effects at the site of application", "It is safe in pregnancy", "It is a calcineurin inhibitor", "It is a synthetic product", "It is used in the treatment of anogenital warts"]'::jsonb, 'It is used in the treatment of anogenital warts', '[]'::jsonb, 'Podophyllin is a plant resin from the mandrake (Podophyllum peltatum); its active component podophyllotoxin arrests mitosis by binding tubulin. It is applied to anogenital warts (condylomata acuminata), is locally irritant, can be absorbed with systemic toxicity, and is contraindicated in pregnancy.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.255 Q3, Phototherapy, Psoralens') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sunscreens-minoxidil-capsaicin-517ebfb34d', 'pharm-sunscreens-minoxidil-capsaicin', 'mcq', 'All of the following are true of chemical sunscreens EXCEPT:', '["They slow ageing of the skin", "They absorb ultraviolet light", "They include para-aminobenzoic acid", "They protect skin against photocarcinogenesis", "They block or reflect ultraviolet light"]'::jsonb, 'They block or reflect ultraviolet light', '[]'::jsonb, 'Chemical sunscreens such as PABA esters, benzophenones and dibenzoylmethanes absorb ultraviolet light. Physically blocking or reflecting it is what the opaque sunshades do: titanium dioxide and zinc oxide. Regular use of either type reduces photoageing and skin cancer.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.255 Q1, Sunscreens, Minoxidil, Capsaicin. Same question repeated as Q4 on p.256; one copy kept. Option b simplified.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sunscreens-minoxidil-capsaicin-fb7cf13713', 'pharm-sunscreens-minoxidil-capsaicin', 'mcq', 'All of the following are true of sunscreens EXCEPT:', '["Regular use of a sunscreen with a sun protection factor of 30 reduces the risk of skin cancer", "Para-aminobenzoic acid and its esters are the most effective absorbers of ultraviolet B light", "Zinc oxide and titanium dioxide are physical sunscreens", "Ecamsule is used in patients with drug-induced photosensitivity", "Sunscreens are applied once daily"]'::jsonb, 'Sunscreens are applied once daily', '[]'::jsonb, 'Sunscreens must be applied generously before exposure and reapplied every two hours or so and after swimming or sweating; one application a day does not maintain protection. Ecamsule absorbs UVA and is useful in UVA-mediated photosensitivity, including that caused by drugs.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.256 Q2, Sunscreens, Minoxidil, Capsaicin. Options a and c reworded for clarity.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sunscreens-minoxidil-capsaicin-224c518654', 'pharm-sunscreens-minoxidil-capsaicin', 'mcq', 'Identify the physical sunscreen:', '["Para-aminobenzoic acid", "Ecamsule", "Capsaicin", "Titanium dioxide", "Oxybenzone"]'::jsonb, 'Titanium dioxide', '[]'::jsonb, 'Titanium dioxide (like zinc oxide) is an opaque inorganic particle that reflects and scatters ultraviolet and visible light, so it is a physical sunscreen or sunshade. PABA, ecamsule and oxybenzone are chemical sunscreens that absorb ultraviolet energy.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.256 Q3, Sunscreens, Minoxidil, Capsaicin') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antipruritic-agents-keratolytic-agents-61338593f5', 'pharm-antipruritic-agents-keratolytic-agents', 'mcq', 'Pruritus induced by uraemia is classically treated using which of the modalities below?', '["Ultraviolet B radiation", "Cholestyramine", "Ondansetron", "Cetirizine", "Rifampicin"]'::jsonb, 'Ultraviolet B radiation', '[]'::jsonb, 'Broad or narrow-band UVB phototherapy is an established, effective treatment for uraemic pruritus, probably by reducing skin mast cells and pruritogenic cytokines. Antihistamines work poorly because the itch is not histamine mediated; cholestyramine and rifampicin are used for cholestatic itch.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.256 Q1, Antipruritic Agents, Keratolytic Agents. Distractors "Naltrexone" and "Doxepin" (both have some evidence in uraemic itch) replaced with cetirizine and rifampicin. Current guidelines also use gabapentinoids; needs a human check.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antipruritic-agents-keratolytic-agents-a1bfc23b87', 'pharm-antipruritic-agents-keratolytic-agents', 'mcq', 'Keratolytic agents should be used with particular care in patients with which of the following conditions?', '["Psoriasis", "Hypertrophic lichen planus", "Keratosis pilaris", "Plantar keratoderma", "Diabetic dermopathy"]'::jsonb, 'Diabetic dermopathy', '[]'::jsonb, 'Keratolytics such as salicylic acid can cause inflammation and ulceration, so they are used cautiously in diabetics and in peripheral vascular disease, where skin healing and sensation are impaired. The other conditions are hyperkeratotic disorders for which keratolytics are indicated.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.256 Q2, Antipruritic Agents, Keratolytic Agents. Reasoned from the caution about salicylic acid in diabetes; needs a human check.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-topical-cytotoxic-and-immunosuppressiv-f26f3b38c7', 'pharm-topical-cytotoxic-and-immunosuppressive-agents', 'mcq', 'Which topical cytotoxic or immunosuppressive drug is NOT appropriately matched with its clinical use?', '["Fluorouracil: superficial basal cell carcinoma", "Carmustine: cutaneous T-cell lymphoma", "Alitretinoin: AIDS-related Kaposi sarcoma", "Podophyllin: actinic keratosis", "Tacrolimus: atopic dermatitis"]'::jsonb, 'Podophyllin: actinic keratosis', '[]'::jsonb, 'Podophyllin is used for anogenital warts, not actinic keratosis. Actinic keratoses are treated with topical fluorouracil, imiquimod or diclofenac. Topical carmustine and mechlorethamine are used in mycosis fungoides, alitretinoin gel in Kaposi sarcoma and tacrolimus in atopic dermatitis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.257 Q1, Topical Cytotoxic and Immunosuppressive Agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sunscreens-minoxidil-capsaicin-0b0b9a896a', 'pharm-sunscreens-minoxidil-capsaicin', 'mcq', 'Which statement about finasteride is UNTRUE?', '["It inhibits the type II isoenzyme of 5-alpha-reductase", "It is administered orally", "It may cause erectile dysfunction, which can persist after stopping the medication", "It is teratogenic", "It promotes hair growth which persists following cessation of treatment"]'::jsonb, 'It promotes hair growth which persists following cessation of treatment', '[]'::jsonb, 'Finasteride blocks conversion of testosterone to dihydrotestosterone; the benefit in androgenic alopecia lasts only while the drug is taken, and new hair is lost within about a year of stopping. It can feminise a male fetus, so pregnant women must not even handle crushed tablets.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.257 Q2, Topical Cytotoxic and Immunosuppressive Agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sunscreens-minoxidil-capsaicin-c60a63563f', 'pharm-sunscreens-minoxidil-capsaicin', 'mcq', 'Which of the following is an anti-trichogenic agent (one that reduces hair growth)?', '["Capsaicin", "Minoxidil", "Eflornithine", "Dutasteride", "Finasteride"]'::jsonb, 'Eflornithine', '[]'::jsonb, 'Eflornithine irreversibly inhibits ornithine decarboxylase, which is needed for polyamine synthesis in the hair follicle; the cream slows growth of unwanted facial hair in women. Minoxidil, finasteride and dutasteride are trichogenic: they promote scalp hair growth.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.257 Q4, Topical Cytotoxic and Immunosuppressive Agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sunscreens-minoxidil-capsaicin-c94e2b44a2', 'pharm-sunscreens-minoxidil-capsaicin', 'mcq', 'Which trichogenic agent (hair growth promoter) may cause hypospadias in male fetuses?', '["Eflornithine", "Bimatoprost", "Minoxidil", "Finasteride", "Capsaicin"]'::jsonb, 'Finasteride', '[]'::jsonb, 'Dihydrotestosterone is needed for development of the male external genitalia. Finasteride, a 5-alpha-reductase inhibitor, lowers it and can cause hypospadias in a male fetus, so it is contraindicated in women who are or may become pregnant.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.257 Q5, Topical Cytotoxic and Immunosuppressive Agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sunscreens-minoxidil-capsaicin-b394dd9031', 'pharm-sunscreens-minoxidil-capsaicin', 'mcq', 'Concerning the use of these agents acting on hair, which statement is FALSE?', '["Eflornithine is used to reduce facial hair growth in women", "Bimatoprost is indicated for hypotrichosis of the eyelashes", "Finasteride is used in female patients with androgenic alopecia", "Minoxidil is used in the treatment of androgenic alopecia", "Eflornithine acts by inhibiting ornithine decarboxylase"]'::jsonb, 'Finasteride is used in female patients with androgenic alopecia', '[]'::jsonb, 'Finasteride is licensed for androgenic alopecia in men only; it is not approved for women and is contraindicated in those of childbearing potential because it can feminise a male fetus. Topical minoxidil is the agent used in both sexes.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.257 Q6, Topical Cytotoxic and Immunosuppressive Agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-tumor-antibiotics-anthracyclines-eb0498e201', 'pharm-tumor-antibiotics-anthracyclines', 'mcq', 'A patient with Hodgkin lymphoma develops dyspnoea, a non-productive cough and intermittent fever. If these problems are due to the anticancer drugs to which he has been exposed, which is the most likely causative agent?', '["Bleomycin", "Dacarbazine", "Doxorubicin", "Prednisone", "Vinblastine"]'::jsonb, 'Bleomycin', '[]'::jsonb, 'Bleomycin, part of the ABVD regimen, causes dose-related pneumonitis that progresses to pulmonary fibrosis, presenting with dry cough, dyspnoea, fever and basal crackles. The lung lacks bleomycin hydrolase. Doxorubicin''s characteristic toxicity is cardiac, and vinblastine''s is myelosuppression.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.258 Q2, Anticancer General Principles & Adverse Effects. Same question repeated on p.263 Q1 (Tumor Antibiotics); one copy kept.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticancer-agents-general-principles-c-870265f3e0', 'pharm-anticancer-agents-general-principles-classification', 'mcq', 'Which of the following is a cell cycle-specific anticancer drug that acts mainly in the M phase of the cell cycle?', '["Etoposide", "Paclitaxel", "Methotrexate", "Bleomycin", "Cisplatin"]'::jsonb, 'Paclitaxel', '[]'::jsonb, 'Paclitaxel stabilises microtubules and prevents their disassembly, arresting cells in mitosis (M phase). The vinca alkaloids also act in M phase. Etoposide acts in S and G2, methotrexate in S phase, bleomycin in G2, and cisplatin is cell cycle non-specific.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.258 Q3, Anticancer General Principles & Adverse Effects. Stem repeated without options as Q5 on the same page.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emetics-antiemetics-and-prokinetic-age-fefc6f79a0', 'pharm-emetics-antiemetics-and-prokinetic-agents', 'mcq', 'A 40-year-old patient is about to undergo cancer chemotherapy with a highly emetogenic drug combination. The antiemetic drug most likely to be included in her regimen is:', '["Ketanserin", "Cetirizine", "Ondansetron", "Cimetidine", "Bromocriptine"]'::jsonb, 'Ondansetron', '[]'::jsonb, 'Ondansetron blocks 5-HT3 receptors on vagal afferents in the gut and in the chemoreceptor trigger zone, the main pathway for acute chemotherapy-induced vomiting. Ketanserin blocks 5-HT2 receptors and has no antiemetic effect; bromocriptine, a dopamine agonist, causes nausea.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.258 Q4, Anticancer General Principles & Adverse Effects') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-hormonal-anticancer-drugs-7b925da07a', 'pharm-hormonal-anticancer-drugs', 'mcq', 'Which anticancer drug is NOT appropriately matched with its mechanism of action or classification?', '["Tamoxifen: selective oestrogen receptor modulator", "Goserelin: gonadotropin-releasing hormone analogue", "Abiraterone: aromatase inhibitor", "Megestrol acetate: progestin", "Flutamide: androgen receptor antagonist"]'::jsonb, 'Abiraterone: aromatase inhibitor', '[]'::jsonb, 'Abiraterone inhibits CYP17 (17-alpha-hydroxylase/17,20-lyase), blocking androgen synthesis in the testes, adrenals and tumour; it is used in prostate cancer. The aromatase inhibitors are anastrozole, letrozole and exemestane. The other pairs are correct; megestrol is also used as an appetite stimulant in cachexia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.258 Q6, Anticancer General Principles & Adverse Effects. Same question repeated on p.264 Q4 (Hormonal Anticancer Drugs); one copy kept.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticancer-agents-general-principles-c-9b2b237f23', 'pharm-anticancer-agents-general-principles-classification', 'mcq', 'Which drug is INCORRECTLY matched with its adverse effect?', '["Cisplatin: ototoxicity", "Bleomycin: pulmonary fibrosis", "Vincristine: aplastic anaemia", "Methotrexate: glossitis", "Doxorubicin: dilated cardiomyopathy"]'::jsonb, 'Vincristine: aplastic anaemia', '[]'::jsonb, 'Vincristine is notable for being relatively marrow sparing; its dose-limiting toxicity is peripheral neuropathy (with constipation and paralytic ileus). The other pairings are the classic organ toxicities of those drugs.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.259 Q7, Anticancer General Principles & Adverse Effects. A similar matching question (p.258 Q1) had no incorrect pair and was skipped.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-alkylating-agents-5d6bde575e', 'pharm-alkylating-agents', 'mcq', 'Which of the following is NOT a nitrogen mustard?', '["Melphalan", "Ifosfamide", "Mechlorethamine", "Temozolomide", "Chlorambucil"]'::jsonb, 'Temozolomide', '[]'::jsonb, 'Temozolomide is a triazene-type methylating agent (related to dacarbazine) used orally for gliomas. The nitrogen mustards, which carry the bis(2-chloroethyl)amine group, are mechlorethamine, cyclophosphamide, ifosfamide, melphalan and chlorambucil. Temozolomide is tempting because it is also an alkylating agent, but of a different chemical class.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.259 Q8, Anticancer General Principles & Adverse Effects') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticancer-agents-general-principles-c-ee08995550', 'pharm-anticancer-agents-general-principles-classification', 'mcq', 'Which of the following is NOT a cell cycle-specific cytotoxic drug?', '["Idarubicin", "Capecitabine", "Paclitaxel", "Vincristine", "Asparaginase"]'::jsonb, 'Idarubicin', '[]'::jsonb, 'Anthracyclines such as idarubicin, like alkylating agents and platinum compounds, kill cells in any phase and are cell cycle non-specific. Capecitabine (S phase), paclitaxel and vincristine (M phase) and asparaginase (G1) are phase specific.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.259 Q9, Anticancer General Principles & Adverse Effects') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticancer-agents-general-principles-c-0c71035585', 'pharm-anticancer-agents-general-principles-classification', 'mcq', 'The rationale for combination chemotherapy includes the following EXCEPT:', '["Biochemical enhancement of effect", "Rescue of normal cells", "Biochemical nullification of effect", "Overcoming or preventing resistance", "Cytotoxicity to both resting and dividing cells"]'::jsonb, 'Biochemical nullification of effect', '[]'::jsonb, 'Drugs are combined to achieve additive or synergistic kill, to cover both resting and dividing cells, to delay resistance and to allow rescue of normal tissue (for example leucovorin after methotrexate). A combination in which one drug cancels the other would be irrational.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.259 Q10, Anticancer General Principles & Adverse Effects') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-alkylating-agents-5f6833f18c', 'pharm-alkylating-agents', 'mcq', 'Which statement regarding cyclophosphamide is FALSE?', '["It can be given orally", "It is an alkylating agent", "Its use may cause haemorrhagic cystitis", "It is a prodrug", "It is a nitrosourea compound"]'::jsonb, 'It is a nitrosourea compound', '[]'::jsonb, 'Cyclophosphamide is a nitrogen mustard, not a nitrosourea (those are carmustine and lomustine). It is a prodrug activated by hepatic CYP enzymes, is active orally and intravenously, and its metabolite acrolein causes haemorrhagic cystitis, prevented with mesna and hydration.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.259 Q1, Alkylating agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-alkylating-agents-ce34bc115b', 'pharm-alkylating-agents', 'mcq', 'Which of the following is NOT an alkylating agent?', '["Bleomycin", "Melphalan", "Cyclophosphamide", "Chlorambucil", "Carmustine"]'::jsonb, 'Bleomycin', '[]'::jsonb, 'Bleomycin is an antitumour antibiotic: it binds DNA and, with iron and oxygen, generates free radicals that cause strand breaks. Melphalan, cyclophosphamide and chlorambucil are nitrogen mustards and carmustine a nitrosourea, all of which alkylate DNA.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.259 Q2, Alkylating agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-alkylating-agents-985fcdfd8c', 'pharm-alkylating-agents', 'mcq', 'Which of the following is NOT an adverse effect of cyclophosphamide?', '["Bone marrow suppression", "Peripheral neuropathy", "Haemorrhagic cystitis", "Alopecia", "Hypogonadism"]'::jsonb, 'Peripheral neuropathy', '[]'::jsonb, 'Cyclophosphamide causes myelosuppression, alopecia, haemorrhagic cystitis, nausea, and gonadal failure with infertility. Peripheral neuropathy is characteristic of the vinca alkaloids, taxanes and platinum compounds rather than cyclophosphamide. Mesna and hydration protect the bladder but do not prevent the other effects.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.260 Q3, Alkylating agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antimetabolites-b3812306f8', 'pharm-antimetabolites', 'mcq', 'Which cytotoxic agent is administered via the intrathecal route?', '["Fluorouracil", "Methotrexate", "Capecitabine", "Cladribine", "Gemcitabine"]'::jsonb, 'Methotrexate', '[]'::jsonb, 'Methotrexate penetrates the CNS poorly, so it is injected intrathecally to treat or prevent meningeal leukaemia and lymphoma. Cytarabine is the other antimetabolite given this way. Vincristine must never be given intrathecally: it is fatal.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.260 Q1, Antimetabolites. The paper also listed cytosine arabinoside, which is given intrathecally too; replaced with fluorouracil so there is one answer.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antimetabolites-969d72cc66', 'pharm-antimetabolites', 'mcq', 'Dose reduction of which of the following drugs is recommended if allopurinol is co-administered?', '["Trifluridine", "Pemetrexed", "Decitabine", "5-fluorouracil", "6-mercaptopurine"]'::jsonb, '6-mercaptopurine', '[]'::jsonb, '6-Mercaptopurine is inactivated by xanthine oxidase, the enzyme allopurinol inhibits. Co-administration raises active thiopurine levels and causes severe myelosuppression, so the oral dose of mercaptopurine (or azathioprine) must be cut to about a quarter.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.260 Q2, Antimetabolites') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antimetabolites-e3414f2f3d', 'pharm-antimetabolites', 'mcq', 'Which of the following is a cell cycle-specific cancer chemotherapeutic agent?', '["Cisplatin", "Daunorubicin", "Methotrexate", "Dacarbazine", "Cyclophosphamide"]'::jsonb, 'Methotrexate', '[]'::jsonb, 'Methotrexate inhibits dihydrofolate reductase, blocking thymidylate and purine synthesis, so it kills cells only while they are synthesising DNA (S phase). Platinum compounds, anthracyclines and alkylating agents such as dacarbazine and cyclophosphamide are cell cycle non-specific.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.260 Q3, Antimetabolites') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antimetabolites-cc60874802', 'pharm-antimetabolites', 'mcq', 'In which of the following conditions is methotrexate NOT indicated?', '["Rheumatoid arthritis", "Gouty arthritis", "Psoriasis", "Medical termination of pregnancy", "Choriocarcinoma"]'::jsonb, 'Gouty arthritis', '[]'::jsonb, 'Gout is a crystal arthropathy treated with NSAIDs, colchicine, steroids and urate-lowering drugs; methotrexate has no role. Methotrexate is used in rheumatoid arthritis and psoriasis, cures choriocarcinoma, and with misoprostol is used for ectopic pregnancy and medical abortion.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.260 Q4, Antimetabolites. Distractor "Asthma" (an uncommon steroid-sparing use) replaced with psoriasis; a second version on p.261 Q9 was skipped as ambiguous.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antimetabolites-ad2de8a820', 'pharm-antimetabolites', 'mcq', 'All of the following are pyrimidine analogues EXCEPT:', '["Capecitabine", "Pentostatin", "Gemcitabine", "Cytarabine", "Fluorouracil"]'::jsonb, 'Pentostatin', '[]'::jsonb, 'Pentostatin is a purine analogue that inhibits adenosine deaminase, used in hairy cell leukaemia. Fluorouracil and its prodrug capecitabine are uracil analogues, and cytarabine and gemcitabine are cytidine analogues: all pyrimidine antimetabolites.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.261 Q5, Antimetabolites') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antimetabolites-c9302a9785', 'pharm-antimetabolites', 'mcq', 'Which statement regarding purine analogues is INCORRECT?', '["They may cause bone marrow suppression", "6-Mercaptopurine is converted to inactive metabolites by thiopurine methyltransferase", "The bioavailability of 6-mercaptopurine is superior to that of azathioprine", "They are used to maintain remission in inflammatory bowel disease", "The dose of azathioprine must be reduced in patients taking concomitant allopurinol"]'::jsonb, 'The bioavailability of 6-mercaptopurine is superior to that of azathioprine', '[]'::jsonb, 'Azathioprine is well absorbed (about 80%) and is converted to 6-mercaptopurine, whereas oral mercaptopurine itself has low and variable bioavailability (about 50% or less) because of first-pass metabolism by xanthine oxidase. Both are inactivated by TPMT and xanthine oxidase and cause dose-related myelosuppression.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.261 Q6, Antimetabolites. Options d and e reworded (the paper said "induction and maintenance in ulcerative colitis" and "reduced by half"; the usual advice is a reduction to a quarter or third).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antimetabolites-32c6267f19', 'pharm-antimetabolites', 'mcq', 'Which statement regarding methotrexate is FALSE?', '["Leucovorin is used in high-dose therapy", "It is only used intravenously", "It is hepatotoxic in long-term use", "Low affinity of dihydrofolate reductase for methotrexate results in resistance to therapy", "It is abortifacient when combined with prostaglandins"]'::jsonb, 'It is only used intravenously', '[]'::jsonb, 'Methotrexate is given orally (for example weekly in rheumatoid arthritis and psoriasis), intramuscularly, intravenously and intrathecally. Leucovorin rescues normal cells after high doses, long-term use causes hepatic fibrosis, and altered or amplified dihydrofolate reductase causes resistance.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.261 Q7, Antimetabolites. Typo in option d corrected ("dihydrofolate" → dihydrofolate reductase).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antimetabolites-0c39cee763', 'pharm-antimetabolites', 'mcq', 'The following are antimetabolite anticancer drugs EXCEPT:', '["6-Thioguanine", "Capecitabine", "Cytosine arabinoside", "Methotrexate", "Cyclophosphamide"]'::jsonb, 'Cyclophosphamide', '[]'::jsonb, 'Cyclophosphamide is an alkylating agent of the nitrogen mustard group. Antimetabolites are structural analogues of normal metabolites: methotrexate (folate), thioguanine (purine), and capecitabine and cytarabine (pyrimidines). Alkylating agents damage DNA directly and are cell cycle non-specific, unlike the S-phase specific antimetabolites.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.261 Q8, Antimetabolites') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-vinca-alkaloids-platinum-agents-e135336e7f', 'pharm-vinca-alkaloids-platinum-agents', 'mcq', 'Which statement regarding vinblastine is FALSE?', '["It is a cell cycle-specific agent", "The nadir in white cell count occurs within 3 days", "It inhibits tubulin polymerisation", "It requires dose adjustment in patients with hepatic dysfunction", "It is useful in the management of testicular tumours"]'::jsonb, 'The nadir in white cell count occurs within 3 days', '[]'::jsonb, 'Vinblastine''s dose-limiting toxicity is myelosuppression, with the leucocyte nadir at about 7 to 10 days, not 3 days. It binds tubulin, blocks spindle formation and arrests cells in M phase; it is excreted in bile and is used in Hodgkin lymphoma and testicular cancer.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.262 Q2, Vinca Alkaloids, Platinum Agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-vinca-alkaloids-platinum-agents-4b19eab65a', 'pharm-vinca-alkaloids-platinum-agents', 'mcq', 'Which drug is NOT a vinca alkaloid?', '["Vindesine", "Vinflunine", "Vincristine", "Vinblastine", "Vigabatrin"]'::jsonb, 'Vigabatrin', '[]'::jsonb, 'Vigabatrin is an antiseizure drug that irreversibly inhibits GABA transaminase. The vinca alkaloids, derived from the periwinkle plant, are vincristine, vinblastine, vinorelbine, vindesine and vinflunine; all inhibit tubulin polymerisation. Their main toxicities differ: neuropathy for vincristine, myelosuppression for vinblastine and vinorelbine.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.262 Q3, Vinca Alkaloids, Platinum Agents. The paper used an invented name ("Vinmectin") as the odd one out; replaced with a real drug, vigabatrin, and vinorelbine swapped for vinflunine.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-vinca-alkaloids-platinum-agents-61e51a749a', 'pharm-vinca-alkaloids-platinum-agents', 'mcq', 'Which is the FALSE statement about cisplatin?', '["It is given intravenously", "It forms cross-links in DNA", "It achieves a high concentration in the testes", "It has poor CNS penetration", "It is safe to give to patients with chronic kidney disease"]'::jsonb, 'It is safe to give to patients with chronic kidney disease', '[]'::jsonb, 'Cisplatin is markedly nephrotoxic and is excreted by the kidney, so it is avoided or dose-reduced in renal impairment and always given with vigorous saline hydration. It concentrates in kidney, liver, intestine and testes (hence its value in testicular cancer) but enters the CNS poorly.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.262 Q4, Vinca Alkaloids, Platinum Agents. Option b reworded from "causes DNA strand breaks" to the accepted mechanism.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-vinca-alkaloids-platinum-agents-a1f8bf61e4', 'pharm-vinca-alkaloids-platinum-agents', 'mcq', 'Which statement about platinum compounds is FALSE?', '["They are cell cycle specific", "They are less likely than the alkylating agents to cause leukaemia", "Cisplatin has synergistic cytotoxicity with radiation and other chemotherapeutic agents", "They can bind to proteins with -SH groups", "They are activated within cells by displacement of chloride ions"]'::jsonb, 'They are cell cycle specific', '[]'::jsonb, 'Platinum compounds behave like alkylating agents: inside the cell, where chloride is low, chloride ligands are replaced by water, and the reactive species cross-links DNA at guanine N7. They kill cells in all phases, so they are cell cycle non-specific.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.262 Q5, Vinca Alkaloids, Platinum Agents') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-epipodophyllotoxins-camptothecins-anal-7fe7ee12a3', 'pharm-epipodophyllotoxins-camptothecins-analogues', 'mcq', 'All of the following are true of irinotecan EXCEPT:', '["Diarrhoea that occurs 7 days after administration is treated with atropine", "Bacteria in the gastrointestinal tract may reactivate the excreted metabolite", "It is a camptothecin analogue", "It is an S-phase specific drug", "It is a prodrug"]'::jsonb, 'Diarrhoea that occurs 7 days after administration is treated with atropine', '[]'::jsonb, 'Irinotecan causes two kinds of diarrhoea. The early type, within 24 hours, is cholinergic and responds to atropine; the late type, days afterwards, is due to the active metabolite SN-38 damaging gut mucosa and is treated with high-dose loperamide. Gut bacterial glucuronidase regenerates SN-38 from its glucuronide.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.262 Q1, Epipodophyllotoxins, Camptothecin Analogues') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-epipodophyllotoxins-camptothecins-anal-e99329ee4e', 'pharm-epipodophyllotoxins-camptothecins-analogues', 'mcq', 'All of the following are true of camptothecins EXCEPT:', '["They inhibit the activity of topoisomerase I", "Irinotecan is mainly excreted in faeces", "Irinotecan inhibits acetylcholinesterase", "Topotecan is a prodrug", "They include topotecan and irinotecan"]'::jsonb, 'Topotecan is a prodrug', '[]'::jsonb, 'Topotecan is active as given and is excreted mainly by the kidney. It is irinotecan that is a prodrug, converted by carboxylesterase to SN-38, which is eliminated in bile and faeces. Irinotecan also inhibits acetylcholinesterase, explaining its early cholinergic diarrhoea.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.263 Q2, Epipodophyllotoxins, Camptothecin Analogues. Option c corrected from "inhibits acetylcholine" to "inhibits acetylcholinesterase".') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-epipodophyllotoxins-camptothecins-anal-c5bf44b4a8', 'pharm-epipodophyllotoxins-camptothecins-analogues', 'mcq', 'Lack of carboxylesterase activity is a mechanism of resistance to which of the following drugs?', '["Irinotecan", "Busulphan", "Etoposide", "Cisplatin", "Methotrexate"]'::jsonb, 'Irinotecan', '[]'::jsonb, 'Irinotecan is a prodrug that must be hydrolysed by carboxylesterase in liver and tumour to its active metabolite SN-38, a potent topoisomerase I inhibitor. Tumour cells with low carboxylesterase activity fail to activate it and are resistant.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.263 Q3, Epipodophyllotoxins, Camptothecin Analogues') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-tumor-antibiotics-anthracyclines-132a73c72e', 'pharm-tumor-antibiotics-anthracyclines', 'mcq', 'Radiation recall reaction is associated with which of the following cytotoxic agents?', '["Doxorubicin", "Plicamycin", "Asparaginase", "Cisplatin", "Vincristine"]'::jsonb, 'Doxorubicin', '[]'::jsonb, 'Radiation recall is an inflammatory reaction (erythema, desquamation) confined to previously irradiated skin, triggered when certain drugs are given later. Anthracyclines such as doxorubicin, and dactinomycin, are the classic causes.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.263 Q2, Tumor Antibiotics - Anthracyclines. Distractor "Mitomycin C" replaced with asparaginase to avoid any doubt.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-tumor-antibiotics-anthracyclines-c6f53b3849', 'pharm-tumor-antibiotics-anthracyclines', 'mcq', 'Which of the following has cardiotoxicity as its dose-limiting toxicity?', '["Bleomycin", "Doxorubicin", "Methotrexate", "Busulphan", "Cyclophosphamide"]'::jsonb, 'Doxorubicin', '[]'::jsonb, 'Doxorubicin, an anthracycline, generates iron-dependent free radicals in the myocardium, causing cumulative dose-dependent dilated cardiomyopathy (risk rises above about 450 to 550 mg/m2); dexrazoxane is protective. Bleomycin damages the lung and busulphan the marrow and lung.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.263 Q3, Tumor Antibiotics - Anthracyclines. Stem reworded, since only one option is an anthracycline.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-tumor-antibiotics-anthracyclines-d1468c8968', 'pharm-tumor-antibiotics-anthracyclines', 'mcq', 'Which anthracycline is NOT appropriately matched with its clinical use?', '["Doxorubicin: acute lymphoblastic leukaemia", "Liposomal daunorubicin: AIDS-related Kaposi sarcoma", "Valrubicin: soft tissue sarcomas", "Idarubicin: acute myeloid leukaemia", "Epirubicin: breast cancer"]'::jsonb, 'Valrubicin: soft tissue sarcomas', '[]'::jsonb, 'Valrubicin is instilled into the bladder for BCG-refractory carcinoma in situ of the urinary bladder; it is not used for sarcomas. Doxorubicin is the anthracycline used in soft tissue sarcoma, as well as in leukaemias, lymphomas and breast cancer.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.264 Q5, Tumor Antibiotics - Anthracyclines') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-hormonal-anticancer-drugs-688e447ceb', 'pharm-hormonal-anticancer-drugs', 'mcq', 'Which is a first-line drug for the treatment of hormone receptor-positive breast cancer in postmenopausal women?', '["Abiraterone acetate", "Letrozole", "Leuprolide", "Bicalutamide", "Ethinyl oestradiol"]'::jsonb, 'Letrozole', '[]'::jsonb, 'After the menopause, oestrogen comes from peripheral aromatisation of adrenal androgens. Letrozole, a non-steroidal aromatase inhibitor, blocks this and is first-line (more effective than tamoxifen) for receptor-positive disease. Abiraterone and bicalutamide are prostate cancer drugs.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.264 Q1, Hormonal Anticancer Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-hormonal-anticancer-drugs-c716f70ff9', 'pharm-hormonal-anticancer-drugs', 'mcq', 'Which of the following is NOT an adverse effect of tamoxifen?', '["Hot flushes", "Increased risk of endometrial cancer", "Hypocalcaemia", "Vaginal bleeding", "Venous thromboembolism"]'::jsonb, 'Hypocalcaemia', '[]'::jsonb, 'Tamoxifen is an oestrogen antagonist in breast but a partial agonist in endometrium, bone and liver. It causes hot flushes, vaginal bleeding, endometrial hyperplasia and cancer, and thromboembolism. In patients with bone metastases it may cause a hypercalcaemic flare, not hypocalcaemia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.264 Q2, Hormonal Anticancer Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-alkylating-agents-9fce6a1d90', 'pharm-alkylating-agents', 'mcq', 'All of the following are true of altretamine EXCEPT:', '["It is neurotoxic", "It is structurally related to the alkylating agent triethylenemelamine", "It is given intravenously", "Dose-limiting toxicities include nausea, vomiting and myelosuppression", "It is approved for use in ovarian cancer"]'::jsonb, 'It is given intravenously', '[]'::jsonb, 'Altretamine (hexamethylmelamine) is given orally and is activated by hepatic demethylation. It is used for persistent or recurrent ovarian cancer; its toxicities are nausea, vomiting, myelosuppression and peripheral and central neurotoxicity.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.264 Q3, Hormonal Anticancer Drugs. Option b reworded: the paper called it "an ethyleneimine" (thiotepa is the ethyleneimine; altretamine is a methylmelamine).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticancer-monoclonal-antibodies-f3dec21b98', 'pharm-anticancer-monoclonal-antibodies', 'mcq', 'Which agent is a soluble decoy receptor for vascular endothelial growth factor (VEGF)?', '["Ziv-aflibercept", "Bevacizumab", "Sorafenib", "Carfilzomib", "Dasatinib"]'::jsonb, 'Ziv-aflibercept', '[]'::jsonb, 'Ziv-aflibercept is a recombinant fusion protein of the VEGF-binding portions of VEGFR-1 and VEGFR-2 joined to the Fc of human IgG1; it traps circulating VEGF. Bevacizumab also neutralises VEGF but is a monoclonal antibody, not a receptor.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.265 Q2, Small Molecule Inhibitors & Monoclonal Antibodies. Stem reworded for clarity.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticancer-monoclonal-antibodies-67e6e65bc9', 'pharm-anticancer-monoclonal-antibodies', 'mcq', 'Which monoclonal antibody is a chimeric antibody?', '["Rituximab", "Trastuzumab", "Alemtuzumab", "Panitumumab", "Pembrolizumab"]'::jsonb, 'Rituximab', '[]'::jsonb, 'The suffix tells the source: -ximab is chimeric (mouse variable regions on human constant regions), -zumab is humanised and -umab fully human. Rituximab (anti-CD20) is chimeric; trastuzumab, alemtuzumab and pembrolizumab are humanised and panitumumab is human.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.265 Q3, Small Molecule Inhibitors & Monoclonal Antibodies') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticancer-monoclonal-antibodies-405ef50f78', 'pharm-anticancer-monoclonal-antibodies', 'mcq', 'Which is the FALSE statement about therapeutic monoclonal antibodies?', '["They can block cell surface receptors", "They can carry toxins and radionuclides to the cell of interest, enhancing cytotoxicity", "They are specific for a single target", "They have a long plasma half-life", "They require daily administration"]'::jsonb, 'They require daily administration', '[]'::jsonb, 'IgG monoclonal antibodies have half-lives of days to weeks, so they are given every one to four weeks, not daily. Their specificity for one antigen allows receptor blockade and targeted delivery of toxins or radioisotopes.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.265 Q4, Small Molecule Inhibitors & Monoclonal Antibodies') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticancer-small-molecule-inhibitors-b49386780e', 'pharm-anticancer-small-molecule-inhibitors', 'mcq', 'All of the following are true of imatinib EXCEPT:', '["It is excreted in faeces", "It is a tyrosine kinase inhibitor", "Mutations that cause resistance to imatinib also cause cross-resistance to ponatinib", "It is administered orally", "It causes fluid retention"]'::jsonb, 'Mutations that cause resistance to imatinib also cause cross-resistance to ponatinib', '[]'::jsonb, 'Ponatinib was designed to overcome imatinib resistance: it remains active against BCR-ABL kinase domain mutations, including T315I, that defeat imatinib, dasatinib and nilotinib. Imatinib is oral, metabolised by CYP3A4, excreted in faeces, and causes oedema and fluid retention.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.265 Q6, Small Molecule Inhibitors & Monoclonal Antibodies') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticancer-small-molecule-inhibitors-fec690ebd1', 'pharm-anticancer-small-molecule-inhibitors', 'mcq', 'Which of the following is NOT a clinical use of imatinib mesylate?', '["Hypereosinophilic syndrome", "Gastrointestinal stromal tumour", "Dermatofibrosarcoma protuberans", "Chronic lymphocytic leukaemia", "Chronic myeloid leukaemia"]'::jsonb, 'Chronic lymphocytic leukaemia', '[]'::jsonb, 'Imatinib works where a sensitive kinase drives the disease: BCR-ABL in chronic myeloid leukaemia, c-KIT in gastrointestinal stromal tumours and PDGFR in hypereosinophilic syndrome and dermatofibrosarcoma protuberans. Chronic lymphocytic leukaemia is treated with ibrutinib, venetoclax and anti-CD20 antibodies.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.265 Q7, Small Molecule Inhibitors & Monoclonal Antibodies') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-miscellaneous-anticancer-drugs-be11657a49', 'pharm-miscellaneous-anticancer-drugs', 'mcq', 'Which is the FALSE statement?', '["Mitomycin is instilled directly into the urinary bladder for treatment of superficial bladder cancer", "Mitotane is used in the treatment of adrenal cortex carcinoma", "Trabectedin is administered with dexamethasone to reduce hepatic toxicity", "Pegaspargase has a longer half-life than asparaginase", "Hydroxyurea is contraindicated in patients with sickle cell disease"]'::jsonb, 'Hydroxyurea is contraindicated in patients with sickle cell disease', '[]'::jsonb, 'Hydroxyurea is a standard treatment for sickle cell disease: it raises fetal haemoglobin, reducing sickling, painful crises and transfusion needs. It inhibits ribonucleotide reductase and is also used in chronic myeloid leukaemia and polycythaemia vera.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.266 Q1, Miscellaneous Anticancer Drugs') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emergency-management-of-poisoning-e772bdc996', 'pharm-emergency-management-of-poisoning', 'mcq', 'Haemodialysis may be used in the management of overdose with which of the following?', '["Calcium channel blockers", "Amphetamine", "Opioids", "Theophylline", "Digoxin"]'::jsonb, 'Theophylline', '[]'::jsonb, 'Dialysis removes drugs that are small, water soluble, little protein bound and have a small volume of distribution, such as theophylline, lithium, salicylates, methanol and ethylene glycol. Digoxin, opioids, amphetamines and calcium channel blockers have large volumes of distribution, so little is in the blood to remove.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.266 Q1, Emergency Management of Poisoning') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emergency-management-of-poisoning-1a1419e28e', 'pharm-emergency-management-of-poisoning', 'mcq', 'Activated charcoal is useful in the management of overdose with:', '["Iron", "Lithium", "Cyanide", "Alcohol", "Dapsone"]'::jsonb, 'Dapsone', '[]'::jsonb, 'Dapsone is well adsorbed by charcoal and undergoes enterohepatic circulation, so repeated doses of activated charcoal speed its elimination. Charcoal binds poorly to small ions and molecules: iron, lithium, cyanide, alcohols, acids and alkalis.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.266 Q2, Emergency Management of Poisoning') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emergency-management-of-poisoning-a56dab77ea', 'pharm-emergency-management-of-poisoning', 'mcq', 'Haemodialysis may be indicated in the emergency management of poisoning with the following EXCEPT:', '["Ethylene glycol", "Theophylline", "Valproic acid", "Digoxin", "Metformin"]'::jsonb, 'Digoxin', '[]'::jsonb, 'Digoxin has a very large volume of distribution (it is bound in tissues), so dialysis removes a negligible amount; severe toxicity is treated with digoxin-specific antibody fragments. Ethylene glycol, theophylline, valproate in massive overdose and metformin-associated lactic acidosis are dialysable problems.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.266 Q3, Emergency Management of Poisoning') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emergency-management-of-poisoning-b5537d4f80', 'pharm-emergency-management-of-poisoning', 'mcq', 'Which of the following is well adsorbed by activated charcoal?', '["Alcohol", "Corrosive acids", "Phenobarbital", "Iron sulphate", "Lithium"]'::jsonb, 'Phenobarbital', '[]'::jsonb, 'Phenobarbital binds well to charcoal, and multiple-dose activated charcoal also interrupts its enteroenteric circulation, shortening its half-life. Alcohols, corrosives, iron and lithium are not adsorbed to a useful extent, and charcoal obscures endoscopy after corrosive ingestion.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.266 Q4, Emergency Management of Poisoning') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emergency-management-of-poisoning-d2ccafbf43', 'pharm-emergency-management-of-poisoning', 'mcq', 'All of the following are true of activated charcoal EXCEPT:', '["It reduces the enterohepatic circulation of phenobarbital", "It reduces absorption of poisons", "It adsorbs iron", "It causes constipation", "It is contraindicated if the airway is unprotected"]'::jsonb, 'It adsorbs iron', '[]'::jsonb, 'Activated charcoal does not bind iron, lithium, potassium, alcohols or cyanide effectively. It adsorbs most organic drugs, can interrupt enterohepatic recycling, may cause constipation or obstruction, and must not be given to a drowsy patient with an unprotected airway because of aspiration.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.267 Q5, Emergency Management of Poisoning') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-opioids-and-barbiturate-poisoning-8e8cd1e860', 'pharm-opioids-and-barbiturate-poisoning', 'mcq', 'Which of the following is NOT a sign of opioid poisoning?', '["Miosis", "Coma", "Tachypnoea", "Hypothermia", "Hypotension"]'::jsonb, 'Tachypnoea', '[]'::jsonb, 'Opioids depress the brainstem respiratory centre, so the respiratory rate is slow, not fast. The classic triad is coma, pinpoint pupils and respiratory depression, often with hypotension, bradycardia and hypothermia; naloxone reverses it.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.267 Q1, Opioids and Barbiturate Poisoning') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-opioids-and-barbiturate-poisoning-30b8e7a313', 'pharm-opioids-and-barbiturate-poisoning', 'mcq', 'Miosis is an expected physical finding in a patient with overdose of each of the following EXCEPT:', '["Organophosphates", "Clonidine", "Cocaine", "Opioids", "Phenothiazines"]'::jsonb, 'Cocaine', '[]'::jsonb, 'Cocaine blocks noradrenaline reuptake, producing sympathetic overactivity with dilated pupils (mydriasis). Small pupils are seen with opioids, organophosphates (muscarinic stimulation), clonidine (central alpha-2 agonist) and phenothiazines (alpha blockade). Other causes of mydriasis are amphetamines, antimuscarinics and tricyclic antidepressants.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.267 Q2, Opioids and Barbiturate Poisoning. The paper omitted "EXCEPT" although four options cause miosis; added.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-addiction-to-cns-depressants-psychedel-aa918c3645', 'pharm-addiction-to-cns-depressants-psychedelic-agents', 'mcq', 'A combination of vertical and horizontal nystagmus is a prominent feature of poisoning with:', '["Phenothiazines", "Phenytoin", "Phencyclidine", "Phenobarbital", "Diphenhydramine"]'::jsonb, 'Phencyclidine', '[]'::jsonb, 'Phencyclidine (PCP) intoxication characteristically produces both vertical and horizontal nystagmus, together with agitation, hypertension, analgesia and psychosis. Phenytoin and barbiturates typically cause horizontal gaze-evoked nystagmus. Diphenhydramine causes an antimuscarinic picture with dilated pupils, and phenothiazines cause sedation and dystonia.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.267 Q3, Opioids and Barbiturate Poisoning') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-acetaminophen-acetylsalicylic-acid-poi-5aab95ff30', 'pharm-acetaminophen-acetylsalicylic-acid-poisoning', 'mcq', 'An 18-month-old boy dies from an accidental overdose of acetaminophen (paracetamol). Which is the most likely cause of death?', '["Arrhythmia", "Haemorrhagic stroke", "Liver failure", "Non-cardiogenic pulmonary oedema", "Ventilatory failure"]'::jsonb, 'Liver failure', '[]'::jsonb, 'In overdose the glucuronide and sulphate pathways are saturated and more paracetamol is oxidised by CYP2E1 to NAPQI, which exhausts glutathione and causes centrilobular hepatic necrosis and fulminant liver failure. Non-cardiogenic pulmonary oedema is a feature of salicylate poisoning.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.267 Q1, Acetaminophen and Salicylate Poisoning') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-acetaminophen-acetylsalicylic-acid-poi-644db8dc89', 'pharm-acetaminophen-acetylsalicylic-acid-poisoning', 'mcq', 'A 16-year-old girl comes to the emergency department with the effects of an aspirin overdose. Which syndrome is she most likely to exhibit?', '["Bone marrow suppression", "Fever, hepatic dysfunction and encephalopathy", "Hyperthermia, metabolic acidosis and coma", "Rapid, fulminant hepatic failure", "Rash, interstitial nephritis and acute renal failure"]'::jsonb, 'Hyperthermia, metabolic acidosis and coma', '[]'::jsonb, 'Salicylates uncouple oxidative phosphorylation, generating heat (hyperthermia) and lactic and ketoacids; after an initial respiratory alkalosis a metabolic acidosis develops, with CNS depression and coma in severe cases. Fever with hepatic dysfunction and encephalopathy describes Reye syndrome, and fulminant liver failure paracetamol.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.268 Q2, Acetaminophen and Salicylate Poisoning') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraffin-organophosphate-and-amphetami-f8fe786e8e', 'pharm-paraffin-organophosphate-and-amphetamine-poisoning', 'mcq', 'Toxicity that stems from exposure to parathion is treated with:', '["Antiseizure drugs", "Atropine and pralidoxime", "Haemodialysis", "Hyperbaric oxygen", "Measures to reduce pulmonary oedema"]'::jsonb, 'Atropine and pralidoxime', '[]'::jsonb, 'Parathion is an organophosphate that irreversibly inhibits acetylcholinesterase. Atropine blocks the muscarinic effects of the accumulated acetylcholine, and pralidoxime reactivates the enzyme (if given before ageing), relieving nicotinic effects such as muscle weakness.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.268 Q1, Organophosphate and Paraffin (Kerosene) Poisoning') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-paraffin-organophosphate-and-amphetami-0570f48b33', 'pharm-paraffin-organophosphate-and-amphetamine-poisoning', 'mcq', 'Which is the FALSE statement regarding the management of a child who has ingested kerosene?', '["The child should be put on mechanical ventilation if severe breathing difficulties occur", "A gastric lavage should be done immediately if within one hour", "Activated charcoal has no role", "There are no specific antidotes", "An initial chest radiograph may be normal"]'::jsonb, 'A gastric lavage should be done immediately if within one hour', '[]'::jsonb, 'The danger of kerosene is aspiration causing chemical pneumonitis, not systemic absorption. Gastric lavage and induced vomiting are contraindicated because they increase the risk of aspiration. Treatment is supportive with oxygen; radiographic changes may lag several hours behind.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.268 Q2, Organophosphate and Paraffin (Kerosene) Poisoning') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-carbon-monoxide-cyanide-acid-and-alkal-51324b0a1c', 'pharm-carbon-monoxide-cyanide-acid-and-alkali-poisoning', 'mcq', 'Stuck in heavy traffic, a person develops a headache, tightness in the temporal region and an increased pulse rate. Which of the following is the most likely cause?', '["Carbon monoxide", "Nicotine", "Nitrogen dioxide", "Ozone", "Sulphur dioxide"]'::jsonb, 'Carbon monoxide', '[]'::jsonb, 'Vehicle exhaust contains carbon monoxide, which binds haemoglobin with over 200 times the affinity of oxygen. At carboxyhaemoglobin levels of 20 to 30% the first symptoms are headache, temporal tightness and tachycardia. The other gases are respiratory irritants causing cough and airway symptoms.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.269 Q1, Carbon Monoxide and Cyanide Poisoning') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-carbon-monoxide-cyanide-acid-and-alkal-538358725a', 'pharm-carbon-monoxide-cyanide-acid-and-alkali-poisoning', 'mcq', 'Which is the FALSE statement about cyanide poisoning?', '["It is a highly toxic chemical", "It binds to the cytochrome oxidase enzyme", "It causes severe metabolic alkalosis", "Sodium thiosulphate is an antidote", "Hydroxocobalamin is an antidote"]'::jsonb, 'It causes severe metabolic alkalosis', '[]'::jsonb, 'Cyanide binds ferric iron in cytochrome c oxidase, stopping aerobic respiration; cells switch to anaerobic metabolism and a severe lactic (metabolic) acidosis results. Thiosulphate helps convert cyanide to thiocyanate and hydroxocobalamin binds it as cyanocobalamin.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.269 Q2, Carbon Monoxide and Cyanide Poisoning. Option e in the paper ("Activated charcoal is contraindicated") was also false; replaced with a true statement.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-heavy-metal-poisoning-8cf5628d5a', 'pharm-heavy-metal-poisoning', 'mcq', 'All of the following are true of arsenic poisoning EXCEPT:', '["Unithiol is effective in treatment", "Encephalopathy occurs only after weeks of exposure", "The main routes of absorption are the GIT and respiratory tract", "It causes diffuse capillary leak", "Chronic exposure causes lung cancer"]'::jsonb, 'Encephalopathy occurs only after weeks of exposure', '[]'::jsonb, 'Acute arsenic poisoning can cause delirium, encephalopathy and coma within the first days, alongside gastroenteritis, capillary leak and shock; it is not limited to chronic exposure. Unithiol or dimercaprol are the chelators, and chronic exposure causes skin, lung and bladder cancer.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.269 Q1, Heavy metal poisoning. Timing of encephalopathy is the only doubtful statement; needs a human check against Katzung.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-heavy-metal-poisoning-643286bdee', 'pharm-heavy-metal-poisoning', 'mcq', 'Lead poisoning causes the following EXCEPT:', '["Hearing loss", "Neurocognitive deficits", "Encephalopathy", "Increased libido", "Sleep disturbances"]'::jsonb, 'Increased libido', '[]'::jsonb, 'Lead is toxic to the nervous and reproductive systems: it reduces libido and causes infertility, along with cognitive deficits, irritability, sleep disturbance, hearing loss, peripheral motor neuropathy and, at high levels, encephalopathy.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.269 Q2, Heavy metal poisoning') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-heavy-metal-poisoning-bc6f54466c', 'pharm-heavy-metal-poisoning', 'mcq', 'All of the following are true of lead poisoning EXCEPT:', '["Children absorb less than adults", "It causes encephalopathy", "There is no safe blood level", "Respiratory absorption is the most common cause of industrial poisoning", "The skeleton holds about 90% of the total lead in the body in adults"]'::jsonb, 'Children absorb less than adults', '[]'::jsonb, 'Children absorb far more ingested lead than adults (about 40 to 50% against 10 to 15%), which, with their developing brains, makes them especially vulnerable. In industry, inhalation of fumes and dust is the main route. Lead is stored in bone with a half-life of decades.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.269 Q3, Heavy metal poisoning') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-development-stages-regulations-go-caf188dc98', 'pharm-drug-development-stages-regulations-governing-development-of-new', 'mcq', 'All of the following are true of phase II clinical trials EXCEPT:', '["They provide early efficacy data on medicines", "They demonstrate the immunogenicity of vaccines", "The studies are routinely carried out in 100-200 patients", "These are the first studies in the target population", "They are post-marketing studies"]'::jsonb, 'They are post-marketing studies', '[]'::jsonb, 'Phase II trials are the first in patients with the target disease, typically 100 to 200 of them, and give early evidence of efficacy, dose range and (for vaccines) immunogenicity. Post-marketing surveillance is phase IV.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.270 Q1, Drug Development and Regulation. Option e in the paper ("Phase IIA studies are designed to establish the appropriate dose") was only arguably false (dose-finding is usually phase IIb); replaced with a clearly false statement.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-development-stages-regulations-go-5fe25b9d2f', 'pharm-drug-development-stages-regulations-governing-development-of-new', 'mcq', 'Which of the following is NOT required for an Investigational New Drug (IND) application?', '["Preclinical data", "Information on the composition and source of the drug", "Manufacturing process", "Source of finance", "Proposed clinical trial protocols"]'::jsonb, 'Source of finance', '[]'::jsonb, 'An IND application must contain the composition and source of the drug, chemistry and manufacturing information, all preclinical (animal) data, the proposed clinical protocols and the investigators'' credentials. How the sponsor is funding the work is not part of it.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.270 Q2, Drug Development and Regulation. Option e changed from "Ethical committee clearance" to "Proposed clinical trial protocols" to avoid argument.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-development-stages-regulations-go-aa17bd622d', 'pharm-drug-development-stages-regulations-governing-development-of-new', 'mcq', 'The following are limitations of preclinical testing of drugs EXCEPT:', '["Toxicity testing is time-consuming and expensive", "It is difficult to calculate the initial dose of the drug to be tried in humans", "Large numbers of animals are required to obtain valid preclinical data", "Extrapolations of toxicity data from animals to humans may not be reliable", "Rare adverse effects are unlikely to be detected"]'::jsonb, 'It is difficult to calculate the initial dose of the drug to be tried in humans', '[]'::jsonb, 'A purpose of preclinical testing is precisely to estimate a safe starting dose for humans from the no-observed-adverse-effect level in animals. The recognised limitations are cost and time, the number of animals needed, uncertain extrapolation to humans and failure to detect rare adverse effects.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.270 Q3, Drug Development and Regulation') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-development-stages-regulations-go-6ea8b144f1', 'pharm-drug-development-stages-regulations-governing-development-of-new', 'mcq', 'Which of the following is NOT a feature of phase I clinical trials?', '["Evaluation of tolerability", "Post-marketing surveillance", "Study of pharmacokinetic properties", "A small group of volunteers", "Identification of potentially dangerous effects"]'::jsonb, 'Post-marketing surveillance', '[]'::jsonb, 'Phase I is the first-in-human stage: 20 to 100 usually healthy volunteers receive ascending doses to establish safety, tolerability and pharmacokinetics. Post-marketing surveillance is phase IV, after the drug has been licensed.', 'admin', 'published', 1, false, '[]'::jsonb, 'top p.270 Q4, Drug Development and Regulation') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-development-stages-regulations-go-a20f2c98ed', 'pharm-drug-development-stages-regulations-governing-development-of-new', 'mcq', 'Which statement is TRUE of the large double-blind, randomised controlled trials used to confirm the efficacy of a new drug before registration?', '["Post mortems are done on animals to identify tissue damage", "They are also known as phase III clinical studies", "They involve target selection for the drug", "About 20 volunteers participate", "They are carried out after the drug has been marketed"]'::jsonb, 'They are also known as phase III clinical studies', '[]'::jsonb, 'Phase III trials enrol hundreds to thousands of patients, usually randomised and double blind against placebo or standard treatment, to confirm efficacy and safety before a marketing application. Animal post mortems and target selection are preclinical, and 20 volunteers suggests phase I.', 'admin', 'draft', 1, false, '[]'::jsonb, 'top p.270 Q5, Drug Development and Regulation. Stem expanded and option e reworded (the paper said "Post-marketing surveillance is required") so that only one option is true; double-blind designs are not unique to phase III.') on conflict (id) do nothing;
